P.entries["quest:737"] = {n="Le savoir perdu",s="Le Sommaire de Yagyin est sous votre garde, en route vers Theldurin l'Egaré et à l'abri des mains hostiles.",h="Le Sommaire de Yagyin est sous votre garde, en route vers Theldurin l'Egaré et à l'abri des mains hostiles.",kw={"terres ingrates","savoir interdit","l'étoile, la main et le cœur","theldurin l'egaré","sommaire de yagyin"},sec={{t="Un livre qui brûle",b="Gerrig Poigne-d'os, à Forgefer, ou le Gardien Bel'dugur, à Fossoyeuse, vous remet le Sommaire de Yagyin. Gardez-le à l'abri des mains hostiles en le portant à Theldurin l'Egaré. Il renferme bien des vérités, et la vérité a tendance à brûler."},{t="L'espoir de Theldurin",b="Theldurin s'écrie que l'espoir luit encore. Vos efforts pourraient bien tous les sauver, dit-il, et faire ériger un monument et un sanctuaire où votre nom sera loué pour des générations.\n\nCet espoir ne tient que tant qu'ILS restent sous la surface. S'ILS remontent en liberté, tout le monde finira en nourriture pour les vers."}},faq={{q="Quel objet faut-il livrer ?",a="Il faut livrer le Sommaire de Yagyin. Il renferme bien des vérités et doit être gardé à l'abri des mains hostiles.",al={"quel est ce livre","qu'est-ce que le sommaire de yagyin","que dois-je apporter"}},{q="Qui doit recevoir le sommaire ?",a="Le Sommaire de Yagyin doit être remis à Theldurin l'Egaré.",al={"qui reçoit le livre","à qui dois-je remettre cet objet","où va le sommaire"}},{q="Que s'est-il passé avant ?",a="Cette étape suit celle où vous avez récupéré trois objets en échange du Sommaire de Yagyin.",al={"quête précédente","qu'est-ce qui mène à cette quête","quelle quête précède savoir interdit"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="Trouver Agmond",s="Depuis des semaines, le Prospecteur Agmond ne donne plus signe de vie sur les sites des Terres Ingrates. Le Prospecteur Baguefer a maintenant besoin que vous retrouviez Agmond et rapportiez son compte rendu.",h="Depuis des semaines, le Prospecteur Agmond ne donne plus signe de vie sur les sites des Terres Ingrates.",kw={"agmond","forteresse d'angor","terres ingrates","forgefer","prospecteur baguefer"},sec={{t="Un prospecteur silencieux",b="Le Prospecteur Agmond supervisait les fouilles des Terres Ingrates, au sud-ouest de Baguefer. Baguefer ne l'appelle plus prospecteur, car il n'a pas eu de ses nouvelles depuis des semaines. Il a besoin que vous retrouviez Agmond et récupériez son compte rendu. La dernière fois qu'on a entendu parler d'Agmond, il se trouvait sur le site de fouilles le plus au sud, une modeste installation au-delà de la Forteresse d'Angor. Commencez par là."},{t="Au bout de la piste",b="Au terme de vos recherches, vous trouvez un squelette qui doit être ce qu'il reste d'Agmond. Le corps est brisé et meurtri, et les os ont été dépouillés de toute chair."}},faq={{q="Qui est le Prospecteur Agmond ?",a="Le Prospecteur Agmond supervisait les fouilles des Terres Ingrates, au sud-ouest du Prospecteur Baguefer.",al={"qui est agmond","histoire d'agmond"}},{q="Pourquoi le Prospecteur Baguefer recherche-t-il Agmond ?",a="Le Prospecteur Baguefer n'a pas eu de nouvelles d'Agmond depuis des semaines et a besoin de son compte rendu.",al={"pourquoi retrouver agmond","baguefer recherche agmond"}},{q="Où le Prospecteur Agmond a-t-il été vu pour la dernière fois ?",a="La dernière fois qu'on a entendu parler d'Agmond, il se trouvait sur le site de fouilles le plus au sud des Terres Ingrates, une modeste installation au-delà de la Forteresse d'Angor.",al={"emplacement d'agmond","où se trouve le site de fouilles d'agmond","où se trouvait agmond"}},{q="Quelle quête précède celle-ci dans la suite ?",a="Elle suit Ironband Wants You!",al={"quête précédente","prérequis de trouver agmond"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmond gît mort dans les Terres Ingrates, le nom Murdaloc gravé dans le grès près de sa main. Tuez son meurtrier et portez la nouvelle au Prospecteur Baguefer, à Loch Modan.",h="Agmond gît mort dans les Terres Ingrates, le nom Murdaloc gravé dans le grès près de sa main.",kw={"agmond","terres ingrates","loch modan","murdaloc","prospecteur baguefer","stonevault bonesnapper","trogg"},sec={{t="Un nom dans le grès",b="Des traces de sang marquent la piste d'Agmond depuis l'ouest, sur la pierre et le sable. Elles montrent jusqu'où le nain a rampé avant de mourir. Près de sa main immobile, un mot est gravé dans le grès des Terres Ingrates : Murdaloc. Tuez le meurtrier d'Agmond et plusieurs Stonevault Bonesnappers, puis portez la nouvelle au Prospecteur Baguefer, à Loch Modan."},{t="La réponse de Baguefer",b="Le Prospecteur Baguefer reçoit la nouvelle d'un air grave. Il se souvient d'Agmond comme d'un nain aux bras vigoureux, redoutable au marteau et dur de la tête. Baguefer affirme que des troggs maudits ont tué Agmond. Il pense qu'Agmond en a abattu un bon nombre en chemin."}},faq={{q="Qui était Agmond ?",a="Agmond était un nain qui supervisait les sites d'excavation des Terres Ingrates pour le Prospecteur Baguefer. Votre recherche s'est achevée devant un squelette.",al={"qui est agmond","histoire d'agmond"}},{q="Qui est Murdaloc ?",a="Murdaloc est le nom gravé dans le grès près de la main morte d'Agmond. Tuez le meurtrier d'Agmond, Murdaloc.",al={"qu'est-ce que murdaloc","histoire de murdaloc"}},{q="À qui faut-il porter le rapport ?",a="Portez le rapport au Prospecteur Baguefer, à Loch Modan.",al={"à qui signaler murdaloc","où se trouve baguefer"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="La légende de Stalvan",s="Cette étape de l'enquête mène au fond d'une vieille caisse d'héritages des Flintridge, abandonnée le long des canaux de la Cité de Hurlevent. Fouiller parmi ces reliques poussiéreuses permet de découvrir une page de journal déchirée, offrant un précieux indice manuscrit sur la vie passée de Stalvan Mantebrume, qui conduit au maréchal Haggard dans la Forêt d’Elwynn.",h="Cette étape de l'enquête mène au fond d'une vieille caisse d'héritages des Flintridge, abandonnée le long des...",kw={"bois de la pénombre","forêt d’elwynn","esprit mélancolique","le maréchal haggard","mistmantle","caisse scellée","stalvan","page de journal déchirée"},ang={["faction:Alliance"]="Enquêter sur de vieilles affaires non élucidées au cœur d'Elwynn révèle à quel point des horreurs profondément intimes ont pu échapper au regard des maréchaux de Hurlevent.",["race:Human"]="Le maréchal Haggard incarne la génération des vétérans vieillissants de Hurlevent, gardiens de souvenirs essentiels du royaume d'avant que la Première et la Deuxième guerre ne déchirent les familles."},sec={{t="Exhumer le passé",b="En fouillant dans une caisse scellée remplie de reliques de famille moisies, de vieux trophées de chasse et de portraits de famille, les enquêteurs découvrent une unique page de journal déchirée, dissimulée sous un vase en céramique. Rédigé de la propre main de Stalvan Mantebrume, ce vestige offre un aperçu intime de l'esprit d'un érudit solitaire avant que la tragédie ne frappe."},{t="La vue défaillante d'un maréchal",b="Le maréchal Haggard, désormais âgé et affligé d'une vue défaillante, peine à déchiffrer l'écriture sur le parchemin abîmé. Malgré cela, cette graphie si particulière réveille en lui un écho troublant, lui rappelant des documents et des événements survenus des années plus tôt, avant que l'obscurité ne lui ravisse la vue."}},faq={{q="Où se trouve la caisse scellée ?",a="La caisse scellée se trouve près des Canaux de la Cité de Hurlevent, juste derrière le Conservateur Folsom, au milieu des affaires emballées de la famille Flintridge. La page qui y est découverte est ensuite apportée au maréchal Haggard, dans le sud-est de la Forêt d’Elwynn.",al={"emplacement de la caisse","où se trouve la caisse","caisse haggard"}},{q="Que contient la caisse scellée ?",a="La caisse contient des reliques poussiéreuses, un portrait de famille, de vieux livres, des trophées de chasse et un vase en céramique, sous lequel repose une page déchirée du journal de Stalvan.",al={"contenu de la caisse","que contient la caisse","page déchirée caisse"}},{q="Qui est le maréchal Haggard ?",a="Le maréchal Haggard est un officier âgé et à la retraite de Hurlevent, qui vit reclus dans le sud de la Forêt d’Elwynn. Malgré sa vue déclinante et sa fragilité, ses souvenirs de vieux registres et de voyageurs font de lui un témoin crucial des événements passés.",al={"qui est haggard","histoire du maréchal haggard","vieux maréchal elwynn"}},{q="Pourquoi cette page de journal est-elle importante ?",a="Cette page de journal déchirée constitue une preuve directe rédigée par Stalvan Mantebrume lui-même. Son écriture caractéristique et les pensées qui y sont couchées permettent de relier des récits disparates disséminés entre le Bois de la Pénombre et Elwynn à sa tragédie personnelle.",al={"pourquoi la page déchirée est importante","indice page de journal","journal de stalvan"}},{q="Que se passe-t-il lorsque la caisse est ouverte ?",a="Perturber les vestiges du passé de Stalvan réveille les morts sans repos, provoquant l'apparition d'un Esprit mélancolique vengeur qui s'en prend à ceux qui cherchent à percer le mystère de la tragédie.",al={"apparition esprit mélancolique","fantôme après la caisse","pourquoi un fantôme m'a attaqué"}},{q="Où mène l'enquête par la suite ?",a="Après avoir présenté la page déchirée au maréchal Haggard, les souvenirs que lui inspire cette écriture permettent d'orienter la suite de l'enquête pour retrouver d'autres fragments subsistants de l'histoire de Stalvan.",al={"étape suivante","après la page déchirée","où aller ensuite"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="Les absences du prospecteur",s="De Sombrivage, Hollee envoie le fossile de Remtravel à Darnassus, tandis qu’elle veille sur le prospecteur errant. Le Chef archéologue Grisemoustache s’intéresse de près à la découverte.",h="De Sombrivage, Hollee envoie le fossile de Remtravel à Darnassus, tandis qu’elle veille sur le prospecteur...",kw={"archéologue","sombrivage","darnassus","ligue des explorateurs","fossile","grisemoustache","hollee","songerrance"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à relier ses peuples sur de grandes distances. Les chercheurs nains comptent sur les voyageurs pour transporter leurs découvertes en toute sécurité, des rivages reculés de Sombrivage jusqu’à Darnassus.",["race:Dwarf"]="En tant que nain, transporter le fossile de Songerrance sert l’objectif principal de la Ligue des explorateurs : découvrir le passé lointain du monde et montrer la valeur de la persévérance des nains.",["race:NightElf"]="En tant qu’elfe de la nuit, voir des fouilleurs nains ramener d’anciens vestiges du sol sacré de Sombrivage peut être déconcertant. La coopération avec la Ligue préserve les liens de l’Alliance."},sec={{t="Un messager pour la capitale",b="Le Prospecteur Songerrance a trouvé un curieux fossile sur la côte de Sombrivage. Il préfère continuer à creuser plutôt que de suivre le protocole. L’Archéologue Hollee reste donc avec lui, au milieu des bêtes dangereuses et des sectateurs hostiles du rivage. Elle vous demande de porter le spécimen à Darnassus, où se trouve une délégation d’érudits nains."},{t="Les intérêts des nains en Kalimdor",b="Des nains de Forgefer ont traversé la Grande mer sous la bannière de la Ligue des explorateurs. Ils cherchent des reliques antiques et l’histoire oubliée enfouie dans le sol de Kalimdor. À Darnassus, le Chef archéologue Grisemoustache s’émerveille du talent de Songerrance pour trouver des trésors anciens. Les elfes de la nuit voient leurs forêts comme des sanctuaires vivants, tandis que la Ligue considère ces terres anciennes comme des lieux à étudier et à déchiffrer."}},faq={{q="Qu’est-ce que le Mystérieux fossile ?",a="Le Prospecteur Songerrance a trouvé un spécimen pétrifié non identifié sur la côte de Sombrivage. Son âge et sa nature étrange en font une découverte précieuse pour les érudits de la Ligue des explorateurs à Darnassus.",al={"mystérieux fossile","quel est ce fossile","fossile de songerrance"}},{q="Pourquoi Hollee reste-t-elle à Sombrivage ?",a="L’Archéologue Hollee reste pour veiller sur le Prospecteur Songerrance. Il s’éloigne et ignore le danger pendant ses fouilles. Elle ne veut donc pas le laisser seul dans la nature pendant qu’elle transporte ses découvertes à Darnassus.",al={"pourquoi hollee ne part pas","hollee reste","pourquoi hollee reste"}},{q="Qui est le Chef archéologue Grisemoustache ?",a="Le Chef archéologue Grisemoustache est un représentant chevronné de la Ligue des explorateurs de Forgefer. Depuis Darnassus, il supervise les travaux archéologiques dans le nord de Kalimdor et étudie les reliques rapportées par les fouilleurs nains.",al={"grisemoustache","qui est grisemoustache","chef grisemoustache"}},{q="Pourquoi la Ligue des explorateurs est-elle à Darnassus ?",a="Le Roi Magni Barbe-de-Bronze a fondé la Ligue des explorateurs pour découvrir les origines des nains et l’histoire ancienne d’Azeroth. Les liens amicaux avec les elfes de la nuit permettent aux érudits nains d’établir leurs expéditions à Darnassus et d’étudier les terres oubliées de Kalimdor.",al={"nains à darnassus","ligue des explorateurs à darnassus","pourquoi les nains sont ici"}},{q="Où va le fossile après Darnassus ?",a="Le Chef archéologue Grisemoustache examine le fossile à Darnassus. Les découvertes de cette importance doivent être répertoriées ou envoyées par les voies de la Ligue au grand musée de Forgefer.",al={"où va le fossile","étape suivante du fossile"}},{q="Où Songerrance a-t-il trouvé le spécimen ?",a="Songerrance a découvert le spécimen sur la côte sauvage de Sombrivage, parmi les épaves, les ruines antiques et les vestiges fossilisés de la vie marine d’avant le Great Sundering.",al={"où le fossile a été trouvé","site de fouilles de songerrance"}}},fx={c70c2c67={q="Pourquoi l'Archéologue Hollee veut-elle que le fossile soit livré à Darnassus ?",a="Le Prospecteur Songerrance veut que sa découverte soit examinée immédiatement, mais quelqu'un doit l'apporter à leurs supérieurs. Hollee est déterminée à ne pas abandonner Sombrivage tant que Songerrance reste dans la nature, elle compte donc sur vous pour transporter la trouvaille inestimable directement au Chef archéologue Grisemoustache à Darnassus en leur nom.",al={"pourquoi envoyer le fossile à darnassus","motif hollee","pourquoi livrer le fossile"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="La Chasse d'Orneval",s="À Pitons-du-Tonnerre, la Chasse d'Orneval envoie de jeunes champions de la Horde servir dans les avant-postes forestiers. Les hérauts les orientent vers Senani Cœur-de-tonnerre, au Poste de Bois-brisé, pour une chasse probatoire.",h="À Pitons-du-Tonnerre, la Chasse d'Orneval envoie de jeunes champions de la Horde servir dans les avant-postes...",kw={"orneval","chasse","senani","poste de bois-brisé","pitons-du-tonnerre","cœur-de-tonnerre","rôdeur-du-vent","la grève de zoram"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez affûter vos talents de pisteur dans les bois denses d'Orneval, où les rôdeurs se déplacent dans un environnement bien différent des savanes sèches et dégagées du sud.",["faction:Horde"]="En tant que membre de la Horde, vous comptez sur le Poste de Bois-brisé et La grève de Zoram pour soutenir les lignes de ravitaillement du nord. Les nouvelles recrues aident à tenir à distance les bêtes sauvages et les autochtones hostiles.",["race:Tauren"]="Élevé dans les plaines dégagées de Mulgore, vous, Tauren, relevez un défi inhabituel sous la canopée dense d'Orneval. Des proches comme Senani veillent sur la chasse."},sec={{t="Une convocation depuis High Rise",b="Le Messager des Pitons Rôdeur-du-vent porte une invitation ouverte aux aventuriers aguerris à travers Pitons-du-Tonnerre. Au nord des Tarides, la Horde tient des positions dans une forêt ancienne, et ses avant-postes ont besoin de jeunes guerriers. Ceux qui répondent affronteront des contrées plus hostiles et mettront leurs talents de survie à l'épreuve au-delà de Mulgore."},{t="La frontière du Nord",b="Orneval offre à la Horde de riches ressources et de graves périls. Le Poste de Bois-brisé se trouve le long de la route principale, tandis qu'un avant-poste isolé se dresse sur la côte occidentale, à La grève de Zoram. Au Poste de Bois-brisé, Senani Cœur-de-tonnerre est une vétérane aguerrie de la vie en plein air qui organise une grande chasse. Là, les recrues domptent la nature sauvage et remportent la gloire pour la Horde."}},faq={{q="Qui propose cette quête à Pitons-du-Tonnerre ?",a="Le Messager des Pitons Rôdeur-du-vent propose la convocation aux aventuriers de passage à Pitons-du-Tonnerre. Il informe les combattants capables des efforts de la Horde pour étendre son territoire et les dirige vers les avant-postes qui ont besoin d'aide.",al={"qui lance la chasse d'orneval","donneur de quête de la chasse d'orneval","messager des pitons rôdeur-du-vent"}},{q="Où se trouve le Poste de Bois-brisé ?",a="Le Poste de Bois-brisé est une colonie fortifiée de la Horde dans l'est d'Orneval. Traversez la frontière des Tarides vers le nord, puis suivez le sentier forestier oriental qui s'enfonce dans les bois.",al={"emplacement du poste de bois-brisé","comment se rendre au poste de bois-brisé","où se trouve le poste de bois-brisé"}},{q="Qui est Senani Cœur-de-tonnerre ?",a="Senani Cœur-de-tonnerre est une pisteuse taurène chevronnée en poste au Poste de Bois-brisé. Elle organise des chasses en Orneval et met les recrues de la Horde à l'épreuve face aux prédateurs locaux.",al={"senani cœur-de-tonnerre","qui est senani","pnj cœur-de-tonnerre"}},{q="Pourquoi la Horde chasse-t-elle en Orneval ?",a="La Horde chasse en Orneval pour récolter du bois et sécuriser son territoire. La chasse réduit le nombre de bêtes sauvages qui menacent ses camps et permet aux jeunes aventuriers de faire leurs preuves sur des terres inconnues.",al={"pourquoi chasser en orneval","but de la chasse d'orneval","objectifs de la horde en orneval"}},{q="Qu'est-ce que La grève de Zoram mentionnée dans le briefing ?",a="La grève de Zoram est un campement de la Horde sur la côte la plus occidentale d'Orneval, face à la mer. C'est une tête de pont navale secondaire et un bastion contre les nagas et les habitants hostiles de la forêt.",al={"qu'est-ce que la grève de zoram","avant-poste de la grève de zoram","avant-poste de zoram"}},{q="Que se passe-t-il après s'être présenté à Senani ?",a="Quand vous vous présentez à Senani Cœur-de-tonnerre, elle vous accueille à l'avant-poste et vous confie la grande chasse. Elle vous charge de traquer et de vaincre les bêtes les plus féroces d'Orneval.",al={"que se passe-t-il après la chasse d'orneval","quête après senani","suite de la chasse"}}},fx={af70e220={q="Pourquoi le Messager des Pitons Rôdeur-du-vent veut-il que vous alliez à Orneval ?",a="Le Messager des Pitons Rôdeur-du-vent sert de héraut pour la Horde, dirigeant de jeunes champions capables là où ils sont le plus nécessaires. La Horde sécurise agressivement ses avant-postes frontaliers dans les forêts indomptées au nord des Tarides, et des chasseurs comme Senani Cœur-de-tonnerre ont besoin de nouvelles recrues pour renforcer leur présence et revendiquer la gloire dans la nature sauvage.",al={"pourquoi envoyer à orneval","motif messager des pitons rôdeur-du-vent","pourquoi le messager veut cela"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="Le danger des Furies-des-vents",s="Ruul Serre-d'aigle met à l'épreuve votre aptitude à affronter les harpies Furie-des-vents de Mulgore. Leur vitesse et leurs serres vous mettront au défi sur les falaises du sud-est, avant votre départ de la terre natale des taurens.",h="Ruul Serre-d'aigle met à l'épreuve votre aptitude à affronter les harpies Furie-des-vents de Mulgore.",kw={"sabot-de-sang","le danger des furies-des-vents","harpies","mulgore","ruul serre-d'aigle","épreuve des taurens","furies-des-vents","serres des furies-des-vents"},ang={["class:Warrior"]="En tant que guerrier, le défi de Ruul Serre-d'aigle vous apprend à parer les piqués rapides. Il vous entraîne à affronter les assaillants féroces venus des airs avec une discipline inébranlable.",["faction:Horde"]="En tant qu'allié des taurens, relever l'épreuve de Ruul témoigne de votre dévouement à protéger le cœur de la Horde. Vous pourriez ainsi gagner le respect du village de Sabot-de-Sang.",["race:Tauren"]="En tant que jeune tauren, détruire les nids des Furies-des-vents aide à défendre les plaines. Sous l'œil des anciens du village, cette épreuve marque votre entrée dans l'âge adulte reconnu."},sec={{t="L'épreuve d'un maître",b="Depuis le village de Sabot-de-Sang, Ruul Serre-d'aigle observe les voyageurs qui traversent Mulgore. Il demande à ceux qui atteignent l'âge adulte ou se préparent à partir au loin de prouver leur instinct de combat. Au-delà des vallées abritées de Mulgore, survivre exige du sang-froid face à des ennemis rusés. Ruul mesure votre valeur à l'aune des prédateurs indigènes les plus féroces de la région."},{t="La menace des Furies-des-vents",b="Les harpies Furie-des-vents nichent le long de la bordure montagneuse du sud-est de Mulgore, loin des sentiers battus. Elles menacent la faune errante et les voyageurs isolés. Elles fondent rapidement sur leurs proies et les frappent de leurs serres acérées, en quête de chair fraîche. Terrassez-les et rapportez leurs serres pour prouver que vous pouvez vaincre une menace bien installée et parer une attaque venue des airs."}},faq={{q="Qui est Ruul Serre-d'aigle ?",a="Ruul Serre-d'aigle est un guerrier tauren chevronné et un maître au village de Sabot-de-Sang. Il met à l'épreuve les jeunes aventuriers avant qu'ils ne s'aventurent dans les régions plus dangereuses de Kalimdor.",al={"ruul serre-d'aigle","qui donne le danger des furies-des-vents","ruul"}},{q="Où trouve-t-on les harpies Furie-des-vents à Mulgore ?",a="Les harpies Furie-des-vents nichent dans les montagnes du sud-est de Mulgore, dans des nids rudimentaires perchés sur les rochers et les pentes des contreforts. Leurs nids se trouvent à l'écart de la route principale qui traverse la vallée.",al={"emplacement des harpies furie-des-vents","où trouver les harpies furie-des-vents","emplacement des nids des furies-des-vents"}},{q="Pourquoi les harpies Furie-des-vents sont-elles des ennemies naturelles des taurens ?",a="Les harpies Furie-des-vents sont des charognardes agressives et territoriales qui attaquent quiconque s'approche de leurs nids. Leur faim de chair fraîche et leurs attaques contre les voyageurs et les bêtes au pâturage menacent constamment les plaines.",al={"pourquoi les taurens combattent les harpies","menace des harpies à mulgore","histoire des furies-des-vents"}},{q="Quelle preuve Ruul Serre-d'aigle exige-t-il après la chasse ?",a="Ruul vous demande de rapporter huit Windfury Talons prélevées sur des harpies abattues. Ces serres sont leurs principales armes naturelles.",al={"preuve du danger des furies-des-vents","objets à rapporter à ruul","objectif de la quête des furies-des-vents"}},{q="Pourquoi les aventuriers doivent-ils subir cette épreuve avant de quitter Mulgore ?",a="Pour Ruul, les harpies Furie-des-vents mettent à l'épreuve les aptitudes au combat. Leur vitesse, leur férocité et leurs serres défient ceux qui se préparent à affronter les dangers au-delà des falaises protectrices de Mulgore.",al={"but de l'épreuve","pourquoi faire le danger des furies-des-vents","épreuve de ruul"}},{q="Où se trouve le village de Sabot-de-Sang ?",a="Le village de Sabot-de-Sang se trouve au centre de Mulgore, près du lac Taureau-de-pierre, au sud de la Grande porte et des Pitons-du-Tonnerre. Les voyageurs taurens y trouvent culture, commerce et entraînement.",al={"emplacement du village de sabot-de-sang","où se trouve sabot-de-sang","emplacement de ruul"}}},fx={d8522cbd={q="Pourquoi Ruul Serre-d'aigle veut-il que les harpies Furie-des-vents soient chassées ?",a="Ruul Serre-d'aigle est un Guerrier et mentor chargé de préparer les jeunes aventuriers avant qu'ils n'aillent au-delà des limites sûres de Mulgore. Il considère les féroces harpies Furie-des-vents comme une épreuve naturelle — une véritable mesure de vos prouesses martiales et de votre préparation à affronter les menaces plus sévères du vaste monde.",al={"pourquoi chasser les harpies","motif ruul","raison de ruul serre-d'aigle"}},["1789ad72"]={q="Qui sont les harpies Furie-des-vents ?",a="Les harpies Furie-des-vents sont des charognards aviaires sauvages nichant le long des corniches montagneuses au sud-est du village de Sabot-de-Sang. Vicieuses et rusées, elles ont longtemps fait leur proie des voyageurs et de la faune à travers Mulgore, poussées par une faim incessante de viande fraîche et une inimitié naturelle envers les Tauren.",al={"harpies furie-des-vents","qui sont les furie-des-vents","harpies furie-des-vents mulgore"}},["29c303b8"]={q="Pourquoi Ruul Serre-d'aigle ne chasse-t-il pas les harpies lui-même ?",a="Ruul est un enseignant dont le devoir au village de Sabot-de-Sang est de former la prochaine génération de défenseurs, et non de mener leurs batailles à leur place. Cette tâche est explicitement un rite de passage : vous devez prouver votre propre force contre les prédateurs de Mulgore avant d'être considéré comme apte à voyager au-delà des plaines.",al={"pourquoi moi","pourquoi m'envoyer","pourquoi ruul ne le fait pas"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="Préparation à la cérémonie",s="Eyahn Eagletalon confectionne une coiffe pour son frère, qui se présentera bientôt devant le chef Cairne Sabot-de-Sang. Il vous demande de ramasser des plumes éclatantes chez les harpies au-delà des Pitons-du-Tonnerre, pendant qu'il tanne les lanières de cuir.",h="Eyahn Eagletalon confectionne une coiffe pour son frère, qui se présentera bientôt devant le chef Cairne...",kw={"cairne sabot-de-sang","cérémonie","plumes","harpie","coiffe","mulgore","préparation à la cérémonie","tauren","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous honorez les coutumes de vos alliés taurens sur les mesas des Pitons-du-Tonnerre en les aidant dans leurs tâches cérémonielles.",["race:Tauren"]="En tant que tauren, vous savez que les coiffes naturelles sont liées à l'honneur et aux rites de passage devant le grand chef. Aider à confectionner une telle parure témoigne de la fierté et de l'esprit partagés par les tribus."},sec={{t="Honorer le chef",b="Chez les taurens, se présenter devant le chef Cairne Sabot-de-Sang est une source de fierté et de révérence. Les familles honorent l'occasion en préparant une tenue appropriée. La coiffe traditionnelle est faite de cuir traité et d'un plumage symbolique, chaque élément étant choisi pour témoigner de dignité et de respect envers le chef des tribus unies."},{t="Plumes des escarpements",b="Une coiffe cérémonielle nécessite un bandeau de cuir et des plumes pour sa couronne. Pendant que les lanières de cuir sont tannées, il faut ramasser de longues plumes intactes. Les harpies nichent dans les collines escarpées au nord et au nord-ouest des Pitons-du-Tonnerre. Vous devez donc vous aventurer dans leurs nids hostiles pour trouver des plumes de la taille et de la couleur voulues."}},faq={{q="Pour quelle cérémonie se prépare-t-on ?",a="La cérémonie marque le moment où un tauren se présente devant le chef Cairne Sabot-de-Sang. Son frère ou sa sœur confectionne une coiffe en cuir tanné et en plumes éclatantes pour l'occasion.",al={"quelle est cette cérémonie","quelle est la cérémonie","qui se présente devant sabot-de-sang"}},{q="Qui est le chef Sabot-de-Sang ?",a="Le chef Cairne Sabot-de-Sang dirige les tribus taurens unies depuis les Pitons-du-Tonnerre. Se présenter devant lui est un honneur pour tout tauren.",al={"qui est le chef sabot-de-sang","cairne sabot-de-sang","qui est sabot-de-sang"}},{q="Pourquoi faut-il des plumes de harpie pour la coiffe ?",a="La coiffe nécessite des plumes d'une taille et d'une couleur particulières. Son modèle requiert un plumage azur et bronze, tandis que les lanières de cuir sont tannées.",al={"pourquoi faut-il des plumes de harpie","pourquoi des plumes de harpie","pourquoi des plumes"}},{q="Où se trouvent les harpies ?",a="Les harpies vivent dans les terres escarpées au nord et au nord-ouest des Pitons-du-Tonnerre, en Mulgore.",al={"où vivent les harpies","où trouver des harpies","où trouver des plumes azur et bronze"}},{q="Quel rôle les harpies jouent-elles en Mulgore ?",a="Les harpies sont des créatures féroces, mi-oiseaux, mi-humanoïdes, qui nichent dans les escarpements rocheux de Mulgore. Elles menacent les voyageurs et les tribus, tandis que leur plumage abondant et coloré fournit de quoi confectionner des ornements cérémoniels.",al={"pourquoi chasser les harpies","que sont les harpies"}},{q="Qui confectionne la coiffe cérémonielle ?",a="Eyahn Eagletalon tanne les lanières de cuir et confectionne la coiffe pour son frère, qui se prépare à se présenter devant le chef.",al={"qui confectionne la coiffe","qui fabrique la coiffe"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="Partager la terre",s="À Mulgore, Baine Sabot-de-Sang vous demande d’empêcher les gnolls Crin-pâle de tuer la faune des plaines. Vous protégez les troupeaux et le mode de vie tauren auprès de la Terre-Mère.",h="À Mulgore, Baine Sabot-de-Sang vous demande d’empêcher les gnolls Crin-pâle de tuer la faune des plaines.",kw={"baine sabot-de-sang","sabot-de-sang","gnolls","mulgore","crin-pâle","poachers","partager la terre","écorcheurs","tanneurs"},ang={["class:Druid"]="En tant que druide, vous savez que le braconnage sans frein nuit à l’esprit des plaines. L’harmonie de la terre a besoin de votre aide.",["class:Hunter"]="Les écorcheurs et les braconniers Crin-pâle chassent avec cruauté et gaspillent leurs prises. Ils n’ont pas le respect des créatures sauvages d’un véritable chasseur.",["faction:Horde"]="En tant que membre de la Horde, vous renforcez vos liens avec les dirigeants de la jeune nation tauren en aidant Baine Sabot-de-Sang.",["race:Tauren"]="En tant que jeune tauren, vous répondez à l’appel de Baine pour défendre Mulgore et honorer l’équilibre de la Terre-Mère."},sec={{t="Une terre déséquilibrée",b="Les taurens ne prennent à la terre que ce dont ils ont besoin et honorent la Terre-Mère en toute chose. Les gnolls Crin-pâle se sont installés au sud du village de Sabot-de-Sang et dans une caverne à l’ouest. Dans les plaines, ils massacrent la faune et laissent des carcasses derrière eux. Leurs chasses excessives nuisent à l’équilibre des prairies et menacent le paisible foyer que les taurens bâtissent à Mulgore."},{t="Quand les mots ne suffisent plus",b="Baine Sabot-de-Sang a tenté de régler le différend pacifiquement en parlant aux gnolls Crin-pâle. Ils ont rejeté chaque tentative et continué à tuer la faune. Il envoie maintenant de jeunes braves dans leurs camps de chasse pour arrêter les braconniers, les tanneurs et les écorcheurs avant que les prairies ne subissent des dommages durables."},{t="Le cycle de la vie et de la mort",b="À votre retour, Baine enseigne qu’il ne faut jamais prendre une vie par malveillance, même si cela peut être nécessaire pour préserver l’harmonie. La vie et la mort forment un cercle. Chaque gardien de Mulgore doit garder cette vérité à l’esprit."}},faq={{q="Qui donne cette quête ?",a="Baine Sabot-de-Sang, fils du grand chef Cairne Sabot-de-Sang, vous confie cette tâche au village de Sabot-de-Sang, au centre de Mulgore.",al={"donneur de quête","qui lance partager la terre","quête de baine"}},{q="Pourquoi les taurens s’en prennent-ils aux gnolls Crin-pâle ?",a="Les gnolls Crin-pâle chassent sans discernement la faune de Mulgore et déciment les troupeaux. Ils ont aussi rejeté les tentatives des taurens de leur parler pacifiquement.",al={"pourquoi tuer les gnolls","problème des crin-pâle","qu’ont fait les gnolls"}},{q="Où se trouvent ces gnolls ?",a="Les Crin-pâle campent au sud du village de Sabot-de-Sang et vivent dans le réseau de cavernes du Rocher des crins-pâles, à l’ouest.",al={"emplacement des gnolls","camp des crin-pâle","où trouver les crin-pâle"}},{q="Les taurens ont-ils d’abord essayé de faire la paix ?",a="Oui. Baine dit que les taurens ont essayé plusieurs fois de parler aux gnolls et de partager la terre, mais que les Crin-pâle ont rejeté leurs offres pacifiques.",al={"les taurens ont-ils parlé aux gnolls","diplomatie avec les crin-pâle"}},{q="Quelle leçon Baine cherche-t-il à enseigner ?",a="Baine veut que les jeunes défenseurs comprennent que la vie et la mort forment un cercle indissociable. Prendre une vie peut être nécessaire pour protéger l’équilibre, mais il faut le faire dans le respect de la Terre-Mère.",al={"leçon de baine","sens de partager la terre"}},{q="Qui sont les gnolls Crin-pâle ?",a="Les gnolls Crin-pâle sont une tribu primitive de Mulgore, semblable à des hyènes. Ils ont le pelage pâle, défendent leur territoire avec agressivité et méprisent l’harmonie des plaines.",al={"qui sont les crin-pâle","tribu des crin-pâle"}}},fx={["901e0c5d"]={q="Contre qui êtes-vous envoyé dans Sharing the Land ?",a="Baine vous envoie contre les gnolls Crinière-pâle qui ont empiété sur les plaines au sud du village de Sabot-de-Sang et se sont abrités dans une grotte à l'ouest. Ces Poachers, tanneurs et dépouilleurs ont massacré imprudemment la faune de Mulgore sans respect pour l'équilibre ou la Mère Terre. Parce qu'ils ont violemment rejeté chaque ouverture pacifique des Tauren, la force est la seule mesure qui reste pour arrêter leur braconnage.",al={"cibles sharing the land","qui tuer sharing the land","gnolls crinière-pâle sharing the land"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="Les fouilles des nains",s="À Sabot-de-Sang, Baine Sabot-de-Sang craint que les prospecteurs n’irritent les bêtes de Mulgore et ne meurtrissent sa terre sacrée. Il demande aux jeunes défenseurs de la Horde de briser leurs pioches et de mettre fin aux fouilles.",h="À Sabot-de-Sang, Baine Sabot-de-Sang craint que les prospecteurs n’irritent les bêtes de Mulgore et ne...",kw={"baine sabot-de-sang","sabot-de-sang","nain","forge","kodo","mulgore","pioches","prospecteur"},ang={["class:Shaman"]="En tant que chaman, vous savez que des fouilles imprudentes perturbent le socle rocheux, bouleversent les éléments et troublent les esprits et les créatures de la terre.",["faction:Horde"]="En tant que membre de la Horde, vous voyez les nains de l’Alliance qui pénètrent sur les terres de la Horde comme une menace pour la paix fragile qui dure depuis la Troisième guerre. Ils ignorent les frontières tribales.",["profession:Mining"]="En tant que mineur, vous appréciez peut-être ce que recèle la pierre, mais les travaux des nains à Mulgore privilégient la destruction irréfléchie au respect et à l’harmonie.",["race:Tauren"]="En tant que tauren, vous savez que le corps de Earth Mother est sacré. Les étrangers qui forent dans les steppes de Mulgore appellent une réponse ferme."},sec={{t="Des intrus dans les collines",b="Au nord-ouest de Sabot-de-Sang, des prospecteurs nains ont marqué un site dans les collines de Mulgore. La Ligue des explorateurs parcourt Kalimdor à la recherche de reliques des titans et de secrets des terrestres. Souvent, ils prêtent peu d’attention aux terres et aux coutumes de ceux qui y vivent. Pour les taurens, la terre est une mère vivante, digne de révérence plutôt que d’être creusée pour en extraire pierre et métal."},{t="Défendre la terre sacrée",b="Baine Sabot-de-Sang voit dans les machines et les explosions des nains une menace pour le fragile équilibre des plaines. Leur bruit agite la faune locale et rend les kodos furieux. Les taurens comptent donc détruire les pioches des prospecteurs aux forges. Ces outils brisés avertiront les nains et mettront fin aux fouilles avant qu’elles ne causent des dégâts durables."}},faq={{q="Pourquoi les nains creusent-ils à Mulgore ?",a="Les prospecteurs nains fouillent Mulgore à la recherche de secrets et d’artefacts enfouis. Leurs travaux miniers ignorent le territoire et les coutumes des taurens, ce qui les oppose à eux.",al={"nains à mulgore","pourquoi les prospecteurs sont-ils ici","fouilles naines à mulgore"}},{q="Qui donne la quête Les fouilles des nains ?",a="Baine Sabot-de-Sang donne la requête à Sabot-de-Sang, au centre de Mulgore. Il est le jeune fils du grand chef Cairne Sabot-de-Sang.",al={"donneur de quête des fouilles des nains","qui lance les fouilles des nains"}},{q="Pourquoi Baine veut-il que leurs outils soient brisés plutôt que simplement volés ?",a="Baine veut que les pioches soient brisées afin que les fouilles cessent immédiatement. Les détruire aux forges avertira les nains que la force brute ne leur livrera pas les secrets de la terre.",al={"pourquoi briser les pioches","destruction des outils nains"}},{q="Quel effet les fouilles ont-elles sur la faune de Mulgore ?",a="Les fouilles et les blessures infligées à la terre agitent les créatures natives de Mulgore, en particulier les kodos qui parcourent les collines. Les troupeaux paisibles deviennent irritables et agressifs.",al={"kodos en colère","pourquoi les bêtes sont-elles furieuses"}},{q="Où peut-on briser les pioches ?",a="Vous pouvez briser les pioches à une forge en activité. Le camp d’excavation des nains en possède une, et les forgerons de Pitons-du-Tonnerre en ont une autre.",al={"où se trouve la forge","briser les pioches des prospecteurs à la forge"}},{q="Cette quête est-elle liée à la présence plus vaste de la Ligue des explorateurs en Kalimdor ?",a="Oui. Les expéditions naines de Forgefer ont des avant-postes partout en Kalimdor, notamment à Mulgore, dans Les Tarides et dans Southern Kalimdor. Leurs revendications sur les terres et les lieux sacrés provoquent souvent des escarmouches avec les peuples de la Horde.",al={"ligue des explorateurs à mulgore","forgefer en kalimdor"}}},fx={["755e231a"]={q="À quoi servent les Outils cassés ?",a="Les Outils cassés servent de preuve tangible que vous avez mis un terme aux opérations des nains. Plutôt que de simplement chasser les prospecteurs ou de saisir leur équipement, Baine Sabot-de-Sang veut que leurs pioches soient brisées à la forge et rapportées, afin de s'assurer que leur travail est stoppé et d'envoyer un message clair contre la profanation de la terre sacrée.",al={"outils cassés","pourquoi outils cassés","but des outils cassés"}},["95107d94"]={q="Qui sont les nains qui creusent en Mulgore ?",a="Ce sont des prospecteurs nains qui ont installé un camp d'excavation dans les collines au nord-ouest de Mulgore. Poussés par des rumeurs selon lesquelles d'anciens secrets sont enterrés sous les plaines, ils recherchent des reliques historiques et des connaissances sur les titans, sans se soucier de la profanation spirituelle que leurs carrières infligent à la terre et à sa faune.",al={"nains en mulgore","qui sont les prospecteurs nains","prospecteurs en mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="La chasse commence",s="Au Camp Narache, les jeunes chasseurs rassemblent nourriture et plumes pour leur peuple. Grull Vent-du-faucon vous envoie chasser des trotteurs des plaines sur la Mesa de Nuage rouge, où le village compte sur ce que ses jeunes peuvent fournir.",h="Au Camp Narache, les jeunes chasseurs rassemblent nourriture et plumes pour leur peuple.",kw={"camp narache","chef vent-du-faucon","plumes","grull vent-du-faucon","la chasse commence","mulgore","trotteur des plaines","mesa de nuage rouge"},ang={["class:Hunter"]="En tant que chasseur, vous exercez votre adresse au tir et vos talents de pisteur en chassant les rapides trotteurs des plaines de la Mesa de Nuage rouge. Vous apprenez aussi à honorer les bêtes qui vous nourrissent.",["race:Tauren"]="En tant que jeune shu'halo, votre première chasse aux trotteurs des plaines sur la mesa vous lie à la terre et à votre devoir de nourrir le Camp Narache."},sec={{t="La subsistance d’une tribu",b="Les Tauren chassent sur la Mesa de Nuage rouge pour nourrir et vêtir leur peuple. Ils considèrent la traque et la poursuite comme des épreuves de discipline et comme un sport. Quand les réserves du Camp Narache s’amenuisent, les jeunes chasseurs récoltent de la viande de trotteur des plaines pour la cuisine et des plumes pour les vêtements tribaux."},{t="Gagner la reconnaissance",b="Grull Vent-du-faucon juge les nouveaux venus qui espèrent quitter la Mesa de Nuage rouge pour les vastes plaines de Mulgore. Avant qu’ils puissent rencontrer son père, le Chef Vent-du-faucon, il leur demande de prouver leurs capacités. Une chasse réussie montre qu’ils savent se débrouiller seuls et contribue à soutenir la tribu."}},faq={{q="Qui donne cette quête ?",a="Grull Vent-du-faucon vous confie cette tâche au Camp Narache. Fils du Chef Vent-du-faucon, il guide les jeunes chasseurs sur la Mesa de Nuage rouge.",al={"donneur de quête","qui lance la chasse commence","grull vent-du-faucon"}},{q="Pourquoi chasser des trotteurs des plaines plutôt que d’autres bêtes ?",a="Les trotteurs des plaines sont nombreux sur la mesa. Leur viande renfloue les réserves de nourriture basses, et leurs plumes servent à confectionner les vêtements et les ornements traditionnels des Tauren.",al={"pourquoi les trotteurs des plaines","viande et plumes de trotteur des plaines","chasser les trotteurs des plaines"}},{q="Pourquoi dois-je faire mes preuves avant de rencontrer le Chef Vent-du-faucon ?",a="Grull Vent-du-faucon vous demande de montrer que vous maîtrisez les bases de la survie et que vous êtes fidèle au village avant de rencontrer le Chef Vent-du-faucon et d’assumer de plus grandes responsabilités.",al={"pourquoi faire ses preuves auprès du chef vent-du-faucon","approbation du chef vent-du-faucon","pourquoi chasser d’abord"}},{q="Quel est le but général de ces épreuves sur la Mesa de Nuage rouge ?",a="La Mesa de Nuage rouge met les jeunes Tauren à l’épreuve avant qu’ils descendent vers les vastes plaines de Mulgore et entrent dans Pitons-du-Tonnerre, la capitale.",al={"but des épreuves sur la mesa","pourquoi suis-je sur la mesa de nuage rouge","quitter la mesa de nuage rouge"}},{q="Que se passe-t-il après cette chasse ?",a="Après que vous avez rapporté viande et plumes, Grull approuve votre chasse et vous envoie pister du gibier plus gros, plus difficile à trouver sur la mesa.",al={"quête suivante","suite de quête","que faire après la chasse commence"}},{q="Les Tauren ne chassent-ils que pour survivre ?",a="Les Tauren chassent pour se procurer de la nourriture et des matériaux comme le cuir, les os et les plumes. Ils chassent aussi par sport et pour communier avec les esprits. La chasse aiguise les instincts qui permettent à leurs tribus de rester vigilantes et fortes.",al={"philosophie de la chasse des tauren","chasser par sport","pourquoi les tauren chassent"}}},fx={["395288c5"]={q="Pourquoi Grull Vent-du-faucon veut-il que cela soit fait ?",a="Grull Vent-du-faucon voit du potentiel en vous et souhaite que vous prouviez votre valeur à la tribu et à son père, le Chef Vent-du-faucon. Les réserves de viande du Camp Narache s'amenuisent, et le camp a besoin de plumes fraîches. En vous envoyant les récolter, il teste vos instincts de chasseur tout en reconstituant les provisions essentielles du village.",al={"pourquoi grull veut chasser les trotteurs","mobile de grull vent-du-faucon","pourquoi chasser les trotteurs pour grull"}},f26a5c4f={q="À quoi sert la Viande de trotteur des plaines ?",a="La viande est collectée pour reconstituer les réserves de nourriture du Camp Narache, qui s'amenuisent. La survie sur la Mesa de Nuage rouge exige une alimentation fiable, et la chasse aux trotteurs des plaines fournit la viande fraîche nécessaire pour nourrir les jeunes chasseurs et les anciens vivant au camp.",al={"à quoi sert la viande de trotteur","pourquoi collecter de la viande de trotteur","utilisation de la viande de trotteur"}},fb1052a7={q="À quoi sert la Plume de trotteur des plaines ?",a="Les plumes de trotteur des plaines sont utilisées par les Taurens du Camp Narache pour confectionner des vêtements et des ornements. La tribu utilise chaque partie des bêtes qu'elle chasse, transformant le plumage robuste en tenues pratiques et en regalia adaptés à la vie sur la mesa.",al={"à quoi servent les plumes de trotteur","pourquoi collecter les plumes de trotteur","utilisation de la plume de trotteur"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="L'eau empoisonnée",s="Les puits souillés de Mulgore menacent l’eau qui nourrit les taurens et la faune locale. À Sabot-de-Sang, Mull Corne-tonnerre demande aux jeunes défenseurs de la Horde de rassembler des composants pour un totem purificateur.",h="Les puits souillés de Mulgore menacent l’eau qui nourrit les taurens et la faune locale.",kw={"sabot-de-sang","totem purificateur","mulgore","mull corne-tonnerre","trotteur des plaines","l'eau empoisonnée","loup des prairies","puits sabot-d’hiver"},ang={["class:Druid"]="En tant que druide, vous savez que les gobelins qui empoisonnent les sources d’eau douce menacent l’équilibre naturel de Mulgore. Vous protégez sa flore et sa faune fragiles.",["class:Shaman"]="En tant que chaman, vous restaurez l’eau polluée à l’aide d’un totem fait de morceaux de bêtes, honorant le chamanisme tauren et ses liens avec la faune locale.",["race:Tauren"]="En tant que tauren, vous savez que l’eau douce empoisonnée bafoue les dons de la Terre-Mère. Purifier les puits est un devoir que vous assumez en atteignant l’âge adulte à Mulgore."},sec={{t="Une terre profanée",b="Des intrus gobelins et leurs sbires ont souillé les puits de Mulgore. La pollution menace l’eau qui nourrit les tribus taurens et la faune locale. Mull Corne-tonnerre, un ancien du village de Sabot-de-Sang, a découvert les dégâts. Les taurens se sont installés ici récemment, et ces puits sont essentiels à la vie sur leurs plaines sacrées."},{t="Rassembler l’essence de la nature",b="Mull s’appuie sur le chamanisme tauren pour purifier le Puits Sabot-d’Hiver. Il lui faut un totem rituel façonné dans la force des bêtes indigènes de Mulgore. Vous récoltez des pattes de loups des prairies et des serres de trotteurs des plaines adultes dans les plaines du sud-ouest. La force de la terre elle-même sera opposée à la pollution."}},faq={{q="Qui a souillé les puits de Mulgore ?",a="Des intrus gobelins et leurs sbires ont souillé les puits sacrés de Mulgore, menaçant l’eau qui nourrit les taurens et la faune locale.",al={"qui a souillé les puits","qui a empoisonné mulgore","qui a pollué l’eau"}},{q="Pourquoi Mull Corne-tonnerre a-t-il besoin de pattes de loups et de serres de trotteurs des plaines ?",a="Mull utilise des pattes de loups des prairies et des serres de trotteurs des plaines pour fabriquer un totem purificateur ancré dans la force des bêtes indigènes de Mulgore.",al={"pourquoi des pattes de loup","pourquoi des serres de trotteur des plaines","composants du totem"}},{q="Quel puits cette quête prépare-t-elle à purifier ?",a="Les composants récoltés serviront à fabriquer un totem purificateur pour le Puits Sabot-d’Hiver.",al={"pour quel puits","quel puits"}},{q="Où se trouve Mull Corne-tonnerre ?",a="Mull Corne-tonnerre se trouve au village de Sabot-de-Sang, le principal établissement tauren du centre de Mulgore, près du Lac Taureau-de-pierre.",al={"emplacement de mull corne-tonnerre","où se trouve mull","où rendre l’eau empoisonnée"}},{q="Où trouver les loups et les trotteurs des plaines nécessaires ?",a="Des loups des prairies et des trotteurs des plaines adultes parcourent les plaines au sud-ouest du village de Sabot-de-Sang.",al={"où trouver des loups des prairies","emplacement des trotteurs des plaines","lieux de chasse"}},{q="Que se passe-t-il après que Mull a reçu les pattes et les serres ?",a="Mull lie les pattes et les serres dans un Totem de purification de Sabot-d’hiver, puis vous envoie au Puits Sabot-d’Hiver pour accomplir le rite de purification.",al={"quête suivante après l’eau empoisonnée","que faire ensuite"}}},fx={["50414ce1"]={q="Pourquoi Mull Corne-tonnerre veut-il que cela soit fait ?",a="Les gobelins et leurs mercenaires ont corrompu les puits sacrés à travers Mulgore, s'attaquant à la force vitale même de la terre natale des Taurens. Pour Mull Corne-tonnerre et les habitants du village de Sabot-de-Sang, laisser les puits souillés invite la maladie et profane l'équilibre sacré de la terre. Les purifier est un devoir spirituel et pratique urgent.",al={"mobile de mull corne-tonnerre","pourquoi purifier les puits d'eau","pourquoi quête poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="La caravane dévastée",s="Près du Lac Taureau-de-pierre, La caravane dévastée attire toujours les récupérateurs de la KapitalRisk. Des guerriers taurens ont brûlé le convoi après avoir perdu des compagnons dans une escarmouche. Les caisses intactes témoignent de l’ampleur des opérations de la KapitalRisk en Mulgore.",h="Près du Lac Taureau-de-pierre, La caravane dévastée attire toujours les récupérateurs de la KapitalRisk.",kw={"morin traqueur-de-nuage","mulgore","caravane dévastée","lac taureau-de-pierre","caisse de fournitures","kapitalrisk"},ang={["faction:Horde"]="L’expansion sans contrôle des entreprises en Mulgore menace la stabilité des Pitons-du-Tonnerre. Les éclaireurs de la Horde doivent donc perturber la logistique de la KapitalRisk.",["profession:Mining"]="Les caisses robustes et les notes logistiques témoignent des opérations agressives de prospection et d’extraction minières de la KapitalRisk en Mulgore.",["race:Tauren"]="Les machines de la KapitalRisk profanent les plaines, et ses opérations de défrichement frappent directement votre terre ancestrale. Récupérer et détruire ses fournitures aide à défendre Mulgore."},sec={{t="Vengeance au bord du lac",b="Des guerriers taurens ont brûlé un convoi de la KapitalRisk après avoir perdu deux compagnons lors d’une escarmouche antérieure. Morin Traqueur-de-nuage et ses guerriers ont frappé rapidement, puis incendié les chariots pour chasser les intrus armés. Ils ont abandonné les débris, convaincus que le feu consumerait tout ce que les gobelins étaient venus transporter."},{t="Une affaire inachevée",b="Des récupérateurs de la KapitalRisk sont revenus sur les décombres noircis, signe que le feu n’a pas détruit toute la cargaison. Morin envoie des éclaireurs inspecter les restes plutôt que de risquer d’autres vies à l’aveuglette. Parmi les débris couverts de suie se trouvent des caisses intactes portant l’insigne de la division minière de la KapitalRisk. Elles sont emballées pour être expédiées vers des installations centrales de traitement."}},faq={{q="Pourquoi la caravane a-t-elle été détruite ?",a="Morin Traqueur-de-nuage et ses guerriers taurens ont tendu une embuscade à la caravane et l’ont incendiée en représailles, après la mort de deux de leurs éclaireurs lors d’une escarmouche antérieure contre la KapitalRisk.",al={"qui a détruit la caravane","pourquoi la caravane est-elle incendiée","attaque de la caravane"}},{q="Où se trouve la caravane dévastée ?",a="Les chariots brûlés se trouvent sur la rive nord du Lac Taureau-de-pierre, à l’est de Sabot-de-Sang, en Mulgore.",al={"emplacement de la caravane","où se trouve la caravane","lieu de la caravane dévastée"}},{q="Pourquoi les gobelins reviennent-ils sur les décombres ?",a="La KapitalRisk a envoyé des récupérateurs, car le feu n’a pas détruit toute sa cargaison. Ils cherchent à récupérer des caisses de fournitures résistantes, destinées à ses installations centrales de traitement.",al={"pourquoi les récupérateurs sont-ils ici","récupérateurs de la kapitalrisk","que veulent les gobelins"}},{q="Que contiennent les caisses de fournitures ?",a="Les caisses portent l’insigne de la division minière de la KapitalRisk et contiennent des ressources minérales destinées au raffinage et au traitement dans les principales usines industrielles de la compagnie.",al={"contenu des caisses","que contient la caisse","caisse de fournitures scellée"}},{q="Qui est Morin Traqueur-de-nuage ?",a="Morin Traqueur-de-nuage est un éclaireur et pisteur tauren posté à l’est de Sabot-de-Sang. Il surveille les incursions ennemies dans le centre de Mulgore, en particulier celles de la KapitalRisk.",al={"qui est morin","rôle de morin traqueur-de-nuage"}},{q="Que révèle cette caravane sur la KapitalRisk ?",a="La caravane montre que la présence de la KapitalRisk en Mulgore dépasse celle d’une simple équipe d’exploration. Il s’agit d’une opération organisée d’extraction industrielle, dotée de lignes de ravitaillement armées et de réseaux de raffinage centralisés.",al={"présence de la kapitalrisk en mulgore","pourquoi les gobelins sont-ils en mulgore"}}},fx={["89fc7cfd"]={q="Pourquoi Morin Traqueur-de-nuage veut-il que les caisses de la caravane soient examinées ?",a="Morin et ses guerriers ont tendu une embuscade à la caravane de la KapitalRisk près du Lac Taureau-de-pierre pour venger leurs camarades tombés au combat, brûlant les chariots et supposant que le feu détruirait tout ce qui était utile. Voir des pillards gobelins fouiller les décombres l'a alerté sur le fait que quelque chose de précieux ou de dangereux avait survécu aux flammes. Il a besoin que vous inspectiez les caisses pour savoir ce que la KapitalRisk transportait à travers Mulgore et pourquoi ils sont si impatients de les récupérer.",al={"pourquoi examiner la caravane","mobile de morin traqueur-de-nuage","pourquoi fouiller les caisses de ravitaillement"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="Le voyage commence à peine",s="À Orgrimmar, les travailleurs du cuir expérimentés apprennent à se protéger du Vol draconique noir avec les écailles d’Onyxia. Le seigneur Runthak leur enseigne une technique rare pour confectionner une cape qui résiste aux flammes du Pic Rochenoire.",h="À Orgrimmar, les travailleurs du cuir expérimentés apprennent à se protéger du Vol draconique noir avec les...",kw={"rochenoire","mère des couvées","cape","travail du cuir","runthak","nefarian","onyxia","écaille"},ang={["faction:Horde"]="Pour la Horde, l’équipement protecteur forgé à partir des dépouilles de ses ennemis est essentiel pour préserver ses troupes d’autres ravages draconiques."},sec={{t="L’héritage d’une mère des couvées",b="La chute d’Onyxia est un triomphe pour la Horde, mais le Vol draconique noir reste une menace. Sa peau écailleuse résiste aux flammes draconiques. Les chefs de la Horde cherchent donc des artisans capables de transformer les restes du dragon en armure défensive, plutôt que de les laisser se perdre."},{t="Un rempart contre les flammes de l’ombre",b="Le seigneur Runthak apprend aux travailleurs du cuir talentueux à confectionner la Cape en écailles d’Onyxia. Sa leçon n’est ni une simple démonstration ni une marque de prestige. Au cœur du mont Rochenoire, le frère d’Onyxia, Nefarian, crache un feu dévastateur. Sans la protection enchantée des écailles de leur mère des couvées, toute avant-garde affrontant le Lord of Blackrock serait réduite en cendres."}},faq={{q="Qui propose cette quête et où se trouve-t-il ?",a="Le seigneur Runthak propose cette quête à Orgrimmar. Il reconnaît les champions de la Horde, maîtres dans l’art du travail du cuir, qui ont contribué à vaincre Onyxia.",al={"donneur de quête runthak","où se trouve le seigneur runthak","début de quête"}},{q="Quelle condition faut-il remplir pour recevoir cette quête ?",a="Seuls les travailleurs du cuir expérimentés ayant accompli les suites de la défaite d’Onyxia peuvent recevoir cette quête, notamment ceux qui ont terminé « Victory for the Horde » ou « A Most Puzzling Circumstance ».",al={"condition de travail du cuir","comment obtenir la quête","conditions préalables"}},{q="Qu’enseigne le seigneur Runthak ?",a="Le seigneur Runthak apprend aux travailleurs du cuir à confectionner la Cape en écailles d’Onyxia avec celles de la mère des couvées vaincue.",al={"recette en récompense de quête","patron de la cape d’onyxia","qu’apprend-on"}},{q="Pourquoi la Cape en écailles d’Onyxia est-elle importante ?",a="La cape protège son porteur du souffle incendiaire meurtrier de Nefarian. Sans cette protection unique, affronter le maître de la couvée serait fatal.",al={"pourquoi confectionner une cape","utilité de la cape","cape contre nefarian"}},{q="Qui est le Lord of Blackrock ?",a="Nefarian est le Lord of Blackrock, un puissant dragon noir et le frère d’Onyxia. Depuis les hauteurs du mont Rochenoire, il complote pour dominer les races mortelles.",al={"qui est le lord of blackrock","identité de nefarian","seigneur de rochenoire"}},{q="Pourquoi la quête affirme-t-elle que le voyage commence à peine ?",a="Onyxia a été tuée, mais la guerre plus vaste contre le Vol draconique noir et les machinations de Nefarian au cœur du mont Rochenoire n’a fait que s’intensifier.",al={"sens du titre","pourquoi le voyage commence à peine"}}},fx={cb1b5404={q="Pourquoi le seigneur Runthak souhaite-t-il que cela soit fait ?",a="Le seigneur Runthak cherche l'éradication totale du Vol draconique noir. Bien que la défaite d'Onyxia ait été un triomphe retentissant, sa couvée infeste toujours le royaume sous les ordres de son frère, Nefarian. En transmettant la technique ancestrale permettant de façonner des capes protectrices à partir des écailles de la matrone, Runthak s'assure que les champions de la Horde disposent de la protection vitale nécessaire pour résister à la Flamme d'ombre mortelle de Nefarian et mettre fin à la guerre.",al={"pourquoi runthak donne cette quête","motivation du seigneur runthak","objectif de runthak"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="Le voyage commence à peine",s="À Hurlevent, le Major Mattingly honore l'artisan qui a vaincu Onyxia. Il lui enseigne à confectionner une cape à partir de ses écailles.",h="À Hurlevent, le Major Mattingly honore l'artisan qui a vaincu Onyxia.",kw={"vol draconique noir","rochenoire","travail du cuir","major mattingly","nefarian","onyxia","cape en écailles d'onyxia","hurlevent"},ang={["faction:Alliance"]="En tant que héros de l'Alliance, vous portez la victoire de Hurlevent sur Onyxia jusqu'à la prochaine offensive contre son frère Nefarian, au Mont Rochenoire."},sec={{t="Un savoir-faire rare",b="Peu de ceux qui ont aidé à vaincre Onyxia savent travailler sa peau. Quand un maître travailleur du cuir se présente devant le Major Mattingly à Hurlevent, l'officier comprend combien ce savoir-faire pourrait compter dans les batailles à venir."},{t="Se protéger du Vol draconique noir",b="La mort d'Onyxia ne met pas fin à la menace du Vol draconique noir. Le Major Mattingly apprend à l'artisan à traiter et à coudre ses écailles pour confectionner une Cape en écailles d'Onyxia. Elle protège du souffle ardent de son frère Nefarian, Lord of Blackrock."}},faq={{q="Qui propose la quête Le voyage commence à peine ?",a="Le Major Mattingly, à Hurlevent, transmet ce savoir aux héros de l'Alliance qui ont combattu lors de la campagne contre Onyxia et maîtrisent le travail du cuir.",al={"qui donne la quête le voyage commence à peine","où trouver la quête le voyage commence à peine","personnage qui donne la quête le voyage commence à peine"}},{q="Qu'enseigne cette quête ?",a="Le Major Mattingly apprend aux maîtres travailleurs du cuir à confectionner une Cape en écailles d'Onyxia à partir des écailles d'Onyxia.",al={"quelle recette obtient-on","recette de la cape d'onyxia","récompense de la quête le voyage commence à peine"}},{q="Pourquoi la Cape en écailles d'Onyxia est-elle nécessaire ?",a="La Cape en écailles d'Onyxia protège son porteur du souffle ardent de Nefarian, Lord of Blackrock.",al={"pourquoi faut-il la cape d'onyxia","à quoi sert la cape en écailles d'onyxia","protection contre l'ombreflamme"}},{q="Qui est le Lord of Blackrock dont parle le Major Mattingly ?",a="Nefarian est Lord of Blackrock, un puissant dragon noir et le frère d'Onyxia. Il règne sur le Pic Rochenoire et poursuit les complots du Vol draconique noir.",al={"qui est lord of blackrock","qui est nefarian","avertissement du major mattingly sur les dragons"}},{q="Pourquoi le héros doit-il être travailleur du cuir pour recevoir ce savoir ?",a="Un maître travailleur du cuir possède le savoir-faire avancé nécessaire pour travailler les écailles de dragon sans détruire leurs propriétés protectrices magiques.",al={"pourquoi le travail du cuir est-il requis","tout le monde peut-il obtenir cette quête","condition de travailleur du cuir"}},{q="La mort d'Onyxia met-elle fin à la menace du Vol draconique noir à Hurlevent ?",a="Non. Onyxia est morte, mais son frère Nefarian commande toujours le Mont Rochenoire et complote contre l'Alliance et les races mortelles.",al={"hurlevent est-elle sûre maintenant","onyxia est morte, que faire ensuite","le vol draconique noir après onyxia"}}},fx={b42a6800={q="Pourquoi le Major Mattingly vous offre-t-il ces connaissances ?",a="Le Major Mattingly sait que tuer Onyxia n'était que la première frappe. La mère de la couvée est morte, mais ses semblables menacent toujours Azeroth depuis les hauteurs du Mont Rochenoire. Pour éliminer le vol draconique noir restant, les champions doivent survivre aux flammes brûlantes de Nefarian lui-même. Mattingly partage cette technique spécialisée afin que les héros de l'Alliance puissent confectionner des capes protectrices à partir des écailles d'Onyxia et terminer la guerre.",al={"pourquoi mattingly vous enseigne cela","mobile du major mattingly","raison de mattingly"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="La légende de Stalvan",s="Cette enquête sur Stalvan Mantebrume vous mène hors du Bois de la Pénombre jusqu’à une maison isolée dans le sud-est de la forêt d’Elwynn. Le marshal Haggard, un vétéran âgé à la vue déclinante, vous dirige vers un coffre à l’étage contenant un vieux paquet de papiers abandonné lors de son emménagement.",h="Cette enquête sur Stalvan Mantebrume vous mène hors du Bois de la Pénombre jusqu’à une maison isolée dans le...",kw={"bois de la pénombre","forêt d’elwynn","page de journal décolorée","esprit mélancolique","marshal haggard","stalvan"},ang={["faction:Alliance"]="Dévoiler l’héritage de Stalvan expose des chapitres sombres cachés discrètement au sein des frontières pastorales pourtant paisibles d’Elwynn.",["race:Human"]="Le chemin de Stalvan serpente à travers les établissements humains ordinaires, servant de mise en garde contre l’isolement et la malveillance cachés au grand jour."},sec={{t="Le grenier d’un vétéran",b="Le marshal Haggard vit loin de la ville, aux confins sud-est de la forêt d’Elwynn, près des frontières du Bois de la Pénombre et des Carmines. En emménageant dans sa demeure isolée, il a trouvé un coffre dissimulé à l’étage, rempli de vieux parchemins. Sa vue défaillante l’empêchant de les lire, il a abandonné toute tentative et a laissé les documents intacts jusqu’à ce qu’un enquêteur vienne poser des questions sur Stalvan."},{t="Ombres persistantes",b="Les papiers laissés dans le coffre à l’étage ne sont pas de simples détritus domestiques. Déranger les affaires de Stalvan agite régulièrement une magie instable, invoquant un Esprit mélancolique lié au passé de Mantebrume. La page de journal dissimulée à l’intérieur fournit un témoignage direct des écrits privés de Stalvan, prouvant concrètement que le reclus a laissé sa marque à Elwynn avant de disparaître."}},faq={{q="Qui est le marshal Haggard ?",a="Le marshal Haggard est un vétéran âgé, presque aveugle, qui vit tranquillement dans une cabane isolée au sud-est de la forêt d’Elwynn. Il conserve des documents oubliés depuis longtemps, découverts chez lui, qui appartenaient à Stalvan Mantebrume.",al={"marshal haggard","haggard elwynn","qui est haggard"}},{q="Pourquoi la piste a-t-elle mené à la forêt d’Elwynn ?",a="Les indices recueillis à Sombre-Comté et Ruisselune retracent les errances de Stalvan à travers le territoire sud de Hurlevent. La propriété de Haggard abritait de vieux papiers laissés par Stalvan.",al={"pourquoi la forêt d’elwynn","stalvan elwynn","pourquoi aller voir haggard"}},{q="Que contient le coffre à l’étage ?",a="Le coffre contient une page de journal décolorée écrite par Stalvan Mantebrume, préservée parmi un paquet de parchemins que Haggard n’a jamais réussi à examiner correctement.",al={"coffre à l’étage","page de journal décolorée","que contient le coffre"}},{q="Pourquoi un esprit attaque-t-il lorsque le coffre est ouvert ?",a="Un Esprit mélancolique hante les reliques de l’ancienne vie de Stalvan et se manifeste violemment lorsqu’un étranger dérange ses écrits et ses souvenirs personnels.",al={"esprit mélancolique","pourquoi l’esprit attaque","fantôme chez haggard"}},{q="Comment cela fait-il avancer l’enquête sur Stalvan ?",a="La page décolorée fournit une preuve de première main écrite par Stalvan lui-même, aidant à reconstituer l’histoire de son passé.",al={"mystère stalvan","que révèle la page","étape de la quête de stalvan"}},{q="Pourquoi le marshal Haggard n’a-t-il pas pu lire les papiers lui-même ?",a="La vue de Haggard s’est troublée et affaiblie avec l’âge, l’empêchant de déchiffrer l’écriture fine ou altérée sur les documents décolorés.",al={"haggard aveugle","pourquoi haggard a besoin d’aide"}}},fx={["7284e072"]={q="Pourquoi le Marshal Haggard veut-il que cela soit fait ?",a="Le Marshal Haggard est un vieux soldat vivant dans une retraite paisible, mais il conserve les instincts d'un officier du royaume. Lorsque vous venez chercher la vérité sur Stalvan Mantebrume, il se souvient des parchemins abandonnés dans le coffre lorsqu'il a repris la maison. Bien qu'il n'ait aucun intérêt personnel dans ce sombre mystère, il souhaite aider votre enquête autant qu'il le peut, même si sa vue défaillante l'empêche d'examiner les papiers lui-même.",al={"pourquoi aider haggard","mobile du marshal haggard","pourquoi haggard veut le journal"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="La chasse continue",s="Grull Vent-du-faucon envoie de jeunes chasseurs dans les collines au sud de la Mesa de Nuage rouge pour y chasser des pumas des montagnes et en rapporter les peaux. Elles serviront à vêtir les enfants de la tribu et à raccommoder ses tentes.",h="Grull Vent-du-faucon envoie de jeunes chasseurs dans les collines au sud de la Mesa de Nuage rouge pour y...",kw={"camp narache","chef vent-du-faucon","grull vent-du-faucon","peaux de pumas des montagnes","mesa de nuage rouge","chasse tauren","la chasse continue"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez la manière de chasser dans les plaines : traquer les bêtes avec un but, ne prendre que le nécessaire et ne jamais les traiter comme du gibier de sport ni comme des trophées.",["race:Tauren"]="En tant que jeune tauren qui atteint l'âge adulte sur la Mesa de Nuage rouge, vous apprenez à utiliser chaque partie d'une bête au profit de la tribu, de la nourriture aux vêtements et aux abris. C'est un rite de passage essentiel."},sec={{t="Le but de la chasse",b="Au Camp Narache, Grull Vent-du-faucon envoie de jeunes chasseurs au sud, dans les collines de la Mesa de Nuage rouge, pour chasser des pumas des montagnes. Il ne s'agit pas de chercher des trophées. Cette chasse apprend aux jeunes chasseurs à subvenir aux besoins de leur communauté."},{t="Abriter la tribu",b="Le Camp Narache a besoin des peaux pour confectionner des vêtements pour les enfants de la tribu et raccommoder les tentes usées. Quand vous les rapporterez, les anciens vous seront reconnaissants de votre contribution. Grull promet de dire à son père, le chef Vent-du-faucon, ce que vous avez accompli."}},faq={{q="Pourquoi la tribu a-t-elle besoin de peaux de pumas des montagnes ?",a="La tribu a besoin de peaux de pumas des montagnes pour confectionner des vêtements pour ses enfants et réparer les tentes du village au Camp Narache. Grull Vent-du-faucon explique que ces peaux sont nécessaires pour les deux usages.",al={"pourquoi chasser les pumas","à quoi servent les peaux de puma","utilisation des peaux de pumas des montagnes"}},{q="Qui propose cette quête ?",a="Grull Vent-du-faucon propose cette chasse au Camp Narache. Chasseur de renom et fils du chef Vent-du-faucon, il guide les jeunes chasseurs pour qu'ils contribuent à la vie du village.",al={"qui donne la quête la chasse continue","donneur de quête au camp narache"}},{q="Où trouve-t-on les pumas des montagnes ?",a="Les pumas des montagnes rôdent dans les collines au sud du Camp Narache, sur la Mesa de Nuage rouge.",al={"où sont les pumas","emplacement des pumas des montagnes","où trouver un puma des montagnes"}},{q="Quel lien unit Grull Vent-du-faucon au chef Vent-du-faucon ?",a="Grull Vent-du-faucon est le fils du chef Vent-du-faucon, le dirigeant de la tribu au Camp Narache. Grull promet de parler de vos exploits à son père si vous rapportez les peaux nécessaires.",al={"comment impressionner le chef vent-du-faucon","fils du chef vent-du-faucon"}},{q="Que nous apprend cette chasse sur la tradition tauren ?",a="Chez les taurens, la chasse n'est ni un sport ni une quête de trophées. Utiliser la peau, la viande et les os d'une bête pour faire vivre la communauté honore les plaines et aide la tribu à survivre.",al={"philosophie de la chasse tauren","pourquoi chasser à mulgore"}},{q="Pourquoi les peaux de pumas des montagnes sont-elles si précieuses ?",a="Les peaux de pumas des montagnes sont épaisses et résistantes, et supportent bien les intempéries des plaines. Elles réchauffent les enfants et aident à réparer les habitations, ce qui leur vaut l'estime des anciens du village.",al={"les peaux de puma ont-elles de la valeur","pourquoi les peaux de puma sont-elles prisées"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="La caravane dévastée",s="À Mulgore, La caravane dévastée révèle aux Pistonneurs de Sabot-de-Sang une présence illégale sur le territoire tauren. KapitalRisk pille les richesses minérales du pays, et les Pistonneurs se préparent à défendre leurs plaines ancestrales.",h="À Mulgore, La caravane dévastée révèle aux Pistonneurs de Sabot-de-Sang une présence illégale sur le...",kw={"sabot-de-sang","morin traqueur-de-nuage","mulgore","pistonneurs","caravane dévastée","caisse de fournitures","kapitalrisk","documents de kapitalrisk"},ang={["class:Druid"]="En tant que druide, vous tenez l’équilibre de la terre pour sacré. L’exploitation minière à ciel ouvert destructrice de KapitalRisk, noyée dans la fumée, est une profanation qu’il faut purifier.",["faction:Horde"]="En tant que membre de la Horde, vous savez que sa sécurité dépend de la loyauté et de la stabilité de Mulgore. Les cartels marchands étrangers qui saccagent ses collines menacent Pitons-du-Tonnerre lui-même.",["profession:Mining"]="En tant que mineur, vous voyez que les minerais de haute qualité entassés dans la caisse prouvent que de riches filons souterrains se trouvent sous les collines orientales de Mulgore, attirant des étrangers avides de les exploiter.",["race:Tauren"]="En tant que tauren, vous pouvez voir dans ces machines grossières qui éventrent les plaines ancestrales de Mulgore un affront à la Mère-Terre et un acte de guerre contre la paix que vous venez de trouver."},sec={{t="Preuves d’exploitation",b="À l’est du village de Sabot-de-Sang, une caravane dévastée gît au bord de la route. Dans une caisse de fournitures scellée se trouvent du minerai et des minéraux extraits, ainsi qu’une liasse ficelée de documents de KapitalRisk. Ces papiers prouvent que la compagnie a commencé à creuser des mines dans les vallées paisibles de Mulgore, sans autorisation."},{t="La vigilance des Pistonneurs",b="Morin Traqueur-de-nuage et ses compagnons Pistonneurs surveillent attentivement les frontières de Mulgore. Ils craignent que des factions extérieures n’exploitent leur paisible patrie. Quand Morin reçoit les documents récupérés, ceux-ci confirment ses pires craintes. La fumée qui s’élève au-dessus des contreforts orientaux annonce une invasion commerciale grandissante. Les taurens doivent repousser les Profanateurs avant que leurs collines ne soient entièrement éventrées."}},faq={{q="Que contient la caisse de fournitures scellée ?",a="La caisse de fournitures scellée contient du minerai et des minéraux bruts extraits, ainsi qu’une liasse ficelée de documents de KapitalRisk décrivant ses activités.",al={"butin de la caisse de fournitures","que contient la caisse","contenu de la caisse"}},{q="Qui est Morin Traqueur-de-nuage ?",a="Morin Traqueur-de-nuage est un Pistonneur tauren posté sur la route à l’est du village de Sabot-de-Sang, en direction de la frontière des Tarides. Il patrouille à Mulgore et surveille les menaces étrangères.",al={"qui est morin","rôle de morin traqueur-de-nuage","morin le pistonneur"}},{q="Pourquoi KapitalRisk est-elle à Mulgore ?",a="KapitalRisk cherche à exploiter les ressources naturelles et les filons minéraux de Mulgore, éventrant les collines sans se soucier de la terre ni de ses habitants.",al={"pourquoi les gobelins sont-ils ici","objectif de kapitalrisk à mulgore","que veulent les gobelins"}},{q="D’où venait la caravane ?",a="La caravane appartenait à KapitalRisk. Elle transportait du minerai extrait et des documents sur ses activités depuis les opérations de la compagnie dans les contreforts, avant d’être détruite sur la piste.",al={"à qui appartenait la caravane","origine de la caravane","qui a attaqué la caravane"}},{q="Où cette enquête mène-t-elle ensuite ?",a="Une fois les documents en main, Morin Traqueur-de-nuage charge des guerriers d’affronter les dirigeants de KapitalRisk et de démanteler ses mines dans les contreforts orientaux.",al={"what comes next","quête suivante après la caravane dévastée","suite de l’enquête sur la caravane"}},{q="Pourquoi cela menace-t-il les taurens ?",a="Les taurens considèrent la terre comme sacrée et vénèrent la Mère-Terre. L’exploitation minière à ciel ouvert et la pollution industrielle irresponsables de KapitalRisk profanent le paysage intact de Mulgore.",al={"pourquoi les taurens s’en soucient","menace de kapitalrisk","menace pour mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="Une humble contribution",s="Sur la Mesa de Nuage rouge, Chef Vent-du-faucon charge un jeune aventurier de prendre des nouvelles de sa mère. Ses urgentes préoccupations tribales le retiennent au Camp Narache ; il vous envoie donc vers le sud-est, au puits où Grand-mère Hawkwind est allée chercher de l'eau.",h="Sur la Mesa de Nuage rouge, Chef Vent-du-faucon charge un jeune aventurier de prendre des nouvelles de sa...",kw={"une humble contribution","camp narache","chef vent-du-faucon","grand-mère hawkwind","mulgore","mesa de nuage rouge","puits"},ang={["faction:Horde"]="Les tâches paisibles et pastorales de Narache montrent le mode de vie communautaire des Taurens, dans un contraste avec la lutte plus rude pour survivre qui se joue dans la Horde naissante.",["race:Tauren"]="Pour les jeunes guerriers taurens, répondre à l'appel du chef montre leur respect des aînés et leur attachement au bien-être commun de la tribu, selon les enseignements de la Terre-Mère."},sec={{t="Harmonie et devoirs communs",b="Chaque membre de la tribu doit contribuer à son harmonie et faire sa part. Pour les jeunes Taurens, le devoir commence par prendre soin de la communauté, et pas seulement par faire preuve de prouesse contre les hurans ou les prédateurs. Chef Vent-du-faucon est retenu à son poste par les tâches qui consistent à diriger et à défendre le camp. Il fait donc confiance aux jeunes aventuriers pour veiller sur les aînés."},{t="Le puits au sud-est de Narache",b="Les puits au-delà du campement fournissent de l'eau à la Mesa de Nuage rouge. Grand-mère Hawkwind a quitté le Camp Narache tôt le matin pour aller puiser de l'eau fraîche à une source au sud-est du campement. La faune territoriale et les hurans Dos-ébouriffé parcourent ces terres. Quand une aînée s'absente pendant des heures, Chef Vent-du-faucon s'inquiète et vous envoie vérifier qu'elle n'a rien."}},faq={{q="Qui propose cette quête et où puis-je le trouver ?",a="Chef Vent-du-faucon, dirigeant du Camp Narache sur la Mesa de Nuage rouge, dans Mulgore, propose cette tâche. Il se trouve dans le pavillon central du camp, où il veille aux affaires locales.",al={"qui propose une humble contribution","où prendre la quête","emplacement de chef vent-du-faucon"}},{q="Où se trouve Grand-mère Hawkwind ?",a="Grand-mère Hawkwind se trouve au puits juste au sud-est du Camp Narache, dans la partie basse de la mesa.",al={"emplacement de grand-mère hawkwind","où se trouve la mère","emplacement du puits"}},{q="Pourquoi Chef Vent-du-faucon ne va-t-il pas lui-même voir sa mère ?",a="Chef Vent-du-faucon doit rester au Camp Narache pour s'occuper des affaires urgentes de la tribu et guider les jeunes guerriers. En tant que chef, il fait confiance à la tribu pour prendre soin des siens et compte sur les jeunes aventuriers pour veiller aux affaires du village à sa place.",al={"pourquoi le chef ne peut pas y aller","pourquoi vent-du-faucon ne va pas voir sa mère","chef vent-du-faucon est occupé"}},{q="Grand-mère Hawkwind est-elle en danger au puits ?",a="Des couguars des montagnes agressifs et des striders parcourent les plaines alentour, mais Grand-mère Hawkwind est en sécurité près du puits. Elle est agréablement surprise que quelqu'un ait pris la peine de venir s'enquérir d'une aînée.",al={"est-elle en sécurité","grand-mère est-elle attaquée","danger au puits"}},{q="Quelle est l'importance culturelle de cette quête pour les Taurens ?",a="La culture tauren accorde une grande importance à la famille, à une communauté soudée et au respect des aînés. Les jeunes héros apprennent que la force réside dans le service humble et la protection de leurs proches, et non dans la quête de gloire personnelle.",al={"culture tauren et humble contribution","pourquoi est-ce une humble contribution","aînés taurens"}},{q="Que se passe-t-il après avoir trouvé Grand-mère Hawkwind ?",a="Après avoir parlé à Grand-mère Hawkwind, elle vous demande de l'aider à rapporter au camp la cruche d'eau remplie.",al={"quête suivante","suite d'une humble contribution","que faire après avoir trouvé la mère"}}},fx={b1d313d3={q="Pourquoi le Chef Vent-du-faucon veut-il que vous vérifiiez sa mère ?",a="Sa mère âgée a quitté le Camp Narache tôt le matin pour puiser de l'eau au puits au sud-est, et cela fait très longtemps qu'elle est partie. La vie des Taurens est enracinée dans la responsabilité communautaire et l'entraide, donc bien que Vent-du-faucon s'inquiète pour son bien-être, ses devoirs de chef le retiennent au camp.",al={"pourquoi vent-du-faucon veut cela","mobile du chef vent-du-faucon","pourquoi vérifier grand-mère hawkwind"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="Une humble contribution",s="À la Mesa de Nuage rouge, de jeunes taurens portent l’eau du puits au Camp Narache, à la demande de Grand-mère Hawkwind. Cette tâche leur apprend l’humilité et le souci de la tribu.",h="À la Mesa de Nuage rouge, de jeunes taurens portent l’eau du puits au Camp Narache, à la demande de...",kw={"camp narache","chef vent-du-faucon","grand-mère hawkwind","humble contribution","mulgore","mesa de nuage rouge","rites of the earthmother","cruche d'eau"},ang={["faction:Horde"]="En tant que membre de la Horde, vous découvrez comment la famille Hawkwind enseigne la solidarité et la survie aux taurens de Mulgore, une partie paisible mais résolue de la Horde de Thrall.",["race:Tauren"]="En tant que tauren, porter de l’eau pour vos aînés témoigne de votre souci de la communauté et de votre disposition à suivre la voie de la Terre-Mère."},sec={{t="La vigueur de la jeunesse",b="Grand-mère Hawkwind veille à ses devoirs près du puits, à l’extrémité sud de la Mesa de Nuage rouge. L’âge l’a ralentie, bien qu’elle ait parcouru de nombreux sentiers à travers les plaines. Lorsque de jeunes taurens qui espèrent défendre leur peuple viennent la voir, elle canalise leur énergie vers les besoins de la communauté. En rendant service, ils peuvent faire leurs preuves en prenant soin des autres."},{t="Au service de la tribu",b="Vous portez une cruche pleine vers le nord-ouest, jusqu’au Camp Narache, et la remettez au Chef Vent-du-faucon, le dirigeant du camp et le fils de Grand-mère Hawkwind. Dans les plaines arides de Mulgore, la vie dépend du travail partagé et d’un approvisionnement régulier en eau fraîche. Porter le fardeau d’une aînée témoigne du respect envers ceux dont les soins unissent la tribu."},{t="La voie vers Pitons-du-Tonnerre",b="Quand vous apportez au Camp Narache l’eau de sa mère, le Chef Vent-du-faucon voit plus qu’une corvée achevée. La coutume tauren veut que ceux qui souhaitent défendre leur peuple au loin commencent par faire preuve d’humilité et de disponibilité. Votre discrète discipline attire l’attention du chef. Il vous recommande pour les Rites of the Earthmother, des épreuves spirituelles qui ouvrent les portes de Pitons-du-Tonnerre."}},faq={{q="Qui est Grand-mère Hawkwind ?",a="Grand-mère Hawkwind est une aînée de la famille Hawkwind qui veille sur le puits de la Mesa de Nuage rouge. Elle est la mère du Chef Vent-du-faucon et enseigne aux jeunes taurens l’humilité et le souci de leur tribu.",al={"grand-mère hawkwind","qui confie une humble tâche","aînée hawkwind"}},{q="Où se trouve le puits ?",a="Le puits se trouve au sud-est du Camp Narache, dans les plaines herbeuses de la Mesa de Nuage rouge. Des cruches d’eau fraîche attendent près du puits, pour que les voyageurs et les responsables du camp puissent les rapporter.",al={"emplacement du puits","où se trouve le puits","trouver une cruche d’eau"}},{q="Qui est le Chef Vent-du-faucon ?",a="Le Chef Vent-du-faucon dirige le Camp Narache, sur la Mesa de Nuage rouge. Il organise l’entraînement et les rites spirituels des jeunes taurens qui se préparent à servir l’ensemble de la tribu dans Mulgore.",al={"chef vent-du-faucon","qui est le chef","dirigeant du camp narache"}},{q="Pourquoi cette corvée est-elle considérée comme une épreuve importante ?",a="Les taurens valorisent l’humilité, le souci de la communauté et le respect des aînés. Les tâches quotidiennes montrent que vous prenez soin de votre peuple autant que de votre propre gloire au combat.",al={"pourquoi porter de l’eau","pourquoi une humble tâche","cette quête est-elle importante"}},{q="Que se passe-t-il après Une humble contribution ?",a="Après avoir porté l’eau, le Chef Vent-du-faucon vous oriente vers les Rites of the Earthmother, des épreuves traditionnelles pour les taurens qui atteignent l’âge adulte.",al={"what comes next","quête suivante","après une humble contribution"}},{q="Où cette voie mène-t-elle finalement ?",a="Le respect des aînés vous prépare à quitter la Mesa de Nuage rouge et à traverser Mulgore en direction de Pitons-du-Tonnerre, la capitale aux hautes mesas.",al={"destination future","où allons-nous","objectif pitons-du-tonnerre"}}},fx={["57bce500"]={q="Pourquoi Grand-mère Hawkwind veut-elle que cela soit fait ?",a="Grand-mère Hawkwind admet que ses jambes vieillissantes n'ont plus leur vigueur d'antan, ce qui rend les corvées quotidiennes simples autour de la Mesa de Nuage rouge lentes et fatigantes. Plus important encore, elle considère cette course de routine comme une leçon morale vitale pour vous. Livrer de l'eau potable essentielle à son fils, le Chef Vent-du-faucon, sert d'épreuve initiale pour voir si vous possédez l'humilité, la patience et l'esprit communautaire attendus d'un véritable serviteur de la tribu.",al={"mobile de grand-mère hawkwind","pourquoi apporter de l'eau au chef vent-du-faucon","pourquoi tâche humble"}},b511fd77={q="À quoi sert la Cruche d'eau ?",a="La Cruche d'eau est un simple récipient en argile rempli au puits sur la Mesa de Nuage rouge pour fournir de l'eau propre au Camp Narache. Le transporter teste votre dévouement aux corvées communautaires, en veillant à ce que même les aventuriers novices apprennent la valeur de soutenir leurs proches avant de poursuivre une gloire martiale plus grande.",al={"but de la cruche d'eau","pourquoi cruche d'eau","qu'est-ce que la cruche"}},["19ad5d96"]={q="Pourquoi Grand-mère Hawkwind vous le demande-t-elle au lieu de le faire elle-même ?",a="Grand-mère Hawkwind est âgée et admet que ses jambes n'ont plus leur force d'antan, ce qui signifie que porter des cruches lourdes lui prend beaucoup plus de temps qu'auparavant. Lorsqu'un novice valide comme vous s'approche, elle saisit l'occasion à la fois de soulager son propre fardeau et de tester votre volonté d'effectuer des tâches quotidiennes ingrates pour le camp.",al={"pourquoi pas grand-mère","pourquoi me demander de l'eau","pourquoi vent-du-faucon ne peut pas chercher de l'eau"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="La purification de Sabot-d'hiver",s="Le Puits Sabot-d’Hiver, en Mulgore, a été souillé. À Sabot-de-Sang, Mull Corne-tonnerre vous remet un totem consacré pour le purifier. Des opérations gobelines ont contaminé les sources voisines, et purifier ce puits est la première étape pour assainir les eaux du centre de Mulgore.",h="Le Puits Sabot-d’Hiver, en Mulgore, a été souillé.",kw={"sabot-de-sang","purification","mulgore","mull corne-tonnerre","poison","totem","kapitalrisk","puits d’eau","sabot-d’hiver"},ang={["class:Druid"]="En tant que druide, vous voyez la faune assoiffée revenir à la source purifiée. Son retour montre pourquoi la nature doit être soignée partout où la civilisation la menace.",["class:Shaman"]="En tant que chaman, vous canalisez les esprits à travers les totems pour purifier la corruption industrielle et honorer votre lien avec les eaux élémentaires.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à préserver l’eau potable du cœur des terres taurens, un pilier méridional de la jeune Horde.",["race:Tauren"]="En tant que tauren, vous savez que les puits de Mulgore sont des dons sacrés de la Terre-Mère qui donnent la vie. Les protéger de la cupidité des gobelins est à la fois un devoir envers votre peuple et une obligation sacrée."},sec={{t="Une terre souillée",b="Les plaines herbeuses de Mulgore dépendent de puits ancestraux qui font vivre le gibier et les tribus taurens dispersées. La KapitalRisk a récemment amené ses mercenaires industriels dans les collines au sud-est de Sabot-de-Sang. Leurs activités ont contaminé les nappes phréatiques locales et rendu toxique le Puits Sabot-d’Hiver. Les bêtes sauvages évitent son eau, et les campements voisins sont menacés si la corruption se répand dans la terre."},{t="Le rituel de purification des eaux",b="Mull Corne-tonnerre sculpte un totem purificateur et le bénit au nom de la Terre-Mère. Des hommes de main armés de la KapitalRisk se sont emparés de la source, alors vous devez les affronter pour atteindre le puits. Placez le totem à sa tête, et il chassera les rejets immondes. L’eau pourra alors remonter, pure, des profondeurs de la terre."}},faq={{q="Où se trouve le Puits Sabot-d’Hiver ?",a="Le Puits Sabot-d’Hiver se trouve dans les collines au sud-est de Sabot-de-Sang, en Mulgore. Des ouvriers gobelins et des mercenaires de la KapitalRisk patrouillent dans les environs.",al={"emplacement du puits sabot-d’hiver","où se trouve le puits sabot-d’hiver","comment trouver le puits sabot-d’hiver"}},{q="Pourquoi le puits a-t-il été empoisonné ?",a="La KapitalRisk a commencé à miner et à creuser dans les environs. Des rejets toxiques et des déchets se sont infiltrés dans la nappe phréatique, rendant la source dangereuse à boire pour la faune locale et les taurens.",al={"qui a empoisonné l’eau","pourquoi le puits est-il sale","puits de la kapitalrisk"}},{q="Qui est Mull Corne-tonnerre ?",a="Mull Corne-tonnerre est un ancien spirituel du village de Sabot-de-Sang, profondément attentif à la santé de la terre. Il façonne des totems cérémoniels pour réparer les dégâts causés par les envahisseurs venus d’ailleurs.",al={"qui est mull","rôle de mull corne-tonnerre"}},{q="Que se passe-t-il après la purification du puits ?",a="Une fois que l’eau du Puits Sabot-d’Hiver est redevenue limpide et que la faune peut la boire sans danger, Mull Corne-tonnerre vous envoie purifier d’autres puits menacés de Mulgore, en commençant par le Thunderhorn Totem.",al={"what comes next","après la purification de sabot-d’hiver","que fait mull ensuite"}},{q="Qui garde le puits ?",a="Le puits est tenu par des ouvriers et des mercenaires employés par la KapitalRisk. Ce syndicat dirigé par des gobelins exploite les ressources naturelles sans se soucier de l’écosystème local.",al={"qui garde le puits sabot-d’hiver","quels ennemis se trouvent au puits"}},{q="Comment fonctionne le totem purificateur ?",a="Sculpté selon les rites sacrés des taurens et couvert de protections, le totem puise dans les esprits de la nature et les bénédictions de la Terre-Mère pour purger la source de ses polluants chimiques artificiels.",al={"tradition du totem purificateur","comment fonctionne le totem de mull"}}},fx={["16ee77f0"]={q="Pourquoi Mull Corne-tonnerre veut-il que le Puits Sabot-d'Hiver soit purifié ?",a="Le Puits Sabot-d'Hiver est vital pour l'équilibre et la survie de Mulgore. Son eau a été souillée, menaçant à la fois la faune locale et les tribus qui en dépendent. Mull Corne-tonnerre a préparé un totem de purification consacré, mais son pouvoir doit être apporté directement sur le site pour guérir les eaux et restaurer l'harmonie sur la terre.",al={"pourquoi purifier le puits winterhoof","mobile de mull corne-tonnerre","pourquoi purifier l'eau winterhoof"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Un service pour la Horde",s="À Orgrimmar, Zor Arbre-solitaire a reçu le pendentif serti et peut vous parler de votre service pour la Horde.",h="À Orgrimmar, Zor Arbre-solitaire a reçu le pendentif serti et peut vous parler de votre service pour la Horde.",kw={"marécage d’âprefange","pendentif","report to zor","service pour la horde","zor arbre-solitaire"},sec={{t="Zor Arbre-solitaire à Orgrimmar",b="Le pendentif serti se trouve désormais auprès de Zor Arbre-solitaire à Orgrimmar. Retournez le voir pour en apprendre davantage sur votre service pour la Horde."},{t="Les dernières paroles de Zor",b="Zor dit que les érudits ont besoin de temps pour étudier le pendentif. Il vous offre un petit témoignage de reconnaissance pour votre service à la Horde. Vos actes vous font honneur, ainsi qu’à la Horde."}},faq={{q="Qui a le pendentif maintenant ?",a="Zor Arbre-solitaire, à Orgrimmar, a le pendentif. Vous le lui avez apporté depuis Nazeer Bloodpike, à Mur-de-Fougères.",al={"qui récupère le pendentif","qui donne cette quête","rôle de zor arbre-solitaire"}},{q="Quelle quête précède celle-ci ?",a="Report to Zor vient d’abord. Vous avez apporté le pendentif serti à Zor Arbre-solitaire.",al={"quelle quête précède celle-ci","condition préalable au service pour la horde","quête précédente"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Les Rites de la Terre-mère",s="Sur la Mesa de Nuage rouge, les jeunes taurens commencent leur voyage spirituel sous la protection du Chef Vent-du-faucon. Il les envoie au sud de Camp Narache, auprès du Voyant Langue-grise, qui les guide vers les épreuves.",h="Sur la Mesa de Nuage rouge, les jeunes taurens commencent leur voyage spirituel sous la protection du Chef...",kw={"camp narache","chef vent-du-faucon","terre-mère","mesa de nuage rouge","rites of the earthmother","voyant langue-grise","tauren"},ang={["class:Druid"]="En tant que druide, vous commencez votre quête d'harmonie avec la nature en respectant les conseils sacrés des anciens et des voyants de votre tribu.",["class:Shaman"]="En tant que futur chaman, vous commencez par des rites bénis par les voyants de votre tribu. Ils constituent une première étape essentielle vers la communion avec les éléments et les esprits de Mulgore.",["faction:Horde"]="En tant que membre de la Horde, vous découvrez le cœur spirituel de vos alliés taurens, récemment ralliés à la Horde, à travers ces épreuves sacrées.",["race:Tauren"]="En tant que tauren, vous entamez un voyage spirituel à travers les Rites of the Earthmother. Ils mettent à l'épreuve votre aptitude à servir votre tribu et à vénérer la Terre-mère."},sec={{t="Le seuil des épreuves",b="Sur la Mesa de Nuage rouge, le Chef Vent-du-faucon envoie les jeunes taurens auprès du Voyant Langue-grise, dans les collines au sud de Camp Narache. Le voyant guide les jeunes au début de leur cheminement spirituel. Ce voyage les éloigne de la vie quotidienne du camp et les mène vers les devoirs qu'exigent leurs coutumes tribales."},{t="Honorer la Terre-mère",b="La Terre-mère façonne les croyances des taurens sur la création et la vie quotidienne. Ses rites mettent à l'épreuve leur maturité, leur résilience et leur profondeur spirituelle. Le Voyant Langue-grise avertit ceux qui atteignent son sanctuaire que les épreuves exigent un dévouement total aux traditions de la mesa."}},faq={{q="Qui donne la quête Rites of the Earthmother ?",a="Le Chef Vent-du-faucon dirige les jeunes taurens de Camp Narache vers le Voyant Langue-grise, dans les collines voisines.",al={"qui lance rites of the earthmother","donneur de quête"}},{q="Où trouver le Voyant Langue-grise ?",a="Le Voyant Langue-grise vit dans les collines juste au sud de Camp Narache, sur la Mesa de Nuage rouge, en Mulgore.",al={"où se trouve le voyant langue-grise","emplacement du voyant langue-grise","trouver le voyant langue-grise"}},{q="Que sont les Rites of the Earthmother ?",a="Les Rites of the Earthmother sont des épreuves traditionnelles sacrées où les jeunes taurens prouvent leur sagesse, leur force et leur dévouement envers leur peuple et leurs croyances.",al={"que sont les rites of the earthmother","histoire des épreuves de la terre-mère"}},{q="Qui est le Voyant Langue-grise ?",a="Le Voyant Langue-grise est un ancien spirituel respecté. Il vit au sud de Camp Narache et guide les initiés lors des épreuves sacrées de la Terre-mère.",al={"qui est le voyant langue-grise","rôle du voyant langue-grise"}},{q="Qui est le Chef Vent-du-faucon ?",a="Le Chef Vent-du-faucon dirige Camp Narache, sur la Mesa de Nuage rouge, et prépare les jeunes taurens avant de les envoyer auprès des voyants.",al={"qui est le chef vent-du-faucon","rôle du chef vent-du-faucon"}},{q="Que faut-il faire pour achever cette tâche ?",a="Partez vers le sud depuis Camp Narache, dans les collines, puis parlez au Voyant Langue-grise pour lui dire que vous êtes prêt pour les épreuves.",al={"que dois-je faire","comment terminer la quête"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Le totem de Corne-tonnerre",s="À Sabot-de-Sang, Mull Corne-tonnerre demande aux jeunes champions de la Horde de façonner un totem sacré. La pollution de KapitalRisk gagne les puits de Mulgore, et les griffes des prédateurs insuffleront dans le bois la force primordiale des plaines.",h="À Sabot-de-Sang, Mull Corne-tonnerre demande aux jeunes champions de la Horde de façonner un totem sacré.",kw={"sabot-de-sang","purification","griffes de puma","cougar des plaines","mulgore","mull corne-tonnerre","traqueur des prairies","griffes de traqueur","le totem de corne-tonnerre","puits d’eau"},ang={["class:Hunter"]="Comme chasseur, vous apprenez à connaître les bêtes qui traquent dans les plaines et honorez chaque bête abattue en récoltant ses griffes pour préserver l’écosystème.",["class:Shaman"]="Comme chaman, vous invoquez les esprits vivants de la terre pour purifier l’eau souillée par une entreprise contre nature et irresponsable.",["race:Tauren"]="Comme tauren, protéger les aquifères de Mulgore de l’exploitation étrangère est un devoir tribal sacré. Le précepte de la Mère Terre appelle à préserver l’équilibre de la vie plutôt qu’à tout piller."},sec={{t="Chasser les prédateurs des plaines",b="Mull Corne-tonnerre a besoin de griffes naturelles pour créer un totem de purification. KapitalRisk empoisonne l’eau de Mulgore en exploitant les terres, et Mull cherche un remède. Les traqueurs des prairies et les cougars des plaines rôdent à l’est et à l’ouest de Sabot-de-Sang. Leurs griffes portent l’essence naturelle des prédateurs et insufflent au totem leur vigueur brute et intacte."},{t="La nature de la chasse",b="La tradition tauren distingue la chasse pour se nourrir ou préserver l’équilibre spirituel du pillage massif des gobelins. Mull pense que la pureté de la chasse des prédateurs indigènes peut aider à purifier la terre corrompue. Les machines gobelines souillent les sources avec du pétrole et des déchets industriels. La force naturelle des bêtes peut fournir l’énergie spirituelle nécessaire pour restaurer le Puits Corne-tonnerre."}},faq={{q="Pourquoi Mull Corne-tonnerre a-t-il besoin de griffes de prédateurs ?",a="Mull utilise les griffes des traqueurs des prairies et des cougars des plaines pour canaliser dans un totem de purification l’esprit prédateur pur et primordial des plaines. Il pense que l’esprit des chasseurs naturels peut contrer la corruption industrielle artificielle.",al={"pourquoi des griffes","utilité des griffes de traqueur","utilité des griffes de puma"}},{q="Qui pollue l’eau de Mulgore ?",a="Les gobelins de KapitalRisk qui travaillent à Mulgore polluent les terres et l’eau. Leurs activités d’extraction irréfléchies et leurs installations minières déversent des boues toxiques dans les aquifères qui alimentent les puits tribaux.",al={"qui a contaminé le puits","pourquoi le puits est-il empoisonné","qu’est-ce qui a empoisonné mulgore"}},{q="Où trouve-t-on les traqueurs des prairies et les cougars des plaines ?",a="Les traqueurs des prairies et les cougars des plaines rôdent dans les plaines dégagées du centre de Mulgore, surtout dans les savanes vallonnées à l’est et à l’ouest de Sabot-de-Sang.",al={"emplacement des traqueurs","où trouver des cougars","emplacements des griffes de puma"}},{q="Que se passe-t-il après la création du totem de Corne-tonnerre ?",a="Après avoir sculpté le totem et l’avoir enchanté avec les griffes, Mull vous envoie au Puits Corne-tonnerre contaminé. Là, vous accomplissez le rituel de purification et chassez le poison.",al={"que faire ensuite","après le totem de corne-tonnerre","suite de la quête du totem"}},{q="Quel est le lien avec la purification précédente du Puits Sabot-d’Hiver ?",a="Les Tauren s’efforcent de préserver les eaux sacrées de Mulgore. Le Puits Sabot-d’Hiver a été purifié en premier, et la contamination menace maintenant le Puits Corne-tonnerre, plus au nord.",al={"lien avec sabot-d’hiver","quête du totem précédente"}},{q="Pourquoi les Tauren n’utilisent-ils pas simplement des remèdes à base de plantes au lieu de griffes d’animaux ?",a="L’art rituel tauren puise dans les aspects élémentaires et physiques de la nature. La pureté acérée des prédateurs dominants fournit une force spirituelle active qui peut lutter contre les poisons industriels agressifs des gobelins.",al={"pourquoi pas des herbes","matériaux des totems chamaniques"}}},fx={cb047e40={q="Pourquoi Mull Corne-tonnerre veut-il que cela soit fait ?",a="Le Puits Corne-tonnerre devient de plus en plus souillé d'heure en heure, empoisonné par les opérations imprudentes des gobelins à proximité. Mull Corne-tonnerre doit fabriquer un totem de purification sacré pour purifier le puits avant que la corruption ne se propage davantage à travers la terre et ne nuise à son peuple.",al={"pourquoi mull veut cela","mobile de mull corne-tonnerre","pourquoi fabriquer le totem corne-tonnerre"}},["43953f1d"]={q="Contre quoi êtes-vous envoyé pour les griffes ?",a="Vous êtes envoyé pour chasser les prédateurs sauvages qui rôdent dans les plaines de Mulgore : les traqueurs des prairies et les couguars des plaines. Ces bêtes errent naturellement à l'est et à l'ouest du village de Sabot-de-Sang, vivant et chassant comme partie intégrante de l'équilibre naturel de la terre.",al={"que dois-je chasser","quelles sont les cibles","proie du totem corne-tonnerre"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Le rite de force",s="Au Camp Narache, les jeunes taurens affrontent les gurbashis Dos-hérissé lors du Rite de force. Ils rapportent leurs ceintures au Chef Vent-du-faucon pour prouver leur courage et défendre la tribu.",h="Au Camp Narache, les jeunes taurens affrontent les gurbashis Dos-hérissé lors du Rite de force.",kw={"ravin de roncelame","gurbashi dos-hérissé","camp narache","chef vent-du-faucon","terre-mère","mulgore","gurbashi","le rite de force","voyant langue-grise"},ang={["faction:Horde"]="En tant que membre de la Horde, vous contribuez à défendre la Mesa de Nuage rouge, l’un de ses principaux lieux de recrutement. Là, les jeunes guerriers et chamans peuvent mûrir en sécurité et aider la nouvelle union.",["race:Tauren"]="Jeune tauren, vous commencez les rites ancestraux en prouvant que vous pouvez défendre votre peuple contre les gurbashis avant de quitter la Mesa de Nuage rouge."},sec={{t="La première épreuve",b="Le Voyant Langue-grise invite les jeunes taurens à commencer les Rites of the Earthmother par le Rite de force. Pour obtenir la reconnaissance des anciens de la tribu et être acceptés à Pitons-du-Tonnerre, les initiés doivent accomplir cette tâche. L’épreuve vérifie s’ils peuvent affronter avec courage les ennemis mortels de la tribu et défendre la Mesa de Nuage rouge."},{t="La menace des gurbashis Dos-hérissé",b="À l’est du Camp Narache, le Ravin de Roncelame abrite les gurbashis Dos-hérissé. Ils empiètent sur les terres ancestrales, tendent des embuscades aux groupes de chasse et pillent les réserves du camp à la faveur de la nuit. Vous devez les tuer et rapporter leurs ceintures. Celles-ci prouvent votre valeur et contribuent à la sécurité du campement."}},faq={{q="Quel est le but du Rite de force ?",a="Le Rite de force éprouve le courage au combat d’un jeune tauren et marque le début des Rites of the Earthmother. En repoussant les menaces qui pèsent sur le camp, l’initié gagne le droit de poursuivre son chemin vers le respect à Pitons-du-Tonnerre.",al={"pourquoi faire le rite de force","histoire du rite de force","but du rite de force"}},{q="Qui confie cette épreuve et qui la juge ?",a="Le Voyant Langue-grise confie la tâche et en explique les exigences spirituelles et pratiques. Rapportez douze ceintures de gurbashis Dos-hérissé au Chef Vent-du-faucon, au Camp Narache, comme preuve de votre valeur.",al={"qui confie le rite de force","à qui remettre le rite de force"}},{q="Où se trouve le Ravin de Roncelame ?",a="Le Ravin de Roncelame se trouve à l’est du Camp Narache, sur la Mesa de Nuage rouge. Des gurbashis Dos-hérissé hostiles ont élu domicile dans son canyon épineux.",al={"où se trouve le ravin de roncelame","emplacement de roncelame"}},{q="Pourquoi s’en prendre aux gurbashis Dos-hérissé ?",a="Les gurbashis Dos-hérissé empiètent sur les territoires de chasse ancestraux de la tribu. Ils tendent des embuscades aux chasseurs taurens et dérobent des provisions au Camp Narache la nuit, ce qui en fait des ennemis de la tribu.",al={"pourquoi tuer les gurbashis dos-hérissé","qu’ont fait les gurbashis"}},{q="Pourquoi rapporter des ceintures plutôt que d’autres trophées ?",a="Les ceintures prouvent que l’initié a affronté les gurbashis et vaincu leurs guerriers adultes au corps à corps, au lieu de récupérer des trophées à distance.",al={"pourquoi les ceintures des gurbashis dos-hérissé","pourquoi les ceintures"}},{q="Que se passe-t-il après le Rite de force ?",a="Réussir le Rite de force prouve la valeur de l’initié et le qualifie pour les prochaines épreuves de la Terre-mère. Ces épreuves poursuivent le parcours officiel vers l’âge adulte et une place spirituelle au sein de la tribu.",al={"que faire après le rite de force","prochaine épreuve de la terre-mère"}}},fx={f38315d5={q="Pourquoi le Voyant Langue-grise vous envoie-t-il chez les Dos-hérissés ?",a="Le Voyant Langue-grise guide la jeunesse du Camp Narache à travers les Rites of the Earthmother sacrés. Pour votre première épreuve, il doit tester votre résolution martiale face à un danger réel et pressant pour la tribu. Les dos-hérissés ont empiété sur les terres Taurens, tendant des embuscades aux chasseurs et volant à couvert de l'obscurité. En vous envoyant les affronter, Langue-grise s'assure que vous protégez votre peuple tout en prouvant votre force et en gagnant le respect de la tribu.",al={"pourquoi langue-grise veut cela","mobile du voyant langue-grise","pourquoi rite of strength"}},e0dd8e68={q="Pourquoi êtes-vous envoyé pour faire cette épreuve seul ?",a="Le Rite of Strength est un rite de passage personnel, pas une simple corvée de garnison. Tandis que les guerriers du camp gardent le périmètre, chaque jeune Tauren doit démontrer indépendamment sa vaillance et ses capacités martiales avant d'être reconnu comme un adulte aux Pitons-du-Tonnerre. L'épreuve exige que vous affrontiez vous-même les ennemis de votre peuple afin que les anciens sachent que vous pouvez défendre la tribu lorsque vous êtes appelé.",al={"pourquoi moi pour rite of strength","pourquoi ne pas envoyer des gardes contre les dos-hérissés","pourquoi dois-je combattre les dos-hérissés"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="La purification de Corne-tonnerre",s="En Mulgore, la quête « La purification de Corne-tonnerre » vous appelle à purifier le Puits Corne-tonnerre. Mull Corne-tonnerre prépare un totem pour le rite, et les ancêtres Thunderhorn vous remercient lorsque la source est propre.",h="En Mulgore, la quête « La purification de Corne-tonnerre » vous appelle à purifier le Puits Corne-tonnerre.",kw={"esprits ancestraux","sabot-de-sang","totem de purification","earth mother","mulgore","mull corne-tonnerre","la purification de corne-tonnerre","puits corne-tonnerre"},ang={["class:Druid"]="En tant que druide, vous purifiez les eaux empoisonnées pour enrayer la corruption dans les terres vivantes de Mulgore et préserver l’harmonie naturelle des plaines.",["class:Shaman"]="En tant que chaman, vous canalisez l’énergie ancestrale à travers des totems pour soigner les sources corrompues. C’est au cœur de votre vocation.",["faction:Horde"]="En tant que membre de la Horde, vous renforcez ses liens avec les fiers Shu'halo en aidant les taurens à protéger leurs sources sacrées.",["race:Tauren"]="En tant que tauren, vous honorez la Earth Mother et protégez les vôtres tandis qu’ils bâtissent un foyer paisible et durable en Mulgore."},sec={{t="Une source de vie souillée",b="Les puits d’eau font vivre les tribus taurens installées dans les prairies de Mulgore. Quand un poison contamine une source souterraine, la faune et les campements voisins en souffrent. Le Puits Corne-tonnerre se trouve au nord du village de Sabot-de-Sang, et ses eaux ont besoin d’une purification spirituelle."},{t="La purification ancestrale",b="Mull Corne-tonnerre fabrique un totem de purification pour le rite. Portez-le jusqu’à la source empoisonnée et canalisez le pouvoir ancestral à travers lui pour chasser les toxines. Lorsque la purification réussit, les ancêtres Thunderhorn rendent visite à Mull en rêve et le remercient."}},faq={{q="Où se trouve le Puits Corne-tonnerre ?",a="Le Puits Corne-tonnerre se trouve dans les plaines au nord du village de Sabot-de-Sang, en Mulgore. Il fait partie des nombreux points d’eau qui approvisionnent les clans taurens locaux.",al={"emplacement du puits corne-tonnerre","où se trouve le puits","où utiliser le totem"}},{q="Qui lance ce rituel de purification ?",a="Mull Corne-tonnerre lance le rite. Il vit au village de Sabot-de-Sang et fabrique des totems pour soigner les terres meurtries de Mulgore.",al={"qui donne la quête","emplacement de mull corne-tonnerre","donneur de quête"}},{q="Pourquoi purifier les puits d’eau de Mulgore ?",a="Le poison et la corruption menacent les plaines et les tribus taurens qui dépendent d’une eau propre.",al={"pourquoi purifier les puits","qu’est-il arrivé à l’eau","pourquoi le puits est empoisonné"}},{q="Comment Mull sait-il que le rituel a réussi ?",a="Après la réussite du rite, les ancêtres Thunderhorn rendent visite à Mull en rêve et vous remercient pour votre acte.",al={"rêve des ancêtres","comment mull le sait","résultat de la purification du puits"}},{q="Que se passe-t-il après la purification du puits Corne-tonnerre ?",a="Après la purification du puits Corne-tonnerre, Mull vous envoie aider une autre région en difficulté en fabriquant le Wildmane Totem.",al={"que faire ensuite","quête suivante après corne-tonnerre","totem wildmane ensuite"}},{q="Qu’est-ce que le Totem de purification de Corne-tonnerre ?",a="Le Totem de purification de Corne-tonnerre est un focaliseur spirituel que Mull Corne-tonnerre fabrique pour purifier les eaux corrompues du puits ancestral de son clan.",al={"totem de purification","quel est l’objet totem","totem de mull"}}},fx={da3030fe={q="Pourquoi Mull Corne-tonnerre a-t-il besoin que vous purifiiez le puits ?",a="Mull Corne-tonnerre a fabriqué le foyer rituel, mais purifier une terre sacrée est un rite de service et d'honneur pour les champions montants parmi les Taurens et leurs alliés. En portant vous-même le Totem de purification de Corne-tonnerre au puits souillé, vous prouvez votre dévouement à la Terre-mère et aux esprits ancestraux de son clan, gagnant la faveur et les conseils des ancêtres qui veillent sur les eaux.",al={"pourquoi moi mull corne-tonnerre","pourquoi mull vous envoie-t-il","pourquoi effectuer le rituel de purification"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Le totem de Crin-sauvage",s="Au Wildmane Well, Mull Corne-tonnerre cherche à soigner les dernières eaux empoisonnées de Mulgore. Il lui faut les dents de prairie wolf alphas pour créer un totem capable de les purifier.",h="Au Wildmane Well, Mull Corne-tonnerre cherche à soigner les dernières eaux empoisonnées de Mulgore.",kw={"sabot-de-sang","mulgore","mull corne-tonnerre","prairie wolf alpha","pitons-du-tonnerre","totem","puits d’eau","crin-sauvage"},ang={["class:Hunter"]="En tant que chasseur, vous éprouvez votre respect pour la nature sauvage et ses prédateurs les plus féroces en traquant les rusés loups alphas autour des hautes falaises.",["class:Shaman"]="En tant que chaman, vous savez qu’il faut prendre soin d’harmoniser les totems de prédateur et l’eau élémentaire pour combattre le fléau toxique.",["race:Tauren"]="En tant que Tauren, vous héritez du devoir de soigner les puits ancestraux et d’honorer ce que la Terre-Mère demande à la terre d’offrir."},sec={{t="Le dernier puits",b="Le Wildmane Well est la dernière source empoisonnée du centre de Mulgore. Mull Corne-tonnerre a rassemblé ce qu’il lui fallait pour les puits de Sabot-d’Hiver et de Thunderhorn, mais l’eau contaminée menace toujours la faune migratrice et les campements des plaines. De puissants ingrédients issus de la terre sont nécessaires pour rétablir son équilibre."},{t="La force du prédateur",b="Les prairie wolf alphas parcourent les prairies de Mulgore, surtout sous les hautes falaises au pied des Pitons-du-Tonnerre. Mull Corne-tonnerre a besoin de leurs dents pour créer un totem purificateur destiné aux eaux du nord. Leur force et leur endurance conféreront au totem la puissance de ces féroces chasseurs."},{t="Sacrifice et équilibre",b="Pour les Tauren, prendre aux créatures de la terre est un acte solennel. Mull Corne-tonnerre voit les dents des alphas comme une nécessité, non comme une conquête. Le sacrifice des prédateurs pourrait contribuer à soigner les eaux empoisonnées de la Terre-Mère."}},faq={{q="À quoi sert le totem de Crin-sauvage ?",a="Mull Corne-tonnerre fabrique le totem pour purifier le Wildmane Well, la dernière source contaminée qui menace les Tauren de Mulgore.",al={"pourquoi créer le totem de crin-sauvage","utilité du totem de crin-sauvage"}},{q="Pourquoi faut-il précisément les dents des prairie wolf alphas ?",a="La profonde corruption du Wildmane Well exige la féroce puissance d’un prédateur suprême. Les dents des alphas insufflent cette force primitive au totem.",al={"pourquoi les dents de loup","utilité des dents de prairie wolf alphas"}},{q="Où trouve-t-on les prairie wolf alphas à Mulgore ?",a="Les prairie wolf alphas parcourent les plaines du nord de Mulgore, surtout les prairies autour du pied des Pitons-du-Tonnerre.",al={"emplacement des prairie wolf alphas","où trouver les prairie wolf alphas"}},{q="Qui fabrique le totem ?",a="Mull Corne-tonnerre, un ancien spirituel du village Sabot-de-Sang, fabrique chaque totem purificateur après qu’un novice a rassemblé les offrandes.",al={"qui fabrique le totem","donneur de quête du totem"}},{q="Que se passe-t-il après la création du totem de Crin-sauvage ?",a="Une fois que Mull Corne-tonnerre a fabriqué un totem avec les dents des alphas, vous le portez vers le nord pour purifier le Wildmane Well.",al={"what comes next","quête suivante du totem de crin-sauvage"}},{q="En quoi ce rituel reflète-t-il les croyances des Tauren ?",a="Les Tauren considèrent la mort d’un animal comme un échange solennel avec la nature. Mull pleure la mort des loups et honore leur rôle dans la guérison de la terre.",al={"philosophie taurène du totem","croyances de mull corne-tonnerre"}}},fx={["054e923c"]={q="Pourquoi Mull Corne-tonnerre veut-il que le Wildmane Totem soit fabriqué ?",a="Un seul puits d'eau corrompu reste à purifier en Mulgore : celui appartenant au clan Wildmane. Mull Corne-tonnerre s'est consacré à la purification des puits sacrés de la Terre-Mère, et la fabrication de ce dernier totem de purification en utilisant l'esprit prédateur de la terre est essentielle pour terminer le rite sacré et rendre l'eau pure à la tribu.",al={"pourquoi mull veut le wildmane totem","motif de mull corne-tonnerre","pourquoi fabriquer le wildmane totem"}},["2aa23a29"]={q="À quoi sert la Dent d'Alpha des prairies ?",a="Les dents de l'alpha des loups des prairies représentent le sacrifice et la vitalité féroce des prédateurs au sommet de la chaîne alimentaire en Mulgore. Mull Corne-tonnerre lie huit de ces crocs au Wildmane Totem afin que son esprit puisse apaiser l'ordre naturel et renforcer le rituel nécessaire pour purger la corruption du Puits Wildmane.",al={"utilisation de la dent d'alpha des prairies","à quoi servent les dents d'alpha des prairies","dents pour le wildmane totem"}},eb5f4bd0={q="Pourquoi chassez-vous les loups des prairies alpha ?",a="Vous êtes envoyé pour chasser les loups des prairies alpha, les chefs de meute dominants qui parcourent les plaines autour de la base des Pitons-du-Tonnerre. Leur force et leur férocité incarnent l'équilibre naturel des plaines, fournissant l'essence puissante dont Mull Corne-tonnerre a besoin pour le rituel final de purification de l'eau.",al={"pourquoi tuer les loups des prairies alpha","cible loup des prairies alpha","qui êtes-vous envoyé chasser"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="La mine Veine-de-jaspe",s="Des éclaireurs se dirigent vers la mine Veine-de-jaspe, dans l’est d’Elwynn, où les kobolds se sont peut-être répandus. Le maréchal Dughan doit savoir jusqu’où ils sont allés.",h="Des éclaireurs se dirigent vers la mine Veine-de-jaspe, dans l’est d’Elwynn, où les kobolds se sont peut-être...",kw={"azora","dughan","elwynn","fondugouffre","comté-de-l’or","veine-de-jaspe","kobold","mine","éclaireur"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez combien les territoires de Hurlevent sont vulnérables sans soutien royal centralisé, alors que Fondugouffre et Veine-de-jaspe sont toutes deux perdues.",["profession:Mining"]="En tant que mineur, vous voyez les précieux gisements dans les galeries de Veine-de-jaspe, mais les kobolds qui occupent le territoire vous barrent l’accès au minerai.",["race:Human"]="En tant qu’humain, vous voyez les infrastructures rurales d’Elwynn vaciller tandis que les ressources de la frontière tombent si près de la capitale."},sec={{t="Une seconde incursion",b="Après l’invasion des galeries de Fondugouffre, au sud du Comté-de-l’Or, le maréchal Dughan craint que les kobolds n’aient atteint d’autres mines. Veine-de-jaspe se trouve dans les contreforts rocheux, au nord-est de la tour d’Azora. Sa pierre et son métal approvisionnent le royaume. Comme les gardes de Hurlevent doivent patrouiller en ville, Dughan envoie des aventuriers indépendants vers l’est pour vérifier si les kobolds se sont aussi emparés de cette mine."},{t="Des défenses débordées",b="Les éclaireurs qui atteignent les salles de Veine-de-jaspe découvrent que les kobolds ont chassé les mineurs humains et fortifié les passages obscurs. Le maréchal Dughan essuie un nouveau revers tandis que la crise s’aggrave. Le roi Varian Wrynn a disparu et les troupes royales restent retenues loin des territoires périphériques. La garnison locale manque de soldats pour reprendre la mine. Le cœur du royaume manque de minerais et se retrouve cerné par les menaces."}},faq={{q="Où se trouve la mine Veine-de-jaspe ?",a="La mine Veine-de-jaspe se trouve dans les contreforts du nord-est de la forêt d’Elwynn. Depuis le Comté-de-l’Or, prenez la route principale vers l’est, dépassez la tour d’Azora, puis dirigez-vous vers le nord dans les collines.",al={"où se trouve veine-de-jaspe","emplacement de la mine veine-de-jaspe","comment trouver veine-de-jaspe"}},{q="Pourquoi le maréchal Dughan a-t-il besoin d’un éclaireur au lieu d’envoyer des gardes ?",a="Le maréchal Dughan a trop peu de gardes pour en détacher. Le roi Varian Wrynn a disparu et l’impasse politique dans la capitale a épuisé les forces locales, qui protègent les fermes et les villes contre les bandits et les gnolls. Dughan compte donc sur des éclaireurs civils.",al={"pourquoi envoyer des aventuriers","pourquoi aucun garde de hurlevent","où sont les gardes"}},{q="Pourquoi les kobolds s’emparent-ils des mines d’Elwynn ?",a="Les kobolds creusent des galeries vers les filons et les grottes humides. La présence militaire de Hurlevent s’étant réduite, ils ont pris de l’assurance et se sont enfoncés dans des mines humaines comme Fondugouffre et Veine-de-jaspe, pour s’emparer d’or, de minerai et de territoire.",al={"pourquoi des kobolds à veine-de-jaspe","que veulent les kobolds","raison de l’invasion des kobolds"}},{q="Que se passe-t-il après l’exploration de la mine Veine-de-jaspe ?",a="Après votre rapport sur la chute de Veine-de-jaspe, le maréchal Dughan doit faire face à la perte des mines de l’est et aux menaces sur plusieurs fronts. Il se tourne vers l’ouest d’Elwynn, où les gnolls Riverpaw font peser une lourde menace sur la garnison du ruisseau de l’ouest.",al={"que faire après veine-de-jaspe","suite de veine-de-jaspe"}},{q="Pourquoi la perte de la mine Veine-de-jaspe est-elle importante pour Hurlevent ?",a="Les mines d’Elwynn fournissent le minerai et la pierre dont Hurlevent a besoin pour son économie et pour forger armes et armures. La perte de Fondugouffre et de Veine-de-jaspe interrompt l’extraction et affaiblit le redressement du royaume.",al={"pourquoi veine-de-jaspe compte","importance de veine-de-jaspe"}},{q="À qui appartient la tour d’Azora toute proche ?",a="La tour d’Azora est une petite tour de mage située le long de la route de l’est de la forêt d’Elwynn. Theocritus, l’archimage d’Azora, y officie et les serviteurs d’Azora s’occupent de la tour. Les voyageurs s’en servent comme repère en route vers les contreforts de l’est.",al={"qu’est-ce que la tour d’azora","qui vit dans la tour d’azora"}}},fx={a973508b={q="Pourquoi le Maréchal Dughan veut-il que la Mine de Jasperlode soit explorée ?",a="Ayant déjà confirmé que les kobolds ont envahi la The Fargodeep Mine, le Maréchal Dughan craint que l'infestation ne soit pas un incident isolé. Il a besoin de savoir si la menace s'est également propagée à l'est, vers la Mine de Jasperlode. Sécuriser l'approvisionnement en ressources d'Elwynn et comprendre l'ampleur totale du danger imminent sont essentiels pour défendre la ville de Comté-de-l’Or et protéger les routes commerciales vitales de Hurlevent.",al={"motif de dughan pour la mine de jasperlode","pourquoi explorer la mine de jasperlode","pourquoi dughan a besoin que la mine de jasperlode soit examinée"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="La purification de Crin-sauvage",s="À Mulgore, les taurens achèvent leur purification au dernier puits. Depuis le village de Sabot-de-Sang, Mull Corne-tonnerre vous envoie vers le nord avec le Wildmane Totem achevé pour purifier l’eau empoisonnée et protéger le mode de vie tauren.",h="À Mulgore, les taurens achèvent leur purification au dernier puits.",kw={"sabot-de-sang","purification","terre-mère","mulgore","mull corne-tonnerre","totem","kapitalrisk","puits d’eau","crin-sauvage"},ang={["class:Druid"]="En tant que druide, vous contribuez à réparer les dégâts causés par les gobelins en soignant les écosystèmes ravagés et en protégeant les pâturages de Mulgore.",["class:Shaman"]="En tant que chaman, vous utilisez des totems rituels pour réparer les dégâts de la pollution mécanique et préserver l’harmonie entre les éléments naturels et les communautés vivantes.",["race:Tauren"]="En tant que tauren, restaurer les trois puits ancestraux de Mulgore est un rite de passage. Cela prouve votre dévouement à préserver les dons de la Terre-Mère."},sec={{t="Purifier le don de la Terre-Mère",b="Les puits de Mulgore alimentent les troupeaux, les terres et les tribus taurens rassemblées autour des Pitons-du-Tonnerre. La KapitalRisk et les gobelins qui avancent les ont souillés de rejets industriels toxiques. Les anciens taurens voient le danger pour leur peuple et leurs terres.\n\nLes puits Sabot-d’Hiver et Corne-tonnerre sont purifiés. Il ne reste plus que le Puits Wildmane, le troisième et dernier site corrompu. Ses eaux ont encore besoin d’une purification spirituelle."},{t="Le Wildmane Totem",b="Le Totem de purification de Crin-sauvage est fabriqué à partir d’éléments recueillis dans toute la région. Il puise dans le pouvoir réparateur des esprits ancestraux et de la terre élémentaire. Plantez-le près des eaux souillées, au nord des Pitons-du-Tonnerre. Le rituel disperse les produits chimiques, extrait les toxines et rétablit l’écoulement naturel.\n\nLa purification protège les taurens des maladies. Elle montre aussi clairement qu’ils ne toléreront pas la dégradation de leurs terres sacrées."}},faq={{q="Pourquoi le Puits Wildmane a-t-il été empoisonné ?",a="Les activités des gobelins, motivées par la cupidité industrielle et l’exploitation forestière, ont empoisonné les eaux souterraines de Mulgore avec des déchets chimiques. Ces déchets menacent la faune et les campements tribaux.",al={"qui a empoisonné le puits","pourquoi le puits est-il sale","poison des gobelins"}},{q="Où se trouve le Puits Wildmane ?",a="Le Puits Wildmane se trouve dans les plaines, juste au nord des mesas imposantes des Pitons-du-Tonnerre.",al={"emplacement du puits wildmane","où se trouve le puits wildmane","trouver le puits wildmane"}},{q="Qui organise ce rituel de purification ?",a="Mull Corne-tonnerre, un ancien du village de Sabot-de-Sang, vous guide dans la fabrication des totems et vous envoie purifier les puits.",al={"qui donne la quête de purification de crin-sauvage","donneur de quête","emplacement de mull corne-tonnerre"}},{q="Quels autres puits font partie de cette purification ?",a="Le Puits Wildmane est la troisième des trois sources d’eau vitales. Les puits Sabot-d’Hiver et Corne-tonnerre, tous deux au sud, ont été purifiés en premier.",al={"autres puits","puits de mulgore","puits sabot-d’hiver et corne-tonnerre"}},{q="Comment fonctionne le totem de purification ?",a="Fabriqué avec la magie ancestrale et des éléments naturels purifiés, le totem canalise un pouvoir spirituel réparateur dans les nappes phréatiques pour neutraliser les polluants des gobelins.",al={"fonctionnement du totem de purification","comment le totem purifie l’eau"}},{q="Que signifie l’achèvement de ce rituel pour le village de Sabot-de-Sang ?",a="La purification des trois puits garantit de l’eau potable aux tribus du centre de Mulgore. Elle honore le devoir des taurens de soigner la Terre-Mère après son exploitation industrielle.",al={"résultat de la quête","pourquoi purifier les puits","importance des taurens dans le lore"}}},fx={["119d5a48"]={q="Pourquoi Mull Corne-tonnerre veut-il que le Puits Wildmane soit purifié ?",a="Mull Corne-tonnerre veille sur l'équilibre spirituel et les ressources vitales du Mulgore. Les opérations malveillantes de la KapitalRisk ont empoisonné les précieuses sources d'eau de la terre, menaçant la survie des tribus et de leurs troupeaux. Le Puits Wildmane est le dernier des trois puits anciens encore souillés, et sa purification est essentielle pour guérir la Terre-Mère et garantir une eau potable saine pour le village de Sabot-de-Sang et les Pitons-du-Tonnerre.",al={"motif de mull corne-tonnerre","pourquoi purifier le puits wildmane","pourquoi mull se soucie des puits"}},b4cee6a1={q="Qu'est-ce que le Totem de purification de Crin-sauvage ?",a="Le Totem de purification de Crin-sauvage est un instrument préparé rituellement par Mull Corne-tonnerre pour canaliser les esprits ancestraux et terrestres. Lorsqu'il est activé au Puits Wildmane corrompu au nord des Pitons-du-Tonnerre, le totem expulse les boues toxiques laissées par les pollueurs gobelins, purifiant l'aquifère et redonnant à la source son état naturel et immaculé.",al={"utilisation du totem de purification de crin-sauvage","qu'est-ce que le wildmane totem","but du totem de purification"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="Chasse aux rapaces",s="Harken Totem-de-vent vous demande de pister les rapaces à travers Mulgore. Leurs plumes mettent à l’épreuve patience, ingéniosité et adresse au tir, et honorent les épreuves de la Terre-Mère.",h="Harken Totem-de-vent vous demande de pister les rapaces à travers Mulgore.",kw={"sabot-de-sang","harken totem-de-vent","mulgore","rapace","chasse aux rapaces","épreuve tauren","plume de rapace trophée"},ang={["class:Druid"]="En tant que druide, pister les rapaces à travers les mesas de Mulgore vous rapproche de ces oiseaux prédateurs qui contribuent à l’équilibre des cieux.",["class:Hunter"]="En tant que chasseur, pister les rapaces vous apprend à suivre les proies volantes, à lire leur comportement et à frapper avec précision face à des prédateurs vigilants.",["race:Tauren"]="En tant que Tauren, chasser les rapides rapaces de Mulgore est un rite de passage. Cette épreuve aiguise vos talents de pisteur et perpétue les coutumes ancestrales."},sec={{t="Une épreuve de vision",b="Dans les vastes prairies de Mulgore, les rapaces mettent à l’épreuve l’œil du chasseur. Ces grands oiseaux se fondent dans le ciel et les plaines, tournoyant au-dessus de vous ou rasant les hautes herbes. Ils exigent concentration et célérité, contrairement aux trotteurs patauds ou aux kodos qui paissent. Les jeunes chasseurs les poursuivent pour prouver leur talent et gagner l’estime des tribus."},{t="Insignes de la chasse",b="Harken Totem-de-vent demande des plumes trophées pour enseigner la discipline, pas pour réduire la faune. Les Taurens portent les marques d’une traque difficilement remportée, signes d’ingéniosité et de persévérance. Présenter des plumes intactes aux anciens du village de Sabot-de-Sang prouve qu’un chasseur peut nourrir et défendre la communauté. Des sabots rapides et des sens aiguisés les préparent à affronter le vaste monde."}},faq={{q="Pourquoi Harken Totem-de-vent vous demande-t-il de chasser les rapaces ?",a="Harken Totem-de-vent vous demande de pister les rapaces à travers Mulgore pour mettre à l’épreuve votre ingéniosité, votre vitesse et votre dévouement. Des plumes trophées intactes témoignent de votre talent et vous valent l’estime des Taurens du village de Sabot-de-Sang.",al={"pourquoi chasser les rapaces","but de la quête de harken totem-de-vent","but de la chasse aux rapaces"}},{q="Où trouve-t-on généralement les rapaces ?",a="Les rapaces parcourent les plaines ouvertes de Mulgore, planant au-dessus des herbes ou cherchant leurs proies loin des établissements comme le village de Sabot-de-Sang.",al={"où trouver les rapaces","emplacements des rapaces à mulgore","trouver des rapaces"}},{q="Pourquoi les rapaces sont-ils difficiles à chasser ?",a="Les rapaces sont des prédateurs rapides et vigilants qui sillonnent les plaines. Il vous faut un œil aiguisé pour les repérer et des foulées rapides pour les rattraper avant qu’ils ne s’échappent.",al={"pourquoi les rapaces sont difficiles à attraper","comportement des rapaces"}},{q="Que représentent les plumes trophées pour les Taurens ?",a="Les Plumes de Rapace trophées représentent la patience, une vue perçante et une chasse réussie. Elles montrent que vous avez l’instinct nécessaire pour subvenir aux besoins de la tribu et la protéger.",al={"signification de la plume trophée de rapace","importance des plumes"}},{q="Qui est Harken Totem-de-vent ?",a="Harken Totem-de-vent est un Tauren respecté du village de Sabot-de-Sang. Il observe les nouveaux venus et les chasseurs en devenir, et juge leur débrouillardise au fil d’épreuves traditionnelles dans les plaines.",al={"qui donne la quête chasse aux rapaces","histoire de harken totem-de-vent"}},{q="Cette chasse menace-t-elle l’équilibre naturel de Mulgore ?",a="Les Taurens considèrent la chasse comme un échange sacré avec la Terre-Mère, et non comme un massacre gratuit. Récolter des plumes met leur discipline à l’épreuve et honore des proies rusées, tout en préservant l’équilibre de la tribu.",al={"la chasse aux rapaces est-elle excessive","équilibre des rapaces à mulgore"}}},fx={["0d785fcd"]={q="Pourquoi Harken Totem-de-vent envoie-t-il un étranger plutôt que de chasser les swoops lui-même ?",a="Harken Totem-de-vent ne vous envoie pas parce qu'il est incapable de chasser, mais pour tester votre valeur. Pour les taurens, traquer l'astucieux swoop à travers les plaines demande une vue perçante, de la patience et des sabots rapides. En vous chargeant de rapporter leurs plumes, Harken vous donne l'opportunité de prouver vos compétences et votre détermination au village de Sabot-de-Sang, démontrant que vous êtes un chasseur de véritable mérite.",al={"pourquoi m'envoyer chasser des swoops","pourquoi harken a besoin de moi","pourquoi harken ne peut-il pas chasser les swoops"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem vous trouve un don pour la finesse et vous demande d’entrer dans la mine de KapitalRisk. Il veut que vous preniez des Seaforium Mining Charges dans les chariots d’approvisionnement de la mine.",h="Boarton Shadetotem vous trouve un don pour la finesse et vous demande d’entrer dans la mine de KapitalRisk.",kw={"matériel de dynamitage","boarton shadetotem","masque","mine","seaforium mining charges","finesse","pitons-du-tonnerre","kapitalrisk"},ang={["class:Rogue"]="Boarton pense qu’en tant que voleur, vous avez un don pour la finesse et vous demande d’entrer dans la mine de KapitalRisk."},sec={{t="Une approche subtile",b="Boarton Shadetotem, aux Pitons-du-Tonnerre, pense que vous savez agir avec finesse. Il vous donne un masque et vous demande d’entrer dans la mine de KapitalRisk toute proche. Là, vous devez prendre des Seaforium Mining Charges dans les chariots de matériel de dynamitage et les lui rapporter."}},faq={{q="Qui me demande d’entrer dans la mine ?",a="Boarton Shadetotem, aux Pitons-du-Tonnerre, vous demande d’entrer dans la mine de KapitalRisk.",al={"qui est boarton","boarton shadetotem","qui a donné ceci"}},{q="Que dois-je chercher dans la mine ?",a="On vous demande de prendre des Seaforium Mining Charges dans les chariots de matériel de dynamitage.",al={"quoi voler","matériel de la mine","charges de seaforium"}},{q="Pourquoi Boarton me donne-t-il un masque ?",a="Boarton vous donne un masque pour entrer dans la mine de KapitalRisk toute proche.",al={"masque déguisement","pourquoi le masque","infiltrer la mine"}},{q="Où se trouve la mine de KapitalRisk ?",a="La mine se trouve au sud-est des Pitons-du-Tonnerre.",al={"emplacement de la mine","où est la mine","mine de kapitalrisk"}},{q="À qui prend-on le matériel ?",a="Le matériel se trouve dans la mine de KapitalRisk.",al={"à qui appartient le matériel","matériel de kapitalrisk","mine de la compagnie"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem vous demande de préparer un baume avec des Windfury Cones trouvés au nord des Pitons-du-Tonnerre. Il espère qu’il fera brûler les blessures infligées par une lame d’une douleur cuisante.",h="Boarton Shadetotem vous demande de préparer un baume avec des Windfury Cones trouvés au nord des...",kw={"boarton shadetotem","harpies","mortier et pilon","baume","stalk with the earthmother","pitons-du-tonnerre","windfury cones"},sec={{t="Un baume amer",b="Boarton Shadetotem, aux Pitons-du-Tonnerre, veut un baume venimeux, préparé avec des cônes ramassés près des nids des harpies, au nord. Vous devez écraser les Windfury Cones à l’aide d’un mortier et d’un pilon, puis lui rapporter le résultat. Il vous prévient que le baume terminé peut faire mal même au contact de la peau."}},faq={{q="Qui demande ce baume ?",a="Boarton Shadetotem, aux Pitons-du-Tonnerre, vous demande de préparer un baume à partir de Windfury Cones.",al={"qui veut le baume","demande de boarton shadetotem"}},{q="Où poussent les Windfury Cones ?",a="Les harpies au nord des Pitons-du-Tonnerre nichent dans un arbre qui produit cette résine toxique. Des cônes tombés au sol jonchent les alentours de leurs nids.",al={"où trouver les cônes","emplacement des windfury cone"}},{q="Quel effet le baume est-il censé avoir ?",a="Appliqué sur une lame, le baume est censé faire brûler les blessures d’un adversaire et changer son sang en sel.",al={"effet du baume","baume pour empoisonner une lame"}},{q="Pourquoi Boarton vous met-il en garde contre le contact avec ce baume ?",a="Boarton dit que même un simple contact du baume terminé avec la peau pourrait être douloureux.",al={"avertissement baume sur la peau","le baume est-il dangereux"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="Un ambassadeur du mal",s="Dans les Terres Ingrates, l’historien Karnik vous envoie éliminer l’ambassadeur Infernus. Il veut que vous apportiez la preuve de sa mort au conseiller Belgrum, à Forgefer.",h="Dans les Terres Ingrates, l’historien Karnik vous envoie éliminer l’ambassadeur Infernus.",kw={"conseiller belgrum","ambassadeur infernus","forteresse d'angor","terres ingrates","historien karnik","forgefer","ragnaros","shadowforge","uldaman"},sec={{t="L’ambassadeur à la forteresse d’Angor",b="Ragnaros a envoyé l’ambassadeur Infernus à la forteresse d’Angor pour superviser la quête des Shadowforge à la recherche d’artefacts perdus à Uldaman. Cette recherche a déjà coûté la vie à de nombreux nains, et d’autres meurent encore. Karnik craint que les Shadowforge n’utilisent les artefacts contre Forgefer. Il vous renvoie donc dans les Terres Ingrates pour détruire Infernus et apporter à Belgrum la preuve de votre victoire. Le temps presse. Ragnaros n’attendra pas que les Shadowforge se préparent."},{t="Les remerciements de Belgrum",b="Le conseiller Belgrum loue votre dévouement envers Forgefer et son peuple. Il fera parvenir la nouvelle de votre succès à Karnik, et de l’aide sera envoyée dans les Terres Ingrates pour reprendre le site de fouilles. Au nom du roi Barbe-de-Bronze, Belgrum a encore une requête à vous faire."}},faq={{q="Qui est l’ambassadeur Infernus ?",a="Ragnaros a envoyé Infernus à la forteresse d’Angor pour superviser la quête des Shadowforge à la recherche d’artefacts perdus à Uldaman.",al={"qui est infernus","histoire d’infernus","origines de l’ambassadeur infernus"}},{q="Où se trouve l’ambassadeur Infernus ?",a="L’ambassadeur Infernus se trouve à la forteresse d’Angor, dans les Terres Ingrates.",al={"où trouver l’ambassadeur infernus","emplacement de l’ambassadeur infernus","où est infernus"}},{q="Pourquoi Karnik veut-il que l’ambassadeur Infernus soit éliminé ?",a="La recherche des Shadowforge à Uldaman a déjà coûté la vie à de nombreux nains. Karnik craint qu’ils n’utilisent contre Forgefer les artefacts qu’ils trouveront.",al={"pourquoi éliminer l’ambassadeur infernus","que fait infernus à uldaman","menace contre forgefer dans les terres ingrates"}},{q="Qui donne et clôt cette quête ?",a="L’historien Karnik, à Forgefer, vous envoie éliminer Infernus. Vous apportez la preuve de votre victoire au conseiller Belgrum, à Forgefer.",al={"qui commence un ambassadeur du mal","à qui rendre un ambassadeur du mal","donneur de la quête un ambassadeur du mal"}},{q="Quelle preuve est demandée ?",a="Le conseiller Belgrum veut les bracelets de l’ambassadeur Infernus comme preuve de votre victoire.",al={"que faut-il récupérer sur infernus","preuve de la victoire sur l’ambassadeur infernus","bracelets d’infernus"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem vous demande de lever en filets un Goujon brillant cru aux Pitons-du-Tonnerre. Il espère que cet exercice révélera un talent pour les arts subtils.",h="Boarton Shadetotem vous demande de lever en filets un Goujon brillant cru aux Pitons-du-Tonnerre.",kw={"boarton shadetotem","ensemble de couteaux","goujon brillant cru","stalk with the earthmother","arts subtils","pitons-du-tonnerre"},sec={{t="Une dernière épreuve",b="Boarton Shadetotem, aux Pitons-du-Tonnerre, vous demande de montrer vos aptitudes naturelles avec son Ensemble de couteaux. Apportez-lui un Goujon brillant cru et levez-le en filets devant lui. Il espère que cette épreuve moins directe révélera un talent caché."},{t="Paroles d’adieu",b="Boarton Shadetotem constate que vous n’avez pas la précision de voleur qu’il recherchait. Il vous offre un cadeau d’adieu et vous laisse poursuivre votre route, souhaitant à la Horde des héros comme vous."}},faq={{q="Qui me demande de découper un poisson en filets ?",a="Boarton Shadetotem, aux Pitons-du-Tonnerre, vous demande de lever en filets un Goujon brillant cru avec son Ensemble de couteaux.",al={"qui est boarton","boarton shadetotem","quête poisson couteau"}},{q="Pourquoi Boarton veut-il que je découpe un poisson en filets ?",a="Boarton espère que cet exercice révélera un talent caché pour les arts subtils.",al={"pourquoi découper le poisson en filets","que teste boarton","épreuve du petit poisson"}},{q="Quel poisson Boarton demande-t-il ?",a="Boarton demande un Goujon brillant cru.",al={"quel poisson","petit poisson cru","poisson brillant"}},{q="Où dois-je découper le poisson en filets ?",a="Levez en filets le Goujon brillant cru devant Boarton Shadetotem, aux Pitons-du-Tonnerre.",al={"où effectuer la tâche du poisson","poisson pitons-du-tonnerre","où utiliser l’ensemble de couteaux"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="Les rites de la Terre-mère",s="Au Camp Narache, le Chef Vent-du-faucon vous envoie au-delà de la Mesa de Nuage rouge pour poursuivre les rites de la Terre-mère. Après les premières épreuves, vous portez un totem sculpté vers le nord, jusqu’au village de Sabot-de-Sang et à Baine Sabot-de-Sang.",h="Au Camp Narache, le Chef Vent-du-faucon vous envoie au-delà de la Mesa de Nuage rouge pour poursuivre les...",kw={"baine sabot-de-sang","sabot-de-sang","cairne sabot-de-sang","camp narache","chef vent-du-faucon","mulgore","les rites de la terre-mère","totem de vent-du-faucon"},ang={["faction:Horde"]="En tant que membre de la Horde, vous prenez part à des traditions qui renforcent l’unité tribale dans tout Mulgore et préparent de nouveaux défenseurs en leur donnant vaillance guerrière et ancrage spirituel.",["race:Tauren"]="En tant que jeune tauren, vous suivez la voie de la Terre-mère pour prouver votre valeur aux anciens et trouver votre place parmi les tribus unies."},sec={{t="Quitter la mesa",b="Depuis des générations, les jeunes taurens mettent leur force à l’épreuve au Camp Narache, sur la Mesa de Nuage rouge. Les premières épreuves enseignent la discipline et la détermination. Pourtant, les sacrés rites de la Terre-mère ne se limitent pas à survivre à la faune de la mesa. Le Chef Vent-du-faucon sait quand un initié est prêt à quitter les terrains de chasse abrités et à rejoindre la communauté élargie."},{t="Un gage pour Baine",b="Le Chef Vent-du-faucon vous remet un totem sculpté à la main, qui vous servira de recommandation sur la route de Narache aux colonies centrales. Portez-le sur le sentier sinueux jusqu’au village de Sabot-de-Sang et présentez-vous à Baine Sabot-de-Sang, le jeune chef du village et fils du grand chef Cairne Sabot-de-Sang. Le totem est votre titre de recommandation et votre sceau d’approbation. Il montre que vous êtes prêt pour les rites de l’esprit et de la sagesse qui vous attendent."}},faq={{q="Quel est le but de cette quête ?",a="Les rites vous mènent du Camp Narache jusqu’à la communauté tauren élargie du village de Sabot-de-Sang, où commencent les prochaines épreuves.",al={"pourquoi les rites de la terre-mère","but de cette quête","objectif de la quête"}},{q="Qui est Baine Sabot-de-Sang ?",a="Baine Sabot-de-Sang est le fils du grand chef Cairne Sabot-de-Sang et le jeune chef du village de Sabot-de-Sang. Il supervise les épreuves spirituelles et martiales des jeunes taurens.",al={"qui est baine","histoire de baine","fils de cairne"}},{q="Qu’est-ce que le Totem de Vent-du-faucon ?",a="Le Totem de Vent-du-faucon est un gage en bois sculpté à la main par le Chef Vent-du-faucon du Camp Narache. C’est un titre de recommandation officiel et un sceau d’approbation, qui montre à Baine Sabot-de-Sang que Vent-du-faucon vous accorde sa bénédiction pour entreprendre d’autres rites.",al={"totem de vent-du-faucon","totem sculpté"}},{q="Quels rites viennent ensuite ?",a="Au village de Sabot-de-Sang, Baine vous confie le Rite de Vision. Celui-ci met à l’épreuve votre lien spirituel au moyen de visions ancestrales sacrées.",al={"rites suivants","que se passe-t-il ensuite","quête suivante"}},{q="Où se trouve le village de Sabot-de-Sang ?",a="Le village de Sabot-de-Sang se trouve au nord du Camp Narache, sur les rives du lac Taureau-de-pierre, dans le centre de Mulgore. Suivez la route principale qui descend de la mesa, puis prenez vers le nord.",al={"où se trouve le village de sabot-de-sang","comment trouver le village de sabot-de-sang","chemin vers sabot-de-sang"}},{q="Pourquoi faut-il accomplir les rites de la Terre-mère ?",a="Les rites de la Terre-mère sont des traditions taurens sacrées. Réussir leurs différentes étapes prouve votre force physique, votre lien spirituel et votre sagesse, et vous vaut la reconnaissance des anciens des Pitons-du-Tonnerre.",al={"pourquoi les rites de la terre-mère","but des épreuves taurens","histoire des rites de la terre-mère"}}},fx={["4a33bb81"]={q="Pourquoi le Chef Vent-du-faucon vous envoie-t-il au village de Sabot-de-Sang ?",a="Le Chef Vent-du-faucon vous a guidé à travers les épreuves d'initiation de la Mesa de Nuage rouge, mais le Camp Narache ne peut rien vous apprendre de plus. Pour terminer les Rites of the Earthmother sacrés et obtenir l'acceptation des anciens des Pitons-du-Tonnerre, vous devez élargir votre expérience dans les plaines plus vastes du Mulgore. En vous envoyant vers Baine Sabot-de-Sang avec son totem sculpté, Vent-du-faucon transfère la responsabilité de votre croissance spirituelle et physique à un chef qui peut tester votre préparation à la véritable vie adulte.",al={"pourquoi envoyer au village bloodhoof","motif du chef vent-du-faucon","pourquoi les rites of the earthmother"}},["9c980781"]={q="Pourquoi devez-vous livrer le totem vous-même ?",a="Ce voyage n'est pas une simple commission, mais une partie intégrante de votre rite de passage. Sortir des limites protégées de la Mesa de Nuage rouge et suivre la route ouverte dans le Mulgore prouve votre indépendance et votre endurance. Livrer le Totem de Vent-du-faucon de vos propres mains permet à Baine Sabot-de-Sang de vous observer, de reconnaître la recommandation personnelle de Vent-du-faucon sculptée dans le bois, et de juger votre caractère de première main.",al={"pourquoi je prends le totem","pourquoi vent-du-faucon ne peut-il pas envoyer un messager","pourquoi moi pour les rites of the earthmother"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="La KapitalRisk",s="Dans les collines orientales de Mulgore, des gobelins creusent malgré le refus des taurens. La KapitalRisk les amène en force pour extraire le sol de la Terre-Mère, et Morin Traqueur-de-nuage réclame une réponse létale.",h="Dans les collines orientales de Mulgore, des gobelins creusent malgré le refus des taurens.",kw={"gobelin","droits miniers","morin traqueur-de-nuage","mulgore","caravane dévastée","kapitalrisk","mine de la kapitalrisk"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez à défendre Mulgore contre l’exploitation commerciale et à protéger le peuple de Cairne Sabot-de-Sang, qui sécurise sa nouvelle patrie.",["profession:Mining"]="La KapitalRisk exploite la mine par la force brute, bâcle le travail et déstabilise les terres sans se soucier de leur équilibre naturel ni des pratiques minières sûres.",["race:Tauren"]="Pour les taurens, la Terre-Mère est sacrée. Les activités minières de la KapitalRisk profanent leur terre ancestrale, et ils entendent chasser les gobelins par la force."},sec={{t="Une intrusion industrielle",b="Les taurens honorent Mulgore, qu’ils considèrent comme une partie de la Terre-Mère. Ils apprécient ses vastes plaines et l’équilibre de sa faune. Lorsque la KapitalRisk demande à dynamiter et à excaver les collines pour en extraire du minerai, les tribus refusent. La compagnie les ignore et amène machines, ouvriers et contremaîtres dans les crêtes orientales pour y miner sans permission."},{t="Un message sans équivoque",b="Morin Traqueur-de-nuage et les autres éclaireurs taurens ne voient pas l’intérêt de poursuivre les pourparlers une fois l’extraction commencée. Des documents trouvés dans une caravane dévastée de la KapitalRisk confirment l’opération. Morin vous envoie contre les contremaîtres qui font claquer les fouets et les ouvriers qui actionnent les foreuses. Il entend faire payer cher à la compagnie son intrusion."}},faq={{q="Pourquoi la KapitalRisk est-elle à Mulgore ?",a="La KapitalRisk creuse dans les collines orientales de Mulgore pour en extraire du minerai et d’autres ressources. Les taurens ont refusé sa demande de droits miniers, mais la compagnie a tout de même lancé ses opérations.",al={"pourquoi des gobelins sont-ils à mulgore","motif de la kapitalrisk à mulgore","que veut la kapitalrisk"}},{q="Qui a donné l’ordre d’attaquer les mineurs ?",a="Morin Traqueur-de-nuage donne l’ordre. En surveillant les environs de Sabot-de-Sang, il voit dans le refus de la compagnie d’accepter la décision des taurens une violation qui appelle la force.",al={"qui donne cette quête","rôle de morin traqueur-de-nuage","donneur de quête"}},{q="Où se trouve la mine de la KapitalRisk ?",a="La mine principale, Venture Company Mine, se trouve dans les contreforts à l’est de la Caravane dévastée et de Sabot-de-Sang. Le personnel de la compagnie se rassemble aussi dans un petit avant-poste, sur les falaises au nord-est des ascenseurs nord des Pitons-du-Tonnerre.",al={"emplacement de la mine de la kapitalrisk","où sont les contremaîtres","où trouver la kapitalrisk"}},{q="Les taurens ont-ils tenté de négocier avec les gobelins ?",a="Oui. La KapitalRisk a demandé aux taurens des droits miniers à Mulgore, et les chefs tribaux ont refusé qu’elle exploite à ciel ouvert leurs terres ancestrales. Les gobelins ont tout de même creusé sans permission.",al={"les taurens ont-ils autorisé l’extraction minière","droits miniers à mulgore","les gobelins ont-ils demandé la permission"}},{q="Ces gobelins font-ils partie du Cartel Gentepression ?",a="Non. La KapitalRisk est un cartel industriel indépendant et prédateur, distinct des groupes commerciaux neutres comme le Cartel Gentepression. Elle entretient des relations hostiles avec les populations locales partout où elle exploite des ressources.",al={"ces gobelins sont-ils ceux de cabestan","la kapitalrisk est-elle amicale","faction de la kapitalrisk"}},{q="Quel est le lien avec les caravanes dévastées ?",a="La caravane dévastée était un convoi de la KapitalRisk détruit par les taurens. Les caisses et les documents de sa division minière ont révélé les opérations de la compagnie à Mulgore, ce qui a entraîné l’attaque de sa mine.",al={"lien avec la caravane","la kapitalrisk a-t-elle attaqué les caravanes","lien avec la caravane dévastée"}}},fx={f6df914e={q="Pourquoi Morin Traqueur-de-nuage veut-il que la The Venture Co. soit attaquée ?",a="La KapitalRisk s'est officiellement vu refuser des droits miniers en Mulgore, pourtant ils ont ignoré ce refus et ont commencé à installer de l'équipement et des travailleurs malgré tout. Morin Traqueur-de-nuage ne peut pas leur permettre de saccager la terre et de piller ses ressources naturelles sans contrôle. Comme la diplomatie et les refus catégoriques n'ont pas réussi à infléchir leur cupidité, il pense que les taurens doivent délivrer un message clair et brutal : l'intrusion et le vol ne seront pas tolérés.",al={"motif de morin traqueur-de-nuage","pourquoi attaquer la kapitalrisk","pourquoi morin veut-il tuer la kapitalrisk"}},eda5096c={q="Qui êtes-vous envoyé combattre à la mine ?",a="Vous êtes envoyé contre les superviseurs et les travailleurs de la KapitalRisk stationnés dans leur opération minière à l'est du Mulgore. Ces gobelins et ouvriers embauchés creusent profondément dans les collines sacrées pour dépouiller la terre de ses minerais sans la permission de la tribu, dirigés par des contremaîtres guidés par le profit qui imposent l'expansion agressive et illicite de la compagnie.",al={"cibles de quête de la kapitalrisk","qui sont les travailleurs de la kapitalrisk","qui je combats dans la mine"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="Le superviseur Vibrouage",s="À Mulgore, Morin Traqueur-de-nuage demande de l’aide contre la mine de la KapitalRisk. Des documents de la Caravane dévastée révèlent un plan pour chasser les taurens de leur terre natale. Morin a besoin du calepin du superviseur Vibrouage.",h="À Mulgore, Morin Traqueur-de-nuage demande de l’aide contre la mine de la KapitalRisk.",kw={"calepin","vibrouage","mine","morin traqueur-de-nuage","mulgore","superviseur","kapitalrisk"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez les taurens à résister à l’avancée de la KapitalRisk. Vous défendez les terres ancestrales de la Horde en Kalimdor.",["race:Tauren"]="En tant que tauren, vous défendez votre peuple et vos terres en frappant Vibrouage. Son entreprise projette de chasser votre tribu de Mulgore et de piller ses richesses souterraines."},sec={{t="Un complot contre les plaines",b="Une caravane de la KapitalRisk a été détruite, et ses documents révèlent un plan pour chasser les taurens de Mulgore. L’entreprise veut s’approprier les plaines et les filons qui se trouvent sous leurs pieds. Elle compte prendre leurs ressources sans que les taurens ne lui fassent obstacle."},{t="Frappez le contremaître",b="Morin Traqueur-de-nuage envoie des champions à la mine de la KapitalRisk, à l’est de la Caravane dévastée. Le superviseur Vibrouage dirige la mine au fond de ses tunnels de droite, parmi les ouvriers et les sous-chefs. Morin veut récupérer son calepin pour découvrir ce qu’il pourrait révéler sur les prochains projets de l’entreprise."}},faq={{q="Qui est le superviseur Vibrouage ?",a="Le superviseur Vibrouage dirige les opérations de la KapitalRisk dans sa mine, à l’est de Mulgore. Il supervise les ouvriers qui creusent la terre et met en œuvre les projets de l’entreprise dans la région.",al={"vibrouage","qui est vibrouage","histoire de vibrouage"}},{q="Pourquoi Morin Traqueur-de-nuage veut-il tuer le superviseur Vibrouage ?",a="Des documents retrouvés dans une caravane pillée révèlent que la KapitalRisk projette de chasser les taurens de Mulgore pour s’enrichir. Morin Traqueur-de-nuage veut tuer le superviseur Vibrouage, car il dirige ces manœuvres.",al={"pourquoi tuer vibrouage","motivation de morin traqueur-de-nuage"}},{q="Où se trouve le superviseur Vibrouage ?",a="Vibrouage se trouve dans la mine de la KapitalRisk, à l’est de la Caravane dévastée, à Mulgore. Suivez le tunnel de droite jusqu’à une salle où se trouvent des ouvriers et des superviseurs.",al={"où se trouve vibrouage","emplacement de la mine de vibrouage","carte de vibrouage"}},{q="Quelle preuve Morin demande-t-il pour confirmer la défaite du superviseur Vibrouage ?",a="Morin Traqueur-de-nuage veut récupérer le calepin personnel de Vibrouage. Ses notes pourraient révéler les projets de la KapitalRisk à Mulgore.",al={"preuve de la mort","calepin de vibrouage"}},{q="Pourquoi la KapitalRisk est-elle à Mulgore ?",a="La KapitalRisk est à Mulgore pour exploiter son bois, ses minerais et ses richesses souterraines. Elle ne tient pas compte des habitants ni des terres qu’elle s’approprie.",al={"kapitalrisk à mulgore","pourquoi les gobelins sont-ils à mulgore"}},{q="La mort de Vibrouage chassera-t-elle complètement la KapitalRisk ?",a="Non. La mort de Vibrouage perturbe le commandement local et permet à Morin Traqueur-de-nuage d’obtenir des notes sur les projets de l’entreprise. La KapitalRisk reste une menace dans les collines de Mulgore.",al={"la kapitalrisk est-elle partie","après la mort de vibrouage"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="Mazzranache",s="À Sabot-de-Sang, la morsure de Mazzranache plonge Maur Mande-pluie dans la fièvre et le laisse proche de la mort. Une génération plus tôt, le trotteur des plaines hantait les récits de son grand-père. À présent, Maur subit des cauchemars délirants tandis que le venin menace sa vie.",h="À Sabot-de-Sang, la morsure de Mazzranache plonge Maur Mande-pluie dans la fièvre et le laisse proche de la...",kw={"sabot-de-sang","puma des basses plaines","maur mande-pluie","mazzranache","mulgore","trotteur des plaines","loup des prairies","rapace"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez lire les plaines en suivant les traces des loups des prairies, des pumas, des trotteurs des plaines et des Rapaces à travers Mulgore.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger Sabot-de-Sang des dangers de Mulgore et à préserver la paix et la stabilité du foyer des taurens.",["race:Tauren"]="En tant que tauren, vous voyez dans le remède de Maur une pratique ancienne : tirer des remèdes de la flore et de la faune de la Mère-Terre."},sec={{t="Un héritage des plaines",b="Maur Mande-pluie ne connaissait Mazzranache qu'à travers les récits de son grand-père. Le vieux tauren parlait d'un trotteur des plaines sauvage, aux yeux rouges luisants, aux serres acérées comme des rasoirs et à la morsure toxique, différente de celle de la plupart des créatures de Mulgore. Puis Maur croisa la bête dans les vastes prairies. L'avertissement de son grand-père se confirma, et la morsure le laissa grièvement blessé tandis qu'il tentait de rejoindre un lieu sûr."},{t="À la course contre l'infection",b="Le venin de Mazzranache donne à Maur une forte fièvre et provoque un délire cauchemardesque. Il lui faut un remède avant que l'infection ne devienne mortelle. La médecine traditionnelle tauren puise dans la vitalité des bêtes locales. Maur a donc besoin d'un Cœur de loup des prairies, d'un Fémur de puma des basses plaines, d'une Écaille de trotteur des plaines et d'un Gésier de Rapace. Ces éléments réunis permettent de préparer une décoction qui enrayera la propagation de la nécrose et l'aidera à retrouver la santé."}},faq={{q="Qu'est-ce que Mazzranache ?",a="Dans les prairies de Mulgore, Mazzranache est un trotteur des plaines sauvage. Son plumage éclatant, ses yeux rouges démoniaques, ses serres redoutables et sa morsure venimeuse terrorisent les voyageurs depuis des générations.",al={"qui est mazzranache","quelle bête est mazzranache","histoire de mazzranache"}},{q="Qui est Maur Mande-pluie ?",a="Maur Mande-pluie vit à Sabot-de-Sang. Mazzranache l'a pris en embuscade et lui a mordu l'épaule alors qu'il traversait Mulgore, le clouant au lit avec une infection qui menace sa vie.",al={"maur mande-pluie","qui m'a donné cette quête","qui est le tauren malade"}},{q="Pourquoi Maur a-t-il besoin d'éléments de quatre bêtes différentes ?",a="Les remèdes tauren puisent dans les forces et les essences spirituelles des animaux des plaines pour contrer les toxines puissantes. Un cœur de loup, la moelle d'un fémur de puma, une écaille de trotteur des plaines et un gésier de Rapace forment ensemble un antidote assez puissant pour combattre le venin de Mazzranache.",al={"pourquoi un cœur de loup et un fémur de puma","pourquoi des ingrédients animaux","ingrédients du remède contre mazzranache"}},{q="Le grand-père de Maur a-t-il tué Mazzranache ?",a="Non. Le grand-père de Maur a combattu Mazzranache il y a des années, mais n'a pas pu vaincre le féroce trotteur des plaines. Il a survécu et a averti ses descendants de ses couleurs vives et de ses attaques brutales.",al={"le grand-père a-t-il vaincu mazzranache","grand-père de maur et mazzranache","qui a déjà combattu mazzranache"}},{q="Cette quête me demande-t-elle de traquer Mazzranache ?",a="Non. Maur doit survivre à la fièvre ; il faut donc avant tout rassembler les éléments nécessaires à son remède.",al={"dois-je tuer mazzranache","où se trouve mazzranache","chasser mazzranache"}},{q="Où se trouve Sabot-de-Sang ?",a="Sabot-de-Sang se trouve au centre de Mulgore, au sud des Pitons-du-Tonnerre et à l'est du Lac Taureau-de-pierre. Les jeunes braves taurens partent de ce village pour parcourir les plaines.",al={"où se trouve sabot-de-sang","emplacement de sabot-de-sang"}}},fx={["3b88d77e"]={q="Pourquoi Maur Mande-pluie veut-il que cela soit fait ?",a="La vie de Maur est directement en danger. En voyageant dans les plaines du Mulgore, il a croisé Mazzranache, un autruche légendaire qui, selon la rumeur, terrorisait son grand-père. La créature a infligé une morsure sauvage et venimeuse à l'épaule de Maur. Une fièvre débilitante s'est installée, provoquant des cauchemars délirants et se propageant régulièrement dans tout son corps. Sans les ingrédients animaux nécessaires pour préparer un remède médicinal, l'infection galopante le tuera bientôt.",al={"motif de maur mande-pluie","pourquoi aider maur mande-pluie","ce qui est arrivé à maur"}},ce37bf7e={q="Pourquoi Maur a-t-il besoin d'un étranger au lieu de se soigner lui-même ?",a="Maur est trop gravement blessé et fiévreux pour chasser lui-même les bêtes du Mulgore. La morsure venimeuse de Mazzranache l'a rendu incapable, avec délire et épuisement, le confinant au village de Sabot-de-Sang. Alors que le temps presse avant que l'infection ne devienne fatale, il doit compter sur les voyageurs de passage pour traquer les couguars, les swoops, les loups et les autruches rapides nécessaires à son remède.",al={"pourquoi maur ne peut-il pas obtenir les pièces","pourquoi maur a besoin de vous","pourquoi moi pour mazzranache"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="Le rite de vision",s="Baine Sabot-de-Sang envoie des voyageurs à travers Mulgore chercher Zarlman Deux-Lunes avant Le rite de vision. Cette épreuve fait partie des Rites of the Earthmother, et les anciens des hauteurs de Pitons-du-Tonnerre y voient un signe de préparation spirituelle.",h="Baine Sabot-de-Sang envoie des voyageurs à travers Mulgore chercher Zarlman Deux-Lunes avant Le rite de...",kw={"baine sabot-de-sang","sabot-de-sang","mulgore","le rite de vision","rites of the earthmother","épreuve tauren","pitons-du-tonnerre","zarlman deux-lunes"},ang={["class:Druid"]="En tant que druide, communier avec les visions de la Terre-mère approfondit votre vocation à entendre la sagesse et les murmures du monde vivant.",["class:Shaman"]="En tant que chaman, chercher Zarlman Deux-Lunes et suivre la voie des visions témoigne de votre devoir de concilier les affaires du monde et la volonté des ancêtres.",["faction:Horde"]="En tant que membre de la Horde, accomplir ces traditions sacrées témoigne de votre loyauté et de votre respect envers les anciens taurens qui aident à guider la Horde.",["race:Tauren"]="En tant que tauren, vous franchissez une étape culturelle essentielle avec le rite de vision. Il marque votre progression vers le rôle de défenseur de confiance et de marcheur des esprits des tribus."},sec={{t="Une pierre sacrée",b="Depuis des générations, les taurens nomades suivent les conseils de la Terre-mère à travers les plaines de Kalimdor. Ils se sont désormais rassemblés à l’abri des frontières de Mulgore, où les traditions spirituelles restent au cœur de leur société. Les épreuves précédentes testent la force d’un initié et son lien avec la chasse. Le rite de vision invite à l’introspection les jeunes taurens et leurs alliés honorés, qui communient avec les esprits."},{t="Les conseils du voyant",b="Avant de chercher une vision, un initié a besoin d’être guidé dans les voies anciennes. À Sabot-de-Sang, le chaman vénéré Zarlman Deux-Lunes lui offre ses conseils. Baine Sabot-de-Sang confie les voyageurs à ses soins. Zarlman reconnaît ceux qui suivent la voie des ancêtres, puis leur transmet les premiers rites et les préparatifs sacrés pour voir au-delà du monde physique."}},faq={{q="Qu’est-ce que le rite de vision ?",a="Le rite de vision est un rite sacré de la Terre-mère. Il ouvre la perception spirituelle des aventuriers et leur permet de communier avec les esprits ancestraux, montrant ainsi aux anciens de Pitons-du-Tonnerre qu’ils sont prêts spirituellement.",al={"quête du rite de vision","qu’est-ce que le rite de vision","histoire du rite de vision"}},{q="Qui donne cette quête ?",a="Baine Sabot-de-Sang envoie les voyageurs accomplir le rite de vision. Fils du grand chef Cairne Sabot-de-Sang, il veille sur Sabot-de-Sang et dirige les voyageurs dignes de confiance vers les anciens spirituels du village.",al={"qui donne le rite de vision","donneur de quête du rite de vision"}},{q="Qui est Zarlman Deux-Lunes ?",a="Zarlman Deux-Lunes est un chaman tauren expérimenté et le guide spirituel de Sabot-de-Sang. Il prépare les voyageurs et les initiés aux épreuves sacrées comme le rite de vision.",al={"qui est zarlman","histoire de zarlman deux-lunes"}},{q="Pourquoi les Rites of the Earthmother sont-ils importants pour les taurens ?",a="Les Rites of the Earthmother marquent le passage traditionnel des taurens à l’âge adulte. Les accomplir prouve leur aptitude physique, leur harmonie spirituelle et leur respect durable de la terre, ce qui leur vaut l’estime des grands anciens.",al={"sens des rites de la terre-mère","pourquoi accomplir les rites de la terre-mère"}},{q="Les non-taurens peuvent-ils accomplir le rite de vision ?",a="Oui. Les alliés de la Horde de passage à Mulgore peuvent suivre la voie de la Terre-mère s’ils gagnent la confiance de la tribu Sabot-de-Sang. Ils honorent les traditions taurens et espèrent gagner la faveur des anciens.",al={"les orcs peuvent-ils accomplir le rite de vision","non-taurens et terre-mère"}},{q="Où se déroule cette épreuve ?",a="L’épreuve commence à Sabot-de-Sang, près des rives du lac Taureau-de-pierre, au centre de Mulgore. Le village se trouve au sud de Pitons-du-Tonnerre.",al={"où se trouve le rite de vision","lieu du rite de vision"}}},fx={["1fa313da"]={q="Pourquoi Baine Sabot-de-Sang veut-il que vous entrepreniez le Rite of Vision ?",a="Baine Sabot-de-Sang vous prépare à suivre le chemin de vos ancêtres et à prouver votre valeur au peuple tauren. Alors que vous atteignez l'âge adulte en Mulgore, vous devez entreprendre les Rites of the Earthmother sacrés pour communier avec les esprits, apprendre la révérence pour la terre, et finalement gagner le respect des anciens des Pitons-du-Tonnerre. Baine vous dirige vers le mystique du village, Zarlman Deux-Lunes, afin que vous puissiez commencer correctement l'épreuve spirituelle.",al={"pourquoi baine vous envoie-t-il au rite of vision","motif de baine sabot-de-sang pour le rite of vision","pourquoi faire le rite of vision"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="La chasse aux peaux",s="À Pitons-du-Tonnerre, Veren Tallstrider demande aux chasseurs d’apporter du Cuir léger pour la capitale. Il échange des objets fabriqués contre les peaux, selon la tradition tauren qui consiste à confectionner vêtements et armures avec le gibier des plaines.",h="À Pitons-du-Tonnerre, Veren Tallstrider demande aux chasseurs d’apporter du Cuir léger pour la capitale.",kw={"la chasse aux peaux","travail du cuir","cuir léger","mulgore","chasse des tauren","pitons-du-tonnerre","veren tallstrider"},ang={["class:Hunter"]="En tant que chasseur, vous êtes bien placé pour suivre le gibier dans les plaines de Mulgore et rassembler les peaux légères dont Veren a besoin.",["faction:Horde"]="En tant que membre de la Horde, vous approvisionnez les artisans de Pitons-du-Tonnerre tandis que la jeune capitale renforce ses défenses et ses réseaux commerciaux.",["race:Tauren"]="En tant que chasseur tauren, vous honorez une bête abattue en transformant sa peau en objets utiles. Cette discipline se transmet de génération en génération."},sec={{t="Faire vivre Pitons-du-Tonnerre",b="Pitons-du-Tonnerre a besoin d’artisans qualifiés pour confectionner des vêtements et des armures destinés à sa population grandissante. Veren Tallstrider transforme les peaux en objets utiles et demande aux jeunes chasseurs de lui rapporter leur gibier au retour des plaines. Leurs chasses approvisionnent la capitale et nourrissent la tribu."},{t="La voie de la chasse",b="Les Tauren chassent dans les prairies pour nourrir, vêtir et abriter la tribu. Veren Tallstrider demande aux chasseurs qui souhaitent honorer leur clan de rapporter du Cuir léger prélevé sur la faune locale. En échange, il troque des objets fabriqués contre douze peaux bien entretenues, contribuant ainsi aux liens qui unissent la société tauren."}},faq={{q="Qui est Veren Tallstrider ?",a="Veren Tallstrider est un travailleur du cuir à Pitons-du-Tonnerre. Il confectionne vêtements et armures pour les Tauren et échange son ouvrage contre les peaux des plaines.",al={"veren tallstrider","qui donne la chasse aux peaux","donneur de quête pour les peaux à pitons-du-tonnerre"}},{q="De quoi Veren Tallstrider a-t-il besoin ?",a="Veren a besoin de douze pièces de Cuir léger provenant de bêtes de Mulgore et des territoires voisins. Il se sert des peaux pour confectionner des objets destinés à Pitons-du-Tonnerre.",al={"conditions de la chasse aux peaux","quoi apporter à veren","matériaux pour la chasse aux peaux"}},{q="Où se déroule cette quête ?",a="Vous rencontrez Veren Tallstrider au sommet de Pitons-du-Tonnerre. Pour lui apporter ce dont il a besoin, chassez les bêtes sauvages dans les prairies en contrebas.",al={"où se trouve veren tallstrider","lieu de la chasse aux peaux"}},{q="Pourquoi les Tauren accordent-ils tant d’importance à la chasse aux bêtes ?",a="La chasse des Tauren honore l’équilibre avec Earth Mother. La tribu utilise chaque partie d’une bête abattue : sa chair pour se nourrir, ses os et ses peaux tannées pour fabriquer outils, tentes et armures.",al={"culture de la chasse chez les tauren","pourquoi chasser pour obtenir des peaux","traditions taurens du travail du cuir"}},{q="Tout aventurier de la Horde peut-il accomplir cette tâche ?",a="Oui. Tout voyageur fidèle à la Horde peut aider à rassembler des peaux si Veren pense qu’il est prêt à éprouver sa valeur dans les plaines.",al={"qui peut faire la chasse aux peaux","la chasse aux peaux est-elle réservée à la horde"}},{q="Que se passe-t-il une fois les peaux livrées ?",a="Après que vous lui avez remis les peaux, Veren en vérifie la qualité et salue votre travail. Il vous remet une pièce d’équipement fabriquée en échange équitable.",al={"remise des peaux","récompense de veren tallstrider"}}},fx={["1249c214"]={q="Pourquoi Veren Tallstrider veut-il du Cuir léger ?",a="Veren Tallstrider est un travailleur du cuir qui fabrique des vêtements et des armures pour les habitants des Pitons-du-Tonnerre. Pour approvisionner la ville et soutenir son art, il compte sur les chasseurs pour lui apporter des peaux de qualité provenant des plaines du Mulgore.",al={"pourquoi veren a besoin de cuir","motif de veren tallstrider","pourquoi du cuir léger pour veren"}},cd30155e={q="À quoi sert le Cuir léger ?",a="Le cuir est transformé en vêtements essentiels, en armures protectrices et en biens utiles pour les taurens vivant en haut des mesas des Pitons-du-Tonnerre, ainsi qu'en équipement façonné en échange pour les chasseurs itinérants.",al={"à quoi sert le cuir léger","utilisation du cuir léger","comment veren utilise-t-il le cuir léger"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="Sac en cuir de kodo",s="Veren Tallstrider enseigne aux apprentis travailleurs du cuir de Pitons-du-Tonnerre un artisanat inspiré des plaines. Il demande du cuir léger tanné et du fil résistant.",h="Veren Tallstrider enseigne aux apprentis travailleurs du cuir de Pitons-du-Tonnerre un artisanat inspiré des...",kw={"bobine de fil grossier","kodo","sac en cuir de kodo","travail du cuir","cuir léger","mulgore","pitons-du-tonnerre","veren tallstrider"},ang={["faction:Horde"]="En tant que membre de la Horde, vous comptez sur les artisans de Pitons-du-Tonnerre pour fournir aux chasseurs, éclaireurs et guerriers l'équipement dont ils ont besoin dans le centre de Kalimdor.",["race:Tauren"]="En tant que Shu'halo, vous honorez les dons de la Terre-Mère et préservez les traditions ancestrales en apprenant à fabriquer de l'équipement fiable avec le puissant kodo."},sec={{t="Une leçon sur la mesa",b="Veren Tallstrider enseigne le travail du cuir sur les hauteurs artisanales de Pitons-du-Tonnerre. Il perpétue la tradition nomade qui consiste à ne rien gaspiller des prises de chasse. Apportez du cuir léger tanné et du fil résistant, et il vous enseignera son art. Grâce à ces matériaux de base, les apprentis montrent qu'ils savent fabriquer des articles capables de transporter l'équipement de survie à travers les étendues sauvages de Kalimdor."},{t="L'esprit du kodo",b="Pour les taurens, le kodo est un symbole d'endurance, de force et de détermination. Son cuir épais protège des ronces, des vents mordants et des griffes des bêtes. Fabriquer des sacs et des vêtements en cuir de kodo est un travail utile qui rend hommage à l'animal ayant nourri et porté les Shu'halo à travers les plaines de Mulgore pendant des générations."}},faq={{q="Qui propose la quête Sac en cuir de kodo ?",a="Veren Tallstrider, un entraîneur tauren de travail du cuir et marchand à Pitons-du-Tonnerre, propose cette formation.",al={"donneur de quête","où trouver la quête sac en cuir de kodo","emplacement de veren tallstrider"}},{q="Qui peut accomplir cette tâche ?",a="Les travailleurs du cuir ayant atteint au moins le niveau dix en apprentissage peuvent recevoir cette formation de Veren Tallstrider.",al={"qui peut prendre cette quête","conditions de la quête","condition de métier"}},{q="Quels matériaux Veren Tallstrider demande-t-il ?",a="Veren Tallstrider demande quatre pièces de Cuir léger et quatre Bobines de fil grossier pour réapprovisionner ses fournitures avant de vous transmettre son patron.",al={"quels objets faut-il","matériaux du sac en cuir de kodo","objets à remettre pour la quête"}},{q="Pourquoi le cuir de kodo est-il important pour les artisans taurens ?",a="Les kodos incarnent la résilience et la force physique, des qualités chères aux taurens. L'équipement fabriqué avec leur cuir honore l'esprit de l'animal et équipe les voyageurs qui traversent les plaines.",al={"pourquoi le cuir de kodo","signification du kodo chez les taurens","importance du kodo"}},{q="Qu'enseigne Veren Tallstrider une fois la quête terminée ?",a="Après avoir reçu les fournitures, Veren enseigne à l'artisan comment coudre un Sac en cuir de kodo.",al={"récompense de quête","qu'est-ce que je reçois","patron de sac"}},{q="Où trouver les matériaux nécessaires ?",a="Vous pouvez dépecer des bêtes de bas niveau dans tout Mulgore et les terres voisines pour obtenir du Cuir léger. Les marchands de fournitures et de couture vendent des Bobines de fil grossier.",al={"où trouver du cuir léger","où trouver du fil grossier"}}},fx={c94273ea={q="Pourquoi Veren Tallstrider veut-il que cela soit fait ?",a="Veren Tallstrider est fier de former la prochaine génération de travailleurs du cuir taurens. Les kodos du Mulgore sont vénérés pour leur force et leur endurance, et fabriquer un sac traditionnel à partir de leurs peaux est une compétence fondamentale. En vous demandant de rassembler des matériaux de travail pour son commerce, Veren teste votre dévouement et votre ingéniosité avant de transmettre les techniques du métier.",al={"pourquoi veren tallstrider veut-il du cuir","motif de veren tallstrider","pourquoi la quête du sac en peau de kodo"}},["1f62e959"]={q="À quoi sert le Cuir léger ?",a="Le Cuir léger sert d'approvisionnement commercial fondamental dont Veren Tallstrider a besoin en échange de son enseignement. Travailler des peaux tannées est au cœur de l'artisanat du cuir tauren, et fournir du cuir de qualité prouve que vous avez maîtrisé les bases du traitement des peaux d'animaux avant d'apprendre à coudre des contenants spécialisés comme les sacs en peau de kodo.",al={"à quoi sert le cuir léger","pourquoi apporter du cuir léger","but du cuir léger"}},["7d0f7d7f"]={q="À quoi sert la Bobine de fil grossier ?",a="La Bobine de fil grossier est un élément essentiel de la couture et du travail du cuir utilisé pour lier ensemble des peaux épaisses. Pour construire des sacs durables capables de supporter les plaines du Mulgore, un artisan a besoin de cordage solide qui ne cassera pas sous une forte tension ou par mauvais temps.",al={"pourquoi une bobine de fil grossier","but de la bobine de fil grossier","à quoi sert la bobine de fil grossier"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="Une situation délicate",s="Dran Droffers recherche l’emballage d’origine de la Houle au miel des Hinterlands. Gilveradin Sunchaser le possède et demande deux bouteilles supplémentaires. Dix bouteilles attendent dans des caisses autour de la base abandonnée de la Horde, près du Rocher de l’Affût.",h="Dran Droffers recherche l’emballage d’origine de la Houle au miel des Hinterlands.",kw={"dran droffers","gilveradin sunchaser","hinterlands","houle au miel des hinterlands","limons","rocher de l'affût","gelées"},sec={{t="Une question d’emballage",b="Dran Droffers recherche la Houle au miel des Hinterlands, et Gilveradin Sunchaser possède son emballage d’origine. Gilveradin propose son aide en échange de deux bouteilles supplémentaires. Rassemblez dix bouteilles et rapportez-les au camp."},{t="Les ruines du Rocher de l’Affût",b="Des caisses de Houle au miel des Hinterlands sont éparpillées autour de la base abandonnée de la Horde, près du Rocher de l’Affût. Des gelées et des limons immondes s’accrochent aux ruines. La rumeur dit qu’un maître des limons les dirige."}},faq={{q="Qui veut faire emballer la Houle au miel des Hinterlands ?",a="Dran Droffers recherche la Houle au miel des Hinterlands. Gilveradin Sunchaser possède son emballage d’origine, destiné au père de Malton.",al={"qui veut la houle","houle de dran droffers","pour qui est l’emballage"}},{q="Que demande Gilveradin pour l’emballage ?",a="Gilveradin demande deux bouteilles supplémentaires de la Houle en échange. Les caisses contiennent dix bouteilles.",al={"pourquoi dix bouteilles","prix de gilveradin","pourquoi tant de houle"}},{q="Où se trouvent les caisses de Houle au miel des Hinterlands ?",a="Les caisses se trouvent autour de la base abandonnée de la Horde, près du Rocher de l’Affût, dans les Hinterlands.",al={"lieu de la houle","où trouver la houle au miel","caisses du rocher de l’affût"}},{q="Que trouve-t-on dans le camp abandonné du Rocher de l’Affût ?",a="Des gelées et des limons immondes s’accrochent aux ruines, et la rumeur dit qu’un maître des limons les dirige.",al={"monstres du rocher de l’affût","que trouve-t-on au rocher de l’affût","limons du rocher de l’affût"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="La cape de démon balafrée",s="À Mulgore, la cape de démon balafrée porte les blessures du tourment de Ghost Howl. Cette peau provient d’un légendaire loup blanc marqué par la Légion ardente. Son arrivée à Sabot-de-Sang met un terme à l’histoire tourmentée de la bête.",h="À Mulgore, la cape de démon balafrée porte les blessures du tourment de Ghost Howl.",kw={"légion ardente","cape griffée par les démons","ghost howl","mulgore","skorn nuage-blanc","loup blanc"},ang={["class:Druid"]="En tant que druide, vous voyez la fourrure marquée par les démons comme un sombre rappel : la terre et ses habitants sauvages portent encore les blessures de l’invasion démoniaque de Kalimdor, qui n’ont pas cicatrisé.",["class:Hunter"]="En tant que chasseur, vous savez que traquer un alpha solitaire et balafré comme Ghost Howl est un rite de passage. L’ancien Skorn Nuage-blanc salue votre talent et vous offre un présent digne d’un maître chasseur.",["race:Tauren"]="En tant que Shu'halo, vous pouvez voir la chasse à Ghost Howl comme un rite solennel qui libère une créature à l’agonie de la souillure persistante de la Légion ardente."},sec={{t="Une relique blessée par le gangrefeu",b="Ghost Howl est un légendaire loup blanc dont le hurlement plaintif résonne à travers Mulgore. La peau laissée par la bête porte les marques d’une corruption démoniaque. Elles datent des combats désespérés menés contre les démons envahisseurs de la Légion ardente. Les blessures ont longtemps marqué la chair et l’esprit de Ghost Howl après la Troisième Guerre."},{t="La paix pour un esprit tourmenté",b="Les Taurens de Mulgore révèrent les bêtes sauvages de leur terre natale comme des enfants de la Mère-Terre. À Sabot-de-Sang, Skorn Nuage-blanc reçoit la cape balafrée, preuve que le prédateur tourmenté est mort. Il reconnaît le talent nécessaire pour traquer et vaincre Ghost Howl. D’un ton grave, il espère que l’esprit torturé du loup a trouvé la paix."}},faq={{q="Qu’est-ce que la Cape griffée par les démons ?",a="La Cape griffée par les démons est la peau en lambeaux laissée par Ghost Howl, un légendaire loup blanc de Mulgore. Le gangrefeu l’a balafrée lors d’un ancien combat contre la Légion ardente.",al={"cape griffée par les démons","objet cape griffée par les démons","fourrure de ghost howl"}},{q="D’où viennent les marques démoniaques sur la cape ?",a="Ghost Howl a été blessé lors d’affrontements contre les démons envahisseurs de la Légion ardente pendant la Troisième Guerre, alors qu’ils avançaient à travers Kalimdor.",al={"pourquoi ghost howl est-il balafré","comment ghost howl a-t-il été balafré","ghost howl et la légion"}},{q="À qui dois-je apporter la cape ?",a="Apportez la cape à Skorn Nuage-blanc, un chasseur tauren âgé qui vit à Sabot-de-Sang, en Mulgore.",al={"où remettre la cape griffée par les démons","qui veut la cape griffée par les démons","remettre la cape à skorn nuage-blanc"}},{q="Pourquoi Ghost Howl intéresse-t-il Skorn Nuage-blanc ?",a="Skorn Nuage-blanc est un chasseur à la retraite qui sait que Ghost Howl a beaucoup souffert de la corruption démoniaque. Il respecte le talent nécessaire pour abattre la bête et espère que son esprit pourra enfin reposer en paix.",al={"histoire de skorn nuage-blanc","pourquoi skorn veut-il ghost howl"}},{q="Où trouve-t-on Ghost Howl ?",a="Ghost Howl parcourt les plaines vallonnées de Mulgore, généralement dans les champs ouverts du nord ou du centre, entre la Mesa de Nuage rouge et les Pitons-du-Tonnerre.",al={"où trouver ghost howl","lieu où se trouve ghost howl","apparition de ghost howl"}},{q="Pourquoi les Taurens espèrent-ils que l’esprit du loup trouve la paix ?",a="Les Taurens révèrent les esprits sauvages et recherchent l’harmonie avec la nature. La corruption démoniaque a tourmenté Ghost Howl. Ils voient donc la défaite du loup comme une délivrance bienveillante, qui le rend à la Mère-Terre.",al={"croyances des taurens sur ghost howl","esprit de ghost howl"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="ON RECHERCHE : Surveillant Maltorius",s="Dans le Chaudron, une prime réclame la mort du surveillant Maltorius. Elle le désigne comme un agent renégat de la Confrérie du thorium et le nouveau commandant de l’équipe Sombrefer de la Fosse aux scories. Le surveillant Oilfist exige que sa tête soit remise au Capitaine de guet Lolo Longstriker comme preuve.",h="Dans le Chaudron, une prime réclame la mort du surveillant Maltorius.",kw={"prime","chaudron","lolo longstriker","surveillant maltorius","surveillant oilfist","gorge des vents brûlants","la fosse aux scories","confrérie du thorium"},sec={{t="Le prix d’un traître",b="Dans la Fosse aux scories du Chaudron, vous devez retrouver et tuer le surveillant Maltorius. L’avis le décrit comme un nain Sombrefer traître. Rapportez sa tête au Capitaine de guet Lolo Longstriker pour toucher la prime."}},faq={{q="Qui est le surveillant Maltorius ?",a="Le surveillant Maltorius est un nain Sombrefer traître. L’avis le désigne comme un agent renégat de la Confrérie du thorium et le nouveau commandant de l’équipe Sombrefer de la Fosse aux scories du Chaudron.",al={"histoire de maltorius","qui est maltorius","passé du surveillant maltorius"}},{q="Où trouver le surveillant Maltorius ?",a="Le surveillant Maltorius se trouve dans la Fosse aux scories, au cœur du Chaudron.",al={"emplacement de maltorius","où se trouve maltorius","comment trouver le surveillant maltorius"}},{q="Qui a ordonné la mort du surveillant Maltorius ?",a="Le surveillant Oilfist a ordonné la mort du surveillant Maltorius.",al={"qui a affiché l’avis de prime","qui veut la mort de maltorius","qui a ordonné le meurtre"}},{q="Qui reçoit la preuve de la mort de Maltorius ?",a="Le Capitaine de guet Lolo Longstriker, dans la Gorge des Vents brûlants, reçoit la preuve de la mort de Maltorius : sa tête.",al={"à qui remettre la tête de maltorius","où apporter la tête de maltorius","emplacement de lolo longstriker"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Dans la Gorge des Vents brûlants, vous avez un oreiller gigantesque et richement orné, autrefois gardé par Chambermaid Pillaclencher. Evonice Sootsmoker le voudra sûrement.",h="Dans la Gorge des Vents brûlants, vous avez un oreiller gigantesque et richement orné, autrefois gardé par...",kw={"chambermaid pillaclencher","evonice sootsmoker","regardez-moi la taille de ça","oreiller","gorge des vents brûlants"},sec={{t="Un oreiller pour Evonice",b="Evonice Sootsmoker voudra sûrement l’oreiller gigantesque et richement orné de Chambermaid Pillaclencher. Apportez-le-lui dans la Gorge des Vents brûlants et voyez ce qu’elle vous offre pour votre peine."}},faq={{q="Qui veut l’oreiller de Chambermaid Pillaclencher ?",a="Evonice Sootsmoker, dans la Gorge des Vents brûlants, voudra sûrement l’oreiller de Chambermaid Pillaclencher.",al={"à qui apporter l’oreiller","oreiller evonice sootsmoker","où apporter l’oreiller"}},{q="D’où vient cet oreiller ?",a="L’oreiller gigantesque et richement orné appartenait autrefois à Chambermaid Pillaclencher.",al={"butin oreiller","qui donne l’oreiller","oreiller chambermaid"}},{q="Où trouver Evonice Sootsmoker ?",a="Evonice Sootsmoker se trouve dans la Gorge des Vents brûlants.",al={"emplacement evonice","où se trouve evonice sootsmoker","evonice gorge des vents brûlants"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="Le rite de vision",s="Dans tout Mulgore, les jeunes Taurens rassemblent des offrandes pour le rite de vision. À Sabot-de-Sang, Zarlman Deux-Lunes les guide tandis qu’ils préparent l’Eau des Prophètes et cherchent conseil auprès des esprits ancestraux.",h="Dans tout Mulgore, les jeunes Taurens rassemblent des offrandes pour le rite de vision.",kw={"pomme de pin","sabot-de-sang","mère-terre","mulgore","le rite de vision","eau des prophètes","pierres de puits","zarlman deux-lunes"},ang={["class:Druid"]="En tant que druide, vous vénérez les Pommes de pin et les pierres de puits, signes des plantes et des cours d’eau nourriciers qui préservent l’équilibre de Mulgore.",["class:Shaman"]="En tant que chaman, vous reconnaissez l’Eau des Prophètes comme un rituel traditionnel d’ancrage. Elle accorde votre esprit à la lecture des éléments invisibles avant que vous ne parliez directement aux esprits.",["race:Tauren"]="En tant que Tauren, vous franchissez une étape importante de votre culture, qui vous lie à l’héritage spirituel de la Mère-Terre et des ancêtres, que vous soyez guerrier, chasseur ou mystique."},sec={{t="Les réactifs de la terre",b="Zarlman Deux-Lunes vous envoie à travers Mulgore chercher des pierres de puits et des Pommes de pin. Les pierres se trouvent près de puits communaux sacrés, tandis que les Pommes de pin tombent au pied d’arbres anciens. Pour les Taurens, ce sont bien plus que des présents de la terre. Elles portent la magie latente et le sang nourricier de la Mère-Terre, prêts pour le rite."},{t="Préparer l’Eau des Prophètes",b="Zarlman réunit les pierres de puits et les Pommes de pin pour préparer l’Eau des Prophètes. Vous la buvez près de la flamme tribale du village. Le breuvage éclaircit votre esprit et invoque un guide éthéré. Vous suivez ensuite ce guide à travers les plaines, pour éprouver votre capacité à cheminer entre le monde physique et les murmures spirituels de la terre."}},faq={{q="Quel est le but du rite de vision ?",a="Le rite de vision met à l’épreuve les jeunes Taurens qui arrivent à l’âge adulte et cherchent leur voie. Vous préparez et buvez l’Eau des Prophètes, puis apprenez à communier avec les esprits et à suivre les présages ancestraux dans les plaines de Mulgore.",al={"qu’est-ce que le rite de vision","pourquoi faire le rite de vision","but du rite de vision"}},{q="Qui est Zarlman Deux-Lunes ?",a="Zarlman Deux-Lunes est un chaman et voyant tauren de Sabot-de-Sang. Il supervise les épreuves spirituelles des jeunes aventuriers, prépare des breuvages rituels comme l’Eau des Prophètes et interprète les signes de la Mère-Terre.",al={"qui est zarlman","rôle de zarlman deux-lunes","donneur de quête zarlman"}},{q="Où trouve-t-on les pierres de puits et les Pommes de pin ?",a="Les pierres de puits se trouvent près des sources d’eau douce disséminées dans Mulgore. Les Pommes de pin tombent au pied des grands arbres qui parsèment les prairies environnantes.",al={"où trouver les pommes de pin","emplacement des pierres de puits","réactifs du rite de vision"}},{q="Que se passe-t-il après avoir bu l’Eau des Prophètes ?",a="Près du feu tribal, boire l’Eau des Prophètes ouvre votre vision spirituelle et révèle un guide animal fantomatique. Vous suivez l’esprit à travers les plaines pour découvrir la prochaine étape de votre voyage sacré.",al={"suite du rite de vision","effet de l’eau des prophètes","suite de la quête de vision"}},{q="Pourquoi les Taurens vénèrent-ils tant les puits d’eau ?",a="L’eau est le sang nourricier de Mulgore et un précieux don de la Mère-Terre. Les Taurens vénèrent les puits comme des lieux sacrés où la communauté se rassemble, qui nourrissent la terre et ses troupeaux. Les pierres recueillies à leurs abords portent un pouvoir spirituel.",al={"puits d’eau des taurens","pourquoi les puits sont sacrés","eau de mulgore"}},{q="Cette quête mène-t-elle à d’autres rites ?",a="Oui. La cérémonie comporte plusieurs étapes. Après que Zarlman a préparé l’Eau des Prophètes, vous la buvez, suivez la vision qui apparaît et vous présentez aux chefs anciens de Mulgore.",al={"quête suivante du rite de vision","le rite de vision est-il une suite de quêtes","suite de rites taurens"}}},fx={["6b13f1a7"]={q="Pourquoi Zarlman Deux-Lunes veut-il que cela soit fait ?",a="En tant que chaman tribal, Zarlman Deux-Lunes est responsable de guider les jeunes aventuriers prometteurs à travers les traditions sacrées des taurens. Il ne peut pas simplement vous accorder la sagesse spirituelle ; vous devez gagner la faveur de la Terre-Mère et de vos ancêtres en participant directement au rituel, en commençant par rassembler vous-même les éléments sacrés de la terre.",al={"motif de zarlman deux-lunes","pourquoi zarlman vous envoie-t-il","raison du rite of vision de zarlman"}},cc7474fb={q="À quoi servent les Pierres de puits ?",a="Les Pierres de puits sont récoltées dans les puits d'eau sacrés disséminés dans tout Mulgore. Imprégnées de la magie naturelle des sources les plus pures de la Terre-Mère, elles constituent l'un des principaux réactifs dont Zarlman Deux-Lunes a besoin pour préparer la mystique Eau des Prophètes.",al={"but des pierres de puits","pourquoi besoin pierre de puits","utilisation pierre de puits"}},["4efb8f2d"]={q="À quoi sert la Pomme de pin ?",a="Tombée des arbres majestueux qui parsèment Mulgore, la Pomme de pin porte l'essence naturelle de la flore de la région. Associée aux Pierres de puits et mise en infusion par Zarlman Deux-Lunes, elle confère les propriétés magiques nécessaires à la préparation de l'Eau des Prophètes, vous permettant ainsi d'avoir des visions ancestrales.",al={"but de la pomme de pin","à quoi sert la pomme de pin","pourquoi récupérer pomme de pin"}},["761f0189"]={q="Pourquoi devez-vous récolter les réactifs au lieu de Zarlman Deux-Lunes ?",a="Le Rite of Vision est une épreuve individuelle de croissance spirituelle, et non une corvée routinière. Pour communier avec les esprits, vous devez faire preuve de respect et d'harmonie avec la terre en cherchant vous-même ses bénédictions naturelles. Laisser quelqu'un d'autre collecter les réactifs ruinerait le but sacré de l'épreuve.",al={"pourquoi dois-je récupérer la pomme de pin","pourquoi zarlman ne récupère pas les pierres de puits","pourquoi moi rite of vision"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="Le rite de vision",s="À Sabot-de-Sang, les jeunes taurens boivent l’Eau des Prophètes et entrevoient le chemin qui les attend. Un guide spectral apparaît près du feu de joie tribal.",h="À Sabot-de-Sang, les jeunes taurens boivent l’Eau des Prophètes et entrevoient le chemin qui les attend.",kw={"sabot-de-sang","loup fantôme","mulgore","le rite de vision","prophète wiserunner","feu tribal","eau des prophètes","zarlman deux-lunes"},ang={["class:Druid"]="En tant que druide, vous approfondissez votre révérence pour le monde naturel et votre humilité spirituelle face aux conseils des formes animales.",["class:Shaman"]="En tant que chaman, vous apprenez très tôt à cheminer entre les mondes en suivant un loup spirituel ancestral. Le rite ancre votre lien avec les esprits qui guident la Horde.",["race:Tauren"]="Jeune tauren, vous accédez à l’âge adulte en accomplissant le Rite de vision sacré. Il témoigne de votre communion avec vos ancêtres et de votre obéissance aux conseils spirituels."},sec={{t="L’Eau des Prophètes",b="Après avoir cueilli les herbes rituelles et réussi les premières épreuves de foi, vous recevez l’Eau des Prophètes de Zarlman Deux-Lunes. Vous la buvez devant le feu tribal, au cœur de Sabot-de-Sang. Gardez l’esprit concentré et respectueux : l’eau sacrée ouvre votre regard au-delà du monde physique. Elle relie les royaumes matériel et spirituel."},{t="À la suite du loup fantôme",b="Après que vous avez bu le breuvage, un loup fantôme ancestral apparaît dans les flammes. Il ne parle pas et ne combat pas, mais trotte vers le nord-ouest à travers les plaines vallonnées de Mulgore. Suivez sa voie silencieuse, loin du village et jusque dans les collines rocheuses. Là, l’ermite Prophète Wiserunner médite à l’écart."},{t="Un chemin vers la sagesse",b="La vision prend fin lorsque vous rejoignez le Prophète Wiserunner à l’entrée de sa caverne montagnarde. Le chemin à travers les collines herbeuses met à l’épreuve votre patience, votre confiance dans les conseils ancestraux et votre communion avec la Terre-Mère. Réussissez le rite et vous pourrez affronter le Rite of Wisdom, l’ultime épreuve de l’âge adulte."}},faq={{q="Que se passe-t-il quand je bois l’Eau des Prophètes ?",a="Quand vous buvez l’Eau des Prophètes près du feu tribal de Sabot-de-Sang, vos sens spirituels s’éveillent. Bientôt, un loup fantôme apparaît devant les flammes pour vous guider.",al={"fonctionnement de l’eau des prophètes","boire l’eau des prophètes","effets de l’eau"}},{q="Où le guide spirituel me conduit-il ?",a="Le loup spectral vous mène au nord-ouest de Sabot-de-Sang, à travers les collines de Mulgore, jusqu’à une grotte rocheuse où vit le Prophète Wiserunner.",al={"destination du loup fantôme","qui le loup conduit-il à voir","destination du loup"}},{q="Qui est Zarlman Deux-Lunes ?",a="Zarlman Deux-Lunes est un chaman tauren de Sabot-de-Sang. Il prépare les initiés à l’âge adulte spirituel par des rites ancestraux et des breuvages sacrés.",al={"qui donne le rite de vision","rôle de zarlman deux-lunes"}},{q="Qui est le Prophète Wiserunner ?",a="Le Prophète Wiserunner est un mystique tauren âgé qui médite parmi les falaises au nord-ouest de Sabot-de-Sang. Les initiés qui suivent leur vision spirituelle le trouvent et achèvent l’épreuve.",al={"qui est wiserunner","prophète dans une grotte de mulgore"}},{q="Pourquoi faut-il boire l’eau près du feu tribal ?",a="Le feu de joie tribal de Sabot-de-Sang sert d’ancrage aux esprits ancestraux. Ses flammes consacrées et l’eau sacrée permettent ensemble à la vision de pénétrer le monde éveillé.",al={"pourquoi le feu tribal","feu de joie du rite de vision"}},{q="Quel rite vient après le Rite de vision ?",a="Après avoir achevé le Rite de vision avec le Prophète Wiserunner, vous entreprenez le Rite of Wisdom, l’ultime épreuve spirituelle de vos débuts à Mulgore.",al={"quête après le rite de vision","what comes next"}}},fx={["659b3713"]={q="Pourquoi Zarlman Deux-Lunes veut-il que je subisse le Rite of Vision ?",a="En tant que chaman du village de Sabot-de-Sang, Zarlman Deux-Lunes guide les jeunes taurens sur les chemins sacrés de leurs ancêtres. Ayant rassemblé les composants de l'Eau des Prophètes, il vous présente maintenant la décoction afin que vous puissiez communier directement avec les esprits, être témoin de votre vision et franchir l'étape suivante vers la découverte de votre destin au sein de la tribu.",al={"pourquoi rite of vision","motivation zarlman deux-lunes","but du rite of vision"}},b8c8221c={q="Pourquoi dois-je entreprendre ce rite moi-même ?",a="Les Rites of the Earthmother sont des épreuves de maturité et d'éveil spirituel profondément personnelles. Aucun garde ou ancien ne peut parcourir le chemin des esprits à votre place ; seul votre esprit peut recevoir les conseils destinés à révéler votre place et votre but parmi le peuple tauren.",al={"pourquoi dois-je faire le rite","pourquoi moi rite of vision","pourquoi quelqu'un d'autre ne peut pas faire le rite"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="Du carburant pour la zappette",s="Sur la Côte oubliée, Zorbin Fandazzle fait travailler son atelier d’ingénierie dans un lieu désolé. Les élémentaires le dérangent, mais leurs noyaux d’eau peuvent alimenter le raffinage de l’Ultra-Shrinker.",h="Sur la Côte oubliée, Zorbin Fandazzle fait travailler son atelier d’ingénierie dans un lieu désolé.",kw={"féralas","la côte oubliée","sea elemental","sea spray","ultra-shrinker","noyau d’élémentaire d’eau","zorbin fandazzle"},sec={{t="L’énergie des vagues",b="Zorbin Fandazzle maudit la puissance incontrôlée de l’élémentarisme et traite les élémentaires de la côte de nuisibles. Pourtant, il voit dans leurs noyaux d’élémentaires d’eau une source d’énergie brute pour raffiner l’Ultra-Shrinker. Il vous demande d’affronter les Sea Elementals et les Sea Sprays le long de la côte. Gardez leurs noyaux et apportez-les-lui près du quai."},{t="Les remerciements de Zorbin",b="Zorbin est ravi des noyaux. Ils lui permettront de poursuivre son travail pendant quelque temps, et les élémentaires sont désormais moins nombreux à parcourir la côte. Il reconnaît qu’ouvrir son atelier dans ce qui est peut-être le pire endroit imaginable lui donnait envie de pleurer la nuit. La récompense met ses finances à rude épreuve, mais il vous l’offre en signe de gratitude."}},faq={{q="Qui demande les noyaux d’élémentaires ?",a="Zorbin Fandazzle demande les noyaux d’élémentaires. Son atelier d’ingénierie se trouve près du quai, sur la Côte oubliée de Féralas.",al={"qui fournit le carburant pour zapping","donneur de quête zorbin fandazzle","qui lance du carburant pour zapping"}},{q="Pourquoi Zorbin Fandazzle a-t-il besoin de noyaux d’élémentaires d’eau ?",a="Zorbin Fandazzle a besoin de noyaux d’élémentaires d’eau comme source d’énergie brute pour raffiner l’Ultra-Shrinker. Il considère les élémentaires locaux comme une source idéale.",al={"pourquoi des noyaux d’élémentaires d’eau","à quoi servent les noyaux","carburant de l’ultra-shrinker"}},{q="Où récupérer les noyaux d’élémentaires ?",a="Récupérez les noyaux sur les Sea Elementals et les Sea Sprays le long de la Côte oubliée de Féralas.",al={"où trouver des noyaux","emplacement des sea elementals","où trouver les sea sprays"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="Le Flux embrasé",s="Le maître forgeron Burninate cherche les plans secrets : Flux embrasé dans la Fosse aux scories. Maltorius a quitté leur clan avec la recette, que Burninate estime plus précieuse qu’un cristal d’arcanes parfait, et pense que les plans sont près de lui.",h="Le maître forgeron Burninate cherche les plans secrets : Flux embrasé dans la Fosse aux scories.",kw={"burninate","chaudron","flux embrasé","maltorius","plans","gorge des vents brûlants","la fosse aux scories"},sec={{t="La recette volée",b="Le maître forgeron Burninate dit que Maltorius a trahi leur clan en partant avec la recette de flux embrasé. Burninate soupçonne que cette recette a aidé Maltorius à obtenir sa nouvelle promotion parmi les Sombrefer. Il veut maintenant récupérer les plans secrets."},{t="Dans la Fosse aux scories",b="Le maître forgeron Burninate pense que les plans se trouvent près de Maltorius, au fond de la Fosse aux scories. Il veut que vous lui rapportiez les Plans secrets : Flux embrasé."}},faq={{q="Qui a volé la recette de Flux embrasé ?",a="Selon le maître forgeron Burninate, Maltorius a volé la recette de Flux embrasé. Burninate le traite de traître à leur clan.",al={"qui a volé la recette","qui a pris les plans","le traître du flux embrasé"}},{q="Où se trouvent les plans secrets ?",a="Burninate pense que les plans secrets se trouvent près de Maltorius, au fond de la Fosse aux scories du Chaudron.",al={"où sont les plans","emplacement des plans secrets de flux embrasé","où trouver les plans de flux embrasé"}},{q="Qui demande de récupérer les plans ?",a="Le maître forgeron Burninate, un forgeron, veut que les plans lui soient rendus.",al={"qui donne la quête qu’est-ce que le flux"}},{q="Pourquoi les plans comptent-ils tant pour Burninate ?",a="Burninate affirme que la recette secrète de Flux embrasé du clan vaut plus qu’un cristal d’arcanes parfait.",al={"pourquoi le flux embrasé est important","importance de la recette de flux embrasé"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="Maudits gros doigts",s="Dans la Gorge des Vents brûlants, Hansel Lourdemains ne peut plus rosser comme avant. Ses doigts enflés vous chargent des golems de guerre lourds.",h="Dans la Gorge des Vents brûlants, Hansel Lourdemains ne peut plus rosser comme avant.",kw={"chaudron","gros doigts","hansel lourdemains","golems de guerre lourds","gorge des vents brûlants","thelsamar blood sausages"},sec={{t="Des doigts comme des saucisses",b="Hansel Lourdemains accuse le climat de la Gorge des Vents brûlants et son air raréfié de faire enfler ses doigts. Ils ressemblent à d'énormes Thelsamar Blood Sausages. Avec des doigts pareils, Hansel ne peut plus rosser comme avant et a besoin que vous vous occupiez de ses affaires."},{t="En tête de liste",b="Hansel veut que vous frappiez fort les golems de guerre lourds de la Gorge. Vingt doivent être détruits. Ils rôdent dans les zones autour du Chaudron, et vous retournez voir Hansel quand ils sont assez nombreux à être tombés."}},faq={{q="Qui est Hansel Lourdemains ?",a="Hansel Lourdemains se trouve dans la Gorge des Vents brûlants. Ses doigts enflés l'empêchent de se battre, alors Hansel vous demande de frapper à sa place.",al={"hansel lourdemains","qui donne la quête maudits gros doigts","qui donne la quête"}},{q="Pourquoi Hansel ne peut-il pas combattre les golems lui-même ?",a="Hansel accuse le climat de la Gorge des Vents brûlants et son air raréfié de faire enfler ses doigts. Hansel les compare à d'énormes Thelsamar Blood Sausages.",al={"pourquoi les doigts de hansel sont-ils gros","histoire des gros doigts","mains enflées de hansel"}},{q="Quels ennemis faut-il éliminer ?",a="Vous devez détruire vingt golems de guerre lourds.",al={"quels ennemis combattre","que veut hansel voir mort"}},{q="Où se trouvent les golems de guerre lourds ?",a="Les golems de guerre lourds rôdent dans les zones autour du Chaudron, dans la Gorge des Vents brûlants.",al={"où sont les golems","emplacement des golems de guerre lourds"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="Une menace incandescente",s="Hansel Lourdemains a encore une tâche pour vous dans la Gorge des Vents brûlants. Des araignées de lave supérieures sèment le trouble.",h="Hansel Lourdemains a encore une tâche pour vous dans la Gorge des Vents brûlants.",kw={"menace incandescente","araignées de lave supérieures","hansel lourdemains","oilfist","gorge des vents brûlants","araignées"},sec={{t="Une nouvelle tâche pour Hansel",b="Hansel Lourdemains a peu de temps pour se reposer ou réfléchir à sa vie. Les puissants ne cessent de lui confier du travail. Des araignées de lave supérieures sèment le trouble, alors Hansel préférerait que vous vous en chargiez."},{t="Les araignées de lave supérieures",b="Oilfist raconte que les araignées de lave supérieures crachent du feu par un endroit embarrassant. Leurs flammes contrarient les enfants. Hansel veut que vous en tuiez vingt sur les plateaux et près des bassins de lave de la Gorge des Vents brûlants."}},faq={{q="Qui vous envoie tuer les araignées ?",a="Hansel Lourdemains vous envoie tuer les araignées dans la Gorge des Vents brûlants. Il espérait profiter d'un moment de calme.",al={"donneur de quête","qui donne la quête","hansel"}},{q="Pourquoi faut-il tuer les araignées ?",a="Les araignées de lave supérieures sèment le trouble. Oilfist raconte que leur façon de cracher du feu contrarie les enfants.",al={"pourquoi tuer les araignées","qu'ont fait les araignées","problème d'araignées"}},{q="Qui a parlé des araignées à Hansel ?",a="Oilfist a raconté à Hansel que les araignées crachent du feu par un endroit embarrassant.",al={"qui s'est plaint des araignées","oilfist"}},{q="Combien d'araignées de lave supérieures faut-il tuer ?",a="Hansel vous demande de tuer vingt araignées de lave supérieures.",al={"combien d'araignées","nombre d'araignées"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="Le retour des géants rétrécis",s="Aux quais de La Côte oubliée, Zorbin Fandazzle vous fait une nouvelle offre. Rapportez-lui davantage de résidus prélevés sur des géants de Féralas rétrécis avec l’Ultra-réducteur de Zorbin. Il peut vous payer bien moins cette fois, mais promet de faire connaître vos services.",h="Aux quais de La Côte oubliée, Zorbin Fandazzle vous fait une nouvelle offre.",kw={"féralas","la côte oubliée","géants","résidu de miniaturisation","cartel gentepression","ultra-réducteur","zorbin fandazzle"},sec={{t="Un rappel pour l’Ultra-réducteur",b="Zorbin Fandazzle vous demande de rétrécir à nouveau des géants à Féralas et d’apporter dix résidus de miniaturisation aux quais de La Côte oubliée. Il y a toujours de la place pour davantage, même après votre première récolte.\n\nIl ne peut pas vous offrir autant cette fois. En échange, il promet de vanter vos services auprès de ses amis gobelins, qui ont de très grandes oreilles."},{t="Les remerciements de Zorbin",b="Zorbin Fandazzle est ravi que vous ayez une nouvelle fois répondu présent, même si la récompense est inférieure à ce à quoi vous êtes habitué. Il dit que la nouvelle de vos hauts faits pour la communauté gobeline résonne déjà dans les cercles du pouvoir du Cartel Gentepression."}},faq={{q="Qui demande plus de résidus ?",a="Zorbin Fandazzle vous attend aux quais de La Côte oubliée, à Féralas, et vous demande davantage de résidus.",al={"donneur de quête","emplacement de zorbin","qui donne la quête le retour des géants rétrécis"}},{q="Que s’est-il passé avant ?",a="Cette quête fait suite à « Le retour des géants rétrécis », votre première récolte de résidus pour Zorbin Fandazzle.",al={"prérequis","quête précédente","que faire en premier"}},{q="Comment récolter les résidus ?",a="Utilisez l’Ultra-réducteur de Zorbin sur n’importe quel type de géant à Féralas pour le rétrécir. Récupérez ensuite les résidus sur les géants miniaturisés.",al={"comment obtenir des résidus","résidu de miniaturisation","comment rétrécir les géants"}},{q="Où trouve-t-on les géants ?",a="Les géants se trouvent le long de la côte ouest de Féralas.",al={"emplacement des géants","où trouver les géants de féralas","géants de la côte oubliée"}},{q="Zorbin reprendra-t-il des résidus une autre fois ?",a="Zorbin dit qu’il peut toujours utiliser davantage de résidus. Vous pouvez donc revenir avec un nouveau lot de dix.",al={"quête répétable","peut-on répéter la quête le retour des géants rétrécis","quête répétable sur les géants"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="Encore du carburant pour la zappette",s="Sur la Côte oubliée, Zorbin Fandazzle a besoin de nouveaux noyaux d’élémentaire d’eau. Il est difficile d’y établir une boutique, alors la rétribution est modeste. Malgré tout, Zorbin promet de parler de votre aide aux gens du coin et affirme avoir des amis au Cartel Gentepression.",h="Sur la Côte oubliée, Zorbin Fandazzle a besoin de nouveaux noyaux d’élémentaire d’eau.",kw={"féralas","la côte oubliée","sea elemental","sea spray","cartel gentepression","noyau d’élémentaire d’eau","zorbin fandazzle"},sec={{t="Encore du carburant",b="Zorbin Fandazzle plaisante sur le travail héroïque qui consiste à récupérer de la matière visqueuse sur des êtres élémentaires. Puis Zorbin vous demande si vous en voulez encore. Derrière la plaisanterie, Zorbin a besoin de nouveaux noyaux d’élémentaire d’eau.\n\nÉtablir une boutique sur la Côte oubliée est une entreprise désespérée, alors Zorbin ne peut guère offrir en retour. Zorbin promet de raconter aux gens du coin comment vous avez aidé, et affirme que cette promesse est digne de confiance, car Zorbin connaît du monde au Cartel Gentepression. Rapportez six noyaux prélevés sur des Sea Elementals et des Sea Sprays de la Côte oubliée à Zorbin, près du ponton."},{t="Les remerciements de Zorbin",b="Zorbin est satisfait de votre travail, même si la rémunération ne sera peut-être pas la plus importante que vous recevrez. Zorbin parlera de vos efforts à ses camarades du Cartel Gentepression. Vous pouvez continuer si vous le souhaitez : Zorbin a encore besoin de noyaux et d’autres choses du même genre."}},faq={{q="Qui demande les noyaux d’élémentaire d’eau ?",a="Zorbin Fandazzle vous attend près du ponton, sur la Côte oubliée de Féralas.",al={"qui donne cette quête","qui est zorbin fandazzle","où se trouve zorbin"}},{q="D’où viennent les noyaux d’élémentaire d’eau ?",a="Les noyaux proviennent des Sea Elementals et des Sea Sprays de la Côte oubliée de Féralas.",al={"où trouver les noyaux","lieu d’obtention du noyau d’élémentaire d’eau","quels ennemis donnent des noyaux"}},{q="Pourquoi Zorbin Fandazzle a-t-il besoin d’autres noyaux ?",a="Zorbin dit avoir besoin de nouveaux noyaux d’élémentaire d’eau pour tenter d’établir une boutique sur la côte.",al={"pourquoi zorbin veut des noyaux","motif de zorbin fandazzle","à quoi servent les noyaux"}},{q="Que s’est-il passé avant ?",a="Cette quête fait suite à Fuel for the Zapping, où vous avez récolté des noyaux élémentaires pour Zorbin pour la première fois.",al={"quête précédente","quête prérequise","quelle quête vient avant"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaures ? N'importosaures, plutôt",s="Hansel Lourdemains ne peut pas se battre avec les pieds dans un tel état. Il vous envoie donc tuer vingt incendosaures dans la Fosse aux scories, où Scrange et Burninate veulent libérer les bassins de lave pour les équipes d’expédition.",h="Hansel Lourdemains ne peut pas se battre avec les pieds dans un tel état.",kw={"burninate","chaudron","hansel lourdemains","incendosaure","scrange","gorge des vents brûlants","la fosse aux scories"},sec={{t="Des oignons à n’en plus finir",b="Hansel Lourdemains ne peut pas se battre avec ses oignons dans un tel état. Scrange et Burninate lui ont demandé de tuer les incendosaures afin que les équipes d’expédition puissent explorer les bassins de lave de la Fosse aux scories. Il vous envoie maintenant à sa place."},{t="Les bassins de lave",b="Les incendosaures occupent les bassins de lave de la Fosse aux scories, dans le Chaudron. Hansel veut que vous en tuiez vingt avant de revenir."}},faq={{q="Qui est Hansel Lourdemains ?",a="Hansel Lourdemains vous confie des tâches dans la Gorge des Vents brûlants. Scrange et Burninate lui ont demandé de s’occuper des incendosaures, mais ses oignons l’empêchent de se battre.",al={"hansel lourdemains","qui donne la quête","qui confie cette quête"}},{q="Pourquoi faut-il éliminer les incendosaures ?",a="Scrange et Burninate veulent que les équipes d’expédition explorent les bassins de lave de la Fosse aux scories. Les incendosaures qui s’y trouvent causeraient toutes sortes de problèmes.",al={"pourquoi tuer les incendosaures","utilité des incendosaures","pourquoi libérer la fosse aux scories"}},{q="Où trouve-t-on les incendosaures ?",a="Les incendosaures vivent dans les bassins de lave de la Fosse aux scories, dans le Chaudron.",al={"emplacement des incendosaures","où se trouve la fosse aux scories","où sont les bassins de lave"}},{q="Pourquoi Hansel ne les chasse-t-il pas lui-même ?",a="Hansel dit que ses oignons ont des oignons. Ses pieds sont dans un tel état qu’il ne peut rien tuer.",al={"pourquoi hansel ne se bat-il pas","pieds de hansel","oignons de hansel"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="OBJETS VOLES : Tuyère et longue-vue",s="Dans la Gorge des Vents brûlants, la Confrérie du thorium recherche deux outils volés : une tuyère et une Longue-vue de guetteur. La Confrérie est certaine que des nains Sombrefer jaloux et sans scrupules les ont dérobés. Elle demande à quiconque les trouvera de les apporter au Sous-chef Scrange contre rétribution.",h="Dans la Gorge des Vents brûlants, la Confrérie du thorium recherche deux outils volés : une tuyère et une...",kw={"sombrefer","scrange","gorge des vents brûlants","forge","longue-vue","confrérie du thorium","tuyère"},sec={{t="Objets volés",b="La Confrérie du thorium recherche une Longue-vue de guetteur et une tuyère, toutes deux volées. La longue-vue est un excellent outil pour les guetteurs, et la tuyère est un outil de forge irremplaçable. La Confrérie est certaine que des nains Sombrefer les ont dérobées. Quiconque trouvera les outils devra les apporter au Sous-chef Scrange."}},faq={{q="Qui a affiché l’avis ?",a="L’avis est au nom de la Confrérie du thorium, qui est certaine que des nains Sombrefer ont dérobé les objets.",al={"qui recherche les objets volés","qui a donné cette quête","donneur de quête de la tuyère de forge volée"}},{q="Qui a volé les outils ?",a="La Confrérie du thorium est certaine que des nains Sombrefer sans scrupules et jaloux de la Gorge des Vents brûlants ont volé les outils.",al={"qui a pris la tuyère","qui a volé la longue-vue","qui détient les objets volés"}},{q="À qui rapporter les objets retrouvés ?",a="Les objets retrouvés sont à remettre au Sous-chef Scrange.",al={"où rapporter les objets","qui est le sous-chef scrange","à qui remettre la longue-vue"}},{q="À quoi servent les objets volés ?",a="La tuyère est un outil de forge irremplaçable, et la longue-vue aide les guetteurs à monter la garde.",al={"qu’est-ce qu’une tuyère de forge","pourquoi la confrérie veut la tuyère","à quoi sert la longue-vue"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="OFFRE D'EMPLOI : Réduire la concurrence",s="Dans la Gorge des Vents brûlants, le Sous-chef Scrange veut vous faire réduire la concurrence dans le sang.",h="Dans la Gorge des Vents brûlants, le Sous-chef Scrange veut vous faire réduire la concurrence dans le sang.",kw={"éliminer la concurrence","slaver sombrefer","taskmaster sombrefer","opportunité d'embauche","gorge des vents brûlants","sous-chef scrange"},sec={{t="Un poste à pourvoir",b="Le Sous-chef Scrange vous envoie dans la gorge tuer quinze Taskmasters sombrefer et quinze Slavers sombrefer. Revenez quand vos vêtements seront assez ensanglantés. Vous saurez quand ce sera le cas, et vous ne devez pas poser de questions."}},faq={{q="Qui propose cet emploi ?",a="Le Sous-chef Scrange, dans la Gorge des Vents brûlants, veut de l’aide pour éliminer la concurrence.",al={"qui propose cette quête","qui veut la mort des sous-chefs","qui est le sous-chef scrange"}},{q="Quels ennemis doivent être tués ?",a="Tuez quinze Taskmasters sombrefer et quinze Slavers sombrefer.",al={"que dois-je tuer","cibles pour opportunité d'embauche","qui est la concurrence"}},{q="Comment Scrange sait-il que le travail est accompli ?",a="Scrange juge à l’état de vos vêtements, vous pesant avec et sans eux pour s’en assurer.",al={"comment prouver les éliminations","exigence de vêtements ensanglantés","comment scrange vérifie-t-il"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="Le rite de sagesse",s="Aux Rochers rouges, le rite de sagesse mène les Rites of the Earthmother à leur épreuve finale. Après que le Rite de Vision a éclairci votre regard, vous partez communier avec un Esprit ancestral et chercher la bénédiction des morts.",h="Aux Rochers rouges, le rite de sagesse mène les Rites of the Earthmother à leur épreuve finale.",kw={"esprit ancestral","mulgore","rochers rouges","le rite de sagesse","rites of the earthmother","prophète wiserunner","pitons-du-tonnerre","eau des prophètes"},ang={["class:Druid"]="En tant que druide, vous voyez l’équilibre entre le monde des vivants et le cycle éternel veillé par la Terre-mère. Votre devoir va à la terre.",["class:Shaman"]="En tant que chaman, vous honorez les morts en communiant avec un Esprit ancestral. Vous restez fidèle aux esprits qui veillent sur Mulgore.",["race:Tauren"]="En tant que shu'halo, recevoir le manteau des ancêtres aux Rochers rouges marque votre passage à l’âge adulte et votre acceptation parmi les anciens de la tribu."},sec={{t="L’épreuve des Rochers rouges",b="Après que le Rite de Vision a éclairci votre regard, vous partez vers l’est de Pitons-du-Tonnerre, aux Rochers rouges. Ceux qui reposent ici ont combattu et péri pour que Mulgore connaisse la paix, et leurs esprits s’attardent encore. Approchez leur lieu de repos avec révérence et cherchez à communier avec eux. Des menaces gardent les collines tandis que vous cherchez conseil auprès des défunts honorés."},{t="Recevoir le manteau",b="Au sommet des Rochers rouges, vous communiez avec un Esprit ancestral. Cette rencontre éprouve votre maturité spirituelle et votre place parmi les générations, pas votre force au combat. Ces esprits ont combattu aux côtés de Cairne Sabot-de-Sang pour fonder Pitons-du-Tonnerre et protéger les tribus. Leur bénédiction vous reconnaît comme adulte et défenseur. Vous êtes chargé de protéger la cité et pouvez entrer dans Pitons-du-Tonnerre avec fierté."}},faq={{q="Quel est le but du rite de sagesse ?",a="Le rite de sagesse est l’épreuve finale des Rites of the Earthmother. La bénédiction ancestrale unit la vision de la jeunesse aux devoirs de l’âge adulte et vous reconnaît prêt à défendre Pitons-du-Tonnerre.",al={"pourquoi accomplir le rite de sagesse","que fait le rite de sagesse","but du rite de sagesse"}},{q="Qui vous envoie accomplir le rite de sagesse ?",a="Le Prophète Wiserunner vous envoie depuis sa grotte au nord-ouest de Sabot-de-Sang, après que vous avez accompli le Rite de Vision et bu l’Eau des Prophètes.",al={"qui donne le rite de sagesse","où commencer le rite de sagesse"}},{q="Où trouver l’Esprit ancestral ?",a="Vous trouverez l’Esprit ancestral aux Rochers rouges, un ancien cimetière tauren dans les falaises rocheuses juste à l’est de Pitons-du-Tonnerre.",al={"emplacement de l’esprit ancestral","où se trouve l’esprit","où trouver l’esprit ancestral"}},{q="Pourquoi faut-il d’abord accomplir le Rite de Vision ?",a="Le Rite de Vision purifie votre regard spirituel grâce à l’Eau des Prophètes. Vous pouvez ainsi percevoir les anciens esprits des Rochers rouges et recevoir leur bénédiction.",al={"pourquoi accomplir d’abord le rite de vision","prérequis du rite de vision","condition de l’eau des prophètes"}},{q="Que se passe-t-il après avoir accompli le rite de sagesse ?",a="Après avoir obtenu l’approbation des ancêtres, vous recevez l’instruction de vous rendre dans les hauteurs de Pitons-du-Tonnerre.",al={"que faire après le rite de sagesse","quête suivante après le rite de sagesse"}},{q="Quelles créatures menacent les terres des Rochers rouges ?",a="Des gnolls Palemane agressifs ont envahi le cimetière sacré des Rochers rouges. Ils rôdent le long des sentiers rocheux qui mènent à l’ancien lieu de sépulture.",al={"ennemis aux rochers rouges","qui garde les rochers rouges","gnolls aux rochers rouges"}}},fx={["740e2883"]={q="Pourquoi le Prophète Wiserunner vous envoie-t-il suivre le Rite of Wisdom ?",a="Le Prophète Wiserunner guide les jeunes taurens prometteurs à travers les traditionnels Rites of the Earthmother. Vous ayant vu endurer la vision accordée par l'Eau des Prophètes, il vous dirige vers les Rochers rouges afin que vous puissiez recevoir la bénédiction des ancêtres. Pour Wiserunner et les anciens, ce rite garantit que seuls ceux qui sont spirituellement préparés et reconnus par les ancêtres sont accueillis aux Pitons-du-Tonnerre en tant que protecteurs de la tribu.",al={"motivation prophète wiserunner","pourquoi rite of wisdom","pourquoi m'envoyer pour le rite of wisdom"}},["8728f84f"]={q="Pourquoi le Prophète Wiserunner a-t-il besoin que vous y alliez au lieu d'y aller lui-même ?",a="Le Rite of Wisdom est une épreuve de passage personnelle, et non une commission que quelqu'un d'autre peut effectuer à votre place. Pour gagner l'acceptation parmi les anciens et mériter le droit d'entrer aux Pitons-du-Tonnerre, vous devez chercher personnellement l'Esprit ancestral aux Rochers rouges et démontrer la clarté spirituelle acquise grâce à l'Eau des Prophètes. Le devoir de protéger la ville ne peut vous être confié qu'à vous seul.",al={"pourquoi moi rite of wisdom","pourquoi le prophète wiserunner n'y va pas","pourquoi dois-je chercher l'esprit ancestral"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="Infestation de Zukk'ash",s="Au Camp Mojache, Hadoken Swiftstrider soupçonne les Zukk'ash, au sud des gnolls, de les rendre frénétiques. Il vous envoie au Gouffre grouillant pour réduire leur nombre et rapporter vingt carapaces.",h="Au Camp Mojache, Hadoken Swiftstrider soupçonne les Zukk'ash, au sud des gnolls, de les rendre frénétiques.",kw={"camp mojache","carapace","féralas","gnolls","hadoken swiftstrider","insectes","gouffre grouillant","zukk'ash"},sec={{t="L'ennemi au sud des gnolls",b="Hadoken Swiftstrider pense que des créatures insectoïdes vivent au sud des gnolls. Qu'elles soient douées de raison importe peu à ses yeux. Si elles poussent les gnolls à entrer en frénésie contre le Camp Mojache, elles menacent le camp autant que les gnolls. Vous vous aventurez donc dans leur repaire, le Gouffre grouillant, pour réduire leur nombre. Rapportez vingt carapaces de Zukk'ash comme preuve, et dites à Hadoken ce que vous aurez découvert."},{t="Le verdict d'Hadoken",b="Hadoken Swiftstrider est satisfait à votre retour. Seule une invasion à grande échelle peut mettre fin à la présence des Zukk'ash, mais votre travail a donné au Camp Mojache le temps d'élaborer une véritable stratégie. Le camp étudiera les carapaces et apprendra tout ce qu'il peut sur ces créatures. Le danger a pris une ampleur bien supérieure à ce que quiconque avait prévu."}},faq={{q="Qui vous envoie contre les Zukk'ash ?",a="Hadoken Swiftstrider vous envoie depuis le Camp Mojache, en Féralas.",al={"donneur de quête","hadoken swiftstrider","qui donne la quête infestation de zukk'ash"}},{q="Que sont les Zukk'ash ?",a="Hadoken pense que les Zukk'ash sont des créatures insectoïdes vivant au sud des gnolls. Qu'elles soient douées de raison importe peu à ses yeux ; il craint qu'elles ne poussent les gnolls à entrer en frénésie.",al={"que sont les zukk'ash","insectes zukk'ash","insectes du gouffre grouillant"}},{q="Où se trouve le Gouffre grouillant ?",a="Le Gouffre grouillant, repaire des Zukk'ash, se trouve au sud des gnolls.",al={"emplacement du gouffre grouillant","où se trouve le gouffre grouillant","où se trouvent les insectes"}},{q="Pourquoi Hadoken veut-il des carapaces de Zukk'ash ?",a="Hadoken veut les carapaces comme preuve de votre travail contre les Zukk'ash.",al={"pourquoi des carapaces","utilité des carapaces de zukk'ash","but des carapaces"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="Fouet-cuisant",s="Dans le Gouffre grouillant, l’éclaireur de Hadoken Swiftstrider a découvert un insecte bien plus grand que les autres.",h="Dans le Gouffre grouillant, l’éclaireur de Hadoken Swiftstrider a découvert un insecte bien plus grand que...",kw={"camp mojache","féralas","glandes","hadoken swiftstrider","insecte","fouet-cuisant","gouffre grouillant","zukk’ash"},sec={{t="Un géant parmi les insectes",b="Un éclaireur a découvert un insecte géant qui erre sur le terrain tourmenté du Gouffre grouillant. Il semble dégager une aura différente de celle des autres, et Hadoken Swiftstrider l’a baptisé Fouet-cuisant. Hadoken veut que ses glandes sécrétoires soient rapportées directement au Camp Mojache. En étudiant les entrailles de l’insecte, Hadoken espère découvrir comment faire face à cette nouvelle menace."},{t="Les remerciements de Hadoken",b="Hadoken Swiftstrider est impressionné par votre travail. Si Fouet-cuisant compte parmi les insectes les plus puissants, son étude pourrait se révéler précieuse. Hadoken doit défendre le camp assez longtemps pour en profiter. Au nom de tout le camp, Hadoken vous offre une prime en pièces."}},faq={{q="Qui vous envoie traquer Fouet-cuisant ?",a="Hadoken Swiftstrider, au Camp Mojache en Féralas, vous envoie traquer Fouet-cuisant.",al={"donneur de quête","qui donne la quête de fouet-cuisant","hadoken swiftstrider"}},{q="Où trouve-t-on Fouet-cuisant ?",a="Fouet-cuisant erre sur le terrain tourmenté du Gouffre grouillant.",al={"emplacement de fouet-cuisant","où trouver fouet-cuisant","emplacement du gouffre grouillant"}},{q="Qu’est-ce qui distingue Fouet-cuisant des autres insectes ?",a="Un éclaireur rapporte que Fouet-cuisant est bien plus grand que les autres insectes et semble dégager une aura qu’ils n’ont pas.",al={"pourquoi fouet-cuisant","qu’est-ce que fouet-cuisant","aura de fouet-cuisant"}},{q="Pourquoi Hadoken veut-il les glandes de Fouet-cuisant ?",a="Hadoken veut les glandes de Fouet-cuisant afin d’étudier ses entrailles et de trouver un plan pour contrer cette nouvelle menace.",al={"pourquoi récupérer les glandes","utilité des glandes de fouet-cuisant"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="Le rapport sur les Zukk'ash",s="Au Camp Mojache, Hadoken Swiftstrider affirme que vos efforts contre les Zukk'ash ont été deux fois plus efficaces, même si le danger persiste. Il vous demande de porter le rapport du camp à Zilzibin Drumlore, à Orgrimmar.",h="Au Camp Mojache, Hadoken Swiftstrider affirme que vos efforts contre les Zukk'ash ont été deux fois plus...",kw={"camp mojache","la herse","féralas","hadoken swiftstrider","orgrimmar","silithides","zilzibin drumlore","rapport sur les zukk'ash"},sec={{t="Un document pour la Herse",b="Hadoken Swiftstrider possède un document sur ce que le Camp Mojache a appris au sujet des insectes Zukk'ash. Ils restent dangereux, alors il vous demande de porter le rapport à Orgrimmar. Zilzibin Drumlore vit à la Herse et connaît bien les créatures extraterrestres de ce genre. Hadoken espère que les découvertes du camp se révéleront utiles."},{t="L'avis de l'expert",b="Zilzibin Drumlore attendait le rapport. Il qualifie les créatures que vous avez affrontées de menace ancienne que la Horde continue d'ignorer. Hadoken a eu raison d'envoyer le document et vous-même. Zilzibin identifie les Zukk'ash comme des silithides. Certains les considèrent comme une nuisance sans cervelle, mais il affirme qu'ils menacent la Horde plus que l'Alliance ne le pourrait."}},faq={{q="Qui envoie le rapport à Orgrimmar ?",a="Hadoken Swiftstrider vous remet le document au Camp Mojache, en Féralas.",al={"qui remet le rapport sur les zukk'ash","qui donne la quête rapport sur les zukk'ash","donneur de quête"}},{q="À qui le rapport est-il remis ?",a="Vous remettez le rapport à Zilzibin Drumlore, qui vit à la Herse, à Orgrimmar.",al={"où va le rapport","qui reçoit le rapport sur les zukk'ash","emplacement de drumlore"}},{q="Pourquoi porter le document à Orgrimmar ?",a="Hadoken espère que Zilzibin Drumlore pourra utiliser les découvertes du camp. Zilzibin est un expert des créatures extraterrestres comme les Zukk'ash.",al={"pourquoi l'envoyer à orgrimmar","but du rapport"}},{q="Que s'est-il passé avant cette livraison ?",a="Cette livraison fait suite à vos efforts contre les insectes Zukk'ash dans les quêtes Infestation des Zukk'ash et Dardeur.",al={"quêtes précédentes","conditions préalables"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="Qualité améliorée",s="Dans le nord de Féralas, Pratt McGrubben veut des peaux de yéti plus résistantes du Repaire des Griffes féroces. Il vous demande d’en apporter dix au Bastion de Pennelune.",h="Dans le nord de Féralas, Pratt McGrubben veut des peaux de yéti plus résistantes du Repaire des Griffes...",kw={"bastion de pennelune","féralas","qualité améliorée","pratt mcgrubben","repaire des griffes féroces","thorium","peau de yéti","yétis"},sec={{t="Une bande de yétis plus coriaces",b="Après The Mark of Quality, Pratt McGrubben a trouvé des peaux de meilleure qualité. Une bande de yétis plus coriaces vit dans le Repaire des Griffes féroces, au nord de Féralas. Apportez dix peaux à Pratt, au Bastion de Pennelune, et il vous paiera grassement. Si ces peaux égalent celles de Feral Scar, elles pourraient se révéler aussi résistantes que le thorium."},{t="Les remerciements de Pratt",b="Les peaux du Repaire des Griffes féroces sont meilleures que Pratt McGrubben ne l’espérait. Il voit qu’elles deviendront bien plus dures une fois correctement tannées. Pour vous remercier, il vous offre l’une de ses dernières créations."}},faq={{q="Qui demande les peaux de yéti du Repaire des Griffes féroces ?",a="Pratt McGrubben vous demande des peaux de yéti du Repaire des Griffes féroces, au Bastion de Pennelune, en Féralas.",al={"qui donne qualité améliorée","donneur de quête qualité améliorée","pratt mcgrubben"}},{q="Où vivent les yétis du Repaire des Griffes féroces ?",a="Les yétis du Repaire des Griffes féroces vivent dans le Repaire des Griffes féroces, au nord de Féralas.",al={"emplacement des yétis du repaire des griffes féroces","où se trouve le repaire des griffes féroces","où trouver les peaux du repaire des griffes féroces"}},{q="Combien de peaux sont demandées ?",a="Pratt McGrubben veut dix peaux de yéti du Repaire des Griffes féroces.",al={"combien de peaux de yéti","objets requis pour qualité améliorée"}},{q="Quelle quête a précédé celle-ci ?",a="Cette quête fait suite à The Mark of Quality, où vous vous êtes occupé de la première bande de yétis.",al={"quête prérequise","quelle quête mène à qualité améliorée","quête précédente"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="Qualité améliorée",s="Au Camp Mojache, Jangdor Swiftstrider cherche désormais les peaux plus fines des yétis plus coriaces du Repaire des Griffes féroces.",h="Au Camp Mojache, Jangdor Swiftstrider cherche désormais les peaux plus fines des yétis plus coriaces du...",kw={"camp mojache","féralas","qualité améliorée","jangdor swiftstrider","repaire des griffes féroces","yéti de rage scar","peaux de yéti"},sec={{t="Une harde de yétis plus coriaces",b="Après The Mark of Quality, Jangdor Swiftstrider a trouvé une meilleure source de peaux. Des yétis plus coriaces rôdent au Repaire des Griffes féroces, dans le nord de Féralas. Rapportez dix peaux au Camp Mojache, et Jangdor vous paiera grassement. Si elles égalent celles de Feral Scar, elles pourraient s'avérer aussi résistantes que le thorium."},{t="Les remerciements de Jangdor",b="Les peaux dépassent les attentes de Jangdor Swiftstrider. Une fois correctement tannées, elles seront bien plus dures, il peut déjà le dire. En guise de remerciement, il vous offre l'une de ses dernières créations."}},faq={{q="Qui demande les peaux des yétis de Rage Scar ?",a="Jangdor Swiftstrider demande dix peaux de yétis de Rage Scar au Camp Mojache, à Féralas.",al={"qui donne qualité améliorée","donneur de quête qualité améliorée","jangdor swiftstrider"}},{q="Où vivent les yétis de Rage Scar ?",a="Les yétis de Rage Scar vivent au Repaire des Griffes féroces, dans le nord de Féralas.",al={"emplacement des yétis de rage scar","où se trouve le repaire des griffes féroces","où trouver les peaux de rage scar"}},{q="Combien de peaux sont demandées ?",a="Jangdor Swiftstrider veut dix peaux de yétis de Rage Scar.",al={"combien de peaux de yéti","objets requis pour qualité améliorée"}},{q="Quelle quête précède celle-ci ?",a="Cette quête suit The Mark of Quality, où vous vous êtes occupé de la première harde de yétis.",al={"quête prérequise","quelle quête mène à qualité améliorée","quête précédente"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Une peau de yéti en parfait état",s="En Féralas, une peau des yétis de Rage Scar pourrait intéresser Pratt McGrubben. Elle est exceptionnellement épaisse et résistante, et Pratt cherche à acheter des peaux de yéti.",h="En Féralas, une peau des yétis de Rage Scar pourrait intéresser Pratt McGrubben.",kw={"bastion de pennelune","féralas","pratt mcgrubben","peau de yéti en parfait état","rage scar","fourrure de yéti"},sec={{t="Une peau hors du commun",b="Parmi les peaux des yétis de Rage Scar, celle-ci est exceptionnellement épaisse et robuste. Pratt McGrubben cherche à acheter des peaux de yéti au Bastion de Pennelune, en Féralas. Cette peau pourrait donc l’intéresser."},{t="La réaction de Pratt",b="Pratt est émerveillé par la peau et se demande si une peau de yéti pourrait être encore plus belle. Il en offre plus que le prix habituel d’une peau, car il pense qu’on pourrait en faire quelque chose de spécial."}},faq={{q="Qui veut la peau de yéti en parfait état ?",a="Pratt McGrubben cherche à acheter des peaux de yéti au Bastion de Pennelune, en Féralas.",al={"qui prend la peau de yéti en parfait état","où apporter la peau de yéti","pratt mcgrubben peau de yéti"}},{q="Qu’est-ce qui rend cette peau spéciale ?",a="Comparée aux peaux des yétis de Rage Scar, celle-ci est exceptionnellement épaisse et résistante.",al={"origine de la peau de yéti en parfait état","qu’est-ce qui rend la peau spéciale","peau de yéti de féralas"}},{q="Où se trouve Pratt McGrubben ?",a="Pratt McGrubben se trouve au Bastion de Pennelune, en Féralas.",al={"où se trouve pratt mcgrubben","où apporter la peau de yéti en parfait état"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="Réapprovisionnement en flux embrasé (Sang-royal)",s="Dans la Gorge des Vents brûlants, le Maître forgeron Burninate manque de flux embrasé après What the Flux?. Il vous demande des écailles d'incendosaure, du Sang-royal et du charbon, et accepte tout ce que vous pourrez lui offrir.",h="Dans la Gorge des Vents brûlants, le Maître forgeron Burninate manque de flux embrasé après What the Flux?.",kw={"burninate","charbon","flux embrasé","incendosaure","sang-royal","gorge des vents brûlants","confrérie du thorium"},sec={{t="Flux embrasé recherché",b="Le Maître forgeron Burninate n'a guère de temps à perdre en bavardages. Ses réserves de flux embrasé s'épuisent. Il vous demande deux écailles d'incendosaure, quatre Sangs-royals et du charbon. Il prendra tout ce que vous pourrez lui offrir."}},faq={{q="Qui demande ces marchandises ?",a="Le Maître forgeron Burninate demande ces marchandises dans la Gorge des Vents brûlants et les reçoit en personne.",al={"qui donne cette quête","flux embrasé burninate","où rendre la quête"}},{q="Quels matériaux Burninate demande-t-il ?",a="Burninate veut deux écailles d'incendosaure, quatre Sangs-royals et du charbon.",al={"objets nécessaires","matériaux pour le flux embrasé","objets à remettre à burninate"}},{q="Quelle quête précède cette demande ?",a="What the Flux? précède cette demande, et Burninate vous l'a confiée.",al={"prérequis de cette quête","quête précédente flux embrasé","prérequis what the flux"}},{q="Pourquoi Burninate veut-il ces marchandises ?",a="Burninate dit que les réserves de flux embrasé s'épuisent et veut les reconstituer.",al={"pourquoi le flux embrasé","motivation de burninate"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="Une peau de yéti parfaite",s="Au Camp Mojache, Jangdor Swiftstrider achète des peaux de yéti, et l’une des vôtres est peut-être parfaite. Elle est plus épaisse et plus résistante que celles des yétis de Rage Scar.",h="Au Camp Mojache, Jangdor Swiftstrider achète des peaux de yéti, et l’une des vôtres est peut-être parfaite.",kw={"camp mojache","féralas","jangdor swiftstrider","peau de yéti parfaite","rage scar","peau de yéti"},sec={{t="Une peau qui mérite d’être montrée",b="La peau semble plus épaisse et plus solide que celles des yétis de Rage Scar. Jangdor Swiftstrider, au Camp Mojache en Féralas, achète des peaux de yéti. Celle-ci mérite de lui être apportée."},{t="Le verdict de Jangdor",b="Jangdor Swiftstrider se réjouit de la peau et la qualifie de plus belle qu’il ait jamais vue. Il en offre davantage que d’habitude pour une peau, certain de pouvoir en faire quelque chose de spécial."}},faq={{q="Qui s’intéresse à la peau de yéti parfaite ?",a="Jangdor Swiftstrider, au Camp Mojache en Féralas, veut acheter des peaux de yéti.",al={"qui veut la peau","à qui remettre la peau de yéti parfaite","peau de yéti jangdor"}},{q="Pourquoi cette peau est-elle si spéciale ?",a="Son épaisseur et sa résistance inhabituelles la distinguent des peaux des yétis de Rage Scar.",al={"pourquoi est-elle parfaite","qu’est-ce qui rend la peau spéciale"}},{q="Où se trouve Jangdor Swiftstrider ?",a="Jangdor Swiftstrider se trouve au Camp Mojache, en Féralas.",al={"où se trouve jangdor swiftstrider","où apporter la peau de yéti parfaite"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="Un voyage aux Pitons-du-Tonnerre",s="Après les Rites of the Earthmother, les esprits vous envoient de Mulgore aux Pitons-du-Tonnerre. Cairne Sabot-de-Sang, grand chef des taurens, vous y attend.",h="Après les Rites of the Earthmother, les esprits vous envoient de Mulgore aux Pitons-du-Tonnerre.",kw={"esprit ancestral","cairne sabot-de-sang","high rise","un voyage aux pitons-du-tonnerre","mulgore","rites of the earthmother","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous constatez le respect mutuel entre ses peuples lorsque les taurens accueillent les races alliées qui accomplissent leurs traditions sacrées.",["race:Tauren"]="Jeune tauren, vous tenir devant Cairne Sabot-de-Sang après les rites de la Terre-mère marque votre entrée dans l’âge adulte et vous vaut l’honneur de votre tribu."},sec={{t="L’ultime épreuve achevée",b="Dans tout Mulgore, les Rites of the Earthmother mettent à l’épreuve votre force, votre vision et votre sagesse. Les épreuves vous font traverser les plaines et les sites ancestraux de la région. Lorsque l’Esprit ancestral reconnaît votre rite final, vous avez prouvé que vous méritez d’entrer aux Pitons-du-Tonnerre comme défenseur du peuple tauren."},{t="Ascension vers High Rise",b="Depuis la terre sacrée où errent les esprits, vous prenez de la hauteur vers les Pitons-du-Tonnerre. La cité couronne des mesas de roche rouge, reliées par des ponts de corde et de grands ascenseurs en bois. Cairne Sabot-de-Sang, grand chef des taurens, vous attend à High Rise, prêt à accueillir ceux qui ont suivi la voie des ancêtres."}},faq={{q="Qui vous envoie en voyage ?",a="Un Esprit ancestral vous envoie après l’accomplissement du Rite of Wisdom, dernière étape des traditionnels Rites of the Earthmother.",al={"qui donne la quête","quête de l’esprit ancestral","donneur de quête"}},{q="Où trouver Cairne Sabot-de-Sang ?",a="Cairne Sabot-de-Sang vous attend à High Rise, la mesa centrale des Pitons-du-Tonnerre, au-dessus des plateaux rouges et des plaines.",al={"emplacement de cairne","où est cairne","chef des pitons-du-tonnerre"}},{q="Que signifie l’accomplissement de cette quête ?",a="Atteindre Cairne marque la fin officielle de vos premières aventures dans Mulgore. Les dirigeants taurens vous reconnaissent, et vous êtes prêt à servir la Horde partout où elle aura besoin de vous.",al={"pourquoi rendre visite à cairne","sens des rites","importance du voyage aux pitons-du-tonnerre"}},{q="Seuls les taurens accomplissent-ils ce voyage ?",a="Ce voyage est un rite de passage traditionnel des taurens. Tout membre de la Horde qui prouve son dévouement en accomplissant les Rites of the Earthmother reçoit le même honneur et est envoyé rencontrer le grand chef.",al={"les orcs peuvent-ils faire ce voyage","qui peut aller aux pitons-du-tonnerre","races"}},{q="Que se passe-t-il après avoir parlé à Cairne ?",a="Cairne vous accueille chez lui et reconnaît vos exploits. Il vous oriente vers les conflits plus vastes auxquels la Horde fait face dans Kalimdor.",al={"quête suivante","que faire après cairne","après un voyage aux pitons-du-tonnerre"}},{q="Comment rejoindre High Rise aux Pitons-du-Tonnerre ?",a="Prenez les grands ascenseurs mécaniques depuis les plaines jusqu’aux mesas. Puis traversez les ponts de corde et de bois pour rejoindre la plateforme centrale de High Rise, où se trouve la loge du chef.",al={"rejoindre high rise","comment rejoindre cairne","ascenseurs des pitons-du-tonnerre"}}},fx={["74afb15b"]={q="Pourquoi l'Esprit ancestral vous envoie-t-il aux Pitons-du-Tonnerre ?",a="En survivant aux épreuves à travers Mulgore et en communiant avec les esprits, vous avez prouvé votre sagesse, votre force et votre dévotion à travers les Rites of the Earthmother. L'Esprit ancestral vous dirige vers les Pitons-du-Tonnerre afin que vos actes puissent être reconnus par le peuple tauren et leur plus haut dirigeant, Cairne Sabot-de-Sang. Se tenir devant le chef suprême marque votre acceptation formelle dans leur société en tant que champion honoré.",al={"pourquoi l'esprit ancestral vous envoie","motivation esprit ancestral","pourquoi aller voir cairne"}},c86a41a9={q="Pourquoi devez-vous annoncer la nouvelle à Cairne Sabot-de-Sang vous-même ?",a="Les Rites of the Earthmother sont une épreuve personnelle sacrée. L'Esprit ancestral est un guide d'un autre monde lié aux terres saintes de Mulgore, incapable et peu désireux de porter des rapports terrestres. Parce que ce sont votre esprit et votre détermination qui ont été testés, l'honneur de vous présenter au chef suprême Cairne Sabot-de-Sang vous appartient uniquement.",al={"pourquoi moi cairne","pourquoi dois-je rendre visite à cairne","pourquoi dois-je voir cairne sabot-de-sang"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="Les rites de la Terre-mère",s="Le grand chef Cairne Sabot-de-Sang vous envoie à travers Mulgore sur les traces du grand kodo Arra'chea. Même après les anciens rites, il demande à son peuple de prouver à nouveau sa force, son talent de pisteur et son dévouement. La corne d'Arra'chea montre à Cairne que vous êtes prêt à servir la Horde dans son ensemble.",h="Le grand chef Cairne Sabot-de-Sang vous envoie à travers Mulgore sur les traces du grand kodo Arra'chea.",kw={"arra'chea","sabot-de-sang","cairne","terre-mère","corne","chasse","kodo","mulgore","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, vous traquez un colosse solitaire et vagabond à travers les plaines dorées. Les maîtres pisteurs taurens transmettent cette ancienne méthode de chasse de génération en génération.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à fournir aux Pitons-du-Tonnerre nourriture, cuir et matériaux en abattant Arra'chea. Cette chasse témoigne de la lutte commune pour survivre qui soutient la jeune Horde.",["race:Tauren"]="En tant que jeune shu'halo, vous vous présentez devant Cairne Sabot-de-Sang pour lui apporter la corne d’Arra'chea. Ce rite prouve que votre prouesse fait honneur à vos ancêtres et aux troupeaux de Mulgore."},sec={{t="À l’épreuve du chef",b="À Pitons-du-Tonnerre, l’enfance d’un jeune tauren cède la place au devoir. Le grand chef Cairne Sabot-de-Sang demande aux jeunes chasseurs de continuer à faire leurs preuves. Atteindre les hautes falaises marque le début d’une vie au service des tribus unies des taurens. Cairne demande plus qu’une chasse aux petites nuisances : il veut une preuve de savoir-faire sur le terrain, montrée par le pistage et le dépeçage propre de l’une des célèbres bêtes errantes de Mulgore."},{t="La chasse à Arra'chea",b="Arra'chea est un kodo massif et légendaire, dont le parcours en boucle traverse les herbes dorées au nord-est des Pitons-du-Tonnerre. Abattre cette grande bête exige de la patience pour la traquer dans la savane ouverte, et pas seulement de la force brute. Rapportez la corne d’Arra'chea au sommet de High Rise, et Cairne envoie des écorcheurs et des ramasseurs utiliser chaque partie de la bête sacrée pour ravitailler la ville."}},faq={{q="Qui donne cette quête ?",a="Le grand chef Cairne Sabot-de-Sang vous confie cette chasse depuis son siège au sommet de High Rise, aux Pitons-du-Tonnerre.",al={"donneur de quête","qui donne les rites de la terre-mère","quête de cairne"}},{q="Qu’est-ce qu’Arra'chea ?",a="Arra'chea est un kodo réputé qui parcourt les plaines de Mulgore. Sa grande corne prouve le talent de pisteur et la prouesse martiale d’un chasseur.",al={"qui est arra'chea","qu'est-ce qu'arra'chea","histoire d'arra'chea"}},{q="Où trouver Arra'chea ?",a="Arra'chea suit un vaste parcours circulaire au nord-est des falaises des Pitons-du-Tonnerre, faisant le tour des plaines ouvertes dans le sens des aiguilles d’une montre.",al={"où se trouve arra'chea","emplacement d'arra'chea","parcours d'arra'chea"}},{q="Pourquoi Cairne me demande-t-il cette chasse alors que j’ai déjà accompli les rites précédents ?",a="Pour les taurens, obtenir une première place n’est que le début du devoir. Cairne vous demande de continuer à prouver votre force, votre humilité et votre talent de chasseur au service de la tribu.",al={"pourquoi faire cette quête","pourquoi tuer arra'chea","but des rites"}},{q="Que devient le corps d’Arra'chea après qu’on lui a pris sa corne ?",a="Cairne envoie un groupe de ramasseurs récupérer la viande et la peau d’Arra'chea. La dépouille nourrit et vêt les habitants des Pitons-du-Tonnerre, car la tradition tauren leur enseigne à honorer leurs proies.",al={"viande d'arra'chea","que devient le kodo","histoire de la dépouille"}},{q="Est-ce la même quête que les rites de départ ?",a="Non. Les premières épreuves au Camp Narache enseignent à l’initié les rites fondamentaux des rites de la Terre-mère. Cette chasse aux Pitons-du-Tonnerre est l’épreuve personnelle de Cairne, qui évalue si vous méritez toujours votre place comme chasseur.",al={"différences entre les rites de la terre-mère","quelle quête des rites","rites du camp narache"}}},fx={d7a516d7={q="À quoi sert la Corne d'Arra'chea ?",a="La corne sert de preuve physique de votre succès à la chasse. La tradition tauren accorde un grand honneur aux compétences de pistage et de mise à mort de bêtes puissantes, et présenter la Corne d'Arra'chea directement au chef suprême Cairne Sabot-de-Sang prouve que vous possédez les prouesses nécessaires pour nourrir et protéger votre peuple.",al={"utilisation corne d'arra'chea","pourquoi prendre la corne d'arra'chea","but de la corne d'arra'chea"}},a7e696eb={q="Pourquoi Cairne Sabot-de-Sang vous envoie-t-il vous plutôt que les gardes de la ville ?",a="Cette chasse n'est pas une commission de défense ou une simple collecte de ressources ; il s'agit d'une épreuve traditionnelle. Bien que vous ayez pu passer les Rites of the Earthmother initiaux pour atteindre les Pitons-du-Tonnerre, Cairne attend de chaque chasseur de la tribu qu'il prouve continuellement sa valeur et son autonomie par de grandes actions plutôt que de se reposer sur ses accomplissements passés.",al={"pourquoi m'envoyer","pourquoi ne pas envoyer de gardes pour arra'chea","pourquoi cairne a besoin de moi"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="Grandes difficultés",s="À couvert, Lucien Tosselwrench vous attend pendant que vous portez la roue dentée nº 5 à Lotwil Veriatus.",h="À couvert, Lucien Tosselwrench vous attend pendant que vous portez la roue dentée nº 5 à Lotwil Veriatus.",kw={"terres ingrates","roue dentée 5","lotwil veriatus","lucien tosselwrench","entraves","ça va être difficile"},sec={{t="À couvert",b="Lucien Tosselwrench vous remet la roue dentée pour Lotwil Veriatus. Puis il attend à couvert et vous invite à le rejoindre. À votre arrivée, Lotwil est toujours penché sur les entraves. Sans lever les yeux, il tend la main et agite les doigts pour réclamer la roue dentée."},{t="Écrire l’histoire",b="Lotwil prend la roue dentée et la trouve parfaite. Il vous demande de reculer pendant qu’il se prépare à écrire encore l’histoire. Puis il reprend son travail fébrilement."}},faq={{q="Qui vous remet la roue dentée pour Lotwil ?",a="Lucien Tosselwrench vous remet la roue dentée nº 5 à porter à Lotwil Veriatus.",al={"qui remet la roue dentée","où trouver la roue dentée 5","roue dentée de lucien"}},{q="Où va Lucien ?",a="Lucien se met à couvert et vous invite à le rejoindre.",al={"pourquoi lucien se cache","lucien à couvert"}},{q="Que fait Lotwil quand vous lui apportez la roue dentée ?",a="Lotwil travaille sur des entraves. Sans lever les yeux, il tend la main et agite les doigts avec impatience pour réclamer la roue dentée.",al={"que fait lotwil","entraves de lotwil","avancement de lotwil"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="Ça promet d'être dur",s="Dans les Terres Ingrates, Lotwil Veriatus est prêt à invoquer un puissant élémentaire.",h="Dans les Terres Ingrates, Lotwil Veriatus est prêt à invoquer un puissant élémentaire.",kw={"terres ingrates","élémentaire","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},sec={{t="Un jour historique",b="Lotwil annonce que les entraves sont terminées. Le moment est venu. Il vous demande d’assister à l’invocation avec Lucien et Servo. Les entraves allient alchimie, ingénierie et arcanes, et Lotwil s’attend à ce qu’un puissant élémentaire réponde à l’appel en ce jour historique."},{t="Après l’invocation",b="L’invocation ne se déroule pas comme Lotwil l’espérait. Après avoir vaincu le Fam'retor Guardian, Lotwil vous demande de rapporter les Shackles of Elemental Binding. Il ne peut pas dire ce qui a mal tourné. Il est toutefois heureux que les enchantements aient été prêts à renvoyer la créature dans son propre plan."}},faq={{q="Qui est Lotwil Veriatus ?",a="Lotwil Veriatus a fabriqué les Shackles of Elemental Binding en alliant alchimie, ingénierie et arcanes. Lucien et Servo sont avec lui dans les Terres Ingrates.",al={"qui est lotwil","lotwil veriatus"}},{q="Que sont les Shackles of Elemental Binding ?",a="Les Shackles of Elemental Binding allient alchimie, ingénierie et arcanes. Lotwil vient de les terminer pour le puissant élémentaire qu’il compte invoquer.",al={"que sont les entraves","shackles of elemental binding"}},{q="Qui Lotwil appelle-t-il comme témoin ?",a="Lotwil demande à Lucien et Servo d’assister à l’invocation avec vous.",al={"qui est lucien","qui est servo"}},{q="Que se passe-t-il avant cette étape ?",a="Auparavant, vous avez apporté le rouage n° 5 à Lotwil.",al={"quête précédente","ce qui a mené à cela"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="Le seigneur de Rochenoire",s="La tête tranchée de Nefarian arrive au Donjon de Hurlevent après sa défaite au Repaire de l'Aile noire. Le Généralissime Bolvar Fordragon la reçoit comme preuve que le maître du Mont Rochenoire est tombé. Cette victoire compte parmi les plus grands triomphes militaires récents de l'Alliance.",h="La tête tranchée de Nefarian arrive au Donjon de Hurlevent après sa défaite au Repaire de l'Aile noire.",kw={"mont rochenoire","repaire de l'aile noire","généralissime bolvar fordragon","tête de nefarian","seigneur de rochenoire","nefarian","donjon de hurlevent"},ang={["faction:Alliance"]="Pour l'Alliance, présenter la tête de Nefarian est un haut fait militaire. Cela anéantit les complots du Vol draconique contre les terres humaines.",["race:Human"]="En tant qu'humain, vous savez que le Mont Rochenoire a envoyé d'innombrables incursions et complots contre Hurlevent. La défaite de son maître apporte au royaume une revanche attendue depuis longtemps et un soulagement bienvenu."},sec={{t="Un monument à la victoire",b="Nefarian, maître des couvées du Vol draconique noir et souverain du haut du Pic Rochenoire, menace depuis longtemps les royaumes humains voisins. Sa défaite met fin à ses expériences dévoyées et à ses complots. Sa tête, balafrée par les combats, est rapportée à Hurlevent. Elle prouve que les plus grands héros de l'Alliance ont vaincu le seigneur de Rochenoire."},{t="Audience au Donjon de Hurlevent",b="Le Généralissime Bolvar Fordragon gouverne le royaume depuis la salle du trône du Donjon de Hurlevent. La tête tranchée du dragon choque la cour royale et lui impose le respect. Le royaume fait face à des conflits politiques internes et à des menaces extérieures. Cette victoire remonte le moral et entre dans l'histoire de l'Alliance."}},faq={{q="En quoi consiste la quête Le seigneur de Rochenoire ?",a="Vous récupérez la tête tranchée de Nefarian au Repaire de l'Aile noire et la rapportez à Hurlevent. Là, vous présentez le trophée au Généralissime Bolvar Fordragon au nom du royaume.",al={"quête du seigneur de rochenoire","quête de la tête de nefarian pour l'alliance","tête de nefarian à hurlevent"}},{q="Qui est Nefarian ?",a="Nefarian est un puissant dragon noir et le fils d'Aile de mort. Il règne depuis le Repaire de l'Aile noire, au Mont Rochenoire, commande les orcs de Blackrock et mène de sinistres expériences pour créer le Vol draconique chromatique.",al={"qui est nefarian","seigneur de rochenoire","histoire de nefarian"}},{q="Qui est le Généralissime Bolvar Fordragon ?",a="Le Généralissime Bolvar Fordragon est le paladin qui dirige Hurlevent en tant que régent, pendant l'absence du roi Varian Wrynn. Il tient audience dans la salle du trône du Donjon de Hurlevent et veille sur le jeune prince Anduin Wrynn.",al={"bolvar fordragon","qui est bolvar","généralissime bolvar"}},{q="Pourquoi apporter ce trophée au Donjon de Hurlevent ?",a="Le règne de Nefarian au Mont Rochenoire menace Hurlevent et tout le continent méridional. Apporter sa tête aux chefs militaires du royaume confirme sa défaite et donne au royaume une victoire autour de laquelle se rassembler.",al={"pourquoi hurlevent","pourquoi apporter la tête au donjon","pourquoi bolvar"}},{q="Que se passe-t-il après avoir remis la tête à Bolvar ?",a="Le Généralissime Bolvar Fordragon est stupéfait et déclare que ce triomphe restera dans l'histoire. La tête est ensuite exposée publiquement aux yeux de tous les habitants de Hurlevent.",al={"que se passe-t-il ensuite","seigneur de rochenoire partie deux","remise de la tête de nefarian"}},{q="La remise de cette tête a-t-elle un effet sur toute la ville ?",a="Oui. La tête de Nefarian est apportée dans la capitale et dressée au-dessus des portes de la ville. Elle annonce la mort du dragon aux citoyens et aux soldats, et renforce la détermination des défenseurs de Hurlevent.",al={"bonus de ville","cri de ralliement","bonus de la tête de nefarian"}}},fx={["150c64a2"]={q="Pourquoi est-il important d'apporter la Tête de Nefarian à Hurlevent ?",a="Nefarian était le dragon noir qui orchestrait les menaces depuis le Pic Rochenoire, manipulant les royaumes mortels et forgeant des armées monstrueuses juste aux portes de Hurlevent. Livrer sa tête coupée au Généralissime Bolvar Fordragon est la preuve irréfutable que la terreur de la couvée a été brisée, offrant à l'Alliance une victoire monumentale à célébrer et à exposer devant le royaume.",al={"pourquoi apporter la tête de nefarian à hurlevent","motivation tête de nefarian","pourquoi livrer la tête de nefarian"}},["7e2ee731"]={q="Pourquoi devez-vous porter la tête à Hurlevent plutôt que les gardes royaux ?",a="Vous et vos compagnons vous êtes frayé un chemin à travers le Repaire de l'Aile noire et avez abattu le seigneur dragon vous-mêmes. Rapporter le trophée macabre au Donjon de Hurlevent est votre droit en tant que champions qui l'ont vaincu, garantissant que le Généralissime Bolvar Fordragon reçoive la nouvelle de première main des héros qui ont réellement terrassé la bête.",al={"pourquoi dois-je livrer la tête de nefarian","pourquoi pas les gardes royaux pour la tête de nefarian","pourquoi moi trophée de nefarian"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="Le seigneur de Rochenoire",s="Aux portes de Hurlevent, l’Alliance se rassemble pour célébrer sa victoire sur Rochenoire. Après avoir fait votre rapport au Grand amiral Jes-Tereth au Donjon de Hurlevent, les héros prennent la direction de la Vallée des héros. Le Grand maréchal Pont-de-Pierre est prête à mener la commémoration publique de la ville.",h="Aux portes de Hurlevent, l’Alliance se rassemble pour célébrer sa victoire sur Rochenoire.",kw={"rochenoire","tueur de dragon","nefarian","cri de ralliement","pont-de-pierre","hurlevent","vallée des héros"},ang={["class:Warrior"]="Le Cri de ralliement du tueur de dragon donne du courage aux combattants qui partent défendre le royaume.",["faction:Alliance"]="La tête de Nefarian dans la Vallée des héros rassemble les peuples de l’Alliance. Les citoyens de Forgefer, de Darnassus et de Gnomeregan voient que les forces obscures qui ravagent les Royaumes de l’est peuvent être vaincues.",["race:Human"]="Pour le royaume de Hurlevent, vaincre le maître de Rochenoire écarte une grave menace draconique de sa frontière nord."},sec={{t="Le triomphe d’une cité",b="La campagne contre le Clan Rochenoire et la couvée du Vol draconique noir prend fin publiquement. La tête tranchée de Nefarian est présentée au Donjon de Hurlevent. Puis le Généralissime Bolvar Fordragon envoie les champions à travers la ville jusqu’à la Vallée des héros. Le Grand maréchal Pont-de-Pierre les y attend pour recevoir le trophée et lancer les célébrations."},{t="Rassembler l’Alliance",b="Le Grand maréchal Pont-de-Pierre hisse la tête tranchée de Nefarian au-dessus des grandes arches de l’entrée principale de Hurlevent. Le spectacle se répand dans toute la ville, et le Cri de ralliement du tueur de dragon inspire les défenseurs, les dignitaires en visite et les citoyens. Tous savent que la couvée d'Aile de mort a subi un coup dévastateur."}},faq={{q="Que se passe-t-il quand vous terminez cette quête ?",a="Le Grand maréchal Pont-de-Pierre suspend la tête tranchée de Nefarian tout en haut de l’arche de pierre de la Vallée des héros. Puis le Cri de ralliement du tueur de dragon galvanise les combattants et les gardes alliés dans tout Hurlevent.",al={"remise de la quête tête de nefarian","que fait pont-de-pierre","déclenchement du cri de ralliement"}},{q="Qui est le Grand maréchal Pont-de-Pierre ?",a="Le Grand maréchal Pont-de-Pierre est une officier supérieur de l’armée de Hurlevent, postée dans la Vallée des héros près de l’entrée de la ville. Elle organise les commémorations publiques des victoires militaires, notamment l’exposition des têtes des ennemis draconiques vaincus.",al={"pont-de-pierre","grand maréchal pont-de-pierre"}},{q="Pourquoi le Généralissime Bolvar Fordragon vous envoie-t-il ici ?",a="Après avoir appris la défaite de Nefarian dans la salle du trône, le Généralissime Bolvar Fordragon vous envoie aux portes de la ville. Là, l’armée de l’Alliance peut afficher sa victoire au grand jour et remonter le moral de toute la capitale.",al={"bolvar","pourquoi aller à la vallée des héros"}},{q="Cette remise affecte-t-elle toute la ville ?",a="Oui. Quand Pont-de-Pierre reçoit le trophée, une proclamation retentit dans Hurlevent, et le Cri de ralliement du tueur de dragon atteint tous ceux qui se trouvent dans les limites de la ville.",al={"bonus mondial nefarian","hurlevent reçoit-il un bonus"}},{q="Où se trouve la Vallée des héros ?",a="La Vallée des héros est la grande chaussée qui mène à Hurlevent. De hautes statues la bordent, en hommage aux héros de la Deuxième guerre qui ont franchi la Porte des ténèbres.",al={"emplacement de la vallée des héros","où se trouve pont-de-pierre"}},{q="Qui était le « seigneur de Rochenoire » ?",a="Le dragon noir Nefarian était le seigneur de Rochenoire. Fils d'Aile de mort, il règne sur les flèches supérieures du Mont Rochenoire.",al={"qui est le seigneur de rochenoire","identité de nefarian"}}},fx={["3a42f3f3"]={q="Pourquoi Bolvar vous envoie-t-il vous au lieu d'y aller lui-même ?",a="Vous et vos compagnons étiez les champions qui ont bravé les hauteurs du Repaire de l'Aile noire et ont fait tomber Nefarian. En tant que vainqueur, l'honneur de présenter la tête coupée du dragon aux chefs militaires de Hurlevent et de déclencher le triomphe dans toute la ville vous appartient de droit.",al={"pourquoi m'envoyer","pourquoi pas bolvar","pourquoi dois-je livrer la tête"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="Le seigneur de Rochenoire",s="À Orgrimmar, la tête tranchée de Nefarian est présentée à Thrall comme preuve de victoire. Son arrivée marque la chute d'un grand ennemi de la Horde.",h="À Orgrimmar, la tête tranchée de Nefarian est présentée à Thrall comme preuve de victoire.",kw={"rochenoire","repaire de l'aile noire","deathwing","tueur de dragons","thrall","nefarian","orgrimmar","cri de ralliement"},ang={["class:Warrior"]="En tant que guerrier, vous gagnez une grande renommée martiale en portant l'énorme crâne tranché d'un seigneur dragon jusqu'au chef de guerre.",["faction:Horde"]="La chute de Nefarian rend son honneur à la Horde et libère la région de Rochenoire du dragon qui asservissait la Horde noire rebelle.",["race:Orc"]="En tant qu'orc, vous vengez les vôtres du monstre qui manipulait Rend Main-Noire et asservissait les clans orcs pour mener ses expériences, en présentant la tête de Nefarian à Thrall."},sec={{t="Un trophée de ruine",b="Nefarian est enfin tombé. Il dirigeait le Repaire de l'Aile noire et commandait la couvée des dragons noirs dans les Royaumes de l'est. Sa tête marquée par les combats prouve sa mort. Pour les guerriers de la Horde, rapporter ce trophée depuis les hauteurs brûlantes du Mont Rochenoire, par-delà La Grande mer jusqu'en Durotar, est un grand honneur."},{t="Le jugement du chef de guerre",b="Le trophée est présenté au chef de guerre Thrall, qui connaît bien la corruption du Mont Rochenoire. Il a libéré son peuple des camps d'internement et l'a éloigné de la soif de sang démoniaque de l'ancienne Horde. À présent, le fils d'Aile de mort est tombé et les orcs de Rochenoire sont libérés de la cruelle domination du dragon obscur."},{t="Les ombres du père",b="La mort de Nefarian met fin aux expériences perverses du Vol draconique noir, mais le danger demeure. En voyant la tête tranchée, Thrall déclare qu'Aile de mort s'agite sûrement à la nouvelle de la destruction de son fils. La victoire est réelle, mais des terreurs plus grandes dorment encore sous le monde."}},faq={{q="Qui est Nefarian ?",a="Nefarian est un grand dragon noir et le fils d'Aile de mort. Depuis son repaire au sommet du Mont Rochenoire, il menait des expériences perverses pour créer le Vol draconique chromatique. Il manipulait aussi les peuples mortels, en particulier la Horde noire, pour les faire agir selon sa volonté.",al={"histoire de nefarian","qui est nefarian","seigneur dragon noir"}},{q="Pourquoi le trophée est-il remis à Thrall ?",a="Thrall est le chef de guerre de la Horde. Il a mené les orcs hors des camps d'internement et les a éloignés de la soif de sang démoniaque de l'ancienne Horde. La preuve que le dragon qui a réduit en esclavage les orcs de Rochenoire et la Horde noire est tombé doit lui revenir.",al={"pourquoi thrall","qui reçoit la tête"}},{q="Que se passe-t-il à Orgrimmar quand la tête est remise ?",a="Quand la tête de Nefarian est rapportée et exposée à Orgrimmar, la ville célèbre l'événement. Les membres de la Horde à proximité reçoivent le Cri de ralliement du tueur de dragons, qui augmente leurs prouesses au combat.",al={"bonus de la tête","bonus mondial d'orgrimmar","bonus du cri de ralliement"}},{q="Cette quête a-t-elle un équivalent pour l'Alliance ?",a="Oui. Les héros de l'Alliance apportent la tête de Nefarian au Généralissime Bolvar Fordragon dans le Donjon de Hurlevent, ce qui confère la même bénédiction à leur ville.",al={"version de l'alliance","équivalent pour l'alliance"}},{q="Pourquoi Aile de mort est-il une source d'inquiétude ?",a="Aile de mort est le père de Nefarian et le patriarche du Vol draconique noir. Vaincre son fils n'écarte pas le danger que représente le père des dragons.",al={"l'être maléfique s'agite","qui est l'être maléfique"}},{q="D'où vient la tête ?",a="La Tête de Nefarian provient du cadavre de Nefarian, au sommet du Repaire de l'Aile noire, après sa défaite.",al={"comment obtenir la tête de nefarian","objet de départ de quête"}}},fx={d14146dc={q="Pourquoi la Tête de Nefarian doit-elle être apportée à Orgrimmar ?",a="Découper la tête massive et marquée par la bataille du dragon déchu fournit une preuve indéniable que le maître du Pic Rochenoire a été vaincu. Livrer un tel trophée monstrueux à Orgrimmar démontre la puissance suprême de la Horde, célèbre une victoire monumentale sur le Vol draconique noir et permet au conseil du Chef de guerre de vérifier que les expériences tordues de Nefarian au sein de la montagne ont enfin pris fin.",al={"pourquoi apporter la tête de nefarian","motivation tête de nefarian","pourquoi donner la tête à eitrigg"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="Le seigneur de Rochenoire",s="Devant la Horde, à Orgrimmar, la tête tranchée de Nefarian témoigne de sa défaite. Thrall confirme la mort du dragon noir, puis vous envoie auprès du Haut seigneur Saurfang, dans la Vallée de la Force, pour montrer le trophée à tous.",h="Devant la Horde, à Orgrimmar, la tête tranchée de Nefarian témoigne de sa défaite.",kw={"repaire de l'aile noire","thrall","tête de nefarian","saurfang","orgrimmar","nefarian","vallée de la force"},ang={["faction:Horde"]="Pour la Horde, l'exposition publique de Nefarian prouve la puissance de la Horde réformée face au dragon noir qui manipulait les orcs du Mont Rochenoire. Elle renforce le nouvel ordre de Thrall.",["race:Orc"]="En tant qu'orc, vous pouvez ressentir un profond soulagement à la chute du dragon qui tenait le Clan Rochenoire sous son emprise. Sa défaite lève une ombre déshonorante sur votre peuple."},sec={{t="Un trophée pour la Horde",b="La tête de Nefarian arrive à Orgrimmar après la chute du dragon noir au sommet du Repaire de l'Aile noire. Le chef de guerre Thrall confirme la mort du fils d'Aile de mort, puis vous envoie auprès du Haut seigneur Saurfang, dans la Vallée de la Force. Là, les restes sont préparés pour que tous puissent les voir. Ce trophée avertit les ennemis de la Horde et rallie la véritable Horde."},{t="Revendiquer l'héritage",b="Nefarian régnait sur les hauteurs du Mont Rochenoire, pliant les orcs de Rochenoire et la Horde noire à sa volonté. En l'abattant et en hissant sa tête dans la Vallée de la Force, la Horde de Thrall porte un coup puissant au Vol draconique noir. Saurfang appelle tout Orgrimmar à se réjouir du Cri de ralliement du tueur de dragon."}},faq={{q="Quel est le but de cette quête ?",a="Après avoir prouvé à Thrall la mort de Nefarian, vous faites votre rapport au Haut seigneur Saurfang, dans la Vallée de la Force, à Orgrimmar. La tête tranchée est exposée au public et vous recevez des honneurs.",al={"but de cette quête","rendre la quête le seigneur de rochenoire","pourquoi aller voir saurfang"}},{q="Qui est le Haut seigneur Saurfang ?",a="Le Haut seigneur Saurfang est un guerrier orc vétéran et l'un des plus grands champions de la Horde. Il est posté dans la Vallée de la Force, à Orgrimmar, où il reçoit la tête et la fait exposer à la vue de tous.",al={"qui est saurfang","rôle du haut seigneur saurfang"}},{q="Pourquoi la tête de Nefarian est-elle exposée ?",a="La tête empaillée de Nefarian prouve que le maître du Mont Rochenoire a été vaincu. Son exposition remonte le moral des défenseurs d'Orgrimmar, et tous les habitants de la ville reçoivent le Cri de ralliement du tueur de dragon.",al={"pourquoi exposer la tête de nefarian","tête de nefarian exposée à orgrimmar"}},{q="Qui était Nefarian ?",a="Nefarian était un puissant dragon noir et un fils d'Aile de mort. Depuis le Repaire de l'Aile noire, au sommet du Mont Rochenoire, il commandait les orcs de Rochenoire et la Horde noire, et créa le Vol draconique chromatique.",al={"qui était nefarian","histoire de nefarian"}},{q="Où se trouve le Haut seigneur Saurfang ?",a="Saurfang se trouve dans la Vallée de la Force, le quartier central à l'entrée d'Orgrimmar.",al={"où se trouve saurfang","emplacement de saurfang"}},{q="Quel est le rôle de Thrall dans cette affaire ?",a="Le chef de guerre Thrall reçoit d'abord la tête de Nefarian. Après avoir confirmé la mort du dragon, il vous envoie auprès de Saurfang pour faire exposer officiellement le trophée.",al={"pourquoi thrall","rôle de thrall"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="Un don de laine",s="À Darnassus, on collecte de l’Etoffe de laine pour approvisionner les réserves de la cité. Vos soixante pièces vous valent une reconnaissance pour votre générosité.",h="À Darnassus, on collecte de l’Etoffe de laine pour approvisionner les réserves de la cité.",kw={"darnassus","don","reconnaissance","réserves","laine","etoffe de laine"},sec={{t="Réserves de laine",b="Darnassus a besoin de soixante pièces d’Etoffe de laine de votre part. Les autres habitants du royaume devraient fournir le reste des réserves. Votre don vous vaut une pleine reconnaissance pour votre générosité."}},faq={{q="De quoi Darnassus a-t-elle besoin ?",a="Darnassus a besoin d’Etoffe de laine pour approvisionner ses réserves.",al={"don de laine","quelle étoffe veut darnassus"}},{q="Quelle quantité de laine dois-je donner ?",a="Vous devez donner soixante pièces d’Etoffe de laine.",al={"combien de laine","soixante pièces de laine"}},{q="Pourquoi Darnassus collecte-t-elle de la laine ?",a="Darnassus collecte de l’Etoffe de laine pour approvisionner ses réserves.",al={"pourquoi de la laine","collecte de laine"}},{q="Que me rapporte un don de laine ?",a="Votre don de soixante pièces vous vaut une pleine reconnaissance de Darnassus pour votre générosité.",al={"reconnaissance pour un don de laine","récompense pour un don de laine"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="La légende de Stalvan",s="Marshal Haggard vous envoie voir Smitts l'aubergiste, qui connaît peut-être l'auteur d'une page du journal de Stalvan Mantebrume.",h="Marshal Haggard vous envoie voir Smitts l'aubergiste, qui connaît peut-être l'auteur d'une page du journal de...",kw={"sombre-comté","bois de la pénombre","elwynn","journal","marshal haggard","mantebrume","scarlet raven tavern","stalvan","smitts l'aubergiste"},ang={["faction:Alliance"]="En tant que défenseur de l'Alliance, vous voyez les liens qui unissent les anciens gardes de Hurlevent aux gardiens de l'histoire locale, à travers le royaume de Hurlevent.",["race:Human"]="En tant qu'humain, vous voyez comment les tragédies d'Elwynn et de Sombre-Comté restent présentes dans la mémoire des habitants."},sec={{t="Une piste du marshal",b="Marshal Haggard ne parvient pas à lire l'écriture effacée sur la page de journal déchirée que vous avez trouvée dans son coffre, en Forêt d’Elwynn. Sa vue défaillante l'empêche de déchiffrer les mots. Il se souvient avoir servi dans la garde de Hurlevent et passé des soirées à la Scarlet Raven Tavern, à Sombre-Comté. Il vous envoie donc de l'autre côté de la rivière, auprès de Smitts l'aubergiste, dont les années derrière le comptoir ont fait un gardien de l'histoire et des rumeurs locales."},{t="Retour à la Scarlet Raven",b="Vous traversez les bois lugubres du Bois de la Pénombre et montrez la page décolorée à Smitts derrière le comptoir. Il est heureux d'avoir des nouvelles de son ancienne connaissance Haggard, même s'il déplore la santé déclinante du vétéran. Puis Smitts aperçoit le parchemin, et son air décontracté laisse place à l'inquiétude. Il reconnaît sans aucun doute cette écriture si particulière, rapprochant l'enquête de la vérité sur la folie de Stalvan Mantebrume."}},faq={{q="Pourquoi Marshal Haggard m'envoie-t-il à nouveau à Sombre-Comté ?",a="Marshal Haggard vieillit et voit presque tout noir, si bien qu'il ne peut examiner la page de journal retrouvée. Il se souvient que Smitts l'aubergiste connaît bien l'histoire locale depuis l'époque où il servait dans la garde de Hurlevent, et vous envoie lui demander d'identifier l'écriture.",al={"pourquoi aller à sombre-comté","haggard à sombre-comté","pourquoi smitts"}},{q="Où se trouve Smitts l'aubergiste ?",a="Smitts l'aubergiste tient le comptoir de la Scarlet Raven Tavern, dans l'est de Sombre-Comté, au Bois de la Pénombre.",al={"où se trouve smitts","emplacement de smitts","emplacement de la scarlet raven tavern"}},{q="Quel objet apportez-vous à Smitts l'aubergiste ?",a="Vous apportez une page de journal décolorée, un extrait du journal perdu de Stalvan Mantebrume, trouvé dans le coffre de pied de Marshal Haggard.",al={"quel objet","page de journal décolorée","page du journal de stalvan"}},{q="Smitts l'aubergiste reconnaît-il l'écriture ?",a="Oui. Smitts reconnaît l'écriture dès qu'il voit la page décolorée, et son inquiétude fournit une nouvelle piste dans la recherche de Stalvan Mantebrume.",al={"smitts reconnaît-il l'écriture","réaction de smitts au journal"}},{q="Comment Smitts connaît-il Marshal Haggard ?",a="Smitts a accueilli Haggard il y a des années, quand celui-ci dirigeait des patrouilles de la garde de Hurlevent au Bois de la Pénombre et venait boire à la Scarlet Raven Tavern.",al={"relation entre smitts et haggard","comment smitts connaît haggard"}},{q="Quelle est la prochaine étape dans la recherche de Stalvan ?",a="Apportez la page de journal décolorée à Smitts, à la Scarlet Raven Tavern, et suivez la piste qu'il vous indiquera.",al={"quelle est la suite","prochaine étape pour stalvan","suite de la quête de stalvan"}}},fx={bf062962={q="Pourquoi le Marshal Haggard veut-il que cela soit fait ?",a="Le Marshal Haggard ne peut pas lire la Page de journal fanée parce que sa vue baisse. Il se souvient de Smitts l'aubergiste comme d'une vieille connaissance ayant une solide connaissance de l'histoire locale, et vous demande de lui apporter la page à Sombre-Comté.",al={"pourquoi haggard veut-il que cela soit fait","motivation marshal haggard","pourquoi aider à trouver stalvan"}},c297959a={q="Pourquoi le Marshal Haggard vous envoie-t-il vous au lieu d'y aller lui-même ?",a="Haggard est un vieux marshal à la retraite vivant dans l'isolement, perdant rapidement la vue. Les routes à travers les bois sont dangereuses, et il manque tout simplement de jeunesse et d'endurance physique pour retourner à travers la frontière jusqu'au Bois de la Pénombre. Il compte sur un voyageur capable comme vous pour faire sa commission et montrer la Page de journal à sa vieille connaissance.",al={"pourquoi haggard ne peut-il pas y aller","pourquoi haggard a besoin de moi","pourquoi haggard ne rend-il pas visite à smitts"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="Les sangliers de guerre apprivoisés",s="Au camp Narache, les jeunes Taurens chassent les sangliers de guerre apprivoisés pour protéger leurs terres et nourrir les jeunes de la tribu.",h="Au camp Narache, les jeunes Taurens chassent les sangliers de guerre apprivoisés pour protéger leurs terres...",kw={"sanglier de guerre","ravin de roncelame","bristleback","camp narache","grull vent-du-faucon","mulgore","quilboar","mesa de nuage rouge"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez à distinguer la faune naturelle des bêtes que les Ronce-dos ont perverties pour en faire des armes de guerre.",["profession:Cooking"]="En tant que cuisinier, vous savez que même une viande coriace et dure peut devenir un ragoût nourrissant qui sustente la tribu.",["race:Tauren"]="En tant que Tauren, vous défendez les territoires de la Mère-Terre et ne gaspillez rien de ce que vous prenez au combat. Les bêtes de guerre des Ronce-dos deviennent de la nourriture pour les petits du camp."},sec={{t="Une menace à la frontière",b="À l’est de la mesa de Nuage rouge, le ravin de Roncelame est aux mains des quillboars Ronce-dos. Les tensions entre les Shu’halo et les quillboars ont dégénéré en guerre ouverte. Les Ronce-dos dressent de féroces sangliers de guerre apprivoisés pour éprouver les frontières taurens et troubler leurs anciens terrains de chasse. Sans intervention, ces bêtes menacent autant les sentiers de chasse que le camp Narache."},{t="Nourrir la tribu",b="La chasse protège les Taurens et nourrit la tribu. Grull Vent-du-faucon demande aux jeunes chasseurs de rapporter les museaux et les flancs des sangliers de guerre apprivoisés. Même ces bêtes dressées par les quillboars sont mises à profit. Leur viande et leurs cartilages entrent dans la préparation du ragoût destiné aux jeunes de la tribu, transformant une arme quillboar en nourriture pour la prochaine génération de défenseurs taurens."}},faq={{q="Pourquoi les sangliers de guerre attaquent-ils la mesa ?",a="Les quillboars Ronce-dos du ravin de Roncelame ont élevé et dressé les sangliers de guerre apprivoisés. Ils se servent de ces bêtes pour harceler les Taurens et s’enfoncer dans les terrains de chasse tribaux de la mesa de Nuage rouge.",al={"agressivité des sangliers de guerre","pourquoi les sangliers de guerre sont hostiles","attaque des sangliers de guerre"}},{q="Qui envoie les joueurs accomplir cette chasse ?",a="Grull Vent-du-faucon, chasseur et ancien du camp Narache, guide les jeunes Taurens lors des dernières épreuves de leur formation initiale.",al={"donneur de quête les sangliers de guerre apprivoisés","qui donne la quête les sangliers de guerre apprivoisés","rôle de grull vent-du-faucon"}},{q="Où trouve-t-on les sangliers de guerre ?",a="Les sangliers de guerre apprivoisés rôdent près du ravin de Roncelame et dans celui-ci, à l’est du camp Narache, sur la bordure orientale de la mesa de Nuage rouge.",al={"emplacement des sangliers de guerre","où trouver les sangliers de guerre","sangliers du ravin de roncelame"}},{q="Qu'advient-il de la viande prélevée sur les sangliers ?",a="Les flancs et les museaux des sangliers de guerre apprivoisés sont rapportés au camp Narache pour préparer du ragoût destiné aux enfants et aux anciens du campement. Les Taurens utilisent tout ce qu’ils chassent.",al={"utilisation des flancs de sanglier de guerre","à quoi sert la viande de sanglier","ragoût de sanglier"}},{q="Comment cette quête s'inscrit-elle dans le conflit local contre les quilboars ?",a="La chasse introduit la guerre ouverte entre les Taurens et la tribu Ronce-dos. L’abattage de leurs bêtes de guerre réduit le nombre de celles qui harcèlent les terrains de chasse taurens et envoie un message clair aux Ronce-dos du ravin de Roncelame.",al={"guerre entre taurens et quilboars","conflit avec les bristlebacks","lore des quilboars"}},{q="Quelle quête précède Les sangliers de guerre apprivoisés ?",a="La quête La chasse continue vient d’abord. Grull Vent-du-faucon envoie les jeunes chasseurs découvrir les terrains de chasse de la mesa de Nuage rouge.",al={"prérequis des sangliers de guerre apprivoisés","quête précédente les sangliers de guerre apprivoisés","suite de quêtes the hunt continues"}}},fx={b70ec92c={q="Pourquoi Grull Vent-du-faucon veut-il que les The Battleboars soient tués ?",a="Les The Battleboars sont sortis du Ravin de Roncelame et ont empiété directement sur les terrains de chasse ancestraux de la tribu du Nuage rouge. Élevés et entraînés à la férocité par les Piquants-tranchants, leur agressivité croissante menace directement le Camp Narache. Grull Vent-du-faucon a l'intention d'envoyer un message ferme aux Piquants-tranchants en décimant leurs bêtes de guerre tout en transformant la chasse en nourriture pour les jeunes de la tribu.",al={"pourquoi grull vent-du-faucon veut-il les the battleboars morts","motivation grull vent-du-faucon the battleboars","pourquoi tuer les the battleboars mulgore"}},["58a19c3f"]={q="Que sont les The Battleboars ?",a="Les The Battleboars sont des bêtes féroces élevées et entraînées par les Piquants-tranchants du Ravin de Roncelame. Contrairement aux couguars des montagnes et aux autruches des plaines indigènes de la Mesa de Nuage rouge, ces sangliers sont conditionnés à dessein pour la guerre et la malveillance, servant d'armes vivantes dans la lutte continue des Piquants-tranchants contre les taurens.",al={"qui sont les the battleboars","que sont les the battleboars","connaissance the battleboars"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="Un don de laine",s="À Forgefer, les dons d’étoffe de laine contribuent à approvisionner ses réserves. Soixante pièces vous vaudront toute sa reconnaissance pour votre générosité.",h="À Forgefer, les dons d’étoffe de laine contribuent à approvisionner ses réserves.",kw={"don","forgefer","reconnaissance","soixante pièces","réserves","laine","etoffe de laine"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, votre don d’étoffe de laine vous vaudra la reconnaissance de Forgefer."},sec={{t="Réserves de laine",b="Forgefer vous demande soixante pièces d’étoffe de laine. C’est tout ce dont ses réserves ont besoin. Les autres doivent donner suffisamment pour soutenir la collecte."}},faq={{q="De combien de pièces d’étoffe de laine Forgefer a-t-elle besoin ?",a="Soixante pièces d’étoffe de laine, pour Forgefer.",al={"quantité d’étoffe de laine à donner","combien d’étoffe de laine","soixante pièces d’étoffe de laine"}},{q="Que reçoit-on en donnant de l’étoffe de laine ?",a="Donnez à Forgefer soixante pièces d’étoffe de laine et vous gagnerez toute sa reconnaissance pour votre générosité.",al={"récompense du don d’étoffe de laine","que donner en échange de laine","reconnaissance de forgefer"}},{q="Pourquoi Forgefer collecte-t-elle de l’étoffe de laine ?",a="Forgefer rassemble de l’étoffe de laine pour approvisionner ses réserves.",al={"collecte de laine","pourquoi donner de la laine","laine de forgefer"}}},fp="18,110,11.148.0,42.42.0,32.93.0,33.51.0"}
P.entries["quest:7807"] = {n="Un don de laine",s="Dans tout le royaume, A Donation of Wool appelle à aider les Exilés de Gnomeregan. Chassés de Gnomeregan, ils ont besoin d'Etoffe de laine pour subvenir aux besoins de leur peuple déplacé. Soixante pièces leur valent une reconnaissance officielle parmi les gnomes.",h="Dans tout le royaume, A Donation of Wool appelle à aider les Exilés de Gnomeregan.",kw={"collecte d'étoffes","don d'étoffe de laine","gnome","gnomeregan","exilés de gnomeregan","textiles","etoffe de laine"},ang={["faction:Alliance"]="L'apport de matières premières renforce la solidarité de l'Alliance et aide à soutenir un allié essentiel, chassé de son foyer montagnard.",["profession:Tailoring"]="Les couturiers qui ramassent ou tissent de l'Etoffe de laine disposent d'une grande quantité de textiles dont les réfugiés ont besoin pour leurs vêtements et fournitures de base.",["race:Gnome"]="Pour les gnomes en exil, ramasser de la laine aide à ravitailler vos proches déplacés, qui tentent de survivre et de reconstruire leur foyer hors de Gnomeregan."},sec={{t="Les besoins d'un peuple déplacé",b="La chute de Gnomeregan, envahie par les troggs et frappée par la contamination radioactive, a chassé les gnomes survivants de leur cité de haute technologie. Ils vivent désormais comme des réfugiés, principalement accueillis par leurs cousins nains à Forgefer.\n\nLoin de leurs salles ancestrales, les Exilés de Gnomeregan peinent à approvisionner leur peuple. Des collectes régulières d'étoffes et d'autres biens essentiels les aident à rester vêtus, approvisionnés et organisés."},{t="La collecte de textiles",b="La collecte demande exactement soixante pièces d'Etoffe de laine à chaque volontaire. En réunissant de modestes contributions venues de tout le royaume, les exilés peuvent rassembler les textiles nécessaires aux literies, aux bandages et aux vêtements sans trop solliciter un seul fournisseur. Ceux qui contribuent à leur rétablissement reçoivent une reconnaissance officielle parmi les leurs."}},faq={{q="Pourquoi les Exilés de Gnomeregan ont-ils besoin d'Etoffe de laine ?",a="Les Exilés de Gnomeregan rassemblent des fournitures textiles essentielles. Chassés de leur cité, leurs réfugiés ont besoin d'Etoffe de laine pour subvenir aux besoins de leur peuple et poursuivre leurs activités.",al={"pourquoi la laine","à quoi sert la laine","but du don de laine"}},{q="Quelle quantité d'Etoffe de laine faut-il ?",a="La collecte demande soixante pièces d'Etoffe de laine à chaque contributeur. Les organisateurs comptent sur les contributions de tout le royaume pour répondre à leurs besoins en fournitures.",al={"quelle quantité de laine","quantité du don","laine nécessaire"}},{q="Qui organise cette collecte de dons ?",a="Les représentants des Exilés de Gnomeregan organisent la collecte et reçoivent les dons destinés aux gnomes déplacés qui trouvent refuge auprès de leurs alliés.",al={"qui reçoit le don","qui accepte la laine","destinataire du don"}},{q="Peut-on donner de l'Etoffe de laine plusieurs fois ?",a="Chaque donateur doit contribuer une fois à hauteur de soixante pièces. Les exilés ont besoin de cette quantité fixe de votre part et comptent sur les contributions de tout le royaume pour atteindre leur quota.",al={"peut-on donner à nouveau","est-ce répétable","autres dons de laine"}},{q="Quelle reconnaissance les Exilés de Gnomeregan offrent-ils ?",a="Un don de soixante pièces vaut reconnaissance et gratitude de la part des Exilés de Gnomeregan. Il témoigne de votre loyauté et de votre soutien à leur peuple déplacé en temps de crise.",al={"réputation auprès des exilés de gnomeregan","réputation des gnomes","reconnaissance des exilés"}},{q="Pourquoi les gnomes sont-ils actuellement en exil ?",a="Les gnomes ont fui leur foyer souterrain de Gnomeregan après une catastrophe dévastatrice et une invasion des troggs. Réfugiés, ils dépendent de camps temporaires, de l'aide de leurs alliés et des collectes de fournitures.",al={"pourquoi les gnomes sont en exil","où se trouve gnomeregan","crise des réfugiés gnomes"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:78091"] = {n="Earning Your Salt",s="Ursula Deline, à Hurlevent, a accepté d’étudier un orbe pour vous, mais exige un service en échange. Pour découvrir ses conclusions, vous devez vous rendre dans les Carmines et dérober au clan Rochenoire des sels préparés pour les invocateurs.",h="Ursula Deline, à Hurlevent, a accepté d’étudier un orbe pour vous, mais exige un service en échange.",kw={"clan rochenoire","invocateur du clan rochenoire","gagner son sel","les carmines","hurlevent","sel des invocateurs","ursula deline"},ang={["class:Warlock"]="Ursula Deline étudiera un orbe pour vous, à condition que vous lui rapportiez les sels préparés dont les invocateurs du clan Rochenoire se servent pour renforcer leurs rituels."},sec={{t="Ritual Salt",b="Les invocateurs du clan Rochenoire, dans les Carmines, transportent des sels spécialement traités pour renforcer leurs sombres rites. Ursula Deline refuse d’examiner un orbe pour vous tant que vous ne lui aurez pas rapporté une réserve de ces campements. Elle a accepté de vous révéler les résultats de ses recherches dès votre retour à Hurlevent avec le sel."}},faq={{q="Qui est Ursula Deline ?",a="Ursula Deline est une chercheuse de Hurlevent qui accepte d’examiner un orbe pour vous en échange de composants rituels.",al={"qui veut le sel des invocateurs","qui donne la quête gagner son sel","qui est ursula deline"}},{q="Pourquoi Ursula a-t-elle besoin du sel des invocateurs ?",a="Les démonistes du clan Rochenoire utilisent des sels spécialement préparés pour renforcer leurs rituels d’invocation, et Ursula exige que vous lui en rapportiez avant de partager ses recherches.",al={"pourquoi ursula veut-elle du sel","à quoi sert le sel des invocateurs","pourquoi récolter du sel"}},{q="Où trouver le sel des invocateurs ?",a="Le sel est transporté par les invocateurs du clan Rochenoire installés dans les Carmines.",al={"où trouver le sel des invocateurs","où se trouvent les invocateurs du clan rochenoire","où obtenir le sel"}},{q="Que vous offre Ursula en échange ?",a="Ursula promet d’étudier un orbe et de partager les résultats de ses recherches dès votre retour avec le sel.",al={"que promet ursula","qu’étudie ursula","qu’obtient-on en échange"}}},fp="17,233,11.314.0,21.114.0,37.145.0,35.82.0,33.101.0"}
P.entries["quest:781"] = {n="L'attaque du camp Narache",s="Au Camp Narache, vous portez un avertissement qui pourrait donner aux Taurens le temps d’appeler à l’aide. Les hurans Dos-hirsute préparent un siège, et le Chef Vent-du-faucon doit le savoir.",h="Au Camp Narache, vous portez un avertissement qui pourrait donner aux Taurens le temps d’appeler à l’aide.",kw={"plans d’attaque","sabot-de-sang","ravin de roncelame","dos-hirsute","camp narache","chef vent-du-faucon","carte couverte de poussière","hurans","mesa de nuage rouge"},ang={["faction:Horde"]="En préservant la présence des Taurens en Mulgore, vous aidez la Horde à garder son ancrage méridional vital au centre de Kalimdor.",["race:Tauren"]="Jeune brave tauren qui commence ses premiers rites sur la mesa, vous prouvez votre loyauté en interceptant la carte et en protégeant les vôtres d’un massacre soudain."},sec={{t="Un complot dans les ronces",b="Dans le Ravin de Roncelame, vous trouvez une carte grossière sur le sol de la caverne. Ses marques couvertes de poussière révèlent que les hurans Dos-hirsute préparent un long siège contre le Camp Narache. Il ne s’agit pas d’une série d’attaques isolées."},{t="Avertir le chef",b="Vous apportez les plans d’attaque au Chef Vent-du-faucon, au Camp Narache. Peu de défenseurs gardent le camp, qui abrite de jeunes initiés, aussi Vent-du-faucon s’apprête-t-il à envoyer un message au village de Sabot-de-Sang pour demander des renforts. Votre avertissement donne au camp le temps de se préparer au siège."}},faq={{q="Où trouve-t-on les plans d’attaque des Dos-hirsute ?",a="Les plans des Dos-hirsute sont marqués sur une carte couverte de poussière, dans une grotte du Ravin de Roncelame, juste en haut d’un chemin à droite de la hutte de Chief Sharptusk.",al={"emplacement de la carte","où trouver la carte couverte de poussière","trouver les plans"}},{q="À qui remettre les plans d’attaque des Dos-hirsute ?",a="Le Chef Vent-du-faucon reçoit les plans d’attaque des Dos-hirsute au centre du Camp Narache.",al={"à qui remettre la quête","qui reçoit la carte","personnage de fin de quête"}},{q="Pourquoi les hurans Dos-hirsute ciblent-ils le Camp Narache ?",a="La tribu des Dos-hirsute cherche à chasser les Taurens de la Mesa de Nuage rouge et à reprendre les terrains de chasse et les plaines sacrées de Mulgore pour les siens.",al={"pourquoi attaquer le camp narache","motifs des hurans en mulgore","siège des dos-hirsute"}},{q="Comment le Chef Vent-du-faucon compte-t-il contrer le siège ?",a="Averti par la carte, le Chef Vent-du-faucon compte faire appel à leurs frères du village de Sabot-de-Sang pour renforcer la mesa et repousser l’assaut.",al={"plan de vent-du-faucon","renforts pour le camp narache"}},{q="Faut-il parler à quelqu’un avant de ramasser la carte ?",a="Non. Vous trouvez la Carte couverte de poussière sur le sol d’une grotte du Ravin de Roncelame. Une fois récupérée, elle devient les plans de bataille.",al={"personnage de départ de quête","départ de quête carte couverte de poussière","comment commencer l’attaque du camp narache"}},{q="Que se passera-t-il si le Camp Narache tombe ?",a="Le Camp Narache est le principal refuge des jeunes Taurens et le lieu de leurs rites de passage. Sa perte menacerait la sécurité de la Mesa de Nuage rouge et priverait Mulgore de ses lieux sacrés de formation spirituelle.",al={"enjeux du camp narache","pourquoi défendre narache"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="Le maître de l'arène",s="À la Stranglethorn Arena, Short John Mithril sait peut-être ce qu’il faut pour maîtriser ses épreuves.",h="À la Stranglethorn Arena, Short John Mithril sait peut-être ce qu’il faut pour maîtriser ses épreuves.",kw={"maître de l’arène","gurubashi","pirate","short john mithril","stranglethorn arena","vallée de strangleronce"},sec={{t="À la recherche du Pirate",b="Vous avez obtenu quelque chose à Gurubashi, mais maîtriser l’arène demande davantage. Short John Mithril organise les épreuves et sait peut-être ce qu’il faut. Trouvez-le dans la Stranglethorn Arena."},{t="Les paroles de Short John",b="Short John Mithril vous dit qu’un seul bijou ne suffit pas pour maîtriser l’arène. La véritable mise à l’épreuve de votre acier commence maintenant."}},faq={{q="À qui dois-je parler ?",a="Parlez à Short John Mithril, le Pirate derrière l’événement de Gurubashi.",al={"à qui parler","rendre la quête du maître de l’arène","où aller"}},{q="Où se trouve Short John Mithril ?",a="Trouvez Short John Mithril dans la Stranglethorn Arena, à Gurubashi, dans la Vallée de Strangleronce.",al={"emplacement de gurubashi","où se trouve la stranglethorn arena","emplacement de l’arène"}},{q="Qu’est-ce qui laisse entendre qu’on peut devenir maître de l’arène ?",a="Vous avez accompli quelque chose à Gurubashi, mais maîtriser l’arène semble demander davantage. Short John Mithril, le Pirate derrière l’événement, sait peut-être ce qu’il faut.",al={"comment devenir maître de l’arène","suis-je déjà maître de l’arène"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Les érudits recherchent le Nar'thalas Almanac pour préserver les anciennes études magiques. Sa découverte apporte un savoir oublié dans une Library où les chercheurs peuvent l'étudier.",h="Les érudits recherchent le Nar'thalas Almanac pour préserver les anciennes études magiques.",kw={"almanach","arcanique","livre","library","ouvrages magiques","nar'thalas","narthalas","tome"},ang={["class:Mage"]="En tant que mage, vous connaissez la valeur savante des textes consacrés aux anciennes traditions arcaniques. Ajouter les ouvrages retrouvés à la collection magique d'une Library compte beaucoup.",["faction:Alliance"]="En tant qu'aventurier de l'Alliance, vous pouvez aider les érudits et les conservateurs des archives de l'Alliance à rechercher de rares manuscrits et à enrichir le savoir rassemblé du royaume.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous connaissez Nar'thalas comme un ancien centre d'érudition arcanique kaldorei, avant que la Fracture ne détruise l'ancien monde. Un almanach portant son nom vous relie à l'ancienne histoire des elfes de la nuit."},sec={{t="Un vestige d'études anciennes",b="Rare ouvrage d'érudition arcanique, le Nar'thalas Almanac est issu des anciennes traditions savantes des elfes de la nuit d'avant la Fracture. Pour les gardiens des grandes archives, mettre la main sur ce volume sauve de l'oubli un savoir vieux de plusieurs siècles et ajoute une pièce importante de l'histoire à leurs rayonnages. Ceux qui découvrent des ouvrages délaissés contribuent à relier l'antiquité oubliée aux études modernes."},{t="Enrichir les archives",b="Partout en Azeroth, archivistes et chercheurs recherchent des traités perdus, des notes de terrain et des chroniques. Confier le Nar'thalas Almanac à une Library dédiée permet à ses gardiens de le préserver, de le cataloguer et de l'étudier, plutôt que de le laisser se dégrader dans des ruines ou tomber entre des mains négligentes. Chaque volume retrouvé apporte un nouvel éclairage sur les arts arcaniques des époques passées."}},faq={{q="Qu'est-ce que le Nar'thalas Almanac ?",a="Le Nar'thalas Almanac est un ancien manuscrit rare consacré aux études magiques, que les conservateurs recherchent pour leurs archives historiques. Ceux qui le retrouvent confient son savoir à des érudits, qui peuvent le préserver et le cataloguer.",al={"qu'est-ce que le nar'thalas almanac","quête du nar'thalas almanac","informations sur l'almanach"}},{q="Qui rassemble le Nar'thalas Almanac ?",a="Les érudits de la Library qui s'intéressent aux anciens textes magiques et aux archives historiques rassemblent l'almanach. Les conservateurs recherchent activement de nouveaux ouvrages pour enrichir leur connaissance commune du patrimoine arcanique du monde.",al={"qui veut l'almanach","où déposer l'almanach","remettre l'almanach"}},{q="À quoi le nom Nar'thalas fait-il référence ?",a="Nar'thalas était un ancien centre d'études kaldorei et de recherches magiques, avant la Grande Fracture. Les textes qui portent son nom préservent des fragments des arts arcaniques et du savoir des elfes d'avant la Fracture.",al={"qu'est-ce que nar'thalas","histoire de nar'thalas","où se trouve nar'thalas"}},{q="Pourquoi rassembler des textes magiques pour la Library ?",a="Des archives historiques et des traités magiques ont été déplacés, perdus ou ensevelis dans des ruines à travers Azeroth. Les érudits étudient les écrits retrouvés pour approfondir leur compréhension des courants arcaniques et protéger ces fragiles archives contre une disparition définitive.",al={"pourquoi rassembler des ouvrages magiques","but de la library","pourquoi les livres comptent"}},{q="Peut-on apporter d'autres ouvrages magiques à la Library ?",a="Les traités, les tomes et les manuscrits oubliés peuvent éclairer la théorie arcanique et l'histoire ancienne. Les érudits recherchent sans cesse de nouveaux ouvrages pour enrichir leurs rayonnages.",al={"plus de livres magiques","autres tomes","plus de textes"}},{q="Le Nar'thalas Almanac est-il dangereux à manipuler ?",a="L'almanach rassemble des notes d'étude ; ce n'est pas un artefact interdit et instable. Les historiens et les praticiens peuvent s'en servir comme d'une précieuse référence sur la magie d'autrefois.",al={"l'almanach est-il dangereux","l'almanach contient-il de la magie noire","sans danger à lire"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="Le bibliothécaire vous demande des ouvrages magiques pour la collection. Chaque livre enrichit la bibliothèque.",h="Le bibliothécaire vous demande des ouvrages magiques pour la collection.",kw={"collection","dalaran digest","connaissances","bibliothécaire","library","ouvrages magiques"},sec={{t="La collection",b="Le bibliothécaire accueille les ouvrages magiques susceptibles d’enrichir la bibliothèque. Vous apportez un livre pour l’ajouter à la collection et contribuer à accroître ses connaissances."}},faq={{q="Que souhaite le bibliothécaire ?",a="Le bibliothécaire vous demande des ouvrages magiques susceptibles d’enrichir la collection.",al={"quoi apporter","livre de bibliothèque","ouvrages magiques"}},{q="Où dois-je apporter le livre ?",a="Apportez le livre au bibliothécaire qui vous a demandé de l’ajouter à la collection.",al={"où se trouve le bibliothécaire","emplacement de la bibliothèque"}},{q="Pourquoi le bibliothécaire rassemble-t-il des ouvrages magiques ?",a="Votre contribution enrichit les connaissances de la collection.",al={"pourquoi collectionner des livres","but de la bibliothèque"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Envoûtements et glamours",s="À Forgefer, la bibliothèque recherche des ouvrages magiques pour ses rayons. Vous pouvez aider ses gardiens à élargir leurs connaissances en apportant des livres susceptibles d’enrichir la collection.",h="À Forgefer, la bibliothèque recherche des ouvrages magiques pour ses rayons.",kw={"bewitchments and glamours","livres","collection","forgefer","library","ouvrages magiques"},sec={{t="Une collection grandissante",b="Apportez des ouvrages magiques à la bibliothèque de Forgefer. Chaque ajout peut élargir les connaissances de ses gardiens."}},faq={{q="Que recherche la bibliothèque ?",a="La bibliothèque recherche des ouvrages magiques susceptibles d’enrichir sa collection.",al={"que recherchent-ils","livres de la bibliothèque","ouvrages magiques"}},{q="Où dois-je apporter les ouvrages magiques ?",a="Apportez les ouvrages magiques à la bibliothèque.",al={"où apporter les livres","où se trouve la bibliothèque","bibliothèque de forgefer"}},{q="Pourquoi rassemblent-ils des ouvrages magiques ?",a="La bibliothèque affirme que ces ouvrages élargiront ses connaissances.",al={"pourquoi rassembler des livres magiques","à quoi sert la collection"}}},fp="25,168,20.103.0,27.64.0,35.39.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets des Rêveurs",s="Les érudits d’une bibliothèque recherchent des écrits liés aux Rêveurs et à d’autres savoirs magiques.",h="Les érudits d’une bibliothèque recherchent des écrits liés aux Rêveurs et à d’autres savoirs magiques.",kw={"arcanes","rêveurs","library","ouvrages magiques","érudits","secrets of the dreamers","grimoires"},ang={["class:Druid"]="En tant que druide, les écrits liés à la magie de la nature et au Rêve d’émeraude ont une grande importance dans les arts cénariens.",["class:Mage"]="En tant que mage, vous pouvez rechercher des grimoires obscurs et des textes magiques pour enrichir les archives savantes.",["faction:Alliance"]="Les érudits de l’Alliance, surtout ceux qui veillent sur de grands dépôts, comptent sur les champions pour retrouver les connaissances perdues dans des lieux dangereux."},sec={{t="À la recherche de savoirs oubliés",b="Les érudits de tout le royaume comptent sur les voyageurs pour retrouver de rares textes magiques et des traités historiques. Ces ouvrages reposent dans d’antiques ruines ou des collections privées, loin des archives. Les aventuriers les acheminent donc en toute sécurité jusqu’à ceux qui étudient les mystères arcaniques d’Azeroth et préservent son savoir."},{t="Enrichir les archives",b="Lorsque les voyageurs rapportent des traités, les archivistes les ajoutent aux collections permanentes de la bibliothèque. Les chercheurs recherchent des écrits obscurs sur le Rêve d’émeraude et la théorie arcanique. Leurs travaux se poursuivent, et ils accueillent volontiers d’autres textes magiques trouvés sur le terrain."}},faq={{q="Quel est le but de la quête Secrets of the Dreamers ?",a="Les voyageurs récupèrent des écrits magiques et des connaissances obscures, puis les apportent aux érudits d’une bibliothèque pour enrichir les archives.",al={"que sont secrets of the dreamers","quête secrets of the dreamers","que faut-il faire dans cette quête"}},{q="Qui rassemble ces textes magiques ?",a="Un érudit chargé des collections d’une bibliothèque rassemble les textes et demande aux voyageurs d’apporter des ouvrages magiques.",al={"qui veut secrets of the dreamers","qui donne cette quête","où rendre secrets of the dreamers"}},{q="Où sont conservés les ouvrages récupérés ?",a="Les écrits rejoignent les archives grandissantes d’une bibliothèque institutionnelle, où les érudits et chercheurs de l’Alliance peuvent cataloguer et préserver les savoirs rares et les découvertes magiques.",al={"quelle est cette collection","pour quelle bibliothèque","où vont les livres"}},{q="À qui le titre fait-il référence avec « les Rêveurs » ?",a="Les Rêveurs désignent les druides en harmonie avec le Rêve d’émeraude ou d’anciennes entités endormies liées au sommeil de la nature. Les écrits révélant leurs secrets préservent une mystérieuse puissance primordiale.",al={"qui sont les rêveurs","histoire des rêveurs","pourquoi ce nom de rêveurs"}},{q="Peut-on apporter d’autres ouvrages magiques après avoir terminé la quête ?",a="Les archivistes accueillent volontiers d’autres contributions. Lorsque vous trouvez des écrits magiques susceptibles d’enrichir les collections, vous pouvez les leur apporter pour poursuivre les recherches.",al={"puis-je rendre d’autres livres","cette quête est-elle répétable","autres ouvrages magiques"}},{q="Pourquoi est-il important pour les érudits de rassembler ces écrits magiques ?",a="Les érudits cherchent à approfondir leur compréhension des savoirs arcaniques, naturels et obscurs. Les traités perdus ou dispersés peuvent révéler des aspects de l’histoire profonde du monde et de ses mystères.",al={"pourquoi rassembler des livres magiques","pourquoi la bibliothèque a-t-elle besoin de grimoires magiques"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="Manuel des systèmes arcaniques",s="L’Arcanic Systems Manual est un ouvrage magique recherché pour la collection d’une bibliothèque. Son ajout permet à la bibliothèque d’étendre ses connaissances.",h="L’Arcanic Systems Manual est un ouvrage magique recherché pour la collection d’une bibliothèque.",kw={"arcanic","arcanic systems manual","collection","forgefer","library","ouvrages magiques","manuel"},sec={{t="Une place à la Library",b="La bibliothèque accueille les ouvrages magiques susceptibles d’enrichir sa collection. Vous en apportez un à y ajouter, et votre contribution l’aide à étendre ses connaissances."}},faq={{q="Qu’est-ce que l’Arcanic Systems Manual ?",a="C’est un ouvrage magique recherché pour la collection d’une bibliothèque.",al={"manuel arcanic","quel manuel"}},{q="Qui souhaite obtenir le manuel ?",a="Un bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’enrichir la collection.",al={"qui l’a demandé","manuel pour qui"}},{q="Pourquoi apporter le manuel à la bibliothèque ?",a="Les connaissances de la bibliothèque s’enrichissent grâce aux dons d’ouvrages magiques.",al={"pourquoi en faire don","à quoi sert-il"}}},fp="22,129,22.137.0,35.55.0,21.76.0,36.69.0"}
P.entries["quest:78146"] = {n="Parchemins de Goaz",s="Le bibliothécaire vous demande d’apporter les Parchemins de Goaz pour enrichir la collection. Votre contribution accroît le savoir de la bibliothèque.",h="Le bibliothécaire vous demande d’apporter les Parchemins de Goaz pour enrichir la collection.",kw={"collection","parchemins de goaz","savoir","library","ouvrages magiques","parchemins"},sec={{t="Une collection qui s’agrandit",b="Le bibliothécaire vous remercie d’avoir apporté les Parchemins de Goaz. D’autres ouvrages magiques pourraient aussi aider la bibliothèque, qui les accueillera avec plaisir."}},faq={{q="À quoi servent les Parchemins de Goaz ?",a="Les Parchemins de Goaz enrichissent la collection et le savoir de la bibliothèque.",al={"utilité des parchemins de goaz","pourquoi apporter des parchemins","parchemins bibliothèque"}},{q="Qui vous demande les Parchemins de Goaz ?",a="Un bibliothécaire vous demande d’apporter les Parchemins de Goaz pour enrichir la collection.",al={"qui veut les parchemins de goaz","qui reçoit les parchemins","personne de la bibliothèque"}},{q="Où vont les parchemins ?",a="Les Parchemins de Goaz sont destinés à la collection de la bibliothèque.",al={"où apporter les parchemins","lieu des parchemins de goaz","parchemins de la bibliothèque"}},{q="Qu’est-ce qui pourrait aussi aider la bibliothèque ?",a="Le bibliothécaire accueille volontiers d’autres ouvrages magiques susceptibles d’aider la bibliothèque.",al={"autres ouvrages magiques","plus de livres pour la bibliothèque","quoi apporter d’autre"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="Une bibliothécaire vous demande d’ajouter des ouvrages magiques au fonds d’une bibliothèque. Vos découvertes contribuent à enrichir les connaissances de la bibliothèque.",h="Une bibliothécaire vous demande d’ajouter des ouvrages magiques au fonds d’une bibliothèque.",kw={"collection","crimes against anatomy","forgefer","bibliothécaire","library","ouvrages magiques"},sec={{t="Pour la collection",b="Tout ouvrage magique susceptible d’être utile à la bibliothèque y est bienvenu. Vous pouvez apporter vos découvertes à la bibliothécaire, dont le savoir s’enrichit grâce à ces contributions. D’autres ouvrages pourraient encore être utiles à la bibliothèque."}},faq={{q="Qui demande des ouvrages magiques ?",a="Une bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’enrichir la collection.",al={"qui veut des livres","demande de la bibliothèque"}},{q="Où dois-je apporter les ouvrages ?",a="Apportez-les à la bibliothécaire. Les bibliothécaires rassemblent ces ouvrages à Hurlevent et à Fossoyeuse.",al={"où est la bibliothèque","où apporter les livres"}},{q="Pourquoi rassembler des ouvrages magiques ?",a="Les ouvrages contribuent à étendre les connaissances de la bibliothèque.",al={"pourquoi des livres","à quoi servent les ouvrages magiques"}}},fp="22,124,18.204.0,27.78.0,27.92.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="Une bibliothèque accueille des ouvrages magiques dans sa collection. Vos découvertes contribuent à enrichir son savoir.",h="Une bibliothèque accueille des ouvrages magiques dans sa collection.",kw={"collection","forgefer","savoir","library","ouvrages magiques","runes","rois-sorciers"},sec={{t="La collection",b="Le bibliothécaire vous remercie de vos efforts qui enrichissent sa collection. D'autres ouvrages magiques peuvent enrichir son savoir, et le bibliothécaire les accueille volontiers dans la bibliothèque."}},faq={{q="Que recherche la bibliothèque ?",a="La bibliothèque accueille les ouvrages magiques susceptibles d'enrichir sa collection.",al={"que recherchent-ils","livres de bibliothèque","ouvrages magiques"}},{q="Où se trouve la bibliothèque ?",a="Les bibliothécaires réunissent ces ouvrages à Hurlevent et à Fossoyeuse.",al={"emplacement de la bibliothèque","où est la bibliothèque","bibliothèque de forgefer"}},{q="Pourquoi apporter des ouvrages magiques ?",a="Vos efforts enrichissent le savoir de la bibliothèque.",al={"pourquoi des livres","dans quel but","aider la bibliothèque"}}},fp="27,96,14.168.0,27.67.0,21.63.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="Une bibliothèque recherche des ouvrages magiques pour enrichir sa collection. Vos découvertes contribuent à étendre ses connaissances.",h="Une bibliothèque recherche des ouvrages magiques pour enrichir sa collection.",kw={"collection","fury of the land","forgefer","connaissances","library","ouvrages magiques"},sec={{t="Un lieu de savoir",b="Un bibliothécaire vous demande si vous avez apporté quelque chose à ajouter. Il accueille avec plaisir vos trouvailles et vous invite à en rapporter d’autres si vous en découvrez."}},faq={{q="Que recherche la bibliothèque ?",a="La Library recherche des ouvrages magiques susceptibles d’enrichir sa collection.",al={"de quoi ont-ils besoin","livres de bibliothèque","ouvrages magiques"}},{q="Où dois-je apporter les ouvrages magiques ?",a="Apportez-les au bibliothécaire. Des bibliothécaires rassemblent ces ouvrages à Hurlevent et à Fossoyeuse.",al={"où apporter les livres","emplacement de la bibliothèque","apporter des ouvrages"}},{q="Pourquoi rassemblent-ils des ouvrages magiques ?",a="Le bibliothécaire dit que chaque contribution enrichit ses connaissances.",al={"pourquoi rassembler des livres magiques","collection de la bibliothèque","dans quel but"}}},fp="16,90,21.153.0,27.64.0,35.92.0,38.61.0"}
P.entries["quest:7815"] = {n="Les Gueules d'acier, l'ami !",s="Au Village des Revantusk, Katoom le pêcheur vous demande de vous occuper des mordillards d'eau salée qui ruinent sa pêche. Il veut que vous tuiez quinze tortues.",h="Au Village des Revantusk, Katoom le pêcheur vous demande de vous occuper des mordillards d'eau salée qui...",kw={"pêcheur","appât","pêche","hinterlands","katoom","revantusk","mordillards d'eau salée","tortues"},sec={{t="Des ennuis au bout du fil",b="Katoom le pêcheur vous demande d'aider ses voisins et lui-même au Village des Revantusk. Les mordillards d'eau salée ont beau avoir l'air inoffensifs, ils compliquent la pêche. L'un d'eux déchire sa ligne et vole son appât avant qu'il ait pu pêcher cinq minutes. Katoom veut que vous tuiez quinze de ces tortues."}},faq={{q="Qui vous demande de chasser les tortues ?",a="Katoom le pêcheur, un pêcheur du Village des Revantusk, dans les Hinterlands, vous demande de chasser les tortues.",al={"qui donne la quête des gueules d'acier","donneur de quête des gueules d'acier","katoom le pêcheur"}},{q="Pourquoi Katoom veut-il tuer les mordillards d'eau salée ?",a="Katoom dit que les mordillards d'eau salée déchirent sa ligne et volent son appât. Il peut à peine pêcher cinq minutes avant que l'un d'eux ne l'interrompe.",al={"pourquoi tuer les gueules d'acier","tortues nuisibles","pourquoi tuer les tortues de revantusk"}},{q="Combien de mordillards faut-il tuer ?",a="Vous devez tuer quinze tortues mordillards d'eau salée.",al={"combien de tortues","nombre de gueules d'acier","nombre de gueules d'acier l'ami"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="Gammerita, l'ami !",s="Au Village des Revantusk, Katoom le pêcheur veut récupérer son meilleur leurre, pris par Gammerita, l'ami !, la meneuse des tortues mordantes d'eau salée. Retrouvez-la et récupérez-le.",h="Au Village des Revantusk, Katoom le pêcheur veut récupérer son meilleur leurre, pris par Gammerita, l'ami !...",kw={"pêcheur","gammerita","hinterlands","katoom","leurre","revantusk","tortue mordante","tortue"},sec={{t="Une voleuse parmi les tortues",b="Katoom dit que Gammerita n'est pas une tortue ordinaire. Elle mène les tortues mordantes d'eau salée, et il la traite de voleuse. Elle a arraché son meilleur leurre de sa ligne. Depuis, les poissons ne mordent plus comme avant."},{t="Récupérer le leurre",b="Katoom veut que vous trouviez Gammerita et récupériez son leurre dans son estomac. Elle reste sur la côte, parmi les autres tortues."},{t="Les espoirs de Katoom",b="Avec son leurre récupéré et moins de tortues mordantes dans les parages, Katoom s'attend à ce que les poissons affluent en masse."}},faq={{q="Qui est Katoom le pêcheur ?",a="Katoom le pêcheur pêche au Village des Revantusk, dans les Hinterlands. Il vous demande de chasser Gammerita.",al={"qui est katoom","katoom revantusk","emplacement de katoom"}},{q="Qu'est-ce que Gammerita ?",a="Gammerita n'est pas une tortue ordinaire. Elle mène les tortues mordantes d'eau salée, et Katoom la traite de voleuse.",al={"qui est gammerita","qu'est-ce que gammerita","tortue gammerita"}},{q="Pourquoi Katoom veut-il tuer Gammerita ?",a="Gammerita a arraché le meilleur leurre de Katoom de sa ligne, et les poissons ne mordent plus comme avant. Il veut le récupérer dans son estomac.",al={"pourquoi tuer gammerita","qu'a volé gammerita","motif de katoom"}},{q="Où trouver Gammerita ?",a="Gammerita reste sur la côte, parmi les autres tortues mordantes d'eau salée.",al={"où est gammerita","emplacement de gammerita","trouver gammerita"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.96.0,18.96.0,36.132.0,29.71.0"}
P.entries["quest:782"] = {n="Alliances rompues",s="Gorn vous envoie depuis Kargath récupérer ce que les ogres ont pris. Il cherche à restaurer l’honneur de la Horde après son alliance avec Aile de mort. Boss Tho’grun, engagé pour trouver le Signe de la Terre, a trahi la Horde et l’a gardé.",h="Gorn vous envoie depuis Kargath récupérer ce que les ogres ont pris.",kw={"terres ingrates","blacklash","camp boff","deathwing","gorn","hematus","kargath","ravin de lethlor","signe de la terre","tho'grun"},sec={{t="Une bande de mercenaires se retourne",b="Pendant la Deuxième Guerre, la Horde combattit aux côtés d'Aile de mort. Ses lieutenants Blacklash et Hematus furent ensuite emprisonnés loin à l’est, dans le Ravin de Lethlor. Gorn estime que ces anciens alliés dépravés doivent être réduits au silence pour restaurer l’honneur de la Horde.\n\nLa Horde avait besoin du Signe de la Terre pour ouvrir la prison des drakes. Elle engagea donc des mercenaires ogres menés par Boss Tho’grun pour trouver le signe. Tho’grun se retourna contre la Horde, accabla ses forces et garda le signe."},{t="Camp Boff",b="Gorn vous envoie au sud-est de Kargath, au Camp Boff. Tuez Tho’grun et rapportez le Signe de la Terre. Gorn sera ravi de voir Tho’grun mort. Les ogres ne font plus partie de la Horde."},{t="Ce qu’ouvre le Signe",b="Gorn s’attend à ce que les ogres sombrent dans le désarroi après la mort de Tho’grun. Ce sera une petite victoire, qui pourrait en mener à une plus grande.\n\nAvec le Signe de la Terre entre les mains de la Horde, la prison des drakes noirs du Ravin de Lethlor peut être ouverte. Ils seront libérés de leur emprisonnement sans fin, pour aller à leur perte."}},faq={{q="Qui est Gorn ?",a="Gorn est une figure de la Horde à Kargath qui vous envoie chercher le Signe de la Terre. Il veut restaurer l’honneur de la Horde en réduisant au silence ses anciens alliés dépravés.",al={"qui donne alliances rompues","gorn kargath","histoire de gorn"}},{q="Pourquoi Gorn veut-il la mort de Boss Tho’grun ?",a="La Horde a engagé Boss Tho’grun et ses mercenaires ogres pour obtenir le Signe de la Terre. Tho’grun les a trahis, a accablé leurs forces et a gardé le signe.",al={"pourquoi tuer thogrun","trahison de thogrun","histoire de boss thogrun"}},{q="Où se trouve le Camp Boff ?",a="Le Camp Boff se trouve au sud-est de Kargath.",al={"emplacement du camp boff","où se trouve thogrun","trouver boss thogrun"}},{q="Qu’est-ce que le Signe de la Terre ?",a="Le Signe de la Terre est une clé nécessaire pour ouvrir la prison des drakes dans le Ravin de Lethlor.",al={"signe de la terre","à quoi sert le signe de la terre"}},{q="Quels dragons sont emprisonnés dans le Ravin de Lethlor ?",a="Blacklash et Hematus sont deux des lieutenants d'Aile de mort. Ils furent emprisonnés dans le Ravin de Lethlor après que la Horde eut combattu aux côtés d'Aile de mort pendant la Deuxième Guerre.",al={"qui se trouve dans le ravin de lethlor","blacklash et hematus","lieutenants de deathwing"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="Un don de laine",s="Les Pitons-du-Tonnerre recherchent de l’étoffe de laine. Donnez-en soixante pièces pour obtenir toute leur reconnaissance. Les autres donateurs doivent apporter assez de fournitures pour soutenir la collecte.",h="Les Pitons-du-Tonnerre recherchent de l’étoffe de laine.",kw={"collecte d’étoffe","don","reconnaissance","soixante pièces","pitons-du-tonnerre","laine","etoffe de laine"},sec={{t="Un don d’étoffe de laine",b="Les Pitons-du-Tonnerre rassemblent de l’étoffe de laine. Donnez-en soixante pièces pour obtenir toute leur reconnaissance pour votre générosité. Les autres donateurs du royaume doivent en apporter assez pour soutenir la collecte."}},faq={{q="Que souhaitent recevoir les Pitons-du-Tonnerre ?",a="Les Pitons-du-Tonnerre acceptent les dons d’étoffe de laine.",al={"don d’étoffe de laine","quelle étoffe leur faut-il","donner de la laine"}},{q="Quelle quantité d’étoffe de laine dois-je donner ?",a="Donnez soixante pièces d’étoffe de laine pour obtenir toute la reconnaissance des Pitons-du-Tonnerre.",al={"quelle quantité de laine","soixante pièces d’étoffe","quantité du don"}},{q="Que me rapporte un don de laine ?",a="Votre don de soixante pièces d’étoffe de laine vous vaudra toute la reconnaissance des Pitons-du-Tonnerre.",al={"reconnaissance pour le don de laine","quelle reconnaissance","récompense du don"}},{q="Pourquoi les Pitons-du-Tonnerre collectent-ils de la laine ?",a="Les Pitons-du-Tonnerre comptent sur les autres donateurs du royaume pour fournir assez d’étoffe de laine afin de soutenir la collecte.",al={"pourquoi cette collecte de laine","à quoi sert la laine","pourquoi collecter de l’étoffe"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="Un don de laine",s="À Orgrimmar, A Donation of Wool demande de l’aide pour rassembler de l’étoffe. La ville en a dans ses réserves et compte sur d’autres donateurs pour en apporter assez.",h="À Orgrimmar, A Donation of Wool demande de l’aide pour rassembler de l’étoffe.",kw={"a donation of wool","don","orgrimmar","reconnaissance","soixante pièces","laine","etoffe de laine"},sec={{t="De la laine pour Orgrimmar",b="Orgrimmar vous demande de donner soixante pièces d’étoffe de laine. En échange, la ville promet de vous témoigner sa reconnaissance. Ses réserves contiennent déjà de la laine, et d’autres donateurs devraient contribuer à la collecte."}},faq={{q="Que demande Orgrimmar ?",a="Orgrimmar accepte les dons d’étoffe de laine.",al={"ce qu’ils demandent","don de laine"}},{q="Quelle quantité de laine faut-il donner ?",a="Orgrimmar demande soixante pièces d’étoffe de laine.",al={"combien de laine","soixante pièces de laine"}},{q="Que rapporte un don de laine ?",a="En donnant soixante pièces d’étoffe de laine, vous obtiendrez la pleine reconnaissance d’Orgrimmar.",al={"reconnaissance pour un don","récompense pour la laine"}},{q="Pourquoi Orgrimmar collecte-t-elle de la laine ?",a="Orgrimmar rassemble de la laine pour soutenir sa collecte de dons.",al={"collecte de laine","pourquoi de la laine"}},{q="Orgrimmar a-t-elle déjà de la laine ?",a="Oui. Orgrimmar a de la laine dans ses réserves et compte sur d’autres donateurs pour en apporter assez.",al={"réserves de laine","quantité de laine"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="Un mot de C vous demande de récupérer le Horn of Xelthos au Donjon d'Ombrecroc sans aide. Veenix, dans les Serres-Rocheuses, pourrait vous aider à franchir la grille de la cour.",h="Un mot de C vous demande de récupérer le Horn of Xelthos au Donjon d'Ombrecroc sans aide.",kw={"c","cache secrète","horn of xelthos","bois-du-bûcher","donjon d'ombrecroc","les serres-rocheuses","veenix","xelthos"},sec={{t="Une approche discrète",b="C laisse le mot près de Bois-du-Bûcher et désigne Veenix comme contact dans les Serres-Rocheuses. Le Horn of Xelthos se trouve quelque part dans le Donjon d'Ombrecroc, où il faut généralement des renforts pour entrer. C veut que cette mission reste discrète : vous devez donc partir sans compagnie et rapporter le cor à la cache secrète."}},faq={{q="Qui demande le Horn of Xelthos ?",a="C laisse un mot vous demandant de récupérer le Horn of Xelthos et de le rapporter à la cache secrète près de Bois-du-Bûcher.",al={"qui est c","qui veut le cor","mission du cor de c"}},{q="Où se trouve le Horn of Xelthos ?",a="Le Horn of Xelthos se trouve quelque part dans le Donjon d'Ombrecroc.",al={"où est le cor","emplacement du cor","trouver xelthos"}},{q="Pourquoi dois-je y aller sans compagnie ?",a="C dit que cette mission exige de la discrétion : vous devez donc entrer dans le Donjon d'Ombrecroc sans compagnie.",al={"pourquoi en solo","pourquoi partir sans compagnie","sans renforts"}},{q="Qui est Veenix ?",a="Veenix est le contact de C dans les Serres-Rocheuses et pourrait vous aider à franchir la grille de la cour du Donjon d'Ombrecroc.",al={"aide de veenix","qui est veenix","contact pour la grille"}},{q="Où dois-je rapporter le cor ?",a="Rapportez le cor à la cache secrète de C près de Bois-du-Bûcher.",al={"où rapporter le cor","emplacement de la cache secrète","rendre le cor"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="Un contact de KapitalRisk vous propose des explosifs pour franchir la grille de Shadowfang, mais vous demande d’abord de trouver un ordre de travail. Un autre ouvrier de KapitalRisk dans les environs devrait en porter un.",h="Un contact de KapitalRisk vous propose des explosifs pour franchir la grille de Shadowfang, mais vous demande...",kw={"explosifs","grille","crochets de gobelin","shadowfang","kapitalrisk","ordre de travail"},sec={{t="Un ordre de travail",b="Un contact de KapitalRisk apprend que vous comptez entrer seul dans Shadowfang. Des explosifs pourraient vous faire franchir la grille, mais il lui faut un ordre de travail pour justifier les fournitures dans les comptes de l’entreprise. Un autre ouvrier de KapitalRisk dans les environs devrait avoir le document."}},faq={{q="Pourquoi lui faut-il un ordre de travail ?",a="Le contact de KapitalRisk a besoin d’un ordre de travail pour justifier les explosifs dans les comptes de l’entreprise.",al={"pourquoi un ordre de travail","pourquoi des papiers","crochets de gobelin"}},{q="À quoi servent les explosifs ?",a="Les explosifs doivent vous permettre de franchir la grille de Shadowfang.",al={"à quoi servent les explosifs","grille de shadowfang","franchir la grille"}},{q="Qui pourrait avoir l’ordre de travail ?",a="Un autre ouvrier de KapitalRisk dans les environs devrait porter un ordre de travail.",al={"qui a l’ordre de travail","trouver les papiers","ordre de travail de kapitalrisk"}},{q="Vais-je entrer seul dans Shadowfang ?",a="Le contact de KapitalRisk sait que vous comptez entrer seul dans Shadowfang.",al={"shadowfang en solitaire","entrer seul","entrer dans shadowfang"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="Traquer les traqueurs",s="À Revantusk, le Veneur Markhor désigne les loups qui menacent les chasseurs du village. Il vous demande de les traquer.",h="À Revantusk, le Veneur Markhor désigne les loups qui menacent les chasseurs du village.",kw={"loups des hinterlands","veneur markhor","revantusk","village des revantusk","silvermane howler","silvermane stalker","traquer les traqueurs"},sec={{t="Des loups cachés",b="Les étendues sauvages des Hinterlands ont déjà emporté de nombreux trolls. Markhor compte les loups Silvermane parmi les plus grands dangers pour les chasseurs de Revantusk. Ils se cachent dans les buissons et le relief, puis bondissent au bon moment. Il vous exhorte à penser comme un Silvermane et à chasser les chasseurs. Aucun ne doit en réchapper."},{t="La demande de Markhor",b="Markhor vous demande de tuer quinze Silvermane Stalkers et quinze Silvermane Howlers. Ils rôdent dans les étendues sauvages des Hinterlands."},{t="Les remerciements de Revantusk",b="Une fois la chasse terminée, Markhor vous remercie pour ce que vous avez apporté aux Revantusk."}},faq={{q="Qui demande de chasser les loups ?",a="Le Veneur Markhor, de Revantusk dans les Hinterlands, vous demande de chasser les loups.",al={"qui donne la quête traquer les traqueurs","donneur de quête traquer les traqueurs","quête de markhor"}},{q="Pourquoi les loups Silvermane sont-ils si dangereux ?",a="Les loups Silvermane se cachent dans les buissons et le relief, puis attaquent dès qu'ils en ont l'occasion. Markhor les compte parmi les plus grands dangers pour les chasseurs de Revantusk, et de nombreux trolls ont déjà péri dans les étendues sauvages.",al={"pourquoi tuer les loups silvermane","menace des loups silvermane","pourquoi éliminer les loups des hinterlands"}},{q="Quels loups faut-il éliminer ?",a="Vous devez chasser quinze Silvermane Stalkers et quinze Silvermane Howlers.",al={"quels loups tuer","cibles de traquer les traqueurs","types de loups des hinterlands"}},{q="Où trouve-t-on ces loups ?",a="Ces loups rôdent dans les étendues sauvages des Hinterlands.",al={"où trouver les loups silvermane","emplacement du silvermane stalker","emplacement du silvermane howler"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="Chasser les sauvages",s="Dans les Hinterlands, le Veneur Markhor vous envoie chasser des chouettards sauvages. Il vous demande d’en abattre vingt.",h="Dans les Hinterlands, le Veneur Markhor vous envoie chasser des chouettards sauvages.",kw={"hinterlands","chasse aux sauvages","veneur markhor","chouettards","revantusk","village des revantusk","chouettard sauvage"},sec={{t="Griffes et becs",b="Le Veneur Markhor vous avertit que les chouettards sauvages comptent parmi les créatures les plus hargneuses des Hinterlands. Leurs griffes et leurs becs ont coûté la vie à de nombreux bons guerriers de Revantusk. Il veut que vous tuiez chaque chouettard que vous voyez, jusqu’à ce que vous ne supportiez plus le carnage. Il pèsera et jugera alors votre contribution. Vingt doivent périr."},{t="Faire le vide",b="Markhor vous conseille de faire le vide dans votre esprit en écartant toute pensée impure et de ne faire qu’un avec la nature. Les chouettards sauvages parcourent les étendues sauvages des Hinterlands."},{t="Le jugement de Markhor",b="Après la chasse, le Veneur Markhor vous déclare digne d’être un ami des Revantusk."}},faq={{q="Qui propose cette chasse ?",a="Le Veneur Markhor, un veneur du village de Revantusk dans les Hinterlands, propose cette chasse.",al={"qui propose la chasse aux sauvages","donneur de quête chasse aux sauvages","quête du veneur markhor"}},{q="Pourquoi Markhor veut-il tuer les chouettards sauvages ?",a="Markhor qualifie les chouettards sauvages de hargneux. Leurs griffes et leurs becs ont coûté la vie à de nombreux bons guerriers de Revantusk.",al={"pourquoi tuer les chouettards sauvages","raison de chasser les chouettards","pourquoi chasser les sauvages"}},{q="Où trouve-t-on les chouettards sauvages ?",a="Markhor dit que les chouettards sauvages parcourent les étendues sauvages des Hinterlands.",al={"emplacement des chouettards sauvages","où trouver les chouettards sauvages","chouettards dans les hinterlands"}},{q="Combien de chouettards sauvages faut-il tuer ?",a="Vingt chouettards sauvages doivent périr.",al={"combien de chouettards tuer","objectif de la chasse aux sauvages"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="Menace intérieure",s="Dans la Vallée de Comté-du-Nord, les volontaires répondent à l’appel de Hurlevent tandis que les défenses locales faiblissent. À l’Abbaye de Comté-du-Nord, le maréchal McBride dirige la riposte et vous commencez à servir sur les terres menacées.",h="Dans la Vallée de Comté-du-Nord, les volontaires répondent à l’appel de Hurlevent tandis que les défenses...",kw={"menace intérieure","abbaye","forêt d’elwynn","maréchal mcbride","comté-du-nord","recrutement","garde de hurlevent","volontaires"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez comment les devoirs dans des contrées lointaines exposent aux troubles jusqu’au cœur de ses terres.",["race:Human"]="En tant que défenseur humain du Comté-du-Nord, répondre à l’appel du maréchal McBride est votre premier engagement officiel à protéger votre patrie et le royaume de Hurlevent."},sec={{t="Un royaume à bout de forces",b="La Vallée de Comté-du-Nord offrait autrefois un havre de paix propice à la prière, à l’agriculture et à l’étude monastique. Elle constitue désormais la première ligne de défense de la Forêt d’Elwynn contre les troubles intérieurs. Il reste peu de gardes dans les environs, aussi la garde de Hurlevent fait-elle appel à chaque volontaire disposé qui se présente à l’abbaye. Les troubles se répandent dans les campagnes alentour."},{t="L’appel du maréchal",b="Depuis l’Abbaye de Comté-du-Nord, le maréchal McBride dirige les défenses de la vallée tandis que le danger grandit. Des bandits, de la vermine et des nuisibles souterrains menacent les habitants des environs. Vous commencez par dégager les abords de l’abbaye, où ces menaces se rapprochent des défenseurs de la vallée et du lieu qu’ils protègent."}},faq={{q="Quel est l’objectif de cette quête ?",a="Le maréchal McBride appelle les nouveaux arrivants dans la Vallée de Comté-du-Nord à l’aider à la défendre. Vous entrez dans l’Abbaye de Comté-du-Nord pour vous présenter à lui.",al={"quête menace intérieure","quel est l’objectif de cette quête","quête d’introduction au comté-du-nord"}},{q="Qui est le maréchal McBride ?",a="Le maréchal McBride est l’officier supérieur de la garde de Hurlevent à l’Abbaye de Comté-du-Nord. Il dirige la défense de la vallée et charge les recrues d’affronter les menaces des campagnes voisines.",al={"maréchal mcbride","qui est mcbride","commandant de l’abbaye"}},{q="Pourquoi Hurlevent recrute-t-elle des volontaires au lieu d’envoyer des soldats réguliers ?",a="Les forces régulières de Hurlevent servent à l’étranger pour protéger l’Alliance. Les garnisons du cœur du royaume manquent de soldats, alors les commandants locaux comptent sur les volontaires pour défendre leurs foyers.",al={"pourquoi des volontaires","où sont les gardes","pourquoi hurlevent manque de soldats"}},{q="Quelles menaces frappent actuellement la Vallée de Comté-du-Nord ?",a="Les kobolds infestent les mines et les collines voisines, tandis que des nuisibles malades ou prédateurs sévissent dans les vignobles. Des brigands et des hors-la-loi profitent également de l’affaiblissement de la garnison de la vallée.",al={"menaces dans la vallée","qu’est-ce qui attaque le comté-du-nord","problèmes au comté-du-nord"}},{q="Où cette mission vous mènera-t-elle ensuite ?",a="Après vous être présenté au maréchal McBride, vous devrez chasser les kobolds des collines, aider les fermiers et les ouvriers locaux, puis enquêter sur la présence croissante de bandits organisés.",al={"quête suivante","que faire après menace intérieure","suite avec mcbride"}},{q="Pourquoi l’Abbaye de Comté-du-Nord sert-elle de poste de commandement militaire ?",a="L’Abbaye de Comté-du-Nord est un lieu saint consacré à l’étude et à la foi, mais ses murs de pierre et sa position centrale en font une base pratique pour la vallée. L’autorité locale étant mise à rude épreuve, la garde de Hurlevent a établi son commandement dans l’abbaye.",al={"pourquoi des soldats dans l’abbaye","église militaire du comté-du-nord","soldats de l’abbaye sainte"}}},fx={["2039075b"]={q="Pourquoi l'Adjoint Willem vous envoie-t-il vers le Maréchal McBride ?",a="L'Adjoint Willem est posté à l'extérieur de l'Abbaye de Comté-du-Nord pour examiner les nouveaux arrivants valides aussi rapidement que possible. Avec l'armée du royaume à bout de forces et de multiples crises se refermant sur les frontières de Comté-du-Nord, il a besoin que chaque volontaire capable soit correctement enrôlé. Plutôt que d'assigner des missions lui-même, Willem vous dirige directement vers son officier commandant, le Maréchal McBride, afin que vous puissiez être officiellement briefé et déployé là où les défenses de la vallée flanchent le plus.",al={"pourquoi parler à mcbride","motivation willem","pourquoi parler avec mcbride"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="Venger les victimes",s="Au Village des Revantusk, Markhor dirige sa colère contre les Skylords. Il vous demande d’en tuer un et de lui rapporter sa plume.",h="Au Village des Revantusk, Markhor dirige sa colère contre les Skylords.",kw={"venger les victimes","griffon","hinterlands","veneur markhor","razorbeak skylord","village des revantusk","plume de skylord","wildhammer"},sec={{t="Tuer les Skylords",b="Le Veneur Markhor du Village des Revantusk en veut aux Wildhammer, qui dressent des griffons pour tuer des trolls. Il promet justice aux trolls, mais veut d’abord que vous vous en preniez aux Skylords, les griffons anciens des Hinterlands.\n\nTuez un Razorbeak Skylord et rapportez sa plume à Markhor. Cette race rare vit dans les contrées sauvages des Hinterlands. Markhor l’accuse d’engendrer une progéniture meurtrière."},{t="La plume examinée",b="Markhor examine la plume et se demande combien de chasseurs la bête a dévorés avant que vous ne lui rendiez justice."}},faq={{q="Qui propose cette chasse ?",a="Le Veneur Markhor propose cette chasse au Village des Revantusk, dans les Hinterlands.",al={"donneur de quête","qui donne venger les victimes","emplacement de markhor"}},{q="Pourquoi le Veneur Markhor veut-il qu’un Skylord soit tué ?",a="Markhor affirme que les Wildhammer dressent des griffons pour tuer des trolls. Il veut éliminer les griffons anciens de la région, les Skylords, et accuse le rare Razorbeak Skylord d’engendrer une progéniture meurtrière.",al={"pourquoi tuer un razorbeak skylord","pourquoi tuer un skylord","pourquoi chasser les griffons"}},{q="Où trouver un Razorbeak Skylord ?",a="Markhor affirme que le rare Razorbeak Skylord vit dans les contrées sauvages des Hinterlands.",al={"emplacement des skylords","où trouver un razorbeak skylord","où trouver une plume de skylord"}},{q="Que faut-il rapporter à Markhor ?",a="La plume d’un Razorbeak Skylord. Il faut donc d’abord en tuer un.",al={"quel objet me faut-il","objectif de venger les victimes","butin de skylord"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="Un don de laine",s="Un troll sombrelance rassemble des dons de laine, et vos soixante pièces d’Etoffe de laine viennent enrichir une collecte plus importante.",h="Un troll sombrelance rassemble des dons de laine, et vos soixante pièces d’Etoffe de laine viennent enrichir...",kw={"collecte","sombrelance","don","réserves","trolls","laine","etoffe de laine"},sec={{t="Une collecte commune",b="Les Trolls sombrelances rassemblent de l’Etoffe de laine pour réapprovisionner leurs réserves. The Collector peut prendre vos soixante pièces dès maintenant, tandis que l’aide d’autres personnes devrait permettre de compléter la collecte."}},faq={{q="Que collecte-t-on ?",a="Les Trolls sombrelances rassemblent de l’Etoffe de laine.",al={"ce qu’il leur faut","don de laine"}},{q="Combien d’Etoffe de laine leur faut-il ?",a="The Collector a besoin de soixante pièces d’Etoffe de laine de votre part.",al={"quantité de laine","60 étoffes"}},{q="Pourquoi les trolls collectent-ils de la laine ?",a="Les trolls rassemblent de la laine pour réapprovisionner leurs réserves.",al={"pourquoi de la laine","à quoi ça sert"}},{q="Puis-je donner l’étoffe maintenant ?",a="Oui. The Collector peut accepter vos soixante pièces d’Etoffe de laine dès maintenant.",al={"où donner la laine","faire un don maintenant"}}},fp="18,103,19.181.0,24.46.0,41.56.0,35.56.0,25.66.0"}
P.entries["quest:7839"] = {n="Les voyous Vilebranch",s="Au Village des Revantusk, le Forgeron Slagtree cherche les outils volés par les trolls Vilebranch. Un gnome au grand cœur les lui a donnés après lui avoir sauvé la vie alors qu’il était un jeune orc.",h="Au Village des Revantusk, le Forgeron Slagtree cherche les outils volés par les trolls Vilebranch.",kw={"agol'watha","hinterlands","markhor","village des revantusk","shaol'watha","rocher de l'affût","outils perdus de slagtree","forgeron slagtree","vilebranch"},sec={{t="Un cadeau d’un gnome",b="Les trolls Vilebranch ont pris les outils du Forgeron Slagtree lors de leur invasion du Village des Revantusk. Il en a d’autres, mais l’ensemble volé venait d’un gnome au grand cœur qui lui a sauvé la vie alors qu’il était un jeune orc. Ce cadeau représente tout pour Slagtree, qui vous demande de le récupérer."},{t="Où les outils ont été vus",b="Markhor a vu les outils près des temples d’Agol'watha et de Shaol'watha, au nord-est des Hinterlands. Slagtree vous conseille aussi de fouiller le Rocher de l'Affût. Les trolls Vilebranch qui s’y trouvent sont impitoyables et meurtriers."}},faq={{q="Pourquoi ces outils volés sont-ils si importants pour le Forgeron Slagtree ?",a="Un gnome au grand cœur a donné ces outils à Slagtree après lui avoir sauvé la vie alors qu’il était un jeune orc. Slagtree en a d’autres, mais dit que cet ensemble offert représente tout pour lui.",al={"pourquoi slagtree tient à ses outils","histoire des outils perdus de slagtree","pourquoi les outils de slagtree sont spéciaux"}},{q="Qui a volé les outils du Village des Revantusk ?",a="Les trolls Vilebranch ont volé les outils du Forgeron Slagtree pendant leur invasion du Village des Revantusk.",al={"qui a pris les outils","qui a volé les outils de slagtree"}},{q="Où les outils manquants ont-ils été emportés ?",a="Près des temples d’Agol'watha et de Shaol'watha, au nord-est des Hinterlands, où Markhor les a vus. Slagtree indique aussi le Rocher de l'Affût.",al={"où sont les outils de slagtree","où trouver les outils","emplacement des outils de slagtree"}},{q="Qui a signalé avoir vu les outils après le raid ?",a="Markhor a indiqué au Forgeron Slagtree où les outils avaient été vus.",al={"qui a vu les outils","qui a signalé le vol des outils"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="Vaincre les traîtres",s="Au donjon de Tiragarde, les forces kultirassiennes tiennent toujours une tête de pont sur la côte de Durotar. Gar'Thok appelle la Horde à frapper la garnison du lieutenant Benedict, dont la présence a rompu la fragile paix avec Theramore.",h="Au donjon de Tiragarde, les forces kultirassiennes tiennent toujours une tête de pont sur la côte de Durotar.",kw={"daelin portvaillant","durotar","gar'thok","kul tiras","lieutenant benedict","soldats","tranchecolline","marins","donjon de tiragarde","vaincre les traîtres"},ang={["faction:Horde"]="Les forces kultirassiennes occupent toujours le donjon de Tiragarde, aux portes de Durotar. Chasser les troupes de Benedict montre que la Horde peut défendre sa nouvelle patrie contre les flottes étrangères.",["race:Orc"]="Les orcs respectent la trêve conclue avec Jaina au Mont Hyjal, mais Kul Tiras ravive les souvenirs amers de la Deuxième guerre. Combattre les soldats de Benedict est une question de survie et de fierté ancestrale.",["race:Troll"]="Le donjon de Tiragarde est dangereusement proche du Village de Sen'jin, campement des Sombrelances. Chasser ses marins hostiles contribue à protéger la nouvelle patrie vulnérable des trolls."},sec={{t="Une trêve brisée",b="Thrall mena la Horde à travers La Grande mer jusqu'à Kalimdor. Là, lui et Dame Jaina Portvaillant combattirent la Légion ardente au Mont Hyjal. La paix fut rompue lorsque le père de Jaina, dont elle était éloignée, le grand amiral Daelin Portvaillant, amena la marine de Kul Tiras à Durotar. Il tenait chaque orc pour responsable des atrocités de la Vieille Horde et s'empara de places fortes côtières, dont le donjon de Tiragarde. Daelin mourut à Theramore, mais des restes de sa flotte rejettent toujours tout pacte et restent animés par leur haine."},{t="Le retour de Benedict",b="Le donjon de Tiragarde tomba pendant un temps après la défaite du grand amiral. Puis des renforts de Kul Tiras, sous les ordres du lieutenant Benedict, le reprirent. La forteresse se trouve entre Tranchecolline et le Village de Sen'jin. Depuis là, marins et soldats harcèlent les voyageurs et menacent les approches maritimes orientales de Durotar. Gar'Thok considère leur présence comme un danger immédiat pour la sécurité de Durotar. Il appelle donc les guerriers de la Horde à frapper le commandement de Benedict."}},faq={{q="Pourquoi des humains kultirassiens attaquent-ils Durotar ?",a="Ce sont les restes de la flotte expéditionnaire du grand amiral Daelin Portvaillant. Daelin rejetait la paix entre humains et orcs et cherchait à détruire Durotar. Même après sa mort, ses fidèles tiennent des places fortes côtières comme le donjon de Tiragarde et défient la Horde.",al={"pourquoi des humains sont-ils à durotar","attaque de kul tiras","histoire des humains du donjon de tiragarde"}},{q="Qui est le lieutenant Benedict ?",a="Le lieutenant Benedict commande les renforts kultirassiens qui tiennent le donjon de Tiragarde. Après la défaite du grand amiral Portvaillant, Benedict rallia les soldats et les marins survivants. Il reprit la forteresse côtière et lança des opérations persistantes contre les orcs.",al={"qui est benedict","histoire du lieutenant benedict","chef du donjon de tiragarde"}},{q="Jaina Portvaillant soutient-elle ces humains ?",a="Non. Jaina conclut un pacte avec le chef de guerre Thrall pour assurer leur survie mutuelle et s'opposa à la croisade agressive de son père afin de préserver la paix. Les troupes du donjon de Tiragarde sont des restes de Kul Tiras qui rejettent la diplomatie de Theramore et considèrent la trêve de Jaina comme une trahison.",al={"jaina les soutient-elle","alliance entre theramore et kul tiras","jaina portvaillant et tiragarde"}},{q="Pourquoi les appelle-t-on les « traîtres » ?",a="Gar'Thok les appelle des traîtres parce que leur invasion a rompu l'entente forgée par Thrall et Jaina Portvaillant pour vaincre Archimonde durant la Troisième guerre. Leur présence militaire persistante en territoire de la Horde défie les frontières d'après-guerre établies sur Kalimdor.",al={"pourquoi les traîtres","qui a trahi qui","signification de traîtres"}},{q="Où se trouve le donjon de Tiragarde ?",a="Le donjon de Tiragarde se trouve sur la côte orientale de Durotar, au sud de Tranchecolline et juste au nord-est du Village de Sen'jin. Ses hauts murs de pierre dominent les eaux côtières et offrent aux envahisseurs une base stratégique près des campements de la Horde.",al={"emplacement du donjon de tiragarde","où se trouve le donjon de tiragarde","où trouver benedict"}}},fx={["6a077d02"]={q="Pourquoi Gar'Thok veut-il que le donjon de Tiragarde soit libéré ?",a="Gar'Thok supervise la défense de Tranchecolline et de l'est de Durotar. La réoccupation du donjon de Tiragarde par des forces hostiles kultirassiennes menace directement la sécurité de la terre natale des orcs, défiant la paix conclue entre Thrall et Jaina Portvaillant. Laisser une forteresse humaine armée s'implanter sur le littoral de Durotar place les colonies et les lignes de ravitaillement voisines sous la menace immédiate d'une invasion.",al={"motif de gar'thok","pourquoi libérer le donjon de tiragarde","pourquoi gar'thok attaque les humains"}},["902328ad"]={q="Qui devez-vous éliminer au donjon de Tiragarde ?",a="Vous avez pour mission de briser les forces navales kultirassiennes survivantes qui occupent le donjon de Tiragarde : les marins, les soldats et leur officier commandant, le lieutenant Benedict. Ces soldats représentent les vestiges de la flotte du grand amiral Daelin Portvaillant, maintenant une tête de pont armée non autorisée au plus profond du territoire souverain de la Horde.",al={"qui tuer au donjon de tiragarde","qui sont les cibles","vaincre les cibles"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="Lard a perdu son déjeuner !",s="Dans les Hinterlands, Lard a fui vers Revantusk en laissant son déjeuner derrière lui. Un Vilebranch l’a frappé pendant un pique-nique privé. Lard vous demande maintenant de rapporter la nourriture depuis une île au nord.",h="Dans les Hinterlands, Lard a fui vers Revantusk en laissant son déjeuner derrière lui.",kw={"hinterlands","île","lard","déjeuner","pique-nique","village des revantusk","vilebranch"},sec={{t="Un pique-nique interrompu",b="Un Vilebranch a frappé Lard avec un gros bâton dans un lieu secret pour pique-niquer. Selon Lard, le troll était laid et méchant. Lard a fui vers Revantusk en laissant le déjeuner derrière lui, et craint d’y retourner."},{t="L’île au nord",b="Le lieu du pique-nique de Lard se trouve sur une île au nord. Lard espère que vous trouverez le déjeuner et le rapporterez. Prenez garde aux trolls Vilebranch."},{t="Les remerciements de Lard",b="Le déjeuner de Lard est un énorme cuissot de viande. Lard l’engloutit, vous remercie et vous promet un panier de pique-nique spécial pour votre aide."}},faq={{q="Qui est Lard ?",a="Lard vit à Revantusk, dans les Hinterlands. Affamé et effrayé, Lard s’est enfui après qu’un Vilebranch l’a frappé avec un gros bâton.",al={"lard hinterlands","qui est lard","lard revantusk"}},{q="Où Lard a-t-il perdu son déjeuner ?",a="Lard a laissé le déjeuner dans un lieu secret pour pique-niquer, sur une île au nord.",al={"où est le déjeuner de lard","lieu du pique-nique de lard","lieu secret de lard"}},{q="Pourquoi Lard a-t-il laissé sa nourriture derrière lui ?",a="Un Vilebranch a frappé Lard avec un gros bâton pendant le pique-nique. Lard a fui vers Revantusk sans le déjeuner.",al={"pourquoi lard a fui","qui a attaqué lard"}},{q="De quoi faut-il se méfier sur l’île ?",a="Lard signale que les trolls Vilebranch représentent un danger sur l’île.",al={"vilebranch sur l’île","dangers sur l’île de lard"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="Un message pour les Wildhammer",s="Au Village des Revantusk, Otho Moji'ko veut faire porter un message aux nains Wildhammer. Leurs nouveaux alliés comprennent les hauts-elfes, et Otho veut que son avertissement soit écrit avec le sang des hauts-elfes de Highvale au Gîte de Quel'Danil.",h="Au Village des Revantusk, Otho Moji'ko veut faire porter un message aux nains Wildhammer.",kw={"highvale","hinterlands","message pour les wildhammer","otho moji'ko","gîte de quel'danil","village des revantusk","wildhammer"},sec={{t="Un message dans le sang",b="Les Wildhammer forgent des alliances avec les ennemis des trolls, et maintenant les hauts-elfes se tiennent à leurs côtés. Otho Moji'ko crache à cette pensée. Il veut avertir les nains du sang de leurs nouveaux amis. Massacrez chaque haut-elfe de Highvale que vous trouverez et laissez les corps en guise d'avertissement.\n\nLes Coureurs, Éclaireurs, Tireurs d'élite et Rôdeurs de Highvale se rassemblent au Gîte de Quel'Danil, au nord-ouest des Hinterlands."},{t="Des nouvelles du Village des Revantusk",b="À votre retour au Village des Revantusk, Otho déclare que les Revantusk nouent eux aussi de nouvelles alliances. Il loue votre travail."}},faq={{q="Qui propose cette quête ?",a="Otho Moji'ko la propose depuis le Village des Revantusk.",al={"qui donne un message aux wildhammer","quête d'otho moji'ko"}},{q="Où se trouvent les hauts-elfes de Highvale ?",a="Les hauts-elfes de Highvale se rassemblent au Gîte de Quel'Danil, au nord-ouest des Hinterlands.",al={"emplacement du gîte de quel'danil","où se trouvent les elfes de highvale","où trouver les éclaireurs de highvale"}},{q="Pourquoi Otho Moji'ko veut-il attaquer les hauts-elfes ?",a="Otho dit que les Wildhammer concluent des accords avec les ennemis des trolls et qu'ils s'allient maintenant aux hauts-elfes. Il veut faire porter un message aux nains Wildhammer, écrit avec le sang des hauts-elfes.",al={"pourquoi attaquer quel'danil","pourquoi tuer les hauts-elfes des hinterlands"}},{q="Quels elfes de Highvale Otho veut-il voir massacrés ?",a="Otho veut que les Coureurs, Éclaireurs, Tireurs d'élite et Rôdeurs de Highvale au Gîte de Quel'Danil soient massacrés.",al={"quels elfes de highvale","tireur d'élite de highvale","rôdeur de highvale"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="Encore un message pour les Wildhammer",s="Au Village des Revantusk, Otho Moji'ko adresse un autre message aux Wildhammer. Il voit leur lien avec les griffons comme aussi étroit que celui d'un troll et de sa compagne, et compte s'en servir contre eux.",h="Au Village des Revantusk, Otho Moji'ko adresse un autre message aux Wildhammer.",kw={"griffon","hinterlands","long elegant feather","otho moji'ko","village des revantusk","wildhammer"},sec={{t="Un message de plumes",b="Après les hauts-elfes de Highvale, Otho Moji'ko a un autre message pour les Wildhammer. Leur proximité avec les griffons le dégoûte, mais il y voit une utilité. Tuez les griffons que vous rencontrez dans les Hinterlands et récupérez leurs Long Elegant Feathers. Les griffons vivent dans chaque région des Hinterlands. Otho fera son message final avec les plumes."},{t="Le plaisir d'Otho",b="Otho s'attend à ce que son message final effraie les Wildhammer ou les mette en rage. Il se réjouit qu'il ne reste qu'une étape avant qu'ils n'apprennent qu'on ne s'en prend pas aux trolls."}},faq={{q="Qui donne cette quête ?",a="Otho Moji'ko transmet le message depuis le Village des Revantusk.",al={"qui donne un autre message aux wildhammer","donneur de quête autre message","otho mojiko"}},{q="Pourquoi Otho Moji'ko veut-il des plumes de griffon ?",a="Otho dit que les Wildhammer et leurs griffons sont aussi proches qu'un troll et sa compagne. Il compte se servir de ce lien contre eux et faire son message final avec les plumes.",al={"pourquoi des plumes de griffon","pourquoi tuer des griffons dans les hinterlands"}},{q="Où trouve-t-on des griffons ?",a="Les griffons vivent dans chaque région des Hinterlands.",al={"emplacements des griffons dans les hinterlands","où sont les griffons des hinterlands"}},{q="Que s'est-il passé avant ce message ?",a="Cela fait suite à Message to the Wildhammer, dans lequel Otho avait fait massacrer les hauts-elfes de Highvale pour avertir les nains.",al={"que s'est-il passé avant encore un message pour les wildhammer","suite de quêtes message pour les wildhammer"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="Le message final pour les Wildhammer",s="Au Village des Revantusk, Otho Moji'ko vous envoie vers l’ouest avec une lance couverte de sang et liée par des plumes de griffon. Les nains Wildhammer la trouveront plantée près du puits, au cœur de Nid-de-l’Aigle.",h="Au Village des Revantusk, Otho Moji'ko vous envoie vers l’ouest avec une lance couverte de sang et liée par...",kw={"nid-de-l’aigle","plumes de griffon","hinterlands","otho moji'ko","village des revantusk","lance","wildhammer"},sec={{t="Une lance pour Nid-de-l’Aigle",b="Après Another Message to the Wildhammer, Otho Moji'ko vous remet une lance couverte de sang et liée par des plumes de griffon. Portez-la vers l’ouest, jusqu’à Nid-de-l’Aigle, et plantez-la près du puits, au cœur de la ville. Les nains Wildhammer verront que les trolls ne plaisantent pas. Des nains furieux et des membres turbulents de l’Alliance vous y attendent, et Otho espère que vous reviendrez vivant."},{t="L’espoir d’Otho",b="Otho se demande comment les nains réagiront en voyant la lance. Il aurait aimé voir leurs visages. Font-ils leurs bagages pour quitter la ville ? Pour avoir accompli cette tâche, Otho vous promet le grand mojo."}},faq={{q="Qui vous envoie planter la lance ?",a="Otho Moji'ko vous envoie depuis le Village des Revantusk.",al={"donneur de quête","qui donne la quête","otho mojiko"}},{q="Où faut-il planter la lance ?",a="Plantez la lance près du puits, au cœur de Nid-de-l’Aigle, dans l’ouest des Hinterlands.",al={"emplacement de la lance","où planter la lance","puits de nid-de-l’aigle"}},{q="En quoi consiste le message final ?",a="Le message final est une lance couverte de sang et liée par des plumes de griffon.",al={"qu’est-ce que la lance","lance aux plumes de griffon","objet du message final"}},{q="Quelle quête précède celle-ci dans la suite ?",a="Another Message to the Wildhammer vient en premier. Otho a demandé des plumes de griffon pour confectionner ce message final.",al={"quête précédente","prérequis","suite de quêtes du message aux wildhammer"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="Les cousins cannibales",s="Dans Les Hinterlands, Yayo'jin la Mystique vous demande de frapper les Vilebranch près de leurs temples. Elle les décrit comme une bande dépravée qui s'en prend aux autres trolls et aux humanoïdes. Zul'jin étant absent, les Revantusk sont livrés à eux-mêmes.",h="Dans Les Hinterlands, Yayo'jin la Mystique vous demande de frapper les Vilebranch près de leurs temples.",kw={"agol'watha","les cousins cannibales","yayo'jin la mystique","village des revantusk","scalpeur","shaol'watha","devin","vilebranch","zul'jin"},sec={{t="Trois tribus, une terre",b="Trois tribus de trolls se partagent les Hinterlands, mais Yayo'jin la Mystique affirme que peu de choses les unissent. Les Vilebranch s'en prennent aux autres trolls et aux humanoïdes. Zul'jin pourrait les anéantir sans difficulté, mais il est absent. Les Revantusk sont donc livrés à eux-mêmes."},{t="Là où les Vilebranch se rassemblent",b="Yayo'jin vous demande de détruire les Scalpeurs et les Devins Vilebranch près des temples de Shaol'watha et d'Agol'watha. Ces temples se trouvent au nord-nord-est des Hinterlands."},{t="Les éloges de Yayo'jin",b="À votre retour, Yayo'jin affirme que même Zul'jin n'aurait pas pu faire mieux."}},faq={{q="Qui propose cette quête ?",a="Yayo'jin la Mystique la propose depuis le Village des Revantusk.",al={"donneur de la quête les cousins cannibales","qui donne les cousins cannibales","yayo'jin la mystique"}},{q="Pourquoi Yayo'jin veut-elle détruire les Vilebranch ?",a="Yayo'jin décrit les Vilebranch comme une bande dépravée qui s'en prend aux autres trolls et aux humanoïdes. Elle dit que c'est à vous de détruire la vermine de la région.",al={"pourquoi les revantusk combattent les vilebranch","cannibalisme des vilebranch","conflit entre revantusk et vilebranch"}},{q="Où trouver les trolls Vilebranch ?",a="Les Vilebranch se rassemblent autour des temples de Shaol'watha et d'Agol'watha, au nord-nord-est des Hinterlands.",al={"emplacement de shaol'watha","emplacement d'agol'watha","où trouver les devins vilebranch"}},{q="Quels Vilebranch Yayo'jin veut-elle voir détruits ?",a="Yayo'jin veut que vous détruisiez les Scalpeurs et les Devins Vilebranch.",al={"cibles des cousins cannibales","qui tuer pour les cousins cannibales"}},{q="Où se trouve Zul'jin ?",a="Zul'jin n'est pas dans les Hinterlands. Yayo'jin dit qu'il pourrait anéantir les Vilebranch sans difficulté, mais il est absent et les Revantusk sont livrés à eux-mêmes.",al={"zul'jin est-il ici","où se trouve zul'jin dans les hinterlands","situation de zul'jin"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="L’Ancien Torntusk a été enlevé !",s="Au Village des Revantusk, l'Aînée Torntusk vous demande de sauver son compagnon après un raid audacieux à minuit. Ses espions affirment que l'Ancien Torntusk est vivant au sommet de Jintha'Alor.",h="Au Village des Revantusk, l'Aînée Torntusk vous demande de sauver son compagnon après un raid audacieux à...",kw={"l'ancien torntusk","hakkar","hexx","hinterlands","jintha'alor","l'aînée torntusk","revantusk","torntusk","vilebranch"},sec={{t="Un raid à minuit",b="Des sauvages Vilebranch ont frappé le Village des Revantusk à minuit et enlevé l'Ancien Torntusk, le compagnon de l'Aînée Torntusk. Ses espions affirment qu'il est vivant, prisonnier au sommet de Jintha'Alor, la capitale des Vilebranch dans le sud des Hinterlands. L'Aînée Torntusk craint que le village ne puisse supporter sa perte."},{t="Le dieu du Sang sans visage",b="On raconte que la Vile Priestess Hexx prépare l'Ancien Torntusk pour le sacrifier à Hakkar, le dieu du Sang sans visage."},{t="Une fois près de lui",b="L'Ancien Torntusk est à portée, mais les gardes savent sûrement que vous êtes arrivé. Dépêchez-vous."}},faq={{q="Qui a enlevé l'Ancien Torntusk ?",a="Des sauvages Vilebranch ont enlevé l'Ancien Torntusk lors d'un raid audacieux à minuit sur le Village des Revantusk.",al={"qui a enlevé l'ancien torntusk","qui a enlevé torntusk","ravisseurs de torntusk"}},{q="Où l'Ancien Torntusk est-il retenu prisonnier ?",a="Les espions de l'Aînée Torntusk affirment que l'Ancien Torntusk est prisonnier au sommet de Jintha'Alor, la capitale des Vilebranch dans le sud des Hinterlands.",al={"emplacement de l'ancien torntusk","où se trouve l'ancien torntusk","où torntusk est-il retenu prisonnier"}},{q="Quel sort attend l'Ancien Torntusk au sommet de Jintha'Alor ?",a="Le sacrifice. On raconte que la Vile Priestess Hexx prépare l'Ancien Torntusk pour l'offrir à Hakkar, le dieu du Sang sans visage.",al={"pourquoi torntusk a-t-il été capturé","que veulent les vilebranch de torntusk","hexx sacrifie torntusk"}},{q="Qui est l'Aînée Torntusk ?",a="L'Aînée Torntusk est la compagne de l'Ancien Torntusk et vous demande de le sauver.",al={"qui est l'aînée torntusk","compagnon de l'aînée torntusk"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="Récupérez la clé !",s="À Jintha'Alor, L'Ancien Torntusk est enchaîné et vous demande de le libérer. Hitah'ya the Keeper détient sa clé dans une grotte voisine bien gardée.",h="À Jintha'Alor, L'Ancien Torntusk est enchaîné et vous demande de le libérer.",kw={"l'ancien torntusk","les hinterlands","hitah'ya the keeper","jintha'alor","récupérer la clé","revantusk","clé des chaînes"},sec={{t="La grotte de la Gardienne",b="Après Kidnapped Elder Torntusk!, vous trouvez L'Ancien Torntusk enchaîné à Jintha'Alor. Hitah'ya the Keeper détient la clé de ses chaînes dans une grotte voisine, bien gardée. L'Ancien Torntusk vous demande de la tuer et de rapporter la clé. Il pourra alors desserrer ses chaînes et rentrer chez lui."},{t="Les remerciements de L'Ancien Torntusk",b="Grâce à la clé, L'Ancien Torntusk se relève. Il vous remercie et dit que les Revantusk entendront parler de vos exploits."}},faq={{q="Qui détient la clé des chaînes de L'Ancien Torntusk ?",a="Hitah'ya the Keeper détient la clé des chaînes de L'Ancien Torntusk. Il dit qu'elle se trouve dans une grotte voisine, bien gardée.",al={"qui détient la clé","hitah'ya the keeper","où se trouve la clé des chaînes"}},{q="Où L'Ancien Torntusk est-il retenu ?",a="L'Ancien Torntusk est retenu à Jintha'Alor.",al={"où est l'ancien torntusk","emplacement de torntusk","jintha'alor torntusk"}},{q="Pourquoi L'Ancien Torntusk a-t-il besoin de la clé ?",a="La clé ouvre les chaînes de L'Ancien Torntusk. Il dit qu'il pourra rentrer chez lui une fois libre.",al={"pourquoi la clé des chaînes","à quoi sert la clé"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="Retourner voir l’Aînée Torntusk",s="L'Ancien Torntusk est libre et vous envoie au Village des Revantusk porter des nouvelles à sa compagne, l'Aînée Torntusk.",h="L'Ancien Torntusk est libre et vous envoie au Village des Revantusk porter des nouvelles à sa compagne...",kw={"l'ancien torntusk","hinterlands","jintha'alor","l'aînée torntusk","revantusk","village des revantusk"},sec={{t="Des nouvelles pour sa compagne",b="L'Ancien Torntusk est libéré de ses liens et vous demande de retourner au Village des Revantusk. Annoncez à sa compagne, l'Aînée Torntusk, qu'il rentre chez lui."},{t="Le village vous est reconnaissant",b="L'Aînée Torntusk vous remercie d'avoir servi les Revantusk. Le village vous doit une profonde gratitude."}},faq={{q="Qui vous envoie dans cette aventure ?",a="L'Ancien Torntusk vous envoie annoncer à sa compagne qu'il a été secouru.",al={"qui lance la quête retourner voir l’aînée torntusk","donneur de quête ancien torntusk"}},{q="Où se trouve l'Aînée Torntusk ?",a="L'Aînée Torntusk se trouve au Village des Revantusk, dans les Hinterlands.",al={"où se trouve l’aînée torntusk","emplacement de l’aînée torntusk","où rendre la quête retourner voir l’aînée torntusk"}},{q="Que dois-je dire à l'Aînée Torntusk ?",a="Dites à l'Aînée Torntusk que l'Ancien Torntusk rentre chez lui.",al={"que dire à l’aînée torntusk","message pour torntusk"}},{q="Quelle quête a précédé cette aventure ?",a="Cette quête fait suite à Recover the Key!, après les efforts précédents qui ont commencé avec Kidnapped Elder Torntusk!.",al={"quête précédente","suite de quêtes de l’aînée torntusk"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="L’angoisse de la séparation",s="Le Veneur Markhor pleure son frère jumeau, Malkhor, au Village des Revantusk. Les Vilebranch ont enlevé Malkhor lors du raid où ils ont pris la compagne de Torntusk. Markhor croit qu'il est encore possible de sauver l'âme de Malkhor, même si sa vie ne peut plus l'être. Il vous demande donc de récupérer ses restes.",h="Le Veneur Markhor pleure son frère jumeau, Malkhor, au Village des Revantusk.",kw={"os","arrière-pays","jintha'alor","malkhor","markhor","revantusk","crâne","vilebranch","yayo'jin"},sec={{t="La perte d’un jumeau",b="Beaucoup d'habitants du Village des Revantusk ont perdu des êtres chers dans les étendues sauvages, dit Markhor. Lui-même pleure son frère jumeau, Malkhor. Les Vilebranch ont enlevé Malkhor lors du raid où ils ont pris la compagne de Torntusk. Ses ravisseurs l'ont tué rapidement et brutalement ; son destin n'était pas de vivre."},{t="Où reposent les restes",b="Les Vilebranch ont donné les restes de Malkhor en pâture à leurs limons et à leurs loups. Près du sommet du temple de Jintha'Alor se trouvent une fosse à détritus remplie de limons et un repaire de loups. Ses os reposent dans une fosse de limon près du niveau supérieur, tandis que son crâne gît sur ce niveau. Markhor prévoit d'apporter les restes à Yayo'jin, qui les préparera pour une sépulture convenable."}},faq={{q="Qui était le Veneur Malkhor ?",a="Malkhor était le frère jumeau du Veneur Markhor. Les Vilebranch l'ont enlevé lors du raid où ils ont aussi pris la compagne de Torntusk, puis l'ont tué rapidement et brutalement.",al={"qui est malkhor","frère de markhor","histoire de malkhor"}},{q="Où ont été emmenés les restes de Malkhor ?",a="Les Vilebranch ont donné les restes de Malkhor en pâture à leurs limons et à leurs loups. Son crâne gît sur le niveau supérieur de Jintha'Alor, tandis que ses os reposent dans une fosse de limon près de ce niveau.",al={"où sont les os","où se trouve le crâne de malkhor","restes de jintha'alor"}},{q="Qui préparera Malkhor pour sa sépulture ?",a="Markhor apportera les restes de Malkhor à Yayo'jin, qui les préparera pour une sépulture convenable.",al={"sépulture de malkhor","qui est yayo'jin","yayo'jin"}},{q="Pourquoi Markhor veut-il récupérer les os ?",a="Markhor dit que la vie de Malkhor ne peut plus être sauvée, mais que son âme peut encore l'être. Il veut récupérer les restes pour que l'âme de Malkhor puisse être sauvée.",al={"pourquoi récupérer les restes","sauver l'âme de malkhor","sauver son âme"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="Les calices ténébreux",s="Au Village des Revantusk, L'Aînée Torntusk affirme que les Vilebranch combattent avec une fureur surnaturelle. Elle accuse la magie impie de Vile Priestess Hexx et vous demande de prendre les réceptacles de sang souillé à Jintha'Alor pour les purifier.",h="Au Village des Revantusk, L'Aînée Torntusk affirme que les Vilebranch combattent avec une fureur surnaturelle.",kw={"dieu du sang","calices ténébreux","jintha'alor","l'aînée torntusk","village des revantusk","sang souillé","vile priestess hexx","vilebranch"},sec={{t="La fureur des Vilebranch",b="Partout dans Jintha'Alor, les réceptacles de sang souillé portent la puissance du Dieu du sang sans visage. Cette puissance renforce les Vilebranch et les rend fous. Torntusk pense que leur retirer les réceptacles et les purifier desserrera l'emprise du Dieu du sang sur les trolls."},{t="Au retour des réceptacles",b="Rendre les réceptacles dissipe l'énergie sombre qui pousse les Vilebranch à agir, mais seulement pour un temps. Torntusk vous avertit de rester sur vos gardes face au mal, car une prêtresse déchue est vite remplacée par une autre."}},faq={{q="Qui donne la quête des Calices ténébreux ?",a="L'Aînée Torntusk vous attend au Village des Revantusk, dans les Hinterlands.",al={"qui donne les calices ténébreux","donneur de quête des calices ténébreux"}},{q="Où se trouvent les réceptacles souillés ?",a="Les réceptacles de sang souillé se trouvent partout dans Jintha'Alor, dans les Hinterlands.",al={"où trouver les calices ténébreux","emplacement des réceptacles de sang souillé","trouver le sang souillé"}},{q="Pourquoi les trolls Vilebranch sont-ils si féroces ?",a="L'Aînée Torntusk accuse la magie impie de Vile Priestess Hexx. Les réceptacles de sang souillé portent aussi la puissance du Dieu du sang sans visage, qui renforce les Vilebranch et les rend fous.",al={"pourquoi les vilebranch sont-ils fous","folie des vilebranch","férocité des vilebranch"}},{q="Que compte faire l'Aînée Torntusk des réceptacles ?",a="Torntusk compte purifier les réceptacles pour desserrer l'emprise du Dieu du sang sans visage sur les Vilebranch.",al={"pourquoi récupérer les réceptacles","que deviennent les réceptacles de sang"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
P.entries["quest:786"] = {n="Déjouer l'agression des Kolkar",s="Déjouer l'agression des Kolkar est une mission défensive vitale de la Horde confiée par l'éclaireur Lar Fouinebroche près du Village de Sen'jin. Les joueurs sont chargés de s'infiltrer dans la Combe des Kolkar pour détruire trois séries de plans d'invasion coordonnés avant que le clan centaure ne frappe les colonies naissantes de Durotar.",h="Déjouer l'agression des Kolkar est une mission défensive vitale de la Horde confiée par l'éclaireur Lar...",kw={"durotar","kolkar","combe des kolkar","lar fouinebroche","orgrimmar","village de sen'jin","déjouer l'agression des kolkar","vallée des épreuves"},ang={["faction:Horde"]="Enrayer l'offensive des Kolkar évite à la Horde naissante de mener une guerre territoriale épuisante sur plusieurs fronts au seuil même de son nouveau foyer.",["race:Orc"]="La Vallée des épreuves est l'endroit où les jeunes orcs accomplissent leurs rites de passage à l'âge adulte ; une agression centaure en ce lieu constitue donc une insulte existentielle à la culture guerrière orque.",["race:Troll"]="Ayant déjà perdu leur île ancestrale, les Trolls Sombrelance ne peuvent pas se permettre de voir le Village de Sen'jin submergé par des centaures maraudeurs."},sec={{t="Une invasion imminente",b="En explorant l'ouest de Durotar, le pisteur troll Lar Fouinebroche s'est faufilé dans la Combe des Kolkar à la faveur de la nuit. Ce qu'il y a découvert était alarmant : les centaures Kolkar ne se contentaient pas d'organiser des raids côtiers désordonnés, mais préparaient une ambitieuse invasion sur trois fronts visant directement les terres des orcs et des Trolls Sombrelance. Les chefs de guerre centaures ont réparti leurs stratégies de bataille entre trois dirigeants distincts, avec l'intention de frapper la Vallée des épreuves, le Village de Sen'jin et les Gates of Orgrimmar elles-mêmes."},{t="Frapper dans les canyons",b="Pour éviter des combats catastrophiques à travers les canyons rouges et arides de Durotar, des recrues sont envoyées au cœur de la Combe des Kolkar afin de trancher la tête du serpent. S'infiltrer dans le campement poussiéreux et brûler les trois parchemins d'attaque désorganise la chaîne de commandement des centaures. Bien que Lar Fouinebroche reste convaincu que la Horde écraserait inévitablement toute invasion massive, la destruction de ces documents épargne aux défenseurs de Durotar une effusion de sang coûteuse alors que leur jeune nation cherche encore ses marques."}},faq={{q="Qui propose la quête Déjouer l'agression des Kolkar ?",a="La quête est confiée par Lar Fouinebroche, un éclaireur troll Sombrelance posté juste à l'extérieur du Village de Sen'jin, le long des falaises méridionales de Durotar.",al={"donneur de quête","qui donne la quête","emplacement de lar fouinebroche"}},{q="Quelles sont les cibles que les centaures Kolkar prévoient d'attaquer ?",a="Les plans de bataille des Kolkar décrivent une offensive coordonnée sur trois fronts ciblant la Vallée des épreuves, le Village de Sen'jin et la capitale de la Horde, Orgrimmar.",al={"cibles des centaures","quels sont les plans d'attaque","trois cibles"}},{q="Où se trouve la Combe des Kolkar ?",a="La Combe des Kolkar est un réseau de canyons brûlés par le soleil, niché juste à l'ouest des crêtes rocheuses du Village de Sen'jin, dans le sud de Durotar.",al={"emplacement de la combe des kolkar","où se trouve la combe","village centaure durotar"}},{q="Où trouve-t-on les plans d'attaque à l'intérieur de la combe ?",a="Les trois parchemins contenant les plans de l'invasion sont détenus par trois chefs Kolkar distincts gardant différents campements à travers la combe.",al={"emplacements des plans d'attaque","où sont les parchemins","chefs centaures"}},{q="Pourquoi les Kolkar veulent-ils envahir Durotar ?",a="Les Kolkar sont un clan centaure agressif et expansionniste originaire des terres arides de Kalimdor. Ils considèrent les orcs et les Trolls Sombrelance nouvellement arrivés comme des intrus empiétant sur leur territoire et leurs terrains de chasse.",al={"pourquoi les centaures attaquent","mobile des centaures","histoire des kolkar"}},{q="Que se passe-t-il une fois les plans détruits ?",a="La destruction des documents empêche un siège coordonné, plongeant l'offensive tactique des Kolkar dans le désarroi et protégeant les colonies fragiles de Durotar d'une dévastation soudaine.",al={"conséquences de la quête","l'attaque centaure s'arrête-t-elle"}}},fx={a839716d={q="Pourquoi Lar Fouinebroche veut-il que les plans d'attaque soient détruits ?",a="Lar Fouinebroche a exploré la Combe des Kolkar et a découvert que les centaures préparent une invasion à trois volets ciblant le village de Sen'jin, la Vallée des épreuves et Orgrimmar elle-même. Bien que la Horde finirait par écraser un tel assaut, Fouinebroche veut que leurs plans opérationnels soient brûlés afin d'arrêter l'invasion avant qu'elle ne commence, épargnant aux défenseurs de Durotar des effusions de sang et des perturbations inutiles.",al={"pourquoi détruire les plans d'attaque","motif de lar fouinebroche","pourquoi contrecarrer l'agression kolkar"}},["4d134dbe"]={q="Qui sont les centaures Kolkar de la Combe des Kolkar ?",a="Les Kolkar sont un clan brutal de centaures qui a établi une place forte dans les combes le long de la crête ouest de Durotar. Féroces et territoriaux, ils nourrissent une haine profonde pour les orcs et les Trolls sombrelances nouvellement arrivés, lançant régulièrement des raids depuis leur campement et complotant pour chasser complètement la Horde de la région.",al={"qui sont les kolkar ici","centaures de la combe des kolkar","pourquoi les kolkar sont à durotar"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="On recherche : la vile prêtresse Maléficia et ses sbires",s="L'Aînée Torntusk vous envoie à Jintha'alor pour traduire en justice la vile prêtresse Maléficia et ses sbires. Elle offre une grande récompense pour éliminer Maléficia et sa garde d'élite Aman'zasi.",h="L'Aînée Torntusk vous envoie à Jintha'alor pour traduire en justice la vile prêtresse Maléficia et ses sbires.",kw={"aman'zasi","maléficia","hinterlands","jintha'alor","l'aînée torntusk","village des revantusk","vile prêtresse maléficia","vilebranch"},sec={{t="Une attaque contre Jintha'alor",b="L'Aînée Torntusk vous envoie éliminer la vile prêtresse Maléficia et ses sbires. Ils se trouvent au sommet de Jintha'alor, dans les Hinterlands, où Maléficia est accompagnée de sa garde d'élite Aman'zasi. Éliminez-les, puis faites votre rapport à Torntusk au Village des Revantusk."}},faq={{q="Qui a offert une récompense pour la vile prêtresse Maléficia ?",a="L'Aînée Torntusk a ordonné cette mise à prix et offre une grande récompense pour éliminer la prêtresse et sa garde.",al={"qui veut la mort de maléficia","qui a offert cette récompense","prêtresse maléficia donneuse de quête"}},{q="Où se trouvent la vile prêtresse Maléficia et ses gardes ?",a="La vile prêtresse Maléficia et ses gardes se trouvent au sommet de Jintha'alor, dans les Hinterlands.",al={"où se trouve maléficia","emplacement de la vile prêtresse maléficia","emplacement des gardes aman'zasi"}},{q="Qui faut-il éliminer pour toucher la récompense ?",a="Éliminez la prêtresse Maléficia et sa garde d'élite Aman'zasi des Vilebranch.",al={"objectifs de la mise à prix de maléficia","qui tuer pour maléficia"}},{q="Où faut-il remettre le rapport ?",a="Après avoir éliminé la prêtresse et sa garde, faites votre rapport à L'Aînée Torntusk au Village des Revantusk.",al={"où remettre la récompense pour maléficia","emplacement de l'aînée torntusk"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="Offre d’emploi : capitaine de la garde du village des Revantusk",s="Le Village des Revantusk cherche un nouveau chef pour sa garde. Les candidats doivent faire leurs preuves contre quatre types de Vilebranch et apporter leur candidature à L'Aînée Torntusk.",h="Le Village des Revantusk cherche un nouveau chef pour sa garde.",kw={"berserker","blood drinker","capitaine de la garde","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},sec={{t="Un poste vacant",b="Le capitaine de la garde Malkhor a disparu, laissant une fois de plus la garde des Revantusk sans capitaine. L'avis invite quiconque souhaite la diriger à accomplir ses tâches et à envoyer sa candidature à L'Aînée Torntusk."},{t="Faire ses preuves",b="Pour briguer le poste de capitaine, éliminez des Berserkers Vilebranch, des Shadow Hunters, des Blood Drinkers et des Soul Eaters. Retournez ensuite auprès de L'Aînée Torntusk au Village des Revantusk."}},faq={{q="Pourquoi le poste de capitaine de la garde est-il vacant ?",a="Le capitaine de la garde Malkhor a disparu, laissant de nouveau le poste vacant.",al={"pourquoi le poste de capitaine de la garde est vacant","qu'est-il arrivé à malkhor","qui était le précédent capitaine"}},{q="À qui faut-il remettre la candidature une fois les ennemis éliminés ?",a="Apportez votre candidature à L'Aînée Torntusk, au Village des Revantusk.",al={"à qui remettre ma candidature","où déposer sa candidature","qui évalue les candidats"}},{q="Quels ennemis faut-il éliminer pour être admissible ?",a="Les candidats doivent éliminer des Berserkers Vilebranch, des Shadow Hunters, des Blood Drinkers et des Soul Eaters.",al={"quels vilebranch éliminer","cibles du poste vacant","qui éliminer pour devenir capitaine de la garde"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:78676"] = {n="The Eye of Bhossca",s="C vous envoie chercher l’Eye of Bhossca, qui se trouverait au Monastère écarlate. L’artefact doit être rapporté à une cache près du Bois-du-Bûcher.",h="C vous envoie chercher l’Eye of Bhossca, qui se trouverait au Monastère écarlate.",kw={"artefact","bhossca","c","cache","déguisement","eye of bhossca","bois-du-bûcher","monastère écarlate"},sec={{t="La demande de C",b="Un billet dans le coffre porte une nouvelle demande de C, près du Bois-du-Bûcher. L’Eye of Bhossca se trouverait quelque part au Monastère écarlate, et C veut que vous le rapportiez. Comme au Donjon d’Ombrecroc, vous devez entrer seul. Un déguisement trouvé dans l’enceinte du monastère pourrait faciliter votre passage."}},faq={{q="Qui demande l’Eye of Bhossca ?",a="C vous demande de récupérer l’Eye of Bhossca et de le rapporter à une cache près du Bois-du-Bûcher.",al={"qui le veut","qui est c","demande de c concernant l’eye"}},{q="Où se trouve l’Eye of Bhossca ?",a="Selon les sources de C, l’Eye of Bhossca se trouverait quelque part au Monastère écarlate.",al={"où est l’eye","emplacement de l’eye","trouver bhossca"}},{q="Pourquoi C veut-il l’Eye of Bhossca ?",a="C qualifie l’Eye of Bhossca d’artefact et affirme qu’il s’agit du dernier objet convoité.",al={"pourquoi l’eye","pourquoi c le veut","pourquoi le récupérer"}},{q="Où dois-je apporter l’Eye of Bhossca ?",a="Vous devez rapporter l’Eye à la cache de C, près du Bois-du-Bûcher.",al={"où le rapporter","emplacement de la cache","où est le coffre"}},{q="Dois-je y aller seul ?",a="C exige que vous entriez seul au Monastère écarlate et que vous accomplissiez la mission seul.",al={"seul ?","puis-je demander de l’aide","eye en solo"}},{q="Un déguisement serait-il utile ?",a="C affirme qu’un déguisement pourrait faciliter vos déplacements et vous suggère d’en chercher un dans l’enceinte du monastère.",al={"déguisement pour l’eye","faut-il un déguisement","où trouver un déguisement"}}},fp="18,145,11.282.0,26.92.0,28.76.0,24.82.0,24.65.0,22.79.0,22.105.0"}
P.entries["quest:78699"] = {n="The Eye of Bhossca",s="Un mot vous attend dans un coffre. Son auteur signe seulement de l’initiale C.",h="Un mot vous attend dans un coffre.",kw={"bhossca","c","coffre","œil de bhossca","garder l’œil ouvert","mot"},sec={{t="Le mot",b="Un coffre contient un mot qui vous est adressé. Son auteur dit qu’il gardera l’œil ouvert pour vous, puis signe de la lettre C."}},faq={{q="Qui a laissé le mot ?",a="Le mot est signé de l’initiale C ; aucun nom complet n’y figure.",al={"qui est c","qui l’a écrit","mot de c"}},{q="Que dit le mot ?",a="Son auteur vous dit qu’il gardera l’œil ouvert pour vous et signe de l’initiale C.",al={"que contient le coffre","mot de l’œil de bhossca","qu’a écrit c"}},{q="Où se trouve le mot ?",a="Le mot se trouve dans un coffre.",al={"où est le mot","mot dans un coffre"}}},fp="18,74,8.119.0,18.61.0,23.84.0,18.25.0"}
P.entries["quest:787"] = {n="La nouvelle Horde",s="Dans la Vallée des épreuves, Eitrigg convoque les nouvelles recrues de la Horde à L'Antre. Il vous envoie auprès de Gornek pour vous entraîner et vous explique pourquoi il a rejoint la Horde et ce que Thrall espère en faire.",h="Dans la Vallée des épreuves, Eitrigg convoque les nouvelles recrues de la Horde à L'Antre.",kw={"légion ardente","durotar","eitrigg","gornek","nouvelle horde","l'antre","thrall","vallée des épreuves"},ang={["faction:Horde"]="Pour la Horde, le règne de Thrall marque la fin de la servitude démoniaque et le retour à l'honneur, à la survie et à l'identité ancestrale.",["race:Orc"]="En tant qu'orc qui entre dans la Vallée des épreuves, vous rencontrez Eitrigg, qui se souvient du passé tragique de votre peuple et de son rachat sous Thrall.",["race:Troll"]="En tant que troll Sombrelance, vous vous entraînez aux côtés des orcs dans la Vallée des épreuves et partagez la vision de Thrall, fondée sur la survie et l'honneur."},sec={{t="Le retour d'un vétéran",b="Sur ordre du chef de guerre Thrall, Eitrigg veille sur les nouveaux aspirants de la Vallée des épreuves. Après la Deuxième guerre, il a quitté l'Ancienne Horde, écœuré par sa corruption sous l'influence de la Légion ardente. Il a vécu en exil paisible jusqu'à ce que des humains le capturent. Thrall a secouru Eitrigg, et le vétéran est revenu lorsqu'il a appris le rêve du jeune chef de guerre : une Horde honorable, enracinée dans le chamanisme ancestral et affranchie de maîtres démoniaques."},{t="Se présenter à L'Antre",b="Avant que vous ne quittiez les rudes canyons de la Vallée des épreuves, Eitrigg vous envoie dans la caverne ombragée appelée L'Antre pour parler à Gornek. Gornek parle sans détour du manque d'expérience des nouveaux aspirants. Il veille à leur entraînement afin que seuls ceux qui maîtrisent la discipline et la survie puissent gagner les contrées plus vastes de Durotar."}},faq={{q="Qui est Eitrigg ?",a="Eitrigg est un vétéran orc vieillissant qui a vu l'Ancienne Horde sombrer sous l'influence corruptrice de la Légion ardente. Désabusé, il s'est retiré dans un exil paisible à Lordaeron. Des humains l'ont capturé, puis Thrall l'a libéré. Eitrigg s'est engagé auprès de la Horde réformée de Thrall et aide désormais à former les recrues de la Vallée des épreuves.",al={"qui est eitrigg","histoire d'eitrigg","lore d'eitrigg"}},{q="Pourquoi Eitrigg parle-t-il de la « nouvelle Horde » ?",a="La Horde originelle a succombé à une soif de sang démoniaque et à l'influence de la Légion ardente. La nouvelle Horde de Thrall a rejeté le contrôle démoniaque, renoué avec les anciennes traditions chamaniques et cherché un avenir honorable et indépendant pour les orcs et leurs alliés en Kalimdor.",al={"qu'est-ce que la nouvelle horde","différence entre l'ancienne et la nouvelle horde","signification de la nouvelle horde"}},{q="Où se trouve Gornek ?",a="Gornek vous attend juste à l'entrée de L'Antre, dans une caverne bien visible creusée dans la paroi rocheuse nord de la Vallée des épreuves.",al={"où se trouve gornek","trouver gornek","emplacement de gornek"}},{q="Que se passe-t-il après s'être présenté à Gornek ?",a="Après que vous vous êtes présenté à Gornek, il vous accepte parmi les recrues d'Eitrigg et vous confie vos premières missions sur le terrain. Vous défendez la vallée et prouvez que vous êtes prêt à servir la Horde.",al={"quête après la nouvelle horde","que fait gornek","quête de gornek"}},{q="Pourquoi Eitrigg a-t-il été exilé ?",a="Eitrigg a quitté la Horde, écœuré par sa corruption démoniaque et les massacres insensés provoqués par les démonistes au service de la Légion ardente durant les guerres précédentes.",al={"pourquoi eitrigg est-il parti","raison de l'exil d'eitrigg","corruption démoniaque d'eitrigg"}},{q="Pourquoi les recrues sont-elles formées dans la Vallée des épreuves ?",a="La Vallée des épreuves offre aux jeunes orcs et aux nouveaux venus alliés un lieu isolé et accidenté de Durotar, où affronter des bêtes et des scorpides dangereux sous la surveillance d'instructeurs vétérans avant de partir explorer le vaste monde.",al={"pourquoi la vallée des épreuves","but de la vallée des épreuves","entraînement dans la vallée des épreuves"}}},fx={["42eb0b46"]={q="Pourquoi Eitrigg vous envoie-t-il auprès de Gornek ?",a="Le chef de guerre Thrall a chargé Eitrigg de superviser l'entraînement de toutes les nouvelles recrues arrivant dans la Vallée des épreuves. Tandis qu'Eitrigg accueille les nouveaux venus et leur inculque les idéaux d'une Horde libérée de la corruption démoniaque, Gornek gère les tâches pratiques nécessaires pour vous tester et vous endurcir. Eitrigg vous envoie auprès de lui afin que votre épreuve et votre entraînement puissent officiellement commencer.",al={"pourquoi voir gornek","motif d'eitrigg","pourquoi faire rapport à gornek"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:7881"] = {n="Carnival Boots",s="Les travailleurs de la Foire de Sombrelune cherchent des chaussures robustes, confectionnées par des artisans chevronnés. En échange de bottes d’excellente qualité, les employés du carnaval remettent de précieux tickets de la foire.",h="Les travailleurs de la Foire de Sombrelune cherchent des chaussures robustes, confectionnées par des artisans...",kw={"carnaval","bottes de carnaval","qualité de confection","foire de sombrelune","ticket de la foire de sombre lune"},sec={{t="Des chaussures pour la foire",b="Des collecteurs et des artisans apportent des bottes de carnaval robustes à la Foire de Sombrelune, où les travailleurs échangent de précieux tickets contre des articles d’excellente qualité. Chaque paire aide le carnaval itinérant à garder pied."}},faq={{q="Pourquoi la Foire de Sombrelune a-t-elle besoin de bottes ?",a="La Foire de Sombrelune accepte des chaussures robustes et bien confectionnées pour soutenir ses travailleurs et ses terrains de carnaval, et offre des tickets de prix en échange.",al={"utilité des bottes de carnaval","pourquoi des bottes à la foire de sombre lune"}},{q="À quoi servent les tickets de la Foire de Sombrelune ?",a="Les tickets gagnés au carnaval peuvent être réunis puis échangés contre divers prix et curiosités de la Foire de Sombrelune.",al={"que peut-on acheter avec les tickets de la foire de sombre lune","utilité des tickets de la foire"}},{q="Quel type de bottes le carnaval accepte-t-il ?",a="Les travailleurs du carnaval inspectent les bottes pour vérifier la qualité de leur confection et leur durabilité avant de remettre les tickets.",al={"échange de bottes à la foire de sombre lune","critères des bottes de carnaval"}}},fp="14,153,22.199.0,39.134.0,41.110.0,44.106.0"}
P.entries["quest:78823"] = {n="Terror of the Desert Skies",s="Un dessin grossier représente un grand oiseau de proie qui inspirait crainte et admiration. Hemet Nesingwary, dans la Vallée de Strangleronce, en sait peut-être davantage à son sujet.",h="Un dessin grossier représente un grand oiseau de proie qui inspirait crainte et admiration.",kw={"oiseau de proie","hemet nesingwary","primitive drawing","vallée de strangleronce","terreur des cieux du désert"},sec={{t="Une image terrifiante",b="Le Primitive Drawing vous parvient avec la demande de le remettre à Hemet Nesingwary, dans la Vallée de Strangleronce. Ses traits appuyés représentent un grand oiseau de proie, et l’image révèle clairement la crainte et l’admiration de l’artiste. On demande à Hemet de déterminer ce qu’elle représente."}},faq={{q="Que représente le dessin ?",a="Le Primitive Drawing représente un grand oiseau de proie.",al={"dessin d’oiseau","que représente l’image"}},{q="Qui peut me parler de cet oiseau ?",a="Hemet Nesingwary, dans la Vallée de Strangleronce, pourra peut-être vous en dire davantage sur cette créature.",al={"qui en sait quelque chose","expert des oiseaux"}},{q="À qui dois-je remettre le dessin ?",a="Remettez le Primitive Drawing à Hemet Nesingwary, dans la Vallée de Strangleronce.",al={"où remettre le dessin","dessin hemet"}}},fp="26,133,15.242.0,27.51.0,31.87.0,28.70.0"}
P.entries["quest:78830"] = {n="Terror of the Desert Skies",s="Hemet Nesingwary a entendu parler de Gharrik, un grand oiseau qui chasse dans les Terres Ingrates. Il vous prête une cage pour attraper des appâts vivants et espère que vous lui rapporterez l’une de ses plumes.",h="Hemet Nesingwary a entendu parler de Gharrik, un grand oiseau qui chasse dans les Terres Ingrates.",kw={"terres ingrates","camp cagg","plume écarlate de trophée","gharrik","grand oiseau","hemet nesingwary","appât vivant"},sec={{t="Un chasseur du désert",b="Un dessin rappelle Gharrik à Hemet Nesingwary, qui en a entendu parler lors d’une autre expédition. On dit que ce grand oiseau règne sur les Terres Ingrates en tant que prédateur suprême. On vous demande de la chercher au nord-est de Camp Cagg, où elle a été aperçue pour la dernière fois, et d’utiliser un appât vivant pour l’attirer. La petite faune est rare dans les Terres Ingrates, alors Hemet vous prête une cage pour attraper des appâts ailleurs. Il espère obtenir l’une des plumes de Gharrik."}},faq={{q="Qui est Gharrik ?",a="Gharrik est un grand oiseau que l’on dit être un prédateur suprême dans les Terres Ingrates.",al={"oiseau gharrik","oiseau du désert","qui est gharrik"}},{q="Où Gharrik a-t-elle été aperçue pour la dernière fois ?",a="Gharrik a été aperçue pour la dernière fois au nord-est de Camp Cagg, dans les Terres Ingrates.",al={"emplacement de gharrik","où trouver gharrik","nord-est de camp cagg"}},{q="Pourquoi Hemet veut-il une plume ?",a="Hemet dit qu’une plume de Gharrik ferait un beau trophée et ferait de vous le sujet de toutes les conversations du camp.",al={"plume de gharrik","plume trophée","pourquoi une plume"}},{q="Où trouver des appâts ?",a="La petite faune est rare dans les Terres Ingrates. Hemet vous conseille donc de trouver des appâts vivants ailleurs et vous prête une cage pour en attraper.",al={"appât vivant","appât pour gharrik","cage à appâts"}},{q="Qui m’a envoyé chercher Gharrik ?",a="Hemet Nesingwary vous demande de chercher Gharrik et de lui rapporter l’une de ses plumes.",al={"personne qui donne la quête de gharrik","hemet et gharrik","qui veut la plume"}}},fp="26,142,15.407.0,15.68.0,28.64.0,28.90.0,24.119.0,26.75.0"}
P.entries["quest:789"] = {n="L'aiguillon du scorpide",s="À l'Antre, dans la Vallée des épreuves, Gornek envoie les recrues de la Horde chasser des scorpides au nord-ouest du camp. Dix queues prouveront qu'elles peuvent affronter le danger au combat.",h="À l'Antre, dans la Vallée des épreuves, Gornek envoie les recrues de la Horde chasser des scorpides au...",kw={"antidote","durotar","gornek","scorpide","ouvrier scorpide","l'aiguillon du scorpide","l'antre","vallée des épreuves","venin"},ang={["class:Warrior"]="En tant que guerrier, vous apprenez auprès de Gornek que des frappes décisives peuvent venir à bout des carapaces résistantes. Mépriser les adversaires plus petits mène à la défaite.",["race:Orc"]="Jeune orc qui entre dans l'âge adulte dans la Vallée des épreuves, vous passez une épreuve essentielle d'endurance et de vigilance au combat sous l'œil de Gornek.",["race:Troll"]="Troll Sombrelance qui s'entraîne aux côtés de la Horde dans la Vallée des épreuves, vous prouvez votre valeur face aux scorpides locaux avant de vous enfoncer dans Durotar."},sec={{t="L'épreuve de l'aiguillon",b="Gornek met à l'épreuve les recrues novices de la Horde face à la faune de la Vallée des épreuves. Des ouvriers scorpides rôdent parmi les rochers au nord-ouest de l'Antre. Leur venin a humilié des guerriers chevronnés comme des novices maladroits. Les recrues doivent les affronter et rapporter dix queues pour prouver leur valeur."},{t="Venin et vigilance",b="Les scorpides sont dangereux, mais leur venin contribue aussi à sauver les initiés blessés. L'Antre garde de l'antivenin préparé à partir du venin extrait des scorpides pour soigner les novices tombés au combat. Gornek apprend aux recrues à rester vigilantes au combat. Même un petit adversaire peut avoir assez de venin pour terrasser un puissant guerrier."}},faq={{q="Qui confie L'aiguillon du scorpide ?",a="Gornek supervise l'entraînement des novices à l'Antre, dans la Vallée des épreuves. Il confie cette chasse aux jeunes guerriers et aux aventuriers.",al={"qui donne l'aiguillon du scorpide","donneur de quête scorpide","quête de gornek"}},{q="Où se trouvent les scorpides ?",a="Des ouvriers scorpides rôdent au nord-ouest de l'Antre, dans la Vallée des épreuves.",al={"où trouver des scorpides","emplacement des scorpides","scorpides de la vallée des épreuves"}},{q="Que demande Gornek après la chasse ?",a="Gornek demande dix Scorpid Worker Tails pour prouver qu'une recrue a affronté et vaincu les bêtes venimeuses.",al={"butin des scorpides","objet de quête scorpide","queues de scorpide"}},{q="Comment prépare-t-on l'antidote contre le venin des scorpides ?",a="L'Antre prépare de l'antivenin à partir du venin extrait des aiguillons des scorpides. Il en garde des réserves pour soigner les novices qui sous-estiment leurs proies.",al={"remède contre le venin des scorpides","histoire de l'antidote","préparation de l'antidote contre le venin des scorpides"}},{q="Quelle leçon Gornek veut-il apprendre aux recrues ?",a="Gornek apprend aux recrues que tout adversaire, grand ou petit, peut être mortel. L'excès de confiance face à un ennemi apparemment insignifiant peut coûter la vie.",al={"leçon de gornek","pourquoi chasser les scorpides","but de l'épreuve des scorpides"}},{q="Gornek propose-t-il d'autres entraînements après cette chasse ?",a="Après la remise des queues, Gornek dit qu'il n'a plus rien à vous apprendre à l'Antre. Il vous envoie poursuivre votre route en Durotar, au service de la Horde.",al={"que faire après l'aiguillon du scorpide","quête suivante de gornek","gornek enseigne-t-il encore quelque chose"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:7890"] = {n="Heavy Grinding Stone",s="Un préposé de la foire vous demande d’apporter des Heavy Grinding Stones. Votre livraison vous rapporte des tickets pour la foire.",h="Un préposé de la foire vous demande d’apporter des Heavy Grinding Stones.",kw={"foire","pierres à aiguiser","heavy grinding stone","sucreries","tickets"},sec={{t="À la foire",b="Le préposé de la foire vous remercie et dit que les pierres font déjà grossir ses muscles. En échange, vous recevez des tickets et un avertissement : ne mangez pas trop de sucreries. Le préposé veut que vous restiez fort et prêt à vous battre."}},faq={{q="Que veut le préposé ?",a="Le préposé veut des Heavy Grinding Stones.",al={"que sont les heavy grinding stones","pierres pour la foire"}},{q="Que vais-je recevoir en apportant les pierres ?",a="Le préposé vous donne des tickets pour la foire.",al={"tickets contre des pierres","tickets de la foire"}},{q="Pourquoi le préposé parle-t-il des sucreries ?",a="Le préposé vous avertit de ne pas manger trop de sucreries et dit que vous devez rester en forme pour vous battre.",al={"trop de sucreries","sucreries de la foire"}}},fp="20,101,12.221.0,29.42.0,38.46.0,38.95.0"}
P.entries["quest:79"] = {n="La légende de Stalvan",s="À Sombre-Comté, La légende de Stalvan repose sur des pages maculées de boue et de nouvelles preuves. Smitts l'aubergiste vous remet les pages et vous envoie auprès du Commandant Althea Bouclenoire.",h="À Sombre-Comté, La légende de Stalvan repose sur des pages maculées de boue et de nouvelles preuves.",kw={"sombre-comté","bois de la pénombre","ebonlocke","enquête","mantebrume","journal maculé de boue","les veilleurs","smitts","stalvan"},ang={["class:Paladin"]="En tant que paladin, vous mettez au jour des meurtres oubliés depuis longtemps et exigez que l'on rende des comptes pour les vies innocentes fauchées dans les ombres du Bois de la Pénombre.",["class:Rogue"]="En tant que voleur, vous rassemblez des échantillons d'écriture trouvés dans des tavernes et de vieux coffres, et suivez patiemment une proie insaisissable grâce à votre travail d'enquêteur.",["faction:Alliance"]="En tant que héros de l'Alliance, vous aidez les territoires du sud à obtenir justice lorsque le soutien officiel de Hurlevent fait défaut."},sec={{t="Une avancée à Sombre-Comté",b="Smitts l'aubergiste et Marshal Haggard ont autrefois enquêté sur le massacre d'une famille noble de passage dans le Bois de la Pénombre. Haggard dirigeait alors la garde de Hurlevent. Sur les lieux, ils ont trouvé des pages de journal déchirées et maculées de boue, mais n'avaient ni échantillons d'écriture ni autres documents pour confirmer leur auteur. Ces notes ne pouvaient donc pas officiellement incriminer le reclus dont la rumeur disait qu'il vivait dans la nature.\n\nÀ présent, des preuves recueillies dans Elwynn, la Marche de l’Ouest et le Bois de la Pénombre relient l'écriture à Stalvan Mantebrume. Les vieilles rumeurs sont devenues des preuves de meurtre."},{t="Porter l'affaire à la Garde",b="Le Commandant Althea Bouclenoire dirige les Veilleurs tandis que Sombre-Comté fait face aux morts-vivants, aux bêtes sauvages et à des horreurs pires encore dans la forêt. La survie de la ville étant en jeu, elle a peu de temps à consacrer aux histoires invraisemblables ou aux soupçons sans preuve. Vous lui apportez les pages maculées de boue de Smitts, faisant d'une vieille affaire la préoccupation des Veilleurs. Ces pages consignent un massacre sur les terres du Bois de la Pénombre et donnent à la Garde des raisons de considérer Stalvan Mantebrume comme un dangereux fugitif qui doit répondre de ses actes."}},faq={{q="Quelles preuves Smitts l'aubergiste avait-il depuis tout ce temps ?",a="Il y a des années, Smitts l'aubergiste et Marshal Haggard ont trouvé des pages de journal déchirées et maculées de boue sur les lieux du massacre de nobles de passage. Il leur manquait des échantillons d'écriture pour prouver que Stalvan Mantebrume les avait écrites, jusqu'à présent.",al={"pages du journal de smitts","pages de journal maculées de boue","qu'a trouvé smitts"}},{q="Pourquoi Smitts n'a-t-il pas prévenu le Commandant Althea Bouclenoire plus tôt ?",a="Smitts et Haggard n'avaient aucune preuve reliant l'écriture des pages maculées de boue à l'ancien précepteur reclus. Sans ce lien, ils ne pouvaient présenter au Commandant Althea Bouclenoire que des indices circonstanciels.",al={"pourquoi avoir attendu si longtemps","pourquoi avoir caché les pages","pourquoi smitts n'a-t-il pas prévenu la garde"}},{q="Qui est le Commandant Althea Bouclenoire ?",a="Le Commandant Althea Bouclenoire dirige les Veilleurs, la milice de Sombre-Comté. Ses veilleurs gardent la ville et patrouillent sur les routes du Bois de la Pénombre pour repousser les morts-vivants et les prédateurs de la forêt.",al={"qui est ebonlocke","rôle d'althea bouclenoire","commandant de sombre-comté"}},{q="Quel massacre a eu lieu dans le Bois de la Pénombre ?",a="Une famille noble de passage a été massacrée dans le Bois de la Pénombre il y a plusieurs années. Bien que les rumeurs aient accusé leur ancien précepteur, Stalvan Mantebrume, les enquêteurs locaux n'avaient aucune preuve pour l'inculper.",al={"quel massacre","massacre de nobles","qui a été assassiné"}},{q="Quelle est la place de cette étape dans l'enquête générale ?",a="Après avoir fouillé les registres, les dossiers scolaires et les caisses familiales dans trois territoires, vous apportez les preuves aux autorités locales. L'enquête passe ainsi à la justice officielle et leur donne des motifs d'agir contre Stalvan.",al={"étape de la suite de quêtes de stalvan","où en est-on dans l'enquête","est-ce la fin de la quête"}},{q="Pourquoi les Veilleurs hésitent-ils tant à enquêter sur de vieux crimes ?",a="Sombre-Comté doit affronter chaque jour des monstruosités errantes, des meutes de worgens et des araignées. Le Commandant Althea Bouclenoire doit mobiliser ses veilleurs pour défendre la ville. Il lui faut donc des preuves irréfutables avant de pouvoir les affecter à de vieux crimes.",al={"pourquoi ebonlocke est-elle occupée","priorité à la défense de sombre-comté","priorités des veilleurs"}}},fx={["3928db26"]={q="Pourquoi Smitts l'aubergiste veut-il que vous parliez au commandant Bouclenoire ?",a="Smitts suit discrètement la légende de Stalvan Mantebrume depuis des années, depuis que des nobles en visite ont été massacrés à l'extérieur de Sombre-Comté. Lorsqu'il a inspecté la scène macabre avec Haggard à l'époque, ils ont trouvé des pages de journal maculées de boue mais n'avaient pas d'écriture pour les lier à l'ermite dans les bois. Maintenant que votre enquête a permis de découvrir des échantillons prouvant que Stalvan en est l'auteur, Smitts possède enfin la preuve irréfutable de l'identité du meurtrier. Il veut que vous présentiez la vérité immédiatement afin que les défenseurs de la ville puissent officiellement confronter le tueur.",al={"pourquoi smitts vous envoie à ebonlocke","motif de smitts l'aubergiste","pourquoi prévenir ebonlocke maintenant"}},["225fd2ad"]={q="Pourquoi Smitts vous envoie-t-il plutôt que de signaler cela lui-même ?",a="Smitts tient le bar à la Scarlet Raven Tavern et ne détenait que quelques fragments épars du massacre original. C'est vous qui avez réellement suivi la piste à travers les Marche de l'Ouest et le Bois de la Pénombre, récupérant les lettres et les journaux qui lient l'écriture à Stalvan Mantebrume. Parce que vous avez découvert les indices vitaux reliant tout le puzzle, le commandant Bouclenoire a besoin d'entendre le récit complet de la bouche de l'enquêteur qui l'a prouvé.",al={"pourquoi smitts ne parle pas à ebonlocke","pourquoi moi le rapport stalvan","pourquoi je fais rapport à ebonlocke"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:7900"] = {n="Torn Bear Pelts",s="Vous apportez des peaux d’ours déchirées à quelqu’un qui compte les faire coudre pour en faire des peluches. Des tickets vous sont proposés en paiement.",h="Vous apportez des peaux d’ours déchirées à quelqu’un qui compte les faire coudre pour en faire des peluches.",kw={"peaux d’ours","peinture","peluches","rembourrage","tickets","peaux d’ours déchirées"},sec={{t="Une nouvelle utilisation",b="Le destinataire compte faire coudre les peaux d’ours pour en faire des peluches, avec du rembourrage et de la peinture. Il vous propose des tickets en paiement."}},faq={{q="À quoi serviront les peaux d’ours ?",a="Elles doivent être cousues pour en faire des peluches, avec du rembourrage et de la peinture.",al={"utilité des peaux d’ours déchirées","que faire avec les peaux"}},{q="Qu’est-ce que je recevrai pour les peaux ?",a="Le destinataire vous propose des tickets en paiement.",al={"paiement pour les peaux","tickets contre des peaux"}},{q="Qui coudra les jouets ?",a="Le destinataire dit que quelqu’un coudra les peaux pour en faire des peluches.",al={"qui fabrique les peluches","qui coud les ours"}}},fp="15,113,9.124.0,28.69.0,28.44.0,22.62.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="Sur un campement récent, il ne reste que des braises qui refroidissent et des provisions éparpillées. Un parchemin roussi porte une énigme sur la recherche d'une terre jumelle, le seul indice laissé derrière.",h="Sur un campement récent, il ne reste que des braises qui refroidissent et des provisions éparpillées.",kw={"... and that note you found","mot boursouflé","mot calciné","braises","feu récent","provisions éparpillées","terre jumelle"},sec={{t="Des braises dans la nature",b="Un feu de camp récent s'éteint près de provisions éparpillées et d'un morceau de papier boursouflé. Quiconque s'est arrêté ici est parti récemment, et le parchemin a échappé de justesse aux flammes. Les provisions sont restées à découvert, comme si le voyageur était parti à la hâte ou avait été interrompu."},{t="Une énigme cryptique",b="Le fragment rescapé porte une seule consigne : « Tout ce qui brûle n'est pas perdu. Trouvez la terre jumelle, trouvez l'endroit. » Aucune signature, aucune coordonnée ni autre contexte n'a survécu au feu. L'énigme est la seule piste laissée à quiconque la découvre."}},faq={{q="Que dit le mot trouvé au campement ?",a="Le mot noirci et boursouflé indique : « Tout ce qui brûle n'est pas perdu. Trouvez la terre jumelle, trouvez l'endroit. » C'est le seul indice laissé dans le campement abandonné.",al={"que dit le mot","texte du mot","mot boursouflé"}},{q="Qui a laissé le mot derrière lui ?",a="L'auteur du mot est inconnu. Il a été trouvé parmi des provisions éparpillées, près des braises mourantes d'un feu de camp récent, ce qui laisse penser que la personne qui l'a écrit ou transporté est partie récemment ou a dû partir à la hâte.",al={"d'où vient le mot","qui a écrit le mot","qui a allumé le feu"}},{q="À quoi fait référence la « terre jumelle » ?",a="Dans le mot, la « terre jumelle » désigne un lieu semblable ou un reflet. Le fragment calciné ne donne aucune autre explication et laisse aux voyageurs le soin d'en percer le sens.",al={"qu'est-ce que la terre jumelle","indice de la terre jumelle"}},{q="Comment suivre les indices du mot ?",a="Le mot calciné est votre seul guide, et aucune destination n'est indiquée sur une carte. Son énigme vous invite à chercher une terre ou un lieu qui rappelle sa description.",al={"que faire du mot","où mène cette quête"}},{q="Pourquoi le campement a-t-il été abandonné ?",a="Le campement porte les signes d'un départ précipité ou d'une perturbation. Des provisions éparpillées gisent près des braises mourantes, et il ne reste aucun autre équipement reconnaissable ni indice, hormis le fragment boursouflé.",al={"qui a abandonné les provisions","provisions éparpillées au campement"}},{q="Reste-t-il d'autres indices près du feu ?",a="Aucun autre écrit ni marqueur n'est intact près du feu de camp. Les flammes ont détruit presque tout, ne laissant que le papier boursouflé comme preuve du passage de la personne qui s'y est reposée.",al={"le feu révèle-t-il autre chose","indices du campement"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="Une note calcinée gît près d’un feu de camp mourant dans la Marche de l’Ouest. Son bref message désigne un lieu appelé la terre jumelle.",h="Une note calcinée gît près d’un feu de camp mourant dans la Marche de l’Ouest.",kw={"note boursouflée","feu de camp","note calcinée","braises","note","terre jumelle","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, vous savez déchiffrer les indices énigmatiques laissés dans des campements cachés. Ce genre de tâche vient naturellement à ceux qui vivent de chuchotements, de secrets et de messages dissimulés.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance cherchant à rétablir l’ordre dans la Marche de l’Ouest, vous faites face à un nouveau mystère aux confins du royaume : un campement non identifié et un chiffre énigmatique."},sec={{t="Un feu mourant",b="En traversant les champs abandonnés et les plaines balayées par le vent de la Marche de l’Ouest, les voyageurs découvrent des camps laissés par des vagabonds, des hors-la-loi ou des errants désespérés. Ce petit campement a été quitté à la hâte ou en secret. Ses provisions sont abandonnées, les braises rougeoyent encore et un morceau de parchemin calciné repose parmi les débris épars."},{t="Le message énigmatique",b="La note boursouflée porte deux courtes phrases : « Tout ce qui brûle n’est pas perdu. Trouve la terre jumelle, trouve l’endroit. » Ses mots indiquent une direction qui s’éloigne de la Marche de l’Ouest, sans donner de repère précis. Quel lieu partage un nom, une géographie ou un destin avec cette terre ?"}},faq={{q="Que dit la note ?",a="La note boursouflée porte ces mots : « Tout ce qui brûle n’est pas perdu. Trouve la terre jumelle, trouve l’endroit. » C’est le seul indice du campement abandonné.",al={"texte de la note","ce qui est écrit sur la note","mots de la note boursouflée"}},{q="Où cette note a-t-elle été trouvée ?",a="La note gît parmi les restes d’un feu et des provisions éparpillées, dans les étendues sauvages de la Marche de l’Ouest.",al={"emplacement de la note","où se trouve la note","emplacement du feu de camp"}},{q="Qui a laissé le feu de camp ?",a="Personne ne sait qui a quitté le camp. La personne qui a allumé le feu est partie récemment, laissant des provisions éparpillées et le message calciné parmi les braises.",al={"qui a laissé la note","propriétaire du feu de camp","auteur de la note"}},{q="À quoi fait référence « la terre jumelle » ?",a="« La terre jumelle » désigne une autre région liée à la terre où la note a été trouvée, mais le message calciné ne donne aucune autre explication.",al={"signification de la terre jumelle","qu’est-ce que la terre jumelle","où se trouve la terre jumelle"}},{q="Pourquoi la note a-t-elle brûlé ?",a="La note a été boursouflée et calcinée dans les braises. Quelqu’un a peut-être tenté de la détruire à la hâte, ou l’a laissée par inadvertance tandis que les flammes s’éteignaient.",al={"pourquoi a-t-elle brûlé","quelqu’un a-t-il essayé de brûler la note","note calcinée"}},{q="Est-ce lié à la Confrérie défias ?",a="La Marche de l’Ouest est envahie par la Confrérie défias et des squatteurs démunis, mais le message énigmatique semble plus obscur que les communications habituelles des bandits.",al={"note défias","est-ce défias","feu de camp de la confrérie défias"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7901"] = {n="Soft Bushy Tails",s="À la Foire de Sombrelune, une demande de queues touffues permet d’offrir des récompenses aux visiteurs. La foire espère que les visiteurs heureux en inviteront d’autres.",h="À la Foire de Sombrelune, une demande de queues touffues permet d’offrir des récompenses aux visiteurs.",kw={"foire de sombrelune","récompenses","soft bushy tails","queues","tickets","visiteurs"},sec={{t="Récompenses de la foire",b="Des visiteurs heureux, c’est bénéfique pour la Foire de Sombrelune. Les queues que vous apportez serviront de récompenses aux visiteurs, qui pourraient ensuite parler de la foire à leurs amis. La foire vous donne des tickets et vous invite à profiter de votre visite."}},faq={{q="À quoi servent les queues touffues ?",a="La Foire de Sombrelune les offrira en récompense à ses visiteurs.",al={"pourquoi des queues","utilisation des queues touffues","queues pour la foire"}},{q="Pourquoi la foire veut-elle des visiteurs heureux ?",a="Les visiteurs heureux parleront peut-être de la foire à leurs amis et en attireront d’autres.",al={"pourquoi des visiteurs heureux","visiteurs de la foire","plus de monde à la foire"}},{q="Que vous donne la foire ?",a="La foire vous donne des tickets.",al={"tickets de la foire","qu’est-ce que je reçois","tickets contre des queues"}}},fp="16,143,12.228.0,29.60.0,39.78.0,29.28.0"}
P.entries["quest:7905"] = {n="La foire de Sombrelune",s="Vous portez à Gelvas Grimgate un Coupon pour des bons gratuits, dans la fête foraine de la Foire de Sombrelune. Ce coupon lui est destiné.",h="Vous portez à Gelvas Grimgate un Coupon pour des bons gratuits, dans la fête foraine de la Foire de...",kw={"fête foraine","foire de sombrelune","coupon pour des bons gratuits","gelvas grimgate","bon"},sec={{t="Un bon pour Gelvas",b="Gelvas Grimgate se trouve dans la fête foraine de la Foire de Sombrelune, et vous avez sur vous un Coupon pour des bons gratuits pour lui. Le coupon attend d’être remis."}},faq={{q="À qui le bon est-il destiné ?",a="Le Coupon pour des bons gratuits est destiné à Gelvas Grimgate, qui se trouve dans la fête foraine de la Foire de Sombrelune.",al={"bon pour qui","bon de gelvas"}},{q="Où se trouve Gelvas Grimgate ?",a="Gelvas Grimgate se trouve dans la fête foraine de la Foire de Sombrelune.",al={"où est gelvas","emplacement de gelvas"}},{q="Que dois-je apporter à Gelvas ?",a="Apportez le Coupon pour des bons gratuits à Gelvas Grimgate.",al={"quel bon","bon pour un billet"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Archimage Antonidas : L’autobiographie intégrale",s="À Forgefer, vous recherchez l’Autobiographie intégrale de l’archimage Antonidas. Ce volume rare contient le récit du défunt dirigeant du Kirin Tor et éclaire l’histoire de Dalaran ainsi que le grand savoir des arcanes.",h="À Forgefer, vous recherchez l’Autobiographie intégrale de l’archimage Antonidas.",kw={"antonidas","arcanes","archimage antonidas","autobiographie","dalaran","hall of explorers","forgefer","kirin tor","library","mage"},ang={["class:Mage"]="L’archimage Antonidas fut l’un des plus grands dirigeants du Kirin Tor et un modèle d’érudition dans les arcanes. Sa vie et ses écrits personnels offrent un éclairage essentiel à tout praticien des arts des arcanes.",["faction:Alliance"]="Antonidas fut un pilier de l’Alliance de Lordaeron contre la Horde des orcs et le Fléau. Ses mémoires personnelles sont un précieux témoignage historique dans les terres de l’Alliance.",["race:Dwarf"]="Le tome provient de la grande bibliothèque du Hall of Explorers, à Forgefer. Les érudits qui le reçoivent semblent peu se soucier de priver les archivistes nains d’un volume aussi rare.",["race:Human"]="Antonidas était un archimage humain vénéré, qui dirigea le Kirin Tor et Dalaran pendant les deuxième et troisième guerres. Son autobiographie intégrale est un précieux vestige de l’histoire humaine."},sec={{t="Les paroles du grand mage",b="L’archimage Antonidas dirigea le Kirin Tor pendant des décennies et régna sur Dalaran. L’un des esprits les plus brillants d’Azeroth, il gravit les échelons de la Citadelle Pourpre et maîtrisa les arcanes. Son autobiographie intégrale relate son rôle de dirigeant durant les deuxième et troisième guerres. Pour les érudits et les praticiens de la magie, elle offre un témoignage direct sur les rouages de Dalaran et les arts des arcanes."},{t="La grande bibliothèque de Forgefer",b="Avant de rejoindre sa nouvelle demeure, le rare manuscrit reposait dans la grande bibliothèque de Forgefer. Dans le Hall of Explorers, des archivistes nains le conservaient auprès d’anciennes reliques des titans et d’ouvrages historiques nains. Leurs vastes collections renferment des textes recueillis dans des ruines et des royaumes étrangers à travers Azeroth. Pourtant, des érudits des arcanes d’ailleurs convoitent ces ouvrages pour leurs propres collections, certains que les archivistes débordés ne remarqueront jamais qu’un volume manque."}},faq={{q="Qui était l’archimage Antonidas ?",a="L’archimage Antonidas dirigea le Kirin Tor pendant de nombreuses années et régna sur la cité-État magique de Dalaran. Maître légendaire des arcanes, il fut un conseiller important de l’Alliance de Lordaeron durant la deuxième guerre. Il avertit le roi Terenas au sujet de la peste avant de périr en défendant Dalaran durant la troisième guerre.",al={"qui était antonidas","histoire de l’archimage antonidas","passé d’antonidas"}},{q="Qu’est-ce que l’autobiographie intégrale ?",a="L’archimage Antonidas écrivit lui-même cette autobiographie détaillée, où il relate sa vie, ses travaux savants et son rôle de dirigeant à Dalaran. À la tête du Kirin Tor, ses écrits constituent un précieux témoignage sur l’histoire et la magie.",al={"qu’est-ce que ce livre","livre autobiographie intégrale","tome d’antonidas"}},{q="D’où vient ce livre ?",a="Le volume provient de la bibliothèque du Hall of Explorers, à Forgefer. Les explorateurs et archivistes nains recueillent souvent des textes historiques et magiques dans les continents orientaux.",al={"d’où vient le livre","ce livre vient-il de forgefer","livre de la bibliothèque de forgefer"}},{q="Pourquoi recherche-t-on ce livre ?",a="Les érudits et les bibliothécaires recherchent des textes magiques puissants ou historiques pour enrichir leurs archives et préserver le savoir des arcanes. Les œuvres de mages légendaires sont particulièrement convoitées, de peur qu’elles ne soient perdues ou cachées dans des collections étrangères.",al={"pourquoi collectionner des livres magiques","qui veut le livre d’antonidas","pourquoi la bibliothèque veut-elle ce livre"}},{q="Qu’est-il arrivé à l’archimage Antonidas ?",a="L’archimage Antonidas périt durant la troisième guerre, lorsque le prince déchu Arthas Menethil et le Fléau envahirent Dalaran. Antonidas dressa une puissante barrière magique pour défendre la ville et ses secrets. Arthas franchit les défenses et l’abattit pour s’emparer du Livre de Medivh.",al={"antonidas est-il mort","comment antonidas est-il mort","qu’est-il arrivé à antonidas"}},{q="La bibliothèque de Forgefer remarquera-t-elle que le livre a disparu ?",a="Son destinataire écarte toute inquiétude à l’idée que les nains remarquent la disparition du livre. Les archives de Forgefer sont si vastes qu’un tome manquant passera probablement inaperçu.",al={"forgefer regrettera-t-elle le livre","vol dans la bibliothèque de forgefer"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="Archmage Theocritus' Research Journal est un tome arcanique documentant les recherches du maître Mage de la Tour d’Azora. Remis aux érudits de la Library de Forgefer, le journal apporte de précieuses connaissances magiques aux grandes archives naines.",h="Archmage Theocritus' Research Journal est un tome arcanique documentant les recherches du maître Mage de la...",kw={"connaissance des arcanes","archimage theocritus","forgefer","library de forgefer","journal de recherche","theocritus","tour d’azora"},ang={["class:Mage"]="Les érudits des arcanes apprécient les notes récupérées auprès de personnalités éminentes comme l'archimage Theocritus, dont les recherches contribuent à sauvegarder des traités magiques historiques dans les archives de Forgefer.",["faction:Alliance"]="Mettre la main sur des textes rares et des journaux enrichit le grand répertoire du savoir abrité au cœur de Forgefer pour tous les érudits de l'Alliance."},sec={{t="Notes de terrain d'un maître",b="L'archimage Theocritus est connu dans toute l'Alliance comme un lanceur de sorts estimé, en poste à la Tour d’Azora dans les confins orientaux de la Forêt d’Elwynn. Au fil d'années d'études solitaires, Theocritus a examiné de curieux artefacts, des anomalies de lignes telluriques et des menaces magiques proches, consignant ses découvertes dans des journaux détaillés. Récupérer un tel volume représente une occasion rare d'étudier les observations personnelles d'un archimage émérite du Kirin Tor."},{t="Agrandir les archives de Forgefer",b="La Ligue des explorateurs et les conservateurs de la Library de Forgefer entretiennent l'un des plus grands dépôts d'archives du continent. En remettant Archmage Theocritus' Research Journal à leurs soins, les aventuriers veillent à ce que ses connaissances arcaniques soient précieusement préservées et répertoriées aux côtés des tomes historiques de Khaz Modan. Les bibliothécaires accueillent volontiers toute nouvelle découverte magique capable d'élargir leur sagesse collective."}},faq={{q="Qu'est-ce qu'Archmage Theocritus' Research Journal ?",a="Il s'agit d'un journal de recherche érudit appartenant au Mage Archmage Theocritus, remis à la Library de Forgefer pour préserver le savoir arcanique et enrichir les archives.",al={"remise du journal de theocritus","qu'est-ce que le journal de theocritus"}},{q="Qui est l'archimage Theocritus ?",a="L'archimage Theocritus est un Mage Humain renommé qui réside dans la Tour d’Azora au sein de la Forêt d’Elwynn, où il étudie d'anciennes perturbations magiques et des artefacts.",al={"qui est theocritus","histoire de l'archimage theocritus"}},{q="Où ce journal est-il apporté ?",a="Le journal est apporté aux archivistes de la Library à Forgefer, qui rassemblent des documents rares et des manuscrits magiques pour leur collection.",al={"où rendre le journal de theocritus","qui veut le journal de theocritus"}},{q="Pourquoi la bibliothèque recherche-t-elle ce journal ?",a="Les érudits de la Library de Forgefer cherchent à préserver les connaissances arcaniques et à étudier des traités rares de maîtres lanceurs de sorts afin d'enrichir leurs registres historiques.",al={"pourquoi collecter des journaux magiques","utilité du journal de theocritus"}},{q="D'autres ouvrages magiques peuvent-ils être apportés à la bibliothèque ?",a="Oui, les conservateurs encouragent les aventuriers à continuer de rechercher des ouvrages magiques perdus et des textes historiques à travers le monde pour enrichir leur fonds d'archives.",al={"autres journaux à rendre","y a-t-il d'autres livres pour la bibliothèque"}},{q="Quel genre de recherches est consigné dans le journal ?",a="Le journal contient des notes et des observations compilées par l'archimage Theocritus au cours de ses vastes enquêtes sur les phénomènes magiques et le savoir des arcanes.",al={"que contient le journal de theocritus","contenu du journal de theocritus"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi de Gnomeregan : Le recueil d’œuvres",s="Un recueil de Rumi de Gnomeregan est recherché par une bibliothèque. Ses pages préservent des écrits et des connaissances gnomes qui pourraient autrement disparaître.",h="Un recueil de Rumi de Gnomeregan est recherché par une bibliothèque.",kw={"recueil d’œuvres","lore de gnomeregan","écrits gnomes","library","ouvrages magiques","rumi de gnomeregan"},ang={["class:Mage"]="En tant que mage, vous appréciez les écrits rares venus de tout Azeroth, qui approfondissent votre compréhension de la théorie et de l’histoire de la magie.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez aider les érudits et les conservateurs à protéger des ouvrages précieux et des textes magiques pour enrichir le savoir commun de l’Alliance.",["race:Gnome"]="En tant que gnome, préserver les écrits rassemblés de penseurs comme Rumi contribue à maintenir vivants votre culture et votre héritage intellectuel après la chute de Gnomeregan."},sec={{t="Préserver la pensée gnome",b="Les écrits gnomes ont été dispersés, ensevelis ou menacés lorsque les troggs ont envahi Gnomeregan. Aujourd’hui, des érudits et des archivistes recherchent les manuscrits, traités et recueils qui ont survécu. Ils espèrent préserver la sagesse et l’ingéniosité des penseurs gnomes."},{t="Récupération des archives",b="Lorsque des voyageurs trouvent des recueils sur le terrain et les apportent aux archives, les conservateurs les ajoutent à leurs collections grandissantes. Chaque manuscrit récupéré élargit le champ d’étude des érudits. Les archivistes accueillent d’autres textes magiques et historiques, afin qu’ils restent accessibles aux érudits, aux mages et aux historiens qui préservent le savoir d’Azeroth."}},faq={{q="Qu’est-ce que Rumi of Gnomeregan: The Collected Works ?",a="Rumi of Gnomeregan: The Collected Works est un recueil d’écrits gnomes recherché par une bibliothèque. Un aventurier le remet à un érudit afin que son savoir soit préservé et étudié.",al={"quête de rumi de gnomeregan","qu’est-ce que rumi de gnomeregan","qui est rumi"}},{q="Où faut-il remettre ce recueil ?",a="Le recueil est destiné à un conservateur ou à un érudit qui veille sur la collection d’une bibliothèque. Ils recherchent des écrits importants et des traités magiques pour les archives.",al={"où remettre les œuvres de rumi","qui récupère les livres de rumi","remettre le recueil de rumi"}},{q="Pourquoi la bibliothèque veut-elle ce recueil ?",a="La bibliothèque veut préserver des travaux érudits importants. Les érudits et les archivistes rassemblent des textes rares, des traités historiques et des manuscrits magiques, en particulier des écrits de Gnomeregan.",al={"pourquoi rassembler les livres de rumi","but de rumi de gnomeregan","pourquoi la bibliothèque veut rumi"}},{q="Qui est Rumi de Gnomeregan ?",a="Rumi de Gnomeregan est un auteur érudit ou magique dont les écrits rassemblés sont recherchés par les archivistes. Gnomeregan étant en grande partie envahie, les œuvres qui ont survécu préservent les traditions érudites des gnomes.",al={"qui était rumi de gnomeregan","lore de rumi","auteur rumi"}},{q="Peut-on apporter d’autres livres à la bibliothèque ensuite ?",a="Oui. Les archivistes accueillent volontiers d’autres découvertes, et les conservateurs encouragent les voyageurs à apporter des traités magiques rares et des ouvrages historiques pour la collection.",al={"y a-t-il d’autres livres à trouver","puis-je apporter d’autres textes","autres ouvrages magiques pour la bibliothèque"}},{q="Qui peut accomplir cette tâche ?",a="Les aventuriers de l’Alliance peuvent aider les érudits à protéger les écrits historiques et arcaniques. Toute personne qui retrouve ces textes peut les apporter aux archives pour soutenir la recherche.",al={"conditions de la quête de rumi","qui peut remettre les œuvres de rumi","rumi réservé à l’alliance"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="Une bibliothécaire vous demande d’apporter à la bibliothèque des ouvrages magiques comme The Lessons of Ta'zo. Chaque ajout enrichit sa collection et son savoir.",h="Une bibliothécaire vous demande d’apporter à la bibliothèque des ouvrages magiques comme The Lessons of Ta'zo.",kw={"collection","forgefer","connaissances","leçons","library","ouvrages de magie","ta'zo"},sec={{t="La collection d'une Library",b="Une bibliothécaire vous demande si vous avez apporté quelque chose pour enrichir la collection de la bibliothèque. Les ouvrages magiques susceptibles de lui être utiles sont les bienvenus, et vos efforts contribuent à accroître son savoir."}},faq={{q="Qui demande des ouvrages de magie ?",a="Une bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’être utiles à la bibliothèque. The Lessons of Ta'zo en est un exemple.",al={"qui est ta'zo","ta'zo bibliothèque","ta'zo"}},{q="Que demande la bibliothécaire d’apporter à la bibliothèque ?",a="La bibliothécaire demande des ouvrages magiques susceptibles d’enrichir la collection de la bibliothèque.",al={"quoi apporter à ta'zo","livres de magie","collection de la bibliothèque"}},{q="Où la collection est-elle conservée ?",a="Les bibliothécaires rassemblent ces ouvrages à Hurlevent et à Fossoyeuse.",al={"où est ta'zo","bibliothèque de forgefer","emplacement de la bibliothèque"}},{q="Pourquoi la bibliothécaire demande-t-elle des ouvrages magiques ?",a="La bibliothécaire affirme que vos efforts enrichissent le savoir de la bibliothèque.",al={"pourquoi des ouvrages de magie","enrichir les connaissances","aider la bibliothèque"}}},fp="20,145,22.183.0,32.114.0,52.81.0,29.63.0,45.72.0"}
P.entries["quest:79095"] = {n="L’abécédaire métaphysique de l’apothicaire",s="Les conservateurs recherchent The Apothecary's Metaphysical Primer pour enrichir leurs archives. Le remettre aide à préserver de rares théories alchimiques et arcaniques pour les chercheurs et les lanceurs de sorts.",h="Les conservateurs recherchent The Apothecary's Metaphysical Primer pour enrichir leurs archives.",kw={"alchimie","apothicaire","fossoyeuse","library","ouvrages magiques","manuel métaphysique","tome"},ang={["class:Mage"]="En tant que mage, vous appréciez les manuels métaphysiques pour ce qu’ils révèlent sur la théorie magique, les interactions alchimiques et les fondements de l’art des arcanes.",["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider Owen Thadd, à Fossoyeuse, à retrouver de rares traités pour les collections arcaniques de la bibliothèque."},sec={{t="Une acquisition érudite",b="Les conservateurs accueillent favorablement The Apothecary's Metaphysical Primer pour son étude des principes ésotériques et magiques. Owen Thadd ajoute directement l’ouvrage à sa collection de références magiques."},{t="Enrichir les archives",b="La collection d’Owen Thadd, à Fossoyeuse, conserve des traités spécialisés. En lui apportant de rares manuels sur les théories arcaniques et alchimiques, vous aidez à préserver les connaissances métaphysiques dans les archives et à les rendre accessibles aux chercheurs, au lieu de les laisser se perdre dans la nature."}},faq={{q="Qu’est-ce que The Apothecary's Metaphysical Primer ?",a="Les conservateurs recherchent The Apothecary's Metaphysical Primer, un rare ouvrage érudit destiné à leur collection de littérature magique et à l’étude des sciences métaphysiques.",al={"qu’est-ce que the apothecary's metaphysical primer","quête du manuel métaphysique","qu’est-ce que ce livre"}},{q="À qui faut-il remettre ce manuel ?",a="Owen Thadd, à Fossoyeuse, souhaite recevoir le manuel. Il recherche des ouvrages magiques et des traités arcaniques afin de préserver le savoir pour les chercheurs et les lanceurs de sorts.",al={"qui veut ce livre","où remettre le manuel","qui prend le manuel"}},{q="Pourquoi la bibliothèque rassemble-t-elle ce genre d’ouvrages ?",a="Les bibliothèques et les archives rassemblent des ouvrages métaphysiques et magiques pour enrichir leurs connaissances. Ces textes aident les érudits, les alchimistes et les arcanistes à étudier les principes arcaniques.",al={"pourquoi la bibliothèque veut ce manuel","but de la collecte du manuel","pourquoi collectionner des livres magiques"}},{q="Pouvez-vous apporter d’autres ouvrages magiques à la bibliothèque ?",a="Les érudits qui répertorient la littérature magique accueillent volontiers les découvertes arcaniques et savantes que vous trouverez pour leurs archives.",al={"y a-t-il d’autres livres à remettre","puis-je apporter d’autres livres","autres livres pour la bibliothèque"}},{q="Quel savoir contient un manuel métaphysique ?",a="Dans les études magiques, la métaphysique porte sur la nature des énergies magiques, les forces invisibles qui régissent la réalité et les interactions entre les composants physiques et les forces arcaniques.",al={"que signifie métaphysique dans wotlk classic","métaphysique dans le lore de wow","qu’est-ce que la métaphysique des apothicaires"}},{q="Qui a écrit The Apothecary's Metaphysical Primer ?",a="Les archives ne nomment pas l’apothicaire qui a écrit le manuel. Les apothicaires et les érudits compilent souvent des manuels sur l’alchimie pratique, les mélanges d’herbes et les formules mystiques.",al={"qui a écrit le manuel de l’apothicaire","auteur du manuel de l’apothicaire","qui est l’apothicaire"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric : À propos des curiosités des arcanes",s="Ataeric cherche des écrits magiques rares pour enrichir la collection d'une bibliothèque. Les érudits espèrent approfondir ainsi leur étude de l'arcane et préserver son savoir.",h="Ataeric cherche des écrits magiques rares pour enrichir la collection d'une bibliothèque.",kw={"arcane","curiosités arcaniques","ataeric","library","ouvrages magiques","érudits"},ang={["class:Mage"]="En tant que mage, vous vous intéressez naturellement à l'étude de l'arcane. Retrouver des traités magiques et contribuer aux bibliothèques érudites convient à votre art.",["race:Dwarf"]="En tant que nain, vous connaissez la valeur des documents écrits, des artéfacts et des savoirs obscurs. Les érudits nains et l'Explorers' League les tiennent en haute estime."},sec={{t="Préserver le savoir arcanique",b="Partout en Azeroth, les érudits comptent sur les voyageurs pour retrouver des tomes et des traités rares en terres dangereuses. Ataeric cherche des écrits magiques pour élargir l'étude de l'arcane dans une institution. Chaque ouvrage peut aider les érudits à reconstituer des pratiques qui, autrement, resteraient dispersées ou seraient perdues."},{t="Des archives qui s'enrichissent",b="Le conservateur ajoute chaque curiosité aux archives. La bibliothèque reste avide d'autres écrits magiques découverts à travers le monde, afin d'enrichir sa collection au fil des recherches."}},faq={{q="Quel est le but de cette quête ?",a="Ataeric cherche des écrits magiques pour enrichir la collection de savoir arcanique d'une bibliothèque.",al={"quelle est cette quête","quête d'ataeric","remettre les curiosités arcaniques"}},{q="Qui rassemble ces écrits arcaniques ?",a="Ataeric a écrit le traité. Un chercheur ou un conservateur rassemble des ouvrages magiques et des volumes rares pour les archives d'une bibliothèque.",al={"qui les demande","qui reçoit le livre","qui est ataeric"}},{q="Quelle bibliothèque profite de ces curiosités ?",a="Ces curiosités sont recherchées pour le fonds universitaire d'une bibliothèque érudite.",al={"de quelle bibliothèque s'agit-il","où vont ces livres"}},{q="Y a-t-il d'autres ouvrages magiques à collecter ?",a="Oui. L'érudit accueille tout autre ouvrage magique découvert au cours de vos voyages pour enrichir le savoir de la bibliothèque.",al={"peut-on en remettre davantage","ouvrages magiques répétables","d'autres livres pour la bibliothèque"}},{q="Pourquoi la bibliothèque recherche-t-elle des curiosités arcaniques ?",a="La bibliothèque recherche des traités rares pour approfondir l'étude de l'arcane et préserver le savoir mystique.",al={"qu'étudie la bibliothèque","pourquoi collecter des livres arcaniques"}},{q="Pourquoi est-il important de retrouver des ouvrages arcaniques ?",a="Retrouver des ouvrages arcaniques permet de préserver et d'étudier dans une bibliothèque des connaissances obscures qui, autrement, resteraient perdues sur le terrain.",al={"est-ce dangereux","risque de magie arcanique"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan : Sur les magies destructrices",s="À la Library, Baxtan: On Destructive Magics rejoint les ouvrages qui aident les érudits à comprendre les dangereux pouvoirs arcaniques.",h="À la Library, Baxtan: On Destructive Magics rejoint les ouvrages qui aident les érudits à comprendre les...",kw={"arcanes","baxtan","livre","magies destructrices","library","magie","tome"},ang={["class:Mage"]="En tant que mage, vous pouvez apprécier les traités sur la magie destructrice tandis que vous étudiez le pouvoir arcanique et ses dangers.",["class:Warlock"]="En tant que démoniste, vous pouvez comprendre pourquoi les érudits cherchent à étudier les pouvoirs instables ou interdits.",["faction:Alliance"]="En tant que membre de l’Alliance, vous profitez de l’enrichissement du savoir conservé pour tous dans les bibliothèques de l’Alliance."},sec={{t="Un tome des arts destructeurs",b="Les érudits cherchent à préserver le savoir arcanique. Quand vous trouvez un texte sur la magie destructrice, il doit être conservé avec soin par des universitaires. Ainsi, sa puissance et ses dangers peuvent être compris plutôt que sombrer dans l'oubli."},{t="Les savoirs de la Library",b="La Library rassemble des ouvrages d'histoire, de science et d'arcanes. Son érudit accueille les voyageurs qui rapportent des traités oubliés de contrées dangereuses. Chaque volume enrichit les connaissances de la Library."}},faq={{q="Que représente la quête « Baxtan: On Destructive Magics » ?",a="Vous apportez le traité de Baxtan sur les magies destructrices à un érudit de la Library, qui ajoute ainsi un ouvrage de magie à la collection.",al={"que représente baxtan: on destructive magics","que représente cette quête","quête de baxtan"}},{q="Qui est Baxtan ?",a="Baxtan a écrit On Destructive Magics. L’érudit qui reçoit l’ouvrage rassemble des tomes importants et des traités magiques pour la Library.",al={"qui est baxtan","pnj baxtan","où se trouve baxtan"}},{q="Quels types de livres Baxtan recherche-t-il ?",a="L’érudit de la Library recherche des ouvrages d’étude et de magie pour la collection, notamment des traités que vous découvrez à travers le monde.",al={"quel genre de livres baxtan recherche","collection de livres de baxtan","d’autres livres pour baxtan"}},{q="Où ces connaissances magiques sont-elles conservées ?",a="Les textes rassemblés rejoignent la collection de la Library, où les érudits les préservent afin d’étudier les arcanes et leurs dangers.",al={"où va le livre","quelle bibliothèque","collection de la bibliothèque de forgefer"}},{q="Pourquoi la Library rassemble-t-elle des ouvrages sur la magie destructrice ?",a="Les érudits répertorient la magie destructrice pour comprendre les dangers, le fonctionnement et les formes des puissantes énergies arcaniques.",al={"pourquoi étudier la magie destructrice","savoir sur les magies destructrices"}},{q="Pouvez-vous apporter d’autres ouvrages magiques à Baxtan ?",a="Oui. L’érudit accueille les autres ouvrages magiques que vous découvrez dans le cadre d’un effort continu pour rassembler le savoir.",al={"y a-t-il d’autres quêtes pour baxtan","puis-je remettre d’autres livres"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="Assumer ses responsabilités",s="Assumer ses responsabilités est une tâche d'initiation confiée par Furl Morguefront au sommet de la tour de guet surplombant Tranchecolline. Trop âgé pour combattre en première ligne, ce vétéran balafré demande aux jeunes aventuriers de la Horde de récupérer du canevas sur les humanoïdes et centaures hostiles de la région afin de confectionner du ravitaillement pour leur périple.",h="Assumer ses responsabilités est une tâche d'initiation confiée par Furl Morguefront au sommet de la tour de...",kw={"morceaux de canevas","assumer ses responsabilités","durotar","furl morguefront","kolkar","tranchecolline","tour de guet de tranchecolline","tiragarde"},ang={["faction:Horde"]="Chaque jeune soldat en Durotar s'appuie sur des vétérans chevronnés comme Furl Morguefront, qui rappellent aux nouveaux venus qu'honorer la Horde exige d'accomplir chaque tâche réclamée par la patrie, qu'il s'agisse de garder un avant-poste ou de coudre du canevas.",["profession:Tailoring"]="Furl fait montre d'un artisanat de frontière pragmatique et rustique, transformant le lourd canevas récupéré sur les envahisseurs humains et les maraudeurs centaures en équipement de survie durable.",["race:Orc"]="Furl incarne l'ancienne génération d'orcs qui s'est affranchie de la corruption démoniaque, a traversé les mers avec Thrall et consacre désormais ses dernières années à bâtir l'avenir de leur nation naissante."},sec={{t="La vocation d'un vétéran",b="Furl Morguefront est un vétéran de la Troisième guerre qui a marché aux côtés du chef de guerre Thrall lors de la colonisation de Durotar et de la défense désespérée au mont Hyjal. Désormais ralenti par l'âge et d'anciennes blessures, il ne manie plus sa hache au combat. À la place, il monte une garde vigilante depuis la tour de guet de Tranchecolline, sonnant l'alarme contre les incursions tout en soutenant la nouvelle génération de défenseurs."},{t="Canevas de récupération",b="Les alertes au cor se faisant plus rares à mesure que l'emprise de la Horde sur la région se renforce, Furl passe ses journées à fabriquer de l'équipement pratique. Le canevas robuste est difficile à trouver dans les canyons arides de Durotar, mais il est transporté en abondance par les intrus kultirassiens le long de la côte orientale ainsi que par les centaures nomades Kolkar qui arpentent les plaines. Récupérer des morceaux sur ces forces hostiles fournit à Furl l'étoffe nécessaire pour coudre des sacs utilitaires destinés aux éclaireurs."}},faq={{q="Qui est Furl Morguefront ?",a="Furl Morguefront est un vieux vétéran orc posté dans la tour de guet au-dessus de Tranchecolline. Il a combattu aux côtés de Thrall lors de la fondation de Durotar et a pris part aux rangs unifiés qui ont abattu Archimonde au mont Hyjal. Ne pouvant plus combattre en première ligne, il sert de vigie et met son temps libre à profit pour confectionner de l'équipement de campagne pour les jeunes guerriers de la Horde.",al={"qui est furl","histoire de furl morguefront","qui donne assumer ses responsabilites"}},{q="Où trouver des morceaux de canevas en Durotar ?",a="Des morceaux de canevas s'obtiennent sur les humains kultirassiens qui occupent le Donjon de Tiragarde le long de la côte de Durotar, ainsi que sur les centaures Kolkar campant dans les plaines. Ces deux factions possèdent des matériaux tissés épais pouvant être récupérés dans leurs campements et sur leurs dépouilles.",al={"ou trouver des morceaux de canevas","qui donne des morceaux de canevas","emplacements des morceaux de canevas"}},{q="Où se trouve la tour de guet dans laquelle se tient Furl ?",a="La tour de guet de Furl est perchée sur les hautes falaises rocheuses situées directement au nord-ouest de Tranchecolline. Un sentier sinueux derrière le campement mène au sommet où se dresse la structure de guet en bois.",al={"ou se trouve furl morguefront","emplacement tour de guet de tranchecolline","trouver la tour de guet de tranchecolline"}},{q="Que fabrique Furl avec les morceaux de canevas ?",a="Furl assemble les morceaux de canevas récupérés pour confectionner un sac utilitaire robuste. Pour les jeunes aventuriers qui parcourent Durotar, disposer d'un espace de transport supplémentaire pour leurs provisions, leurs rations et les armes récupérées est essentiel pour survivre dans ces terres inhospitalières.",al={"que fabrique furl","a quoi sert le canevas","recompense morceaux de canevas"}},{q="Pourquoi un vieux guerrier fabrique-t-il des sacs au lieu de se battre ?",a="Des décennies de combats incessants ont éprouvé le corps de Furl, l'empêchant d'égaler la vitesse et la force requises sur le champ de bataille. Plutôt que de déplorer sa retraite, il trouve son honneur à veiller sur Tranchecolline et à confectionner de l'équipement qui permet directement aux plus jeunes combattants de défendre le territoire.",al={"pourquoi furl fabrique des objets","pourquoi furl reste dans la tour","pourquoi furl ne se bat pas"}},{q="À quelle guerre Furl a-t-il participé ?",a="Furl a combattu sous les ordres du chef de guerre Thrall pendant la Troisième guerre, prenant part à l'établissement de Durotar ainsi qu'à l'affrontement décisif de la bataille du mont Hyjal contre la Légion ardente. Il se remémore avec fierté avoir répondu à l'appel lors de la trêve temporaire et salutaire forgée entre la Horde, les elfes de la nuit et l'Alliance pour vaincre Archimonde.",al={"passe guerrier de furl","que faisait furl avant","archimonde furl"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="Dans un camp isolé des Tarides, une note usée indique Stepping Stones, un refuge de montagne près de Désolace. Elle raconte que deux courriers livraient The New Plague et qualifie leur mort soudaine de simples accidents d’apothicaire.",h="Dans un camp isolé des Tarides, une note usée indique Stepping Stones, un refuge de montagne près de Désolace.",kw={"désolace","mercenaries","montagnes","the new plague","note","société royale des apothicaires","stepping stones","les tarides"},ang={["class:Rogue"]="En tant que voleur, vous savez suivre la piste d’informateurs anonymes et évaluer les messages secrets laissés entre Désolace et les Tarides.",["faction:Horde"]="En tant que voyageur de la Horde dans les Tarides, vous vous demandez si les rumeurs de livraisons d’une peste mortelle sur les terres de Kalimdor menacent vos terres et vos alliances.",["race:Undead"]="Pour les voyageurs réprouvés, une mention suspecte de la Société royale des apothicaires et de ses recherches sur le chancre peut signaler une urgence en matière de sécurité ou un dangereux complot interne."},sec={{t="Une note dans les terres sauvages",b="Un message déchiré est accroché à une planche de bois dans un camp isolé des Tarides. Mercenaries, coupe-jarrets et vagabonds s’arrêtent dans ces camps pour s’abriter brièvement, loin des regards de La Croisée ou de Cabestan. Parmi les signes ordinaires des terres sauvages, cette note vous donne une raison de regarder au-delà du camp, vers les montagnes."},{t="Rumeurs sur The New Plague",b="L’auteur anonyme affirme que deux agents livraient The New Plague, puis qualifie leur mort soudaine de simples accidents d’apothicaire. La note vous invite à le retrouver dans un refuge de montagne entre les Tarides et Désolace, où vous pourrez discuter de l’affaire en sécurité."}},faq={{q="De quoi parle la note trouvée à Stepping Stones ?",a="La note dit que deux courriers chargés de livrer The New Plague ont connu une mort soudaine, que l’auteur qualifie de simples accidents d’apothicaire. L’auteur propose un lieu de rendez-vous en montagne pour discuter de ce qui s’est passé.",al={"note de stepping stones","de quoi parle la note","texte de quête stepping stones"}},{q="Où la note vous dit-elle d’aller ?",a="L’auteur vous indique un refuge isolé dans les montagnes, entre les Tarides et Désolace.",al={"où aller à stepping stones","coin agréable dans les montagnes","emplacement de stepping stones"}},{q="Qu’est-ce que The New Plague, mentionnée dans la lettre ?",a="The New Plague est un mélange mortel mis au point à Fossoyeuse par la Société royale des apothicaires des Réprouvés. Il est destiné à détruire le Fléau et les ennemis vivants. Ses essais et les courses de ses courriers sur les continents sont entourés de secret et exposent à un danger mortel.",al={"qu’est-ce que the new plague","peste des apothicaires royaux","livraisons des apothicaires"}},{q="Qui a écrit la note accrochée à la planche ?",a="La note, anonyme, est accrochée à une planche de bois brut dans un camp isolé. Son auteur propose un lieu de rendez-vous en montagne, entre les Tarides et Désolace.",al={"qui a écrit la note","auteur de stepping stones","qui attend dans les montagnes"}},{q="Pourquoi des courriers des Réprouvés seraient-ils en Kalimdor ?",a="Les apothicaires réprouvés récoltent des venins exotiques, des spores et des réactifs parmi la flore et la faune de Kalimdor. Ils coordonnent les expéditions par les avant-postes de la Horde et les routes sauvages.",al={"réprouvés dans les tarides","pourquoi the new plague en kalimdor","apothicaires dans les tarides"}},{q="Pourquoi laisse-t-on ce genre de notes dans des camps isolés ?",a="Les Tarides s’étendent au-delà des grandes villes et sont peu gouvernées. Des relais neutres, des haltes de mercenaires et des camps de hors-la-loi offrent aux voyageurs, contrebandiers et informateurs un endroit discret où laisser un message, à l’écart de la Horde et des postes de garde régionaux.",al={"histoire des camps isolés","camps de mercenaires des tarides"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="Les vils quasits",s="Dans la Vallée des épreuves, des vils quasits déferlent d’une caverne voisine. En surveillant les épreuves, Zureetha Mireloin a découvert un convent caché de la Lame ardente. Les recrues traquent désormais les familiers qui se répandent sur la terre rouge de Durotar.",h="Dans la Vallée des épreuves, des vils quasits déferlent d’une caverne voisine.",kw={"lame ardente","convent de la lame ardente","durotar","diablotins","l'antre","vallée des épreuves","les vils quasits","zureetha mireloin"},ang={["class:Warlock"]="En tant que démoniste orc ou troll, vous affrontez des invocateurs des ombres renégats qui usent de pactes démoniaques à des fins destructrices. Vous canalisez les énergies gangrenées pour assurer la survie de la Horde.",["faction:Horde"]="En tant que membre de la Horde, vous faites face aux tentatives de la Lame ardente de corrompre Durotar de l’intérieur. La jeune Horde doit fermement affirmer sa souveraineté.",["race:Orc"]="En tant qu’orc, vous rencontrez la souillure gangrenée dans vos lieux sacrés d’entraînement. C’est un rappel amer que l’héritage du Conseil des ombres continue de pourrir, malgré le rejet par Thrall de l’esclavage démoniaque."},sec={{t="Une ombre dans la vallée",b="Dans la Vallée des épreuves, de jeunes orcs et des Trolls sombrelances affrontent des épreuves de force, de discipline et de loyauté envers la Horde de Thrall. Ils étaient censés affronter des scorpides et des sangliers, pas la corruption démoniaque. Pourtant, une grotte au nord-est abrite des agents de la Lame ardente. Ils ont formé un convent secret à l’insu des surveillants de la vallée."},{t="Éliminer les diablotins",b="Zureetha Mireloin guide les nouveaux venus près de L'Antre. Elle a repéré la souillure avant qu’elle n’envahisse le canyon. Désormais, les vils quasits jaillissent de l’entrée de la grotte et lancent des boules de feu sur quiconque s’approche trop. Avant que la Horde ne puisse débusquer les maîtres cachés, de jeunes recrues sont envoyées éliminer ces serviteurs mineurs et assurer la sécurité de la vallée."}},faq={{q="Qui donne la quête Les vils quasits ?",a="Zureetha Mireloin vous confie cette tâche. Elle attend juste devant l’entrée de L'Antre, au centre de la Vallée des épreuves.",al={"donneur de quête des vils quasits","qui donne les vils quasits","où prendre la quête des vils quasits"}},{q="Que sont les vils quasits ?",a="Les vils quasits sont de petits démons semblables à des diablotins, invoqués et asservis par les cultistes de la Lame ardente. Ces serviteurs mineurs et familiers lancent des flammes contre les intrus.",al={"que sont les vils quasits","histoire des vils quasits","type de créatures des vils quasits"}},{q="Où se trouve le convent de la Lame ardente ?",a="Le convent de la Lame ardente se cache dans une grotte au nord-est de la Vallée des épreuves. Il se trouve au-delà des Mottled Boars et des Scorpid Workers qui rôdent dans les environs.",al={"emplacement du convent de la lame ardente","où se trouve le convent de la lame ardente","grotte de la vallée des épreuves"}},{q="Pourquoi la Lame ardente se trouve-t-elle dans la Vallée des épreuves ?",a="La Lame ardente est un culte clandestin qui cherche à saper la nouvelle Horde de Thrall et à répandre la corruption démoniaque. Depuis la Vallée des épreuves, ses membres peuvent se cacher tout en menaçant les nouveaux combattants de la Horde, qui affirme sa souveraineté.",al={"pourquoi la lame ardente est ici","motivations de la lame ardente","que veut la lame ardente"}},{q="Que se passe-t-il après avoir terminé Les vils quasits ?",a="Une fois les familiers qui rôdent à l’extérieur de la caverne éliminés, Zureetha Mireloin vous envoie dans la grotte. Vous y affrontez le chef des cultistes et récupérez un Médaillon de la Lame ardente.",al={"suite des vils quasits","que faire après les vils quasits","quête du médaillon de la lame ardente"}},{q="Dois-je m’enfoncer dans la grotte pour trouver les familiers ?",a="Non. Les vils quasits vivent dans la caverne, mais beaucoup grouillent autour de l’entrée et sur le sol du canyon, à l’extérieur de la grotte.",al={"les vils quasits sont-ils dans la grotte","où tuer les vils quasits","où trouver des vils quasits à tuer"}}},fx={edfaf791={q="Pourquoi Zureetha Mireloin veut-elle que les Vile Familiars soient tués ?",a="Zureetha Mireloin est venue dans la Vallée des épreuves pour guider les nouvelles recrues, mais a découvert une corruption grandissante juste aux portes de la Horde. Le culte occulte de la Lame ardente a établi un convent caché dans les grottes voisines, et leurs diablotins invoqués se répandent dans toute la vallée. Pour protéger les terrains d'épreuve et purger la souillure démoniaque avant qu'elle ne se propage davantage, elle a besoin que leur avant-garde soit éliminée.",al={"pourquoi tuer les vile familiars","motivation de zureetha mireloin","pourquoi zureetha veut la mort des vile familiars"}},["67a24c10"]={q="Pourquoi Zureetha vous envoie-t-elle au lieu de s'occuper elle-même des familiers ?",a="Vous êtes dans la Vallée des épreuves pour prouver que vous êtes digne de servir la Horde. Tandis que Zureetha coordonne la réponse contre les cultistes occultes et monte la garde à l'extérieur de l'Antre, vous envoyer sert un double objectif : cela réduit l'infestation démoniaque qui menace la vallée tout en servant de baptême du feu vital contre les puissances obscures qui sapent votre peuple.",al={"pourquoi m'envoyer","pourquoi zureetha ne se bat pas","pourquoi dois-je tuer les familiers"}}},fp="14,220,22.318.0,16.332.0,35.113.0,24.147.0,41.137.0,49.243.0,45.170.1,57.130.0"}
P.entries["quest:79229"] = {n="Highway Robbery",s="En Désolace, un camp pillé révèle les indices d’une attaque brutale. Vous cherchez quelqu’un qui puisse éclaircir les faits.",h="En Désolace, un camp pillé révèle les indices d’une attaque brutale.",kw={"attaque","campement","centaure","désolace","nain","vol sur la grand-route","humain","camp pillé","fouilleur"},sec={{t="Un camp saccagé",b="Deux humains et un nain gisent parmi les débris d’un campement en Désolace. Les marques sur leurs os évoquent une attaque sauvage, tandis que les provisions volées montrent qu’un animal n’en est pas responsable. Leurs blessures ne correspondent pas non plus aux armes des centaures. On vous demande de trouver en Désolace quelqu’un qui connaît ces terres et saura interpréter les indices."}},faq={{q="Qui a été attaqué au campement ?",a="Les restes indiquent que deux humains et un nain ont été attaqués.",al={"qui est mort au camp","victimes du campement","humains et nain"}},{q="Que s’est-il passé au campement ?",a="Le campement a été pillé, et les restes portent les traces d’une attaque sauvage.",al={"que s’est-il passé ici","camp pillé","attaque du camp"}},{q="Un animal est-il responsable ?",a="Les provisions pillées laissent penser qu’un animal n’est pas à l’origine de l’attaque.",al={"attaque animale","c’est la bête qui l’a fait","qui les a attaqués"}},{q="Les blessures ont-elles été infligées par des centaures ?",a="Les blessures ne correspondent pas aux armes des centaures.",al={"attaque des centaures","armes des centaures","est-ce l’œuvre des centaures"}},{q="Qui peut expliquer l’attaque ?",a="On vous demande de trouver en Désolace quelqu’un qui connaît bien ces terres et sait les fouiller.",al={"qui connaît le camp","demander à un fouilleur","qui trouver"}}},fp="15,119,16.330.0,33.63.0,30.73.0,26.65.0,33.41.0,27.80.0"}
P.entries["quest:79235"] = {n="On the Lam",s="Une rumeur de caravane évoque des maraudeurs de la Horde, partis de Désolace après avoir attaqué des camps humains et nains. Vous êtes envoyé vers la Baie-du-Butin pour en retrouver un.",h="Une rumeur de caravane évoque des maraudeurs de la Horde, partis de Désolace après avoir attaqué des camps...",kw={"maréchal de l’alliance","baie-du-butin","caravanes","désolace","horde","maraudeurs","en cavale"},sec={{t="Une piste jusqu’à la Baie-du-Butin",b="Un contact des caravanes décrit des attaques contre des camps humains et nains de Désolace, puis vous oriente vers la Baie-du-Butin. Les victimes et la violence des attaques ont poussé les caravanes à soupçonner des maraudeurs de la Horde. Un maréchal de l’Alliance a poursuivi les bandits, qui ont quitté Désolace. On vous demande maintenant d’en retrouver un."}},faq={{q="Qui a attaqué les camps ?",a="Une rumeur de caravane accuse un groupe de maraudeurs de la Horde d’avoir attaqué des camps humains et nains de Désolace.",al={"qui a fait ça","assaillants des camps"}},{q="Où les maraudeurs sont-ils allés ?",a="Les bandits ont fui Désolace après avoir été poursuivis par un maréchal de l’Alliance. La Baie-du-Butin est suggérée comme endroit où chercher l’un d’eux.",al={"où ils ont fui","lieu où se trouvent les maraudeurs"}},{q="Pourquoi chercher à la Baie-du-Butin ?",a="Le contact suggère la Baie-du-Butin, car des individus peu recommandables passent par son port et un maraudeur pourrait chercher un bateau.",al={"pourquoi la baie-du-butin","où trouver un maraudeur"}},{q="Que dois-je chercher ?",a="Vous cherchez l’un des maraudeurs de Désolace.",al={"objectif de la cavale","en retrouver un"}}},fp="10,150,20.286.0,23.97.0,27.116.0,22.130.0,22.55.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="À Baie-du-Butin, Tokal propose un verre en échange de la vérité sur les attaques contre des avant-postes humains et nains. Les rumeurs accusent la Horde, mais sa bande agissait sous contrat privé de mercenaires.",h="À Baie-du-Butin, Tokal propose un verre en échange de la vérité sur les attaques contre des avant-postes...",kw={"baie-du-butin","un grog à la cerise contre vos pensées","grog à la cerise","maréchal","mercenaire","pillage","contrat privé","tokal"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez apprendre qu’un mécène privé a engagé les pillards qui ont attaqué des camps humains et nains. La Horde ne les a pas engagés.",["faction:Horde"]="En tant qu’aventurier de la Horde, vous pouvez apprendre de Tokal que les attaques contre les camps de l’Alliance découlaient de contrats privés de mercenaires. Il ne s’agissait pas d’une agression officielle de la Horde."},sec={{t="Les murmures de Baie-du-Butin",b="Tokal se fait discrète à Baie-du-Butin et surveille les forces de l’ordre. De récents raids ont dévasté des camps humains et nains, et les rumeurs accusent la Horde. Quand des voyageurs qui ne travaillent visiblement pas pour le maréchal viennent poser des questions, Tokal livre une autre version. Elle propose de la raconter en échange d’un verre."},{t="Mercenaires privés",b="Tokal reconnaît avoir participé au pillage d’avant-postes humains et nains, mais affirme que la Horde n’a pas mené les raids. Sa bande travaillait sous contrat privé pour un tiers dont elle ne révèle pas le nom. Tokal exige un Grog à la cerise avant de dire qui a payé l’opération et pourquoi."}},faq={{q="Qui est Tokal ?",a="Tokal est une mercenaire qui se cache à Baie-du-Butin. Un maréchal enquête sur des raids contre des établissements humains et nains, et Tokal propose de révéler qui l’a engagée contre un Grog à la cerise.",al={"qui est tokal","tokal baie-du-butin","donneur de quête grog à la cerise"}},{q="Pourquoi Tokal veut-elle un Grog à la cerise ?",a="Tokal veut un Grog à la cerise avant de parler de ses anciens contrats. Elle expliquera ensuite qui a financé en privé les raids contre les camps de l’Alliance.",al={"pourquoi acheter du grog à la cerise","grog à la cerise tokal","que veut tokal"}},{q="La Horde est-elle responsable du pillage des camps humains et nains ?",a="Tokal affirme que la Horde n’a pas ordonné les raids contre les camps humains et nains. Les rumeurs accusent la Horde, mais son groupe agissait sous contrat privé de mercenaires.",al={"qui a engagé tokal","la horde a-t-elle attaqué les camps de l’alliance","la horde était-elle derrière les raids"}},{q="Pourquoi Tokal craint-elle un maréchal ?",a="Tokal craint un maréchal qui enquête sur le pillage d’établissements humains et nains. Elle vérifie que personne qui l’approche à Baie-du-Butin n’a été envoyé pour la traduire en justice.",al={"qui est le maréchal","tokal se cache-t-elle du maréchal","maréchal à la recherche de tokal"}},{q="Où trouver du Grog à la cerise pour Tokal ?",a="Les taverniers et les barmen de Baie-du-Butin vendent du Grog à la cerise. Apportez une chope à Tokal pour satisfaire sa demande et l’inciter à raconter son histoire.",al={"où trouver du grog à la cerise","emplacement du grog à la cerise","grog de baie-du-butin"}},{q="Pourquoi Tokal séjourne-t-elle à Baie-du-Butin ?",a="Baie-du-Butin est un port de flibustiers qui échappe à la juridiction stricte de l’Alliance et de la Horde. Une mercenaire qui se cache après des raids contre des camps humains et nains peut s’y faire oublier.",al={"pourquoi tokal est-elle à baie-du-butin","cachette de tokal"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:79242"] = {n="No Honor Among Thieves",s="Un ancien voleur désigne Illari Duskfeather comme l’elfe de la nuit qui dirigeait la bande et les a abandonnés. Il vous indique sa cachette sur la côte des Hautes-terres Arathies et son butin volé.",h="Un ancien voleur désigne Illari Duskfeather comme l’elfe de la nuit qui dirigeait la bande et les a...",kw={"hautes-terres arathies","cache","cachette","illari duskfeather","maréchal","elfe de la nuit","pas d’honneur chez les voleurs","butin volé","voleurs"},ang={["race:NightElf"]="En tant qu’elfe de la nuit, vous apprenez qu’Illari Duskfeather dirigeait une bande de voleurs et les a abandonnés quand le maréchal s’est lancé à leur poursuite."},sec={{t="Une bande trahie",b="Le maréchal est sur la piste de la bande quand Illari Duskfeather les abandonne. Un voleur survivant pense qu’ils ont servi de boucs émissaires, mais il ne sait pas pourquoi. Il laisse la poursuite à quiconque voudra s’y lancer. Illari a parlé autrefois d’une cachette sur la côte des Hautes-terres Arathies, où se trouvent encore ses marchandises volées."}},faq={{q="Qui est Illari Duskfeather ?",a="Illari Duskfeather est une elfe de la nuit qui dirigeait une bande de voleurs. Elle leur fournissait des renseignements sur les camps et ne gardait que certaines de leurs trouvailles les plus rares.",al={"illari","qui est illari","histoire d’illari duskfeather"}},{q="Pourquoi Illari a-t-elle quitté la bande ?",a="Le voleur survivant ignore pourquoi Illari a abandonné la bande alors que le maréchal était sur leurs traces.",al={"pourquoi est-elle partie","motivations d’illari","pourquoi abandonner les voleurs"}},{q="Où trouver Illari ?",a="Illari a mentionné autrefois une cachette sur la côte des Hautes-terres Arathies.",al={"lieu où se trouve illari","où est illari","cachette en arathi"}},{q="Que veut la bande à Illari ?",a="Un ancien membre de la bande vous indique la cachette d’Illari et son butin volé.",al={"butin d’illari","marchandises volées","que contient sa cachette"}},{q="Qui dirigeait la bande ?",a="Illari Duskfeather, une elfe de la nuit, dirigeait la bande.",al={"chef des voleurs","chef de bande","qui dirigeait les voleurs"}}},fp="22,194,15.303.0,26.140.0,30.100.0,24.65.0,36.90.0,24.53.0"}
P.entries["quest:793"] = {n="Alliances rompues",s="Gorn vous envoie à l’est, dans le ravin de Lethlor, libérer deux drakes noirs liés par le Seal of the Earth. Cela fait suite à la première Alliances rompues.",h="Gorn vous envoie à l’est, dans le ravin de Lethlor, libérer deux drakes noirs liés par le Seal of the Earth.",kw={"vol draconique noir","blacklash","orcs rochenoire","gorn","hematus","ravin de lethlor","seal of the earth","signe de la terre"},sec={{t="Trois pierres runiques",b="Trois pierres runiques maintiennent le Seal of the Earth fermé, une dans chacun des piliers Diamant, Opale et Améthyste du ravin de Lethlor. Gorn vous remet le Signe de la Terre, qui attire les pierres et ouvre le sceau.\n\nD’innombrables drakes vivent dans le ravin, et Blacklash et Hematus sont des adversaires redoutables. Gorn veut leur mort à tous les deux et que vous lui rapportiez leurs liens."},{t="Ce qu’en pense Gorn",b="Gorn affirme que le Vol draconique noir reste allié aux orcs renégats Rochenoire. Selon lui, dragons comme orcs doivent être maîtrisés ou chassés. Blacklash et Hematus morts, la Horde pourra regarder vers l’ouest, en direction du Pic Rochenoire."}},faq={{q="Qui donne cette quête ?",a="Gorn vous envoie dans le ravin de Lethlor, pour poursuivre les premières Alliances rompues.",al={"donneur de quête alliances rompues","emplacement de gorn","qui donne alliances rompues"}},{q="Où se trouve le ravin de Lethlor ?",a="Le ravin de Lethlor se trouve à l’extrémité est des Terres Ingrates, où vivent d’innombrables drakes.",al={"emplacement du ravin de lethlor","comment aller au ravin de lethlor","où se trouve le ravin de lethlor"}},{q="Comment libérer Blacklash et Hematus ?",a="Utilisez le Signe de la Terre pour extraire une pierre runique de chacun des trois piliers. Placez les pierres dans le Seal of the Earth pour libérer les deux drakes.",al={"comment invoquer blacklash","seal of the earth","piliers diamant opale améthyste"}},{q="Que faut-il rapporter à Gorn ?",a="Une fois les deux drakes morts, rapportez à Gorn les bindings of Blacklash, les Entraves de Hematus et le Signe de la Terre.",al={"objets à rapporter pour alliances rompues","que veut récupérer gorn","bindings of blacklash"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79358"] = {n="Storm, Earth, and Fire",s="Veyric Thunderhame vous demande de rassembler des totems élémentaires déformés dans les Hautes-terres Arathies. Il espère découvrir comment d’autres peuples pratiquent le chamanisme et trouver un moyen de contrer les pratiques élémentaires des quilboar.",h="Veyric Thunderhame vous demande de rassembler des totems élémentaires déformés dans les Hautes-terres...",kw={"hautes-terres arathies","rituel de riposte","quilboar","chamanisme","tempête, terre et feu","mille pointes","totems déformés","veyric thunderhame"},ang={["class:Shaman"]="En tant que chaman, vous êtes appelé à aider Veyric à découvrir comment les peuples d’Azeroth pratiquent le chamanisme et à comprendre les éléments déformés."},sec={{t="Un rituel de riposte",b="Veyric Thunderhame, dans les Hautes-terres Arathies, a besoin de votre aide après que les quilboar ont inondé les Mille pointes. Il affirme que leur usage des éléments a suscité l’indignation, et qu’un rituel de riposte exigera une meilleure connaissance de ces forces déformées. Un livre décrit les pratiques chamaniques des nombreux peuples d’Azeroth. Veyric vous demande de lui apporter des totems déformés de feu, de terre, d’air et d’eau afin qu’il puisse les étudier."}},faq={{q="Qui demande les totems ?",a="Veyric Thunderhame, dans les Hautes-terres Arathies, vous demande de récupérer des totems déformés de feu, de terre, d’air et d’eau.",al={"qui veut les totems","la demande de veyric"}},{q="Pourquoi Veyric a-t-il besoin des totems ?",a="Veyric veut comprendre les éléments déformés tandis qu’il prépare un rituel de riposte contre les pratiques élémentaires des quilboar.",al={"pourquoi des totems","à quoi servent-ils"}},{q="Que s’est-il passé aux Mille pointes ?",a="Les quilboar ont inondé les Mille pointes, et Veyric affirme que leur usage des éléments a suscité l’indignation.",al={"inondation des mille pointes","qu’ont fait les quilboar"}},{q="Que décrit le livre ?",a="Le livre décrit les nombreux peuples d’Azeroth et leurs pratiques chamaniques.",al={"livre sur le chamanisme","que contient le livre"}},{q="Quels totems Veyric demande-t-il ?",a="Il demande des totems déformés de feu, de terre, d’air et d’eau.",al={"types de totems","feu terre air eau"}}},fp="22,198,16.393.0,29.102.0,32.125.0,34.101.0,28.79.0,33.55.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="Un appel à rendre aux éléments leur aide vous mène au Kraal de Tranchebauge. Les quilboars détournent la puissance élémentaire, et leurs plans menacent ces terres.",h="Un appel à rendre aux éléments leur aide vous mène au Kraal de Tranchebauge.",kw={"charlga trancheflanc","elemental aid","éléments","quilboars","plans des quilboars","kraal de tranchebauge"},ang={["class:Shaman"]="En tant que chaman, vous maîtrisez les éléments et l'on vous demande de leur rendre leur aide en les protégeant des machinations des quilboars."},sec={{t="Un appel aux éléments",b="Les éléments vous ont aidé, et l'on vous demande à présent de leur rendre la pareille. Les quilboars détournent leur pouvoir à leurs propres fins et semblent étendre leur influence dans ces terres. Vous êtes envoyé au Kraal de Tranchebauge pour mettre fin à leurs machinations et protéger ces terres."}},faq={{q="Pourquoi dois-je me rendre au Kraal de Tranchebauge ?",a="Les quilboars détournent les éléments à leurs propres fins et semblent étendre leur influence. On vous demande de mettre fin à leurs machinations et de protéger ces terres.",al={"kraal de tranchebauge pourquoi","pourquoi aller au kraal","raison de l'aide élémentaire"}},{q="Qui est Charlga Trancheflanc ?",a="Charlga Trancheflanc est la quilboar que vous devez vaincre au Kraal de Tranchebauge.",al={"qui est charlga","charlga trancheflanc","trancheflanc"}},{q="Quelles informations dois-je recueillir ?",a="On vous demande de recueillir des informations sur les plans des quilboars.",al={"plans des quilboars","quelles informations","informations sur les plans"}},{q="Pourquoi devrais-je aider les éléments ?",a="Les éléments vous ont aidé, et l'on vous demande de leur rendre la pareille en protégeant ces terres des machinations des quilboars.",al={"pourquoi l'aide élémentaire","aider les éléments","rendre leur aide aux éléments"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="Prate Cloudseer vous demande d'empêcher les hurans d'inonder les Mille pointes par un chamanisme perverti. Un grimoire destiné à votre formation pourrait aider à dissiper la tempête qui approche.",h="Prate Cloudseer vous demande d'empêcher les hurans d'inonder les Mille pointes par un chamanisme perverti.",kw={"prate cloudseer","hurans","tempête terre et feu","mille pointes","grimoire","chamanisme perverti","totems corrompus"},sec={{t="Une tempête approche",b="Prate Cloudseer comptait poursuivre votre formation, mais la menace qui pèse sur les Mille pointes ne peut attendre. Vous avez vu qu'il ne faut pas prendre les hurans à la légère. Prate vous remet un grimoire destiné à l'étude et vous demande de rassembler des totems corrompus de feu, de terre, d'air et d'eau. Le grimoire pourrait contenir un moyen de dissiper la tempête qu'ils font venir."}},faq={{q="Qui demande de l'aide ?",a="Prate Cloudseer vous demande de rassembler des totems corrompus dans les Mille pointes.",al={"qui est prate","prate cloudseer","cloudseer"}},{q="Que cherchent à faire les hurans ?",a="Prate dit que les hurans comptent inonder les Mille pointes par un chamanisme perverti.",al={"plan des hurans","pourquoi les totems","tempête des hurans"}},{q="Que me donne Prate ?",a="Prate vous remet un grimoire qui était destiné à l'étude et pourrait aider à dissiper la tempête qui approche.",al={"grimoire","quel est ce livre","grimoire d'étude"}},{q="De quels totems Prate a-t-il besoin ?",a="Prate vous demande de rassembler des totems corrompus de feu, de terre, d'air et d'eau.",al={"types de totems","feu terre air eau","quels totems"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Bouclier de Grant",s="Sirra Von’Indie cherche la masse de Grant Valor au Cimetière de Colline-aux-Corbeaux, où son esprit combat encore les morts-vivants. Ces armes pourraient l’aider à en apprendre davantage sur ce fier héros.",h="Sirra Von’Indie cherche la masse de Grant Valor au Cimetière de Colline-aux-Corbeaux, où son esprit combat...",kw={"sombre-comté","grant valor","masse de grant","bouclier de grant","cimetière de colline-aux-corbeaux","sirra von'indie","mort-vivant","valor family"},sec={{t="Un héros déchu",b="À Sombre-Comté, Sirra Von’Indie vous demande de trouver la masse de Grant Valor parmi les squelettes du Cimetière de Colline-aux-Corbeaux. Le spectre de Grant a laissé son bouclier derrière lui, et son esprit y combat encore les morts-vivants. La masse pourrait permettre d’identifier la créature qui l’a blessé, et Sirra souhaite étudier ces armes."},{t="Les armes",b="À Sombre-Comté, Sirra Von’Indie s’interroge sur la façon dont une simple créature a pu terrasser Grant Valor. Selon elle, un seul faux pas peut laisser une personne infirme à vie. Les armes, pense-t-elle, en disent long sur leur propriétaire, et elle prend le temps de les étudier."}},faq={{q="Qui était Grant Valor ?",a="Grant Valor était le père de la Valor Family et un héros de Colline-aux-Corbeaux. Son spectre combat encore les morts-vivants.",al={"grant valor","qui est grant","histoire de grant"}},{q="Où est la masse de Grant ?",a="La masse de Grant se trouve sur l’un des squelettes du Cimetière de Colline-aux-Corbeaux.",al={"masse de grant","trouver la masse de grant","emplacement de la masse"}},{q="Pourquoi chercher la masse de Grant ?",a="Sirra Von’Indie vous demande de trouver la masse pour qu’elle puisse en apprendre davantage en étudiant les armes de Grant.",al={"pourquoi chercher la masse","quête du bouclier de grant","que veut sirra"}},{q="Où apporter la masse ?",a="Rapportez la masse de Grant à Sirra Von’Indie, à Sombre-Comté.",al={"rapporter la masse","emplacement de sirra","où est von'indie"}},{q="Qu’est-il arrivé à Grant ?",a="Grant a été blessé par une créature au Cimetière de Colline-aux-Corbeaux. Son esprit y combat encore les morts-vivants.",al={"grant blessé","comment grant a été blessé","bouclier de grant valor"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="Épée de Silvia",s="L’épée de Silvia Valor, laissée par son esprit, vous mène aux Defias près de la Colline-aux-Corbeaux. Cette lame appartenait à une garde qui protégeait les civils et leurs foyers.",h="L’épée de Silvia Valor, laissée par son esprit, vous mène aux Defias près de la Colline-aux-Corbeaux.",kw={"ferme des addle","sombre-comté","defias","garde","colline-aux-corbeaux","silvia valor","épée de silvia","sirra von'indi","affaires en suspens"},sec={{t="La lame d'une garde",b="L’esprit de Silvia Valor, garde de la Colline-aux-Corbeaux, a laissé son épée derrière lui. Silvia a consacré sa vie à défendre les civils et leurs foyers. Son esprit visite encore les fermes, et les Defias se sont installés à la Ferme des Addle, au sud de la Colline-aux-Corbeaux. Les en chasser est peut-être la tâche qu’elle n’a pu achever, et Sirra Von'Indi, à Sombre-Comté, attend d’en connaître l’issue."},{t="L'étude de la lame",b="À la Ferme des Addle, les Defias sont la première piste concernant les affaires laissées en suspens par Silvia Valor. À votre retour auprès de Sirra Von'Indi à Sombre-Comté, elle reconnaît en Silvia une excellente guerrière et protectrice, malgré sa vision étroite des personnes méritant sa protection. Sirra ne parvient pas à déterminer ce que Silvia attend de l'épée, alors elle poursuit son étude de la lame."}},faq={{q="Qui était Silvia Valor ?",a="Silvia Valor était une garde de la Colline-aux-Corbeaux qui a passé sa vie à protéger les civils et leurs foyers.",al={"histoire de silvia valor","qui est silvia","silvia garde de la colline-aux-corbeaux"}},{q="Pourquoi l'esprit de Silvia visite-t-il les fermes ?",a="L’esprit de Silvia visite encore les fermes, et sa tâche inachevée concerne peut-être les Defias de la Ferme des Addle.",al={"pourquoi le fantôme de silvia","pourquoi hante-t-elle les fermes","affaires en suspens de silvia"}},{q="Qui s'intéresse à l'épée de Silvia ?",a="Sirra Von'Indi, à Sombre-Comté, reprend l’histoire de l’épée. Vous retournez la voir pour en apprendre davantage sur Silvia Valor une fois le sort des Defias de la Ferme des Addle réglé.",al={"qui a donné l'épée de silvia","épée sirra von'indi","qui donne l'épée à sombre-comté"}},{q="Où les Defias se sont-ils installés ?",a="Les Defias se sont installés à la Ferme des Addle, au sud de la Colline-aux-Corbeaux.",al={"defias ferme des addle","où sont les defias","defias colline-aux-corbeaux"}},{q="Que pense Sirra de Silvia ?",a="Sirra décrit Silvia comme une excellente guerrière et protectrice, mais elle précise que Silvia avait une vision étroite des personnes méritant sa protection.",al={"avis de sirra sur silvia","silvia guerrière","quel genre de garde était silvia"}},{q="Que fait Sirra avec l'épée ?",a="Sirra poursuit son étude de la lame de Silvia Valor.",al={"que devient la lame","sirra étudie l'épée","suite de l'épée de silvia"}}},fp="14,154,15.360.0,17.332.1,21.95.0,43.109.0,30.150.0,41.73.0,32.116.0,34.43.0"}
P.entries["quest:79364"] = {n="Eyes on the Sky",s="Une note avertit que les Razormane mènent un rituel à l’abri des regards dans les Mille pointes. On vous demande de trouver une réponse à la menace des tempêtes et de la montée des eaux.",h="Une note avertit que les Razormane mènent un rituel à l’abri des regards dans les Mille pointes.",kw={"sorcellerie élémentaire","eyes on the sky","hirzek","prate cloudseer","hurans","razormane","montée des eaux","rituel","tempêtes","mille pointes"},sec={{t="Une menace grandissante",b="La note que vous avez trouvée désigne les Razormane dans les Mille pointes, où un rituel se déroule à l’abri des regards. Des tempêtes déchaînées et la montée des eaux font craindre que le canyon ne soit inondé. Les hurans puisent peut-être dans les pouvoirs élémentaires que leur a enseignés Hirzek, un chaman. Retournez auprès de vos alliés et parlez à Prate Cloudseer."}},faq={{q="Que dit la note ?",a="Elle indique que les Razormane ont creusé leurs terriers dans les Mille pointes pour mener un rituel à l’abri des regards, alors que les tempêtes se déchaînent et que les eaux montent.",al={"note dans les mille pointes","quelle note","note des razormane"}},{q="Qui est Hirzek ?",a="Hirzek est un chaman qui a enseigné aux hurans une sorcellerie qui dénature les éléments.",al={"hirzek","hirzek chaman","qui est hirzek"}},{q="Quelle menace les hurans représentent-ils ?",a="On craint que les hurans n’utilisent les pouvoirs élémentaires pour inonder le canyon.",al={"menace des hurans","rituel des razormane","que font les hurans"}},{q="À qui dois-je parler ?",a="On vous demande de parler à Prate Cloudseer dans les Mille pointes.",al={"où aller","qui trouver","prate cloudseer"}}},fp="15,160,18.309.0,23.116.0,14.76.0,33.85.0,24.64.0"}
P.entries["quest:79365"] = {n="With Wind Beneath Your Wings",s="Une Squall-breakers Potion protège brièvement des éléments de la tempête. Vous retournez auprès de Rau Cours-les-falaises, au Poste de Librevent, dans les Mille pointes.",h="Une Squall-breakers Potion protège brièvement des éléments de la tempête.",kw={"poste de librevent","rau cours-les-falaises","squall-breakers potion","tempête","mille pointes"},sec={{t="Retour au Poste de Librevent",b="La tempête menace toujours vos amis, et la protection de la potion ne dure qu’un court instant. Retournez auprès de Rau Cours-les-falaises, au Poste de Librevent, dans les Mille pointes, où vos amis attendent, en détresse."}},faq={{q="Que fait la potion ?",a="La Squall-breakers Potion vous protège des éléments de la tempête pendant un court instant.",al={"protection de la potion","squall-breakers potion"}},{q="À qui dois-je retourner ?",a="Retournez auprès de Rau Cours-les-falaises, au Poste de Librevent, dans les Mille pointes.",al={"où aller","rau cours-les-falaises"}},{q="Pourquoi dois-je y retourner ?",a="Vous retournez auprès de vos amis, qui ont besoin d’aide.",al={"amis en détresse","retour auprès des amis"}}},fp="28,152,16.197.0,24.92.0,23.63.0,20.48.0"}
P.entries["quest:79366"] = {n="Heed My Call",s="Vous utilisez les Twisted Totems contre le rituel des Razormane, puis retournez faire votre rapport à Rau Cours-les-falaises. Les élémentaires corrompus risquent de souiller ces terres.",h="Vous utilisez les Twisted Totems contre le rituel des Razormane, puis retournez faire votre rapport à Rau...",kw={"élémentaires corrompus","cercle terrestre","entends mon appel","quilboars","rau cours-les-falaises","razormane","rituel","steam pools","twisted totems"},sec={{t="Aux Steam Pools",b="Les Twisted Totems en main, vous êtes prêt à interrompre le rituel des Razormane. On vous conseille de commencer aux bassins de vapeur à l’ouest, où chaque élément abonde. Les quilboars résisteront à vos efforts. Utilisez les totems contre le rituel et ses élémentaires corrompus."},{t="Les remerciements de Rau",b="Rau Cours-les-falaises vous demande si vous avez des nouvelles de la tempête. À votre retour, il comprend que le sol grondant s’est tu et vous remercie d’avoir fait honneur au Cercle terrestre."}},faq={{q="Que veut Rau Cours-les-falaises que je fasse ?",a="Rau Cours-les-falaises veut que vous utilisiez les Twisted Totems pour mettre fin au rituel des quilboars, puis que vous reveniez lui annoncer votre réussite.",al={"mission de rau cours-les-falaises","que veut rau"}},{q="Où dois-je commencer ?",a="Commencez aux bassins de vapeur à l’ouest, où chaque élément abonde.",al={"où commencer","steam pools"}},{q="À quoi servent les Twisted Totems ?",a="Les Twisted Totems sont censés invoquer les élémentaires corrompus auxquels les quilboars font appel.",al={"twisted totems","utilité des totems"}},{q="Qui accomplit le rituel ?",a="Les quilboars Razormane accomplissent le rituel et invoquent des élémentaires corrompus.",al={"qui accomplit le rituel","rituel des razormane"}},{q="Pourquoi les quilboars pourraient-ils résister ?",a="On vous avertit que les quilboars ne resteront pas sans réagir pendant que vous interrompez leurs projets.",al={"résistance des quilboars","pourquoi m’attaquer"}}},fp="12,155,18.271.0,12.170.1,40.122.0,21.70.0,32.87.0,29.84.0,30.83.0"}
P.entries["quest:794"] = {n="Médaillon de la Lame ardente",s="Zureetha Mireloin envoie de jeunes initiés de la Horde dans la caverne de la Vallée des épreuves, où s’est rassemblée la Lame ardente. Ils affrontent un sectateur dissimulé et cherchent le Médaillon de la Lame ardente. Sa présence révèle une corruption démoniaque près de la Horde.",h="Zureetha Mireloin envoie de jeunes initiés de la Horde dans la caverne de la Vallée des épreuves, où s’est...",kw={"lame ardente","convent","durotar","médaillon","l'antre","vallée des épreuves","démoniste","yarrog baneshadow","zureetha mireloin"},ang={["class:Shaman"]="En tant que chaman, récupérer la relique souillée aide Zureetha Mireloin à révéler la corruption démoniaque qui souille la terre de Durotar.",["class:Warlock"]="En tant que démoniste, affronter Yarrog vous rappelle les dangers d’un culte démoniaque clandestin, en dehors des pactes autorisés et soigneusement dissimulés sous le règne de Thrall.",["faction:Horde"]="En tant que membre de la Horde, cette épreuve finale marque votre aptitude à vous aventurer dans les contrées plus sauvages de Durotar et à défendre la jeune nation.",["race:Orc"]="En tant qu’orc, traquer Yarrog Baneshadow montre les efforts de la nouvelle Horde pour purger ses terrains d’entraînement de l’ancienne corruption démoniaque."},sec={{t="Une menace cachée dans la vallée",b="De jeunes orcs et trolls affrontent des épreuves de combat et de survie dans la Vallée des épreuves. Une menace se rassemble à proximité. Grâce à ses divinations, la démoniste Zureetha Mireloin comprend que les Vile Familiars des falaises du nord ne sont que l’avant-garde d’une présence plus sombre. Au fond d’une caverne voisine, le culte de la Lame ardente a établi un convent secret. Ses adeptes pratiquent les arts obscurs et gardent de dangereuses reliques de puissance démoniaque."},{t="Affronter Yarrog Baneshadow",b="Yarrog Baneshadow, un démoniste orc et agent de la Lame ardente, détient le médaillon. Il attend sur une corniche surélevée, au fond de l’Antre souterrain, commande des bêtes gangrenées et manie une magie noire à l’insu des surveillants de la Vallée. Le vaincre et prendre le médaillon perturbe le commandement local du culte avant que ses rituels ne s’étendent davantage dans Durotar."},{t="L’ombre persistante",b="Le médaillon confirme les craintes de Zureetha Mireloin. Le convent de la Vallée des épreuves a été démantelé, mais la relique prouve que la Lame ardente est organisée et agit avec méthode. Son influence dépasse les terrains d’initiation. La Horde naissante doit faire face à de plus vastes complots démoniaques à travers Durotar."}},faq={{q="Où se trouve le Convent de la Lame ardente ?",a="Le Convent de la Lame ardente se trouve dans une caverne parmi les falaises, au nord-ouest de l’Antre, dans la Vallée des épreuves. Des Vile Familiars, semblables à des diablotins, l’encerclent.",al={"emplacement de la caverne du convent","où se trouve la caverne","caverne de la lame ardente dans la vallée des épreuves"}},{q="Qui porte le Médaillon de la Lame ardente ?",a="Yarrog Baneshadow porte le médaillon. Il se trouve au fond de la caverne, sur une corniche rocheuse surélevée, au-delà d’un bassin peu profond.",al={"qui fait tomber le médaillon","yarrog baneshadow","créature qui donne le médaillon"}},{q="Qu’est-ce que la Lame ardente ?",a="La Lame ardente est un culte perfide d’orcs et de démonistes corrompus par la magie gangrenée, voués aux puissances démoniaques. Ses membres complotent contre la nouvelle Horde de Thrall depuis des repaires et des campements cachés.",al={"qui sont les membres de la lame ardente","culte de la lame ardente","qu’est-ce que la lame ardente"}},{q="Pourquoi le médaillon est-il si important pour Zureetha Mireloin ?",a="Grâce à ses divinations, Zureetha Mireloin a vu le médaillon. Cet objet de pouvoir alimente les rituels obscurs du culte et prouve que des agents démoniaques infiltrent la Vallée des épreuves.",al={"pourquoi zureetha le veut","qu’est-ce que le médaillon","médaillon de zureetha mireloin"}},{q="Vaincre Yarrog met-il fin au culte dans Durotar ?",a="Non. La défaite de Yarrog purifie la caverne de la Vallée des épreuves, mais Zureetha prévient que ce convent n’est qu’une petite cellule. La Lame ardente nourrit de plus grandes ambitions à travers Durotar.",al={"la lame ardente est-elle détruite","sont-ils partis","après le médaillon de la lame ardente"}},{q="Que se passe-t-il après avoir remis le médaillon ?",a="Après avoir tué Yarrog et récupéré la relique, vous avez fait vos preuves et êtes prêt à quitter la Vallée des épreuves. Vous êtes envoyé faire votre rapport à Sen’jin Village, sur la côte sud de Durotar.",al={"quête suivante","what comes next","après cette quête"}}},fx={["29893710"]={q="À quoi sert le Médaillon de la Lame ardente ?",a="Grâce à ses divinations, Zureetha Mireloin a identifié le médaillon comme un objet de magie noire puissant dissimulé au plus profond du Convent de la Lame ardente. Possédé par Yarrog Baneshadow, il sert d'artefact de puissance démoniaque et d'emblème de l'influence persistante du conseil des ombres juste aux portes de la Horde.",al={"but du médaillon de la lame ardente","que fait le médaillon de la lame ardente","pourquoi le médaillon est puissant"}}},fp="23,237,29.405.0,29.348.1,20.290.1,40.143.0,44.124.0,26.183.0,54.170.0,53.177.0,44.191.0"}
P.entries["quest:79442"] = {n="The Tempest's Weapons",s="Un vieux chaman des Montagnes d’Alterac sait peut-être comment utiliser l’Œil de la Tempête. Vous lui apportez l’artefact pour qu’il façonne quelque chose grâce à sa magie orageuse.",h="Un vieux chaman des Montagnes d’Alterac sait peut-être comment utiliser l’Œil de la Tempête.",kw={"montagnes d’alterac","bath'rah","bath'rah la vigie des vents","œil de la tempête","chaman","magie des élémentaires de tempête","les armes de la tempête"},ang={["class:Shaman"]="En tant que chaman, vous apportez un puissant artefact de magie des élémentaires de tempête à Bath'rah, un vieux chaman qui connaît bien cette magie."},sec={{t="Un vieux chaman",b="Après le combat contre les élémentaires, vous apportez l’Œil de la Tempête à Bath'rah la Vigie des vents, dans les Montagnes d’Alterac. Il connaît bien la magie des élémentaires de tempête et perçoit le pouvoir de l’artefact. Bath'rah dit qu’il n’a pas travaillé avec un objet pareil depuis longtemps et vous recommande d’en prendre grand soin."}},faq={{q="Qui est Bath'rah ?",a="Bath'rah la Vigie des vents est un vieux chaman des Montagnes d’Alterac qui connaît bien la magie des élémentaires de tempête.",al={"bath'rah la vigie des vents","vieux chaman","qui est bath'rah"}},{q="Qu’est-ce que l’Œil de la Tempête ?",a="L’Œil de la Tempête est un puissant artefact lié à la magie des élémentaires de tempête.",al={"œil de la tempête","artefact œil","qu’est-ce que l’œil"}},{q="Pourquoi apporter l’Œil à Bath'rah ?",a="Bath'rah pourrait façonner quelque chose avec l’Œil de la Tempête, car il comprend la magie des élémentaires de tempête.",al={"pourquoi bath'rah","quête les armes de la tempête","où apporter l’œil"}},{q="Que dit Bath'rah au sujet de l’artefact ?",a="Bath'rah qualifie l’Œil de la Tempête de puissant et dit qu’il n’a pas façonné d’objet pareil depuis longtemps.",al={"réaction de bath'rah","que dit-il","fin de quête de l’œil"}}},fp="21,147,13.305.0,16.105.0,31.84.0,30.113.0,42.112.0"}
P.entries["quest:79535"] = {n="Basilisks: Should Petrification be Feared?",s="Une bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’enrichir la collection de la bibliothèque. Vos découvertes contribuent à étendre ses connaissances.",h="Une bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’enrichir la collection de la...",kw={"basilisques","collection","connaissances","library","ouvrages magiques","pétrification"},sec={{t="Une collection qui s’agrandit",b="La bibliothécaire vous remercie d’avoir enrichi la collection. Grâce à vos efforts, la bibliothèque acquiert de nouvelles connaissances, et d’autres ouvrages magiques pourraient y être les bienvenus."}},faq={{q="Que veut la bibliothécaire ?",a="La bibliothécaire accueille les ouvrages magiques susceptibles d’enrichir la collection.",al={"requête de la bibliothèque","que dois-je apporter"}},{q="Pourquoi veut-elle des ouvrages magiques ?",a="La bibliothécaire explique qu’ils peuvent enrichir la bibliothèque et étendre ses connaissances.",al={"pourquoi des livres","à quoi servent-ils"}},{q="Que se passe-t-il quand j’apporte quelque chose ?",a="La bibliothécaire vous remercie et dit que vos efforts étendent les connaissances de la bibliothèque.",al={"mise à jour de la collection","qu’ai-je ajouté"}}},fp="42,133,20.151.0,29.71.0,29.73.0,36.79.0"}
P.entries["quest:79624"] = {n="Anyone Can Cook",s="Une recette illisible semble décrire un plat de viande, et vous pensez qu’elle est écrite en ogre. Trouvez un ogre capable de la lire.",h="Une recette illisible semble décrire un plat de viande, et vous pensez qu’elle est écrite en ogre.",kw={"tout le monde peut cuisiner","recette illisible","plat de viande","ogre","recette","skonk","traduction"},ang={["profession:Cooking"]="En tant que cuisinier, vous avez de bonnes raisons de vous demander quel genre de plat de viande décrit cette recette illisible."},sec={{t="Une étrange recette",b="La recette est écrite dans une langue que vous ne savez pas lire, et elle semble décrire un plat de viande. Vous pensez surtout à l’ogre, vu sa provenance et ce qu’elle décrit. Vous espérez trouver un ogre capable de la traduire."}},faq={{q="Que permet de préparer la recette ?",a="Elle semble permettre de préparer une sorte de plat de viande.",al={"utilité de la recette","quel plat","recette de viande"}},{q="Dans quelle langue la recette est-elle écrite ?",a="Vous ne comprenez pas cette langue. Vous pensez surtout à l’ogre.",al={"langue de la recette","quelle écriture","recette impossible à lire"}},{q="Qui peut lire la recette ?",a="Vous cherchez un ogre capable de la lire.",al={"traduire la recette","qui peut la lire","ogre capable de lire"}},{q="Qui est Skonk ?",a="Skonk est un ogre qui tend l’oreille pour entendre la recette.",al={"skonk","qui est skonk","ogre skonk"}}},fp="15,112,16.213.0,23.44.0,39.60.0,24.44.0,13.49.0"}
P.entries["quest:79677"] = {n="A Quick Grocery Run",s="Skonk vous demande de réunir des ingrédients pour un plat dans les Hautes-terres Arathies. Il a appris à cuisiner après que d’autres ogres se sont moqués de sa taille et de ses talents au combat.",h="Skonk vous demande de réunir des ingrédients pour un plat dans les Hautes-terres Arathies.",kw={"hautes-terres arathies","cuisine","plat","ingrédients","ogre","skonk","moqueries"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez aider Skonk à réunir des ingrédients pour un plat qu’il sait préparer."},sec={{t="Les ingrédients de Skonk",b="Skonk, un ogre des Hautes-terres Arathies, a besoin d’ingrédients pour un plat qu’il sait préparer. D’autres ogres se moquaient de sa taille et le traitaient de faible, alors il s’est tourné vers la cuisine. Vous réunissez les ingrédients et les lui apportez."}},faq={{q="Qui est Skonk ?",a="Skonk est un ogre qui a appris à cuisiner après que d’autres ogres se sont moqués de sa taille et de ses talents au combat.",al={"skonk","qui est skonk"}},{q="Pourquoi Skonk cuisine-t-il ?",a="D’autres ogres se moquaient de Skonk parce qu’il était plus petit et le traitaient de faible, alors il a appris à cuisiner plutôt qu’à combattre.",al={"pourquoi cuisiner","skonk cuisine"}},{q="De quoi Skonk a-t-il besoin ?",a="Skonk a besoin d’ingrédients pour un plat qu’il sait préparer.",al={"ingrédients","quels ingrédients"}},{q="Où apporter les ingrédients ?",a="Apportez les ingrédients à Skonk dans les Hautes-terres Arathies.",al={"où est skonk","apporter les ingrédients"}}},fp="19,143,19.214.0,13.92.0,20.107.0,21.47.0,33.51.0"}
P.entries["quest:79678"] = {n="Taste Testing",s="Skonk vous invite à goûter un nouveau plat préparé sur un feu vif. Il le partage ainsi avec un nouvel ami qui l'a aidé.",h="Skonk vous invite à goûter un nouveau plat préparé sur un feu vif.",kw={"plat","feu","nourriture","recette","skonk","dégustation"},sec={{t="Un nouveau plat",b="Skonk a préparé un nouveau plat près du feu et souhaite le partager avec vous. Après tous les services que vous lui avez rendus, il estime que vous devriez aussi y goûter. La recette est prête à être dégustée."}},faq={{q="Qui est Skonk ?",a="Skonk prépare un nouveau plat et vous invite à le goûter.",al={"skonk","qui est skonk"}},{q="Que veut Skonk ?",a="Skonk veut goûter la recette avec vous.",al={"dégustation","que veut skonk"}},{q="Pourquoi Skonk partage-t-il ce plat ?",a="Skonk dit que vous lui avez rendu de nombreux services, alors il veut vous faire goûter son nouveau plat.",al={"pourquoi de la nourriture","pourquoi partager"}},{q="Que pense Skonk de la recette ?",a="Après la dégustation, Skonk dit que la recette est délicieuse.",al={"est-ce bon","goût de la recette"}}},fp="13,131,10.189.0,13.55.0,30.45.0,30.78.0,36.54.0"}
P.entries["quest:79947"] = {n="Geomancy: The Stone-Cold Truth",s="Un bibliothécaire cherche des ouvrages magiques pour enrichir la collection de la bibliothèque. Votre contribution peut élargir ses connaissances.",h="Un bibliothécaire cherche des ouvrages magiques pour enrichir la collection de la bibliothèque.",kw={"collection","géomancie","library","ouvrages magiques","la vérité froide comme la pierre"},sec={{t="Une collection grandissante",b="Tout ouvrage magique que vous trouvez peut prendre place sur les rayons de la bibliothèque. Sa collection s’enrichit grâce à vos efforts, et le bibliothécaire accueille volontiers d’autres découvertes."}},faq={{q="Que souhaite le bibliothécaire ?",a="Le bibliothécaire vous demande d’apporter des ouvrages magiques susceptibles d’enrichir la collection de la bibliothèque.",al={"que veulent-ils","demande de la bibliothèque"}},{q="D’où vient cette demande ?",a="Cette demande vient d’un bibliothécaire : Garion Wendell à Hurlevent pour l’Alliance, ou Owen Thadd à Fossoyeuse pour la Horde.",al={"où se trouve la bibliothèque","bibliothèque de forgefer"}},{q="Pourquoi apporter des ouvrages magiques ?",a="Le bibliothécaire affirme que les connaissances de la bibliothèque s’élargissent grâce à vos efforts.",al={"pourquoi des livres magiques","à quoi servent-ils"}}},fp="30,110,20.159.0,29.90.0,27.118.0,24.72.0"}
P.entries["quest:79948"] = {n="Defensive Magics 101",s="La bibliothèque recherche des ouvrages magiques pour enrichir sa collection. Vous pouvez élargir ses connaissances en lui apportant des ouvrages susceptibles d’enrichir ses rayons.",h="La bibliothèque recherche des ouvrages magiques pour enrichir sa collection.",kw={"collection","magies défensives","connaissances","library","ouvrages magiques"},sec={{t="Une collection grandissante",b="La collection de la Library peut s’enrichir grâce à vos efforts. Apportez à sa gardienne des ouvrages magiques susceptibles de garnir ses rayons, et les connaissances de la Library s’étendront."}},faq={{q="De quoi la Library a-t-elle besoin ?",a="La Library recherche des ouvrages magiques susceptibles d’enrichir sa collection.",al={"besoins de la bibliothèque","quoi apporter","livres de magie"}},{q="D’où vient cette demande ?",a="La demande vient d’un bibliothécaire. Il s’agit de Garion Wendell à Hurlevent pour l’Alliance, ou d’Owen Thadd à Fossoyeuse pour la Horde.",al={"qui en fait la demande","demande de la bibliothèque","quelle bibliothèque"}},{q="Pourquoi apporter des ouvrages magiques ?",a="Les ouvrages magiques apportés à la Library élargissent ses connaissances.",al={"pourquoi rassembler des ouvrages magiques","à quoi cela sert","collection de la bibliothèque"}}},fp="20,137,20.153.0,27.66.0,27.135.0,24.58.0"}
P.entries["quest:79949"] = {n="A Web of Lies: Debunking Myths and Legends",s="Un bibliothécaire cherche des ouvrages magiques pour enrichir le fonds de la Library. Vous pouvez apporter des écrits susceptibles d’enrichir ses rayons.",h="Un bibliothécaire cherche des ouvrages magiques pour enrichir le fonds de la Library.",kw={"livres","collection","savoir","bibliothécaire","library","ouvrages magiques"},sec={{t="Une collection qui s’agrandit",b="Tout nouveau livre est le bienvenu sur ces étagères. Les écrits magiques peuvent enrichir le savoir de la bibliothèque, et vos découvertes peuvent contribuer à le faire grandir."}},faq={{q="Que cherche le bibliothécaire ?",a="Le bibliothécaire cherche des ouvrages magiques susceptibles d’enrichir la collection.",al={"besoins du bibliothécaire","demande de la bibliothèque","quoi apporter à la bibliothèque"}},{q="Où apporter les livres ?",a="Apportez les ouvrages magiques au bibliothécaire Garion Wendell, à Hurlevent, ou à Owen Thadd, à Fossoyeuse, si vous êtes de la Horde.",al={"où se trouve la bibliothèque","bibliothèque de forgefer","où apporter les ouvrages magiques"}},{q="Pourquoi collectionner des ouvrages magiques ?",a="Selon le bibliothécaire, la collection enrichit le savoir de la bibliothèque.",al={"pourquoi apporter des livres","à quoi sert la collection","but de la bibliothèque"}}},fp="42,122,20.145.0,29.68.0,31.117.0,26.68.0"}
P.entries["quest:79950"] = {n="Demons and You",s="Un bibliothécaire vous demande d’ajouter un ouvrage magique à la collection. Grâce à vos efforts, le savoir de la bibliothèque s’enrichit.",h="Un bibliothécaire vous demande d’ajouter un ouvrage magique à la collection.",kw={"collection","démons et vous","savoir","library","ouvrages magiques"},sec={{t="Une collection de la Library",b="Tout ouvrage magique que vous apportez est le bienvenu sur les rayons. La collection s’enrichit grâce à vos efforts, et le gardien accueille volontiers d’autres ouvrages susceptibles de profiter à la bibliothèque."}},faq={{q="Que veut le gardien de la bibliothèque ?",a="Le gardien vous demande d’apporter un ouvrage magique pour l’ajouter à la collection de la bibliothèque.",al={"que dois-je apporter","demande de la bibliothèque","quête démons et vous"}},{q="Où se trouve la collection ?",a="Le gardien est un bibliothécaire. Il s’agit de Garion Wendell à Hurlevent pour l’Alliance, ou d’Owen Thadd à Fossoyeuse pour la Horde.",al={"où est-ce","emplacement de la bibliothèque","quelle bibliothèque"}},{q="Pourquoi apporter des ouvrages magiques à la bibliothèque ?",a="Le gardien dit que vos efforts enrichissent le savoir de la bibliothèque.",al={"pourquoi donner des livres","à quoi cela sert","but de la bibliothèque"}}},fp="14,118,20.166.0,34.81.0,24.126.0,39.62.0"}
P.entries["quest:79951"] = {n="Mummies: A Guide to the Unsavory Undead",s="Un bibliothécaire recherche des ouvrages magiques sur les momies et les morts-vivants répugnants. Votre contribution enrichira le savoir de la bibliothèque.",h="Un bibliothécaire recherche des ouvrages magiques sur les momies et les morts-vivants répugnants.",kw={"livres","collection","library","ouvrages magiques","momies","morts-vivants répugnants"},sec={{t="Une collection grandissante",b="La collection de la bibliothèque dépend des ouvrages apportés par les visiteurs. On vous demande d’ajouter un ouvrage sur les momies et les morts-vivants répugnants. D’autres livres magiques pourraient aussi être utiles. Chacun de ces ouvrages peut élargir les connaissances de la bibliothèque."}},faq={{q="Que rassemble le bibliothécaire ?",a="Le bibliothécaire recherche des ouvrages sur les momies et les morts-vivants répugnants, ainsi que d’autres livres magiques qui pourraient enrichir la bibliothèque.",al={"livres sur les momies","guide des morts-vivants","quels livres recherchent-ils"}},{q="Pourquoi apporter un livre à la bibliothèque ?",a="Les ouvrages apportés au bibliothécaire enrichissent les connaissances de la bibliothèque.",al={"pourquoi offrir un livre","que gagne la bibliothèque","aider la bibliothèque"}},{q="Puis-je apporter d’autres livres magiques ?",a="Oui. Le bibliothécaire accueille volontiers d’autres ouvrages magiques susceptibles d’enrichir la bibliothèque.",al={"autres livres magiques","autres ouvrages magiques","que puis-je apporter d’autre"}}},fp="39,144,20.229.0,33.127.0,32.64.0,32.79.0"}
P.entries["quest:79952"] = {n="RwlRwlRwlRwl!",s="Un bibliothécaire accueille les ouvrages magiques destinés à enrichir la collection. Vos contributions l’aident à développer son savoir.",h="Un bibliothécaire accueille les ouvrages magiques destinés à enrichir la collection.",kw={"collection","savoir","library","ouvrages magiques","rwl"},sec={{t="Une collection qui s’enrichit",b="Chaque ajout enrichit le savoir qui y est conservé, et le bibliothécaire vous en remercie. D’autres ouvrages susceptibles d’enrichir la collection sont les bienvenus."}},faq={{q="Que souhaite le gardien de la bibliothèque ?",a="Le gardien accueille les ouvrages magiques susceptibles d’enrichir la collection de la Library.",al={"livres de bibliothèque","ouvrages magiques","quoi apporter"}},{q="Où se trouve cette collection ?",a="Aucune ville n’est nommée. Les livres comme celui-ci sont à remettre à Garion Wendell à Hurlevent ou à Owen Thadd à Fossoyeuse.",al={"emplacement de la bibliothèque","bibliothèque de forgefer","où se trouve la bibliothèque"}},{q="Pourquoi apporter des ouvrages magiques ?",a="Vos contributions aident le savoir de la bibliothèque à s’enrichir.",al={"pourquoi des livres","aider la bibliothèque","quel est l’intérêt"}}},fp="13,113,20.138.0,34.76.0,25.99.0,24.53.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Sur un flanc de montagne, Wet Job vous envoie récupérer une cache de secours. Quelqu’un l’a préparée pour une fuite précipitée et cachée près d’un perchoir élevé au bord d’une falaise.",h="Sur un flanc de montagne, Wet Job vous envoie récupérer une cache de secours.",kw={"ingénierie naine","nid d’aigle","sacoche de coursier","flanc de montagne","parchemin","cache de réserve","provisions","wet job"},ang={["class:Rogue"]="En tant que voleur, vous connaissez la valeur des caches d’urgence dissimulées, gardées prêtes en cas de fuite précipitée.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez admirer l’ingéniosité naine à l’origine de cette réserve fiable, cachée dans un terrain escarpé.",["race:Dwarf"]="En tant que nain, vous pouvez être fier de la qualité durable de l’artisanat montagnard, saluée lors de la récupération de la cache."},sec={{t="Une cache d’urgence",b="En territoire dangereux, une réserve peut permettre de fuir rapidement. Vous fouillez les hauteurs escarpées à la recherche d’une cache laissée là au cas où les plans tourneraient mal. Ses provisions attendent d’être récupérées."},{t="Le nid d’aigle",b="Les indications mènent à un haut perchoir de montagne, décrit comme sculpté par les cascades du temps. Là, au nid d’aigle, une sacoche de coursier usée repose en partie enfouie dans la terre. À l’intérieur, provisions et parchemin ont résisté sous le sol, protégés par le savoir-faire nain."}},faq={{q="En quoi consiste la quête Wet Job ?",a="Vous récupérez une cache d’urgence dissimulée, préparée avec des provisions pour une fuite précipitée.",al={"qu’est-ce que wet job","quête wet job","quel genre de quête est wet job"}},{q="Qui a laissé la réserve ?",a="Quelqu’un a laissé cette cache en réserve, au cas où il faudrait fuir rapidement. Elle contient une sacoche de coursier avec un parchemin et des provisions, fabriquée selon le savoir-faire nain.",al={"qui a laissé la cache","à qui sont ces provisions","qui a caché la réserve"}},{q="Où se trouvent la cache et le nid de l’aigle ?",a="La cache est la sacoche de messager enfouie dans le monticule de terre des Serres-Rocheuses, là où commence Wet Job. Son parchemin vous mène au nid de l’aigle : le Barrage de Formepierre, à Loch Modan, où attend une figurine sculptée.",al={"où se trouve la cache","lieu de wet job","lieu du nid d’aigle"}},{q="Que trouve-t-on dans la sacoche de coursier ?",a="La sacoche de messager enfouie dans les Serres-Rocheuses contient des provisions et un parchemin, protégés par le savoir-faire des nains.",al={"que contient la cache","objets de wet job","que trouve-t-on"}},{q="Pourquoi la tâche s’appelle-t-elle Wet Job ?",a="Le nom correspond à sa destination : le nid de l’aigle est le Barrage de Formepierre, à Loch Modan, au milieu de ses cascades.",al={"pourquoi le nom wet job","signification du nom wet job"}},{q="Quel est le lien avec l’ingénierie naine ?",a="La construction et la fiabilité de la cache témoignent de l’ingénierie naine, conçue pour résister à un enfouissement en plein air.",al={"lien avec l’ingénierie naine","est-ce nain"}}},fp="7,154,18.194.0,16.273.0,32.80.0,27.162.0,50.214.0,35.112.0,31.107.0,36.101.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Sur un point de vue brumeux, Eagle's Fist monte la garde, seul, devant une barricade usée. Une lettre évoque la loyauté envers les Old Kingdoms et the Eagle and Fist, mais son auteur est parti à la hâte.",h="Sur un point de vue brumeux, Eagle's Fist monte la garde, seul, devant une barricade usée.",kw={"barricade","feu de camp","eagle's fist","lettre pliée","poste d’observation","old kingdoms","planeur parachute","boîte à outils"},ang={["profession:Engineering"]="La note du poste d’observation décrit l’endroit comme idéal pour lancer un planeur parachute. Les ingénieurs pourraient apprécier cette occasion de reconnaissance aérienne et de vol mécanique."},sec={{t="Un perchoir caché",b="Une lettre pliée se trouve dans une boîte à outils, sur un point de vue élevé. Son auteur écrit que, de là, on peut diriger les opérations ou lancer un planeur parachute au-dessus des terres. Les embruns brumeux humidifient ce poste isolé, mais la vue s’étend sur des terres historiques."},{t="Loyauté envers les Old Kingdoms",b="L’auteur de la lettre promet une loyauté durable envers the Eagle and Fist. Pour servir cette cause comme il se doit, écrit-il, il faut garder une distance mesurée. La barricade toute proche est délabrée, comme les Old Kingdoms qu’elle protégeait autrefois du danger. Pourtant, la sentinelle jure de ne jamais abandonner son poste."},{t="Un départ précipité",b="La sentinelle a quitté le point de vue à la hâte. Le feu de camp a été alimenté en bois frais tout récemment, et pourtant le guetteur a disparu. Des outils, des braises ardentes et une lettre énigmatique sont restés sur place."}},faq={{q="Qu’est-ce qu’Eagle's Fist ?",a="Eagle's Fist est un poste d’observation isolé devant une barricade usée, où une boîte à outils contient une lettre pliée. Son auteur est parti à la hâte.",al={"qu’est-ce qu’eagle's fist","quête eagle's fist","quelle est cette quête"}},{q="Qui a écrit la lettre trouvée dans la boîte à outils ?",a="Un éclaireur ou une sentinelle non identifié a écrit la lettre. L’auteur sert les Old Kingdoms et the Eagle and Fist, et monte la garde devant une barricade isolée.",al={"qui a écrit la note","qui a laissé la lettre","auteur de la lettre dans la boîte à outils"}},{q="À quoi « the Eagle and Fist » fait-il référence ?",a="The Eagle and Fist est une allégeance mentionnée dans la lettre. Elle exige de garder une distance mesurée dans le service et est liée à la protection de ce qu’il reste des Old Kingdoms.",al={"qu’est-ce que the eagle and fist","signification de eagle and fist","qui est eagle and fist"}},{q="Pourquoi le campement est-il abandonné ?",a="L’éclaireur est parti à la hâte, alors que le feu de camp venait d’être alimenté en bois frais. L’auteur décrit le point de vue comme un endroit idéal pour lancer un planeur parachute.",al={"où est allé l’éclaireur","pourquoi sont-ils partis","qui a alimenté le feu de camp"}},{q="Quelle barricade est défendue ?",a="L’auteur de la lettre dit que la barricade est usée, comme les Old Kingdoms de l’humanité, aujourd’hui déchus, qu’elle défendait autrefois. Pourtant, le guetteur jure de ne jamais l’abandonner.",al={"quelle barricade","quels old kingdoms","histoire de la barricade"}},{q="De quel type de poste d’observation s’agit-il ?",a="Le perchoir offre une vue incroyable, et les embruns humidifient l’air. Il pourrait s’agir d’une haute falaise ou d’un point de vue près d’une grande cascade ou d’une rivière tumultueuse.",al={"où se trouve cet endroit","pourquoi y a-t-il des embruns","emplacement d’eagle's fist"}}},fp="12,190,14.236.0,27.295.0,17.175.1,21.129.0,42.145.0,40.167.0,30.161.0,33.151.0,34.147.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="À This Must Be The Place, un campeur a disparu quelques instants avant que quiconque puisse le rattraper. Un mot déchiré indique que son auteur a poursuivi ses travaux dans la clandestinité pour éviter qu’ils ne tombent entre de mauvaises mains.",h="À This Must Be The Place, un campeur a disparu quelques instants avant que quiconque puisse le rattraper.",kw={"campement abandonné","sac et équipement","cachette","sac de couchage","this must be the place","mot déchiré","clandestinité"},sec={{t="Un départ précipité",b="Quelqu’un a levé le camp dans cet endroit isolé il y a quelques instants à peine. Un sac de couchage mal attaché se déroule sous les pieds, tandis qu’une lourde toile repose enroulée sur du matériel hétéroclite. Un petit morceau de papier contient un message d’adieu hâtif, mais quiconque campait ici a disparu avant que l’on puisse le rattraper."},{t="Dans la clandestinité",b="Le mot déchiré indique que son auteur a poursuivi ses travaux dans la clandestinité pour éviter qu’ils ne tombent entre de mauvaises mains. On ignore s’il s’agit de ses dernières paroles ou d’un indice menant au prochain refuge caché du chercheur. L’équipement est abandonné à la merci de quiconque a trouvé le campement."}},faq={{q="Qui a écrit le mot déchiré ?",a="Le mot ne nomme pas son auteur. Celui-ci dit seulement avoir poursuivi ses travaux dans la clandestinité pour les protéger de mauvaises mains, laissant derrière lui le campement et son équipement.",al={"qui a écrit le mot","auteur du mot","qui a laissé le message"}},{q="Quels travaux sont menés dans la clandestinité ?",a="Le mot ne révèle pas quels travaux son auteur poursuit dans la clandestinité. Celui-ci dit vouloir les protéger d’adversaires non précisés.",al={"quels travaux dans la clandestinité","pourquoi poursuivre des travaux dans la clandestinité","quels travaux"}},{q="Où est allé l’occupant du campement ?",a="L’occupant est parti quelques instants avant l’arrivée de quiconque, et sa destination est inconnue. Le mot laisse entendre qu’il est peut-être parti vers un autre refuge caché.",al={"l’ai-je manqué","où est-il allé","où se trouve l’auteur"}},{q="Qu’a-t-on laissé au campement ?",a="Le voyageur a laissé un sac de couchage mal attaché qui se déroule sur le sol, une lourde toile enroulée sur du matériel hétéroclite et un sac abandonné contenant diverses affaires.",al={"qu’est-ce qui a été laissé","provisions au campement","que contenait le sac"}},{q="Est-ce un indice menant à une autre cachette ?",a="Le mot pourrait être un adieu ou un indice menant au prochain refuge souterrain de son auteur. Il ne permet pas de trancher.",al={"y a-t-il une autre cachette","prochain campement","plus d’indices"}},{q="Qui sont les « mauvaises mains » mentionnées dans le mot ?",a="Le mot ne précise pas qui sont ces mauvaises mains. Son auteur craignait d’être poursuivi ou volé et est parti avant que ses travaux ne soient compromis.",al={"qui sont les mauvaises mains","sens de mauvaises mains","qui poursuit l’auteur"}}},fp="22,180,17.289.0,20.253.1,24.175.0,37.140.0,37.143.0,37.175.0,42.106.0,48.127.0"}
P.entries["quest:79980"] = {n="Scramble",s="Une note de charognard envoie les voyageurs chercher les provisions cachées de Scramble au bas d’une falaise abrupte. Cent pas plein nord, ils trouvent des vivres et un parchemin sale.",h="Une note de charognard envoie les voyageurs chercher les provisions cachées de Scramble au bas d’une falaise...",kw={"cache","flanc de falaise","sacoche de messager","parchemin","scramble","provisions"},sec={{t="La piste vers le nord",b="Une note indique la voie vers une cache de provisions dissimulée. Son auteur adresse quelques encouragements familiers, puis donne des indications précises : descendez cent pas plein nord le long de la falaise traîtresse. Des vivres vous y attendent pour vous permettre de poursuivre votre route."},{t="À la recherche de la sacoche de messager",b="En suivant les indications le long de la paroi abrupte, vous trouverez une sacoche de messager enfouie. Elle contient des provisions pratiques pour survivre et un autre parchemin sale. La note indique la suite d’une piste plus vaste."}},faq={{q="Quelle est la quête Scramble ?",a="Scramble envoie les voyageurs suivre une piste laissée par un charognard jusqu’à une cache dissimulée. Une note indique des provisions enfouies cent pas plein nord, au bas d’une falaise traîtresse.",al={"quête scramble","qu’est-ce que scramble","cache de scramble"}},{q="Où se trouve la cache dissimulée ?",a="La note situe la cache à environ cent pas plein nord, au bas d’une falaise abrupte. Il faut avancer prudemment pour descendre.",al={"où se trouve la cache","comment trouver la cache","emplacement de la cache"}},{q="Qui a laissé la note et la cache ?",a="La note ne nomme pas son auteur. Ses indications familières et pratiques aident un explorateur à trouver des provisions de secours, et la cache est toujours intacte.",al={"qui a écrit la note de scramble","qui a laissé la cache","auteur de scramble"}},{q="Que contient la cache enfouie ?",a="La sacoche de messager enfouie contient des provisions de survie et un parchemin sale glissé parmi elles.",al={"récompenses de scramble","que contient la cache de scramble","contenu de la sacoche"}},{q="Qu’est-ce que le parchemin sale trouvé avec les provisions ?",a="Le parchemin sale se trouve dans la sacoche de messager enfouie, parmi les provisions. Vous le découvrez en déterrant la sacoche.",al={"parchemin sale de scramble","que dit le parchemin","note de scramble"}},{q="Quels dangers présente le chemin vers la cache ?",a="La principale difficulté est la descente abrupte vers le nord. Un faux pas peut entraîner une fracture de la cheville ou une chute grave.",al={"dangers de scramble","falaise de scramble","flanc de la falaise de scramble"}}},fp="8,163,19.246.0,28.196.1,27.156.0,34.127.0,32.143.0,32.89.0,52.133.0,48.99.0"}
P.entries["quest:8"] = {n="Un marché de voleur",s="Au Glas, Calvin Montague vous demande de porter à Brill un message sans adresse. Il parle d'une simple livraison et promet une généreuse récompense.",h="Au Glas, Calvin Montague vous demande de porter à Brill un message sans adresse.",kw={"brill","calvin montague","le glas","taverne des pendus","renée l'aubergiste","lettre quelconque","voleur","clairières de tirisfal"},ang={["class:Rogue"]="En tant que voleur, vous découvrez les affaires qui se trament autour du Glas et de Brill grâce à la course privée de Calvin Montague.",["faction:Horde"]="En tant que membre de la Horde, vous vous rendez à Brill, centre régional de l'administration des Réprouvés et havre de repos dans les Clairières de Tirisfal.",["race:Undead"]="Fraîchement relevé en tant que Réprouvé, vous quittez pour la première fois le cimetière du Glas et prenez la route de Brill, le centre animé de la région."},sec={{t="Un coursier bienveillant",b="Calvin Montague se prélasse parmi les tombes et les chapelles en ruine du Glas. Il dit que les zombies du Fléau et les araignées rampantes l'ont épuisé, puis vous demande de porter une lettre sans adresse à Brill. Il promet une généreuse récompense. Pour un Réprouvé fraîchement éveillé, cela semble être un moyen simple de rejoindre la principale ville de la région."},{t="La Taverne des Pendus",b="La route vers l'est traverse les Clairières de Tirisfal et passe devant le Manoir du Foyer froid avant d'atteindre Brill. À la Taverne des Pendus, Renée l'aubergiste accueille chaleureusement les nouveaux venus et veille à leur confort. Mais à la réception de la lettre de Montague, son attitude change brusquement. Elle prétend qu'elle lui apporte des nouvelles d'une mère bien-aimée, puis vous réprimande pour votre indiscrétion et exige que vous achetiez quelque chose ou que vous partiez.\n\nÀ votre retour auprès de Calvin, il vous défie en duel au lieu de vous payer paisiblement ce qu'il avait promis."}},faq={{q="Qui est Calvin Montague ?",a="Calvin Montague est un voleur du Glas qui demande aux voyageurs fraîchement éveillés de porter une lettre à Renée l'aubergiste, à Brill. Il présente cela comme un simple service et promet une généreuse récompense.",al={"calvin montague","qui donne un marché de voleur","donneur de quête"}},{q="Que contient la Lettre quelconque ?",a="Le contenu exact de la lettre n'est pas consigné. Calvin vous confie un message sans adresse destiné à Renée l'aubergiste, à Brill.",al={"contenu de la lettre quelconque","que contient la lettre","lettre de calvin"}},{q="Pourquoi Renée l'aubergiste agit-elle si étrangement ?",a="Renée l'aubergiste tient la taverne de Brill et insiste sur le caractère privé de sa correspondance. Vous découvrez sa réaction en lui apportant la lettre de Montague.",al={"attitude de renée l'aubergiste","pourquoi renée fait semblant","excuse de renée au sujet de sa mère"}},{q="Calvin Montague paie-t-il vraiment la livraison ?",a="Calvin Montague promet une généreuse récompense pour la livraison. Lorsque la lettre lui parvient, Renée vous propose à manger ou à boire. Retournez ensuite voir Calvin pour poursuivre vos échanges avec lui au sujet de la récompense promise.",al={"calvin m'a-t-il arnaqué","où est mon argent","récompense de montague"}},{q="Où se trouve Brill ?",a="Brill se trouve au nord-est du Glas. Suivez la route principale vers l'est, en quittant la vallée de départ, puis prenez à droite après le Manoir du Foyer froid et traversez un pont couvert pour entrer dans la ville.",al={"comment aller à brill","route vers brill","itinéraire vers brill"}},{q="Que se passe-t-il après avoir remis la lettre à Renée ?",a="Après avoir remis la lettre à Renée, retournez voir Calvin Montague au Glas pour poursuivre vos échanges avec lui.",al={"quête suivante","suite d'un marché de voleur","que faire après renée"}}},fx={df83fdd9={q="Pourquoi Calvin Montague veut-il que la lettre soit livrée ?",a="Calvin Montague prétend qu'il a combattu plus que sa part de zombies et d'araignées écervelés autour du Glas et a simplement besoin de quelqu'un pour faire une course à sa place. Plutôt que de faire le trajet jusqu'à Brill lui-même, il vous propose de vous payer grassement pour livrer sa lettre scellée et quelconque directement à l'aubergiste Renée.",al={"motif de calvin montague","pourquoi envoyer la lettre à renée","pourquoi calvin veut cela"}}},fp="14,136,18.299.0,23.469.1,23.175.0,38.112.0,40.147.0,51.194.0,23.161.0,46.100.1"}
P.entries["quest:80"] = {n="La légende de Stalvan",s="À Sombre-Comté, la recherche de Stalvan Mantebrume mène une page maculée de sang aux Veilleurs. Le commandant Althea Bouclenoire vous envoie auprès du greffier Daltry pour comparer l’écriture aux registres de la ville.",h="À Sombre-Comté, la recherche de Stalvan Mantebrume mène une page maculée de sang aux Veilleurs.",kw={"althea bouclenoire","page de journal maculée de sang","greffier daltry","sombre-comté","bois de la pénombre","légende de stalvan","les veilleurs","stalvan mantebrume"},ang={["faction:Alliance"]="L’enquête de Sombre-Comté montre comment les villes frontalières préservent la loi, l’ordre et les registres civils alors que des morts-vivants et des bêtes des ombres les assiègent.",["race:Human"]="En tant qu’humain des royaumes du Sud, vous pouvez voir les tragédies qui relient la noblesse de Hurlevent, les colons du Bois de la Pénombre et les manoirs dispersés d’Elwynn."},sec={{t="Le filet se resserre",b="Les Veilleurs ont rassemblé des pages de journal dans tout le Bois de la Pénombre et les territoires humains voisins. Ensemble, elles semblent accabler Stalvan Mantebrume, le précepteur insaisissable. Le commandant Althea Bouclenoire le soupçonne depuis quelque temps, mais elle a besoin de preuves avant de rendre son jugement. La page maculée de sang, à elle seule, ne permet pas de savoir qui l’a écrite. Il faut comparer son écriture à celle de Stalvan."},{t="L’œil du greffier",b="Le greffier Daltry tient les registres de Sombre-Comté et a examiné d’innombrables registres et signatures au fil des ans. Vous lui apportez la page de journal récemment découverte afin qu’il la compare aux signatures de Stalvan dans le registre. Son verdict peut établir si la page est bien de la main de Stalvan et apporter aux Veilleurs la certitude dont ils ont besoin."}},faq={{q="Pourquoi le commandant Bouclenoire a-t-il besoin de la confirmation du greffier Daltry ?",a="Le commandant Althea Bouclenoire demande au greffier Daltry de vérifier si l’écriture de la page maculée de sang correspond à celle de Stalvan dans les registres de Sombre-Comté. Daltry tient le registre municipal et possède une longue expérience de l’examen des signatures. Son verdict peut établir la culpabilité de Stalvan avant que Bouclenoire n’agisse.",al={"pourquoi daltry","pourquoi vérifier l’écriture","rôle du greffier daltry"}},{q="À quel moment cette étape s’inscrit-elle dans l’histoire de la légende de Stalvan ?",a="C’est le onzième chapitre de l’enquête, après la récupération de la page de journal maculée de sang. La comparaison de Daltry est la dernière vérification des preuves avant que les Veilleurs n’agissent contre Stalvan.",al={"quelle est cette étape","où en est la suite de quêtes","ordre des quêtes de stalvan"}},{q="Où se trouve le greffier Daltry à Sombre-Comté ?",a="Le greffier Daltry se trouve dans l’hôtel de ville de Sombre-Comté, où il tient les registres locaux et les registres fonciers de la communauté.",al={"emplacement de daltry","où se trouve le greffier daltry","trouver daltry"}},{q="Quelles preuves l’enquêteur a-t-il apportées à Sombre-Comté ?",a="Vous apportez une page de journal maculée de sang, récupérée au cours des recherches sur Stalvan. Elle décrit ses sombres pensées et ses expériences, mais son écriture doit encore être comparée aux registres officiels.",al={"quelles sont les preuves","de quelle page s’agit-il","histoire de la page maculée de sang"}},{q="Le greffier Daltry confirme-t-il que l’écriture est celle de Stalvan ?",a="Oui. Daltry compare la page maculée de sang aux signatures du registre municipal et confirme que l’écriture correspond à celle de Stalvan. Bouclenoire a désormais la certitude qu’elle recherchait avant d’agir.",al={"l’écriture correspond-elle","est-ce stalvan","stalvan l’a-t-il écrite"}},{q="Pourquoi les Veilleurs font-ils preuve d’autant de prudence avant d’accuser Stalvan ?",a="Les Veilleurs veulent des preuves qu’ils peuvent vérifier avant d’accuser un ancien érudit de crimes horribles. Même dans la forêt troublée et isolée du Bois de la Pénombre, ils s’efforcent de faire respecter la loi et l’ordre plutôt que de se fier aux rumeurs ou aux conjectures.",al={"pourquoi faut-il des preuves","pourquoi ne pas simplement tuer stalvan","soupçons de bouclenoire"}}},fx={["5aad2c8f"]={q="Pourquoi le commandant Bouclenoire vous demande-t-elle d'apporter la page au greffier Daltry ?",a="Le commandant Bouclenoire est responsable de la défense du Bois de la Pénombre et de Sombre-Comté, surveillant le périmètre de la colonie pendant que vous vous occupiez du travail sur le terrain concernant Stalvan Mantebrume. Puisque vous avez apporté la page du journal maculée de sang directement à elle, le plus rapide est de vous faire marcher jusqu'au greffier Daltry à la mairie pour vérifier l'écriture pendant qu'elle reste de service.",al={"pourquoi moi ebonlocke","pourquoi ebonlocke ne parle pas à daltry","pourquoi m'envoyer à daltry"}}},fp="21,201,15.372.0,15.329.1,62.286.0,62.202.0,43.119.0,54.194.0,55.183.1,58.219.0"}
P.entries["quest:80001"] = {n="Rekindle",s="Un foyer éteint contient du bois sec prêt à s’enflammer. Vous mettez vos talents d’éclaireur à profit.",h="Un foyer éteint contient du bois sec prêt à s’enflammer.",kw={"bois sec","feu éteint","foyer","rekindle","talents d’éclaireur"},sec={{t="Auprès du foyer",b="Le bois est assez sec pour s’enflammer. Vous mettez vos talents d’éclaireur à profit près du foyer éteint."}},faq={{q="De quoi parle Rekindle ?",a="Un foyer éteint contient du bois sec prêt à s’enflammer, et vous mettez vos talents d’éclaireur à profit.",al={"quête rekindle","rallumer le feu rekindle","foyer"}},{q="Qu’est-ce qui ne va pas avec le foyer ?",a="Le foyer est éteint, bien que son bois soit assez sec pour s’enflammer.",al={"problème de foyer","pourquoi le feu est éteint","feu éteint"}},{q="Que dit le texte de validation ?",a="Le texte de validation dit que vous mettez vos talents d’éclaireur à profit.",al={"fin de rekindle","que se passe-t-il à la validation","talents d’éclaireur"}}},fp="8,96,15.107.0,23.98.0,32.75.0,29.54.0"}
P.entries["quest:804"] = {n="Sarkoth",s="Sur les hauts promontoires de la Vallée des épreuves, Hana'zua attend de l'aide, cloué sur place par le venin de Sarkoth. Vous avez tué le scorpide qui l'a blessé. Gornek doit maintenant être averti à l'Antre pour que les secours atteignent l'éclaireur.",h="Sur les hauts promontoires de la Vallée des épreuves, Hana'zua attend de l'aide, cloué sur place par le venin...",kw={"sombrelance","durotar","gornek","hana'zua","sarkoth","scorpide","l'antre","vallée des épreuves"},ang={["faction:Horde"]="En tant que membre de la Horde, vous apprenez que la survie dans une terre rude et impitoyable dépend de l'entraide. On vous enseigne à ne laisser aucun camarade derrière dès vos premiers pas comme initié.",["race:Orc"]="En tant qu'orc, vous savez que la force personnelle compte. Défendre l'honneur d'un allié hors de combat révèle le cœur d'un vrai guerrier.",["race:Troll"]="En tant que troll, vous pouvez renforcer le jeune lien entre la tribu Sombrelance et les orcs de Thrall en sauvant Hana'zua d'une lente agonie causée par le venin."},sec={{t="Le sort d'un éclaireur",b="L'éclaireur Sombrelance Hana'zua est bloqué sur les hauts promontoires de la Vallée des épreuves. Le venin de Sarkoth l'a trop affaibli pour qu'il puisse redescendre seul les sentiers dangereux. Vous l'avez vengé en tuant le scorpide, mais il ne peut toujours pas traverser seul les pierres arides. Un initié de passage doit donc porter la nouvelle jusqu'au campement d'entraînement."},{t="L'honneur à l'Antre",b="Gornek attend votre rapport à l'Antre. Lorsqu'il apprend le sort de Hana'zua, il reconnaît le danger que représente Sarkoth et organise des secours pour l'éclaireur. Les commandants de la Horde honorent ceux qui délaissent leur propre entraînement pour défendre et secourir un étranger à terre. Une telle conduite prouve la valeur d'un initié avant même qu'il ne s'aventure dans Durotar."}},faq={{q="Qui est Hana'zua et pourquoi est-il bloqué ?",a="Hana'zua est un jeune éclaireur troll Sombrelance, bloqué dans les hauteurs de la Vallée des épreuves. Sarkoth l'a surpris et empoisonné, le laissant trop faible pour redescendre seul.",al={"hana'zua","qui est hana'zua","pourquoi le troll est-il blessé"}},{q="Qui est Gornek ?",a="Gornek est un superviseur orc à l'Antre, dans la Vallée des épreuves. Il évalue les nouvelles recrues, leur confie des tâches de survie et organise les secours lorsque les initiés sont confrontés à des menaces mortelles dans le ravin.",al={"gornek","où se trouve gornek","chef de l'antre"}},{q="Qu'est-ce que Sarkoth ?",a="Au-dessus de la Vallée des épreuves, Sarkoth rôde sur les promontoires rocheux. Ce scorpide gigantesque est tristement célèbre. Son venin et sa férocité en font un danger légendaire pour les jeunes orcs et trolls qui passent les épreuves.",al={"monstre sarkoth","quel genre de monstre est sarkoth"}},{q="Hana'zua survit-il à ses blessures ?",a="Gornek promet d'envoyer des secours à Hana'zua dès qu'il aura entendu votre rapport. Le sort de l'éclaireur par la suite n'est pas précisé.",al={"le troll survit-il","hana'zua va-t-il bien","hana'zua sauvé"}},{q="Pourquoi Gornek loue-t-il tant cet acte ?",a="On attend des initiés qu'ils survivent aux épreuves. Délaisser ses propres tâches pour défendre l'honneur d'un étranger et l'aider à survivre reflète les valeurs que la New Horde cherche à inculquer à ses guerriers.",al={"pourquoi gornek s'en soucie-t-il","discours de gornek sur l'honneur"}},{q="Où se trouve l'Antre ?",a="L'Antre est une grotte centrale d'entraînement et un terrain de rassemblement, au cœur de la Vallée des épreuves, dans le sud-ouest de Durotar.",al={"où se trouve l'antre","emplacement de l'antre à durotar"}}},fx={["88c1d5d5"]={q="Pourquoi Hana'zua vous demande-t-il de faire rapport à Gornek ?",a="Bien que venger sa défaite contre Sarkoth ait renforcé la volonté de survie d'Hana'zua, ses blessures graves le laissent complètement immobilisé dans la vallée. Il ne peut pas faire le trajet jusqu'à l'Antre par ses propres moyens. En vous envoyant avec le message de sa situation difficile, il espère que Gornek enverra de l'aide avant qu'il ne succombe à ses blessures ou aux éléments.",al={"pourquoi envoyer à gornek","motif d'hana'zua","pourquoi dire à gornek"}},["66b1c5a1"]={q="Pourquoi Hana'zua ne peut-il pas retourner à l'Antre lui-même ?",a="Hana'zua a été battu et laissé pour mort par Sarkoth pendant son épreuve. Il n'a pas la force de se tenir debout, encore moins de ramper sur le sol brûlant du canyon pour revenir en sécurité sans assistance. Sans aucun autre guerrier à proximité pour l'aider, vous êtes sa seule bouée de sauvetage pour transmettre le message à Gornek avant qu'il ne soit trop tard.",al={"pourquoi hana'zua a besoin d'aide","pourquoi hana'zua ne peut pas marcher","pourquoi moi hana'zua"}}},fp="7,210,16.336.0,16.328.0,39.166.0,14.182.0,16.184.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="Faire un rapport au Village de Sen'jin",s="Zureetha Mireloin envoie de jeunes initiés de la Vallée des épreuves avertir les trolls sombrelances du Village de Sen'jin. Des cultistes de la Lame ardente ont sévi dans la vallée. Maître Gadrin leur apprend qu'une magie noire menace les Îles de l'Écho voisines.",h="Zureetha Mireloin envoie de jeunes initiés de la Vallée des épreuves avertir les trolls sombrelances du...",kw={"lame ardente","sombrelance","durotar","îles de l'écho","maître gadrin","village de sen'jin","vallée des épreuves","zureetha mireloin"},ang={["faction:Horde"]="En tant que membre de la Horde de Thrall, vous voyez ses races fondatrices s'échanger des avertissements pour protéger leurs jeunes colonies.",["race:Orc"]="En tant que jeune orc, vous quittez la Vallée des épreuves pour aider les Sombrelance. C'est une première épreuve d'honneur et de solidarité envers les alliés qui ont accompagné Thrall de l'autre côté de La Grande mer.",["race:Troll"]="En tant qu'aventurier sombrelance, vous retournez au Village de Sen'jin pour affronter le déracinement de votre peuple et sa lutte pour reconquérir les Îles de l'Écho."},sec={{t="Quitter L'Antre",b="Après avoir prouvé leur valeur au combat et récupéré des médaillons sombres auprès du Convent de la Lame ardente, les jeunes initiés quittent la Vallée des épreuves. Zureetha Mireloin comprend que les démons du Proving Grounds sacré ne sont pas une simple nuisance isolée. Ils annoncent un fléau qui se répand à travers Durotar. Elle envoie les combattants aguerris vers l'est, au-delà de l'embouchure du ravin, puis vers le sud en direction de la côte, pour avertir la tribu sombrelance."},{t="Ombres sur la côte",b="Au Village de Sen'jin, les voyageurs transmettent leur avertissement à Maître Gadrin, le vieux sorcier-docteur qui guide les Sombrelance en exil. Gadrin affirme que la Lame ardente n'a pas marché sur le sable du village. Pourtant, une magie noire a pris racine tout près, sur les Îles de l'Écho, et une trahison menace les trolls qui y vivent. La jeune Horde reste fragile, tandis que ses alliés se pressent de se défendre mutuellement, alors que les divisions tribales et la corruption gangrenée frappent leurs flancs."}},faq={{q="Pourquoi Zureetha Mireloin envoie-t-elle des gens hors de la Vallée des épreuves ?",a="L'activité démoniaque dans la Vallée des épreuves fait craindre à Zureetha Mireloin que la Lame ardente menace tout Durotar. Elle envoie des initiés aguerris hors de la vallée pour avertir les colonies alliées et découvrir jusqu'où s'étend l'influence du culte.",al={"pourquoi quitter la vallée","pourquoi aller à sen'jin","ordres de zureetha mireloin"}},{q="Qui est Maître Gadrin ?",a="Maître Gadrin est un vieux sorcier-docteur et le guide spirituel des trolls sombrelances du Village de Sen'jin. Il conseille le chef Vol'jin et veille aux affaires de la tribu tandis que des menaces se rapprochent de leur refuge côtier.",al={"histoire de maître gadrin","qui est gadrin"}},{q="La Lame ardente a-t-elle attaqué le Village de Sen'jin ?",a="Non, la Lame ardente n'a pas attaqué le Village de Sen'jin. Maître Gadrin avertit qu'une magie noire et une trahison ont pris racine tout près, sur les Îles de l'Écho, et mettent les trolls en danger.",al={"la lame ardente est-elle à sen'jin","culte à sen'jin"}},{q="Où se trouve le Village de Sen'jin ?",a="Le Village de Sen'jin se trouve à l'est, au-delà de la sortie principale du canyon de la Vallée des épreuves, puis au sud, à la bifurcation de la route qui longe la côte sud-est de Durotar.",al={"comment aller à sen'jin","direction du village de sen'jin"}},{q="Quelle menace Maître Gadrin évoque-t-il sur les Îles de l'Écho ?",a="Maître Gadrin craint que Zalazane, un autre sorcier-docteur troll, ait trahi les Sombrelance. Zalazane a utilisé des maléfices insidieux pour asservir ses frères et s'emparer des Îles de l'Écho, poussant les Sombrelance survivants à gagner les côtes du continent.",al={"problèmes aux îles de l'écho","que s'est-il passé aux îles de l'écho"}},{q="Que se passe-t-il après avoir fait rapport à Maître Gadrin ?",a="Après avoir entendu votre rapport et décrit la détresse des trolls, Gadrin vous demande de l'aider à combattre les dangers qui menacent la côte. Des ordres ultérieurs vous envoient ensuite au nord-ouest, auprès d'Orgnil Marque-l'âme, à Tranchecolline.",al={"quête après le rapport à sen'jin","que faire après gadrin"}}},fx={["54845e0f"]={q="Pourquoi Zureetha Mireloin vous envoie-t-elle auprès du maître Gadrin au lieu d'un garde ?",a="Vous avez personnellement affronté la Lame ardente à l'intérieur de leur convent dans la Vallée des épreuves et récupéré la preuve de leur présence. Ayant prouvé votre loyauté et votre force par vos épreuves, vous êtes le messager le plus qualifié pour fournir au maître Gadrin un récit témoin de l'infiltration du culte.",al={"pourquoi m'envoyer","pourquoi moi zureetha","pourquoi ne pas envoyer un messager à sen'jin"}}},fp="25,237,15.395.0,22.434.1,70.235.0,21.202.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="De sombres orages",s="À Durotar, les sectateurs de la Lame ardente corrompent la terre depuis les Falaises du Tonnerre. Orgnil Marque-l'âme, à Tranchecolline, a appris que Fizzle Darkstorm les dirige et vous demande de mettre fin à la menace.",h="À Durotar, les sectateurs de la Lame ardente corrompent la terre depuis les Falaises du Tonnerre.",kw={"lame ardente","de sombres orages","durotar","fizzle darkstorm","griffe de féplouf","orgnil marque-l'âme","tranchecolline","falaises du tonnerre"},ang={["class:Shaman"]="En tant que chaman, vous savez que les rites sombres de Fizzle et ses serviteurs troublent les esprits naturels des Falaises du Tonnerre et agitent les bêtes. L'équilibre élémentaire doit être rétabli.",["class:Warlock"]="En tant que démoniste, vous voyez combien le dévouement irréfléchi de Fizzle à la puissance gangrenée le rend dangereux et déshonore les adeptes disciplinés de la Horde.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger le cœur de Durotar contre la subversion démoniaque. La Horde pourra alors tourner ses défenses vers l'extérieur sans s'effondrer de l'intérieur.",["race:Orc"]="En tant qu'orc, vous savez que la Lame ardente incarne le passé sombre que votre peuple s'efforce de surmonter. Chasser les infiltrés comme Fizzle aide à protéger la nation libre de Thrall."},sec={{t="Une menace dans les falaises",b="Orgnil Marque-l'âme a appris que la magie noire s'est emparée des Falaises du Tonnerre, au nord-ouest de Tranchecolline. Les sectateurs de la Lame ardente rôdent dans le ravin tandis que de jeunes défenseurs de la Horde gardent les frontières de Durotar. Ils ravagent la faune et la terre."},{t="Fizzle Darkstorm, démoniste gobelin",b="Fizzle Darkstorm est un démoniste gobelin allié à la Lame ardente. Il dirige les sectateurs des Falaises du Tonnerre et manie la puissance gangrenée au service de la secte, sans servir le commerce ni les intérêts des cartels. Tuez-le et rapportez sa griffe déformée. Orgnil saura alors que les chefs du ravin ont été abattus."},{t="Éliminer la secte",b="La Lame ardente incarne l'asservissement aux démons, la corruption et la folie sanguinaire. La nouvelle Horde de Thrall cherche à laisser ce passé derrière elle. La mort de Fizzle élimine un conspirateur actif au cœur de Durotar. L'ombre qui plane sur la patrie des orcs s'étend au-delà de quelques campements isolés."}},faq={{q="Qui est Fizzle Darkstorm ?",a="Fizzle Darkstorm est un démoniste gobelin au service de la secte de la Lame ardente. Lui et ses fidèles se terrent dans les Falaises du Tonnerre et répandent le chaos démoniaque dans le ravin. Orgnil Marque-l'âme réclame son exécution.",al={"qui est fizzle","histoire de fizzle darkstorm","fizzle le gobelin"}},{q="Où se trouvent les Falaises du Tonnerre ?",a="Les Falaises du Tonnerre se trouvent dans le nord-ouest de Durotar, au nord de Tranchecolline et au sud-ouest d'Orgrimmar. Des bêtes imprégnées de foudre et des sectateurs de la Lame ardente occupent leur canyon escarpé.",al={"où se trouvent les falaises du tonnerre","emplacement des falaises du tonnerre","comment trouver les falaises du tonnerre"}},{q="Pourquoi la Lame ardente est-elle à Durotar ?",a="La Lame ardente cherche à saper la Horde de Thrall et à rétablir la domination démoniaque sur les orcs. Ses membres se cachent dans les ravins, les grottes et les canyons de Durotar, où ils répandent la corruption de l'intérieur.",al={"lame ardente à durotar","pourquoi des sectateurs sont à durotar","objectifs de la lame ardente"}},{q="Pourquoi Orgnil Marque-l'âme veut-il précisément la griffe de Fizzle ?",a="Orgnil veut la griffe de Fizzle comme preuve irréfutable de la mort du démoniste. Elle confirme que le chef des sectateurs des Falaises du Tonnerre ne peut plus diriger leurs opérations.",al={"pourquoi la griffe de fizzle","signification de la griffe de fizzle","preuve de la mort de fizzle"}},{q="Que se passe-t-il après la mort de Fizzle ?",a="Après la mort de Fizzle, vous allez annoncer la nouvelle à Orgnil Marque-l'âme. Il vous envoie auprès de Margoz, un chaman qui en sait plus sur la corruption de la Lame ardente, afin que vous puissiez poursuivre vos recherches sur d'autres conspirations.",al={"que faire après de sombres orages","suite de de sombres orages","quête suivante après de sombres orages"}},{q="Pourquoi un gobelin travaillerait-il pour la Lame ardente ?",a="Certains gobelins sont attirés par la magie de l'ombre pour sa puissance, son influence et ses arts obscurs. Fizzle a embrassé la sorcellerie gangrenée et mis sa ruse impitoyable au service des sectateurs.",al={"gobelin de la lame ardente","pourquoi fizzle est avec la secte","fizzle le démoniste"}}},fx={["18f009de"]={q="Pourquoi Orgnil Marque-l'âme veut-il que Fizzle Darkstorm soit éliminé ?",a="Orgnil craint que si la Lame ardente obtient ne serait-ce qu'un petit pied-à-terre à Durotar, leur corruption et leur influence démoniaque se répandront de manière incontrôlable. Fizzle Darkstorm et son convent se sont retranchés dans les Falaises du Tonnerre, semant activement le chaos juste aux portes de la jeune patrie orque. Les abattre immédiatement empêche une infiltration démoniaque à grande échelle de prendre racine.",al={"pourquoi tuer fizzle darkstorm","motif d'orgnil marque-l'âme","pourquoi la quête dark storms"}}},fp="11,179,21.246.0,16.291.0,20.284.1,24.204.0,31.169.0,36.193.0,57.166.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="Crâne de Minshina",s="Au Village de Sen'jin, Maître Gadrin entend les appels désespérés de son frère défunt, Minshina. Zalazane l'a tué sur les Îles de l'Écho et a lié son esprit à son crâne tranché. Vous pouvez le libérer de son tourment en reprenant le crâne sur le site rituel de Zalazane.",h="Au Village de Sen'jin, Maître Gadrin entend les appels désespérés de son frère défunt, Minshina.",kw={"cercle de pouvoir","sombrelance","îles de l'écho","gadrin","minshina","village de sen'jin","crâne","vaudou","zalazane"},ang={["class:Priest"]="En tant que prêtre, vous connaissez le caractère sacré d'une âme défunte et l'horreur de la nécromancie rituelle qui prive un frère tombé au combat du repos éternel.",["class:Shaman"]="En tant que chaman, vous vénérez les esprits des ancêtres. Briser le cercle de Zalazane libère une âme torturée et rétablit l'équilibre entre le monde des esprits et celui des vivants.",["faction:Horde"]="En tant que membre de la Horde, vous honorez son lien avec les Trolls sombrelances en aidant Maître Gadrin. Votre aide prouve que tous partagent le chagrin d'un allié.",["race:Troll"]="En tant que Troll sombrelance, vous honorez votre famille et votre tribu en récupérant le crâne de Minshina. Vous vous opposez à la corruption des traditions vaudou ancestrales par Zalazane."},sec={{t="Un appel venu des ombres",b="Maître Gadrin est l'un des piliers spirituels de la tribu des Trolls sombrelances au Village de Sen'jin. Pourtant, de sombres visions le tourmentent. Son frère Minshina est tombé lorsque Zalazane a trahi la tribu et s'est emparé des Îles de l'Écho. Minshina a péri dans le conflit, mais la mort ne lui a pas apporté la paix. La tradition troll et le mysticisme vaudou veulent qu'un esprit puisse rester lié après la mort du corps. À présent, la voix tourmentée de Minshina rejoint Gadrin dans ses rêves et le supplie de le sauver d'un sort pire que la mort."},{t="Le cercle de pouvoir de Zalazane",b="Zalazane ne se contente pas de tuer ses anciens frères. Il emprisonne leurs âmes pour alimenter sa sorcellerie noire. Il a lié l'esprit de Minshina à son propre crâne, désormais placé dans un cercle de pouvoir sur la plus grande des Îles de l'Écho. Des trolls ensorcelés gardent le cercle tandis que les bougies brûlent au fil des rites. Le crâne concentre le mojo corrompu de Zalazane. Tant qu'il reste là, Minshina est captif de la volonté du féticheur."},{t="La liberté dans la mort",b="Pour libérer Minshina, vous partez vers l'est depuis le Village de Sen'jin jusqu'aux Îles de l'Écho méridionales. Vous vous introduisez dans l'anneau rituel et arrachez le crâne à Zalazane. Quand vous rapportez les restes de Minshina à Maître Gadrin, les liens sombres se brisent. L'esprit reconnaissant de Minshina apparaît brièvement et s'incline avec révérence. Puis il rejoint le royaume des ancêtres."}},faq={{q="Qui était Minshina ?",a="Minshina était le frère de Maître Gadrin. Zalazane l'a assassiné pendant le soulèvement sur les Îles de l'Écho, puis a profané ses restes par la sorcellerie noire.",al={"identité de minshina","qui est minshina","frère de gadrin"}},{q="Pourquoi l'esprit de Minshina est-il prisonnier de son crâne ?",a="Zalazane se sert du vaudou noir et de la magie des démonistes pour asservir les esprits des Trolls sombrelances tués. Il a lié l'âme de Minshina à son crâne et l'a placé dans un cercle de pouvoir. Minshina n'a ainsi pas pu rejoindre l'au-delà, et Zalazane a pu exploiter son esprit.",al={"pourquoi emprisonner un crâne","zalazane emprisonne les âmes","âme de minshina"}},{q="Où se trouve le cercle de pouvoir ?",a="Le cercle de pouvoir se trouve au sommet d'une colline, sur la plus grande et la plus méridionale des Îles de l'Écho, au large de la côte sud-est de Durotar. Des bougies rituelles, des trolls ensorcelés qui dansent et des crânes exposés signalent le lieu.",al={"où se trouve le crâne","emplacement du cercle de pouvoir","lieu du crâne de minshina"}},{q="Que se passe-t-il quand le crâne est rapporté au Village de Sen'jin ?",a="Quand Maître Gadrin reçoit le crâne, les liens nécromantiques se brisent. La silhouette fantomatique de Minshina apparaît devant Gadrin et vous, s'incline en signe de gratitude, puis disparaît pour reposer en paix auprès des ancêtres.",al={"rendre la quête","qu'arrive-t-il à minshina","minshina apparaît-il"}},{q="Qui est Zalazane et pourquoi a-t-il fait cela ?",a="Zalazane était autrefois un féticheur sombrelance respecté. Rendu fou par sa soif de pouvoir, il s'est retourné contre sa tribu et a utilisé des maléfices pour contrôler l'esprit de ses frères et sœurs. Il a poussé les derniers réfugiés sombrelances sur le continent de Durotar.",al={"qui est zalazane","pourquoi zalazane est-il maléfique","histoire de zalazane"}},{q="Pourquoi Gadrin ne peut-il pas récupérer le crâne lui-même ?",a="Maître Gadrin ne peut pas laisser le Village de Sen'jin sans protection. Il maintient la communauté unie, guide les jeunes dirigeants sombrelances, conseille le chef Vol'jin et lutte contre les maléfices de Zalazane qui s'étendent le long de la côte.",al={"pourquoi gadrin ne part-il pas","devoirs de gadrin"}}},fx={["2001e9be"]={q="Pourquoi le maître Gadrin veut-il que cela soit fait ?",a="Le maître Gadrin est tourmenté par les cris de son frère, Minshina, qui l'appelle dans ses rêves. Minshina a été tué par le féticheur traître Zalazane sur les Îles de l'Écho, mais la mort n'a apporté aucune paix. Zalazane a lié l'âme de Minshina directement à son crâne tranché, l'enchaînant dans la magie noire. Gadrin ne peut supporter de laisser l'esprit de son frère condamné à l'esclavage éternel, et il a désespérément besoin de quelqu'un pour briser l'emprise du démoniste et accorder à Minshina le repos éternel.",al={"pourquoi gadrin a besoin du crâne de minshina","motif du maître gadrin","pourquoi libérer minshina"}},["5583848b"]={q="À quoi sert le Crâne de Minshina ?",a="Le Crâne de Minshina sert de réceptacle magique contenant l'essence piégée du frère assassiné du maître Gadrin. Zalazane l'a placé dans un cercle rituel de puissance sur la plus grande des Îles de l'Écho, utilisant une sorcellerie vile pour réduire en esclavage l'esprit de Minshina même après la mort. Retirer le crâne de l'autel sombre perturbe la magie de lien du démoniste, permettant à Gadrin de libérer enfin l'âme de son frère une fois que vous l'aurez ramené en toute sécurité au village de Sen'jin.",al={"qu'est-ce que le crâne de minshina","but du crâne de minshina","objet crâne de minshina"}}},fp="16,254,23.468.0,26.384.0,16.345.1,17.142.0,46.259.0,37.197.0,63.199.1,39.230.0,44.220.0"}
P.entries["quest:809"] = {n="Ak'Zeloth",s="Près d’Orgrimmar, Neeru Fireblade vous envoie dans les Tarides alors qu’une corruption démoniaque s’éveille. Son contact vous attend près de la frontière.",h="Près d’Orgrimmar, Neeru Fireblade vous envoie dans les Tarides alors qu’une corruption démoniaque s’éveille.",kw={"ak'zeloth","tarides","lame ardente","la faille de l'ombre","the demon seed","pic de brume-funeste","poste de garde extérieur","neeru fireblade"},ang={["class:Warlock"]="En tant que démoniste, vous remarquerez peut-être que même l’assistant de Neeru Fireblade remet en question l’ordre de détruire une relique démoniaque.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger les nouvelles routes commerciales et de voyage qui relient Durotar aux Tarides, en sécurisant le Poste de garde extérieur et en nettoyant le Pic de Brume-funeste.",["race:Orc"]="En tant qu’orc, vous connaissez le prix de l’emprise de la Légion ardente. Le culte de la Lame ardente et les reliques démoniaques à votre porte menacent la liberté durement acquise par votre peuple."},sec={{t="Une piste dans l’ombre",b="Neeru Fireblade affirme que la Lame ardente menace toujours la Horde par sa corruption démoniaque. Vous lui avez rapporté un collier orné de l’insigne de la Lame ardente, trouvé en Durotar. Il vous envoie maintenant dans les Tarides. Un culte se rassemble autour de The Demon Seed, un artefact au pouvoir infâme. Neeru veut que vous retrouviez son contact près de la frontière."},{t="Le contact de l’avant-poste",b="Ak'Zeloth vous attend près du Poste de garde extérieur, à la frontière entre Durotar et les Tarides. L’assistant de Neeru se demande tout haut si son maître veut vraiment détruire The Demon Seed. Il vous explique ensuite comment vous occuper de l’artefact au sommet du Pic de Brume-funeste."}},faq={{q="Qui donne cette quête ?",a="Neeru Fireblade, un démoniste de la Faille de l'Ombre à Orgrimmar, vous demande votre aide après que vous lui avez présenté un collier de la Lame ardente.",al={"départ de quête","où trouver ak'zeloth","quête de neeru fireblade"}},{q="Où se trouve Ak'Zeloth ?",a="Ak'Zeloth vous attend juste à l’extérieur du Poste de garde extérieur, près de la frontière est des Tarides, là où le pont mène depuis Durotar.",al={"emplacement d’ak'zeloth","où se trouve ak'zeloth","trouver ak'zeloth"}},{q="Qu’est-ce que The Demon Seed ?",a="The Demon Seed est un artefact de pouvoir démoniaque détenu par le culte de la Lame ardente au sommet du Pic de Brume-funeste, dans le nord des Tarides.",al={"histoire de the demon seed","qu’est-ce que la graine"}},{q="Pourquoi les ordres de Neeru semblent-ils étranges à Ak'Zeloth ?",a="Ak'Zeloth dit seulement que le souhait de Neeru de détruire The Demon Seed est étrange, puis accepte de vous expliquer comment vous en débarrasser.",al={"pourquoi ak'zeloth est surpris","réaction étrange d’ak'zeloth"}},{q="Quelle quête vient ensuite ?",a="Après avoir parlé à Ak'Zeloth, il vous envoie gravir le Pic de Brume-funeste et neutraliser la relique corruptrice.",al={"quête suivante après ak'zeloth","suite d’ak'zeloth"}},{q="Cette quête fait-elle partie de l’histoire de la Lame ardente ?",a="Oui. Les activités du culte de la Lame ardente en Durotar mènent aux activités plus vastes et organisées du culte dans les Tarides.",al={"suite de quêtes de la lame ardente","quête du culte à orgrimmar"}}},fx={["91b6b00f"]={q="Pourquoi Neeru Fireblade veut-il que la The Demon Seed soit détruite ?",a="Neeru Fireblade prétend que depuis la défaite de la Légion ardente, il s'est consacré à éradiquer la corruption démoniaque restante dans les terres orques. Lorsque vous lui avez apporté un collier de cultiste de la Lame ardente, il a déclaré que cela confirmait ses pires craintes. Selon Neeru, le culte tire sa force de la The Demon Seed au sommet du Pic de Brume-funeste, et briser cette relique démoniaque est vital pour stopper leur sombre influence sur la Horde.",al={"motif de neeru fireblade","pourquoi détruire la the demon seed","pourquoi neeru vous envoie"}}},fp="9,122,17.313.0,19.224.1,21.126.0,27.120.0,23.122.0,47.116.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="Besoin d'un remède",s="Sur les falaises du nord-ouest de Durotar, Rhinag est empoisonné et loin du remède dont il a besoin. Le troll Sombrelance a peu de temps avant que le venin ne le tue. Il envoie donc un messager de passage à Orgrimmar chercher le remède de Kor'ghan.",h="Sur les falaises du nord-ouest de Durotar, Rhinag est empoisonné et loin du remède dont il a besoin.",kw={"antidote","la faille de l'ombre","durotar","kor'ghan","besoin d'un remède","orgrimmar","rhinag","scorpid","queue-venimeuse"},ang={["faction:Horde"]="En tant que membre de la Horde, vous affrontez le terrain rocheux et impitoyable de Durotar, une épreuve pour les défenseurs qui viennent d’arriver dans le jeune royaume de Thrall.",["race:Troll"]="En tant que troll, vous comprenez la peur de Rhinag face aux moqueries des siens, au Village de Sen'jin. Chez les Sombrelance, négliger sa survie en pleine nature attire les railleries les plus dures."},sec={{t="La piqûre d’un scorpid",b="Rhinag combattait des scorpids queue-venimeuse près de la frontière de Durotar lorsque l’un d’eux l’a piqué. Leur venin peut tuer en moins d’une heure. Le poison l’empêche de rejoindre Orgrimmar à pied. Sa survie dépend donc d’un voyageur qui atteindra son camp isolé à temps."},{t="Les secrets de l’ombre",b="Rhinag vous envoie sous Orgrimmar, dans la Faille de l'Ombre, où Kor'ghan sait contrer les poisons des terres désolées de Durotar. Kor'ghan peut préparer un remède, mais il aide rarement ceux qui n’ont pas fait leurs preuves."}},faq={{q="Qui est Rhinag ?",a="Rhinag est un aventurier troll Sombrelance qui lutte pour survivre sur les falaises du nord-ouest de Durotar. Un scorpid queue-venimeuse l’a piqué, et il craint que les siens, au Village de Sen'jin, se moquent de lui s’il revient dans un état aussi pitoyable.",al={"histoire de rhinag","qui est rhinag","rhinag le troll"}},{q="Pourquoi Kor'ghan se trouve-t-il dans la Faille de l'Ombre ?",a="Kor'ghan vit dans la Faille de l'Ombre, sous Orgrimmar. Les démonistes, les voleurs et ceux qui pratiquent les arts obscurs y travaillent loin du regard des guerriers honorés de Thrall. Les connaissances de Kor'ghan sur les breuvages vénéneux et les épreuves éprouvantes conviennent bien à ces cavernes.",al={"où se trouve korgan","qui est kor'ghan","emplacement de kor'ghan"}},{q="Pourquoi Rhinag ne va-t-il pas simplement voir un chaman ou un soigneur au Village de Sen'jin ?",a="Rhinag dit que son orgueil l’empêche de demander de l’aide au Village de Sen'jin. Il craint que ses semblables se moquent de lui parce qu’il revient imprudent et empoisonné. Il cherche donc un remède discret auprès de Kor'ghan.",al={"pourquoi ne pas aller à sen'jin","pourquoi rhinag évite sen'jin"}},{q="Que se passe-t-il après que Rhinag a reçu l’antidote ?",a="Rhinag boit l’antidote et se rétablit, mais Kor'ghan exige davantage de lui. Le guérisseur s’attend à ce qu’il affronte des épreuves éprouvantes, notamment tuer des sangliers et récupérer des queues de scorpid, avant de retrouver les bonnes grâces de Kor'ghan.",al={"rhinag survit-il","suite de l’histoire de rhinag"}},{q="Où trouver Rhinag ?",a="Rhinag se trouve dans les escarpements accidentés du nord-ouest de Durotar, près des cols frontaliers qui mènent vers l’ouest, en direction des Tarides.",al={"emplacement de rhinag","où se trouve rhinag"}},{q="Pourquoi faut-il se dépêcher autant pour trouver ce remède ?",a="Sans traitement, le poison du scorpid queue-venimeuse peut s’attaquer aux organes vitaux de sa victime en moins d’une heure.",al={"pourquoi faut-il se dépêcher","délai du poison de rhinag"}}},fx={["0710a7b2"]={q="À quoi sert l'Antidote du queue-venin ?",a="L'antidote neutralise le poison mortel des scorpides queue-venin qui rôdent dans le nord-ouest de Durotar. Rhinag a été piqué profondément lors d'une escarmouche imprudente avec les bêtes, et la toxine circule rapidement dans son sang. Sans cette potion spécifique brassée par Kor'ghan à Orgrimmar, Rhinag a moins d'une heure avant que le venin ne lui ôte la vie.",al={"à quoi sert l'antidote","utilisation de l'antidote du queue-venin","pourquoi avoir besoin de l'antidote du queue-venin"}}},fp="15,218,17.239.0,22.216.0,14.215.0,39.260.0,67.197.0,48.222.1,26.121.0,47.113.0"}
P.entries["quest:813"] = {n="La recherche de l'antidote",s="Kor'ghan, à Orgrimmar, prépare un remède pour Rhinag, le chasseur empoisonné.",h="Kor'ghan, à Orgrimmar, prépare un remède pour Rhinag, le chasseur empoisonné.",kw={"antidote","durotar","kor'ghan","orgrimmar","poison","rhinag","scorpide","venimqueue"},ang={["class:Hunter"]="En tant que chasseur, vous entendez le sévère rappel de Kor'ghan : connaissez le venin des bêtes et emportez les bons remèdes, avec votre arc et vos talents de pisteur.",["faction:Horde"]="Membre de la Horde en Durotar, vous veillez sur les vôtres. Les rôdeurs et éclaireurs isolés aux frontières peuvent compter sur l'aide d'Orgrimmar.",["race:Orc"]="Orc récemment installé en Durotar, vous êtes mis à l'épreuve. Même un éclaireur chevronné peut succomber aux dangers naturels de la région par négligence."},sec={{t="Une course contre le venin",b="Rhinag, un troll Sombrelance, chassait dans Durotar quand des scorpides venimqueue l'ont attaqué. Leur venin agit vite et il a besoin d'aide sans tarder. Kor'ghan, chasseur expérimenté à Orgrimmar, doit préparer une potion avant que le poison ne le tue."},{t="Préparer le remède",b="Les scorpides venimqueue adultes aux portes d'Orgrimmar portent les poches dont Kor'ghan a besoin pour préparer un antidote. Il dit qu'il pourra reprocher plus tard à Rhinag d'être parti sans préparation, mais chaque instant compte. Rapportez les poches en ville pour que Kor'ghan prépare une potion au chasseur mourant."}},faq={{q="Qui est Rhinag ?",a="Rhinag est un chasseur troll Sombrelance de Durotar. Des venimqueues l'ont piqué alors qu'il suivait des bêtes. Sans antidote, il dépend de l'aide d'Orgrimmar avant que le poison ne l'accable.",al={"histoire de rhinag","qui est empoisonné","qui a besoin de l'antidote"}},{q="Qui est Kor'ghan ?",a="Kor'ghan est un chasseur troll Sombrelance expérimenté, dans la Faille de l'Ombre à Orgrimmar. Il connaît les bêtes de Durotar et sait préparer un contre-poison avec les poches de venin des venimqueues.",al={"kor'ghan","qui est korphan","korgan orgrimmar"}},{q="D'où viennent les poches de venin nécessaires ?",a="Les poches de venin proviennent des scorpides venimqueue qui vivent à l'extérieur d'Orgrimmar, sur le terrain rocheux et aride près de l'entrée de la ville.",al={"où trouver les venimqueues","emplacement des poches de venin","poches de scorpide venimqueue"}},{q="Pourquoi cette tâche est-elle limitée dans le temps ?",a="Rhinag dépérit sur le terrain. Les toxines des venimqueues agissent vite : Kor'ghan doit recevoir les ingrédients à temps pour préparer un remède avant que Rhinag ne meure empoisonné.",al={"pourquoi y a-t-il un compte à rebours","compte à rebours need for a cure","quête chronométrée"}},{q="Quelle leçon Kor'ghan souligne-t-il pendant cette chasse ?",a="Kor'ghan avertit les chasseurs qu'ils doivent étudier leur proie et ses dangers avant de l'affronter. S'aventurer dans la nature sans préparation ni antidotes peut coûter la vie à un guerrier.",al={"leçon de kor'ghan","leçon de chasse","conseils de kor'ghan"}},{q="Quel est le lien avec « Need for a Cure » ?",a="« Need for a Cure » déclenche l'urgence et lance le compte à rebours. La recherche de l'antidote est l'étape entre cette urgence et le remède achevé : vous rassemblez les ingrédients bruts nécessaires à Kor'ghan pour le préparer.",al={"lien avec need for a cure","quête prérequise","quel est le lien"}}},fx={["837950c2"]={q="Pourquoi Kor'ghan veut-il que cela soit fait ?",a="Kor'ghan reconnaît que Rhinag a commis une erreur stupide en chassant les scorpides les plus mortels de Durotar sans préparation, mais il refuse de laisser mourir l'un des Sombrelance à cause d'un manque de jugement. Pour Kor'ghan, préserver la vie de l'un des siens passe avant les réprimandes. Il veut préparer un antidote immédiatement afin que Rhinag survive à l'envenimement mortel.",al={"pourquoi aider rhinag","motivation de kor'ghan","pourquoi kor'ghan s'en soucie"}},["20540779"]={q="À quoi sert la Glande à venin de queue-venin ?",a="Kor'ghan a besoin de glandes à venin fraîches pour distiller un antidote pour Rhinag. En extrayant les composants toxiques directement des scorpides queue-venin de Durotar, il peut concocter un contre-agent assez puissant pour neutraliser le venin à action rapide qui circule dans le sang du chasseur empoisonné.",al={"utilisation de la glande de queue-venin","à quoi servent les glandes à venin de queue-venin","pourquoi rassembler des glandes à venin"}},d062d72d={q="Que sont les queue-venin près d'Orgrimmar ?",a="Les queue-venin sont des scorpides prédateurs indigènes des terres arides de Durotar, rôdant sur les falaises rocheuses en dehors d'Orgrimmar. Connus parmi les chasseurs orcs comme faisant partie des créatures les plus mortelles de la région, leurs piqûres toxiques peuvent tuer rapidement si elles ne sont pas traitées, ce qui en fait des bêtes dangereuses qui exigent prudence et respect.",al={"que sont les queue-venin","scorpide queue-venin","pourquoi tuer des queue-venin"}}},fp="20,262,24.232.0,17.282.0,14.180.0,16.164.0,43.114.0,47.160.0,53.181.0,46.202.0"}
P.entries["quest:815"] = {n="Des oeufs pour l'omelette",s="Le cuisinier Torka attend des œufs frais des Îles de l'Écho avant le prochain repas. Vous les rapportez sans les casser pour que la cuisine respecte son horaire.",h="Le cuisinier Torka attend des œufs frais des Îles de l'Écho avant le prochain repas.",kw={"break a few eggs","petit-déjeuner","cuisinier","cuisine","œufs","repas"},ang={["profession:Cooking"]="En tant que cuisinier, vous connaissez la pression qu'implique le fait de nourrir tout le monde. Rapporter des ingrédients fragiles sans les casser fait partie du travail dans toute cuisine."},sec={{t="Des repas sans fin",b="À Tranchecolline, en Durotar, le cuisinier Torka prépare des repas du matin au soir. Le petit-déjeuner laisse place au déjeuner, puis au dîner, avec peu de temps pour quitter les fourneaux et chercher des provisions. Torka vous envoie donc aux Îles de l'Écho chercher des œufs de Taillasher avant que le service suivant ne prenne du retard. Rapportez-les intacts, et la cuisine pourra continuer à servir à l'heure."},{t="La gratitude du cuisinier",b="Le cuisinier Torka a peu de temps pour les compliments quand les repas attendent d'être préparés. Il faut manipuler les œufs avec délicatesse, car une coquille fêlée gâche un ingrédient dont la cuisine a besoin. Quand vous rapportez les œufs intacts, Torka vous renvoie et retourne travailler au-dessus du feu."}},faq={{q="En quoi consiste la quête Break a Few Eggs ?",a="Le cuisinier Torka a besoin que vous rapportiez intacts des œufs de Taillasher des Îles de l'Écho pour que la cuisine respecte son horaire.",al={"quête break a few eggs","qu'est-ce que break a few eggs","quête des œufs"}},{q="Qui est le cuisinier de Break a Few Eggs ?",a="Le cuisinier Torka prépare des repas tout au long de la journée à Tranchecolline, en Durotar. Torka parle sans détour et est pressé. Il compte sur vous pour rapporter des œufs de Taillasher des Îles de l'Écho sans les casser avant le repas.",al={"qui donne break a few eggs","quête des œufs cuisinier","qui cuisine"}},{q="Pourquoi le cuisinier a-t-il besoin d'œufs ?",a="Le cuisinier Torka a besoin d'œufs pour préparer les repas de la journée, du petit-déjeuner au dîner. Des œufs frais permettent à la cuisine de respecter son horaire.",al={"pourquoi des œufs","à quoi servent les œufs","pourquoi faut-il des œufs"}},{q="Pourquoi le cuisinier dit-il de ne pas être maladroit ?",a="Les œufs peuvent se casser pendant le trajet du retour. Le cuisinier Torka a besoin que les coquilles et les jaunes restent intacts pour le prochain service.",al={"pourquoi faire attention aux œufs","ne pas casser les œufs","pourquoi ne pas être maladroit"}},{q="À quoi fait référence le titre Break a Few Eggs ?",a="Le titre évoque le proverbe selon lequel il faut casser des œufs pour faire une omelette. Il convient au transport d'ingrédients fragiles vers une cuisine débordée.",al={"sens de break a few eggs","sens de l'expression","pourquoi ce titre break a few eggs"}},{q="Pourquoi le cuisinier est-il si impatient ?",a="Le cuisinier Torka est occupé à préparer les repas, du petit-déjeuner au dîner. Il a encore beaucoup à cuisiner, peu de patience pour les bavardages et veut retourner aux fourneaux.",al={"attitude du cuisinier","pourquoi le cuisinier est-il impoli","cuisinier grincheux"}}},fp="16,147,13.350.0,18.256.0,35.121.0,36.209.0,28.139.0,46.105.0,46.139.0,29.163.0"}
P.entries["quest:816"] = {n="L'égaré",s="Misha Tor'kren attend des nouvelles de son fils Kron dans sa ferme de Durotar. Parti chasser les crocolisques vers l'ouest, le long du fleuve Furie-du-Sud, il lui fait craindre le pire.",h="Misha Tor'kren attend des nouvelles de son fils Kron dans sa ferme de Durotar.",kw={"amulette","crocolisque","gueule-d'effroi","kron","misha","tranchecolline","furie-du-sud","tor'kren"},ang={["class:Hunter"]="En tant que chasseur, vous savez qu'un pisteur doit évaluer la férocité de sa proie. Kron ne l'a pas fait, et les crocolisques l'ont tué.",["faction:Horde"]="En tant que membre de la Horde, vous savez que la vie est rude à Durotar. Les familles luttent contre une terre impitoyable et les prédateurs mortels qui rôdent à ses frontières.",["race:Orc"]="En tant qu'orc, vous savez que l'orgueil et la gloire martiale comptent beaucoup dans votre culture. Le sort de Kron montre le prix à payer quand on affronte des bêtes dangereuses sans respecter leur force."},sec={{t="L'effroi d'une mère",b="Misha Tor'kren vit dans une ferme au nord-ouest de Tranchecolline. Il y a quelques jours, son fils Kron est parti vers l'ouest chasser de féroces crocolisques le long du fleuve Furie-du-Sud, près de la frontière des Tarides. Misha l'avait prévenu du danger mortel que représentaient ces bêtes, mais son orgueil l'a poussé à prouver sa force. Personne ne l'a revu depuis."},{t="Une sinistre confirmation",b="Misha vous demande de chercher le moindre signe de Kron sur les rives du fleuve Furie-du-Sud, jusque dans le ventre des crocolisques. Les crocolisques gueule-d'effroi détiennent la réponse. Parmi leurs restes, vous trouvez l'amulette que Kron avait avalée. Quand vous la rapportez, Misha comprend que son fils n'a pas survécu. Ce souvenir lui apporte le réconfort nécessaire pour commencer son deuil."}},faq={{q="Qui est Misha Tor'kren ?",a="Misha Tor'kren est une mère orque qui vit dans une ferme au nord-ouest de Tranchecolline, à Durotar. Elle craint pour son fils Kron, porté disparu, et demande aux voyageurs de chercher le moindre signe de sa présence.",al={"misha torkren","qui donne l'égaré","mère de kron"}},{q="Qui était Kron ?",a="Kron était le fils obstiné de Misha Tor'kren. Il est parti chasser de dangereux crocolisques près du fleuve Furie-du-Sud pour prouver sa force, et il y est mort.",al={"qui est kron","qu'est-il arrivé à kron","fils de misha"}},{q="Où Kron a-t-il disparu ?",a="Kron est parti vers l'ouest, à travers Durotar, en direction de la frontière des Tarides, pour chasser sur les rives du fleuve Furie-du-Sud.",al={"où est kron","où chercher kron","lieu où se trouve kron"}},{q="Comment prouver à Misha ce qui est arrivé à Kron ?",a="Vous trouvez l'amulette que Kron avait avalée parmi les restes de crocolisques gueule-d'effroi dans le fleuve Furie-du-Sud. La rapporter à Misha confirme sa mort.",al={"amulette de kron","signe du sort de kron","ventre de crocolisque"}},{q="Quelle récompense Misha donne-t-elle ?",a="Misha vous donne un cadeau qu'elle avait préparé pour le retour triomphal de Kron après sa chasse. En apprenant sa mort, elle ne peut plus le regarder et l'offre au voyageur qui lui a apporté le réconfort nécessaire pour faire son deuil.",al={"récompense de l'égaré","cadeau de misha"}},{q="Pourquoi Kron est-il parti ?",a="Kron est parti par orgueil et pour prouver ses talents de chasseur. Quand Misha l'a mis en garde contre les dangereux crocolisques, il s'est mis en colère et est parti les chasser malgré tout.",al={"pourquoi kron est-il parti chasser","orgueil de kron"}}},fx={ad2ab742={q="Pourquoi Misha Tor'kren veut-elle que cela soit fait ?",a="Misha est tourmentée de ne pas savoir ce qu'il est advenu de son fils. Kron est parti en trombe il y a quelques jours après une dispute, déterminé à faire ses preuves contre des bêtes dangereuses. Bien qu'elle craigne le pire, elle ne peut commencer à faire son deuil ou à trouver la paix intérieure tant qu'elle n'a pas une preuve définitive de son sort.",al={"pourquoi misha a besoin d'aide","motivation de misha tor'kren","pourquoi chercher kron"}},a54100a0={q="À quoi sert l'Amulette de Kron ?",a="L'Amulette de Kron était une possession personnelle portée par le fils de Misha lorsqu'il est parti chasser. Récupérée dans l'estomac d'une bête de rivière, elle sert de preuve sinistre et indéniable à sa mère que Kron a été tué le long du fleuve Furie-du-Sud.",al={"lore de l'amulette de kron","qu'est-ce que l'amulette","but de l'amulette de kron"}},a107a32d={q="Que sont les crocolisques le long du fleuve Furie-du-Sud ?",a="Les crocolisques Gueule-d'effroi sont des reptiles agressifs et puissants originaires des voies navigables et des berges boueuses séparant Durotar des Tarides. Vicieux et opportunistes, ils dévoreront toute proie assez imprudente pour s'aventurer seule sur leurs terrains de chasse le long du fleuve.",al={"crocolisques du fleuve furie-du-sud","pourquoi tuer des crocolisques","crocolisques gueule-d'effroi"}}},fp="22,156,16.286.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="Proie nécessaire",s="Vel'rin Fang réclame des peaux de tigre des Îles de l'Écho pour approvisionner le Village de Sen'jin. Les effectifs des Sombrelance augmentent et leurs réserves s'amenuisent.",h="Vel'rin Fang réclame des peaux de tigre des Îles de l'Écho pour approvisionner le Village de Sen'jin.",kw={"sombrelance","tigre de durotar","îles de l'écho","chasse","travail du cuir","proie nécessaire","village de sen'jin","fourrure de tigre","vel'rin fang"},ang={["class:Hunter"]="En tant que chasseur, vous savez que la patience et la précision comptent. Vel'rin a jadis suivi sa proie en silence pendant toute une journée avant de déclencher son piège.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à approvisionner la jeune enclave Sombrelance et à défendre le flanc sud de la Horde le long de la Grande mer.",["race:Troll"]="En tant que troll Sombrelance, vous chassez dans les Îles de l'Écho et subvenez aux besoins de votre clan. Les îles vous rappellent avec amertume le foyer que Zalazane a pris à votre peuple."},sec={{t="Une question de survie",b="Sur la côte rude de Durotar, les Sombrelance du Village de Sen'jin font durer chaque ressource. Les peaux de tigre servent à fabriquer des tentes, des couvertures et des armures. Des réfugiés arrivent et les éclaireurs reviennent, ce qui épuise les réserves du village. Le travailleur du cuir Vel'rin Fang envoie donc des chasseurs rapporter d'autres peaux."},{t="Équilibre et chasse",b="Les Sombrelance ne chassent les tigres de Durotar que lorsque la tribu a besoin de provisions. Leurs chasseurs traversent les eaux jusqu'aux Îles de l'Écho et y suivent la piste des prédateurs. Pour les trolls, chaque chasse met aussi à l'épreuve la patience, la discipline et le savoir-faire dans la nature."}},faq={{q="Qui est Vel'rin Fang ?",a="Vel'rin Fang est un travailleur du cuir Sombrelance au Village de Sen'jin. Il envoie des chasseurs chercher les peaux dont la tribu a besoin pour fabriquer vêtements, abris et équipement.",al={"vel'rin fang","qui donne proie nécessaire"}},{q="Pourquoi le Village de Sen'jin a-t-il besoin de fourrures de tigre ?",a="Le Village de Sen'jin utilise les peaux de tigre pour fabriquer des tentes, des couvertures et des armures. Avec l'augmentation de la population, les réserves du village sont mises à rude épreuve.",al={"pourquoi des peaux de tigre","but de proie nécessaire","à quoi servent les fourrures"}},{q="Où trouve-t-on les tigres de Durotar ?",a="Les tigres de Durotar rôdent dans les Îles de l'Écho, au large de la côte sud-est de la région.",al={"où sont les tigres","lieu où vivent les tigres","tigres des îles de l'écho"}},{q="Pourquoi les trolls ne chassent-ils pas tous les tigres des environs ?",a="Les Sombrelance laissent les tigres tranquilles jusqu'à ce qu'ils aient besoin de provisions. Ils ne prennent que ce dont la tribu a besoin, laissant les prédateurs prospérer.",al={"pourquoi laisser prospérer les tigres","régulation des troupeaux"}},{q="La chasse au tigre a-t-elle une importance dans la culture Sombrelance ?",a="Oui. Les Sombrelance voient la chasse au tigre comme une épreuve de patience et de ruse. Vel'rin a jadis attendu près d'un jour dans les Îles de l'Écho avant de remporter sa première grande victoire à la chasse.",al={"tradition de la chasse au tigre","première chasse au tigre"}},{q="Pourquoi les chasseurs doivent-ils se rendre aux Îles de l'Écho si Zalazane les contrôle ?",a="Zalazane et ses serviteurs ensorcelés contrôlent une grande partie des Îles de l'Écho, mais les bêtes sauvages y abondent encore. Chasser et récupérer des provisions le long des côtes extérieures comporte toujours des risques que les Sombrelance doivent prendre.",al={"tigres des îles de l'écho","pourquoi aller aux îles de l'écho"}}},fx={b158745d={q="À quoi sert la Fourrure de tigre de Durotar ?",a="Les Sombrelance transforment les fourrures en biens essentiels pour abriter et soutenir leur colonie en pleine croissance. Vel'rin Fang utilise les peaux pour confectionner des armures de cuir robustes, des couvertures chaudes et des tentes résistantes aux intempéries, veillant à ce que les villageois du Village de Sen'jin restent protégés et ne gèlent pas au fil des saisons.",al={"utilisation de la fourrure de tigre de durotar","à quoi sert la fourrure de tigre","fourrure de tigre proies pratiques"}}},fp="14,137,20.267.0,20.236.0,20.144.0,41.131.0,35.79.0,48.138.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="Un esprit parfaitement éduqué",s="Au Village de Sen'jin, Maître Vornal met à l'épreuve ceux qui cherchent à apprendre auprès de lui, tandis que sa vue décline. Il les envoie sur la côte de Durotar chercher des yeux de makrura et du mucus de rampant, afin de mesurer leur patience et leur détermination.",h="Au Village de Sen'jin, Maître Vornal met à l'épreuve ceux qui cherchent à apprendre auprès de lui, tandis que...",kw={"alchimie","mucus de rampant","darkspear strand","durotar","œil de makrura intact","makrura","maître vornal","village de sen'jin"},ang={["faction:Horde"]="La côte de Durotar reste dangereuse pour la jeune Horde. Éliminer les makrura agressifs et les rampants des flots aide à sécuriser les rivages de pêche autour du Village de Sen'jin.",["race:Orc"]="Vornal doute ouvertement que les orcs possèdent la discipline discrète qu'exige l'alchimie. Cette tâche vous donne l'occasion de montrer que la solidarité de la Horde demande aussi une patience studieuse.",["race:Troll"]="En tant que Sombrelance qui rebâtit le Village de Sen'jin, vous pouvez aider à perpétuer les traditions mystiques et alchimiques de la tribu en faisant vos preuves auprès d'anciens praticiens comme Maître Vornal."},sec={{t="La vue déclinante d'un maître",b="Maître Vornal vit au Village de Sen'jin, où l'âge a affaibli sa vue. La magie primordiale lui venait autrefois facilement, mais il compte désormais sur l'alchimie pour aiguiser ses perceptions et pratiquer ses arts. Son corps faiblit, mais le troll obstiné refuse toujours de prendre un apprenti. Il affirme que ni les Sombrelances ni les orcs de Durotar n'ont produit quiconque digne de son enseignement."},{t="L'épreuve des novices",b="Vornal demande des matières premières provenant de la côte inhospitalière de Durotar : des yeux de makrura intacts et des fioles de mucus de rampant. Prélever des yeux sans les abîmer sur des makrura cuirassés et agressifs exige des frappes précises. Récolter assez de mucus permet de voir si un élève potentiel peut endurer une tâche fastidieuse. Pour Vornal, la chasse porte moins sur les réactifs que sur la découverte de ceux qui savent rester concentrés."},{t="Une épreuve de volonté",b="Pour Maître Vornal, le temps et la patience mesurent la force. Il s'attend à ce que les jeunes impétueux s'impatientent ou abandonnent la tâche. Rapporter des ingrédients intacts au Village de Sen'jin prouve que l'on sait survivre le long des récifs dangereux du chenal des Îles de l'Écho. Cela révèle aussi la discipline nécessaire pour maîtriser les arts subtils de l'alchimie."}},faq={{q="Qui est Maître Vornal ?",a="Maître Vornal est un vieux troll alchimiste et lanceur de sorts qui vit au Village de Sen'jin. L'âge a affaibli sa vue. Il utilise donc des solvants et des breuvages alchimiques pour pratiquer une magie qui lui venait autrefois facilement.",al={"maître vornal","qui est vornal","histoire de vornal"}},{q="Pourquoi Vornal a-t-il besoin d'yeux de makrura et de mucus de rampant ?",a="Vornal utilise des mélanges alchimiques pour soutenir sa magie et compenser sa vue défaillante. Il lui faut du mucus de rampant et des yeux de makrura intacts comme réactifs. Les récolter met à l'épreuve ceux qui cherchent à apprendre auprès de lui.",al={"pourquoi du mucus de rampant","pourquoi des yeux de makrura","que prépare vornal"}},{q="Pourquoi Vornal hésite-t-il tant à prendre un apprenti ?",a="Vornal exige un grand dévouement et de la patience, et tolère mal l'arrogance. Il pense qu'aucun troll ni orc n'a montré le dévouement qu'il demande, et juge la plupart des élèves potentiels orgueilleux et prompts au découragement.",al={"apprenti de vornal","pourquoi pas d'apprenti","vornal cherche-t-il un élève"}},{q="Où trouve-t-on ces créatures près du Village de Sen'jin ?",a="Les rampants et les makrura parcourent les hauts-fonds le long de Darkspear Strand et les voies d'eau entre le continent et les Îles de l'Écho voisines.",al={"où trouver des makrura","où trouver des rampants","bêtes de darkspear strand"}},{q="Pourquoi les yeux de makrura doivent-ils être intacts ?",a="Vornal a besoin d'organes sensoriels non endommagés pour préparer des breuvages qui aiguisent la perception. Un coup trop puissant peut écraser les yeux délicats d'un makrura. Le chasseur doit donc agir avec précision et retenue.",al={"œil intact","yeux de makrura intacts","pourquoi des yeux intacts"}},{q="Quelle leçon Vornal cherche-t-il à enseigner ?",a="Vornal estime que la patience met le caractère à l'épreuve. Récolter des ingrédients à répétition dans la saleté du rivage révèle si un novice cède à la précipitation ou garde le calme et la concentration d'un alchimiste.",al={"leçon de vornal","sens de la quête","épreuve de patience"}}},fx={["4926ebef"]={q="Pourquoi Maître Vornal a-t-il besoin d'un aventurier plutôt que de récolter lui-même les ingrédients ?",a="Maître Vornal admet que sa vue décline avec l'âge, ce qui rend le travail de terrain dangereux le long de la côte déconseillé. Plus important encore, il utilise cette tâche comme un test délibéré. Vornal a longtemps refusé de prendre un apprenti, croyant qu'aucun troll ou orc digne de ce nom n'avait croisé son chemin. En vous envoyant récolter des ingrédients délicats sur la faune côtière hostile, il mesure votre patience, votre force et votre volonté pour voir si vos actes sont à la hauteur de votre assurance.",al={"pourquoi moi vornal","pourquoi vornal a besoin de moi","pourquoi envoyer un aventurier"}},cab96330={q="Que sont les makruras et les rampants des vagues qui menacent la côte de Durotar ?",a="Les makruras sont des humanoïdes crustacés agressifs indigènes aux eaux et aux côtes de Durotar, tandis que les rampants des vagues sont des crabes sauvages et territoriaux qui courent le long des plages et des hauts-fonds près des Îles de l'Écho. Tous deux habitent les eaux au large de Darkspear Strand, rendant la côte périlleuse pour les pêcheurs locaux et la collecte. Pour Maître Vornal, cependant, ils sont des sources précieuses d'ingrédients alchimiques spécialisés nécessaires pour compenser ses sens défaillants.",al={"que sont les makruras","makrura durotar","rampants des vagues sen'jin"}}},fp="16,194,23.343.0,20.348.0,17.315.0,21.196.0,52.200.0,50.212.0,55.127.0,42.180.0,38.161.0"}
P.entries["quest:819"] = {n="Tonneau vide de Chen",s="Dans les Tarides, le tonneau marqué de Chen Stormstout gît à l’abandon. Sa découverte rappelle les anciens liens du brasseur avec Durotar.",h="Dans les Tarides, le tonneau marqué de Chen Stormstout gît à l’abandon.",kw={"tarides","brassage","brasseur drohn","chen stormstout","tonneau vide","pandaren","cabestan","rexxar"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez vous souvenir de Chen Stormstout comme d’un allié honoré, qui a combattu aux côtés de Rexxar et de Rokhan pour fonder Durotar et protéger la Horde à ses débuts.",["profession:Cooking"]="En tant que cuisinier, vous pouvez voir dans le tonneau de Chen l’héritage d’un brasseur artisan. Son palais et sa quête d’ingrédients rares ont inspiré les artisans de tout Kalimdor."},sec={{t="Une relique errante",b="Dans les Tarides arides, les voyageurs trouvent parfois un tonneau en bois abandonné. Les quilboars Razormane et les centaures Kolkar laissent des fûts ordinaires derrière eux, mais celui-ci est soigneusement fabriqué et porte une plaque : « Chen Stormstout - Puisse votre esprit s’élever et toujours vous remonter le moral. » C’est une étrange relique sous le soleil de Kalimdor. Pour découvrir comment elle est arrivée là, vous cherchez quelqu’un qui s’y connaît en brassage."},{t="Échos de la fondation de Durotar",b="À Cabestan, le Brasseur Drohn reconnaît le travail du tonneau et nomme Chen Stormstout comme son propriétaire. Chen est un Pandaren errant qui a voyagé avec Rexxar lors des batailles qui ont assuré Durotar à la Horde de Thrall. Des années ont passé depuis que Chen a foulé la terre rouge de Kalimdor. Pourtant, les brasseurs chevronnés se souviennent encore de ses recettes et de son esprit vagabond."}},faq={{q="Qu’est-ce que le Tonneau vide de Chen ?",a="C’est un tonneau de brassage abandonné, trouvé dans les Tarides. Son inscription rend hommage au brasseur pandaren errant Chen Stormstout.",al={"tonneau vide","tonneau de chen","qu’est-ce que ce tonneau"}},{q="Qui est Chen Stormstout ?",a="Chen Stormstout est un brasseur pandaren errant qui a parcouru Kalimdor. Il est surtout connu pour avoir aidé Rexxar, un maître des bêtes demi-ogre, à défendre et à fonder Durotar.",al={"qui est chen","histoire de chen","brasseur pandaren"}},{q="À qui dois-je apporter le tonneau ?",a="Apportez le tonneau au Brasseur Drohn, un brasseur orc installé le long de la route près de Cabestan. Il reconnaît la marque de Chen et sait comment recréer ses recettes.",al={"où rendre le tonneau","qui veut le tonneau de chen","rendre le tonneau"}},{q="Pourquoi le tonneau de Chen se trouve-t-il dans les Tarides ?",a="Chen a parcouru Kalimdor il y a des années à la recherche d’ingrédients de brassage exotiques. Il voyageait tout en aidant la jeune Horde à défendre sa patrie contre les forces de l’amiral Proudmoore.",al={"pourquoi le tonneau est dans les tarides","comment le tonneau est arrivé ici"}},{q="Chen Stormstout apparaît-il en personne ?",a="Non. Chen a quitté la région et n’a pas été vu à Kalimdor depuis longtemps. Ses vieux tonneaux, ses recettes et les bons souvenirs de ses alliés, comme Drohn et Rexxar, demeurent.",al={"peut-on trouver chen","où se trouve chen stormstout","chen est-il dans classic"}},{q="Que fait le Brasseur Drohn du tonneau ?",a="Drohn accueille la relique et met au défi les voyageurs aventureux de rassembler des ingrédients tirés des bêtes locales. Il compte s’en servir pour recréer les puissantes et légendaires bières de Chen.",al={"suite de quêtes de drohn","que devient le tonneau ensuite"}}},fp="16,124,17.383.0,28.343.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:81924"] = {n="Wisdom of the Guardians",s="Parmi les ruines brisées de Féralas, Tyrisius cherche à retrouver les enseignements kaldorei anciens avant qu'ils ne disparaissent. Malgré les pierres en ruine, l'essence spirituelle de cette sagesse perdue perdure dans des sanctuaires lointains.",h="Parmi les ruines brisées de Féralas, Tyrisius cherche à retrouver les enseignements kaldorei anciens avant...",kw={"azshara","féralas","esprits gardiens","hinterlands","kaldorei","sanctuaires","tyrisius","sagesse des gardiens"},ang={["race:NightElf"]="Le savoir ancien des Kaldorei ne survit pas dans la pierre, mais dans les esprits immortels des sanctuaires sauvages."},sec={{t="Échos d'une sagesse ancienne",b="Tyrisius avertit que les traces matérielles du savoir kaldorei ont disparu des pierres de Féralas. Tandis que la pierre s'effrite, l'héritage spirituel des anciens elfes de la nuit perdure dans des lieux sacrés plus anciens, à travers Kalimdor et les Royaumes de l'est.\n\nPour retrouver ce que l'on croyait oublié, vous devez vous rendre dans les sanctuaires sacrés disséminés à Féralas, à Azshara et dans les Hinterlands. Tyrisius vous demande de vous tenir devant les esprits gardiens qui veillent sur ces lieux, de prouver votre valeur et de recevoir les enseignements anciens avant qu'ils ne s'effacent à jamais."}},faq={{q="Qui est Tyrisius ?",a="Tyrisius veille sur d'anciennes ruines kaldorei à Féralas et guide ceux qui cherchent les connaissances anciennes qui subsistent.",al={"qui est tyrisius","où se trouve tyrisius"}},{q="Où trouver les esprits gardiens ?",a="Les esprits gardiens veillent sur des sanctuaires à Féralas, à Azshara et dans les Hinterlands.",al={"où sont les esprits","emplacement des esprits gardiens","quelles zones visiter"}},{q="Pourquoi faut-il chercher les esprits gardiens ?",a="Tyrisius cherche à préserver la sagesse kaldorei ancienne dans la mémoire des vivants, avant qu'elle ne disparaisse à jamais du monde.",al={"pourquoi visiter les sanctuaires","quel est l'objectif"}},{q="Comment trouver les esprits gardiens ?",a="Chaque esprit gardien repose dans son propre sanctuaire, au cœur des terres anciennes.",al={"comment reconnaître les esprits","trouver les sanctuaires"}},{q="Sur quelles ruines Tyrisius veille-t-il ?",a="Tyrisius se tient parmi les ruines kaldorei effondrées, où les traces matérielles du savoir elfique ancien se sont désagrégées.",al={"quelles sont ces ruines","ruines de féralas"}},{q="Où retourner après avoir parlé aux esprits ?",a="Après avoir prouvé votre valeur à chaque esprit, Tyrisius vous attend à Féralas.",al={"où aller après les sanctuaires","à qui retourner"}}},fp="23,221,24.533.0,16.110.0,40.81.0,40.112.0,37.70.0,36.117.0,52.85.0"}
P.entries["quest:8193"] = {n="Master Angler",s="Chaque dimanche, un concours de pêche cherche les meilleurs pêcheurs. Rapportez des Tastyfish des bancs côtiers de la Vallée de Strangleronce parmi les cinquante premiers pour être déclaré Master Angler.",h="Chaque dimanche, un concours de pêche cherche les meilleurs pêcheurs.",kw={"concours de pêche","pêche","bancs de poissons","master angler","vallée de strangleronce","dimanche","tastyfish"},sec={{t="Le concours du dimanche",b="Le concours est ouvert chaque dimanche, et vous pouvez obtenir le titre de Master Angler en rapportant des Tastyfish à l’organisateur parmi les cinquante premiers participants. Ces poissons proviennent des bancs qui longent les côtes de la Vallée de Strangleronce et se gâtent rapidement."},{t="Une seconde offre",b="Si vous arrivez trop tard pour les cinquante premières places, l’apprenti de l’organisateur vous achètera tout de même vos Tastyfish. Ces poissons ne se conservent pas jusqu’au dimanche suivant."}},faq={{q="Quand a lieu le concours de pêche ?",a="Le concours a lieu chaque dimanche.",al={"jour du master angler","quel jour a lieu le concours de pêche"}},{q="Où trouver des Tastyfish ?",a="Les bancs de Tastyfish se trouvent le long des côtes de la Vallée de Strangleronce.",al={"emplacement des tastyfish","où pêcher des tastyfish"}},{q="Comment devenir Master Angler ?",a="Rapportez des Tastyfish à l’organisateur du concours parmi les cinquante premiers participants.",al={"conditions pour devenir master angler","gagner le concours de pêche"}},{q="Que se passe-t-il si j’arrive trop tard ?",a="L’apprenti de l’organisateur vous achètera vos Tastyfish si vous arrivez trop tard pour figurer parmi les cinquante premiers.",al={"concours manqué","pêche trop lente"}},{q="Puis-je conserver des Tastyfish pour la semaine prochaine ?",a="Non. Les Tastyfish se gâtent rapidement et ne peuvent donc pas être conservés jusqu’au dimanche suivant.",al={"les tastyfish se gâtent-ils","conserver les poissons jusqu’à dimanche"}}},fp="13,169,18.231.0,14.157.0,28.37.0,26.62.0,32.70.0,26.104.0,35.73.0"}
P.entries["quest:81947"] = {n="Sanguine Sorcery",s="Un bibliothécaire cherche des ouvrages magiques pour la bibliothèque. Votre contribution enrichit sa collection et son savoir.",h="Un bibliothécaire cherche des ouvrages magiques pour la bibliothèque.",kw={"collection","savoir","library","ouvrages magiques","sanguine sorcery"},sec={{t="Une collection grandissante",b="Le bibliothécaire vous a demandé d’apporter quelque chose de nouveau pour les rayons. Votre contribution aide à étendre le savoir de la bibliothèque."}},faq={{q="Que veut le bibliothécaire ?",a="Le bibliothécaire vous demande d’apporter quelque chose pour enrichir la collection.",al={"que veulent-ils","demande de la bibliothèque","sanguine sorcery"}},{q="D’où vient cette demande ?",a="Cette quête vient du bibliothécaire Garion Wendell à Hurlevent, ou d’Owen Thadd à Fossoyeuse si vous êtes de la Horde.",al={"où se trouve le bibliothécaire","bibliothèque de forgefer","emplacement de la bibliothèque"}},{q="Pourquoi apporter des ouvrages magiques à la bibliothèque ?",a="Le bibliothécaire dit que les ouvrages magiques pourraient enrichir la bibliothèque et étendre son savoir.",al={"pourquoi des livres magiques","à quoi cela sert","collection de la bibliothèque"}}},fp="16,104,20.123.0,29.67.0,27.106.0,39.82.0"}
P.entries["quest:81949"] = {n="Legends of the Tidesages",s="Un tome de savoir ésotérique est parvenu à la Library de Forgefer. Les érudits accueillent avec plaisir ces ajouts, impatients d'enrichir leur collection de savoirs arcaniques.",h="Un tome de savoir ésotérique est parvenu à la Library de Forgefer.",kw={"collection","forgefer","legends of the tidesages","library","ouvrages magiques","tidesages","tome"},sec={{t="Réunir des connaissances",b="Les érudits de Forgefer cherchent à approfondir leur connaissance des savoirs arcaniques et historiques. Chaque volume rapporté du vaste monde préserve un savoir qui, autrement, pourrait sombrer dans l'oubli."}},faq={{q="Que sont les Legends of the Tidesages ?",a="C'est un tome magique apporté pour enrichir les archives de la Library de Forgefer.",al={"que sont les legends of the tidesages","quel est ce livre","livre des tidesages"}},{q="Qui veut le livre ?",a="Les érudits de la Library de Forgefer acceptent l'ouvrage afin d'en préserver les connaissances et d'enrichir leur collection.",al={"qui veut les legends of the tidesages","où apporter les legends of the tidesages","qui prend le livre"}},{q="Peut-on apporter d'autres livres à la bibliothèque ?",a="Les érudits vous demandent de leur apporter tout autre écrit magique que vous découvrirez et qui pourrait enrichir la bibliothèque.",al={"que se passe-t-il après les legends of the tidesages","autres livres bibliothèque","puis-je apporter d'autres livres"}}},fp="24,161,19.190.0,33.82.0,19.107.0,41.105.0"}
P.entries["quest:81952"] = {n="Everyday Etiquette",s="Un gardien de bibliothèque recherche des ouvrages magiques à ajouter à la collection. Votre contribution aide à enrichir le savoir de la bibliothèque.",h="Un gardien de bibliothèque recherche des ouvrages magiques à ajouter à la collection.",kw={"collection","étiquette au quotidien","savoir","library","ouvrages magiques"},sec={{t="Une collection qui s’enrichit",b="Tout ouvrage magique que vous trouverez pourrait rejoindre les rayons de la bibliothèque. Vos efforts contribuent à enrichir le savoir de la bibliothèque."}},faq={{q="Que souhaite le gardien de la bibliothèque ?",a="Le gardien recherche des ouvrages magiques susceptibles d’enrichir la bibliothèque.",al={"livres de bibliothèque","ouvrages magiques","quoi apporter"}},{q="Où cela se passe-t-il ?",a="Il vient d’un bibliothécaire : Garion Wendell à Hurlevent pour l’Alliance, ou Owen Thadd à Fossoyeuse pour la Horde.",al={"emplacement de la bibliothèque","où se trouve la bibliothèque","bibliothèque de forgefer"}},{q="Pourquoi rassemble-t-on des ouvrages magiques ?",a="Le gardien affirme que chaque contribution enrichit le savoir de la bibliothèque.",al={"pourquoi rassembler des livres","but de la collection de la bibliothèque","à quoi ça sert"}}},fp="18,120,20.120.0,34.62.0,27.123.0,38.68.0"}
P.entries["quest:82"] = {n="Enquête au Repaire nuisible",s="Au Repaire nuisible, les insectes Centipaar assèchent les bassins qui s'y trouvaient autrefois. Le Grand Géomètre Radiésthéflop veut savoir qui est l'ennemi. Vous apportez donc cinq morceaux d'insectes à l'Alchimiste Pestlezugg, à Gadgetzan, pour qu'il les examine.",h="Au Repaire nuisible, les insectes Centipaar assèchent les bassins qui s'y trouvaient autrefois.",kw={"centipaar","radiésthéflop","gadgetzan","insectes","le repaire nuisible","pestlezugg","tanaris"},sec={{t="Des morceaux du repaire",b="Après Gadgetzan Water Survey, le Grand Géomètre Radiésthéflop se tourne vers les rapports sur les insectes. Ils assèchent les bassins qui se trouvaient autrefois à l'emplacement actuel du Repaire nuisible. Il en sait peu sur eux et veut savoir qui est l'ennemi. Vous ramassez donc cinq morceaux sur les Centipaar du Repaire nuisible. Puis vous les apportez à l'Alchimiste Pestlezugg, à Gadgetzan, pour qu'il les examine."},{t="Les découvertes de Pestlezugg",b="L'Alchimiste Pestlezugg examine aussitôt les morceaux. Ils ne correspondent à aucune forme d'insecte qu'il ait déjà vue. Ces insectes semblent presque contrôlés par une force extérieure. Pestlezugg vous renvoie auprès du Grand Géomètre Radiésthéflop, qui a un besoin urgent d'aide, peut-être pour s'occuper d'autres insectes en Tanaris."}},faq={{q="Pourquoi le Grand Géomètre Radiésthéflop veut-il des morceaux d'insectes ?",a="Les insectes assèchent les bassins qui se trouvaient autrefois à l'emplacement du Repaire nuisible, et l'on sait peu de choses d'autre à leur sujet. Les morceaux des Centipaar pourraient aider l'Alchimiste Pestlezugg à découvrir ce qu'ils sont.",al={"pourquoi ramasser des morceaux d'insectes","radiésthéflop morceaux d'insectes","but du repaire nuisible"}},{q="Où trouve-t-on les Centipaar ?",a="Les Centipaar se trouvent au Repaire nuisible, où se trouvaient autrefois des bassins d'eau.",al={"où se trouve le repaire nuisible","emplacement des centipaar","où trouver les centipaar"}},{q="À qui remettre les morceaux d'insectes à Gadgetzan ?",a="L'Alchimiste Pestlezugg, à Gadgetzan, reçoit les morceaux d'insectes pour les examiner.",al={"à qui remettre les objets","emplacement de pestlezugg","qui veut les morceaux d'insectes"}},{q="Quelle étape précède celle-ci ?",a="Elle fait suite à Gadgetzan Water Survey.",al={"quête précédente","quête requise","ce qui mène à cette quête"}}},fp="26,219,19.364.0,21.280.1,56.176.0,30.72.0,43.76.0,28.38.0"}
P.entries["quest:821"] = {n="Tonneau vide de Chen",s="À Cabestan, le Brasseur Drohn espère recréer le puissant breuvage de Chen Stormstout avec des ingrédients sauvages des Tarides.",h="À Cabestan, le Brasseur Drohn espère recréer le puissant breuvage de Chen Stormstout avec des ingrédients...",kw={"brasseur drohn","chen stormstout","tonneau","rognon de trotteur des plaines","cabestan","canine de lion des savanes","les tarides","corne de lézard-tonnerre","bière de trogg"},ang={["faction:Horde"]="Chen Stormstout combattit aux côtés de Rexxar pour aider à établir Durotar. Les vestiges de son voyage ont une importance culturelle particulière pour la Horde.",["profession:Cooking"]="Pour un cuisinier, cette quête réunit le dépeçage des régions sauvages et l'art du brassage dans la création de spiritueux légendaires de Kalimdor.",["race:Orc"]="En tant qu'orc, vous pouvez voir en Drohn un exemple d'orcs qui adoptent les anciennes traditions de brassage transmises par les voyageurs ayant marché aux côtés de la Horde naissante."},sec={{t="Un héritage en tonneau",b="Un tonneau marqué rappelle Chen Stormstout au Brasseur Drohn, à Cabestan. Chen confia les secrets de son breuvage éponyme au mentor de Drohn, qui les transmit à Drohn. La recette exige des ingrédients bruts et puissants issus de la faune féroce des Tarides. Pour qui ne brasse pas, ce choix est inhabituel."},{t="La récolte dans la savane",b="Pour faire renaître le puissant breuvage de Chen, vous rassemblez des rognons de trotteur des plaines, des défenses de lion des savanes et une Corne de lézard-tonnerre. Les ingrédients doivent provenir de bêtes robustes, ce qui vous mène à travers les plaines poussiéreuses.\n\nQuand vous les apportez à Drohn, il se remémore avec tendresse ses anciennes cuvées de bière de trogg. Faire renaître cette vieille formule lui réchauffe l'estomac presque autant que ces breuvages d'autrefois."}},faq={{q="Qui est le Brasseur Drohn ?",a="Le Brasseur Drohn est un brasseur orc installé à Cabestan, la ville portuaire. Son mentor reçut des recettes du vagabond Chen Stormstout et transmit à Drohn l'art du brassage.",al={"brasseur drohn","qui est drohn","drohn cabestan"}},{q="Pourquoi une recette de bière exige-t-elle des rognons et des cornes d'animaux ?",a="Les traditions de brassage pandarènes et leurs adaptations des régions sauvages font appel à des ingrédients puissants et ésotériques issus de la faune locale. Ils donnent vigueur, mordant et essences naturelles distinctes aux breuvages corsés.",al={"pourquoi des parties d'animaux","rognons de trotteur des plaines pour le brassage","défenses de lion pour la bière"}},{q="Où trouver les ingrédients requis ?",a="Les trotteurs des plaines et les lions des savanes parcourent les prairies ouvertes des Tarides. Les lézards-tonnerre paissent dans les zones plus sèches ou rocheuses.",al={"où trouver des défenses","où se trouvent les lézards-tonnerre","trouver des ingrédients de brassage"}},{q="Qui était Chen Stormstout ?",a="Chen Stormstout est un brasseur pandaren vagabond qui parcourut Kalimdor lors de la fondation de Durotar. Il aida la Horde tout en cherchant des ingrédients rares et exotiques pour parfaire ses bières puissantes.",al={"qui est chen","histoire de chen stormstout","chen"}},{q="Que se passe-t-il après avoir apporté les ingrédients à Drohn ?",a="Quand vous apportez à Drohn les défenses de lion, les rognons de trotteur des plaines et la corne de lézard-tonnerre, il est ravi. Ces ingrédients lui rappellent ses débuts dans le brassage et ouvrent la dernière étape de la recréation du breuvage.",al={"quête suivante après le tonneau vide de chen","récompense de drohn","que faire ensuite"}},{q="Qu'est-ce que la bière de trogg dont parle Drohn ?",a="Drohn se remémore avec tendresse la bière de trogg en voyant les ingrédients sauvages. Son souvenir témoigne de son passé excentrique, où il faisait fermenter des concoctions âpres et inhabituelles aux confins de la civilisation.",al={"bière de trogg","drohn et la bière de trogg"}}},fx={cd71a987={q="Pourquoi le Brasseur Drohn veut-il ces ingrédients ?",a="Le Brasseur Drohn veut recréer la légendaire bière Stormstout, une boisson exotique et puissante transmise de Chen Stormstout au mentor de Drohn et enfin à lui. Préparer cette bière est un acte de nostalgie et de fierté pour Drohn, évoquant de bons souvenirs de célèbres concoctions passées et honorant les techniques laissées par le maître pandaren errant.",al={"pourquoi drohn veut-il cela","motivation de drohn","pourquoi faire la bière"}}},fp="16,109,17.301.0,23.360.1,24.167.0,56.181.0,44.124.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="Tonneau vide de Chen",s="À Cabestan, le Brasseur Drohn reprend une autre recette que Chen Stormstout lui a transmise. La bière trogg ale exige des organes et des glandes rares prélevés sur les bêtes des Tarides.",h="À Cabestan, le Brasseur Drohn reprend une autre recette que Chen Stormstout lui a transmise.",kw={"les tarides","brasseur drohn","chen stormstout","tonneau vide de chen","foie de kodo","cabestan","stormhide","faucon-tonnerre","trogg ale"},ang={["faction:Horde"]="En tant que membre de la Horde, vous partagez une histoire avec Chen Stormstout, qui a combattu aux côtés de la Horde pour défendre Durotar. Son passage a durablement marqué les orcs comme Drohn.",["profession:Cooking"]="La trogg ale risque de déplaire aux puristes de la cuisine. Pourtant, sa chair d’organes riche et ses glandes puissantes respectent la coutume des frontières : ne rien gaspiller d’une bête tuée.",["race:Orc"]="En tant qu’orc, vous trouverez peut-être le parcours de Drohn inhabituel. Il a préféré les méthodes de brassage exotiques de Chen à la voie traditionnelle du guerrier, et il tient son commerce à Cabestan."},sec={{t="Une deuxième formule pandarène",b="Vous avez aidé le Brasseur Drohn à recréer le premier breuvage de Chen Stormstout. Vous découvrez maintenant que le pandaren errant lui a confié d’autres secrets de brassage. Drohn possède la formule de la trogg ale, une étrange boisson préparée avec des parties puissantes des bêtes sauvages du centre de Kalimdor, plutôt qu’avec des céréales."},{t="Les ingrédients de la trogg ale",b="La trogg ale exige des glandes d’éclair prélevées sur les stormhides, une glande salivaire de grands faucons-tonnerres et un foie robuste de kodos errant dans les plaines. Distillés ensemble, ces ingrédients donnent une boisson fortement stimulante, adaptée à la vie en pleine nature."},{t="Un accord durable",b="Le Brasseur Drohn maintient son accord avec les voyageurs et les mercenaires de passage à Cabestan. Apportez-lui une nouvelle réserve d’organes de bêtes, et il acceptera de brasser davantage de trogg ale."}},faq={{q="Qui est Chen Stormstout ?",a="Chen Stormstout est un maître brasseur pandaren insaisissable qui a parcouru Kalimdor durant la fondation de Durotar. Avant de reprendre la route, il a transmis à Drohn, à Cabestan, quelques-unes de ses puissantes méthodes de brassage.",al={"qui est chen","histoire de chen","chen pandaren"}},{q="Où se trouve le Brasseur Drohn ?",a="Le Brasseur Drohn se trouve à Cabestan, le port neutre sur la côte est des Tarides. Il passe ses journées à perfectionner les breuvages appris auprès de Chen.",al={"emplacement de drohn","où se trouve le brasseur drohn","pnj drohn"}},{q="Qu’est-ce que la trogg ale ?",a="La trogg ale est un puissant breuvage que Chen a appris à préparer à Drohn. Les glandes et la chair des organes de bêtes remplacent le houblon ordinaire, donnant à cette boisson un effet redoutable, digne des aventuriers aguerris.",al={"trogg ale","quelle est cette boisson","que brasse drohn"}},{q="Où trouver des glandes d’éclair ?",a="Vous pouvez récupérer des glandes d’éclair sur les stormhides qui parcourent les terres arides des Tarides. Leur corps porte des charges électriques naturelles.",al={"source des glandes d’éclair","emplacement des stormhides","où trouver des glandes d’éclair"}},{q="Quelles bêtes donnent des glandes salivaires de faucon-tonnerre ?",a="Les grands faucons-tonnerres fournissent les glandes salivaires dont Drohn a besoin. Ces prédateurs ailés chassent dans le ciel ouvert des Tarides.",al={"glande salivaire de faucon-tonnerre","où trouver de grands faucons-tonnerres","emplacement des faucons-tonnerres"}},{q="Peut-on brasser de la trogg ale plusieurs fois ?",a="Oui. Le Brasseur Drohn préparera de nouveau de la trogg ale si des aventuriers lui apportent des glandes fraîches et un foie de kodo.",al={"quête répétable","peut-on refaire cette quête","recommencer la trogg ale"}}},fx={["72ec56fd"]={q="Pourquoi le Brasseur Drohn veut-il ces ingrédients ?",a="Drohn est impatient de partager une autre recette exotique qu'il a apprise directement du brasseur errant Chen Stormstout. Vous ayant déjà guidé dans la recréation de la précieuse bière brune de Chen, Drohn veut préparer un lot de bière de trogg puissante, une concoction avec un sacré caractère destinée à fortifier et à aider les aventuriers courageux qui bravent les périlleuses Tarides.",al={"pourquoi drohn veut-il cela","motivation du brasseur drohn","pourquoi faire de la bière de trogg"}},["63499675"]={q="À quoi sert la Glande d'éclair ?",a="Les glandes d'éclair sont l'un des ingrédients de la recette de bière de trogg de Chen. Drohn en demande cinq, récoltées sur des cuirassés des tempêtes dans les Tarides.",al={"pourquoi la glande d'éclair","lore d'utilisation de la glande d'éclair","à quoi servent les glandes d'éclair"}},["4ecc81d9"]={q="À quoi sert la Glande salivaire de faucon-tonnerre ?",a="Drohn a besoin d'une glande salivaire d'un faucon-tonnerre supérieur pour préparer la bière de trogg de Chen. Il n'explique pas le rôle précis de la glande dans la préparation de la boisson.",al={"pourquoi la glande salivaire de faucon-tonnerre","utilisation de la glande salivaire de faucon-tonnerre","à quoi sert la salive de faucon-tonnerre"}},["315602f6"]={q="À quoi sert le Foie de kodo ?",a="Un foie de kodo est l'un des ingrédients dont Drohn a besoin pour la bière de trogg de Chen. Il accepte un foie provenant de n'importe quel kodo des Tarides.",al={"pourquoi le foie de kodo","lore d'utilisation du foie de kodo","à quoi sert le foie de kodo"}}},fp="16,154,25.261.0,28.252.0,23.181.1,23.209.0,34.145.0,18.176.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:8225"] = {n="Rare Fish - Brownell's Blue Striped Racer",s="Un registre de pêche indique que Brownell's Blue Striped Racer a été identifié. Son identification est terminée.",h="Un registre de pêche indique que Brownell's Blue Striped Racer a été identifié.",kw={"brownell's blue striped racer","brownell's racer","identification du poisson","poisson rare","récompense"},sec={{t="Le registre",b="Un bref signal suit l’identification de Brownell's Racer. Brownell's Blue Striped Racer est marqué comme terminé, et une récompense est disponible."}},faq={{q="Qu’est-ce que Brownell's Blue Striped Racer ?",a="Brownell's Blue Striped Racer est le poisson dont l’identification est marquée comme terminée.",al={"brownell racer","poisson à rayures bleues"}},{q="L’identification est-elle terminée ?",a="Oui. L’identification de Brownell's Racer est terminée.",al={"identification du poisson","racer identifié"}},{q="Une récompense est-elle disponible ?",a="Oui. Une récompense est disponible une fois l’identification terminée.",al={"récompense pour le poisson","récompense obtenue"}}},fp="41,99,10.139.0,38.82.0,31.56.0,22.64.0"}
P.entries["quest:8228"] = {n="Could I get a Fishing Flier?",s="Un concours de pêche est annoncé à Baie-du-Butin pour dimanche. Le dépliant en donne les règles.",h="Un concours de pêche est annoncé à Baie-du-Butin pour dimanche.",kw={"baie-du-butin","concours de pêche","dépliant de pêche","règles de pêche","tournoi"},sec={{t="Règles du tournoi",b="L’avis vous présente les règles du concours de pêche de Baie-du-Butin. Le tournoi aura lieu ce dimanche, et le dépliant vous permet d’en découvrir le déroulement avant de décider si vous souhaitez y participer."}},faq={{q="Quand a lieu le concours de pêche ?",a="Le concours de pêche de Baie-du-Butin a lieu ce dimanche.",al={"date du concours de pêche","quel jour"}},{q="Où a lieu le concours de pêche ?",a="Le concours de pêche a lieu à Baie-du-Butin.",al={"lieu du concours de pêche","lieu du concours"}},{q="Que m’apprend le dépliant de pêche ?",a="Le dépliant vous présente les règles du concours de pêche.",al={"infos sur le dépliant de pêche","contenu du dépliant"}},{q="Puis-je participer au tournoi ?",a="L’avis présente les règles si vous souhaitez participer au concours de pêche.",al={"participer au tournoi de pêche","participer au concours"}}},fp="28,124,16.195.0,28.48.0,29.36.0,36.53.0,36.78.0"}
P.entries["quest:823"] = {n="Un rapport à Orgnil",s="Maître Gadrin envoie depuis le Village de Sen'jin un avertissement à Tranchecolline au sujet de la Lame ardente. La corruption démoniaque se répand dans Durotar.",h="Maître Gadrin envoie depuis le Village de Sen'jin un avertissement à Tranchecolline au sujet de la Lame...",kw={"lame ardente","durotar","maître gadrin","orgnil marque-l'âme","tranchecolline","un rapport à orgnil","village de sen'jin"},ang={["faction:Horde"]="En tant que membre de la Horde, vous comptez sur la coopération entre les trolls sombrelances, récemment alliés, et les orcs de Durotar pour faire face aux menaces communes.",["race:Orc"]="En tant qu'orc, vous pouvez voir en Orgnil Marque-l'âme un défenseur de votre patrie. Il s'efforce d'empêcher la corruption démoniaque de s'enraciner dans Durotar.",["race:Troll"]="Les Sombrelance sont pris dans leur lutte contre Zalazane. Maître Gadrin montre malgré tout l'engagement des trolls envers la Horde en avertissant les chefs orcs des dangers qui menacent toute la région."},sec={{t="Une défense coordonnée",b="Le Village de Sen'jin a ses propres problèmes, en particulier la trahison de Zalazane sur les Îles de l'Écho. Pourtant, la Lame ardente menace bien plus que le village. Une corruption démoniaque a été découverte dans la Vallée des épreuves, et Maître Gadrin sait qu'il ne peut affronter seul ce danger. Il vous envoie donc vers le nord, par la route jusqu'à Tranchecolline, où les autorités orcs veillent sur Durotar."},{t="Orgnil Marque-l'âme",b="Orgnil Marque-l'âme se trouve au campement militaire de Tranchecolline, chargé d'éradiquer les menaces à Durotar et de protéger ses terres centrales. Lorsque vous lui apportez l'avertissement de Gadrin, Orgnil le joint aux rapports du Village de Sen'jin et de la Vallée des épreuves. La Lame ardente est dangereusement proche. Il rassemble rapidement des forces pour disperser les sectateurs avant que leurs rituels ne déstabilisent la jeune nation."}},faq={{q="Qui donne la quête Un rapport à Orgnil ?",a="Maître Gadrin, le féticheur des Trolls sombrelances et leur chef spirituel au Village de Sen'jin, vous envoie après que vous avez aidé les trolls à régler leurs premiers problèmes locaux.",al={"qui donne un rapport à orgnil","où obtenir un rapport à orgnil","donneur de quête un rapport à orgnil"}},{q="Où se trouve Orgnil Marque-l'âme ?",a="Orgnil Marque-l'âme se trouve à Tranchecolline, la bourgade fortifiée au nord du Village de Sen'jin, au centre de Durotar.",al={"où se trouve orgnil marque-l'âme","emplacement d'orgnil marque-l'âme","trouver orgnil marque-l'âme"}},{q="Pourquoi Maître Gadrin vous envoie-t-il à Tranchecolline ?",a="Maître Gadrin voit que l'activité des sectateurs démoniaques dans la Vallée des épreuves et aux alentours de Durotar menace tout le monde, pas seulement les trolls. Il vous envoie auprès d'Orgnil Marque-l'âme, l'orc chargé de protéger la région contre la Lame ardente.",al={"pourquoi un rapport à orgnil","pourquoi aller à tranchecolline","but de la quête un rapport à orgnil"}},{q="Qu'est-ce que la Lame ardente mentionnée dans la quête ?",a="La Lame ardente est une secte clandestine d'adorateurs de démons qui agit dans l'ombre de Durotar et au-delà. Sa présence dissimulée dans les canyons et les grottes voisines menace la sécurité et la stabilité de la jeune Horde.",al={"qui sont les membres de la lame ardente","secte de la lame ardente","qu'est-ce que la lame ardente"}},{q="Quelle quête suit Un rapport à Orgnil ?",a="Après que vous avez remis le rapport à Orgnil Marque-l'âme, à Tranchecolline, il vous confie Dark Storms. Il vous envoie enquêter sur la menace grandissante des sectateurs et la combattre.",al={"quête après un rapport à orgnil","suite de la quête un rapport à orgnil","que faire après un rapport à orgnil"}},{q="Quel prérequis faut-il remplir avant d'obtenir cette quête ?",a="Cette quête suit votre arrivée au Village de Sen'jin dans le cadre de Report to Sen'jin Village. Elle relie ce que vous avez découvert dans la Vallée des épreuves à la campagne qui s'étend à Durotar.",al={"prérequis de la quête un rapport à orgnil","comment débloquer un rapport à orgnil","quête précédente de un rapport à orgnil"}}},fp="16,138,21.361.0,15.375.0,37.151.0,33.103.0,46.230.0,49.194.0,36.156.0,64.158.0"}
P.entries["quest:8234"] = {n="Sac azur scellé",s="À Azshara, on vous demande de récupérer un sac scellé auprès d’un chaman des Timbermaw et de le remettre à l’Archimage Xylem. Le sac relie le chaman au mage.",h="À Azshara, on vous demande de récupérer un sac scellé auprès d’un chaman des Timbermaw et de le remettre à...",kw={"archimage xylem","azshara","sac","sac azur scellé","chaman des timbermaw"},sec={{t="Un sac scellé",b="Un chaman des Timbermaw, à Azshara, détient le Sac azur scellé, et l’Archimage Xylem l’attend dans la même région. On vous demande de transporter le sac de l’un à l’autre."}},faq={{q="Qui détient le Sac azur scellé ?",a="Un chaman des Timbermaw, à Azshara, détient le Sac azur scellé.",al={"qui détient le sac","sac des timbermaw"}},{q="Qui veut le sac ?",a="L’Archimage Xylem doit recevoir le Sac azur scellé à Azshara.",al={"qui reçoit le sac","où apporter le sac"}},{q="Où trouver le sac ?",a="Le Sac azur scellé se trouve auprès d’un chaman des Timbermaw, à Azshara.",al={"emplacement du sac","où se trouve le sac azur scellé"}},{q="Où se trouve l’Archimage Xylem ?",a="L’Archimage Xylem se trouve à Azshara.",al={"emplacement de xylem","où se trouve xylem"}}},fp="16,164,12.164.0,29.55.0,18.61.0,24.59.0,24.29.0"}
P.entries["quest:824"] = {n="Je'neu du Cercle terrestre",s="À l’Avant-poste de Zoram’gar, Je’neu du Cercle terrestre étudie une corruption qui se répand dans la région. Des voyageurs de la Horde lui apportent un globe d’eau corrompu prélevé sur les élémentaires d’Orneval. Il cherche à comprendre le fléau qui sévit le long de la grève de Zoram et dans les Profondeurs de Brassenoire, dans l’espoir d’arrêter le poison qui gagne les eaux.",h="À l’Avant-poste de Zoram’gar, Je’neu du Cercle terrestre étudie une corruption qui se répand dans la région.",kw={"globe d'eau souillée","profondeurs de brassenoire","cercle terrestre","élémentaires","je'neu sancrea","mastok torvesiffle","la grève de zoram","avant-poste de zoram'gar"},ang={["class:Shaman"]="En tant que chaman, vous contribuez à préserver l’équilibre élémentaire. En remettant le globe corrompu, vous aidez un autre membre du Cercle terrestre à diagnostiquer une dangereuse maladie spirituelle.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à sécuriser le littoral d’Orneval en découvrant l’origine obscure de l’hostilité des élémentaires près des camps fortifiés comme l’Avant-poste de Zoram’gar.",["race:Troll"]="En tant que troll, vous pouvez apprécier la profonde sagesse spirituelle de Je’neu Sancrea. Il met son lien ancestral avec les esprits au service du Cercle terrestre."},sec={{t="Un messager des éléments",b="Mastok Torvesiffle vous envoie auprès de Je’neu Sancrea avec un globe d’eau corrompu récupéré sur les élémentaires d’Orneval. D’étranges élémentaires sont apparus dans toute la région, animés par une puissance que les éclaireurs ne peuvent expliquer. Parmi leurs dépouilles, un globe intact vibre d’une magie corrompue.\n\nMastok sait que les soldats et les éclaireurs n’ont pas le discernement spirituel nécessaire pour le comprendre. Il demande donc aux voyageurs de la Horde de s’adresser à quelqu’un qui connaît les légendes anciennes et les traditions élémentaires."},{t="Les yeux du Cercle terrestre",b="Je’neu Sancrea sert le Cercle terrestre, un ordre de chamans voué à l’équilibre entre les forces primordiales d’Azeroth. Les forces de la Horde gardent la frontière de la grève de Zoram tandis qu’il étudie la blessure spirituelle qui sévit dans les ruines du temple voisin des Profondeurs de Brassenoire.\n\nPour Je’neu, un élémentaire qui puise sa force dans un réceptacle souillé n’est pas une menace isolée. C’est un présage alarmant : des puissances anciennes et invisibles pervertissent l’ordre naturel."}},faq={{q="Qui est Je’neu Sancrea ?",a="Je’neu Sancrea est un chaman troll du Cercle terrestre, dans le nord de Kalimdor. Il consacre sa vie à communier avec les éléments et à les étudier. Il demeure près de la grève de Zoram pour enquêter sur les perturbations obscures qui remontent des Profondeurs de Brassenoire.",al={"qui est je’neu","histoire de je’neu sancrea","que fait je’neu ici"}},{q="Qu’est-ce que le Cercle terrestre ?",a="Le Cercle terrestre est un ordre de chamans voué à maintenir l’harmonie entre les éléments primordiaux d’Azeroth. Ses membres étudient les savoirs anciens, les esprits oubliés et les vieilles légendes pour apaiser le chaos élémentaire et guérir la corruption spirituelle à travers le monde.",al={"qu’est-ce que le cercle terrestre","qui sont les membres du cercle terrestre","histoire du cercle terrestre"}},{q="Où trouver Je’neu Sancrea ?",a="Je’neu Sancrea se trouve à l’Avant-poste de Zoram’gar, sur la côte de la grève de Zoram, en Orneval. Il y étudie les perturbations élémentaires qui remontent des Profondeurs de Brassenoire, toutes proches.",al={"où se trouve je’neu","emplacement de je’neu","trouver je’neu sancrea"}},{q="Qu’est-ce que le Globe d’eau souillée ?",a="Le Globe d’eau souillée est un conduit magique par lequel de puissants élémentaires d’eau canalisent leur force. Son état corrompu, malgré son intégrité, suggère que des forces obscures cherchent délibérément à pervertir et à asservir les esprits de la région.",al={"qu’est-ce que le globe","histoire du globe d’eau souillée","globe d’eau"}},{q="Qui vous envoie parler à Je’neu ?",a="Mastok Torvesiffle, un officier de la Horde en poste en Orneval, envoie les voyageurs remettre la relique souillée à Je’neu. L’armée ne parvient pas à percer sa nature magique étrange.",al={"qui donne cette quête","quête de mastok"}},{q="Que fera Je’neu du globe ?",a="Je’neu confie le réceptacle au Cercle terrestre pour que ses membres étudient le fléau. Il espère que cette étude révélera comment purifier les eaux et rétablir la paix parmi les élémentaires tourmentés de la région.",al={"que devient le globe","guérir la corruption"}}},fx={["5c718e13"]={q="Pourquoi Mastok Torvesiffle vous envoie-t-il vers Je'neu ?",a="Mastok reconnaît que le Globe d'eau souillée dépasse largement son expertise. Comprendre la magie corrompue, les vieilles légendes et les élémentaires perturbés relève clairement du domaine du Cercle terrestre. Il vous envoie vers Je'neu Sancrea car Je'neu est un chaman local du Cercle qui possède les connaissances élémentaires profondes nécessaires pour percer la véritable signification et la menace du globe.",al={"motivation de mastok torvesiffle","pourquoi envoyer vers jeneu","pourquoi mastok veut-il que cela soit fait"}}},fp="26,308,28.440.0,28.407.0,22.235.0,25.234.0,34.173.0,33.220.0,35.168.0,35.188.0"}
P.entries["quest:8241"] = {n="Réapprovisionnement en flux embrasé (Fer)",s="Dans la Gorge des Vents brûlants, le flux embrasé vient à manquer et le Maître forgeron Burninate en a besoin. Après What the Flux?, Burninate demande des écailles, des barres de fer et du charbon, et prendra tout ce que vous pourrez offrir.",h="Dans la Gorge des Vents brûlants, le flux embrasé vient à manquer et le Maître forgeron Burninate en a besoin.",kw={"charbon","flux embrasé","écaille d'incendosaure","barre de fer","maître forgeron burninate","réapprovisionnement des réserves de flux embrasé avec du fer","gorge des vents brûlants","confrérie du thorium"},sec={{t="Recherche de flux embrasé",b="Le Maître forgeron Burninate a besoin de davantage de flux embrasé, car les réserves s'épuisent. Dans la Gorge des Vents brûlants, Burninate vous demande deux écailles d'incendosaure, quatre barres de fer et du charbon. Il prendra tout ce que vous pourrez offrir."}},faq={{q="Qui demande ces marchandises ?",a="Le Maître forgeron Burninate demande ces marchandises et les reçoit en personne dans la Gorge des Vents brûlants.",al={"qui donne cette quête","burninate flux embrasé","où rendre la quête"}},{q="Quels matériaux Burninate veut-il ?",a="Burninate veut deux écailles d'incendosaure, quatre barres de fer et du charbon.",al={"quels objets me faut-il","matériaux pour le flux embrasé","objets à remettre à burninate"}},{q="Que s'est-il passé avant cette demande ?",a="What the Flux? a précédé cette demande, et Burninate vous a confié cette quête.",al={"prérequis de cette quête","quête précédente flux embrasé","prérequis what the flux"}},{q="Pourquoi Burninate veut-il ces marchandises ?",a="Burninate explique que les réserves de flux embrasé diminuent et qu'il en faut davantage pour les reconstituer.",al={"pourquoi du flux embrasé","motivation de burninate"}}},fp="38,190,17.196.0,25.91.0,35.65.0,30.70.0,36.88.0"}
P.entries["quest:8242"] = {n="Réapprovisionnement en flux embrasé (Cuir lourd)",s="Dans la Gorge des Vents brûlants, Maître forgeron Burninate a besoin de nouvelles réserves de flux embrasé. Après What the Flux?, il vous demande deux écailles d'incendosaure, dix pièces de Cuir lourd et du charbon. Apportez-lui tout ce que vous pouvez offrir.",h="Dans la Gorge des Vents brûlants, Maître forgeron Burninate a besoin de nouvelles réserves de flux embrasé.",kw={"burninate","charbon","flux embrasé","cuir lourd","écaille d'incendosaure","gorge des vents brûlants","confrérie du thorium"},sec={{t="Flux embrasé recherché",b="Maître forgeron Burninate a besoin de flux embrasé dans la Gorge des Vents brûlants. Les réserves s'épuisent, alors il vous demande deux écailles d'incendosaure, dix pièces de Cuir lourd et du charbon. Apportez-lui tout ce que vous pouvez offrir."}},faq={{q="Qui demande ces marchandises ?",a="Maître forgeron Burninate demande ces marchandises dans la Gorge des Vents brûlants et les reçoit en personne.",al={"qui donne cette quête","burninate flux embrasé","où rendre la quête"}},{q="Quels matériaux Burninate veut-il ?",a="Burninate veut deux écailles d'incendosaure, dix pièces de Cuir lourd et du charbon.",al={"quels objets me faut-il","matériaux pour le flux embrasé","objets à remettre à burninate"}},{q="Que s'est-il passé avant cette demande ?",a="Avant cette demande, Burninate vous a confié What the Flux?.",al={"prérequis de cette quête","quête précédente flux embrasé","prérequis what the flux"}},{q="Pourquoi Burninate veut-il ces marchandises ?",a="Burninate explique que les réserves de flux embrasé s'épuisent et doivent être réapprovisionnées.",al={"pourquoi du flux embrasé","motivation de burninate"}}},fp="47,202,17.200.0,25.91.0,35.78.0,30.55.0,36.75.0"}
P.entries["quest:8249"] = {n="Demande de coffrets",s="Fahrad fournit Ravenholdt en coffrets verrouillés pour entraîner les voleurs. Il échange des couteaux de lancer spécialisés contre de véritables coffrets lourds, et sa demande est sans fin.",h="Fahrad fournit Ravenholdt en coffrets verrouillés pour entraîner les voleurs.",kw={"coffret lourd","hautebrande","coffrets lourds","crochetage","vol à la tire","ravenholdt","fahrad","zan"},ang={["class:Rogue"]="En tant que voleur, vous pouvez obtenir ces coffres lourds en faisant les poches d’adversaires aguerris. Ravenholdt donne à cette pratique illicite une utilité.",["faction:Alliance"]="Ravenholdt se trouve dans le territoire disputé du Lordaeron et agit de manière indépendante. En tant que voyageur de l’Alliance, vous pouvez lui apporter des contrats sans tenir compte des factions.",["faction:Horde"]="En tant qu’agent de la Horde, vous pouvez braver le voyage jusque dans les montagnes de Hautebrande. Ravenholdt se moque des loyautés de faction et privilégie avant tout les biens illicites utiles."},sec={{t="Aiguiser les griffes de Ravenholdt",b="Le Manoir de Ravenholdt se cache dans les montagnes qui surplombent les Contreforts de Hautebrande, où l’entraînement ne s’arrête jamais. Le maître voleur Fahrad supervise les agents de la guilde et accorde une grande importance au crochetage. Zan fournit des mécanismes d’entraînement aux nouvelles recrues. Fahrad les trouve trop rudimentaires pour les voleurs expérimentés qui doivent ouvrir des serrures récalcitrantes sur le terrain."},{t="Un arrangement curieusement ouvert",b="Fahrad paie pour les coffrets lourds dérobés à des cibles dangereuses partout en Azeroth et les accepte par lots. Seuls les voleurs habiles peuvent subtiliser les coffrets à leurs cibles dans la nature, mais tout le monde peut les apporter au manoir. Même les coffrets dépouillés de leurs biens les plus précieux lui valent sa faveur et de fins couteaux de lancer parfaitement équilibrés, fabriqués au manoir. Une pièce doit rester à l’intérieur pour motiver les initiés."}},faq={{q="Pourquoi Fahrad veut-il ces coffrets lourds ?",a="Les voleurs en apprentissage de Ravenholdt ont besoin de serrures réalistes pour s’exercer. Zan, l’artisan qui réside au manoir, fabrique des coffres d’entraînement que Fahrad juge trop élémentaires pour quiconque a dépassé le stade de débutant. Il exige donc de véritables coffrets verrouillés dérobés à des cibles dangereuses.",al={"pourquoi les coffrets lourds","utilité des coffrets lourds","pourquoi fahrad veut des coffrets"}},{q="Où se déroule cette tâche ?",a="L’échange a lieu au Manoir de Ravenholdt, refuge secret de la guilde des voleurs dans les montagnes au nord des Contreforts de Hautebrande.",al={"lieu de la demande de coffrets","où se trouve fahrad","emplacement de ravenholdt"}},{q="Seuls les voleurs peuvent-ils remettre les coffrets ?",a="Toute personne qui apporte des coffrets lourds au manoir peut les remettre. Les voleurs habiles les dérobent à leurs cibles à la tire.",al={"réservé aux voleurs","tout le monde peut-il apporter des coffrets","coffrets lourds pour les autres classes"}},{q="Pourquoi faut-il laisser des pièces dans les coffrets ?",a="Fahrad exige qu’il reste quelques pièces dans chaque coffre, afin de donner aux voleurs en formation une raison concrète de s’exercer au crochetage.",al={"pourquoi laisser des pièces dans le coffret","faut-il du butin dans les coffrets","coffrets lourds vides"}},{q="Qu’offre Ravenholdt en échange ?",a="Les contributeurs gagnent la considération de la guilde et des couteaux de lancer finement ouvragés, remis par Fahrad. Il espère avec ironie qu’ils trouveront leur place dans le cœur de quelqu’un.",al={"récompense de la demande de coffrets","que donne fahrad","couteaux de lancer de ravenholdt"}},{q="Qui est Zan, dont Fahrad se plaint ?",a="Zan fournit à Ravenholdt des serrures et des mécanismes d’entraînement. Fahrad juge son travail grossier et adapté uniquement aux débutants les plus inexpérimentés, pas aux agents sérieux.",al={"qui est zan","zan à ravenholdt","serrures de zan"}}},fx={["45d1fe22"]={q="Pourquoi Ravenholdt a-t-il besoin d'un voleur extérieur pour récupérer des coffrets ?",a="Les apprentis actuels de Ravenholdt font encore leurs premières armes et manquent tout simplement de compétences pour obtenir des serrures complexes par eux-mêmes. Les mécanismes d'entraînement fabriqués par leur bricoleur attitré, Zan, sont bien trop rudimentaires pour un entraînement avancé. Fahrad compte sur des agents accomplis comme vous pour vous aventurer en territoire périlleux et dérober de véritables coffrets de haute sécurité qui représentent un véritable défi.",al={"pourquoi me demander des coffrets","pourquoi lou pierret a besoin de moi","pourquoi ravenholdt ne récupère pas ses propres coffrets"}}},fp="16,166,30.335.0,28.382.0,37.257.0,32.131.0,35.136.0,52.128.0,39.138.0,39.148.0"}
P.entries["quest:825"] = {n="Des épaves",s="Gar'Thok envoie des éclaireurs de la Horde sur les épaves de la Côte des naufrages pour récupérer des Outils gnomes.",h="Gar'Thok envoie des éclaireurs de la Horde sur les épaves de la Côte des naufrages pour récupérer des Outils...",kw={"durotar","gar'thok","outils gnomes","portvaillant","tranchecolline","récupération","côte des naufrages","donjon de tiragarde","épaves"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que Gar'Thok voit dans le métal de l'Alliance un savoir qui aidera à vaincre de futures invasions et des matériaux pour bâtir Durotar.",["profession:Engineering"]="En tant que bricoleur, vous voyez dans les Outils gnomes les prémices d'un affrontement entre la précision mécanique de l'Alliance et les industries artisanales grandissantes de la Horde.",["race:Gnome"]="En tant que gnome, vous laissez votre marque partout où navigue l'Alliance. La Horde respecte assez votre équipement sophistiqué pour envoyer des éclaireurs le récupérer."},sec={{t="Les échos de la flotte",b="Le grand amiral Daelin Portvaillant a mené la flotte de Kul Tiras jusqu'en Kalimdor. Ses navires ont envahi le rivage près du Donjon de Tiragarde. Après sa défaite, des coques brisées ont sombré le long de la Côte des naufrages. Les soldats kultirassiens survivants fortifient le donjon, tandis que les épaves reposent sur les hauts-fonds sous la marée."},{t="Les inventions gnomes",b="L'ingéniosité de l'Alliance peut donner à ses ennemis un avantage sur la force, le fer et le sang des orcs. Des techniciens gnomes ont navigué avec la flotte expéditionnaire et équipé ses navires de machines complexes et d'outils de précision. Gar'Thok veut que la Horde récupère ces outils dans les épaves. Ses artisans pourront alors apprendre à s'en servir."},{t="En route pour Orgrimmar",b="Gar'Thok fait transporter les outils récupérés par caravane de Tranchecolline à Orgrimmar. Là-bas, les artisans et les tacticiens de la Horde espèrent étudier les instruments gnomes. Ils cherchent comment contrer les engins de l'Alliance lors des conflits à venir et renforcer leurs propres industries."}},faq={{q="Pourquoi la Horde récupère-t-elle des outils dans ces épaves ?",a="La Horde veut comprendre la technologie avancée de l'Alliance. Les gnomes fabriquent des machines complexes pour les forces humaines. L'étude de leurs outils pourrait aider les tacticiens de la Horde à contrer les engins de l'Alliance et à adapter des modèles utiles pour leurs propres artisans.",al={"pourquoi récupérer des outils gnomes","pourquoi récupérer les épaves","raison de gar'thok pour les outils"}},{q="À qui appartiennent les navires échoués au large de la Côte des naufrages ?",a="Les navires naufragés appartenaient à la flotte de Kul Tiras du grand amiral Daelin Portvaillant. Après avoir débarqué en Durotar pour combattre la nation récemment fondée par Thrall, plusieurs navires ont été détruits le long de la côte, juste à l'est du Donjon de Tiragarde.",al={"à qui sont ces navires","qui a détruit les navires de durotar","épaves de la flotte de portvaillant"}},{q="Où vont les outils récupérés après Tranchecolline ?",a="Gar'Thok fait transporter les Outils gnomes récupérés par caravane de Tranchecolline à Orgrimmar. Les ingénieurs et les artisans pourront les étudier pour renforcer les défenses et l'industrie de la capitale.",al={"que deviennent les outils","où vont les outils gnomes","qui récupère le butin"}},{q="Pourquoi trouve-t-on des outils gnomes sur des navires de guerre humains ?",a="Les gnomes sont de proches alliés des humains au sein de l'Alliance. Ils apportent souvent leur savoir-faire mécanique, des engins de siège et des outils de précision pour maintenir les navires de guerre humains en état de marche.",al={"pourquoi les gnomes sont alliés aux humains","gnomes sur les navires de portvaillant","technologie gnome de l'alliance"}},{q="Qu'est-ce que la Côte des naufrages ?",a="La Côte des naufrages est le littoral oriental de Durotar, qui longe le Donjon de Tiragarde. Ses eaux peu profondes abritent des navires à moitié submergés ou engloutis après les batailles contre l'expédition de Portvaillant.",al={"où se trouve la côte des naufrages","emplacement de la côte des naufrages","zone des navires engloutis de durotar"}},{q="Quel est le lien entre cette tâche et la menace au Donjon de Tiragarde ?",a="Après l'assaut sur le Donjon de Tiragarde, les marines kultirassiens sont chassés des lieux et Gar'Thok saisit l'occasion de s'emparer des ressources de l'Alliance qui restent. La Horde peut tirer profit de cette défaite en dépouillant les épaves proches avant que les charognards ou la marée n'emportent tout.",al={"lien avec le donjon de tiragarde","lien avec vanquish the betrayers","pourquoi faire cela après tiragarde"}}},fp="21,158,19.294.0,20.317.0,22.254.0,51.247.0,46.219.0,49.182.0,46.159.0,26.186.0,58.246.0"}
P.entries["quest:826"] = {n="Zalazane",s="Sur les Îles de l'Écho, la magie noire a rendu Zalazane fou et l'a dressé contre sa tribu. Maître Gadrin, du Village de Sen'jin, appelle les champions de la Horde à mettre fin au règne du féticheur. Zalazane a réduit ses congénères en esclavage, s'est emparé du foyer légitime des Trolls sombrelances et les a contraints à l'exil sur la côte de Durotar.",h="Sur les Îles de l'Écho, la magie noire a rendu Zalazane fou et l'a dressé contre sa tribu.",kw={"sombrelance","durotar","îles de l'écho","troll ensorcelé","maître gadrin","village de sen'jin","vol'jin","troll vaudou","zalazane"},ang={["class:Shaman"]="En tant que chaman, vous connaissez les arts spirituels et les pouvoirs primordiaux des chamans et féticheurs trolls. Zalazane détourne la magie qui lie les siens pour les asservir.",["faction:Horde"]="En tant que membre de la Horde, vous aidez à défendre les Sombrelance déplacés. Des alliés venus de tout Durotar se rallient à leur cause, lors de l'une des premières grandes épreuves d'unité de la jeune Horde.",["race:Troll"]="En tant que troll sombrelance, vous avez le devoir personnel de punir le traître qui a volé le foyer de votre peuple et réduit les vôtres en esclavage."},sec={{t="Trahison sur les îles",b="Après avoir fui leur île engloutie, les Sombrelance ont suivi Thrall à travers La Grande mer et se sont installés sur les Îles de l'Écho, juste au large de la côte sud-est de Durotar. Zalazane était autrefois un féticheur respecté et puissant, mais il avait soif de pouvoir. Ses maléfices ont asservi l'esprit de ses proches, et la violence a suivi. Vol'jin a mené ceux qui restaient libres, mais ils ont été chassés de leurs campements ancestraux et contraints de bâtir un refuge temporaire au Village de Sen'jin."},{t="Le tourment d'une tribu",b="Depuis sa redoute au sommet de la plus grande des Îles de l'Écho, Zalazane envoie encore des groupes de pillards à travers le chenal. Ils capturent d'autres Sombrelance et les soumettent à son emprise. Les trolls capturés deviennent des esclaves vaudous et maléficiés, décérébrés et perdus pour leur tribu. Maître Gadrin voit là une menace qui dépasse les terres des Sombrelance : Zalazane met en péril la survie de la tribu. Tant que sa tête tranchée n'aura pas été apportée devant les anciens, aucun Sombrelance ne sera en sécurité."}},faq={{q="Qui est Zalazane ?",a="Zalazane était autrefois un féticheur éminent parmi les Trolls sombrelances. La soif de pouvoir occulte l'a corrompu, et il s'est retourné contre les siens, employant le vaudou pour asservir leur esprit et s'emparer des Îles de l'Écho.",al={"histoire de zalazane","qui est le chef des îles de l'écho","zalazane le féticheur"}},{q="Pourquoi les Sombrelance ont-ils fui les Îles de l'Écho ?",a="Les Sombrelance ont fui après que Zalazane a orchestré un coup de force surprise sur les îles et ensorcelé leurs proches pour en faire des esclaves décérébrés. Vol'jin et les Sombrelance libres étaient trop peu nombreux pour affronter leurs proches ensorcelés. Ils se sont donc repliés sur le continent de Durotar et ont fondé le Village de Sen'jin, un refuge temporaire.",al={"pourquoi des trolls sont au village de sen'jin","histoire des îles de l'écho","comment les trolls ont perdu les îles de l'écho"}},{q="Qu'arrive-t-il aux trolls sous l'emprise de Zalazane ?",a="Les maléfices ont privé de leur esprit les trolls sous l'emprise de Zalazane. Ils le servent, patrouillent sur les îles et attaquent le continent pour capturer d'autres victimes. Maître Gadrin les considère comme perdus pour la tribu, et l'exécution comme leur seule délivrance.",al={"trolls ensorcelés","trolls vaudous","peut-on guérir les esclaves de zalazane"}},{q="Où se trouve Zalazane ?",a="Zalazane a établi son repaire sur la plus grande des Îles de l'Écho, juste à l'est de la côte sud de Durotar. Il patrouille depuis le sommet de la colline centrale jusqu'au groupe de huttes trolles à son pied.",al={"emplacement de zalazane","trouver zalazane","où se trouve zalazane"}},{q="Qui donne la quête pour tuer Zalazane ?",a="Maître Gadrin, un ancien de la tribu au Village de Sen'jin, sur la côte sud de Durotar, vous demande de tuer Zalazane. Vous le rencontrez après avoir réglé les menaces locales et être arrivé de la Vallée des épreuves.",al={"qui donne la quête de zalazane","où prendre la quête de zalazane"}},{q="Pourquoi Vol'jin ne mène-t-il pas lui-même l'assaut ?",a="Vol'jin dirige la tribu et coordonne la défense des Sombrelance aux côtés du chef de guerre Thrall, à Orgrimmar. Au Village de Sen'jin, des anciens comme Maître Gadrin veillent à la survie de la communauté, et Gadrin recrute des aventuriers capables de riposter à Zalazane.",al={"où se trouve vol'jin","pourquoi vol'jin ne combat-il pas zalazane"}}},fx={ae6e25c2={q="Pourquoi Maître Gadrin veut-il la mort de Zalazane ?",a="Zalazane ne se contente pas de voler les Îles de l'Écho ; il envoie continuellement ses trolls ensorcelés à travers l'eau pour piller le continent, réduisant en esclavage davantage de Sombrelance pour renforcer ses rangs. Maître Gadrin sait que le Village de Sen'jin ne sera jamais en sécurité tant que le docteur fétiche renégat vivra pour tourmenter et enlever leur peuple.",al={"gadrin zalazane pourquoi","pourquoi tuer zalazane","pourquoi maître gadrin veut-il cela"}},a3c2387d={q="À quoi sert la Tête de Zalazane ?",a="Maître Gadrin exige la tête tranchée de Zalazane comme preuve indéniable de la disparition du docteur fétiche. Ce n'est qu'en voyant la tête de ses propres yeux que Gadrin peut être certain que l'influence sombre de Zalazane est brisée et que la tribu Sombrelance peut enfin dormir en paix.",al={"but de la tête de zalazane","pourquoi apporter la tête de zalazane","objet de quête tête de zalazane"}}},fp="8,304,21.444.0,17.430.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="Le rocher du Crâne",s="Margoz vous envoie à l’est d’Orgrimmar, où des cultistes de la Lame ardente occupent le Rocher du Crâne. Ils se lient à la magie noire au moyen de dispositifs démoniaques douloureux. Margoz a besoin des artéfacts maudits pour étudier la secte près de la capitale.",h="Margoz vous envoie à l’est d’Orgrimmar, où des cultistes de la Lame ardente occupent le Rocher du Crâne.",kw={"lame ardente","cultistes","démoniaque","durotar","gangrené","margoz","orgrimmar","collier brûlant","rocher du crâne"},ang={["class:Warlock"]="En tant que démoniste, vous voyez comment les Searing Collars lient ceux qui les portent au moyen de la magie gangrenée. Leurs enchantements rudimentaires montrent comment la secte transforme les sacrifices démoniaques en pouvoir.",["faction:Horde"]="En tant que membre de la Horde, vous faites face à une secte démoniaque implantée juste au-delà des murs d’Orgrimmar. Elle menace le cœur et la sécurité de votre peuple.",["race:Orc"]="En tant qu’orc, vous faites face à la Lame ardente, vestige du sombre passé de votre peuple. Chasser la secte des rochers de Durotar est une question de survie et d’honneur."},sec={{t="Un repaire dans l’ombre",b="Dans le nord-est de Durotar, des cultistes de la Lame ardente se rassemblent près des portes d’Orgrimmar. Leur grotte se trouve parmi les collines, à l’écart des routes ouvertes, mais près du siège du chef de guerre. La secte tourmente la société orque depuis longtemps, et ses adeptes accomplissent désormais des rituels dans les tunnels. À proximité, les éclaireurs du chef de guerre montent la garde."},{t="L’harmonie démoniaque",b="Les cultistes de la Lame ardente portent des Searing Collars autour du cou. Ces bandes de métal leur brûlent la chair et y impriment leur marque. Margoz pense que la douleur et la sorcellerie gangrenée harmonisent ceux qui les portent avec la puissance démoniaque. Il vous demande de récupérer les colliers afin d’étudier les sorts et les liens qui leur confèrent leur pouvoir."},{t="Une menace grandissante",b="Les Searing Collars révèlent comment la Lame ardente s’est organisée en Durotar. Sa sorcellerie menace les territoires récemment établis de la Horde. Margoz étudie les colliers, puis poursuit ses recherches dans les cercles secrets d’Orgrimmar."}},faq={{q="Où se trouve le Rocher du Crâne ?",a="Le Rocher du Crâne se trouve au nord-est de Durotar, à l’est d’Orgrimmar et au nord du Village de Sen’jin. Son entrée s’ouvre dans une falaise escarpée, le long du rivage.",al={"emplacement du rocher du crâne","où se trouve le rocher du crâne","grotte du rocher du crâne en durotar"}},{q="Qu’est-ce que la Lame ardente ?",a="La Lame ardente est une secte d’orcs et d’adorateurs de la magie gangrenée, dévouée aux démons et à la magie noire. La Horde moderne s’est libérée de la servitude démoniaque, mais des groupes dissidents comme la Lame ardente pratiquent encore des rites interdits et cherchent à corrompre la Horde dans l’ombre.",al={"qu’est-ce que la lame ardente","qui sont les cultistes de la lame ardente","histoire de la lame ardente"}},{q="À quoi servent les Searing Collars des cultistes ?",a="Les cultistes portent des Searing Collars autour du cou, où le métal brûlant leur consume la chair. Margoz soupçonne que la douleur et l’enchantement démoniaque les aident à canaliser les énergies gangrenées et à s’y harmoniser.",al={"utilité des searing collars","pourquoi porter des searing collars","que sont les searing collars"}},{q="Qui est Margoz ?",a="Margoz est un ermite orc qui vit dans un petit camp au sommet des falaises de Durotar, près du Rocher du Crâne. Il surveille les déplacements des cultistes le long de la côte et s’efforce de démanteler les opérations de la Lame ardente.",al={"qui est margoz","margoz en durotar","margoz donneur de quête"}},{q="Pourquoi la Horde laisse-t-elle la secte si près d’Orgrimmar ?",a="La Horde ne tolère pas sciemment la secte près d’Orgrimmar. Les adeptes de la Lame ardente se cachent dans des grottes et des ravins désolés, hors de portée des patrouilles habituelles. Les aventuriers enquêtent lorsque les rituels de la secte révèlent ses positions.",al={"pourquoi le rocher du crâne est près d’orgrimmar","lame ardente près d’orgrimmar"}},{q="Que se passe-t-il après l’examen des colliers par Margoz ?",a="Margoz compte examiner les Searing Collars. Son enquête se poursuit auprès de Neeru Fireblade, à Orgrimmar.",al={"quête suivante après le rocher du crâne","où mènent les colliers","sort de margoz"}}},fx={cfe1a49d={q="Pourquoi Margoz veut-il les Colliers brûlants ?",a="Margoz croit qu'en brûlant leur chair avec ces colliers, les membres du culte s'accordent aux forces démoniaques. Il a besoin d'une collection de colliers intacts pour étudier et inspecter avec sa magie, espérant découvrir les sombres secrets derrière la Lame ardente et exposer à quel point leur corruption démoniaque est profonde.",al={"pourquoi margoz a-t-il besoin de colliers","motivation des colliers brûlants de margoz","pourquoi collecter des colliers brûlants"}},["50396613"]={q="Contre qui êtes-vous envoyé dans le Rocher du Crâne ?",a="Vous êtes envoyé contre les membres du culte de la Lame ardente qui se cachent à l'intérieur du Rocher du Crâne, une caverne à l'est d'Orgrimmar. Ils s'y sont rassemblés sous le nez de la Horde pour accomplir des rituels immondes, se lier à des maîtres démoniaques et comploter contre la sécurité de Durotar.",al={"qui est dans le rocher du crâne","ennemis du rocher du crâne","membres du culte de la lame ardente rocher du crâne"}}},fp="10,216,16.308.0,18.283.0,18.239.1,28.145.0,25.257.0,49.201.0,14.192.0,56.219.0,47.107.1"}
P.entries["quest:8273"] = {n="La gratitude d'Oran",s="Vous apportez une tablette à Oran Snakewrithe, et la suite de Rin'ji prend fin.",h="Vous apportez une tablette à Oran Snakewrithe, et la suite de Rin'ji prend fin.",kw={"dame noire","hinterlands","oran snakewrithe","falaises du surplomb","rin'ji","tablette"},sec={{t="Une tablette pour Oran",b="Après Rin'ji's Secret, vous apportez la tablette à Oran Snakewrithe. Vous la déposez entre ses mains."},{t="La réponse d'Oran",b="Vous dites à Oran Snakewrithe que la tablette vient d'une petite île déserte, près des falaises du Surplomb. Cette découverte l'intéresse beaucoup et il range soigneusement la tablette. Puis il dit que la Dame noire sera très satisfaite."}},faq={{q="Qui est Oran Snakewrithe ?",a="Oran Snakewrithe reçoit la tablette au terme de la suite de quêtes commencée avec Rin'ji is Trapped! et poursuivie avec Rin'ji's Secret.",al={"oran","qui est oran","histoire d'oran snakewrithe"}},{q="Quelle quête précède celle-ci dans la suite ?",a="Rin'ji's Secret précède cette quête, après Rin'ji is Trapped!.",al={"quête précédente","prérequis de la gratitude d'oran","comment commencer la gratitude d'oran"}}},fp="16,72,17.91.0,13.220.1,24.134.0,36.66.0"}
P.entries["quest:828"] = {n="Margoz",s="Dans le nord de Durotar, Margoz surveille la menace grandissante de la Lame ardente. Après l'affrontement contre la corruption gangrenée aux Falaises du Tonnerre, Orgnil Marque-l'âme envoie des champions consulter le chaman dans son campement isolé, avant de frapper un bastion sectaire voisin. Les conseils de Margoz révèlent que le Rocher du Crâne abrite la base souterraine dissimulée de la Lame ardente.",h="Dans le nord de Durotar, Margoz surveille la menace grandissante de la Lame ardente.",kw={"lame ardente","ravin asséché","durotar","margoz","orgnil marque-l'âme","orgrimmar","chaman","rocher du crâne"},ang={["class:Shaman"]="En tant que chaman, vous reconnaissez la sagesse patiente de Margoz dans sa veille aux confins de la nature sauvage. Il perçoit la corruption spirituelle avant qu'elle ne mène à la guerre.",["faction:Horde"]="En tant que membre de la Horde, vous entendez l'avertissement de Margoz : des sectes démoniaques se tapissent à portée d'Orgrimmar.",["race:Orc"]="En tant qu'orc, votre rencontre avec Margoz vous rappelle que le pouvoir gangrené tente encore votre peuple. Il exhorte la nouvelle génération à suivre une voie pure et honorable."},sec={{t="La veille de l'ermite",b="Après avoir découvert l'étendue de la souillure gangrenée aux Falaises du Tonnerre, Orgnil Marque-l'âme comprend que la force seule ne peut purifier Durotar. Il envoie donc des champions consulter Margoz, un chaman orc expérimenté installé dans un campement isolé des rochers au nord-est de Tranchecolline. Entre le Ravin asséché et la mer orientale, Margoz guette les sombres présages dans les terres du nord, souvent ignorés par les guerriers affairés d'Orgrimmar."},{t="La menace du Rocher du Crâne",b="Margoz sait où la Lame ardente a établi son pouvoir dans le nord de Durotar : au Rocher du Crâne, un réseau de cavernes dissimulé dans les falaises, au sud des portes orientales d'Orgrimmar. Les sectateurs sont plus proches de la capitale de Thrall que ne le pensent les gardes du chef de guerre. Les passages secrets pourraient abriter une embuscade démoniaque. Margoz conseille donc ceux qui sont envoyés contre la secte avant qu'ils n'y pénètrent."}},faq={{q="Qui est Margoz ?",a="Margoz est un chaman orc expérimenté, fidèle à la Horde, qui tient un campement isolé dans le nord-est de Durotar. Il étudie la magie noire et surveille la corruption démoniaque qui se répand dans la région.",al={"histoire de margoz","qui est margoz","pnj margoz"}},{q="Où trouver Margoz ?",a="Vous trouverez Margoz dans son campement, dans les collines escarpées du nord-est de Durotar, entre le Ravin asséché et la côte orientale, au sud-est d'Orgrimmar.",al={"emplacement de margoz","trouver margoz","où se trouve margoz"}},{q="Pourquoi Orgnil Marque-l'âme m'envoie-t-il voir Margoz ?",a="Orgnil Marque-l'âme vous envoie voir Margoz, car le chaman a étudié les sectateurs locaux de la Lame ardente. Avant d'attaquer leur bastion, Orgnil veut que vous écoutiez la sagesse spirituelle et les conseils pratiques de Margoz.",al={"pourquoi parler à margoz","orgnil marque-l'âme margoz"}},{q="Qu'est-ce que le Rocher du Crâne ?",a="Le Rocher du Crâne est un réseau de cavernes dissimulées dans la montagne, juste au sud des remparts orientaux d'Orgrimmar. Là, les sectateurs de la Lame ardente vénèrent des démons et accomplissent des rituels près de la capitale de la Horde.",al={"histoire du rocher du crâne","qu'est-ce que le rocher du crâne"}},{q="Que faire après avoir trouvé Margoz ?",a="Quand vous faites votre rapport à Margoz, il reconnaît que vous gagnez en force et vous envoie au Rocher du Crâne pour tuer les sectateurs et récupérer leurs insignes corrompus.",al={"quête suivante après margoz","suite de margoz"}},{q="Margoz fait-il partie de la Lame ardente ?",a="Non. Margoz est un chaman dévoué à la Horde, qui s'emploie à purger l'influence démoniaque et à guider les jeunes champions sur une voie honorable et pure.",al={"margoz est-il maléfique","margoz est-il un sectateur"}}},fp="6,333,16.370.0,24.392.0,14.189.0,23.151.0,43.211.0,19.186.0,34.153.1,36.137.0"}
P.entries["quest:829"] = {n="Neeru Lamefeu",s="À Orgrimmar, Neeru Lamefeu étudie les arts sombres, qu’il affirme pouvoir mettre au service de la Horde. Margoz vous envoie de Durotar avec un Collier brûlant pris à la Lame ardente, dans l’espoir que le démoniste puisse expliquer son pouvoir démoniaque.",h="À Orgrimmar, Neeru Lamefeu étudie les arts sombres, qu’il affirme pouvoir mettre au service de la Horde.",kw={"lame ardente","la faille de l'ombre","durotar","margoz","neeru lamefeu","orgrimmar","collier brûlant","rocher du crâne","démoniste"},ang={["class:Shaman"]="En tant que chaman, vous savez que les éléments ne répondront pas aux artefacts gangrenés. Margoz a atteint les limites de son art et a besoin de l’aide d’un démoniste.",["class:Warlock"]="En tant que démoniste, vous rencontrez Neeru Lamefeu dans la Faille de l’Ombre, le démoniste le plus en vue d’Orgrimmar. Votre art interdit peut servir la Horde.",["faction:Horde"]="En tant que membre de la Horde, vous voyez à Orgrimmar une trêve fragile. Les chamans du chef de guerre comptent parfois sur les parias ombrageux de la Faille de l’Ombre pour protéger Durotar."},sec={{t="Les limites du chaman",b="Margoz a atteint les limites de son art chamanique. Il ne parvient pas à démêler la sorcellerie démoniaque des colliers pris aux sectateurs de la Lame ardente au Rocher du Crâne. Les chamans puisent dans les éléments et les esprits ancestraux. Margoz vous envoie donc consulter un démoniste dans la capitale pour découvrir les pouvoirs des colliers."},{t="Dans la Faille de l’Ombre",b="Sous les falaises rouges d’Orgrimmar se trouve la Faille de l’Ombre. Les démonistes et autres adeptes de la magie interdite y œuvrent sous le regard méfiant de Thrall. Neeru Lamefeu vit dans la caverne et affirme étudier la puissance gangrenée pour contrer les menaces démoniaques. Quand vous lui apportez le collier, sa curiosité oriente l’enquête menée à Durotar vers l’enclave des démonistes."}},faq={{q="Pourquoi Margoz m’envoie-t-il consulter un démoniste ?",a="Margoz est un chaman qui puise dans les éléments et les esprits ancestraux. Les Colliers brûlants du Rocher du Crâne sont imprégnés de magie démoniaque. Il lui faut donc l’aide d’un adepte de la magie gangrenée et des arts sombres pour comprendre leurs enchantements et leur origine.",al={"pourquoi un démoniste","pourquoi neeru","margoz et le démoniste"}},{q="Où trouver Neeru Lamefeu ?",a="Neeru Lamefeu se trouve dans la Faille de l’Ombre, sous Orgrimmar, où se rassemblent démonistes, voleurs et adeptes de la magie de l’ombre.",al={"emplacement de neeru","où se trouve neeru lamefeu","neeru dans la faille de l’ombre"}},{q="Peut-on faire confiance à Neeru Lamefeu ?",a="Margoz doute que les recherches occultes de Neeru soient inoffensives et destinées à combattre les démons, comme il le prétend. Thrall tolère les démonistes à Orgrimmar sous étroite surveillance, mais la fiabilité de Neeru reste incertaine.",al={"neeru est-il maléfique","neeru est-il digne de confiance","puis-je faire confiance à lamefeu"}},{q="Qu’est-ce que le Spécimen de collier ?",a="Le Spécimen de collier est l’un des Colliers brûlants pris aux sectateurs de la Lame ardente au Rocher du Crâne. Margoz vous le confie pour que vous l’apportiez à Neeru Lamefeu afin qu’il l’étudie.",al={"spécimen de collier","qu’est-ce que le collier","objet de quête collier brûlant"}},{q="Que se passe-t-il après avoir remis le collier à Neeru ?",a="Neeru examine le collier de près et vous envoie poursuivre l’enquête sur la présence du culte à Durotar. Les recherches vous mènent vers Ak'Zeloth.",al={"quête suivante après neeru","que fait neeru","suite de la série de quêtes après neeru"}},{q="Pourquoi la Horde autorise-t-elle les démonistes à Orgrimmar ?",a="Thrall autorise les démonistes à Orgrimmar par nécessité. Il les cantonne à la Faille de l’Ombre, où leurs recherches dangereuses peuvent être surveillées, contrôlées et parfois mises à profit pour comprendre les ennemis démoniaques.",al={"pourquoi les démonistes sont-ils autorisés","démonistes dans la faille de l’ombre","thrall et les démonistes"}}},fx={["273c9fa7"]={q="Pourquoi Margoz vous envoie-t-il au lieu d'y aller lui-même ?",a="Margoz reste en poste à l'extérieur de Tranchecolline pour surveiller les troubles spirituels de Durotar. Vous êtes l'aventurier qui a récupéré les colliers brûlants du Rocher du Crâne, prouvant ainsi votre capacité à gérer les artefacts obscurs du culte. Comme il ne peut pas deviner leurs desseins démoniaques par le seul chamanisme, il compte sur vous pour apporter rapidement un échantillon à La Faille.",al={"pourquoi moi margoz","pourquoi m'envoyer à neeru","pourquoi margoz ne va pas à orgrimmar"}}},fp="15,210,17.276.0,24.342.0,37.237.0,33.121.0,31.198.0,27.167.0,46.147.0,47.205.0"}
P.entries["quest:83"] = {n="Articles en lin de qualité",s="Articles en lin de qualité est une tâche de la Forêt d’Elwynn proposée par la couturière Sara Timberlain au Camp de bûcherons du Val d'est. En manque de tissu, elle demande aux aventuriers de passage de traquer les bandits défias locaux et de récupérer leurs bandanas en lin. En échange, elle utilise l'étoffe récupérée pour confectionner des articles utiles pour les voyageurs.",h="Articles en lin de qualité est une tâche de la Forêt d’Elwynn proposée par la couturière Sara Timberlain au...",kw={"toile de jute","confrérie défias","camp de bûcherons du val d'est","forêt d’elwynn","masque rouge en lin","articles en lin de qualité","sara timberlain","couture"},ang={["faction:Alliance"]="Éliminer les bandits défias qui infestent les bosquets d'Elwynn procure non seulement des matériaux de récupération utiles pour le Val d'est, mais affaiblit également l'emprise de la Confrérie sur le cœur du royaume.",["profession:Tailoring"]="L'activité de Sara Timberlain illustre les dures réalités de la couture rurale, où la rareté des rouleaux de tissu contraint les couturières locales à récupérer l'étoffe directement sur le dos des bandits de la région."},sec={{t="Bandits et toile de jute",b="Tandis que les brigands défias de bas niveau qui s'accrochent dans la Vallée de Comté-du-Nord se contentent de masques en toile de jute bon marché, les hors-la-loi organisés qui rôdent dans le reste de la Forêt d’Elwynn arborent de plus fins bandanas en lin cramoisi. Pour les artisans locaux à court de matières premières, ces signes distinctifs de gang représentent une source étonnamment pratique de tissu réutilisable."},{t="Récupération au camp",b="Installée dans le Camp de bûcherons du Val d'est très animé, près de la frontière orientale d'Elwynn, Sara Timberlain est constamment à l'affût de textiles exploitables. En incitant les aventuriers à éclaircir les campements défias dissimulés à travers les bois, elle approvisionne son atelier de couture tout en contribuant à freiner l'avancée éhontée de la Confrérie."}},faq={{q="Qui propose la quête Articles en lin de qualité ?",a="Sara Timberlain, une couturière résidant au Camp de bûcherons du Val d'est, à l'est de la Forêt d’Elwynn, propose cette quête.",al={"qui donne articles rouges en lin","donneur de quete articles rouges en lin","quete sara timberlain"}},{q="Quels objets sont nécessaires pour Articles en lin de qualité ?",a="Vous devez rassembler 6 Bandanas rouges en lin, que l'on peut trouver sur les membres du gang des Défias dispersés à travers la Forêt d’Elwynn.",al={"quoi ramasser pour articles rouges en lin","objets pour articles rouges en lin","bandanas requis"}},{q="Où puis-je trouver des bandits défias dans la Forêt d’Elwynn ?",a="Les hors-la-loi défias occupent de petits campements disséminés dans la Forêt d’Elwynn, notamment autour du Champ de potirons des Brackwell, de La ferme des Champierreux et dans les bois entourant Le Débarcadère de Jerod.",al={"emplacements defias elwynn","ou sont les camps defias","ou trouver des bandanas rouges"}},{q="Pourquoi les Défias d'Elwynn portent-ils du lin au lieu de la toile de jute ?",a="D'après Sara Timberlain, les Défias de bas rang à Comté-du-Nord portent de grossiers masques en toile de jute, tandis que les membres mieux équipés opérant dans le reste d'Elwynn portent du lin rouge, témoignant d'un niveau d'organisation et de ravitaillement supérieur au sein de la Confrérie.",al={"pourquoi du lin rouge","toile de jute vs lin defias","matiere masque defias"}},{q="Pourquoi Sara Timberlain veut-elle des bandanas de bandits ?",a="Sara est à court de tissu pour son commerce de couture. Elle réutilise le lin nettoyable des masques défias pour confectionner des articles pratiques destinés aux bûcherons et aux voyageurs du campement.",al={"pourquoi ramasser des bandanas","que fait sara des masques"}},{q="Où se situe le Camp de bûcherons du Val d'est ?",a="Le Camp de bûcherons du Val d'est se trouve à l'extrême est de la Forêt d’Elwynn, juste au nord de la route principale menant au pont vers Les Carmines.",al={"emplacement val d'est","ou se trouve val d'est","comment trouver sara timberlain"}}},fx={["18a4a024"]={q="À quoi sert le Masque rouge en lin ?",a="Les masques rouges en lin sont portés par les bandits de la Confrérie défias qui rôdent dans toute la Forêt d’Elwynn. Si les gredins du Comté-du-Nord se contentent de toile de jute grossière, les voleurs du reste de la forêt utilisent un tissu de meilleure qualité. Sara Timberlain détricote et retisse ces masques récupérés pour confectionner des vêtements en lin utiles.",al={"à quoi sert le masque rouge en lin","utilisation masque rouge en lin","pourquoi masque rouge en lin"}},["8ac6c8ef"]={q="Pourquoi y a-t-il des bandits défias dans la Forêt d’Elwynn ?",a="La Confrérie défias a établi des camps disséminés dans la Forêt d’Elwynn pour harceler les voyageurs, piller les lignes de ravitaillement et saper l'autorité de Hurlevent. Leur présence croissante menace les établissements locaux comme le Camp de bûcherons du Val d'est, profitant du manque d'effectifs des gardes du royaume pour étendre leurs opérations illégales aux portes de la capitale.",al={"défias à elwynn","pourquoi les défias sont ici","confrérie défias forêt d’elwynn"}},fea06053={q="Pourquoi Sara Timberlain a-t-elle besoin de vous plutôt que des gardes ?",a="Sara Timberlain est une couturière au Camp de bûcherons du Val d'est, pas une soldate, et elle n'a pas les moyens de combattre elle-même les hors-la-loi. Les gardes de Hurlevent et la garnison locale sont déjà débordés par les tentatives de contenir les incursions défias et les raids de gnolls, laissant les humbles artisans dépendre des aventuriers de passage pour obtenir des matériaux et une protection.",al={"pourquoi sara me demande ça","pourquoi pas les gardes d'elwynn","pourquoi timberlain a besoin d'aide"}}},fp="15,169,18.181.0,19.200.0,37.109.0,42.92.0,49.138.0,54.180.0,46.153.0,43.127.0"}
P.entries["quest:830"] = {n="Les ordres de l'amiral",s="Sur la côte de Durotar, les ordres de l’amiral révèlent une menace pour la jeune Horde. Scellés par le défunt grand amiral Daelin Portvaillant, ils montrent que la garnison kultirassienne est organisée et bien retranchée. Gar'Thok, à Tranchecolline, doit savoir ce qu’ils contiennent.",h="Sur la côte de Durotar, les ordres de l’amiral révèlent une menace pour la jeune Horde.",kw={"ordres de l’amiral","vieille enveloppe","daelin portvaillant","gar'thok","kul tiras","lieutenant benedict","tranchecolline","donjon de tiragarde"},ang={["faction:Horde"]="Les ordres de Portvaillant révèlent que la présence de l’Alliance sur les côtes de Durotar relevait d’une campagne d’extermination organisée. La Horde doit défendre avec prudence son nouveau foyer.",["race:Orc"]="Pour les orcs qui bâtissent leur avenir à Durotar, ces documents rappellent la haine de Daelin Portvaillant et la présence de ceux qui cherchent encore à les détruire."},sec={{t="Un héritage scellé",b="Aux étages supérieurs du donjon de Tiragarde, un lourd coffre renferme une vieille enveloppe sous la surveillance du lieutenant Benedict. Le grand amiral Daelin Portvaillant l’a scellée de son blason. Le parchemin contient des ordres navals datant de la sanglante invasion de Durotar par Kul Tiras. Bien que le grand amiral soit tombé à Theramore, ses officiers tiennent toujours leurs fortifications et s’accrochent à leur mission contre la colonie de la Horde."},{t="L’alerte à Tranchecolline",b="Gar'Thok commande la force de défense locale de Tranchecolline. Lorsque vous lui remettez les documents retrouvés, ceux-ci confirment que les soldats kultirassiens de la côte est forment une force établie qui attend des renforts. Ce ne sont pas de simples naufragés. Gar'Thok comprend que la survie de Durotar dépend du démantèlement de la structure de commandement de Tiragarde."}},faq={{q="Où trouve-t-on les ordres de l’amiral ?",a="Les ordres se trouvent dans une vieille enveloppe, à l’intérieur d’un coffre verrouillé au troisième étage du donjon de Tiragarde. Le lieutenant Benedict garde le deuxième étage et porte la clé.",al={"emplacement des ordres","où trouver la vieille enveloppe","trouver les ordres de l’amiral"}},{q="Qui était l’amiral Portvaillant ?",a="Le grand amiral Daelin Portvaillant dirigeait Kul Tiras et commandait la flotte navale de l’Alliance pendant la Seconde guerre. Il refusait de croire que les orcs puissent vivre en paix. Il a donc pris la mer pour Kalimdor afin de mener une guerre d’extermination contre Durotar. Il est mort à Theramore.",al={"qui est l’amiral","histoire de daelin portvaillant","qui a donné les ordres"}},{q="Pourquoi des soldats kultirassiens sont-ils encore au donjon de Tiragarde ?",a="Pendant son invasion de Durotar, Daelin Portvaillant a fait construire des avant-postes côtiers fortifiés comme le donjon de Tiragarde. Après sa défaite, les officiers et les marins survivants, sous le commandement du lieutenant Benedict, ont gardé leurs postes et poursuivi sa campagne contre la Horde.",al={"pourquoi des humains sont-ils à durotar","soldats du donjon de tiragarde","kul tiras à durotar"}},{q="Pourquoi ces ordres préoccupent-ils autant Gar'Thok ?",a="Gar'Thok commande Tranchecolline et défend le centre de Durotar. Les ordres montrent que le donjon de Tiragarde représente une menace militaire active et délibérée pour la patrie des orcs, et qu’il ne s’agit pas d’un groupe de survivants échoués.",al={"réaction de gar'thok","pourquoi gar'thok s'en soucie"}},{q="Qui détient la clé du coffre de l’amiral ?",a="Le lieutenant Benedict, officier kultirassien qui commande au deuxième étage du donjon de Tiragarde, porte la clé du coffre contenant la vieille enveloppe.",al={"clé de benedict","qui donne la clé"}},{q="Que se passe-t-il après avoir remis les ordres à Gar'Thok ?",a="Gar'Thok comprend que les plans de Portvaillant ont été établis avant sa mort et que d’autres de ses hommes pourraient débarquer sur les côtes de Durotar. Il envoie aussitôt les ordres à Orgrimmar pour avertir le conseil du chef de guerre.",al={"suite des ordres de l’amiral","quête suivante"}}},fp="20,262,15.398.0,19.327.1,37.156.0,27.252.0,51.244.0,48.191.0,41.146.0,49.204.0"}
P.entries["quest:831"] = {n="The Admiral's Orders",s="Gar'Thok vous charge de porter les Ordres de l'amiral Portvaillant à Nazgrel, à Orgrimmar. Ces ordres font craindre un nouveau débarquement humain sur les côtes de la Horde.",h="Gar'Thok vous charge de porter les Ordres de l'amiral Portvaillant à Nazgrel, à Orgrimmar.",kw={"amiral portvaillant","gar'thok","horde","débarquement humain","nazgrel","ordres","orgrimmar","thrall"},ang={["faction:Horde"]="En tant que membre de la Horde, vous portez un avertissement que Gar'Thok juge lié à la sécurité des côtes de la Horde."},sec={{t="Un avertissement pour Nazgrel",b="Gar'Thok, à Durotar, craint que les projets de l'amiral Portvaillant menacent encore la Horde. Il vous envoie porter les ordres de l'amiral à Nazgrel, dans la chambre de Thrall à Orgrimmar."},{t="Dans la chambre de Thrall",b="Nazgrel reçoit les ordres et déclare que le chef de guerre doit être informé sans attendre. Il vous remercie d'avoir servi la Horde avec honneur, puis se tourne vers Thrall pour le conseiller."}},faq={{q="Qui m'envoie à Orgrimmar ?",a="Gar'Thok vous envoie de Durotar pour remettre les Ordres de l'amiral Portvaillant à Nazgrel.",al={"qui m'a confié cette mission","ordres de gar'thok"}},{q="À qui remettre les ordres ?",a="Les Ordres de l'amiral Portvaillant doivent être remis à Nazgrel, dans la chambre de Thrall à Orgrimmar.",al={"à qui remettre","ordres pour nazgrel"}},{q="Pourquoi ces ordres sont-ils urgents ?",a="Gar'Thok craint que les projets de l'amiral Portvaillant n'amènent davantage de ses hommes sur les côtes de la Horde.",al={"pourquoi est-ce urgent","menace humaine"}},{q="Que fait Nazgrel de cet avertissement ?",a="Nazgrel dit qu'il doit conseiller Thrall à ce sujet.",al={"que fait nazgrel","conseiller thrall"}}},fp="20,145,21.167.0,19.159.1,26.82.0,30.83.0,26.89.0,38.53.0"}
P.entries["quest:8311"] = {n="Des bonbons de la Sanssaint pour Jesper !",s="Pendant la Sanssaint, Jesper est malade à Hurlevent et rêve de friandises et de divertissements loin de l’orphelinat. Trop malade pour sortir, il demande aux aventuriers de l’Alliance de lui rapporter des douceurs.",h="Pendant la Sanssaint, Jesper est malade à Hurlevent et rêve de friandises et de divertissements loin de...",kw={"darnassus","boule de gomme","sanssaint","forgefer","jesper","massepain","rossignol","nougat","hurlevent","talvash","des friandises ou un sort"},ang={["faction:Alliance"]="Pour l’Alliance, la Sanssaint rapproche des capitales lointaines. Vous traversez les grandes rues de Hurlevent, les salles montagneuses de Forgefer et les frondaisons de Darnassus pour apporter de la joie à un enfant orphelin.",["race:Gnome"]="En tant que gnome, vous avez perdu votre foyer, ravagé par les troggs et les radiations. À Forgefer, Talvash del Kissel fait perdurer la tradition des Boules de gomme de Gnomeregan pendant la fête."},sec={{t="Un enfant à l’abri",b="Pendant la Sanssaint, Jesper est malade à l’orphelinat de Place de la Cathédrale, à Hurlevent. Les autres enfants parcourent Azeroth pour récolter des friandises, mais lui doit rester à l’intérieur. Il espère donc que des aventuriers de passage partageront l’esprit de la fête et lui apporteront des douceurs."},{t="Des tours et des friandises dans l’Alliance",b="Pour apporter à Jesper les friandises dont il rêve, vous voyagez au-delà de la Forêt d’Elwynn. Vous rendez visite aux aubergistes de Hurlevent, de Forgefer et de Darnassus, puis au gnome exilé Talvash del Kissel. Chacun vous demande une petite démonstration avant de vous offrir une friandise. Vous gloussez comme une poule, dansez, montrez vos muscles ou imitez le bruit d’un train, et gagnez des douceurs régionales comme le Nougat de Hurlevent et les Boules de gomme de Gnomeregan."}},faq={{q="Qui est Jesper ?",a="Jesper est un jeune orphelin de l’orphelinat de Hurlevent. Malade pendant la Sanssaint, il rêve de bonbons de fête, mais ne peut pas les récolter lui-même.",al={"jesper hurlevent","orphelin jesper","qui est jesper"}},{q="Pourquoi Jesper ne peut-il pas faire la tournée des friandises lui-même ?",a="Jesper est malade et doit rester à l’intérieur de l’orphelinat pendant que le reste de la ville célèbre la Sanssaint.",al={"pourquoi jesper ne peut pas sortir","jesper est-il malade","tournée des friandises jesper"}},{q="Quelles friandises Jesper veut-il ?",a="Jesper demande quatre douceurs régionales : le Nougat de Hurlevent, Ironforge Mints, le Massepain de Darnassus et les Boules de gomme de Gnomeregan.",al={"friandises jesper","liste des friandises de la sanssaint","bonbons demandés par jesper"}},{q="Où obtenir la Boule de gomme de Gnomeregan ?",a="Talvash del Kissel distribue des Boules de gomme de Gnomeregan dans le quartier mystique de Forgefer.",al={"lieu de la boule de gomme de gnomeregan","qui donne la boule de gomme","bonbons talvash"}},{q="Quels tours les aubergistes vous demandent-ils d’exécuter ?",a="À Hurlevent, les aubergistes vous demandent de montrer vos muscles ; à Darnassus, de danser ; à Forgefer, de glousser comme une poule ; et Talvash vous demande d’imiter le bruit d’un train.",al={"tours de la sanssaint","tours des aubergistes","tours et friandises de l’alliance"}},{q="Que vous donne Jesper en échange des bonbons ?",a="Après avoir reçu les quatre bonbons de fête, Jesper vous offre des friandises à la citrouille qu’il a gardées.",al={"récompense de jesper","finir la quête des friandises de jesper"}}},fx={["103fae29"]={q="Pourquoi Jesper veut-il que les friandises de la Sanssaint soient récoltées ?",a="Jesper est un orphelin malade confiné à l'orphelinat de Hurlevent sous l'œil vigilant de la directrice Nightingale, ce qui l'empêche de participer aux célébrations de la Sanssaint dans les capitales de l'Alliance. Pour vivre la fête comme n'importe quel autre enfant, il espère goûter aux sucreries festives uniques à chaque capitale alliée, et propose d'échanger ses propres friandises à la citrouille pour ne pas être en reste.",al={"pourquoi jesper veut des friandises","motivation bonbons jesper","pourquoi friandises sanssaint jesper"}},["423b280b"]={q="À quoi sert le Nougat de Hurlevent ?",a="Le Nougat de Hurlevent est une confiserie locale traditionnelle distribuée par l'aubergiste du Quartier commerçant pendant la Sanssaint. Il représente la contribution du royaume humain aux friandises de fête que Jesper veut que vous récoltiez pour lui, obtenues en faisant la preuve de votre force auprès de l'aubergiste.",al={"utilisation nougat de hurlevent","qu'est-ce que le nougat de hurlevent","qui veut le nougat de hurlevent"}},["37e1df8a"]={q="À quoi sert la Boule de gomme de Gnomeregan ?",a="La Boule de gomme de Gnomeregan est une sucrerie emblématique distribuée au nom des gnomes exilés par Talvash del Kissel à Forgefer. C'est l'une des quatre sucreries uniques que Jesper vous demande de récolter afin qu'il puisse goûter aux friandises festives de tous les peuples de l'Alliance.",al={"utilisation boule de gomme de gnomeregan","qu'est-ce que la boule de gomme de gnomeregan","qui veut la boule de gomme de gnomeregan"}},e8e502ad={q="À quoi sert le Bonbon à la menthe de Forgefer ?",a="Le Bonbon à la menthe de Forgefer est une confiserie naine offerte par l'aubergiste de Forgefer pendant la fête d'automne. Jesper en a besoin pour compléter sa collection de bonbons de la Sanssaint des quatre villes, qui lui est remise après avoir amusé l'aubergiste avec une imitation de poulet pleine d'entrain.",al={"utilisation bonbon à la menthe de forgefer","qu'est-ce que le bonbon à la menthe de forgefer","qui veut le bonbon à la menthe de forgefer"}},["61787ad3"]={q="À quoi sert le Massepain de Darnassus ?",a="Le Massepain de Darnassus est une exquise confiserie elfe de la nuit distribuée par l'aubergiste de la Terrasse des Artisans à Darnassus. Il complète l'assortiment de délices régionaux de la Sanssaint que Jesper rêve de déguster tout en étant coincé à l'orphelinat de Hurlevent.",al={"utilisation massepain de darnassus","qu'est-ce que le massepain de darnassus","qui veut le massepain de darnassus"}}},fp="31,175,17.236.0,37.367.0,14.135.0,46.101.0,30.117.0,43.90.0,47.135.0,50.92.0"}
P.entries["quest:8312"] = {n="Des bonbons de la Sanssaint pour Spoops !",s="Pour Des bonbons de la Sanssaint pour Spoops !, un enfant malade demande aux voyageurs de rassembler des friandises de fête. Les aubergistes des villes et Kali Remik, au Village de Sen'jin, partagent des friandises, et Spoops offre des bonbons magiques en échange.",h="Pour Des bonbons de la Sanssaint pour Spoops !, un enfant malade demande aux voyageurs de rassembler des...",kw={"bonbons","sanssaint","aubergiste","kali remik","village de sen'jin","spoops","friandises","farce ou friandise"},ang={["faction:Horde"]="En tant que voyageur de la Horde, vous rassemblez des friandises dans les grandes villes et vous rendez au Village de Sen'jin, le village des Sombrelance, pour le compte d'un enfant malade.",["race:Troll"]="En tant que troll Sombrelance, vous pouvez trouver Kali Remik en train de distribuer des friandises de saison au Village de Sen'jin pendant la Sanssaint."},sec={{t="Une Sanssaint alitée",b="Spoops est trop malade pour fêter la Sanssaint dehors. Pendant que les autres célèbrent la fête, Spoops demande aux voyageurs de rassembler des friandises. En échange, Spoops offre des bonbons qui donnent d'étranges formes à ceux qui les mangent."},{t="Farces et friandises dans le royaume",b="Les voyageurs peuvent trouver des friandises de fête dans les villages du royaume. Dans les grandes villes, les aubergistes demandent aux visiteurs de faire des farces avant de partager leurs douceurs. Kali Remik distribue aussi des friandises au Village de Sen'jin, sur la côte de Durotar."}},faq={{q="Qui est Spoops ?",a="Spoops est un jeune malade qui ne peut pas faire la tournée des bonbons pendant la Sanssaint. Pour prendre part à la fête, Spoops demande aux voyageurs de récupérer des friandises de saison auprès des aubergistes et des marchands du monde entier.",al={"qui est spoops","spoops","que fait spoops"}},{q="Pourquoi Spoops ne peut-il pas faire la tournée des bonbons ?",a="Spoops est trop malade pour sortir pendant la Sanssaint. Cloué au lit par la maladie, Spoops compte sur les voyageurs pour rendre visite aux aubergistes des villes et récupérer des friandises de fête.",al={"pourquoi spoops ne fait pas la tournée des bonbons","pourquoi spoops reste à l'intérieur","spoops malade"}},{q="Quels bonbons Spoops offre-t-il en échange ?",a="Spoops offre des bonbons magiques qui métamorphosent ceux qui les mangent. Ils peuvent vous donner des formes à la fois drôles et effrayantes.",al={"quels bonbons spoops donne","bonbons en récompense de spoops","bonbons spéciaux"}},{q="Où trouver les friandises pour Spoops ?",a="Les aubergistes des capitales partagent des bonbons de fête après que les voyageurs ont fait des farces. Kali Remik distribue aussi des douceurs au Village de Sen'jin.",al={"où trouver des bonbons","qui donne des friandises","lieux où trouver des bonbons"}},{q="Qui est Kali Remik ?",a="Kali Remik est un troll du Village de Sen'jin, à Durotar. Pendant la Sanssaint, Kali Remik offre des bonbons de fête aux voyageurs de passage.",al={"qui est kali remik","bonbons de kali remik","bonbons du village de sen'jin"}},{q="Pourquoi les aubergistes demandent-ils des farces ?",a="Pendant la Sanssaint, les aubergistes des grandes villes demandent aux visiteurs de montrer leur esprit festif en faisant une farce ou un geste ridicule avant de partager leurs douceurs.",al={"que veulent les aubergistes","farces des aubergistes","comment obtenir les bonbons des aubergistes"}}},fp="31,209,19.201.0,34.230.0,14.198.0,38.150.0,41.130.0,40.137.0,18.128.0,33.153.0"}
P.entries["quest:832"] = {n="Ombres ardentes",s="Au Rocher du Crâne, l’Oeil de l’ombre ardente transmet les avertissements de la Lame ardente. Sa voix menace Gazz'uz du courroux de Neeru Fireblade.",h="Au Rocher du Crâne, l’Oeil de l’ombre ardente transmet les avertissements de la Lame ardente.",kw={"lame ardente","ombres ardentes","la faille de l'ombre","durotar","oeil de l'ombre ardente","gazz'uz","neeru fireblade","orgrimmar","rocher du crâne"},ang={["class:Warlock"]="En tant que démoniste formé dans la Faille de l’Ombre, vous entendez la Lame ardente invoquer le nom d’un autre adepte. Cette menace montre à quel point la frontière est mince entre l’étude du gangrefeu autorisée par l’État et la haute trahison.",["faction:Horde"]="En tant que membre de la Horde, vous découvrez des murmures entre sectateurs juste au-delà des portes de la capitale. La corruption démoniaque de l’ancienne Horde continue de sévir à proximité inquiétante du cœur de Durotar.",["race:Orc"]="En tant qu’orc, vous savez que la présence de la Lame ardente en Durotar profane votre nouvelle patrie. Les orcs ont combattu aux côtés de Thrall pour purger la souillure de la Légion."},sec={{t="Une voix dans la pierre",b="Après la chute de Gazz'uz au plus profond du Rocher du Crâne, l’Oeil de l’ombre ardente est retrouvé parmi ses restes. La pierre transmet une voix dans l’esprit de quiconque la tient. Le locuteur exige des nouvelles de Gazz'uz. Ses activités secrètes à l’est d’Orgrimmar ont été compromises."},{t="Une menace curieuse",b="La voix donne un ultimatum à Gazz'uz. Qu’il réponde, ou Neeru Fireblade recevra l’ordre de le traquer avec une brutalité expéditive. Neeru vit au grand jour dans la Faille de l’Ombre d’Orgrimmar, où il pratique les arts sombres sous la stricte surveillance de Thrall. Quand le pendentif lui parvient, le démoniste feint la surprise et se demande pourquoi la secte a utilisé son nom pour effrayer Gazz'uz."}},faq={{q="Qu’est-ce que l’Oeil de l’ombre ardente ?",a="L’Oeil de l’ombre ardente est un pendentif enchanté retrouvé parmi les restes de Gazz'uz, chef de la Lame ardente, à l’intérieur du Rocher du Crâne. Il transmet des messages télépathiques dans les deux sens entre les agents de la secte et leurs maîtres invisibles.",al={"oeil de l'ombre ardente","quel est ce pendentif","œil de gazz'uz"}},{q="Qui parle à travers le pendentif ?",a="Un supérieur non identifié de la hiérarchie du Conseil des ombres ou de la Lame ardente tente de contacter Gazz'uz, sans savoir qu’il a déjà été tué au Rocher du Crâne.",al={"qui m’a parlé","voix dans le pendentif","qui parle à travers l’œil"}},{q="Pourquoi la voix menace-t-elle Gazz'uz avec Neeru Fireblade ?",a="La voix dit que Neeru Fireblade s’en prendra à Gazz'uz avec une grande brutalité s’il ne fait pas son rapport. Neeru affirme être connu pour traquer les ennemis du chef de guerre, même s’il trouve étrange que la voix l’ait désigné précisément.",al={"pourquoi mentionner neeru","menace de neeru fireblade","lien avec neeru"}},{q="Où dois-je apporter l’Oeil de l’ombre ardente ?",a="Apportez le pendentif à Neeru Fireblade, dans la Faille de l’Ombre d’Orgrimmar, où il se penche sur des chaudrons et des grimoires.",al={"où remettre les ombres ardentes","où se trouve neeru fireblade"}},{q="Comment Neeru Fireblade réagit-il quand on lui remet l’œil ?",a="Neeru est intrigué que la voix ait mentionné son nom et trouve encore plus étrange que les sectateurs de la Lame ardente portent un nom si proche du sien. Il garde le pendentif pour l’étudier et méditer sur son message.",al={"réaction de neeru","que dit neeru"}},{q="Où se trouve Gazz'uz ?",a="Gazz'uz se terre au point le plus profond du Rocher du Crâne, une caverne dissimulée parmi les escarpements de la côte est de Durotar, juste à l’est d’Orgrimmar.",al={"où se trouve gazz'uz","emplacement de gazz'uz","boss du rocher du crâne"}}},fx={["286b7c01"]={q="Pourquoi la voix dans l'Oeil de l'ombre ardente veut-elle un rapport ?",a="La voix qui chuchote à travers le pendentif tente de contacter Gazz'uz, un chef de la Lame ardente au Rocher du Crâne. La hiérarchie du culte a appris que leur enclave cachée a été découverte par la Horde, et le commandant invisible cherche urgemment à rallier Gazz'uz pour préparer les défenses avant qu'un assaut inévitable n'anéantisse leur bastion.",al={"pourquoi le pendentif parle","pourquoi rapport oeil de l'ombre ardente","mobile voix oeil de l'ombre ardente"}}},fp="15,139,20.260.0,16.347.1,34.212.0,36.152.0,57.213.0,42.109.0,50.205.1,25.137.0"}
P.entries["quest:833"] = {n="Le cimetière sacré",s="Aux Rochers rouges, à l’est de Mulgore, le Gardien du savoir Totem-de-pluie appelle la Horde à protéger les sépultures sacrées. Des quilboars Dos-hirsute ont envahi les tombes des guerriers taurens morts en fondant et en défendant les Pitons-du-Tonnerre.",h="Aux Rochers rouges, à l’est de Mulgore, le Gardien du savoir Totem-de-pluie appelle la Horde à protéger les...",kw={"le cimetière sacré","ancêtres","intrus dos-hirsute","gardien du savoir totem-de-pluie","mulgore","quilboars","rochers rouges","pitons-du-tonnerre"},ang={["class:Shaman"]="En tant que chaman, vous répondez à la profanation de terres sacrées, qui agite les esprits des ancêtres honorés et rend votre intervention nécessaire.",["faction:Horde"]="En tant que membre de la Horde, vous aidez les anciens taurens à protéger leurs monuments sacrés et à respecter la promesse de la Horde de défendre Mulgore aux côtés de ses alliés.",["race:Tauren"]="En tant que tauren, vous contribuez à préserver la tranquillité des Rochers rouges et à honorer les ancêtres qui ont rendu possible l’unité de votre peuple sur sa terre natale."},sec={{t="Terre sacrée des Shu'halo",b="Les Rochers rouges comptent parmi les sanctuaires les plus vénérés de Mulgore, nichés dans les falaises au pied des montagnes orientales. Seuls les Taurens les plus valeureux y sont inhumés. Ces guerriers légendaires ont versé leur sang pour protéger leurs tribus et leurs chefs, et bâtir un foyer durable au sommet des mesas des Pitons-du-Tonnerre. Pour les Shu'halo, troubler leur repos offense à la fois la tradition et la Terre-Mère."},{t="La profanation Dos-hirsute",b="Les quilboars nomades Dos-hirsute contestent depuis longtemps le contrôle des Taurens sur le centre de Kalimdor. Leur récente avancée jusqu’aux Rochers rouges marque une grave escalade. Des bandes d’Intrus dos-hirsute se sont glissées sur ces terres sacrées, ravageant le sol et troublant les lieux de repos. Le Gardien du savoir Totem-de-pluie est trop âgé pour les repousser seul. De jeunes champions de la Horde doivent donc prendre les armes et défendre les défunts honorés."}},faq={{q="Que sont les Rochers rouges ?",a="Les Rochers rouges sont un cimetière ancestral sacré, situé le long des montagnes orientales de Mulgore. Il est réservé aux guerriers taurens les plus valeureux, en particulier à ceux qui sont morts en protégeant leurs tribus et en fondant les Pitons-du-Tonnerre.",al={"où se trouvent les rochers rouges","rochers rouges mulgore","cimetière tauren"}},{q="Qui est le Gardien du savoir Totem-de-pluie ?",a="Le Gardien du savoir Totem-de-pluie est un ancien tauren qui veille sur les Rochers rouges. N’étant plus dans la force de l’âge, il ne peut repousser seul les Dos-hirsute et appelle des aventuriers capables de défendre les défunts.",al={"totem-de-pluie","gardien du savoir totem-de-pluie","qui donne le cimetière sacré"}},{q="Pourquoi les quilboars Dos-hirsute sont-ils aux Rochers rouges ?",a="La tribu Dos-hirsute empiète sur le territoire tauren à travers Mulgore et les Tarides. En quête de territoire et de ressources, des bandes d’intrus ont pénétré dans les falaises des Rochers rouges et profané les tombes.",al={"pourquoi les quilboars sont aux rochers rouges","intrus dos-hirsute","invasion des quilboars"}},{q="Pourquoi cette profanation offense-t-elle tant les Taurens ?",a="Les Taurens honorent leurs ancêtres et cherchent l’équilibre avec les esprits des défunts. Quand les quilboars ravagent la terre et troublent les ossements des héros morts pour les Pitons-du-Tonnerre, l’affront touche profondément leur spiritualité.",al={"rites funéraires taurens","pourquoi les taurens tiennent aux sépultures"}},{q="Où cette quête mène-t-elle ensuite ?",a="Le cimetière sacré est une tâche défensive confiée par le Gardien du savoir Totem-de-pluie. Une fois les Intrus dos-hirsute éliminés, la profanation immédiate prend fin.",al={"suite du cimetière sacré","que faire après le cimetière sacré"}},{q="Qui est enterré aux Rochers rouges ?",a="Les Rochers rouges sont réservés aux champions taurens qui ont combattu pour la survie de leurs tribus et de leurs chefs. Leurs sacrifices ont rendu possibles la fondation et la défense des Pitons-du-Tonnerre.",al={"qui est enterré ici","tombes des rochers rouges"}}},fx={e11b84bd={q="Pourquoi le Gardien du savoir Totem-de-pluie vous le demande-t-il au lieu de les chasser lui-même ?",a="Le Gardien du savoir Totem-de-pluie est un ancien tout simplement trop vieux et au-delà de son apogée pour prendre les armes contre une bande de guerre violente. Chargé de veiller sur les esprits des Rochers rouges et de les honorer plutôt que de se battre sur la ligne de front, il compte sur des voyageurs capables comme vous pour gérer le danger physique que représente le fait de chasser les envahisseurs dos-hérissés.",al={"pourquoi raintotem ne peut pas le faire","pourquoi raintotem a besoin d'aide","pourquoi raintotem ne se bat pas"}}},fp="15,241,31.385.0,27.398.0,18.206.0,28.186.0,46.201.0,51.200.0,32.154.0,27.180.0"}
P.entries["quest:834"] = {n="Des vents dans le désert",s="Rezlak attend à Durotar une caravane de ravitaillement volée. Des harpies Poussièrovent l'ont attaquée dans le Canyon de Tranchevent et ont éparpillé les matériaux de construction parmi les falaises.",h="Rezlak attend à Durotar une caravane de ravitaillement volée.",kw={"caravane","durotar","harpies poussièrovent","gazlowe","orgrimmar","cabestan","canyon de tranchevent","rezlak","fournitures"},ang={["faction:Horde"]="Chaque cargaison perdue au profit des bêtes du canyon menace l'expansion rapide de la Horde et la fortification de son bastion à Durotar.",["profession:Engineering"]="En tant qu'ingénieur, vous comprenez pourquoi Rezlak tient aux plans fiables et aux livraisons ponctuelles, même quand la faune locale pose problème.",["race:Orc"]="En tant qu'orc, vous comptez sur le savoir-faire des gobelins et les fournitures venues d'ailleurs pour faire du sol aride et hostile de Durotar une patrie fortifiée."},sec={{t="Un gobelin pressé par le temps",b="Rezlak est venu de Cabestan sur ordre de l'ingénieur en chef Gazlowe pour aider la Horde à bâtir à travers Durotar. Le terrain aride et hostile rend déjà les travaux de fortification difficiles. Maintenant, les cargaisons disparaissent avant d'atteindre les chantiers, et sans elles, les travaux s'arrêtent. Le superviseur gobelin irritable n'a rien à bâtir."},{t="Embuscade dans le canyon",b="Des harpies Poussièrovent ont attaqué la dernière caravane de ravitaillement dans le Canyon de Tranchevent. Elles nichent dans les ravins élevés qui bordent la route entre Tranchecolline et Orgrimmar, puis fondent sur les chariots de passage. Elles ne mangent ni ne détruisent le fret. Elles entassent plutôt les caisses et les sacs près de leurs nids, où les fournitures attendent quiconque osera traverser leur territoire."}},faq={{q="Qui est Rezlak ?",a="Rezlak est un ouvrier gobelin employé par Gazlowe, le patron de Cabestan. Gazlowe l'a envoyé à Durotar pour aider les orcs à bâtir à l'extérieur des portes d'Orgrimmar.",al={"rezlak","qui est rezlak","qui a donné cette quête"}},{q="Pourquoi les gobelins aident-ils à bâtir à Durotar ?",a="Gazlowe et le Cartel Gentepression ont conclu un partenariat commercial et technique avec le chef de guerre Thrall. Les ingénieurs et les machines gobelins ont aidé à poser les fondations d'Orgrimmar. Gazlowe fournit toujours à la Horde de la main-d'œuvre et des matériaux dans le cadre de contrats.",al={"pourquoi les gobelins aident les orcs","gazlowe à durotar","coopération entre gobelins et horde"}},{q="D'où viennent les fournitures ?",a="Rezlak ne précise pas d'où venait la cargaison. Il dit seulement qu'une caravane transportait des fournitures pour son travail avec les orcs à Durotar.",al={"d'où viennent les fournitures","origine de la caravane"}},{q="Que font les harpies à Durotar ?",a="Les harpies Poussièrovent sont des charognardes agressives et prédatrices qui infestent les falaises et les ravins du centre de Durotar. Elles harcèlent les voyageurs, attaquent le commerce le long du Canyon de Tranchevent et récupèrent tout ce qui brille ou peut servir à leurs nids.",al={"pourquoi des harpies à durotar","histoire des harpies poussièrovent","harpies de tranch event"}},{q="Où se trouve le Canyon de Tranchevent ?",a="Le Canyon de Tranchevent part de la gorge principale au sud, entre Orgrimmar et Tranchecolline. Des ravins entaillent les deux parois, offrant aux harpies Poussièrovent des perchoirs élevés où elles cachent leur butin.",al={"emplacement du canyon de tranchevent","où trouver les fournitures","emplacement des sacs de fournitures"}},{q="Pourquoi les gardes orcs n'ont-ils pas protégé la caravane ?",a="Rezlak dit qu'il est difficile de protéger les caravanes et que cette cargaison devait bénéficier d'un passage sûr. Il ne précise pas quels gardes l'accompagnaient ni pourquoi ils n'ont pas réussi à arrêter les harpies Poussièrovent.",al={"pourquoi la caravane a échoué","sécurité à durotar","caravanes orques"}}},fx={["5ac1923e"]={q="Pourquoi Rezlak veut-il que cela soit fait ?",a="Rezlak a été envoyé directement par Gazlowe pour superviser les travaux d'ingénierie et de construction pour la Horde à Durotar. Sans ces matériaux essentiels, son travail est au point mort, le laissant les mains vides et frustré. Il ne peut pas remplir son contrat ni terminer ses projets assignés tant que la cargaison n'est pas récupérée.",al={"mobile rezlak","pourquoi rezlak a besoin de fournitures","pourquoi rezlak s'en soucie"}},ef031f2c={q="À quoi sert le Sac de ravitaillement ?",a="Ces sacs contiennent des provisions d'ingénierie et de construction destinées aux chantiers de la Horde à travers Durotar. Rezlak et son équipe en ont besoin pour terminer leurs projets de construction pour les orcs, mais le matériel a été dispersé dans le Canyon de Tranchevent lorsque les harpies Tranche-vent ont intercepté la caravane de livraison.",al={"utilisation sac de ravitaillement","que sont les sacs de ravitaillement","sacs de ravitaillement de rezlak"}}},fp="19,156,22.315.0,20.349.0,14.145.0,41.237.0,33.129.0,38.220.0,34.190.0,46.182.0"}
P.entries["quest:835"] = {n="Des lignes sécurisées",s="Près du Canyon de Tranchevent, Rezlak veut sécuriser les routes de ravitaillement gobelines qui traversent Durotar. Dans le Ravin asséché, des harpies interceptent et pillent les caravanes. Il engage donc des aventuriers pour les chasser.",h="Près du Canyon de Tranchevent, Rezlak veut sécuriser les routes de ravitaillement gobelines qui traversent...",kw={"ravin asséché","dustwind savage","dustwind storm witch","gazlowe","cabestan","canyon de tranchevent","rezlak","des lignes sécurisées"},ang={["faction:Horde"]="Éliminer les harpies dans l'est du Canyon de Tranchevent permet aux marchandises et aux renforts de circuler entre les avant-postes frontaliers de Durotar et les ports commerciaux de la côte.",["profession:Engineering"]="Protéger les cargaisons de Rezlak permet aux composants gobelins de Cabestan d'arriver entre les mains des bricoleurs locaux."},sec={{t="Une route infestée de harpies",b="Les harpies Dustwind rendent dangereux les voyages dans les vallées arides de Durotar. Rezlak supervise les opérations de ravitaillement régionales pour son patron, Gazlowe. Depuis leur nid du Ravin asséché, elles attaquent les caravanes dans le Canyon de Tranchevent et s'emparent des cargaisons avant qu'elles n'arrivent à destination."},{t="Commerce et effusion de sang",b="Rezlak pense qu'avec le bon prix, tout est possible. Plutôt que d'entrer lui-même dans le canyon, il engage des aventuriers pour détruire le nid en éliminant les Dustwind Savages et les Dustwind Storm Witches. Chasser les harpies garde les voies commerciales ouvertes et sécurise les cargaisons d'engins d'ingénierie. Cela oriente aussi les voyageurs serviables vers de meilleures occasions à Cabestan."}},faq={{q="Pour qui travaille Rezlak ?",a="Rezlak travaille pour Gazlowe, ingénieur en chef et patron de Cabestan, une ville portuaire gobeline neutre. Gazlowe supervise d'importants projets commerciaux et d'infrastructure dans Durotar et les Tarides.",al={"patron de rezlak","pour qui travaille rezlak","employeur de rezlak"}},{q="Pourquoi les harpies attaquent-elles les caravanes ?",a="Les harpies Dustwind ont leur nid dans le Ravin asséché, qui longe les principales routes de transit du Canyon de Tranchevent. Elles attaquent les intrus et pillent les chariots et les marchandises alentour.",al={"pourquoi les harpies attaquent","motif des harpies dustwind","pourquoi le ravin asséché"}},{q="Où se trouve le Ravin asséché ?",a="Le Ravin asséché se trouve dans les profondeurs de la partie est du Canyon de Tranchevent, au nord de Durotar. Il est creusé dans des collines arides aux teintes cramoisies.",al={"emplacement du ravin asséché","où se trouve le ravin asséché","comment trouver le ravin asséché"}},{q="Que se passe-t-il après avoir aidé Rezlak ?",a="Une fois les harpies Dustwind décimées et la route de ravitaillement sécurisée, Rezlak dirige les aventuriers vers Cabestan, dans les Tarides, de l'autre côté de la frontière. Il les encourage à trouver Gazlowe pour obtenir des contrats plus lucratifs.",al={"après avoir sécurisé les lignes","suite pour rezlak","que faire après rezlak"}},{q="Pourquoi la Horde ne s'occupe-t-elle pas des harpies ?",a="La Horde possède des avant-postes dans Durotar, mais ses ressources sont accaparées par les centaures, les quilboars et les besoins de ses colonies. Les marchands gobelins comme Rezlak trouvent souvent plus rapide et moins coûteux d'engager des aventuriers indépendants pour protéger leurs affaires privées.",al={"pourquoi les gobelins recrutent","pourquoi orgrimmar ne s'en occupe pas","horde et harpies"}},{q="Quels types de harpies vivent dans le Ravin asséché ?",a="Le nid du Ravin asséché abrite des Dustwind Savages sauvages, qui attaquent au corps à corps, et des Dustwind Storm Witches, qui déchaînent le vent et la foudre contre les caravanes qui s'aventurent sur leur territoire.",al={"types de harpies","types de harpies dustwind","ennemis du ravin asséché"}}},fx={bafa495b={q="Pourquoi Rezlak veut-il que les harpies soient éliminées ?",a="Rezlak est responsable d'assurer le mouvement des cargaisons à travers Durotar, mais les harpies Tranche-vent du Ravin asséché ont tendu des embuscades et pillé ses caravanes de ravitaillement. Chaque chariot perdu coûte de l'or, retarde l'arrivée de matériaux vitaux et compromet les expéditions à venir, y compris certains équipements spécialisés qu'il attend personnellement de Cabestan.",al={"mobile rezlak","pourquoi tuer les harpies du ravin asséché","problème de caravane rezlak"}}},fp="18,182,26.278.0,22.363.0,26.191.0,39.168.0,33.125.0,34.209.0,60.259.0,48.172.0"}
P.entries["quest:8353"] = {n="Caqueter pour un bonbon à la menthe",s="À la Sanssaint, Brassefeu l'aubergiste demande aux visiteurs de Forgefer de caqueter pour obtenir un bonbon destiné à Jesper, un jeune orphelin de Hurlevent. Les champions de l'Alliance réunissent des douceurs dans leurs capitales pour lui remonter le moral.",h="À la Sanssaint, Brassefeu l'aubergiste demande aux visiteurs de Forgefer de caqueter pour obtenir un bonbon...",kw={"poulet","caqueter","brassefeu","sanssaint","aubergiste","bonbon à la menthe de forgefer","jesper","friandises"},ang={["faction:Alliance"]="En tant que champion de l'Alliance, vous portez l'hospitalité de Forgefer jusqu'à Hurlevent pour égayer un enfant orphelin.",["race:Dwarf"]="En tant que nain, vous savez que les traditions des fêtes de Forgefer laissent place à la plaisanterie. La demande de Brassefeu montre qu'aucun client ne se prend trop au sérieux."},sec={{t="Une tradition de la Sanssaint",b="Jesper est malade, orphelin à Hurlevent, et rêve de douceurs de la Sanssaint. Les champions de l'Alliance recueillent des friandises pour lui auprès des aubergistes de leurs capitales. Les aventuriers aguerris ont donc une raison de faire du porte-à-porte pendant les festivités qui célèbrent la transition des récoltes à l'hiver."},{t="Le prix de Brassefeu l'aubergiste",b="Brassefeu l'aubergiste garde les Bonbons à la menthe de Forgefer à Stonefire Tavern, dans les Commons de Forgefer. Une demande polie ne suffit pas. Les visiteurs agitent les bras et caquettent comme des poulets avant qu'il ne leur en donne un. Leur numéro fait rire les clients de la taverne, et le bonbon aide à apporter un peu de joie des fêtes à Jesper."}},faq={{q="Pourquoi Brassefeu l'aubergiste veut-il que je caquette comme un poulet ?",a="Brassefeu l'aubergiste vous demande de caqueter, car la Sanssaint appelle les mises en scène amusantes. Les aventuriers aguerris sont trop âgés pour aller quémander des bonbons. Il échange donc un Bonbon à la menthe de Forgefer contre un numéro comique qui fait rire les clients de la taverne.",al={"pourquoi caqueter comme un poulet","pourquoi brassefeu demande de caqueter","pourquoi dois-je caqueter"}},{q="Qui est Jesper et pourquoi est-ce que je lui apporte des bonbons à la menthe ?",a="Jesper est un jeune orphelin malade de Hurlevent qui rêve de douceurs de la Sanssaint. Les champions de l'Alliance recueillent quatre bonbons spéciaux dans les grandes villes de l'Alliance, dont le Bonbon à la menthe de Forgefer à Dun Morogh, pour lui apporter un peu de joie des fêtes.",al={"qui est jesper","pourquoi apporter des bonbons à la menthe","jesper orphelin"}},{q="Quelle est la place de cette quête dans la Sanssaint ?",a="Le Bonbon à la menthe de Forgefer est l'une des quatre friandises régionales réunies pour Jesper pendant la Sanssaint. Les aubergistes de Hurlevent et de Darnassus, ainsi que Talvash del Kissel à Forgefer, demandent aussi un geste théâtral précis avant de céder le bonbon de leur ville.",al={"suite de quêtes de la sanssaint","suite de quêtes des bonbons de jesper","ordre des quêtes"}},{q="Où puis-je trouver Brassefeu l'aubergiste ?",a="Brassefeu l'aubergiste se trouve à Stonefire Tavern, dans les Commons de Forgefer, où il sert à boire et héberge les voyageurs.",al={"où trouver brassefeu","emplacement de brassefeu","aubergiste de forgefer"}},{q="Que reçois-je en caquetant ?",a="Brassefeu l'aubergiste vous donne un Bonbon à la menthe de Forgefer, une friandise des fêtes à rapporter à Hurlevent pour compléter la collection de Jesper pour la Sanssaint.",al={"récompense de quête","qu'est-ce que le bonbon à la menthe","bonbon à la menthe de forgefer"}},{q="Les joueurs de la Horde peuvent-ils accomplir cette tâche ?",a="Non, seuls les champions de l'Alliance peuvent participer. Les aventuriers de la Horde recueillent des friandises pour l'orphelin Spoops auprès des aubergistes d'Orgrimmar, de Fossoyeuse et des Pitons-du-Tonnerre.",al={"quête réservée à l'alliance","quête du poulet de la horde","la horde peut-elle faire cette quête"}}},fp="27,193,24.246.0,26.296.0,60.230.0,49.232.0,56.254.0,36.124.0,31.127.0,37.160.0"}
P.entries["quest:8354"] = {n="Caqueter pour un bonbon à la menthe",s="À la Sanssaint, Norman l'aubergiste de Fossoyeuse offre une friandise aux voyageurs qui aident un enfant malade. Gagnez le Bonbon à la menthe de Fossoyeuse en mettant votre dignité de côté et en vous agitant comme un poulet.",h="À la Sanssaint, Norman l'aubergiste de Fossoyeuse offre une friandise aux voyageurs qui aident un enfant...",kw={"poulet","caqueter","sanssaint","norman l'aubergiste","spoops","quartier des marchands","fossoyeuse","bonbon à la menthe de fossoyeuse"},ang={["faction:Horde"]="À la Sanssaint, les voyageurs de la Horde visitent chaque capitale et supportent d'humiliantes épreuves pour apporter de la joie à un enfant orphelin.",["race:Undead"]="Les rires sont rares dans les couloirs décrépits de Fossoyeuse. La demande saisonnière de Norman offre une étrange parenthèse à la pragmatique nécromantique du quotidien."},sec={{t="Un rare éclat de rire",b="Les rires sont rares à Fossoyeuse, bâtie sous les ruines de Lordaeron par les Réprouvés libérés. Pourtant, à la Sanssaint, même les sinistres habitants du Quartier des Marchands prennent part aux réjouissances. Norman l'aubergiste garde des Bonbons à la menthe de Fossoyeuse pour les voyageurs qui récoltent des friandises pour Spoops, un orphelin malade qui a besoin de réconfort pendant les fêtes."},{t="Gagner la friandise",b="Norman l'aubergiste ne donne pas de friandise aux aventuriers chevronnés sans un spectacle. Il estime que les guerriers et les lanceurs de sorts adultes doivent mériter leurs douceurs. Le quémandeur doit donc imiter un poulet de basse-cour juste devant son comptoir."}},faq={{q="Pourquoi Norman l'aubergiste veut-il que je caquette comme un poulet ?",a="Norman l'aubergiste estime que les champions adultes doivent donner un spectacle avant de partir en quête de friandises. Pour égayer la Sanssaint, il vous demande de battre des ailes et de caqueter comme un poulet avant de vous remettre la friandise.",al={"pourquoi l'emote poulet","pourquoi caqueter pour norman","danse du poulet de norman"}},{q="À qui la friandise est-elle destinée ?",a="Le Bonbon à la menthe de Fossoyeuse est destiné à Spoops, un orphelin malade qui se repose à Orgrimmar et ne peut pas partir en quête de friandises pendant la Sanssaint.",al={"qui reçoit le bonbon à la menthe","à quoi sert le bonbon à la menthe","pourquoi obtenir le bonbon à la menthe de fossoyeuse"}},{q="Où se trouve Norman l'aubergiste ?",a="Norman l'aubergiste tient la taverne centrale du Quartier des Marchands de Fossoyeuse. Il sert les Réprouvés et les voyageurs de la Horde de passage.",al={"emplacement de norman","où se trouve l'aubergiste de fossoyeuse"}},{q="S'agit-il d'une quête de fête saisonnière ?",a="Oui. Elle fait partie de la Sanssaint, une fête annuelle célébrée dans tout Azeroth par la Horde et l'Alliance.",al={"est-ce la sanssaint","quand cette quête est-elle disponible"}},{q="Les Réprouvés célèbrent-ils habituellement la Sanssaint ?",a="Les Réprouvés célèbrent la Sanssaint avec beaucoup d'enthousiasme. Ils brûlent un immense homme d'osier à l'extérieur des ruines de Lordaeron pour honorer leur libération et rompre avec leur ancienne vie de mortels.",al={"sanssaint des réprouvés","fête des morts-vivants"}},{q="Que se passe-t-il après avoir obtenu le Bonbon à la menthe de Fossoyeuse ?",a="Le Bonbon à la menthe de Fossoyeuse rejoint les friandises emblématiques recueillies dans les capitales raciales de la Horde pour composer un cadeau de fête complet destiné au jeune Spoops.",al={"quête suivante","que faire du bonbon à la menthe"}}},fp="27,181,19.303.0,17.222.0,58.201.0,30.121.0,34.130.0,34.105.0,44.183.0,46.129.0"}
P.entries["quest:8355"] = {n="Boule de gomme en approche",s="Talvash del Kissel garde une Boule de gomme de Gnomeregan à Forgefer pour un enfant malade de Hurlevent. Pour l'obtenir, vous devez l'impressionner avec une imitation convaincante de train.",h="Talvash del Kissel garde une Boule de gomme de Gnomeregan à Forgefer pour un enfant malade de Hurlevent.",kw={"boule de gomme de gnomeregan","sanssaint","boule de gomme en approche","forgefer","jesper","talvash del kissel","brikabrok","émote de train"},ang={["faction:Alliance"]="En tant que héros de l'Alliance, vous parcourez les royaumes pour obtenir une boule de gomme de la fête et aider un enfant malade de Hurlevent à profiter des célébrations.",["race:Gnome"]="En tant que gnome de Brikabrok, offrir une Boule de gomme de Gnomeregan pendant la Sanssaint peut rappeler joyeusement votre foyer et l'ingéniosité mécanique de votre peuple déplacé."},sec={{t="Un péage fantaisiste",b="À la Sanssaint, les quêteurs de bonbons visitent les places fortes de l'Alliance pour obtenir des friandises. Dans le Mystic Ward de Forgefer, Talvash del Kissel garde la Boule de gomme de Gnomeregan. Il a de la compassion pour le jeune orphelin qui espère la recevoir. Pourtant, Talvash vous demande d'ajouter une touche de malice à la fête avec une imitation convaincante de train."},{t="Générosité des fêtes",b="Jesper est un orphelin souffrant de Hurlevent qui espère recevoir quatre friandises de toute l'Alliance. Il veut du nougat de Hurlevent, une menthe de Forgefer, du massepain de Darnassus et une boule de gomme de Gnomeregan. Votre imitation de locomotive amuse Talvash et vous permet d'obtenir la boule de gomme. Elle rapproche Jesper de son vœu pour les fêtes."}},faq={{q="Que dois-je faire pour terminer Boule de gomme en approche ?",a="Faites une imitation convaincante de train pour Talvash del Kissel. Dès qu'il entend le bruit, il vous donne la Boule de gomme de Gnomeregan.",al={"comment terminer boule de gomme en approche","objectif de boule de gomme en approche","farce de talvash pour la boule de gomme"}},{q="Qui est Talvash del Kissel ?",a="Talvash del Kissel est un joaillier gnome de Gnomeregan qui vit dans le Mystic Ward de Forgefer. À la Sanssaint, il offre les célèbres boules de gomme de Gnomeregan à l'Alliance.",al={"qui est talvash","histoire de talvash del kissel"}},{q="À quoi sert la Boule de gomme de Gnomeregan ?",a="La Boule de gomme de Gnomeregan est l'une des quatre friandises de la Sanssaint à réunir pour Jesper, un orphelin qui se repose à l'orphelinat de Hurlevent.",al={"utilité de la boule de gomme de gnomeregan","à quoi sert la boule de gomme"}},{q="Où trouver Talvash del Kissel ?",a="Talvash del Kissel se trouve dans le Mystic Ward de Forgefer.",al={"où trouver talvash","emplacement de talvash"}},{q="Pourquoi Talvash vous demande-t-il d'imiter un train ?",a="À la Sanssaint, on fait la tournée des maisons pour quémander des friandises, et Talvash vous demande une farce inoffensive avant de vous donner la sienne. Il veut une imitation de locomotive.",al={"pourquoi imiter un train","pourquoi faire le train pour talvash"}},{q="Cette quête est-elle disponible toute l'année ?",a="Non. Elle n'est disponible que pendant la Sanssaint, la fête annuelle de l'automne.",al={"peut-on faire boule de gomme en approche à tout moment","est-ce une quête saisonnière"}}},fp="16,150,16.308.0,15.323.0,50.116.0,26.176.0,40.135.0,38.61.0,42.143.0,35.75.0"}
P.entries["quest:8356"] = {n="Montrer ses muscles pour du nougat",s="À la Rose dorée, l'Aubergiste Allison vous demande de montrer vos muscles avant de vous donner du Nougat de Hurlevent. Pendant la Sanssaint, vous récoltez des friandises pour Jesper, un orphelin de Hurlevent.",h="À la Rose dorée, l'Aubergiste Allison vous demande de montrer vos muscles avant de vous donner du Nougat de...",kw={"montrer ses muscles pour du nougat","rose dorée","sanssaint","aubergiste allison","jesper","hurlevent","nougat de hurlevent","quête de friandises"},ang={["class:Warrior"]="En tant que guerrier, vous connaissez bien les champs de bataille sanglants. Montrer vos muscles devant une aubergiste est une démonstration de force sans danger, quoique légèrement indigne.",["faction:Alliance"]="Pour l'Alliance, cet échange amusant reflète l'esprit communautaire plus léger de Hurlevent pendant la Sanssaint et les autres fêtes saisonnières. Il rassemble citoyens et héros de passage pour partager un rire.",["race:Human"]="En tant qu'humain à Hurlevent, vous savez que gâter les enfants et échanger des tours contre des friandises est une coutume saisonnière chère à tous. Elle offre un bref répit face aux périls plus sombres qui menacent le royaume."},sec={{t="Une tradition de la Sanssaint",b="La Sanssaint apporte une touche de légèreté à Hurlevent. Cette fête marque le changement de saison et protège des esprits sombres. Le peuple la célèbre avec des déguisements, des réjouissances et la quête de friandises. Les aubergistes de l'Alliance offrent des douceurs traditionnelles à ceux qui accomplissent un tour inoffensif."},{t="Divertir l'aubergiste",b="À la Rose dorée, dans le Quartier commerçant, l'Aubergiste Allison vous demande de faire un numéro avant de vous donner des bonbons de fête. Vous récoltez des friandises pour Jesper, un jeune orphelin. Allison commente votre physique avec malice et vous demande de montrer vos muscles. Vous vous exécutez, et elle vous donne un morceau de Nougat de Hurlevent moelleux."}},faq={{q="Pourquoi l'Aubergiste Allison demande-t-elle aux gens de montrer leurs muscles ?",a="À la Sanssaint, les tours s'échangent contre des friandises. L'Aubergiste Allison vous demande donc de montrer vos muscles avant de vous offrir une douceur.",al={"pourquoi montrer ses muscles pour du nougat","que veut allison","pourquoi l'émote montrer ses muscles"}},{q="Où se déroule cette quête ?",a="Vous retrouvez l'Aubergiste Allison à la Rose dorée, dans le Quartier commerçant de Hurlevent, derrière le comptoir de l'auberge.",al={"où se trouve montrer ses muscles pour du nougat","emplacement d'allison","aubergiste de la rose dorée"}},{q="À qui est destiné le Nougat de Hurlevent ?",a="Le nougat est destiné à Jesper, un jeune orphelin qui séjourne à Hurlevent. Pendant la Sanssaint, il espère goûter aux friandises traditionnelles de chaque grande ville de l'Alliance.",al={"qui reçoit le nougat","qui veut le nougat de hurlevent","friandises de jesper"}},{q="Qu'est-ce que le Nougat de Hurlevent ?",a="Le Nougat de Hurlevent est une douceur régionale que les aubergistes de Hurlevent distribuent pendant la Sanssaint. Les festivaliers le connaissent comme l'une des spécialités du royaume humain.",al={"histoire du nougat de hurlevent","nougat de la sanssaint","friandises de hurlevent"}},{q="Les joueurs de la Horde peuvent-ils obtenir cette friandise auprès d'Allison ?",a="Non. L'Aubergiste Allison réside à Hurlevent, sous le contrôle de l'Alliance, et sert ses membres. Les aventuriers de la Horde accomplissent des tours de fête auprès des aubergistes de leurs propres capitales.",al={"la horde peut-elle montrer ses muscles pour du nougat","version de la horde du nougat"}},{q="Cette quête est-elle disponible toute l'année ?",a="Non. L'Aubergiste Allison ne vous fait cette demande que pendant la Sanssaint, lorsque les coutumes de la quête de friandises animent les villes.",al={"quand montrer ses muscles pour du nougat est-il disponible","cette quête est-elle saisonnière","date de la sanssaint"}}},fp="18,176,24.276.0,26.304.0,44.116.0,33.112.0,38.158.0,25.165.0,49.179.0,34.114.0"}
P.entries["quest:8357"] = {n="Danser pour du massepain",s="À la Sanssaint, les voyageurs de Darnassus récoltent des friandises pour Jesper, un orphelin malade à Hurlevent. Saelienne l'aubergiste perpétue la tradition des farces et friandises : elle demande une danse avant de donner son Massepain de Darnassus.",h="À la Sanssaint, les voyageurs de Darnassus récoltent des friandises pour Jesper, un orphelin malade à...",kw={"danser","darnassus","sanssaint","aubergiste","jesper","massepain","saelienne","teldrassil"},ang={["faction:Alliance"]="Pour l'Alliance, cette coutume de la Sanssaint achemine des friandises depuis le lointain Teldrassil jusqu'à un jeune orphelin de Hurlevent, partagées entre les capitales.",["race:NightElf"]="En tant qu'elfe de la nuit, vous prenez part aux coutumes de la Sanssaint de l'Alliance, où les réjouissances espiègles rencontrent votre mode de vie sylvestre."},sec={{t="Une tradition respectée",b="À la Sanssaint, Darnassus prend un air plus joyeux. C'est la cité forestière sacrée des elfes de la nuit, qui vivent longtemps. Vous venez chercher des friandises pour Jesper, un enfant malade qui se rétablit à Hurlevent. Saelienne l'aubergiste perpétue la coutume de la saison, même pour un enfant dans le besoin. D'abord, elle vous demande une farce."},{t="Le prix du massepain",b="Saelienne vous demande de danser sur le plancher de l'auberge avant de vous donner le Massepain de Darnassus. Votre prestation vous permet d'ajouter cette douceur au colis de la Sanssaint destiné à Jesper."}},faq={{q="À quoi sert la quête Danser pour du massepain ?",a="Vous obtenez du Massepain de Darnassus auprès de Saelienne l'aubergiste, à Darnassus. Cette douceur rejoint les autres friandises de la Sanssaint récoltées pour réconforter Jesper, un orphelin malade à Hurlevent.",al={"pourquoi danser pour du massepain","en quoi consiste cette quête","quête du massepain"}},{q="Qui est Saelienne l'aubergiste ?",a="Saelienne l'aubergiste tient une auberge à Darnassus. Les voyageurs trouvent abri et repos sous les branches de Teldrassil. À la Sanssaint, elle offre des friandises locales à ceux qui prennent part à la tradition.",al={"qui est saelienne","histoire de saelienne"}},{q="Pourquoi Saelienne exige-t-elle une danse ?",a="Saelienne perpétue la tradition des farces et friandises de la Sanssaint. Elle vous demande de danser avant de vous donner une douceur destinée à un enfant malade.",al={"pourquoi danser","pourquoi saelienne veut-elle que je danse"}},{q="Où va le massepain ensuite ?",a="Le Massepain de Darnassus rejoint les friandises de saison des auberges de Forgefer et de Hurlevent, ainsi que celles de Talvash del Kissel, à Forgefer. Toutes ces douceurs doivent apporter la joie de la Sanssaint au jeune Jesper, à Hurlevent.",al={"qui reçoit le massepain","que faire du massepain"}},{q="Qu'est-ce que le Massepain de Darnassus ?",a="Le Massepain de Darnassus est une confiserie sucrée fabriquée dans la capitale des elfes de la nuit. C'est la friandise festive de la ville pour les visiteurs de la Sanssaint.",al={"histoire du massepain de darnassus","de quelle sorte de friandise s'agit-il"}},{q="Les personnages de la Horde peuvent-ils terminer cette quête ?",a="Non. Cette quête est réservée aux personnages de l'Alliance. Darnassus est un bastion de l'Alliance, et le massepain est récolté pour un orphelin de l'Alliance qui se rétablit à Hurlevent.",al={"cette quête est-elle réservée à l'alliance","quête du massepain de la horde"}}},fp="20,206,18.289.0,21.165.0,44.162.0,27.197.0,37.130.0,38.214.0,27.132.0,38.155.0"}
P.entries["quest:8359"] = {n="Montrer ses muscles pour du nougat",s="À Orgrimmar, Gryshka l'aubergiste échange du nougat contre un petit numéro. Pendant la Sanssaint, vous vous musclez pour obtenir une friandise destinée à remonter le moral de Spoops, un enfant alité.",h="À Orgrimmar, Gryshka l'aubergiste échange du nougat contre un petit numéro.",kw={"bonbon","se muscler","gryshka","sanssaint","nougat","orgrimmar","spoops","des farces ou des friandises"},ang={["class:Warrior"]="En tant que Guerrier, vous pouvez être fier de vos exploits dévastateurs sur les lignes de front. Pourtant, prendre la pose comme un artiste de scène pour obtenir des bonbons de fête peut être amusant ou vous rendre humble.",["faction:Horde"]="Même les champions aguerris de la Horde, qui affrontent de dangereux seigneurs de guerre, font gonfler leurs biceps pour les aubergistes afin de réunir des friandises de fête pour les enfants.",["race:Orc"]="En tant qu’Orc, vous êtes mis à l’épreuve pendant la fête quand l’aubergiste d’Orgrimmar vous demande de montrer vos muscles."},sec={{t="Des farces ou des friandises",b="La Sanssaint apporte farces et récolte de friandises dans les capitales d’Azeroth. À l’auberge d’Orgrimmar, Gryshka l’aubergiste garde des douceurs de saison pour ceux qui prennent part à la coutume. Vos voyages vous mènent peut-être face à des dragons et à la sombre sorcellerie, mais ici, le marché est simple : faites une farce ou repartez sans friandise."},{t="Des muscles à exhiber",b="Gryshka l’aubergiste vous demande de montrer la force des Orcs avant de vous donner du Nougat d’Orgrimmar pour le jeune Spoops. Quel que soit votre déguisement ou votre armure, prenez une pose musclée. Même les combattants redoutés de la Horde peuvent amuser le peuple pour quelques bonbons."}},faq={{q="Qui vous demande de vous muscler ?",a="Gryshka l’aubergiste, qui tient la principale auberge de la Vallée de la Force à Orgrimmar, vous demande une farce avant de vous remettre des friandises de saison.",al={"qui donne la quête","gryshka","gryshka l'aubergiste"}},{q="Pourquoi faut-il se muscler pour avoir des bonbons ?",a="La coutume de la Sanssaint demande une petite farce en échange d’une friandise. Gryshka vous taquine en vous demandant de montrer votre force physique avant de vous donner des bonbons.",al={"pourquoi se muscler","quelle est la farce","condition pour le nougat"}},{q="À quoi sert le Nougat d’Orgrimmar ?",a="Ce nougat est l’une des quatre friandises réunies dans les capitales de la Horde pour remonter le moral de Spoops, un jeune orphelin malade et alité, incapable de faire la tournée des bonbons seul.",al={"pourquoi me faut-il du nougat","utilité du nougat","bonbons pour spoops"}},{q="Où se trouve Gryshka l’aubergiste ?",a="Gryshka l’aubergiste tient le comptoir de la principale auberge de la Vallée de la Force à Orgrimmar. Elle y sert les voyageurs fatigués et les habitants du coin.",al={"où se trouve gryshka","emplacement de l’aubergiste d’orgrimmar"}},{q="Tous les membres de la Horde peuvent-ils participer ?",a="Oui. Tous les membres de la Horde peuvent rendre visite à Gryshka l’aubergiste pendant la Sanssaint, prendre une pose et réclamer la friandise de saison.",al={"qui peut se muscler","restrictions de faction","réservé à la horde"}},{q="De quelle fête s’agit-il ?",a="Cela fait partie de la Sanssaint, une fête automnale qui marque la fin des récoltes et défie la mortalité avec des costumes, des farces et des friandises.",al={"quel événement","quelle fête","quête de la sanssaint"}}},fp="18,148,17.282.0,17.237.0,27.143.0,32.161.0,38.159.0,36.131.0,41.122.0,31.136.0"}
P.entries["quest:836"] = {n="À la rescousse de OOX-09/HL !",s="Au-delà de la falaise du Surplomb, OOX-09/HL a besoin d'aide pour atteindre le rivage. Oglethorpe Obnoticus parle depuis le robot tombé et vous demande de l'escorter jusque-là. Il vous attend ensuite à Baie-du-Butin.",h="Au-delà de la falaise du Surplomb, OOX-09/HL a besoin d'aide pour atteindre le rivage.",kw={"baie-du-butin","camouflage","robot d'orientation","oglethorpe obnoticus","overlook cliff","oox-09/hl"},sec={{t="En route vers le rivage",b="La voix d'Oglethorpe crépite à nouveau depuis le robot. OOX-09/HL a besoin d'un endroit dégagé et sûr pour sa longue procédure de décollage, et le rivage au-delà de la falaise du Surplomb fera l'affaire. Son camouflage intégré ne peut pas encore être utilisé. Oglethorpe a besoin de temps pour le réparer."},{t="Des nouvelles à Baie-du-Butin",b="Quand OOX-09/HL atteint le rivage en toute sécurité, Oglethorpe Obnoticus vous demande de venir lui parler à Baie-du-Butin."}},faq={{q="Où faut-il escorter le robot ?",a="Emmenez OOX-09/HL sur le rivage au-delà de la falaise du Surplomb. Il aura là-bas la place nécessaire pour entamer son décollage.",al={"où doit aller oox-09","destination de l'escorte du poulet des hinterlands","rivage d'overlook cliff"}},{q="Qui a créé ce robot d'orientation ?",a="Le gnome Oglethorpe Obnoticus a créé le robot. Il se trouve à Baie-du-Butin.",al={"qui a fabriqué oox-09","créateur d'oox","qui a construit le poulet"}},{q="Pourquoi le robot ne peut-il pas simplement décoller là où il a été trouvé ?",a="La longue procédure de décollage nécessite un endroit dégagé et sûr. Oglethorpe a aussi besoin de temps pour réparer le camouflage du robot.",al={"pourquoi le poulet marche","pourquoi escorter oox-09"}},{q="Où aller une fois l'escorte arrivée au rivage ?",a="Une fois OOX-09/HL arrivé sain et sauf sur le rivage, Oglethorpe Obnoticus vous demande de le retrouver à Baie-du-Butin.",al={"où rendre la quête à la rescousse d'oox-09","à qui faire mon rapport","emplacement d'oglethorpe"}},{q="Quelle quête précède cette escorte ?",a="Cette quête suit Find OOX-09/HL!, où vous avez apporté la balise de détresse au robot écrasé.",al={"quête précédente d'oox-09","prérequis de la quête à la rescousse d'oox-09"}}},fp="17,187,19.257.0,17.102.0,41.96.0,50.69.0,55.115.0,50.94.0,29.88.0"}
P.entries["quest:8360"] = {n="Danser pour du massepain",s="Pendant la Sanssaint, Pala l'aubergiste demande aux visiteurs de danser pour obtenir du Massepain des Pitons du Tonnerre. Cette friandise est destinée à un orphelin malade, et cette coutume apporte la joie des fêtes sur les hautes mesas de Mulgore.",h="Pendant la Sanssaint, Pala l'aubergiste demande aux visiteurs de danser pour obtenir du Massepain des Pitons...",kw={"danser pour du massepain","sanssaint","pala l'aubergiste","massepain","mulgore","pitons-du-tonnerre","des bonbons ou un sort"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez partager un moment de légèreté au milieu des luttes quotidiennes de votre faction et apporter de la joie à un orphelin pendant votre voyage entre les capitales.",["race:Tauren"]="En tant que taurène, vous pouvez trouver Pala l'aubergiste qui répand la joie de la fête à Mulgore avec une danse pour une bonne cause."},sec={{t="Une danse sur les hauteurs",b="Pendant la Sanssaint, Pala l'aubergiste perpétue la coutume du « des bonbons ou un sort » à Pitons-du-Tonnerre. Vous venez chercher une friandise pour un enfant malade, mais Pala vous demande d'abord une danse festive. Elle vous donne ensuite du Massepain des Pitons du Tonnerre."},{t="Des tours contre des friandises",b="Pour Pala, la coutume est simple. Avancez et dansez pour gagner une friandise. Une fois que vous l'avez divertie, elle vous donne le massepain et adresse ses vœux chaleureux au jeune malade qui l'attend."}},faq={{q="À quoi sert la quête Danser pour du massepain ?",a="Vous dansez pour Pala l'aubergiste à Pitons-du-Tonnerre et recevez un morceau de Massepain des Pitons du Tonnerre. Il rejoint les friandises réunies pour un orphelin malade pendant la Sanssaint.",al={"pourquoi danser pour du massepain","but de la quête du massepain","objectif de danser pour du massepain"}},{q="Qui donne cette quête ?",a="Pala l'aubergiste, une aubergiste taurène qui accueille les visiteurs et les habitants de Pitons-du-Tonnerre, vous propose cette danse pendant la Sanssaint.",al={"qui donne danser pour du massepain","quête de pala","pala l'aubergiste à pitons-du-tonnerre"}},{q="Pourquoi Pala insiste-t-elle pour que vous dansiez si le bonbon est destiné à un enfant malade ?",a="Pala respecte la coutume du « des bonbons ou un sort » : vous exécutez un tour pour gagner une friandise. Cette danse contribue à la joie et à l'animation de la Sanssaint.",al={"pourquoi dois-je danser","pourquoi pala veut-elle une danse"}},{q="Quelle récompense recevez-vous en dansant ?",a="Vous recevez un morceau de Massepain des Pitons du Tonnerre, une friandise festive locale qui vient compléter la collection de friandises de la Sanssaint destinée à l'enfant malade.",al={"récompense en massepain","objet danser pour du massepain"}},{q="Les joueurs de l'Alliance peuvent-ils accomplir cette quête ?",a="Non. Pala l'aubergiste vit à Pitons-du-Tonnerre ; seuls les membres de la Horde peuvent lui rendre visite pour cette étape de la tournée des friandises.",al={"quête réservée à la horde","danser pour du massepain alliance"}},{q="Quand cette quête est-elle disponible ?",a="Elle est disponible pendant la Sanssaint, la fête automnale annuelle durant laquelle les aubergistes d'Azeroth proposent des friandises spéciales et des jeux festifs.",al={"quand obtenir du massepain","quête de massepain de la sanssaint"}}},fp="20,185,20.215.0,17.180.0,44.168.0,21.123.0,65.123.0,39.138.0,41.125.0,29.133.0"}
P.entries["quest:837"] = {n="Empiètement",s="À Tranchecolline, au centre de Durotar, Gar'Thok vous envoie vers l'ouest attaquer les camps des Razormane. Leurs tanières fortifiées menacent toujours le jeune territoire orc.",h="À Tranchecolline, au centre de Durotar, Gar'Thok vous envoie vers l'ouest attaquer les camps des Razormane.",kw={"ronces","durotar","empiètement","gar'thok","quilboars","tranchecolline","razormane"},ang={["faction:Horde"]="En tant que membre de la Horde, vous devez sécuriser Durotar face aux quilboars Razormane autochtones afin d'établir un territoire sûr et durable.",["race:Orc"]="En tant qu'orc, vous revendiquez Durotar comme votre nouveau territoire. Les tanières de ronces des Razormane menacent toujours vos colonies."},sec={{t="Une épine dans le flanc de Durotar",b="Quand Thrall mena les orcs en Kalimdor et fonda Durotar, les Razormane parcouraient déjà une grande partie de ces terres rudes et arides. Ces quilboars agressifs aux allures de sangliers devinrent une menace constante pour la nouvelle colonie. La Horde les repoussa en grande partie au terme d'efforts militaires soutenus. Pourtant, des poches fortifiées subsistent dans des redoutes épineuses à l'ouest de Tranchecolline."},{t="L'offensive de Gar'Thok",b="Gar'Thok, un officier de Tranchecolline, dirige l'opération visant à éliminer les Razormane restants. Il envoie des défenseurs chevronnés dans les camps de ronces de l'ouest pour tuer leurs éclaireurs, leurs guerriers et leurs dustrunners. Gar'Thok et les dirigeants de la Horde craignent que tout point d'ancrage quilboar près de Tranchecolline ne tourne au désastre. Ils voient cette attaque comme une première étape pour sécuriser Kalimdor."},{t="Défricher les ronces",b="Une fois les défenseurs quilboars éliminés, les forces de la Horde peuvent brûler les tanières de ronces et empêcher les Razormane de reprendre les contreforts occidentaux. Le feu détruit une menace persistante et sécurise le périmètre ouest de Durotar. Il protège aussi les routes de ravitaillement vitales entre Tranchecolline et le reste du royaume."}},faq={{q="Qui donne la quête Empiètement ?",a="Gar'Thok, un officier orc en poste à Tranchecolline, au centre de Durotar, donne l'ordre.",al={"qui donne empiètement","où trouver empiètement","donneur de quête empiètement"}},{q="Pourquoi la Horde combat-elle les quilboars Razormane à Durotar ?",a="À l'arrivée des orcs à Durotar, les quilboars Razormane occupaient une grande partie de la région. La Horde les repoussa en grande partie, mais des poches fortifiées subsistent à l'ouest de Tranchecolline et menacent la sécurité du nouveau territoire orc.",al={"pourquoi combattre les quilboars à durotar","pourquoi attaquer les razormane","conflit avec les quilboars à durotar"}},{q="Où se trouvent les camps des Razormane ?",a="Les camps des Razormane se trouvent à l'ouest de Tranchecolline, parmi d'épais enchevêtrements de ronces épineuses.",al={"où sont les camps quilboars","comment trouver les camps razormane","lieu d'empiètement"}},{q="Qui sont les Razormane ?",a="Les Razormane sont une tribu hostile de quilboars originaire des plaines arides de Kalimdor. Ils bâtissent des tanières fortifiées dans les ronces et résistent farouchement à l'installation de la Horde à Durotar et dans les Tarides.",al={"qui sont les razormane","histoire des razormane","que sont les razormane"}},{q="Que se passe-t-il une fois les quilboars vaincus ?",a="Après la défaite des quilboars, Gar'Thok donne l'ordre de brûler les ronces et les structures dégagées. Cela renforce le contrôle de la Horde sur la région et sécurise les frontières de Durotar.",al={"que se passe-t-il après empiètement","rendre la quête empiètement","sort des camps quilboars"}},{q="Quel est le rôle de Tranchecolline dans ce conflit ?",a="Tranchecolline est une colonie orc fortifiée au centre de Durotar. C'est un centre militaire et logistique entre la Vallée des épreuves et Orgrimmar.",al={"où se trouve tranchecolline","qu'est-ce que tranchecolline"}}},fp="12,142,25.351.0,20.359.0,21.296.0,33.85.0,60.213.0,38.83.0,22.184.0,44.173.0,43.140.0"}
P.entries["quest:8370"] = {n="Conquering Arathi Basin",s="Un porte-guerre de la Horde vous demande d’apporter trois Arathi Basin Marks of Honor. Ces marques sont les jetons requis pour cette demande.",h="Un porte-guerre de la Horde vous demande d’apporter trois Arathi Basin Marks of Honor.",kw={"bassin arathi","champ de bataille","conquête du bassin arathi","porte-guerre de la horde","marque d’honneur"},faq={{q="Que vous demande le porte-guerre de la Horde ?",a="Le porte-guerre de la Horde vous demande d’apporter trois Arathi Basin Marks of Honor.",al={"ce qu’il me faut","demande du porte-guerre"}},{q="Où dois-je apporter les marques ?",a="Apportez les marques à un porte-guerre de la Horde, à l’extérieur des champs de bataille.",al={"où remettre","emplacement du porte-guerre"}},{q="Combien de marques d’honneur faut-il ?",a="Il vous faut trois Arathi Basin Marks of Honor.",al={"nombre de marques","trois marques"}}},fp="23,118,39.73.0,27.64.0,35.43.0"}
P.entries["quest:8372"] = {n="Fight for Warsong Gulch",s="Un général de brigade de l’Alliance vous demande de lui apporter des marques d’honneur du Goulet des Chanteguerres. Elles sont nécessaires hors des champs de bataille.",h="Un général de brigade de l’Alliance vous demande de lui apporter des marques d’honneur du Goulet des...",kw={"alliance","champs de bataille","général de brigade","marques d’honneur","goulet des chanteguerres"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez apporter les marques d’honneur du Goulet des Chanteguerres à un général de brigade de l’Alliance."},sec={{t="Les marques",b="Après avoir combattu dans le Goulet des Chanteguerres, vous pouvez apporter trois marques d’honneur à un général de brigade de l’Alliance, hors des champs de bataille. Le général demande ces marques, et vous savez ce qu’il faut lui apporter."}},faq={{q="Que demande le général de brigade ?",a="Un général de brigade de l’Alliance vous demande de lui apporter trois marques d’honneur du Goulet des Chanteguerres.",al={"quelles marques sont demandées","demande du général de brigade"}},{q="Où apporter les marques ?",a="Apportez les marques à un général de brigade de l’Alliance, hors des champs de bataille.",al={"où remettre les marques","où se trouve le général"}},{q="Combien de marques d’honneur faut-il ?",a="Le général demande trois marques d’honneur du Goulet des Chanteguerres.",al={"combien de marques","nombre de marques d’honneur"}}},fp="23,125,9.202.0,37.83.0,27.75.0,35.56.0"}
P.entries["quest:8373"] = {n="La puissance du pin",s="À la Sanssaint, le sergent Hartman vous charge de nettoyer Austrivage des bombes puantes des Réprouvés.",h="À la Sanssaint, le sergent Hartman vous charge de nettoyer Austrivage des bombes puantes des Réprouvés.",kw={"réprouvés","sanssaint","nettoyeur au pin","sergent hartman","austrivage","nettoyeur de boules puantes","bombes puantes"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez aider le sergent Hartman à débarrasser Austrivage des bombes puantes des Réprouvés."},sec={{t="La puanteur d’Austrivage",b="Pendant la Sanssaint, les Réprouvés souillent Austrivage avec des bombes puantes. Ces bombes gâchent la célébration de la libération. Le sergent Hartman vous demande d’éliminer celles qui ont atterri dans le village à l’aide d’un Nettoyeur de boules puantes."}},faq={{q="Qui vous demande de ramasser les bombes puantes ?",a="Le sergent Hartman vous demande de débarrasser Austrivage des bombes puantes des Réprouvés.",al={"qui me l’a donné","sergent hartman"}},{q="Où se trouvent les bombes puantes ?",a="Les bombes puantes se trouvent à Austrivage.",al={"emplacement des bombes puantes","où nettoyer"}},{q="Qui utilise des bombes puantes contre Austrivage ?",a="Les Réprouvés utilisent des bombes puantes contre Austrivage pendant la Sanssaint.",al={"qui utilise les bombes puantes","bombes des réprouvés"}},{q="À quoi sert le nettoyeur ?",a="Le Nettoyeur de boules puantes utilise du pin pour combattre les mauvaises odeurs.",al={"nettoyeur au pin","nettoyeur de boules puantes"}},{q="Pourquoi nettoie-t-on Austrivage ?",a="Les bombes puantes des Réprouvés empestent la célébration de la Sanssaint à Austrivage.",al={"pourquoi nettoyer austrivage","puanteur de la sanssaint"}}},fp="17,148,20.213.0,40.74.0,26.34.0,35.65.0,25.54.0,32.93.0"}
P.entries["quest:8374"] = {n="Claiming Arathi Basin",s="Un général de brigade de l’Alliance, près du Bassin Arathi, vous demande trois Arathi Basin Marks of Honor.",h="Un général de brigade de l’Alliance, près du Bassin Arathi, vous demande trois Arathi Basin Marks of Honor.",kw={"alliance","général de brigade de l’alliance","bassin arathi","conquête du bassin arathi","marques d’honneur"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous devez apporter trois Arathi Basin Marks of Honor à un général de brigade de l’Alliance."},faq={{q="Qui demande les marques ?",a="Un général de brigade de l’Alliance, près des champs de bataille, vous demande trois Arathi Basin Marks of Honor.",al={"qui veut les marques","général de brigade"}},{q="Combien de marques d’honneur faut-il ?",a="Le général vous demande trois Arathi Basin Marks of Honor.",al={"combien de marques","trois marques"}},{q="Où apporter les marques ?",a="Apportez les marques à un général de brigade de l’Alliance, près des champs de bataille.",al={"où apporter les marques","remettre les marques"}}},fp="21,153,23.108.0,35.64.0,27.75.0"}
P.entries["quest:8386"] = {n="La lutte pour le goulet des Warsong",s="Un appel à combattre pour le Goulet des Chanteguerres aide à préserver les défenses naturelles d’Orneval. Vos efforts les maintiennent intactes un jour de plus.",h="Un appel à combattre pour le Goulet des Chanteguerres aide à préserver les défenses naturelles d’Orneval.",kw={"orneval","défenses","combattre pour le goulet des chanteguerres","défenses naturelles","goulet des chanteguerres"},sec={{t="Les défenses d’Orneval",b="En Orneval, on vous demande de combattre pour le Goulet des Chanteguerres. Votre travail aide à maintenir les défenses naturelles de la région intactes un jour de plus."}},faq={{q="Pourquoi combattre pour le Goulet des Chanteguerres ?",a="Vos efforts aident à préserver les défenses naturelles d’Orneval un jour de plus.",al={"combat au goulet des chanteguerres","pourquoi les chanteguerres"}},{q="Qu’est-ce que cela aide à protéger ?",a="Le combat aide à maintenir les défenses naturelles d’Orneval intactes un jour de plus.",al={"quelles défenses","protection d’orneval"}},{q="Où se trouve le Goulet des Chanteguerres ?",a="Le Goulet des Chanteguerres est le champ de bataille qui forme une barrière naturelle entre Orneval et les Tarides.",al={"emplacement des chanteguerres","où se trouve le goulet des chanteguerres"}}},fp="23,125,20.128.0,28.72.0,28.73.0,23.96.0"}
P.entries["quest:8389"] = {n="Battle of Warsong Gulch",s="La Horde vous demande de l’aider à garantir sa possession du Goulet des Chanteguerres. Votre aide compte pour sa revendication sur ces terres.",h="La Horde vous demande de l’aider à garantir sa possession du Goulet des Chanteguerres.",kw={"bataille","revendication","horde","possession","goulet des chanteguerres"},ang={["faction:Horde"]="En tant que membre de la Horde, votre aide contribue à garantir qu’elle conserve le Goulet des Chanteguerres."},sec={{t="Revendication de la Horde",b="La revendication de la Horde sur le Goulet des Chanteguerres appelle votre aide. En l’aidant, vous soutenez sa possession du goulet."}},faq={{q="Que veut la Horde ici ?",a="La Horde cherche à garantir sa possession du Goulet des Chanteguerres.",al={"horde goulet des chanteguerres","revendication de la horde","qui possède le goulet des chanteguerres"}},{q="Comment puis-je aider ?",a="Votre aide contribue à garantir que le Goulet des Chanteguerres reste à la Horde.",al={"aider la horde","que fais-je","bataille du goulet des chanteguerres"}},{q="Pourquoi la Horde veut-elle le Goulet des Chanteguerres ?",a="Le récit disponible indique que la Horde cherche à garantir sa possession du Goulet des Chanteguerres.",al={"pourquoi le goulet des chanteguerres","pourquoi la horde le veut","raison du goulet des chanteguerres"}}},fp="23,112,11.116.0,30.57.0,15.63.0,38.84.0"}
P.entries["quest:8393"] = {n="Claiming Arathi Basin",s="Un général de brigade de l’Alliance, à l’extérieur du Bassin Arathi, vous demande d’apporter trois Arathi Basin Marks of Honor. Ce sont les seuls objets nommés dans cette demande.",h="Un général de brigade de l’Alliance, à l’extérieur du Bassin Arathi, vous demande d’apporter trois Arathi...",kw={"alliance","bassin arathi","général de brigade","revendiquer le bassin arathi","marques d’honneur"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous devez apporter trois Arathi Basin Marks of Honor à un général de brigade de l’Alliance."},faq={{q="Que vous demande le général de brigade ?",a="Le général de brigade de l’Alliance vous demande d’apporter trois Arathi Basin Marks of Honor.",al={"marques d’arathi","trois marques","que dois-je apporter"}},{q="Où dois-je apporter les marques ?",a="Apportez les marques à un général de brigade de l’Alliance, à l’extérieur des champs de bataille.",al={"où remettre","emplacement du général de brigade","où livrer les marques"}},{q="Qui demande les marques ?",a="Un général de brigade de l’Alliance, à l’extérieur des champs de bataille, demande les marques.",al={"qui les veut","général d’arathi","qui donne ça"}}},fp="21,155,40.83.0,27.75.0,28.75.0"}
P.entries["quest:8399"] = {n="Fight for Warsong Gulch",s="Un général de brigade de l’Alliance, posté à l’extérieur des champs de bataille, vous demande d’apporter trois Marks of Honor. Ces marques sont nécessaires pour répondre à l’appel au combat.",h="Un général de brigade de l’Alliance, posté à l’extérieur des champs de bataille, vous demande d’apporter...",kw={"alliance","général de brigade","combat","marks of honor","goulet des chanteguerres"},ang={["faction:Alliance"]="En tant que combattant de l’Alliance, vous devez apporter des Marks of Honor à un général de brigade de l’Alliance, posté à l’extérieur des champs de bataille."},sec={{t="La demande du général de brigade",b="Le général de brigade de l’Alliance, à l’extérieur des champs de bataille, recherche les Marks of Honor du Goulet des Chanteguerres. Apportez-lui trois Marks of Honor, et votre combat pour le Goulet des Chanteguerres pourra être compté parmi les efforts de l’Alliance."}},faq={{q="Que veut le général de brigade de l’Alliance ?",a="Un général de brigade de l’Alliance, posté à l’extérieur des champs de bataille, vous demande d’apporter trois Marks of Honor.",al={"marques du général de brigade","quelles marques me faut-il"}},{q="Où apporter les Marks of Honor ?",a="Apportez les Marks of Honor à un général de brigade de l’Alliance, à l’extérieur des champs de bataille.",al={"où rendre les marques","lieu des marques de chanteguerre"}},{q="Combien de Marks of Honor faut-il ?",a="Il vous faut trois Marks of Honor du Goulet des Chanteguerres.",al={"combien de marques","trois marques"}}},fp="23,151,23.219.0,46.96.0,36.84.0,35.44.0"}
P.entries["quest:84"] = {n="Revenir voir Billy",s="Bernice Champierreux vous envoie de l’autre côté de la route avec une tourte de panse de porc pour Billy Maclure. Il sait quelque chose sur son collier disparu, et cette livraison ravive la querelle entre leurs familles au centre de la Forêt d’Elwynn.",h="Bernice Champierreux vous envoie de l’autre côté de la route avec une tourte de panse de porc pour Billy...",kw={"revenir voir billy","bernice champierreux","billy maclure","forêt d’elwynn","les vignes des maclure","tourte de panse de porc","la ferme des champierreux","collier des champierreux"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous découvrez des querelles entre fermes humaines jusque dans la paisible Forêt d’Elwynn. Aider les gens du coin implique souvent de composer avec ces disputes.",["profession:Cooking"]="En tant que cuisinier, vous connaissez la tourte de panse de porc, un plat réconfortant des fermes d’Elwynn, préparé avec la viande des sangliers sauvages qui parcourent la forêt."},sec={{t="Une tourte amère",b="La querelle entre les Champierreux et les Maclure laisse peu de place à la gentillesse. Tatie Bernice Champierreux a préparé une tourte de panse de porc, car Billy Maclure refusait de révéler ce qu’il savait sur l’héritage familial sans en recevoir une. Elle vous tend la tourte avec une irritation manifeste. Bernice espère que Billy s’étouffera à chaque bouchée."},{t="Le pot-de-vin d’un garçon",b="Aux Vignes des Maclure, de l’autre côté de la route, Billy Maclure attend, affamé, et ne se rappelle plus ce qui est arrivé au collier. La rivalité entre les deux fermes touche aussi leurs enfants. Ils échangent des ragots et des bibelots volés contre des friandises de la ferme. Une fois la tourte livrée, Billy se souvient, et la recherche du véritable emplacement du collier peut commencer."}},faq={{q="À quoi sert cette livraison ?",a="Billy Maclure affirme savoir où se trouve le collier perdu de Tatie Bernice Champierreux, mais refuse de parler avant que vous lui apportiez une tourte de panse de porc faite maison. La livraison répond à sa demande, et il révélera où le bijou de famille a échoué.",al={"pourquoi livrer une tourte","que veut billy","objectif de revenir voir billy"}},{q="Pourquoi Tatie Bernice est-elle si fâchée contre Billy ?",a="Les familles Champierreux et Maclure sont prises dans une âpre querelle de campagne depuis des années. Bernice supporte mal de préparer une friandise pour un garnement Maclure afin de récupérer un bijou de famille disparu près de leurs terres.",al={"pourquoi bernice déteste billy","querelle champierreux maclure","pourquoi lui souhaiter de s’étouffer"}},{q="Où Billy dit-il que se trouve vraiment le collier ?",a="Après avoir mangé la tourte, Billy révèle qu’il n’a pas gardé le collier. Goldtooth, un kobold notoire de Fargodeep Mine, l’a récupéré.",al={"où est le collier","qui a pris le collier","lien avec goldtooth"}},{q="Où se trouve Billy Maclure ?",a="Billy Maclure se trouve aux Vignes des Maclure, juste au sud de la route, au centre de la Forêt d’Elwynn et en face de la ferme des Champierreux.",al={"emplacement de billy maclure","où est billy","trouver billy"}},{q="Qui a préparé la tourte de panse de porc ?",a="Tatie Bernice Champierreux a préparé la tourte à la ferme des Champierreux, après que vous avez ramassé des morceaux de viande de sanglier frais dans les étendues sauvages voisines.",al={"qui a préparé la tourte","cuisinier de la tourte"}},{q="Cette quête met-elle fin à la querelle entre les familles ?",a="Non. La tourte satisfait le pot-de-vin personnel de Billy, tandis que l’hostilité profonde entre les adultes Champierreux et Maclure demeure.",al={"la querelle prend-elle fin","paix entre champierreux et maclure"}}},fx={["6d42dc77"]={q="Pourquoi Tatie Bernice envoie-t-elle un étranger pour s'occuper de Billy ?",a="La querelle amère entre les Champierreux et les Maclure rend le contact direct entre les familles presque impossible. Tatie Bernice ne peut supporter de mettre le pied sur les terres des Maclure elle-même, et encore moins de servir en personne un enfant odieux qui réclame de la nourriture en échange de biens volés. Un voyageur de passage offre un messager neutre capable de traverser la route, de livrer la tourte et d'extirper la vérité du jeune Billy sans déclencher une bagarre ouverte entre les clans voisins.",al={"pourquoi m'envoyer retourner voir billy","pourquoi pas bernice elle-même","pourquoi tatie bernice a besoin d'un aventurier"}}},fp="13,218,12.304.0,13.343.1,37.224.0,42.209.0,46.131.1,31.124.0,29.135.0,54.122.0"}
P.entries["quest:840"] = {n="Sous les drapeaux de la Horde",s="Sur la route occidentale de Durotar, les recrues prennent le chemin des Tarides sous le nom de « Sous les drapeaux de la Horde ». Pisteur Takrin veille au-delà de Tranchecolline et leur remet une lettre pour Kargal Balafre-glorieuse, dont l’avant-poste garde le passage.",h="Sur la route occidentale de Durotar, les recrues prennent le chemin des Tarides sous le nom de « Sous les...",kw={"les tarides","sous les drapeaux de la horde","la croisée","kargal balafre-glorieuse","tranchecolline","lettre de recrutement","fleuve furie-du-sud","pisteur takrin"},ang={["faction:Horde"]="En tant que membre de la Horde, cet enrôlement marque votre passage de la protection de Durotar à la défense des terres de la Horde à travers Kalimdor.",["race:Orc"]="Pour un jeune orc qui quitte la Vallée des épreuves et Tranchecolline, répondre à l’appel de Kargal Balafre-glorieuse est un rite de passage au service du chef de guerre.",["race:Troll"]="En tant que troll Sombrelance, vous rejoignez vos alliés orcs dans cette mission pour soutenir l’expansion de la Horde et sécuriser les terres qui bordent la Grande mer."},sec={{t="Traversée du fleuve Furie-du-Sud",b="Vous avez fait vos preuves autour de Tranchecolline, et la Horde vous appelle maintenant vers l’ouest pour la servir. Pisteur Takrin surveille la route qui quitte Durotar pour son ami, le vétéran Kargal Balafre-glorieuse. Il remet aux voyageurs capables une lettre de recrutement à porter de l’autre côté du fleuve Furie-du-Sud. Pour une recrue, elle marque une première affectation officielle au-delà de la nouvelle patrie des orcs."},{t="Défense de la frontière",b="Kargal Balafre-glorieuse tient l’avant-poste au-delà du pont, entre les canyons rouges de Durotar et les Tarides arides. Il rassemble des recrues pour garder la frontière, où centaures, hurans et expéditions de l’Alliance la mettent à l’épreuve. Pourtant, la Horde a besoin de plus que de gardes là-bas. Des effectifs bruts sont aussi envoyés à la colonie de la Croisée."}},faq={{q="Où dois-je apporter la lettre de recrutement ?",a="Prenez la route vers l’ouest en quittant Tranchecolline, puis traversez le pont de bois au-dessus du fleuve Furie-du-Sud. Kargal Balafre-glorieuse vous attend à la tour de guet de la Horde, juste après la frontière, du côté des Tarides.",al={"où aller","emplacement de kargal balafre-glorieuse","lieu où rendre la quête"}},{q="Qui est Pisteur Takrin ?",a="Pisteur Takrin est un éclaireur de la Horde sur la route occidentale, à l’extérieur de Tranchecolline. Il surveille la route et envoie les guerriers capables vers l’ouest rejoindre son camarade Kargal Balafre-glorieuse.",al={"rôle de pisteur takrin","qui donne la quête","donneur de quête"}},{q="Qui est Kargal Balafre-glorieuse ?",a="Kargal Balafre-glorieuse est un officier vétéran bourru, au poste de guet de l’est des Tarides. Il examine les volontaires qui arrivent, signe leurs papiers d’enrôlement et les dirige vers l’ouest, à travers la savane, pour aider la Croisée.",al={"qui est kargal","histoire de balafre-glorieuse"}},{q="Que se passe-t-il après que Kargal a signé la lettre ?",a="Après avoir accepté la lettre, Kargal vous enrôle pour poursuivre le service et vous envoie vers l’ouest, par la route principale, faire votre rapport à Sergra Darkthorn à la Croisée.",al={"quête suivante","que faire après sous les drapeaux de la horde","où aller ensuite"}},{q="Pourquoi la Horde recrute-t-elle des soldats pour les Tarides ?",a="Les Tarides sont une frontière ouverte qui relie Orgrimmar à Mulgore. De féroces tribus de hurans, des maraudeurs centaures et des incursions de l’Alliance menacent les routes de ravitaillement. La Horde a donc besoin de toutes les forces disponibles pour les sécuriser.",al={"pourquoi s’enrôler","dangers des tarides","pourquoi recruter"}},{q="Cette quête est-elle accessible aux personnages de l’Alliance ?",a="Non. Ce service est réservé aux membres de la Horde qui passent de leurs premières aventures à Durotar à celles des Tarides.",al={"l’alliance peut-elle faire cette quête","quête réservée à la horde"}}},fx={dfa16f64={q="Pourquoi le Pisteur Takrin veut-il que je livre la lettre de recrutement ?",a="Le Pisteur Takrin sert d'éclaireur avancé surveillant la route depuis Durotar vers les plaines arides. Son vieux camarade Kargal Balafre-glorieuse commande l'avant-poste frontalier juste de l'autre côté de la rivière et fait face à une pénurie constante de guerriers capables. Voyant du potentiel dans votre force, Takrin veut diriger du sang neuf directement vers la garnison des Tarides pour renforcer la défense de la Horde plutôt que de laisser des mains valides attendre inutilement à Tranchecolline.",al={"pourquoi takrin m'envoie","mobile pisteur takrin","pourquoi recruter pour kargal"}},["788e36ab"]={q="Pourquoi Takrin envoie-t-il un aventurier plutôt que de faire son rapport à Kargal lui-même ?",a="Takrin est assigné à la surveillance du carrefour vital entre Durotar et la frontière ouest, gardant un œil sur les voyageurs et les menaces circulant le long de la route. Quitter son poste pour transporter des messages individuels serait abandonner son devoir. Plus important encore, il cherche des soldats potentiels pour aider Kargal, et le fait que vous fassiez votre rapport directement au commandant de l'avant-poste prouve votre volonté et votre initiative de servir la Horde.",al={"pourquoi takrin ne va pas","pourquoi m'envoyer à kargal","pourquoi moi conscript de la horde"}}},fp="22,229,22.363.0,14.326.0,39.186.0,25.160.0,25.208.0,43.155.0,53.221.0,44.96.0"}
P.entries["quest:8400"] = {n="Fight for Warsong Gulch",s="L’Alliance attend de vous une preuve de bravoure sur les lignes de front du Goulet des Chanteguerres. Un général de brigade de l’Alliance stationné près des champs de bataille réclame trois Marks of Honor remportés contre la Horde.",h="L’Alliance attend de vous une preuve de bravoure sur les lignes de front du Goulet des Chanteguerres.",kw={"alliance","orneval","champs de bataille","général de brigade","marks of honor","goulet des chanteguerres"},ang={["faction:Alliance"]="En tant que soldat de l’Alliance, rapporter vos insignes de bataille au général de brigade prouve votre engagement dans la lutte qui se poursuit contre la Horde au Goulet des Chanteguerres."},sec={{t="L’appel du général",b="Un général de brigade de l’Alliance stationné près du champ de bataille appelle les soldats de retour du front. Si vous avez combattu dans le Goulet des Chanteguerres, trois Marks of Honor attestent de votre valeur et de vos exploits contre la Horde. Rapporter ces insignes au haut commandement montre que l’Alliance tient ses positions dans le canyon disputé."}},faq={{q="Qui récupère les Marks of Honor du Goulet des Chanteguerres ?",a="Un général de brigade de l’Alliance stationné près du champ de bataille rassemble les insignes pour suivre l’effort de guerre.",al={"qui demande les marks of honor","insignes du général de brigade"}},{q="Combien d’insignes devez-vous rapporter ?",a="Trois Marks of Honor du Goulet des Chanteguerres sont nécessaires pour prouver vos exploits sur le champ de bataille.",al={"combien d’insignes goulet des chanteguerres","insignes requis chanteguerres"}},{q="Où se trouve le général de brigade de l’Alliance ?",a="Le général de brigade attend près des champs de bataille, où l’Alliance coordonne ses troupes.",al={"où se trouve le général de brigade","emplacement du général de l’alliance"}}},fp="23,198,18.327.0,43.107.0,36.85.0,40.96.0"}
P.entries["quest:841"] = {n="Une autre Source d'énergie ?",s="À Gadgetzan, l’Ingénieur en chef Bilgewhizzle vous propose une autre source d’énergie contre dix Wastewander Water Pouches.",h="À Gadgetzan, l’Ingénieur en chef Bilgewhizzle vous propose une autre source d’énergie contre dix Wastewander...",kw={"bilgewhizzle","gadgetzan","source d’énergie","tanaris","wastewander","gourdes d’eau"},sec={{t="Un remplacement coûteux",b="L’Ingénieur en chef Bilgewhizzle pense que la première source d’énergie est arrivée à expiration ou s’est perdue dans le sable. Quoi qu’il en soit, il en a une autre à vous vendre. Les temps sont durs pour tout le monde, alors il vous en demande dix Wastewander Water Pouches."}},faq={{q="Pourquoi l’Ingénieur en chef Bilgewhizzle demande-t-il des Wastewander Water Pouches ?",a="L’Ingénieur en chef Bilgewhizzle demande dix Wastewander Water Pouches en échange d’une autre source d’énergie. Les temps sont durs pour tout le monde.",al={"bilgewhizzle gourdes d’eau","pourquoi des gourdes d’eau"}},{q="Qui propose cet échange ?",a="L’Ingénieur en chef Bilgewhizzle propose l’échange et a d’autres sources d’énergie à vendre.",al={"qui propose une autre source d’énergie","donneur de quête source d’énergie"}},{q="Que s’est-il passé avant qu’il faille une autre source d’énergie ?",a="Cela fait suite à Slake That Thirst, où vous avez obtenu une source d’énergie pour votre équipement.",al={"prérequis autre source d’énergie","quête précédente source d’énergie"}}},fp="21,108,20.225.0,68.132.0,25.83.0,52.84.0"}
P.entries["quest:842"] = {n="Conscription à la Croisée",s="Kargal Balafre-glorieuse envoie les recrues vers l’ouest depuis le Poste de garde extérieur pour se présenter à Conscription à la Croisée. Muni de sa lettre signée, vous rejoignez Sergra Darkthorn au carrefour central des Tarides.",h="Kargal Balafre-glorieuse envoie les recrues vers l’ouest depuis le Poste de garde extérieur pour se présenter...",kw={"tarides","balafre-glorieuse","conscription","la croisée","darkthorn","poste de garde extérieur","kargal","sergra darkthorn","thrall"},ang={["class:Shaman"]="En tant que chaman, vous voyez Sergra Darkthorn diriger comme conseillère spirituelle, commandante militaire et administratrice d’un avant-poste stratégique.",["faction:Horde"]="En tant que membre de la Horde, vous quittez la sécurité de votre patrie pour servir dans les étendues disputées des Tarides.",["race:Orc"]="En tant qu’orque, vous voyez la Horde de Thrall changer, alors que le mérite et la clairvoyance spirituelle remettent en question les anciennes traditions claniques du travail de fantassin."},sec={{t="Se présenter au service",b="Après avoir fait vos preuves, Kargal Balafre-glorieuse vous envoie vers l’ouest depuis le Poste de garde extérieur. Il vous remet une lettre de recrutement signée pour le voyage sur la route de terre battue qui traverse les broussailles arides des Tarides. La route mène à un carrefour central où La Croisée relie le nord de Kalimdor aux étendues sauvages du sud."},{t="La chamane de La Croisée",b="À La Croisée, Sergra Darkthorn accueille les nouvelles recrues. Le chef de guerre Thrall a choisi cette chamane orque à la langue acérée pour superviser les opérations. Kargal Balafre-glorieuse grommelle qu’elle est difficile et parle trop, bien que Thrall ait beaucoup d’estime pour elle.\n\nSergra est farouche et inflexible. Elle rappelle aux recrues, surtout aux hommes arrogants, que les guerrières et dirigeantes ont la même place que les hommes dans la Horde de Thrall. L’insolence n’a pas sa place ici."}},faq={{q="Qui m’envoie faire cette quête ?",a="Kargal Balafre-glorieuse, un vétéran orque du Poste de garde extérieur, juste à l’ouest du pont entre Durotar et les Tarides, vous envoie vers l’ouest avec une lettre pour Sergra.",al={"qui donne conscription à la croisée","donneur de quête conscription à la croisée","quête de kargal"}},{q="Où se trouve Sergra Darkthorn ?",a="Sergra Darkthorn se trouve près du croisement routier au centre de La Croisée, où se rencontrent caravanes et messagers.",al={"emplacement de sergra darkthorn","où se trouve sergra","trouver sergra darkthorn"}},{q="Pourquoi Kargal se plaint-il de Sergra ?",a="Sergra exaspère Kargal. Il la décrit comme une chamane détestable qui tourne autour du pot avant que quiconque puisse passer aux choses sérieuses, même s’il respecte l’ordre de Thrall de lui envoyer des recrues.",al={"pourquoi kargal n’aime pas sergra","kargal contre sergra","maudire sa peau"}},{q="Pourquoi Sergra ne s’adresse-t-elle pas de la même façon aux personnages masculins et féminins ?",a="Sergra est fière du mandat de Thrall en faveur de l’égalité des guerrières dans la Horde. Elle encourage les recrues féminines et avertit les recrues masculines qu’elle ne tolérera ni manque de respect ni insolence.",al={"dialogue de sergra avec les hommes et les femmes","dialogue de sergra darkthorn","sergra sur un pied d’égalité"}},{q="Quel chemin prendre pour rejoindre La Croisée ?",a="Suivez la route principale vers l’ouest depuis le Poste de garde extérieur jusqu’à un carrefour en T. Tournez à gauche et suivez la route du sud jusqu’à La Croisée.",al={"comment rejoindre la croisée","itinéraire vers la croisée","chemin vers la croisée"}},{q="Que se passe-t-il après m’être présenté à Sergra Darkthorn ?",a="Sergra accepte votre aide à La Croisée et vous envoie lutter contre les menaces locales, chasser et assurer la sécurité des avant-postes dans le centre des Tarides.",al={"que faire après conscription à la croisée","quête suivante de sergra","prochaine étape pour les recrues des tarides"}}},fx={["3243ab88"]={q="Pourquoi Kargal Balafre-glorieuse m'envoie-t-il à La Croisée ?",a="En tant que commandant du Poste de garde extérieur, Kargal traite les nouvelles recrues entrant dans les Tarides depuis Durotar. Plutôt que de garder chaque combattant valide à un avant-poste d'entrée, son devoir envers la Horde est d'envoyer les nouvelles recrues plus profondément dans la frontière. La Croisée sert de plaque tournante centrale de l'autorité de la Horde et de la mobilisation militaire dans les Tarides, où la main-d'œuvre est désespérément nécessaire pour sécuriser les terres environnantes sous la supervision de Sergra Darkthorn.",al={"pourquoi envoyer à la croisée","mobile kargal conscription de la croisée","pourquoi faire un rapport à sergra"}},["07e83289"]={q="Pourquoi Kargal m'envoie-t-il au lieu d'envoyer l'un de ses gardes ?",a="Vous êtes une nouvelle recrue cherchant à faire vos preuves et à gagner votre place au sein de la Horde. Les gardes de l'avant-poste de Kargal sont déjà assignés à la garnison du poste de garde frontalier contre les menaces locales. Vous envoyer avec une lettre de recrutement signée renforce l'avant-poste de La Croisée tout en testant si une nouvelle recrue a la discipline nécessaire pour naviguer seule dans les plaines sauvages et suivre les ordres.",al={"pourquoi kargal a besoin de moi","pourquoi ne pas envoyer un garde à la croisée","pourquoi moi kargal"}}},fp="23,184,18.318.0,28.425.0,27.153.0,34.111.0,38.185.0,64.193.0,49.130.0,49.145.0"}
P.entries["quest:8426"] = {n="Battle of Warsong Gulch",s="Un Horde Warbringer vous demande d’apporter trois Warsong Gulch Marks of Honor. Ces marques sont les preuves demandées pour cet appel.",h="Un Horde Warbringer vous demande d’apporter trois Warsong Gulch Marks of Honor.",kw={"champs de bataille","horde","marques d’honneur","warbringer","goulet des chanteguerres"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez apporter les Warsong Gulch Marks of Honor à un Horde Warbringer."},sec={{t="Une marque rapportée",b="Vous apportez les trois Warsong Gulch Marks of Honor à un Horde Warbringer à l’extérieur des champs de bataille. Le Warbringer demande ces marques, et cet appel n’exige rien de plus."}},faq={{q="Que demande le Warbringer ?",a="Le Horde Warbringer vous demande d’apporter trois Warsong Gulch Marks of Honor.",al={"quelles marques","demande du warbringer","quoi apporter"}},{q="Où apporter les marques ?",a="Apportez les marques à un Horde Warbringer à l’extérieur des champs de bataille.",al={"où est le warbringer","remettre les marques","où apporter"}},{q="Combien de marques faut-il ?",a="Le Warbringer demande trois Warsong Gulch Marks of Honor.",al={"combien de marques","nombre de marques","trois marques"}}},fp="23,121,15.170.0,33.74.0,27.64.0,26.59.0"}
P.entries["quest:8427"] = {n="Battle of Warsong Gulch",s="Un porte-guerre de la Horde, près du Goulet des Chanteguerres, vous demande trois Marks of Honor du Goulet des Chanteguerres. Ces marques sont nécessaires pour cet échange.",h="Un porte-guerre de la Horde, près du Goulet des Chanteguerres, vous demande trois Marks of Honor du Goulet...",kw={"bataille","champ de bataille","horde","marks of honor","porte-guerre","goulet des chanteguerres"},faq={{q="Que demande le porte-guerre ?",a="Le porte-guerre de la Horde vous demande trois Marks of Honor du Goulet des Chanteguerres.",al={"marques du goulet des chanteguerres","marks of honor","quoi apporter"}},{q="Où dois-je apporter les marques ?",a="Apportez les marques à un porte-guerre de la Horde, près des champs de bataille.",al={"où trouver le porte-guerre","rendre les marques","porte-guerre du goulet des chanteguerres"}},{q="Combien de marques faut-il ?",a="Le porte-guerre demande trois Marks of Honor du Goulet des Chanteguerres.",al={"combien de marques","trois marques","quantité de marques"}}},fp="23,136,33.74.0,27.64.0,26.59.0"}
P.entries["quest:843"] = {n="La reconquête de Gann",s="Dans les Tarides du sud, La reconquête de Gann se tourne vers Bael Modan. Gann Cime-de-pierre, un exilé tauren, vous demande de frapper le site de fouilles qui l’a chassé du foyer ancestral et des terres de chasse de son clan.",h="Dans les Tarides du sud, La reconquête de Gann se tourne vers Bael Modan.",kw={"bael modan","bael'dun","site de fouilles nain","gann cime-de-pierre","khazgorm","tarides du sud"},ang={["class:Shaman"]="En tant que chaman, vous savez que les explosions et les profondes tranchées de Bael Modan blessent les esprits de la terre alentour. La campagne de Gann est une purification nécessaire de ce déséquilibre élémentaire.",["faction:Horde"]="En tant que membre de la Horde, vous voyez Bael Modan comme un bastion fortifié de l’Alliance, au cœur de Kalimdor. Défendre les revendications de Gann est un acte d’honneur et un moyen de contenir ce bastion.",["race:Tauren"]="En tant que Shu'halo, vous pouvez voir le sort de Gann comme un rappel exaspérant du peu de respect que l’Alliance témoigne à la Terre-Mère. La dynamite et les engrenages de fer éventrent les terres ancestrales où reposent les morts."},sec={{t="Une tribu déplacée",b="Gann Cime-de-pierre marche seul le long de la route du sud, en quête de justice pour les siens tombés. Son clan vivait parmi les falaises rouges au sud des Tarides. Des Nains de Forgefer ont construit Bael Modan sur ces terres, chassant les Taurens ou les tuant pour faire place aux carrières et aux tranchées. Gann affirme que les manifestations pacifiques et la diplomatie ont échoué. Il cherche désormais à venger son clan déplacé et décimé."},{t="Les ruines de Bael Modan",b="À Bael Modan, des excavateurs nains éventrent les collines à l’aide de machines à vapeur et d’explosifs. Le prospecteur Khazgorm dirige les fouilles en profondeur. Gann vous demande de réduire les rangs des excavateurs et des contremaîtres de Bael'dun, de tuer Khazgorm et de rapporter les notes de fouilles personnelles du prospecteur. Il veut découvrir ce que l’expédition de l’Alliance cherche dans le sol sacré."}},faq={{q="Qui est Gann Cime-de-pierre ?",a="Gann Cime-de-pierre est un survivant tauren solitaire dont la tribu vivait autrefois dans les Tarides du sud. Des excavateurs nains ont chassé les siens de leurs terres et tué ceux qui résistaient. Il arpente désormais la route du sud, en quête de justice et de vengeance contre le site de fouilles de l’Alliance.",al={"gann","qui donne la reconquête de gann","histoire de gann cime-de-pierre"}},{q="Pourquoi les Nains sont-ils dans les Tarides ?",a="Les Nains appartiennent à une expédition de Forgefer appelée Bael'dun. Ils ont bâti un bastion et un site de fouilles à Bael Modan, dans les Tarides du sud. Leurs explosions et leurs machines bruyantes éventrent les collines malgré la présence des Taurens autochtones.",al={"pourquoi les nains sont-ils à bael modan","but de bael modan","forgefer dans les tarides"}},{q="Qui est le prospecteur Khazgorm ?",a="Le prospecteur Khazgorm dirige les fouilles naines au sud de la forteresse de Bael Modan. Gann le tient pour responsable de la profanation de ses terres ancestrales et réclame son journal comme preuve de sa mort.",al={"khazgorm","prospecteur khazgorm","chef de bael modan"}},{q="Où trouver Gann Cime-de-pierre ?",a="Gann Cime-de-pierre marche le long de la route, dans l’extrême sud des Tarides, à l’ouest de la forteresse de Bael Modan et au nord de la route menant à la Grande élévation et à Mille pointes.",al={"emplacement de gann","trouver gann","où est gann"}},{q="Gann a-t-il essayé de régler le conflit pacifiquement ?",a="Oui. Gann affirme avoir tenté la diplomatie et d’autres moyens pacifiques pour mettre fin à la destruction de ses terres ancestrales. Les Nains ont écarté ses efforts et continué à faire exploser les collines ; il a donc eu recours à la violence.",al={"les taurens ont-ils tenté la diplomatie","diplomatie de gann"}},{q="Que se passe-t-il après cette quête ?",a="Après avoir reçu le journal de Khazgorm, Gann étudie les notes pour comprendre la technologie et les plans des Nains. Il cherche ensuite à saboter leurs machines lourdes.",al={"quête après la reconquête de gann","suite de gann"}}},fx={fd3e714a={q="À quoi sert le Journal de Khazgorm ?",a="Ce journal appartient au prospecteur Khazgorm, le chef qui supervise le chantier de fouilles destructeur de Bael Modan. Gann souhaite en étudier les pages pour mieux comprendre les opérations des nains, leurs motivations dans la région et le meilleur moyen de stopper la destruction continue de son territoire ancestral.",al={"utiliser le journal de khazgorm","pourquoi collecter le journal de khazgorm","ce que gann veut avec le journal"}},["4442e883"]={q="Pourquoi Gann vous demande-t-il de l'aide au lieu de s'occuper de l'excavation lui-même ?",a="Gann erre seul dans les Tarides du sud, un exilé dont la tribu a été massacrée ou dispersée par l'arrivée des nains. Face à un camp fortifié rempli de dizaines d'excavateurs armés, de contremaîtres et de leur chef, il ne peut espérer déloger les envahisseurs sans un champion capable de combattre pour lui.",al={"pourquoi gann ne peut pas le faire lui-même","pourquoi gann a besoin d'aide","pourquoi moi pour gann"}},["5ecef431"]={q="Pourquoi Gann Cime-de-pierre veut-il chasser les nains ?",a="Bael Modan est situé directement sur les terres ancestrales de la tribu de Gann. Lorsque les nains sont arrivés, leur creusement incessant, leurs machines bruyantes et leurs détonations ont chassé les taurens de chez eux et coûté de nombreuses vies innocentes. Ayant épuisé toutes les tentatives pacifiques, Gann cherche des représailles et vise à récupérer la terre sacrée de son peuple par la force.",al={"mobile gann","pourquoi tuer les nains de baeldun","pourquoi gann veut se venger"}}},fp="18,202,17.379.0,23.355.0,23.270.0,35.238.0,27.190.0,35.163.0,40.195.0,30.158.1"}
P.entries["quest:8431"] = {n="Battle of Warsong Gulch",s="La Horde cherche à conserver le Goulet des Chanteguerres. Votre aide renforce ses droits sur ce territoire.",h="La Horde cherche à conserver le Goulet des Chanteguerres.",kw={"bataille","goulet","horde","possession","goulet des chanteguerres"},ang={["faction:Horde"]="Vous aidez la Horde à conserver le Goulet des Chanteguerres."},sec={{t="Une revendication dans le goulet",b="La revendication de la Horde sur le Goulet des Chanteguerres est en jeu, et vous prêtez votre force pour la défendre. Vos efforts aident la Horde à conserver le goulet."}},faq={{q="Que se passe-t-il au Goulet des Chanteguerres ?",a="La Horde cherche à conserver le Goulet des Chanteguerres.",al={"bataille du goulet des chanteguerres","que se passe-t-il dans le goulet"}},{q="Qui est-ce que j’aide ?",a="Vous aidez la Horde à conserver le Goulet des Chanteguerres.",al={"qui demande de l’aide","pour quel camp"}},{q="Que veut la Horde ?",a="La Horde cherche à garder le Goulet des Chanteguerres.",al={"objectif de la horde","pourquoi se battre au goulet des chanteguerres"}}},fp="23,88,20.153.0,35.62.0,17.64.0,25.55.0"}
P.entries["quest:8436"] = {n="Conquering Arathi Basin",s="Un porte-guerre de la Horde vous demande trois marques d’honneur du Bassin Arathi. Rapportez-les du champ de bataille au porte-guerre qui attend à l’extérieur.",h="Un porte-guerre de la Horde vous demande trois marques d’honneur du Bassin Arathi.",kw={"bassin arathi","champ de bataille","porte-guerre de la horde","marque d’honneur","marques d’honneur"},sec={{t="Une demande du porte-guerre",b="Le porte-guerre attend à l’extérieur des champs de bataille, où vous pouvez lui rapporter les marques. La Horde vous demande trois marques d’honneur du Bassin Arathi."}},faq={{q="Que veut le porte-guerre de la Horde ?",a="Le porte-guerre de la Horde vous demande de rapporter trois marques d’honneur du Bassin Arathi.",al={"demande du porte-guerre","que rapporter","marques du bassin arathi"}},{q="Où dois-je rapporter les marques ?",a="Rapportez les marques à un porte-guerre de la Horde, à l’extérieur des champs de bataille.",al={"où rapporter les marques","emplacement du porte-guerre","à l’extérieur du champ de bataille"}},{q="Combien de marques d’honneur faut-il ?",a="On vous demande de rapporter trois marques d’honneur du Bassin Arathi.",al={"nombre de marques","trois marques","compte des marques"}},{q="Quelles marques le porte-guerre demande-t-il ?",a="Il demande des marques d’honneur du Bassin Arathi.",al={"quelles marques","marque du bassin arathi","marques d’honneur"}}},fp="23,129,22.149.0,36.73.0,27.64.0,35.57.0,40.47.0"}
P.entries["quest:84396"] = {n="Magma or Lava?",s="Jennea Cannon recherche des ouvrages magiques pour enrichir la bibliothèque du Mage Quarter de Hurlevent. De nouveaux écrits viennent étoffer les connaissances arcaniques de la ville.",h="Jennea Cannon recherche des ouvrages magiques pour enrichir la bibliothèque du Mage Quarter de Hurlevent.",kw={"arcanes","collection","jennea cannon","library","mage quarter","ouvrages magiques","magma ou lave","hurlevent"},sec={{t="Des pages pour les rayonnages",b="Au Sanctuaire du sorcier, dans le Mage Quarter de Hurlevent, Jennea Cannon constitue des archives toujours plus riches sur les arts arcaniques. Quand vos voyages vous font découvrir des ouvrages magiques, elle vous demande de les lui apporter pour la bibliothèque. Chaque nouveau texte enrichit le savoir des érudits du sanctuaire sur le monde."}},faq={{q="Qui recherche des ouvrages magiques pour la bibliothèque ?",a="Jennea Cannon rassemble des ouvrages magiques dans le Mage Quarter de Hurlevent pour enrichir la collection de la bibliothèque.",al={"magma ou lave bibliothèque","où rapporter des ouvrages magiques","livre de la bibliothèque de hurlevent"}},{q="Que rassemble-t-on pour la collection ?",a="La collection s’enrichit chaque fois que des voyageurs rapportent des écrits et des récits à la bibliothèque.",al={"que faut-il à la bibliothèque","que rassemblent-ils"}},{q="Pourquoi la Library recherche-t-elle ces écrits ?",a="Jennea Cannon accueille les écrits magiques rapportés par les voyageurs afin que le savoir du sanctuaire continue de croître.",al={"pourquoi rapporter des livres à la bibliothèque","but du magma ou de la lave"}}},fp="14,171,21.280.0,39.99.0,42.92.0,41.100.0"}
P.entries["quest:84399"] = {n="Ka-Boom!",s="Jennea Cannon vous demande de lui apporter les ouvrages magiques découverts au cours de vos voyages. Chaque contribution enrichit la collection de la bibliothèque dans le Mage Quarter de Hurlevent.",h="Jennea Cannon vous demande de lui apporter les ouvrages magiques découverts au cours de vos voyages.",kw={"collection","jennea cannon","ka-boom!","library","mage quarter","ouvrages magiques","hurlevent"},sec={{t="Enrichir la collection",b="Dans le Sanctuaire du sorcier de Hurlevent, Jennea Cannon s’emploie à enrichir les réserves de savoir arcanique de la bibliothèque. Lorsque vous découvrez des ouvrages magiques au cours de vos voyages, elle vous demande de les lui apporter pour étoffer la collection."}},faq={{q="Que recherche la Library ?",a="Jennea Cannon recherche des ouvrages magiques pour enrichir la collection de savoir de la bibliothèque.",al={"que veut la library","quoi apporter à la library","quels ouvrages la library collectionne"}},{q="Qui demande ces ouvrages magiques ?",a="Jennea Cannon, dans le Mage Quarter de Hurlevent, accueille les nouveaux ouvrages de la bibliothèque et demande aux voyageurs de lui apporter les écrits magiques qu’ils découvrent.",al={"qui veut des ouvrages magiques","où vont les ouvrages magiques","qui recueille le savoir à hurlevent"}},{q="Pourrez-vous rapporter d’autres ouvrages magiques plus tard ?",a="Jennea vous invite à lui rapporter tout autre ouvrage magique découvert au cours de vos voyages, dans le Mage Quarter, afin de continuer à enrichir la collection de la bibliothèque.",al={"faut-il garder les livres magiques","puis-je apporter d’autres livres","que faire des ouvrages magiques trouvés"}}},fp="8,166,24.232.0,32.82.0,33.136.0,39.141.0"}
P.entries["quest:844"] = {n="La menace des trotteurs des plaines",s="À l’est de La Croisée, les trotteurs des plaines menacent les réserves de vivres de l’avant-poste. Sergra Sombreronce envoie les nouvelles recrues de la Horde les chasser, leur donnant un premier aperçu des Tarides.",h="À l’est de La Croisée, les trotteurs des plaines menacent les réserves de vivres de l’avant-poste.",kw={"tarides","bec","la croisée","sombreronce","chasse","trotteur des plaines","sergra","provisions"},ang={["class:Hunter"]="En tant que jeune chasseur, vous apprenez à approcher, traquer et abattre le gibier dans la vaste savane.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger La Croisée, un carrefour vital pour le ravitaillement, et à sécuriser ses vivres afin que la Horde puisse tenir ses positions à travers Kalimdor.",["race:Orc"]="En tant qu’orc, vous faites honneur à la discipline de la chasse. Sergra attend de vous que vous fassiez vos preuves face aux bêtes locales avant d’assumer des tâches plus importantes."},sec={{t="Protéger La Croisée",b="La Croisée coordonne le ravitaillement à travers Kalimdor. À présent, les trotteurs des plaines à l’est de l’avant-poste s’attaquent à ses caisses de vivres. Sergra Sombreronce, une chamane orque, envoie les aventuriers fraîchement arrivés de la Horde chasser ces oiseaux avant qu’ils n’endommagent les réserves. La colonie dépend de ces provisions."},{t="La première chasse",b="Sergra Sombreronce met les nouveaux venus à l’épreuve tout en protégeant les réserves de la colonie. À ses yeux, les trotteurs des plaines sont des proies faciles, idéales pour apprendre aux jeunes chasseurs à endurer les éléments et à traquer le gibier dans les plaines brûlées par le soleil. Rapporter leurs becs acérés témoigne de la patience et des rudiments martiaux nécessaires pour affronter les bêtes plus féroces des Tarides."}},faq={{q="Pourquoi s’en prendre aux trotteurs des plaines ?",a="Les trotteurs des plaines à l’est de La Croisée sont devenus téméraires. Ils pillent les réserves de vivres et harcèlent les convois de ravitaillement qui passent. Sergra Sombreronce ordonne la chasse pour protéger les provisions de la colonie.",al={"pourquoi tuer les trotteurs des plaines","problème des trotteurs des plaines","qu’ont fait les trotteurs des plaines"}},{q="Qui est Sergra Sombreronce ?",a="Sergra Sombreronce est une chamane orque expérimentée, en poste à La Croisée. Elle supervise les épreuves de chasse, forme les aventuriers fraîchement arrivés et les envoie affronter les bêtes sauvages qui menacent les opérations de la Horde.",al={"qui est sergra","rôle de sergra sombreronce","donneuse de quête à la croisée"}},{q="Pourquoi Sergra veut-elle leurs becs précisément ?",a="Le trotteur des plaines se sert de son bec robuste et acéré comme arme principale et pour fouiller le sol. Rapporter le bec prouve que l’oiseau a été tué.",al={"pourquoi les becs de trotteur des plaines","preuve avec le bec de trotteur des plaines"}},{q="Que se passe-t-il après cette chasse ?",a="Après les trotteurs des plaines, Sergra vous envoie chasser des zhevras, des proies plus rapides et plus fougueuses qui parcourent les plaines.",al={"quelle est la suite","quête après les trotteurs des plaines","série de chasses"}},{q="Où se trouvent ces trotteurs des plaines ?",a="Les trotteurs des plaines parcourent les savanes à l’est et au sud-est de La Croisée, où ils cherchent de la nourriture le long des routes commerciales.",al={"où se trouvent les trotteurs des plaines","emplacements des trotteurs des plaines","terrains de chasse"}},{q="Cela fait-il partie d’une série de chasses plus vaste ?",a="Oui. C’est le début des épreuves de chasse de Sergra Sombreronce dans les Tarides. Elles deviennent plus dangereuses et vous mènent à affronter des bêtes plus féroces dans la savane.",al={"série de chasses des tarides","série de quêtes de sergra"}}},fx={["416dd73a"]={q="Pourquoi Sergra Darkthorn a-t-elle besoin d'un aventurier plutôt que des gardes de la Croisée ?",a="Les gardes stationnés à la Croisée sont déjà bien occupés à défendre les abords contre les raids des hurans et à assurer la sécurité des routes locales. Pour Sergra, chasser les charognards nuisibles dans les plaines sert deux objectifs : soulager les voies de ravitaillement de la colonie tout en vérifiant si les nouveaux arrivants savent suffisamment pister et combattre pour survivre dans les Tarides.",al={"pourquoi envoyer un aventurier","pourquoi les gardes ne tuent pas les trotteurs des plaines","pourquoi un aventurier trotteurs des plaines"}}},fp="19,188,23.286.0,14.345.0,35.186.0,24.201.0,46.142.0,27.107.0,38.111.0,40.150.0"}
P.entries["quest:845"] = {n="Les zhévras",s="À La Croisée, Sergra Darkthorn envoie les jeunes guerriers de la Horde chasser les zhévras. Cette épreuve les prépare à affronter les bêtes plus dangereuses des Tarides.",h="À La Croisée, Sergra Darkthorn envoie les jeunes guerriers de la Horde chasser les zhévras.",kw={"tarides","la croisée","sabots","épreuve de chasse","sergra darkthorn","zhévra","zhévra coureur"},ang={["class:Hunter"]="En tant que chasseur qui apprend à connaître les Tarides, vous pouvez affûter votre pistage et votre visée en traquant les hardes de zhévras rapides.",["faction:Horde"]="En tant que membre de la Horde, vous aidez La Croisée à gérer la faune des environs et à garder ses voies d'approvisionnement dégagées.",["race:Tauren"]="En tant que tauren, vous savez à quel point la ruade d'un zhévra peut être puissante. Sergra vous avertit qu'elle peut faire perdre pied à un tauren adulte."},sec={{t="Un pas de plus dans la savane",b="Après les trotteurs des plaines, Sergra Darkthorn vous envoie chasser des proies plus coriaces. Les zhévras vivent en hardes dans le nord et le sud des Tarides. Ils sont rapides et tenaces, mais ne sont pas les bêtes les plus féroces de la savane. Leurs ruades peuvent briser des os."},{t="Les épreuves de Darkthorn",b="Sergra met votre talent grandissant à l'épreuve avec cette chasse. Elle demande quatre sabots intacts pour prouver votre prise. Une ruade d'un zhévra peut faire tomber un tauren adulte sur son séant. Réussissez cette épreuve et vous vous rapprocherez des rôdeurs prédateurs des plaines."}},faq={{q="Qui confie cette chasse ?",a="Sergra Darkthorn, une chamane orque expérimentée de La Croisée, au centre des Tarides, confie cette épreuve aux jeunes guerriers de la Horde.",al={"qui donne la quête des zhévras","donneur de quête des zhévras","quête de sergra darkthorn"}},{q="Où trouve-t-on les zhévras ?",a="Les zhévras parcourent les plaines dégagées au nord et au sud de La Croisée, au centre des Tarides.",al={"où trouver les zhévras","emplacement des zhévras","carte des zhévras des tarides"}},{q="Pourquoi Sergra veut-elle des sabots de zhévra ?",a="Les sabots prouvent que vous avez tué un zhévra. En rapporter quatre montre que vous avez vaincu une bête dont les puissantes pattes peuvent faire tomber même un tauren robuste.",al={"pourquoi les sabots de zhévra","preuve avec des sabots de zhévra","pourquoi chasser les zhévras"}},{q="Que se passe-t-il après cette quête ?",a="Après vous avoir mis à l'épreuve contre les zhévras, Sergra vous oppose aux prédateurs des Tarides dans les rôdeurs des Tarides.",al={"quête après les zhévras","suite des zhévras","quête suivante de darkthorn"}},{q="Les zhévras sont-ils dangereux ?",a="Les zhévras sont généralement des brouteurs paisibles, mais leurs pattes sont puissantes. Sergra vous avertit qu'un zhévra effrayé ou acculé peut faire tomber un tauren robuste d'une seule ruade.",al={"à quel point les zhévras sont-ils dangereux","danger des zhévras","ruade de zhévra"}},{q="Pourquoi les trotteurs des plaines ont-ils été chassés avant eux ?",a="Sergra rend ses épreuves progressivement plus difficiles. Les trotteurs des plaines sont la première cible ; les zhévras sont des proies plus rapides et plus fortes, qui vous préparent à affronter les rôdeurs agressifs de la savane.",al={"quête précédente","lien avec plainstrider menace"}}},fx={["6d2e3590"]={q="Pourquoi Sergra Darkthorn veut-elle que les zhevras soient chassés ?",a="Sergra Darkthorn teste vos prouesses de chasseur et vous aguerrit pour la nature sauvage et brutale des Tarides. Tandis que les autruches servent d'entraînement de base, les zhevras sont des bêtes plus robustes dont les ruades puissantes mettent vos réflexes et votre endurance à l'épreuve. En vous envoyant les traquer, Sergra s'assure que vous pouvez gérer une faune dangereuse avant de vous envoyer affronter les prédateurs dominants du territoire.",al={"pourquoi chasser les zhevras","motif de sergra","raison de sergra darkthorn"}},["1cbbdcd0"]={q="Que sont les zhevras coureurs ?",a="Les zhevras coureurs sont des équidés rapides et rayés originaires des savanes arides des Tarides. Voyageant en troupeaux à travers les plaines au nord et au sud de La Croisée, ils comptent sur leur vitesse et leurs formidables pattes arrière pour survivre parmi les rôdeurs et les raptors. Bien qu'ils ne soient pas des prédateurs intrinsèquement agressifs, leurs ruades peuvent mettre à terre un tauren adulte.",al={"ce que sont les zhevras","zhevras coureurs","qui nous chassons"}}},fp="10,144,24.232.0,23.248.0,22.129.0,27.93.0,35.145.0,28.116.0,22.164.0,42.169.0"}
P.entries["quest:846"] = {n="La revanche de Gann",s="Dans les Tarides du sud, Gann Cime-de-pierre se prépare à riposter aux nains de Bael Modan. Après la mort du Prospecteur Khazgorm, il envoie des alliés de la Horde dans la forteresse pour s'emparer de munitions instables destinées à son attaque.",h="Dans les Tarides du sud, Gann Cime-de-pierre se prépare à riposter aux nains de Bael Modan.",kw={"bael modan","tarides","dynamite","explosifs","gann cime-de-pierre","forgefer","khazgorm","nitroglycérine","nitrate de sodium","pulpe de bois"},ang={["faction:Horde"]="En tant que membre de la Horde, vous contribuez à empêcher l'Alliance d'établir un avant-poste militaire dans les Tarides du sud. Un tel avant-poste pourrait couper les routes entre Mulgore, La Croisée et la frontière sud.",["profession:Engineering"]="En tant qu'ingénieur, vous reconnaissez la formule industrielle classique des nains : de la nitroglycérine stabilisée avec de la pulpe et mélangée à du nitrate de sodium. Gann l'adapte pour un combat inégal.",["race:Tauren"]="En tant que tauren, vous pouvez voir Bael Modan comme une grave blessure infligée à la Terre-Mère. Saboter les machines naines est un devoir envers votre esprit et votre terre natale."},sec={{t="Le goût de leur propre médecine",b="Gann Cime-de-pierre sait que la mort du Prospecteur Khazgorm n'a fait que ralentir le site de fouilles de Bael Modan. Les nains reprendront le travail, et un autre contremaître dirigera bientôt les machines qui creusent ses terres ancestrales. Il ne laissera pas la terre subir de nouvelles excavations. Gann compte donc retourner contre les envahisseurs leur matériel de démolition et faire éclater leur bastion de l'intérieur."},{t="Piller la forteresse",b="La forteresse de Bael Modan protège une base de fouilles et une garnison de soldats, de fusiliers et d'officiers qui défendent les intérêts nains dans les Tarides. Ses défenseurs transportent de la nitroglycérine, de la pulpe de bois et du nitrate de sodium pour les démolitions industrielles. Gann envoie des alliés de la Horde franchir le périmètre pour récupérer ces provisions instables. Avec une quantité suffisante, il pourra assembler une puissante charge explosive."}},faq={{q="Pourquoi Gann Cime-de-pierre cherche-t-il à se venger ?",a="Les nains de Forgefer à Bael Modan ont envahi les terres ancestrales de Gann, profané leur sol et chassé son peuple pour y établir leur site de fouilles. Après avoir tué le Prospecteur Khazgorm et récupéré son journal, Gann veut mettre fin aux destructions une bonne fois pour toutes.",al={"pourquoi gann est-il en colère","motivation de gann cime-de-pierre","qu'ont fait les nains à gann"}},{q="Où trouver les matériaux explosifs ?",a="Les défenseurs de Bael Modan transportent les ingrédients. Les fusiliers, soldats et officiers présents dans le site de fouilles fortifié et autour de celui-ci, dans les Tarides du sud, possèdent des fioles de nitroglycérine, des ballots de pulpe de bois et des échantillons de nitrate de sodium.",al={"où trouver de la nitroglycérine","comment obtenir de la pulpe de bois","où trouver du nitrate de sodium"}},{q="Pourquoi Gann a-t-il besoin de pulpe de bois et de produits chimiques ?",a="Les schémas de fouilles nains indiquent que la pulpe de bois stabilise la nitroglycérine instable, tandis que le nitrate de sodium permet de fabriquer un explosif industriel fiable. Gann compte façonner le mélange en charge de démolition capable d'abattre des structures naines importantes.",al={"à quoi sert la pulpe de bois","que fabrique gann","ingrédients de la bombe de gann"}},{q="Que se passe-t-il après avoir récupéré les provisions ?",a="Lorsque vous rapportez les composants bruts, Gann assemble une charge explosive et vous envoie détruire la machine volante des nains sur le site de fouilles de Bael Modan. Elle constitue un élément essentiel des infrastructures du site.",al={"que faire ensuite dans la revanche de gann","après avoir récupéré les ingrédients"}},{q="Pourquoi la mort de Khazgorm ne met-elle pas fin à la menace naine ?",a="Khazgorm n'était que le prospecteur en chef. Les forces naines de Bael Modan sont retranchées derrière des murs défensifs et des lignes de ravitaillement. Forgefer peut envoyer un autre contremaître pour poursuivre les fouilles, à moins que la base ne subisse un coup dévastateur.",al={"pourquoi la mort de khazgorm n'a-t-elle pas suffi","bael modan est-il arrêté"}},{q="Quelle menace stratégique Bael Modan représente-t-il pour la Horde ?",a="Bael Modan était d'abord un fort chargé de défendre le site de fouilles, mais il est devenu un bastion de l'Alliance lourdement gardé. Sa position le long des routes commerciales des Tarides du sud en fait une menace militaire pour les campements de la Horde voisins, en Kalimdor.",al={"pourquoi la horde se soucie-t-elle de bael modan","menace de bael modan"}}},fx={["410ab5f4"]={q="Qui transporte les fournitures nécessaires pour l'explosif ?",a="Les fournitures sont détenues par la garnison naine stationnée à Bael Modan. Les fusiliers, les soldats et les officiers à l'intérieur de l'excavation et du fort utilisent fréquemment de la poudre de dynamitage et des machines pour déchirer le sol, ce qui signifie qu'ils gardent à portée de main d'importants stocks de produits chimiques volatils et de stabilisants.",al={"qui a les matériaux explosifs","nains de bael modan","cibles de revenge of gann"}},["5f27d24f"]={q="Pourquoi Gann a-t-il besoin de vous plutôt que d'attaquer Bael Modan lui-même ?",a="Gann Cime-de-pierre est un survivant banni d'une tribu brisée, agissant seul sans le soutien d'un grand parti de guerre. Massacrer une garnison entière de nains de Forgefer fortifiée est bien au-delà de ses capacités ; il s'appuie donc sur un champion capable de la Horde pour infiltrer le fort et rassembler ce dont il a besoin.",al={"pourquoi gann a besoin de moi","pourquoi gann ne peut pas le faire lui-même","pourquoi moi pour revenge of gann"}}},fp="15,210,29.372.0,16.376.0,39.259.0,40.216.0,43.251.0,42.200.1,52.222.0,51.231.0"}
P.entries["quest:8465"] = {n="Speak to Salfa",s="Salfa monte la garde à l’extérieur du Repaire des Grumegueules. On vous demande de traverser le Repaire et de lui parler au Berceau-de-l’Hiver.",h="Salfa monte la garde à l’extérieur du Repaire des Grumegueules.",kw={"entrée","garde","salfa","parler","repaire des grumegueules","berceau-de-l’hiver"},sec={{t="Au Repaire des Grumegueules",b="À l’extérieur du Repaire des Grumegueules, Salfa attend en faction. On vous demande de traverser le Repaire, de déboucher au Berceau-de-l’Hiver et de lui parler là-bas."}},faq={{q="Qui est Salfa ?",a="Salfa monte la garde à l’entrée du Repaire des Grumegueules.",al={"qui est salfa"}},{q="Où trouver Salfa ?",a="Salfa monte la garde à l’entrée du Repaire des Grumegueules, au Berceau-de-l’Hiver.",al={"emplacement de salfa","où trouver salfa"}},{q="Que me demande Salfa ?",a="On vous demande de traverser le Repaire des Grumegueules, de sortir au Berceau-de-l’Hiver et de parler à Salfa.",al={"tâche de salfa","que faire pour salfa"}}},fp="14,116,11.139.0,13.58.0,23.75.0,30.93.0"}
P.entries["quest:8467"] = {n="Feathers for Nafien",s="Nafien rassemble des plumes et accueille chaque plume que vous parvenez à récupérer. En échange de votre aide, il promet que vos bonnes actions seront connues des siens.",h="Nafien rassemble des plumes et accueille chaque plume que vous parvenez à récupérer.",kw={"actions","plumes","nafien","offrandes","réputation"},sec={{t="Offrandes de plumage",b="Nafien cherche des plumes dans la nature et vous promet une bonne réputation auprès des siens en échange. Chaque fois que vous en trouvez, il les accueille et promet que votre aide sera vite connue de son peuple."}},faq={{q="Qui est Nafien ?",a="Nafien est une créature qui promet de parler en bien de vos actions auprès des siens en échange de plumes.",al={"qui est nafien","identité de nafien"}},{q="Pourquoi Nafien veut-il des plumes ?",a="Nafien cherche des plumes et s'engage à faire connaître votre aide parmi les siens pour chaque lot que vous lui apportez.",al={"pourquoi rassembler des plumes","utilité des plumes","à quoi servent les plumes"}},{q="Nafien acceptera-t-il d'autres plumes ?",a="Nafien prendra autant de plumes que vous pourrez en rassembler, tant que son peuple en aura besoin.",al={"plus de plumes","puis-je apporter plus de plumes","plumes à rapporter encore"}}},fp="19,177,20.220.0,14.101.0,30.117.0,39.88.0"}
P.entries["quest:847"] = {n="La ruse du raptor",s="L'orbe de Tor'gan a conféré à Gor'mul l'essence d'un rapace. Cette puissance l'amène à s'interroger sur la magie des chamans. Pour le moment, il écoutera Tor'gan.",h="L'orbe de Tor'gan a conféré à Gor'mul l'essence d'un rapace.",kw={"hautes-terres arathies","gor'mul","ruse du raptor","trépas-d'orgrim","chaman","tor'gan"},sec={{t="Un guerrier convaincu",b="Une puissance traverse Gor'mul, qui se demande si c'est celle des chamans que Tor'gan a tenté de lui montrer. Cette idée l'intéresse. Il vous demande donc de dire à Tor'gan qu'il est convaincu pour le moment et qu'il écoutera ce que Tor'gan a à dire."},{t="La réponse de Tor'gan",b="Tor'gan parlera à Gor'mul une fois l'enchantement dissipé. Il vous remercie d'avoir aidé à ramener Gor'mul parmi les vivants. Tor'gan pense que Gor'mul lui en est également reconnaissant."}},faq={{q="Qui vous envoie parler à Tor'gan ?",a="Gor'mul vous envoie parler à Tor'gan. Après avoir ressenti la puissance de l'orbe, il vous demande de dire qu'il est convaincu pour le moment.",al={"qui lance la ruse du raptor 3","qui donne cette quête","où cela commence"}},{q="Pourquoi Gor'mul change-t-il d'avis au sujet de Tor'gan ?",a="Gor'mul se demande si la puissance qu'il a ressentie venait des chamans, comme Tor'gan a tenté de le lui montrer. Cette idée l'intéresse : il est donc convaincu pour le moment et écoutera Tor'gan.",al={"pourquoi gor'mul a changé d'avis","gor'mul magie des chamans","gor'mul est-il convaincu"}},{q="Que s'est-il passé à l'étape précédente ?",a="À l'étape précédente, vous avez apporté l'orbe de Tor'gan à Gor'mul.",al={"quête précédente","prérequis ruse du raptor"}}},fp="19,142,19.218.0,15.169.1,36.115.0,47.176.0,27.57.0"}
P.entries["quest:848"] = {n="Spores fongiques",s="Aux oasis des Tarides, les aventuriers de la Horde récoltent des Spores fongiques pour l'Apothicaire Helbrim, de la Société royale des apothicaires. D'étranges énergies mutagènes traversent les sources et transforment les plantes locales en réactifs puissants. Helbrim veut récolter ces spécimens pour préparer des concoctions destinées à son collègue de Pitons-du-Tonnerre.",h="Aux oasis des Tarides, les aventuriers de la Horde récoltent des Spores fongiques pour l'Apothicaire Helbrim...",kw={"apothicaire helbrim","apothecary zamah","les tarides","la croisée","les bassins oubliés","spores fongiques","oasis luxuriante","société royale des apothicaires","l'oasis stagnante"},ang={["class:Druid"]="Les oasis abritent un afflux de magie naturelle anormalement tumultueux, qui provoque des mutations agressives dans l'écosystème alentour.",["faction:Horde"]="Enquêter sur les eaux perturbées des Tarides contribue à protéger les routes vitales reliant Orgrimmar, la Croisée et Pitons-du-Tonnerre.",["profession:Herbalism"]="Les champignons chargés qui poussent autour des oasis des Tarides montrent comment des apports soudains d'énergie environnementale peuvent transformer des plantes ordinaires en réactifs puissants.",["race:Undead"]="Loin de Lordaeron, les chercheurs réprouvés poursuivent leurs travaux alchimiques et mettent les anomalies naturelles de Kalimdor au service des objectifs de la Société royale des apothicaires."},sec={{t="Flore luxuriante et mutée",b="Les Tarides sont une savane aride, mais les Bassins oubliés, l'Oasis luxuriante et l'Oasis stagnante débordent de vie surnaturelle. Un curieux afflux d'énergie vitale traverse leurs eaux et déforme et revigore les plantes et les bêtes qui s'y abreuvent. Des champignons chargés poussent le long des berges boueuses et absorbent ces courants. Leurs spores possèdent de rares propriétés qui attirent les alchimistes de passage."},{t="La Société royale des apothicaires à Kalimdor",b="L'Apothicaire Helbrim travaille à la Croisée, loin de Fossoyeuse, mais reste dévoué aux recherches de la Société royale des apothicaires. Il récolte ces spores altérées, car les réactifs indigènes de Kalimdor ont une puissance étrange, puis les utilise pour préparer de puissants mélanges. Les spécimens sont destinés à Apothecary Zamah, à Pitons-du-Tonnerre, dans le cadre des travaux scientifiques des Réprouvés sur les terres de leurs alliés."}},faq={{q="Où poussent ces spores fongiques ?",a="Des champignons chargés poussent au bord de l'eau, dans les oasis des Tarides, notamment aux Bassins oubliés, à l'Oasis luxuriante et à l'Oasis stagnante.",al={"où trouver des spores fongiques","emplacement des spores fongiques","emplacement des champignons chargés"}},{q="Pourquoi les champignons sont-ils altérés près des oasis ?",a="Un puissant afflux d'énergie vitale traverse les eaux des oasis des Tarides. Il altère avec vigueur la faune et la flore alentour, au lieu de simplement favoriser la croissance ordinaire des plantes.",al={"pourquoi les champignons sont mutés","énergie vitale des oasis","que se passe-t-il dans les oasis"}},{q="Qui est l'Apothicaire Helbrim ?",a="L'Apothicaire Helbrim est un Réprouvé de la Société royale des apothicaires, posté à la Croisée, dans les Tarides. Il étudie la biologie inhabituelle de la région et récolte des matériaux locaux pour ses recherches alchimiques.",al={"histoire d'helbrim","qui est helbrim","apothicaire à la croisée"}},{q="Que compte faire Helbrim des spores ?",a="Helbrim utilise ces spores puissantes pour préparer une concoction destinée à son associé de recherche, Apothecary Zamah, à Pitons-du-Tonnerre.",al={"à quoi servent les spores","utilité des spores fongiques"}},{q="Pourquoi des apothicaires réprouvés travaillent-ils dans les Tarides ?",a="Alliés de la Horde, les chercheurs réprouvés étudient les environnements étrangers et la flore inhabituelle de Kalimdor, à la recherche de nouveaux réactifs pour des remèdes, des toxines et des concoctions.",al={"pourquoi des morts-vivants sont dans les tarides","société royale des apothicaires à kalimdor"}},{q="Quelle oasis est la plus sûre pour récolter les spores ?",a="Les Bassins oubliés, au nord-ouest de la Croisée, abritent une faune de niveau inférieur à celle de l'Oasis luxuriante ou de l'Oasis stagnante, au sud. C'est donc l'endroit le plus sûr pour récolter des champignons.",al={"oasis la plus facile pour récolter des spores","oasis la plus sûre des tarides"}}},fx={f81deb18={q="Pourquoi l'apothicaire Helbrim veut-il que les spores fongiques soient récoltées ?",a="L'apothicaire Helbrim étudie les étranges énergies vitales qui surgissent des oasis des Tarides, lesquelles font muter la flore et la faune environnantes. La Société royale des apothicaires trouve les propriétés puissantes de ces champignons altérés particulièrement précieuses pour leurs recherches. Helbrim a un besoin urgent de spécimens pour préparer une décoction spécifique qui doit être envoyée à son associée, l'apothicaire Zamah, stationnée aux Pitons-du-Tonnerre.",al={"pourquoi helbrim veut des spores","motif d'helbrim","pourquoi collecter des spores fongiques"}}},fp="13,297,25.365.0,40.385.0,34.129.0,45.170.0,26.205.0,45.124.0,55.155.0,49.175.0"}
P.entries["quest:849"] = {n="La revanche de Gann",s="À Bael Modan, Gann Cime-de-pierre retourne les plans des nains contre leur machine volante. Cet agent de la Horde veut venger sa tribu tombée.",h="À Bael Modan, Gann Cime-de-pierre retourne les plans des nains contre leur machine volante.",kw={"bael modan","bâton explosif de gann","machine volante","gann cime-de-pierre","khazgorm","tribu stonespire","les tarides","pitons-du-tonnerre"},ang={["faction:Horde"]="Pour la Horde, mettre hors d'état de nuire la machine volante de Bael Modan affaiblit une arme de l'Alliance capable d'observer et de frapper loin dans les Tarides du sud.",["profession:Engineering"]="Pour un ingénieur, cette charge retourne les plans de Forgefer contre un gyrocoptère, dans un acte de sabotage ingénieux sur le terrain.",["race:Tauren"]="Pour un tauren, détruire des machines de guerre naines afin de venger le clan Stonespire rappelle la défense des terres ancestrales contre leur profanation."},sec={{t="Un symbole de domination",b="Les fouilles naines de Bael Modan recouvrent les terres ancestrales des taurens Stonespire, chassés de chez eux. Les Prospecteurs dépendent d'un gyrocoptère pour étendre leur portée et leur puissance militaire. Il attend sur une tour de guet au-dessus du chantier, surveillant les Tarides et protégeant les lignes de ravitaillement des nains. Pour Gann, cette machine symbolise aussi l'intrusion de l'Alliance sur les terres kalimdoriennes."},{t="Retournée contre ses créateurs",b="Après avoir récupéré les plans du Prospector Khazgorm, Gann Cime-de-pierre fabrique une charge spéciale appelée Bâton explosif de Gann. Il la place sur la machine volante et retourne l'invention des nains contre eux. L'explosion détruit un atout militaire vital et humilie le contingent de Bael'dun. Elle rend aussi hommage aux esprits de la tribu perdue de Gann."}},faq={{q="Pourquoi Gann veut-il détruire spécifiquement la machine volante ?",a="La machine volante soutient l'infrastructure de Bael Modan et permet aux nains de mener des reconnaissances aériennes. Pour Gann, elle incarne la puissance naine et domine des terres qui furent autrefois le foyer de sa tribu massacrée.",al={"pourquoi détruire le gyrocoptère","rôle de la machine volante","pourquoi viser la machine volante"}},{q="Où se trouve la machine volante à Bael Modan ?",a="La machine volante se trouve sur une plateforme en bois, à mi-hauteur de la rampe qui mène à la fosse principale, à l'écart de la forteresse naine principale.",al={"où se trouve la machine volante","emplacement de la machine volante","emplacement du gyrocoptère à bael modan"}},{q="Comment Gann a-t-il créé l'engin explosif ?",a="Gann a fabriqué le Bâton explosif de Gann à partir des schémas techniques et des plans d'ingénierie récupérés auprès du Prospector Khazgorm. Il a retourné les propres plans des nains contre eux.",al={"comment la bombe a été fabriquée","origine du bâton explosif","plans de khazgorm pour l'explosif"}},{q="À quelle tribu Gann appartient-il ?",a="Gann appartient à la tribu Stonespire, un clan tauren qui vivait autrefois dans les Tarides du sud. Les fouilles des nains de Forgefer les ont chassés de force et ont détruit leur village.",al={"tribu de gann","qu'est-ce que la tribu stonespire","qui sont les taurens stonespire"}},{q="La destruction de la machine met-elle définitivement fin aux fouilles ?",a="La destruction de la machine affaiblit la puissance aérienne et l'infrastructure de Bael Modan, tout en permettant à Gann de se venger. Les nains, retranchés dans leurs fouilles et leur forteresse, restent une place forte active de l'Alliance dans la région.",al={"bael modan est-il à l'arrêt","bael modan tombe-t-il","gann a-t-il gagné"}},{q="Quelle reconnaissance Gann accorde-t-il à la fin de cette mission ?",a="Gann dit que le héros qui a détruit la machine sera vénéré à Pitons-du-Tonnerre comme un défenseur des terres sacrées des taurens et un champion durable de sa tribu perdue.",al={"fin de la mission de gann","fin de la quête de gann","que dit gann"}}},fx={["947c7a95"]={q="Qu'est-ce que la machine volante à Bael Modan ?",a="La cible est un gyrocoptère nain stationné au sein de Bael Modan. Construite et entretenue par l'expédition naine, cette machine volante constitue une infrastructure vitale pour leur excavation, sert d'arme de guerre aérienne et représente un symbole menaçant de l'intrusion naine qui a déplacé le peuple de Gann de son foyer ancestral.",al={"machine volante de bael modan","ce qu'est la cible dans revenge of gann","machine volante naine de bael modan"}}},fp="15,139,22.352.0,22.343.1,62.197.0,50.143.0,41.172.0,31.181.0,60.216.0,61.156.1"}
P.entries["quest:85"] = {n="Le collier perdu",s="Dans le sud de la Forêt d’Elwynn, Bernice Champierreux cherche son collier disparu. Elle soupçonne Billy Maclure, le jeune fils de la famille d’en face, et vous demande de le retrouver.",h="Dans le sud de la Forêt d’Elwynn, Bernice Champierreux cherche son collier disparu.",kw={"bernice","billy","elwynn","ferme","maclure","collier","champierreux","vignes"},ang={["faction:Alliance"]="En tant que novice de l’Alliance dans la Forêt d’Elwynn, vous découvrez la vie aux confins du royaume en réglant un différend mesquin entre les familles querelleuses Champierreux et Maclure.",["race:Human"]="En tant qu’humain, vous découvrez que les conflits du royaume de Hurlevent ne viennent pas seulement des hors-la-loi défias et des bandes de gnolls. Les vieilles querelles entre voisins de campagne sont elles aussi tenaces."},sec={{t="Une accusation de voisinage",b="Les Champierreux et les Maclure vivent sur des terres voisines dans le sud de la Forêt d’Elwynn, mais ils s’entendent peu. Lorsque « Tatie » Bernice Champierreux découvre que son précieux collier a disparu, elle accuse le plus jeune des Maclure. Convaincue que Billy Maclure est venu dans sa ferme pour le prendre, la veuve amère vous demande de traverser la route jusqu’aux vignes, de trouver le garçon et d’exiger qu’il le rende."},{t="Un garçon affamé",b="Au vignoble voisin, Billy Maclure nie avoir pris le collier et affirme qu’il n’est pas un voleur. Avec un sourire entendu, il laisse entendre qu’il sait peut-être où il se trouve. Mais d’abord, il veut qu’on apaise sa faim avec une tourte au porc fraîche."}},faq={{q="Qui est « Tatie » Bernice Champierreux ?",a="« Tatie » Bernice Champierreux est une veuve âgée qui vit à la ferme des Champierreux, dans le sud de la Forêt d’Elwynn. Elle se méfie de la famille Maclure voisine, surtout de leur jeune fils, Billy, qui sème le trouble.",al={"qui est tatie bernice","bernice champierreux","qui donne le collier perdu"}},{q="Billy Maclure a-t-il vraiment volé le collier ?",a="Billy Maclure nie fermement avoir volé le collier. Il laisse entendre qu’il sait qui l’a pris, mais refuse de révéler ce qu’il sait tant qu’on ne lui donne pas à manger.",al={"billy est-il un voleur","billy l’a-t-il volé","billy a-t-il pris le collier"}},{q="Où trouver Billy Maclure ?",a="Vous trouverez Billy Maclure parmi les vignes des Maclure, juste à l’est de la ferme des Champierreux, de l’autre côté de la route.",al={"emplacement de billy maclure","où est billy","trouver billy maclure"}},{q="Pourquoi les Champierreux et les Maclure ne s’aiment-ils pas ?",a="Les familles voisines Champierreux et Maclure sont prises depuis des années dans une âpre querelle de campagne. Les terres, l’orgueil et de vieilles rancunes personnelles entretiennent les tensions, si bien que chaque famille soupçonne l’autre du pire.",al={"querelle de famille","querelle champierreux maclure","pourquoi se détestent-ils"}},{q="Que se passe-t-il après avoir parlé à Billy Maclure ?",a="Billy dit qu’il a trop faim pour se rappeler où le collier est passé. Il vous renvoie auprès de « Tatie » Bernice pour qu’elle lui prépare une tourte au porc en échange de l’information.",al={"que faire ensuite","après le collier perdu","quête suivante"}},{q="Où se déroule cette quête ?",a="Vous traversez le sud de la Forêt d’Elwynn, entre la ferme des Champierreux et les vignes voisines des Maclure.",al={"zone de quête","où se trouve le collier perdu"}}},fx={b7900c48={q="Pourquoi Tatie Bernice veut-elle récupérer son collier ?",a="Tatie Bernice est une veuve âgée et le collier est un objet personnel profondément chéri. Le perdre l'angoisse, et elle soupçonne immédiatement la famille rivale d'à côté — en particulier le jeune Billy Maclure — de l'avoir volé. Récupérer l'héritage apporterait la tranquillité d'esprit et réchaufferait le cœur de la vieille veuve.",al={"pourquoi bernice veut le collier","motif du collier de bernice","importance du collier des stonefields"}},["27b02d6f"]={q="Pourquoi Tatie Bernice ne confronte-t-elle pas Billy Maclure elle-même ?",a="La querelle amère entre les Stonefields et les Maclure rend presque impossible pour l'un ou l'autre camp de parler civilement sans déclencher une bagarre. Bernice ne peut pas simplement se rendre aux Vignes des Maclure elle-même, et les gardes d'Hurlevent sont beaucoup trop occupés à gérer les gnolls et les bandits de la Confrérie défias pour arbitrer les petites querelles entre fermiers voisins. Un aventurier de passage offre une partie neutre qui peut interroger le garçon directement.",al={"pourquoi bernice a besoin de moi","pourquoi envoyer un aventurier vers billy","pourquoi ne pas demander aux gardes d'hurlevent"}}},fp="13,169,23.376.0,22.225.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.102.0"}
P.entries["quest:850"] = {n="Les chefs des Kolkars",s="Regthar Deathgate s'attaque aux chefs kolkars qui rassemblent leurs forces dans les Tarides. Depuis des générations, les centaures nomades tourmentent les taurens. À présent, de nouveaux chefs unissent des bandes dispersées pour en faire une menace militaire. Regthar envoie les champions de la Horde affronter Barak Kodobane aux Bassins oubliés avant que son influence ne s'étende.",h="Regthar Deathgate s'attaque aux chefs kolkars qui rassemblent leurs forces dans les Tarides.",kw={"barak","tarides","centaure","la croisée","deathgate","les bassins oubliés","kodobane","kolkar","regthar"},ang={["faction:Horde"]="En tant que membre de la Horde, vous dépendez des carrefours des Tarides, qui relient Mulgore, Durotar et les avant-postes lointains de la Horde. Briser le commandement kolkar protège les fragiles convois de ravitaillement des embuscades dévastatrices.",["race:Orc"]="En tant qu'orc, vous savez que Thrall a promis que la Horde défendrait les taurens. Des vétérans comme Regthar Deathgate honorent ce serment de sang et considèrent les centaures belliqueux comme une menace immédiate pour la souveraineté orque dans les Tarides.",["race:Tauren"]="En tant que tauren, abattre les commandants kolkars est une question de survie et de vengeance. Pendant des décennies, les clans centaures ont massacré des tribus et chassé les shu'halo de leurs pâturages ancestraux, avant que la Horde ne s'implante en Kalimdor."},sec={{t="Une menace grandissante dans les terres arides",b="Les centaures terrorisent Kalimdor depuis des temps immémoriaux. Avant l'arrivée de la Horde de Thrall, qui a renversé le cours des choses, ils ont presque exterminé les taurens nomades. Dans les Tarides, la tribu kolkar dominante erre généralement en bandes de maraudeurs dispersées. À présent, des chefs agressifs réunissent ces bandes et font de leurs pillards une force capable de défier les avant-postes fortifiés de la Horde."},{t="Décapiter la bête",b="Regthar Deathgate, un guerrier orc, est posté dans un campement à l'ouest de la Croisée. Il sait que l'audace et la force brute assurent la cohésion des Kolkars. Sans commandants puissants, leurs pillards s'entredéchirent. Regthar envoie donc les champions de la Horde affronter leurs chefs pour freiner leur avancée. Barak Kodobane, un chef ambitieux, est la première cible. Il campe près des eaux des Bassins oubliés."},{t="Le premier d'une longue série",b="La mort de Barak Kodobane affaiblit les campements kolkars du nord. Regthar sait que Barak n'est que le premier d'un mouvement plus vaste. Sa mort ouvre une campagne contre le haut commandement kolkar. Les prochains sont ses pairs, Verog the Dervish et Hezrul Bloodmark, dispersés dans les Tarides."}},faq={{q="Qui est Barak Kodobane ?",a="Barak Kodobane est un féroce chef centaure kolkar qui a rallié des maraudeurs autour des Bassins oubliés, au nord de la Croisée. Son intelligence et sa cruauté le rendaient plus dangereux que les pillards nomades ordinaires. Il a organisé des clans dispersés en une force offensive menaçant la Horde.",al={"barak","qui est barak","histoire de barak kodobane"}},{q="Où trouver Barak Kodobane ?",a="Barak Kodobane campe aux Bassins oubliés, une oasis au nord de la Croisée, dans le centre des Tarides. Des gardes kolkars loyaux l'escortent généralement.",al={"emplacement de barak","où se trouve barak","barak aux bassins oubliés"}},{q="Qui est Regthar Deathgate ?",a="Regthar Deathgate est un vétéran orc installé dans un petit camp fortifié juste à l'ouest de la Croisée. Il surveille les mouvements des centaures dans les Tarides et prépare des frappes préventives pour protéger les colonies de la Horde des raids organisés.",al={"regthar","qui donne la quête des chefs kolkars","histoire de regthar deathgate"}},{q="Pourquoi les Kolkars posent-ils un tel problème à la Horde ?",a="Depuis des générations, les centaures mènent une guerre impitoyable contre les taurens et les ont presque exterminés. En tant que membres de la Horde, les taurens comptent sur leurs alliés pour protéger leurs terres de chasse ancestrales et les routes commerciales des Tarides contre l'expansion continue des centaures.",al={"pourquoi combattre les kolkars","menace kolkar","rivalité entre centaures et horde"}},{q="Que se passe-t-il après la mort de Barak ?",a="La défaite de Barak Kodobane révèle que d'autres chefs rassemblent leurs forces ailleurs dans les Tarides. Regthar vous envoie ensuite traquer Verog the Dervish à l'oasis stagnante, puis Hezrul Bloodmark à l'Oasis luxuriante. Il faudra ensuite repousser une attaque directe des Kolkars.",al={"quête après barak","suite des chefs kolkars","what comes next"}},{q="Pourquoi les Kolkars se rassemblent-ils autour des oasis ?",a="Les Kolkars se rassemblent autour des oasis, car l'eau et les terres fertiles sont précieuses dans le climat aride des Tarides. En s'emparant de sources comme les Bassins oubliés, ils s'assurent un accès à l'eau et en privent les voyageurs et les chasseurs taurens, qui n'y trouvent plus de lieu de repos.",al={"pourquoi les centaures sont aux oasis","eau des kolkars","centaures des bassins oubliés"}}},fx={["55ee765d"]={q="Pourquoi Regthar Deathgate veut-il que les Kolkar leaders soient tués ?",a="Les tribus centaures harcèlent les taurens depuis des générations, mais les Kolkar des Tarides sont généralement fragmentés et désorganisés. Récemment, des chefs charismatiques ont commencé à rallier les bandes de guerre éparpillées en une menace unifiée contre les colonies de la Horde. Regthar sait que si ces commandants émergents sont autorisés à s'organiser, la présence de la Horde à travers les Tarides pourrait s'effondrer. Éliminer des personnages comme Barak Plaie-des-kodos frappe à la tête du soulèvement avant qu'il ne puisse submerger les défenses régionales.",al={"pourquoi tuer les kolkar leaders","motif de regthar deathgate","pourquoi regthar veut que ce soit fait"}},["4347847a"]={q="À quoi sert la tête de Barak ?",a="Regthar exige une preuve indéniable que le commandant centaure est tombé. Dans la dure frontière des Tarides, les rumeurs et les affirmations ne suffisent pas à garantir la sécurité. Apporter la tête tranchée de Barak confirme que la bande de guerre Kolkar campée près des Bassins oubliés a véritablement perdu son chef et sa volonté de coordonner d'autres assauts.",al={"pourquoi la tête de barak","but de la tête de barak","ce que je fais avec la tête de barak"}}},fp="14,323,31.376.0,22.400.0,17.282.1,22.270.0,32.143.0,25.212.0,48.271.0,35.253.1,42.224.0"}
P.entries["quest:851"] = {n="Verog le Derviche",s="Dans les Tarides du sud, Verog le Derviche ne cesse de se déplacer tandis que Regthar Deathgate tente de le faire sortir de sa cachette. L’orc envoie des champions de la Horde attaquer la tente de commandement des Kolkar à l’oasis stagnante pour attirer leur chef nomade à découvert.",h="Dans les Tarides du sud, Verog le Derviche ne cesse de se déplacer tandis que Regthar Deathgate tente de le...",kw={"tarides","centaure","la croisée","derviche","kolkar","regthar deathgate","l'oasis stagnante","verog"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que les oasis sont vitales pour survivre dans les Tarides arides. Vaincre les chefs centaures aide à garder les routes de l’eau ouvertes aux caravanes de ravitaillement.",["race:Orc"]="En tant qu’orc, vous savez que Regthar Deathgate considère la défaite des chefs de guerre kolkars comme essentielle pour sécuriser la route entre la Croisée et les Serres-Rocheuses, empruntée par les voyageurs de Durotar.",["race:Tauren"]="En tant que tauren, vous savez que les Kolkar ont chassé et harcelé votre peuple nomade sur ces plaines pendant des générations. L’exécution de Verog apporte une rétribution attendue depuis longtemps."},sec={{t="Attirer le Derviche",b="Après la chute de Barak Kodobane, Regthar Deathgate s’en est pris aux chefs de guerre kolkars encore debout. Barak restait près des eaux septentrionales des Bassins oubliés, mais Verog parcourt les plaines brûlées par le soleil et s’attarde rarement dans un même camp. Les éclaireurs de la Horde peinent à le suivre sur ces vastes terres. Ils doivent donc obliger le commandant à venir à eux."},{t="L’oasis stagnante",b="Verog opère depuis le poste de commandement kolkar à l’oasis stagnante, au sud-est de la Croisée. Regthar vous envoie attaquer le camp et frapper les guerriers kolkars près de leur tente de commandement. Leur signal d’alarme rappelle Verog pour défendre l’avant-poste. Là, les lames de la Horde peuvent l’atteindre."}},faq={{q="Qui est Verog le Derviche ?",a="Verog le Derviche dirige les centaures kolkars des Tarides. Il commande depuis l’oasis stagnante, mais parcourt les terres désolées du sud et reste difficile à coincer.",al={"qui est verog","histoire de verog","verog le derviche"}},{q="Pourquoi Verog ne reste-t-il pas dans son camp ?",a="Verog erre dans les Tarides au lieu de rester dans un même camp. Ses déplacements le rendent difficile à trouver pour les troupes de guerre de la Horde, alors ses ennemis doivent le provoquer pour le faire revenir.",al={"où se trouve verog","pourquoi verog erre","verog introuvable"}},{q="Comment faire apparaître Verog ?",a="Menacez la tribu de Verog au poste de commandement de l’oasis stagnante. Frappez les Kolkar près de leur tente de commandement, et l’alarme fera revenir Verog pour la défendre.",al={"comment faire apparaître verog","trouver verog","verog n’apparaît pas"}},{q="Qui ordonne la mort de Verog ?",a="Regthar Deathgate ordonne la mort de Verog. Ce vétéran orc campe à l’ouest de la Croisée, le long de la route principale menant aux Serres-Rocheuses. Il traque les chefs régionaux des Kolkar l’un après l’autre.",al={"qui donne la quête","regthar deathgate"}},{q="Que se passe-t-il après la chute de Verog ?",a="Après la chute de Verog, vous apportez sa tête tranchée à Regthar, qui la place à côté de celle de Barak Kodobane. Regthar se tourne ensuite vers Hezrul Bloodmark, le chef de guerre centaure de l’Oasis luxuriante, plus au sud.",al={"what comes next","après verog"}},{q="Pourquoi les centaures kolkars posent-ils tant de problèmes dans les Tarides ?",a="Les Kolkar menacent les Tarides en revendiquant des sources d’eau vitales et en attaquant caravanes, avant-postes et troupeaux de taurens natifs. Leurs attaques mettent en péril la présence naissante de la Horde au centre de Kalimdor.",al={"pourquoi combattre les kolkar","menace des kolkar"}}},fx={["42943e7a"]={q="Pourquoi Regthar Deathgate veut-il que Verog soit tué ?",a="Regthar Deathgate démantèle systématiquement le commandement des centaures Kolkar qui menace les Tarides du nord et La Croisée. Verog le Derviche commande la bande de guerre centaure basée autour de l'oasis stagnante. En l'éliminant, ainsi que les autres chefs Kolkar, Regthar vise à briser leur chaîne de commandement et à affaiblir leur emprise sur les oasis vitales avant que leurs forces ne puissent submerger les colonies de la Horde.",al={"pourquoi tuer verog","motif de regthar deathgate","pourquoi regthar veut la mort de verog"}},f05e98a6={q="À quoi sert la tête de Verog ?",a="Regthar Deathgate prend la tête tranchée de Verog comme preuve indéniable du décès du derviche. Il a l'intention de la monter sur une pique aux côtés de la tête de Barak Plaie-des-kodos à son avant-poste, servant à la fois de décompte des chefs ennemis tombés et d'avertissement sinistre à tout Kolkar approchant le long de la route à l'ouest de La Croisée.",al={"but de la tête de verog","ce que regthar fait avec la tête de verog","pourquoi prendre la tête de verog"}}},fp="17,236,23.334.0,18.273.0,25.141.0,35.159.0,24.147.0,25.187.0,31.193.1,57.195.0"}
P.entries["quest:852"] = {n="Hezrul Marque-de-sang",s="À l’Oasis luxuriante, Hezrul Marque-de-sang dirige les incursions kolkar à travers les Tarides. Regthar Deathgate vous envoie mettre fin à son commandement et briser l’emprise des centaures sur la région.",h="À l’Oasis luxuriante, Hezrul Marque-de-sang dirige les incursions kolkar à travers les Tarides.",kw={"marque-de-sang","centaure","la croisée","deathgate","hezrul","kolkar","oasis luxuriante","oasis","regthar"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que sécuriser la Croisée et les Tarides exige de briser l’emprise des centaures sur les trois grandes oasis qui permettent de traverser la région.",["race:Orc"]="En tant qu’orc, vous entendez Regthar Deathgate juger les Kolkar selon les méthodes de guerre des orcs. Les centaures sont féroces, mais leur fureur sauvage n’a pas la discipline de fer forgée par la Horde.",["race:Tauren"]="En tant que tauren, vous connaissez des générations de déplacements forcés et de massacres perpétrés par les centaures. Vaincre des seigneurs de guerre comme Hezrul apporte une rétribution durement gagnée."},sec={{t="Décapiter les Kolkar",b="Barak Kodobane et Verog the Dervish sont tombés. Hezrul Marque-de-sang reste le chef suprême des Kolkar dans les Tarides. Regthar Deathgate le décrit comme brutal et rusé, fer de lance des incursions centaures à travers la savane. La Horde espère que sa mort sèmera le chaos et brisera irréparablement les rangs kolkar avant qu’ils ne submergent les établissements de la Horde."},{t="Le bastion de l’Oasis luxuriante",b="Hezrul commande ses bandes de guerre depuis l’Oasis luxuriante, au sud de la Croisée. Les points d’eau sont rares dans les Tarides, et cette oasis est donc vitale à la survie. C’est aussi un carrefour stratégique et un point de rassemblement pour les pillards kolkar. Sur les terres mêmes d’Hezrul, vous privez les centaures de leur bastion le plus vital et brisez leur emprise sur les pistes méridionales."},{t="Des suites dangereuses",b="Regthar salue votre victoire sur Hezrul et fait remarquer que les centaures manquent de la discipline méthodique des orcs. Pourtant, les Kolkar ne se dispersent pas sans bruit. Enragés, ils rassemblent leurs forces restantes et lancent un assaut désespéré de grande envergure contre le campement de Regthar, en quête d’une vengeance sanglante."}},faq={{q="Qui est Hezrul Marque-de-sang ?",a="Hezrul Marque-de-sang mène les centaures kolkar à travers les Tarides. Féroce, rusé et brutal, il dirige leurs clans et leurs pillards depuis l’Oasis luxuriante.",al={"qui est hezrul","histoire d’hezrul marque-de-sang","chef des centaures des tarides"}},{q="Où trouver Hezrul Marque-de-sang ?",a="Hezrul patrouille dans le sud des Tarides, le long des rives de l’Oasis luxuriante, au sud de la Croisée, avec ses gardes du corps kolkar à ses côtés.",al={"où est hezrul","emplacement d’hezrul","où trouver hezrul"}},{q="Qui donne la quête pour tuer Hezrul ?",a="Regthar Deathgate, un guerrier orc, donne l’ordre dans un petit camp à l’ouest de la Croisée, sur la route des Serres-Rocheuses.",al={"qui donne hezrul marque-de-sang","quête de regthar deathgate","donneur de quête d’hezrul"}},{q="Pourquoi la Horde veut-elle la mort d’Hezrul ?",a="Les Kolkar menacent les routes commerciales et les établissements de la Horde. Regthar pense que tuer leur chef suprême brisera l’unité du clan et affaiblira considérablement sa capacité à mener une guerre coordonnée.",al={"pourquoi tuer hezrul","objectif d’hezrul marque-de-sang","menace kolkar dans les tarides"}},{q="Que se passe-t-il après la mort d’Hezrul ?",a="Les Kolkar survivants refusent de se rendre. Unis par la fureur, ils lancent une contre-attaque immédiate contre l’avant-poste de Regthar Deathgate, à l’ouest de la Croisée.",al={"contre-attaque après hezrul","que se passe-t-il ensuite","conséquences de la mort d’hezrul"}},{q="Quel est le lien entre Hezrul, Barak et Verog ?",a="Barak Kodobane et Verog the Dervish dirigeaient chacun des oasis et des bandes de guerre en tant que subordonnés kolkar. Hezrul Marque-de-sang commandait tout le clan à travers les Tarides.",al={"barak verog hezrul","chefs kolkar","trois chefs centaures"}}},fx={ca31e908={q="À quoi sert la tête d'Hezrul ?",a="Regthar Deathgate exige la tête d'Hezrul comme preuve incontestable que le chef suprême des Kolkar des Tarides est tombé. Tout comme avec Barak Plaie-des-kodos et Verog le Derviche avant lui, rapporter la tête tranchée confirme à la Horde que le commandement centaure a été brisé et la menace interrompue.",al={"utilisation de la tête d'hezrul","pourquoi prendre la tête d'hezrul","tête d'hezrul"}}},fp="16,177,23.354.0,24.339.0,21.276.1,24.147.0,36.133.0,35.135.0,36.193.0,35.158.1,42.157.0"}
P.entries["quest:853"] = {n="L'apothicaire Zamah",s="Aux Pitons-du-Tonnerre, l'apothicaire Zamah attend une préparation fragile venue des Tarides. Elle doit lui parvenir dans son laboratoire, sous la Cime des Esprits, avant de perdre son efficacité.",h="Aux Pitons-du-Tonnerre, l'apothicaire Zamah attend une préparation fragile venue des Tarides.",kw={"apothicaire helbrim","l'apothicaire zamah","spores fongiques","les bassins de la vision","spores fondues","société royale des apothicaires","cime des esprits","les tarides","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous contribuez à maintenir les communications et l'approvisionnement entre les avant-postes des Tarides et la haute mesa des Pitons-du-Tonnerre.",["race:Tauren"]="En tant que Tauren, vous pouvez accueillir les Réprouvés comme des alliés tout en observant avec méfiance leurs étranges préparations dans les sacrés Bassins de la Vision.",["race:Undead"]="En tant que Mort-vivant, vous apportez les travaux d'Helbrim à Zamah et renforcez le réseau de recherche clandestin de la Société royale des apothicaires dans les confins du centre de Kalimdor."},sec={{t="Une cargaison fragile",b="L'apothicaire Helbrim a transformé des floraisons fongiques des oasis des Tarides en une émulsion délicate. La préparation s'affaiblit peu après sa fabrication. Helbrim ne peut pas rejoindre Mulgore à temps ; il confie donc la fiole à un messager fiable en route pour les Pitons-du-Tonnerre."},{t="Sous le regard des chamans",b="L'apothicaire Zamah travaille dans les Bassins de la Vision, une caverne sous les hauteurs sacrées de la Cime des Esprits. Des mages et des prêtres réprouvés partagent ce refuge souterrain. Sous le sanctuaire tauren, la Société royale des apothicaires étudie discrètement des matières premières récoltées sur tout le continent."}},faq={{q="Pourquoi cette livraison est-elle urgente ?",a="L'émulsion fongique d'Helbrim est chimiquement instable. Si on la laisse trop longtemps à l'air libre ou sans traitement, ses composés se dégradent et perdent leur efficacité, la rendant inutile pour les travaux de Zamah.",al={"pourquoi un délai","délai de la quête","délai des spores fondues"}},{q="Où puis-je trouver l'apothicaire Zamah ?",a="L'apothicaire Zamah se trouve dans les Bassins de la Vision, aux Pitons-du-Tonnerre. L'entrée de la caverne est cachée sur la Cime des Esprits, sous les tentes des chamans.",al={"où est zamah","emplacement de zamah","trouver zamah"}},{q="Qui est l'apothicaire Helbrim ?",a="L'apothicaire Helbrim est un alchimiste de la Société royale des apothicaires, installé à La Croisée, dans les Tarides. Il étudie la flore et la faune locales pour découvrir comment les formes de vie indigènes de Kalimdor pourraient servir les Réprouvés.",al={"qui est helbrim","helbrim à la croisée"}},{q="Que fait la Société royale des apothicaires aux Pitons-du-Tonnerre ?",a="La Société royale des apothicaires étudie discrètement des spécimens recueillis sur Kalimdor, dans les Bassins de la Vision aux Pitons-du-Tonnerre. Les Réprouvés, alliés de la Horde, y maintiennent des représentants comme Zamah et des liens d'approvisionnement avec d'autres avant-postes.",al={"pourquoi des réprouvés aux pitons-du-tonnerre","apothicaires aux bassins de la vision"}},{q="À quoi servaient les spores fongiques à l'origine ?",a="Les spores fongiques poussent autour des oasis luxuriantes des Tarides et prospèrent dans le désert. Helbrim les a réduites pour étudier leurs propriétés biologiques et leurs usages alchimiques avant de les envoyer à Zamah.",al={"pourquoi les spores","usage des champignons des tarides"}},{q="Que se passe-t-il si le délai expire ?",a="À l'expiration du délai, l'émulsion se gâte et perd son efficacité. Vous devez retourner auprès de l'apothicaire Helbrim, à La Croisée, pour récupérer une nouvelle préparation à apporter aux Pitons-du-Tonnerre.",al={"délai expiré","spores périmées"}}},fx={f0da41d1={q="Pourquoi l'apothicaire Helbrim veut-il que les spores fondues soient livrées si rapidement ?",a="L'apothicaire Helbrim a réussi à traiter les étranges spores fongiques récoltées dans les Tarides en une émulsion instable. Le mélange se dégrade rapidement, et seule son associée, l'apothicaire Zamah, dispose des réactifs spécialisés et des installations dans Les Bassins de la Vision nécessaires pour stabiliser, reseeller et analyser correctement le tout avant que sa puissance ne soit perdue à jamais.",al={"pourquoi envoyer des spores à zamah","motif d'helbrim","pourquoi helbrim veut que ce soit livré"}}},fp="16,153,15.241.0,30.269.0,43.165.0,34.139.0,26.209.0,60.238.0,48.184.0,35.165.0"}
P.entries["quest:854"] = {n="Un voyage à la Croisée",s="Au Camp Taurajo, Kirge Corne-sévère envoie les voyageurs vers le nord pour aider Thork à La Croisée. Leur route quitte Mulgore et traverse les Tarides, où les luttes de la Horde s’intensifient.",h="Au Camp Taurajo, Kirge Corne-sévère envoie les voyageurs vers le nord pour aider Thork à La Croisée.",kw={"tarides","camp taurajo","la croisée","terre-mère","kirge corne-sévère","thork","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous voyez la coopération grandir entre les tribus des Pitons-du-Tonnerre et l’avant-garde du chef de guerre au centre de Kalimdor.",["race:Orc"]="En tant qu’orc, vous savez que Thork a besoin de renforts venus du sud pour tenir le terrain que les éclaireurs de Thrall ont sécurisé dans les Tarides.",["race:Tauren"]="En tant que tauren, vous quittez le refuge de la mesa sacrée de la Terre-Mère et prenez part aux luttes plus vastes de la Horde."},sec={{t="Quitter le berceau",b="Au Camp Taurajo, bien des taurens découvrent les Tarides au-delà de Mulgore. Juste après le col, le mystique Kirge Corne-sévère observe les voyageurs descendre dans les prairies arides. Quand Kirge en voit un prêt à aller plus loin, il lui indique le nord, le long de la route commerciale poussiéreuse, jusqu’à La Croisée."},{t="Un lien partagé",b="Les taurens des Pitons-du-Tonnerre et la nouvelle Horde de Thrall partagent désormais leur destin. Kirge affirme que leurs sorts sont liés, et les orcs de La Croisée ont besoin de renforts pour établir un avant-poste. À la colonie, Thork accueille les voyageurs venus même des hautes mesas. Il est prêt à éprouver leur force face aux dangers de la savane."}},faq={{q="Qui donne la quête Un voyage à la Croisée ?",a="Kirge Corne-sévère, un mystique tauren du Camp Taurajo, envoie les voyageurs vers le nord. Le camp se trouve dans les Tarides du sud, juste à l’est du col de montagne qui mène depuis Mulgore.",al={"qui donne cette quête","donneur de quête","quête de kirge corne-sévère"}},{q="Où se trouve Thork ?",a="Thork se trouve derrière les murs de la palissade, à La Croisée, la colonie de la Horde au centre des Tarides. Elle se trouve au nord du Camp Taurajo, le long de la route principale.",al={"où se trouve thork","emplacement de thork","trouver thork"}},{q="Pourquoi Kirge Corne-sévère envoie-t-il les voyageurs à La Croisée ?",a="Kirge Corne-sévère voit qu’un voyageur est prêt à affronter de plus grandes épreuves et sait que les destins des taurens et des orcs sont désormais liés. La garnison orque de La Croisée subit les attaques constantes des menaces locales et a besoin d’alliés capables.",al={"pourquoi aller à la croisée","but de la croisée","pourquoi m’envoyer chez les orcs"}},{q="Qu’est-ce que La Croisée ?",a="La Croisée est le principal centre stratégique et comptoir commercial de la Horde au centre de Kalimdor. Les routes du nord au sud et d’est en ouest s’y rejoignent, et la colonie sert de base pour mettre de l’ordre dans la frontière sauvage.",al={"qu’est-ce que la croisée","colonie de la croisée","centre des tarides"}},{q="Seuls les taurens reçoivent-ils cette tâche ?",a="Oui. Kirge Corne-sévère n’envoie que des taurens dans ce voyage. Il accueille les siens venus d’aussi loin que des Pitons-du-Tonnerre et leur demande de se présenter à Thork.",al={"quête réservée aux taurens","quête d’orientation de la horde"}},{q="Quels dangers menacent la route vers La Croisée ?",a="La route vers le nord traverse des plaines arides où rôdent des plainstriders agressifs, des lions de savane en chasse et des bandes de quilboars Razormane. En restant sur le chemin battu, les voyageurs évitent les prédateurs les plus territoriaux du centre de la savane.",al={"la route est-elle dangereuse","itinéraire de taurajo à la croisée"}}},fx={fc69c860={q="Pourquoi Kirge Corne-sévère vous choisit-il pour ce voyage ?",a="Kirge Corne-sévère prévoit votre venue et reconnaît que vous avez dépassé les épreuves locales. Sentant que vous êtes destiné à de plus grands exploits à travers les terres de la Horde, il vous voit comme l'émissaire idéal pour aller de l'avant et aider vos alliés orcs.",al={"pourquoi moi pour journey to the crossroads","pourquoi kirge me choisit","pourquoi m'envoyer à la croisée"}}},fp="25,171,18.279.0,13.352.0,37.156.0,23.149.0,58.220.0,23.203.0,33.137.0,52.239.0"}
P.entries["quest:855"] = {n="Bracelets de centaure",s="À l’ouest de La Croisée, Regthar Deathgate cherche des preuves contre les Kolkar. Leurs raids menacent le contrôle de la Horde sur le centre des Tarides.",h="À l’ouest de La Croisée, Regthar Deathgate cherche des preuves contre les Kolkar.",kw={"tarides","prime","bracelets","centaure","la croisée","horde","kolkar","regthar deathgate"},ang={["faction:Horde"]="Éliminer les Kolkar protège les voies de ravitaillement entre Orgrimmar et Pitons-du-Tonnerre.",["race:Orc"]="En tant qu’orc, vous contribuez à protéger les frontières de Durotar contre les pillards nomades et à établir une patrie permanente et stable.",["race:Tauren"]="En tant que tauren, vous savez que les centaures ont ravagé les tribus taurènes et perpétré un génocide contre elles pendant des siècles. Réduire leurs rangs dans les Tarides est une vengeance personnelle."},sec={{t="Sécuriser les plaines",b="La jeune Horde sécurise encore ses terres à travers Kalimdor. Les Tarides s’étendent entre Durotar et Mulgore, où les centaures Kolkar se disputent les points d’eau et les plaines. Ils attaquent les convois de ravitaillement et les groupes d’éclaireurs. Depuis son bunker à l’ouest de La Croisée, le guerrier orc Regthar Deathgate dirige la défense."},{t="Un sinistre décompte",b="Regthar demande des preuves que des guerriers kolkars sont tombés. Les soldats qui pénètrent en territoire kolkar reviennent avec des bracelets pris aux centaures tués. Ces trophées justifient les demandes de primes de la Horde, et Regthar espère qu’ils effraieront les pillards survivants."}},faq={{q="Qui est Regthar Deathgate ?",a="Regthar Deathgate est un commandant orc installé dans un bunker fortifié à l’ouest de La Croisée. Il dirige les efforts de la Horde pour réprimer les raids des centaures dans les Tarides.",al={"qui est regthar","histoire de regthar deathgate","qui donne les bracelets de centaure"}},{q="Pourquoi la Horde veut-elle des bracelets de centaure ?",a="Les bracelets de centaure prouvent que des guerriers ennemis sont tombés au combat. Regthar s’en sert pour s’assurer que seules les personnes ayant réellement tué des Kolkar hostiles reçoivent une prime.",al={"pourquoi des bracelets","à quoi servent les bracelets de centaure","pourquoi ramasser les bracelets"}},{q="Pourquoi les Kolkar attaquent-ils la Horde ?",a="Les Kolkar sont un clan de centaures brutal originaire du centre de Kalimdor, qui cherche à étendre son territoire. Ils revendiquent les Tarides comme territoire de chasse et combattent les nouvelles colonies, les camps et les alliances formés par les orcs et les taurens.",al={"pourquoi les centaures détestent la horde","conflit avec les centaures","agressivité des kolkar"}},{q="Où se trouvent les centaures Kolkar dans les Tarides ?",a="Les camps de pillards kolkars se trouvent autour des oasis et des crêtes escarpées du centre et du sud des Tarides. Les centaures se disputent souvent l’accès à l’eau et aux routes de la région.",al={"où trouver des centaures","emplacements des kolkar","camps de centaures"}},{q="La collecte de ces bracelets met-elle fin aux attaques des Kolkar ?",a="Non. Regthar espère que ces pertes effraieront les pillards survivants, mais il doute que les Kolkar cessent volontairement leurs attaques.",al={"les bracelets de centaure ont-ils été efficaces","les centaures arrêtent-ils leurs attaques"}},{q="Quelle est l’importance stratégique de La Croisée ?",a="La Croisée relie Durotar, les plaines taurènes de Mulgore et les routes du nord vers Orneval. Vaincre les groupes de guerre centaures des environs contribue à préserver les lignes de ravitaillement de la Horde.",al={"pourquoi défendre la croisée","importance de la croisée"}}},fx={["5627e76a"]={q="Pourquoi Regthar Deathgate veut-il que des Bracelets de centaure soient collectés ?",a="Regthar Deathgate considère les centaures Kolkar comme une menace directe pour la présence de la Horde à travers les Tarides. En offrant une prime sur leurs bracelets, il vise à réduire leurs rangs combattants par simple usure, espérant que les lourdes pertes sèmeront la peur dans les clans survivants et émousseront leurs assauts continus.",al={"pourquoi regthar veut des bracelets","motif de regthar deathgate","pourquoi des bracelets de centaure"}},["566bd14b"]={q="Qui sont les centaures Kolkar que l'on vous envoie combattre ?",a="Vous êtes dépêché contre le clan Kolkar, une race brutale de centaures qui domine des oasis clés à travers les Tarides centrales et méridionales. Férocement territoriaux et sanguinaires, ils font la guerre à la fois aux taurens et aux orcs nouvellement arrivés pour chasser complètement la Horde des plaines de Kalimdor.",al={"qui sont les kolkar","quels centaures sont dans les tarides","qui est la cible des bracelets de centaure"}}},fp="15,132,19.328.0,21.249.0,25.157.0,40.169.0,39.210.0,53.170.0,54.125.0,46.170.0"}
P.entries["quest:8551"] = {n="Le coffre du capitaine",s="Le coffre perdu de Smotts se trouve chez un géant des mers après un naufrage près de Baie-du-Butin. Le Capitaine Hecklebury Smotts naviguait autrefois entre Baie-du-Butin et Cabestan, en Kalimdor. Des géants des mers ont détruit son navire et tué l’équipage, puis l’ont envoyé vers Baie-du-Butin dans un canot de sauvetage. Gorlash s’est emparé de son Captain's Chest, et Smotts veut maintenant le récupérer.",h="Le coffre perdu de Smotts se trouve chez un géant des mers après un naufrage près de Baie-du-Butin.",kw={"baie-du-butin","gorlash","cabestan","géant des mers","smotts","tabatière","vallée de strangleronce"},sec={{t="Un capitaine brisé",b="Le Capitaine Hecklebury Smotts naviguait autrefois entre Baie-du-Butin et Cabestan, en Kalimdor, et s’était forgé une belle réputation. Puis des géants des mers ont détruit son navire et tué l’équipage. Ils ont envoyé Smotts vers Baie-du-Butin dans un canot de sauvetage, et il a laissé derrière lui ses voyages et sa bonne réputation."},{t="Le coffre volé",b="Gorlash s’est emparé du Captain's Chest de Smotts, disant qu’il le voulait pour en faire une tabatière. Ce coffre était le préféré de Smotts, et un compartiment secret contenait ses plus grands trésors. Smotts a entendu dire que Gorlash rôde sur le rivage à l’est de Baie-du-Butin."},{t="Les remerciements de Smotts",b="Smotts est fou de joie d’avoir récupéré son coffre, et son retour atténue un peu sa colère. Sa vengeance n’est toujours pas accomplie."}},faq={{q="Qui est le Capitaine Hecklebury Smotts ?",a="Le Capitaine Hecklebury Smotts est un capitaine de navire à Baie-du-Butin. Il naviguait autrefois entre Baie-du-Butin et Cabestan, en Kalimdor, jusqu’à ce que des géants des mers détruisent son navire et tuent l’équipage.",al={"capitaine smotts","qui est smotts","hecklebury smotts"}},{q="Qui a pris le coffre ?",a="Gorlash, l’un des géants des mers, a pris le coffre de Smotts et a dit qu’il le voulait pour en faire une tabatière.",al={"qui a volé le coffre","qui a le coffre de smotts","gorlash"}},{q="Où trouver Gorlash ?",a="Sur le rivage à l’est de Baie-du-Butin, d’après Smotts.",al={"où est gorlash","emplacement de gorlash","trouver gorlash"}},{q="Pourquoi Smotts veut-il récupérer le coffre ?",a="Smotts veut récupérer son coffre parce que c’était son préféré et que son compartiment secret contenait ses plus grands trésors.",al={"que contient le coffre","pourquoi smotts veut-il le coffre"}}},fp="19,310,16.259.0,16.224.0,14.125.1,33.170.0,19.87.0,27.55.0,36.112.0"}
P.entries["quest:8552"] = {n="L'écharpe à monogramme",s="Dans la Vallée de Strangleronce, une écharpe perdue porte des initiales qui pourraient mener à son propriétaire. Retrouver le marin qui l'a égarée mène à The Captain's Cutlass.",h="Dans la Vallée de Strangleronce, une écharpe perdue porte des initiales qui pourraient mener à son...",kw={"hecklebury smotts","hs","mok'rash","écharpe à monogramme","géant des mers","vallée de strangleronce"},sec={{t="Un vêtement marqué",b="Vous trouvez une belle écharpe dont l'ourlet porte les initiales HS brodées. Ces deux lettres sont le seul indice permettant d'identifier la personne qui l'a perdue."},{t="Le lien avec Smotts",b="En rendant l'écharpe au capitaine Hecklebury Smotts, vous confirmez qu'elle lui appartient. En la récupérant, le capitaine apprend que le géant des mers Mok'rash a été tué. Cette brute avait contribué à détruire ses navires et son équipage à plusieurs reprises, et cette nouvelle le soulage."}},faq={{q="Quelles lettres sont brodées sur l'écharpe ?",a="Les initiales HS sont brodées sur l'ourlet de l'écharpe.",al={"initiales sur l'écharpe","initiales sur l'écharpe à monogramme","lettres sur l'écharpe"}},{q="Quelle est la suite ?",a="Après avoir rendu l'écharpe à son propriétaire, la suite mène à The Captain's Cutlass.",al={"quelle quête après l'écharpe à monogramme","quête suivante de l'écharpe à monogramme","étape suivante"}}},fp="20,145,16.120.0,21.255.1,40.49.0,26.85.0"}
P.entries["quest:8553"] = {n="Le sabre du capitaine Smott",s="À bord du Smotts' Revenge, le capitaine Hecklebury Smotts essuie une nouvelle défaite en mer. Des géants marins fracassent son second navire, tuent l'équipage et emportent son coutelas. Il vous envoie consulter Sprogger, son ancien cuisinier, pour retrouver le colosse.",h="À bord du Smotts' Revenge, le capitaine Hecklebury Smotts essuie une nouvelle défaite en mer.",kw={"coutelas","hecklebury smotts","negolash","géants marins","smotts revenge","sprogger","vallée de strangleronce"},sec={{t="Un nouveau désastre",b="Après avoir perdu son premier navire, le capitaine Hecklebury Smotts en acheta un autre et le baptisa Smotts' Revenge. Il rassembla un nouvel équipage et des provisions pour traquer les géants marins qui avaient pris son premier navire. Les géants fracassèrent le bateau et tuèrent l'équipage. Une fois de plus, Smotts se retrouva à la dérive dans un canot de sauvetage, et Negolash lui prit son coutelas pendant l'attaque."},{t="Consulter le cuisinier",b="Le capitaine Hecklebury Smotts veut récupérer son coutelas volé et se tourne donc vers Sprogger. Sprogger était le cuisinier à bord du Smotts' Revenge et a survécu à l'attaque. Il peut vous aider à retrouver Negolash."}},faq={{q="Quel navire le capitaine Hecklebury Smotts a-t-il perdu lors de cette attaque ?",a="Le capitaine Hecklebury Smotts a acheté et équipé le Smotts' Revenge pour traquer les géants marins qui avaient pris son premier navire. Les géants ont également détruit ce bateau.",al={"comment s'appelait le second navire","second navire de smotts","quel navire a été fracassé"}},{q="Qui a volé le coutelas du capitaine ?",a="Negolash, l'un des géants marins, a pris le coutelas du capitaine lorsque les géants ont fracassé le Smotts' Revenge et tué son équipage.",al={"qui a le coutelas","quel géant a pris le coutelas","qui a pris le coutelas de smotts"}},{q="Qui est Sprogger ?",a="Sprogger était le cuisinier à bord du Smotts' Revenge et a survécu à l'attaque qui a détruit le navire. Le capitaine Smotts vous demande de le consulter pour vous aider à retrouver Negolash.",al={"qui est sprogger","rôle de sprogger","qui était le cuisinier"}},{q="À quelle étape de la traque des géants marins cela correspond-il ?",a="Cette étape suit The Monogrammed Sash et mène directement à Facing Negolash.",al={"quelle quête précède celle-ci","quelle est la quête suivante","suite de quêtes du coutelas"}}},fp="21,216,17.330.0,19.188.0,60.148.0,32.120.0,16.170.0,58.77.0"}
P.entries["quest:8555"] = {n="Le fardeau des Vols draconiques",s="À Tanaris, Anachronos vous retrouve alors que la première partie du Sceptre des Sables changeants touche à sa fin. Cette suite mène à l'ouverture des Portes d'Ahn'Qiraj.",h="À Tanaris, Anachronos vous retrouve alors que la première partie du Sceptre des Sables changeants touche à sa...",kw={"anachronos","azuregos","eranikus","portes d'ahn'qiraj","sceptre des sables changeants","tanaris","vaelastrasz"},sec={{t="La fin du commencement",b="Anachronos vous retrouve à Tanaris pour conclure la première partie du Sceptre des Sables changeants. Cette suite mène à l'ouverture des Portes d'Ahn'Qiraj."},{t="Les trois veilleurs",b="Anachronos nomme Eranikus, Vaelastrasz et Azuregos, trois dragons qui veillaient sur le monde. Tous ont connu un drame causé par les agents des Dieux très anciens ou par la trahison de ceux qu'ils croyaient leurs amis.\n\nAnachronos reconnaît que sa propre naïveté le rend en partie responsable. Ces événements ont nourri sa méfiance envers les mortels. Il vous envoie donc retrouver les trois dragons et vous préparer au pire."}},faq={{q="Qui est Anachronos ?",a="Anachronos est un dragon du Vol draconique de bronze que vous rencontrez à Tanaris.",al={"qui est anachronos","anachronos tanaris","dragon de bronze"}},{q="Qu'est-ce que le Sceptre des Sables changeants ?",a="Le Sceptre des Sables changeants est une longue suite qui mène à l'ouverture des Portes d'Ahn'Qiraj. Votre rencontre avec Anachronos en conclut la première partie.",al={"suite du sceptre","sceptre des sables changeants","suite des portes d'ahn'qiraj"}}},fp="31,167,24.155.0,18.387.1,18.75.0,42.155.0"}
P.entries["quest:8569"] = {n="Efforts passés dans le goulet des Chanteguerres",s="Dans le Goulet des Chanteguerres, les soldats tiennent la frontière sud d’Orneval, tandis que les commandants honorent leurs sacrifices. Le Ribbon of Sacrifice témoigne d’un service indéfectible, même quand la bataille n’apporte aucune victoire nette.",h="Dans le Goulet des Chanteguerres, les soldats tiennent la frontière sud d’Orneval, tandis que les commandants...",kw={"orneval","brigadier général","orgrimmar","efforts passés","ribbon of sacrifice","hurlevent","belluaire","goulet des chanteguerres"},ang={["class:Warrior"]="En tant que guerrier, vous connaissez les brutales mêlées du goulet. La discipline, c’est se battre avec acharnement même quand l’issue reste incertaine.",["faction:Alliance"]="En tant que soldat de l’Alliance, remettre un ruban à un brigadier général confirme votre engagement à défendre les forêts anciennes et à soutenir vos alliés kaldorei face à l’agression des Chanteguerre.",["faction:Horde"]="En tant que membre de la Horde, remettre une marque à un belluaire confirme que le sang versé pour obtenir du bois et survivre en Orneval n’a pas été gaspillé."},sec={{t="Honorer les morts et les valeureux",b="Le long de la frontière sud d’Orneval, les Sentinelles d’Aile-argent et les Voltigeurs Chanteguerre livrent de brutales escarmouches. Nombre de batailles s’achèvent sans victoire nette. Hurlevent, Orgrimmar et d’autres capitales honorent ceux qui tiennent bon contre vents et marées. Le Ribbon of Sacrifice distingue les combattants qui se sont consacrés à la lutte."},{t="L’effort de guerre à l’arrière",b="Loin du front, les brigadiers généraux de l’Alliance et les belluaires de la Horde supervisent leurs forces. Les recruteurs envoient de nouveaux combattants au Goulet des Chanteguerres, tandis que les intendants et les tacticiens comptabilisent les vétérans de retour de campagnes éprouvantes. En honorant le courage dans l’impasse ou la défaite, les chefs aident les soldats à rester déterminés à tenir Orneval."}},faq={{q="À quoi sert cette distinction ?",a="Le Ribbon of Sacrifice honore les combattants qui ont tout donné au Goulet des Chanteguerres. Les commandants des capitales l’acceptent pour saluer leur persévérance et soutenir le moral des troupes.",al={"pourquoi les efforts passés","but des efforts passés","que signifient les efforts passés"}},{q="Qui accepte ces marques de sacrifice ?",a="Les brigadiers généraux de l’Alliance et les belluaires de la Horde acceptent ces marques dans les grandes villes, notamment à Hurlevent et à Orgrimmar.",al={"qui accepte les efforts passés","où remettre les efforts passés","qui est le brigadier général"}},{q="Pourquoi l’armée récompense-t-elle les efforts qui n’ont pas mené à la victoire ?",a="Les combats dans les forêts d’Orneval font de nombreuses victimes. Honorer le dévouement des soldats montre que leur sacrifice compte, même s’ils ne remportent pas la victoire.",al={"pourquoi récompenser le ribbon of sacrifice","pourquoi récompenser une défaite","sens d’un effort héroïque"}},{q="Où se déroule le conflit du Goulet des Chanteguerres ?",a="Le Goulet des Chanteguerres se trouve le long de la frontière sud d’Orneval. Les Voltigeurs Chanteguerre y récoltent du bois, tandis que les Sentinelles d’Aile-argent leur résistent.",al={"où se trouve le goulet des chanteguerres","emplacement du goulet des chanteguerres","qu’est-ce que le goulet des chanteguerres"}},{q="Les membres de l’Alliance et de la Horde peuvent-ils tous entreprendre cette tâche ?",a="Oui. Les deux factions honorent les soldats de retour par l’intermédiaire de leurs chefs militaires dans leurs capitales respectives.",al={"pour les deux factions","efforts passés de la horde ou de l’alliance","la horde peut-elle remettre cet objet"}},{q="Que représente le Ribbon of Sacrifice ?",a="Le Ribbon of Sacrifice honore les combattants qui ont enduré de violents affrontements au Goulet des Chanteguerres et sont restés prêts à se battre pour leur peuple.",al={"histoire du ribbon of sacrifice","qu’est-ce que le ribbon of sacrifice","ruban du sacrifice"}}},fp="29,193,35.318.0,22.329.0,41.158.0,38.119.0,66.147.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="La larme des lunes",s="À Bael Modan, Feegly l'Exilé réclame encore la larme des lunes, le vestige qui l'a rendu fou.",h="À Bael Modan, Feegly l'Exilé réclame encore la larme des lunes, le vestige qui l'a rendu fou.",kw={"bael modan","les tarides","malédiction naine","feegly","feegly l'exilé","général twinbraid","larme des lunes"},ang={["faction:Horde"]="En frappant Bael Modan pour récupérer le vestige, la Horde a l'occasion de perturber les opérations des nains qui empiètent sur les Tarides."},sec={{t="Découverte à Bael Modan",b="Les nains ont découvert la larme des lunes en creusant les collines du sud de Kalimdor pour bâtir Bael Modan. C'était la première découverte majeure de l'expédition. Son étrange influence s'est aussitôt exercée sur Feegly, l'un des ouvriers."},{t="La quarantaine de Twinbraid",b="Feegly affirmait que la larme lui conférait un immense pouvoir. Il s'est violemment retourné contre ses compagnons pour la protéger. Le général Twinbraid a vu l'emprise corruptrice du vestige, l'a déclaré maudit, l'a retiré à Feegly et l'a enfermé dans le donjon. Banni du camp de fouilles, Feegly a trouvé refuge parmi les falaises. Amer et obsédé, il supplie les voyageurs de passage de dérober la larme."},{t="Le terrible prix à payer",b="Les avertissements du général Twinbraid se révèlent fondés lorsque Feegly récupère la larme des lunes. Sa magie transformatrice cachée le consume et change le nain en trogg sauvage. Quelques secondes après avoir repris son bien, Feegly meurt."}},faq={{q="Qu'est-ce que la larme des lunes ?",a="La larme des lunes est un puissant vestige découvert par des fouilleurs nains lors de leurs premières excavations à Bael Modan, dans le sud des Tarides. Elle corrompt ceux qui la manipulent et les emplit d'un désir enivrant de pouvoir.",al={"qu'est-ce que la larme des lunes","relique larme des lunes","artefact de bael modan"}},{q="Qui est Feegly l'Exilé ?",a="Feegly l'Exilé était un fouilleur de l'expédition du général Twinbraid à Bael Modan. Après la découverte de la larme des lunes, il est devenu obsédé et violent. Twinbraid l'a chassé du donjon.",al={"qui est feegly","histoire de feegly","feegly le nain"}},{q="Pourquoi le général Twinbraid enferme-t-il la larme ?",a="Le général Twinbraid a enfermé la larme parce qu'il l'a reconnue comme une malédiction dangereuse. Après que Feegly s'est retourné contre ses compagnons fouilleurs, Twinbraid a mis le vestige en sûreté dans le donjon de Bael Modan.",al={"pourquoi twinbraid a enfermé la larme","malédiction de twinbraid","relique du donjon de bael modan"}},{q="Que se passe-t-il quand vous rendez la larme à Feegly ?",a="Rendre la larme satisfait Feegly, mais la suite n'est pas encore connue.",al={"qu'arrive-t-il à feegly","fin de feegly","rendre la larme"}},{q="La magie de la larme est-elle entièrement comprise ?",a="Le général Twinbraid qualifie la larme de maudite, tandis que Feegly convoite le pouvoir qu'il croit qu'elle lui confère. Sa magie reste inexpliquée.",al={"magie de la larme","malédiction de la larme des lunes","comment fonctionne la larme"}},{q="Pourquoi s'agit-il d'une quête de la Horde si Feegly est un nain ?",a="Feegly est un paria qui se cache dans les Tarides, où il méprise les forces de l'Alliance occupant Bael Modan. Il fait appel aux aventuriers de la Horde, hostiles aux fouilles de Twinbraid, pour qu'ils attaquent le donjon et récupèrent le vestige.",al={"pourquoi une quête de la horde","feegly est-il de la horde","bael modan et la horde"}}},fx={["76d5a92c"]={q="Pourquoi Feegly l'Exilé veut-il que The Tear of the Moons lui soit restituée ?",a="Feegly est totalement obsédé par The Tear of the Moons. Déterré à Bael Modan, l'artefact lui a conféré un pouvoir étrange et enivrant avant que le général Twinbraid ne le déclare maudit et ne le confisque. Twinbraid a banni Feegly du site de fouilles après l'éclatement de violents conflits au sujet de la relique. Consumé par la paranoïa et avide du pouvoir qu'il a brièvement détenu, Feegly cherche désespérément à récupérer ce qu'il considère être son bien légitime.",al={"pourquoi feegly veut-il the tear of the moons","mobile de feegly","pourquoi feegly l'exilé veut-il the tear of the moons"}},["7effe162"]={q="Pourquoi Feegly vous demande-t-il de récupérer The Tear of the Moons au lieu de le faire lui-même ?",a="Le général Twinbraid a banni Feegly de Bael Modan par la force et a enfermé l'artefact au cœur de la forteresse. Feegly est un paria et persona non grata parmi ses congénères nains ; dès qu'il remettrait les pieds dans le fort, les gardes de Twinbraid l'arrêteraient ou l'abattraient. Incapable d'infiltrer seul son ancien foyer, il se tourne vers un aventurier extérieur pour s'y faufiler et le voler pour lui.",al={"pourquoi feegly a besoin de vous","pourquoi feegly ne peut-il pas récupérer the tear of the moons lui-même","pourquoi feegly a-t-il besoin de mon aide"}}},fp="21,100,23.213.0,22.360.0,17.221.1,30.216.0,25.192.0,46.187.0,48.82.1,37.124.1,47.213.0"}
P.entries["quest:8576"] = {n="La traduction du grand livre",s="Vous apportez le registre d'Azuregos à Narain Divinambolesque, qui doit en déchiffrer l'écriture. Ce qu'il découvrira pourrait vous rapprocher de l'ouverture des Portes d'Ahn'Qiraj.",h="Vous apportez le registre d'Azuregos à Narain Divinambolesque, qui doit en déchiffrer l'écriture.",kw={"arcanite buoy","azuregos","draconic","registre","narain divinambolesque","tanaris"},sec={{t="Le registre arrive chez Narain",b="Le registre d'Azuregos est entre vos mains, et Narain Divinambolesque doit le déchiffrer. Vous le lui apportez pour qu'il découvre ce qu'Azuregos a écrit."},{t="Ce que Narain en comprend",b="Narain Divinambolesque découvre qu'Azuregos vous a chargé de fabriquer un arcanite buoy, et que son schéma se trouve dans le registre. L'écriture est en draconic, une langue que Narain ne peut pas lire. Pour la comprendre, il a besoin des scrying goggles, d'un poulet de cinq cents livres et du second volume de Draconic for Dummies. Il peut les réunir dans n'importe quel ordre."}},faq={{q="À qui appartient le registre ?",a="Le registre appartient à Azuregos, et vous l'apportez à Narain Divinambolesque.",al={"à qui appartient le registre","registre d'azuregos","qui a écrit le registre"}},{q="Qui lit le registre ?",a="Narain Divinambolesque doit comprendre ce qu'Azuregos a écrit dans le registre.",al={"qui traduit le registre","narain divinambolesque","où apporter le registre"}}},fp="22,150,26.140.0,23.326.1,19.64.0,21.66.0"}
P.entries["quest:8577"] = {n="Stewvul, ex-M.A.P.V.",s="Narain ne peut rien traduire sans les lunettes de divination. Stewvul, son ex-M.A.P.V., les a, et vous devez les récupérer.",h="Narain ne peut rien traduire sans les lunettes de divination.",kw={"le mur de grisetête","caisse discrète","registre","narain divinambolesque","lunettes de divination","forêt des pins-argentés","stewvul","tanaris"},sec={{t="Les lunettes volées",b="Narain Divinambolesque ne peut rien traduire sans les lunettes de divination. Stewvul était autrefois son meilleur ami pour la vie, mais les a volées il y a quelque temps. Puis Stewvul a brisé le cœur de Narain en cinq endroits et l’a abandonné ici."},{t="Où chercher",b="La boule de cristal de Narain indique deux endroits où Stewvul pourrait se trouver. L’un est le mur de Grisetête, dans la Forêt des Pins-Argentés. L’autre se trouve au-delà d’un portail. Vous devez trouver Stewvul et rapporter les lunettes."},{t="Ce que dit Stewvul",b="Stewvul n’en croit pas ses yeux : Narain l’a retrouvé. Stewvul refuse de revenir, las d’être son ami une partie du temps et son esclave le reste."}},faq={{q="Pourquoi Narain a-t-il besoin des lunettes de divination ?",a="Narain affirme que rien ne peut être traduit sans les lunettes de divination.",al={"pourquoi les lunettes","utilité des lunettes de narain","usage des lunettes de divination"}},{q="Qui est Stewvul ?",a="Stewvul est l’ex-meilleur ami pour la vie de Narain Divinambolesque. Stewvul a volé les lunettes de divination, brisé le cœur de Narain en cinq endroits, puis l’a abandonné ici.",al={"qui est stewvul","histoire de stewvul","ami de narain"}},{q="Où Narain pense-t-il que se trouve Stewvul ?",a="La boule de cristal de Narain indique deux lieux possibles : le mur de Grisetête, dans la Forêt des Pins-Argentés, ou un monde au-delà d’un portail.",al={"où est stewvul","lieux où se trouve stewvul","le mur de grisetête"}},{q="Que s’est-il passé avant ?",a="Avant cela, vous avez apporté le registre d’Azuregos à Narain dans Translating the Ledger.",al={"quête précédente","prérequis","ce qui mène à cette quête"}}},fp="18,124,18.223.0,13.191.0,17.140.1,41.66.0,15.154.0,35.112.0,23.79.0"}
P.entries["quest:858"] = {n="Contact",s="Dans un camp de la KapitalRisk, au nord des Tarides, un pilote piégé a besoin d'une clé pour s'échapper. L'espion a pris un déchiqueteur sans sa clé de contact et vous envoie en chercher une auprès du superviseur du site.",h="Dans un camp de la KapitalRisk, au nord des Tarides, un pilote piégé a besoin d'une clé pour s'échapper.",kw={"derrick","ignition","clé de contact","cabestan","déchiqueteur","krachevalve","les tarides","kapitalrisk","wizzlecrank"},ang={["faction:Horde"]="La déforestation effrénée de la KapitalRisk menace le nord des Tarides. Saboter ou voler ses machines lourdes perturbe ses activités.",["profession:Engineering"]="Le déchiqueteur de la KapitalRisk possède des commandes de bras précises et des régulateurs de rotation réactifs, bien au-delà des bricolages habituels de Cabestan."},sec={{t="Un vol qui tourne mal",b="Krachevalve a envoyé un espion dans un déchiqueteur de la KapitalRisk, sur le site de forage du nord des Tarides. L'agent compte s'emparer de la machine et étudier son fonctionnement. Mais sa colonne de direction et de mouvement reste verrouillée sans la clé de contact."},{t="Bluffer sous pression",b="Un ouvrier gobelin a repéré le déchiqueteur à l'arrêt, alors le pirate prétend que son moteur est en panne. Piégé sous la verrière, avec des ouvriers à proximité, l'agent vous indique le derrick central. Le superviseur garde des clés de contact de rechange dans le bureau de commande supérieur. L'une d'elles est la seule issue du pilote avant que son bluff ne soit démasqué."},{t="Jalousie industrielle",b="Une fois la clé tournée, le voleur étudie les commandes du déchiqueteur. Ses leviers de bras, ses commandes de rotation et ses amortisseurs de stabilité sont plus précis que ceux des machines maladroites de Cabestan. La machine est désormais un trophée d'espionnage industriel et le seul moyen pour le pilote de survivre."}},faq={{q="Qui se trouve dans le déchiqueteur ?",a="Un agent lié à Krachevalve, un ingénieur de Cabestan, se trouve dans le déchiqueteur. Le pilote s'est infiltré dans les installations de la KapitalRisk pour voler l'une de ses machines avancées de défrichage.",al={"pilote du déchiqueteur","qui est dans le déchiqueteur de wizzlecrank","wizzlecrank"}},{q="Pourquoi le déchiqueteur ne peut-il pas simplement partir ?",a="La colonne de mouvement du déchiqueteur est verrouillée sans sa clé de contact. Le pirate a atteint le cockpit, mais la machine ne peut pas bouger tant que la clé n'a pas déverrouillé ses commandes de déplacement.",al={"pourquoi faut-il une clé","pourquoi est-il bloqué","déchiqueteur verrouillé"}},{q="Où trouver la clé de contact ?",a="Le superviseur de la KapitalRisk possède la clé de contact. Il se trouve dans la salle de commande, au sommet du derrick en bois voisin.",al={"emplacement de la clé de contact","où se trouve le superviseur","comment trouver la clé"}},{q="Pourquoi Cabestan veut-il un déchiqueteur de la KapitalRisk ?",a="Cabestan veut un déchiqueteur de la KapitalRisk parce que sa conception surpasse celle des modèles habituels utilisés sur place. Une machine intacte permettrait aux bricoleurs locaux d'étudier ses commandes de bras, ses régulateurs de vitesse et ses systèmes de stabilité.",al={"pourquoi voler le déchiqueteur","déchiqueteur de cabestan","déchiqueteur de krachevalve"}},{q="Qui est Krachevalve ?",a="Krachevalve est un ingénieur gobelin et un agent de Cabestan. Krachevalve surveille l'expansion de la KapitalRisk et convoite ses innovations mécaniques.",al={"identité de krachevalve","qui a envoyé wizzlecrank","krachevalve à cabestan"}},{q="Que se passe-t-il après le démarrage du déchiqueteur ?",a="En tournant la clé, vous déverrouillez les systèmes de mouvement du déchiqueteur. Le pilote tente alors de conduire la machine volée hors du camp de forage hostile et de rejoindre un lieu sûr, tandis qu'une opération d'escorte est en cours.",al={"que faire après le démarrage","après la clé de contact","suite de la quête de la clé de contact"}}},fx={["52fc6a42"]={q="Pourquoi Wizzlecrank a-t-il besoin que cela soit fait immédiatement ?",a="Wizzlecrank s'est introduit clandestinement sur le site de forage de la KapitalRisk pour réquisitionner l'un de leurs déchiqueteurs avancés pour Cabestan, pour finalement se retrouver piégé dans le cockpit sans le mécanisme de démarrage. Pire encore, lorsqu'un autre opérateur s'est approché, il a paniqué et a prétendu que la machine avait subi une défaillance mécanique. Ce n'est qu'une question de temps avant que l'équipe ne revienne ou ne découvre son mensonge, transformant un vol discret en exécution s'il ne parvient pas à démarrer le moteur et à fuir immédiatement.",al={"mobile de wizzlecrank","pourquoi se presser pour ignition","pourquoi wizzlecrank a-t-il besoin de la clé"}},edef521b={q="Qui détient la clé du déchiqueteur ?",a="La clé est détenue par le superviseur de la KapitalRisk stationné dans la salle de contrôle au sommet du derrick. La KapitalRisk maintient une surveillance impitoyable sur ses opérations d'exploitation forestière et de forage dans Les Tarides, gardant les contrôles critiques hors de portée des ouvriers ordinaires pour prévenir le vol et le sabotage. S'emparer de la clé signifie infiltrer leur poste de commandement et affronter le superviseur qui gère l'ensemble du site.",al={"qui détient la clé de contact","clé du superviseur de la kapitalrisk","qui possède la clé de contact"}},e6f51bdb={q="Pourquoi Wizzlecrank a-t-il besoin que vous récupériez la clé au lieu de le faire lui-même ?",a="Wizzlecrank est piégé dans le cockpit, entouré d'ouvriers suspects de la KapitalRisk. S'il sort et traverse le camp en direction du derrick de commandement, il grillera immédiatement sa couverture et alertera tout le site. Il doit rester à l'intérieur et faire semblant d'inspecter les commandes défectueuses tout en comptant sur un étranger capable de se frayer un chemin jusqu'au poste du superviseur.",al={"pourquoi wizzlecrank ne peut-il pas obtenir la clé","pourquoi wizzlecrank a-t-il besoin d'aide","pourquoi moi wizzlecrank"}}},fp="8,200,21.239.0,23.341.0,18.277.1,27.188.0,41.172.0,32.122.0,49.215.0,20.152.0,43.201.1"}
P.entries["quest:8584"] = {n="On ne parle jamais de mon boulot",s="Narain Divinambolesque vous envoie à Gadgetzan chercher un poulet de cinq cents livres. À l'auberge, Dirge Hachillico pourra vous en indiquer un.",h="Narain Divinambolesque vous envoie à Gadgetzan chercher un poulet de cinq cents livres.",kw={"poulet de 500 livres","black chicken of death","dirge hachillico","gadgetzan","narain divinambolesque","tanaris"},sec={{t="Préparatifs et recherche",b="Narain Divinambolesque ne veut plus de questions sur ses affaires. Elles touchent à des domaines qui vous dépassent, alors il garde son plan pour lui et vous laisse les recherches. Il lui faut un poulet de cinq cents livres. Dirge Hachillico se trouve à l'auberge de Gadgetzan et peut vous orienter vers un poulet."},{t="La réponse de Dirge",b="Dirge Hachillico affirme qu'on ne peut plus trouver de poulet aussi lourd. Il connaissait autrefois le Black Chicken of Death, mais personne n'a survécu après avoir vu cet oiseau pour en parler. Puis Dirge propose une idée qui pourrait vous arranger tous les deux."}},faq={{q="Pourquoi Narain Divinambolesque a-t-il besoin d'un poulet de cinq cents livres ?",a="Narain ne le dira pas. Ses affaires concernent des choses qui vous dépassent, comme un psychotronic muzzledorf. Il garde les préparatifs pour lui et vous laisse les recherches.",al={"pourquoi un poulet de 500 livres","les affaires de narain et le poulet","pourquoi narain veut un poulet"}},{q="À qui devez-vous parler à Gadgetzan ?",a="Narain vous envoie parler à Dirge Hachillico, à l'auberge de Gadgetzan, pour commencer à chercher un poulet qui convienne.",al={"où aller","qui voir à gadgetzan","où se trouve dirge hachillico"}},{q="Quelle quête faut-il faire avant celle-ci ?",a="La traduction du registre vient d'abord. Narain Divinambolesque parle du poulet ensuite.",al={"quête prérequise","quelle quête faire avant","étape précédente"}},{q="Où se trouve Narain Divinambolesque ?",a="Narain Divinambolesque se trouve à Tanaris.",al={"où se trouve narain","emplacement de narain","emplacement de narain divinambolesque à tanaris"}}},fp="30,143,21.284.0,14.214.1,61.175.0,40.98.0,29.86.0,35.32.0"}
P.entries["quest:8586"] = {n="Pyro-côtelettes de chimaerok à la Dirge",s="À Gadgetzan, Dirge Hachillico a sa recette prête, mais il faut vite s’occuper de la viande. Il vous demande vingt Carburants de fusée des gobelins et vingt Sels de Fonderoc avant qu’elle ne se gâte.",h="À Gadgetzan, Dirge Hachillico a sa recette prête, mais il faut vite s’occuper de la viande.",kw={"chimaerok","côtelettes","sel de fonderoc","dirge","gadgetzan","narain","hachillico","carburant de fusée"},sec={{t="Ce qu’il manque encore à Dirge",b="Dirge Hachillico s’occupe lui-même des épices, tandis que la viande que vous lui avez apportée complète le plat. Il lui faut encore vingt Carburants de fusée des gobelins et vingt Sels de Fonderoc. Une fois les deux ingrédients en sa possession, le poulet pourra être rapporté à Narain Divinambolesque. Dirge vous presse de faire vite avant que la viande ne se gâte."}},faq={{q="Qui demande ces provisions ?",a="Dirge Hachillico, à Gadgetzan, vous demande les provisions nécessaires pour terminer sa recette.",al={"qui donne cette quête","qui donne les pyro-côtelettes de chimaerok à la dirge","quête de dirge hachillico"}},{q="De quels ingrédients Dirge Hachillico a-t-il besoin ?",a="Dirge a besoin de vingt Carburants de fusée des gobelins et de vingt Sels de Fonderoc. Il s’occupe des épices, et la viande que vous lui avez apportée complète le plat.",al={"quels objets me faut-il","ingrédients pour les côtelettes de dirge","objets pour les côtelettes de dirge"}},{q="À qui le plat terminé est-il destiné ?",a="Dirge dit que le volatile est prêt à être rapporté à Narain Divinambolesque.",al={"qui mange les côtelettes","à qui est destiné le poulet","pour qui est le plat"}},{q="Que faire après avoir livré ces ingrédients ?",a="Après avoir livré les ingrédients, retournez voir Narain Divinambolesque.",al={"quête suivante","que faire après les côtelettes de dirge","que faire après cette quête"}}},fp="31,172,22.289.0,28.77.0,44.132.0,38.78.0,46.63.0"}
P.entries["quest:8587"] = {n="Retour vers Narain",s="Dirge Hachillico tient parole, et vous apportez son poulet de cinq cents livres à Narain Divinambolesque, en Tanaris. Dirge's Kickin' Chimaerok Chops a précédé cette livraison.",h="Dirge Hachillico tient parole, et vous apportez son poulet de cinq cents livres à Narain Divinambolesque, en...",kw={"poulet de cinq cents livres","chimaerok","dirge hachillico","narain divinambolesque","tanaris"},sec={{t="Une promesse tenue",b="Dirge Hachillico vous remet le poulet promis. Un gobelin tient parole, dit-il. Il ne peut deviner pourquoi un gnome voudrait un oiseau de cette taille et grommelle que ce doit être pour dormir dedans. De là, vous apportez le poulet à Narain Divinambolesque, en Tanaris."},{t="L'accueil de Narain",b="Narain Divinambolesque sent l'odeur du poulet de Dirge. Il enfonce ses deux poings dans l'oiseau, puis se goinfre de la cuisine de Dirge. C'est le meilleur poulet qu'il ait jamais goûté, dit Narain."}},faq={{q="Qu'est-ce qui a précédé cette livraison ?",a="Dirge's Kickin' Chimaerok Chops est arrivé en premier. Dirge Hachillico a demandé du carburant pour fusée et du sel pour terminer sa recette.",al={"quête précédente","qu'ai-je fait avant","prérequis"}},{q="Qui reçoit le poulet gigantesque ?",a="Narain Divinambolesque reçoit le poulet gigantesque en Tanaris.",al={"qui reçoit le poulet","à qui apporter ceci","lieu de remise"}},{q="Pourquoi Dirge a-t-il préparé un poulet de cinq cents livres ?",a="Dirge a préparé le poulet de cinq cents livres pour tenir parole et le remettre. Il dit qu'il ne peut imaginer ce qu'un gnome ferait d'un oiseau de cette taille.",al={"pourquoi un poulet de cinq cents livres","à quoi sert le poulet","poulet de dirge"}},{q="Que se passe-t-il après la livraison du poulet ?",a="The Good News and The Bad News suit. Narain ne la propose qu'une fois les Lunettes de divination de Narain et Le draconique pour les nuls : volume II terminés.",al={"quête suivante","que se passe-t-il ensuite","où aller ensuite"}}},fp="16,169,14.251.0,16.190.1,31.113.0,33.58.0,51.148.0,40.142.0"}
P.entries["quest:8597"] = {n="Le draconique pour les nuls",s="Narain Divinambolesque veut que vous retrouviez le livre qu'il a caché sur une île des Mers du sud. Trouvez d'abord son gyrocoptère écrasé sur la Plage du Bout-du-Monde, puis nagez vers le sud. Cette quête fait suite à Translating the Ledger.",h="Narain Divinambolesque veut que vous retrouviez le livre qu'il a caché sur une île des Mers du sud.",kw={"le draconique pour les nuls","terre fraîchement remuée","gyrocoptère","plage du bout-du-monde","narain divinambolesque","mers du sud","tanaris"},sec={{t="Un livre bien caché",b="Narain Divinambolesque affirme que le livre vous sera utile et qu'il l'a caché là où personne ne pourrait espérer le trouver. Il a pris un gyrocoptère pour rejoindre sa cachette, puis s'est écrasé sur la plage au retour. Narain dit que l'accident lui a conféré ses pouvoirs psychiques super-gnomiques.\n\nL'épave se trouve quelque part le long de la Plage du Bout-du-Monde. De là, nagez vers le sud. Narain est certain que vous reconnaîtrez l'endroit au premier coup d'œil. Le livre est enterré sur une île des Mers du sud."},{t="Sur l’île",b="Sur l’île, vous trouvez un monticule de terre, mais le livre a disparu. À sa place, une note repose sur le monticule."}},faq={{q="Qui vous envoie chercher ce livre ?",a="Narain Divinambolesque vous envoie chercher le livre après que vous avez terminé Translating the Ledger pour lui.",al={"qui donne le draconique pour les nuls","début de quête de narain","qui donne cette quête"}},{q="Où Narain s’est-il écrasé avec son gyrocoptère ?",a="Narain dit qu’il s’est écrasé sur une plage en revenant après avoir caché le livre. Son épave se trouve quelque part le long de la Plage du Bout-du-Monde.",al={"où se trouve le gyrocoptère","emplacement du gyrocoptère écrasé","crash sur la plage du bout-du-monde"}},{q="Où le livre est-il censé être caché ?",a="Narain Divinambolesque dit que le livre est enterré sur une île des Mers du sud. Nagez vers le sud depuis son épave, sur la Plage du Bout-du-Monde ; il dit que vous reconnaîtrez l’endroit au premier coup d’œil.",al={"emplacement du livre","où se trouve l’île","où nager"}},{q="Comment Narain a-t-il obtenu ses pouvoirs psychiques ?",a="Narain dit que l’accident de gyrocoptère sur la plage lui a conféré ses pouvoirs psychiques.",al={"pouvoirs psychiques de narain","comment narain est-il devenu médium"}}},fp="20,193,18.441.0,13.101.1,32.90.0,38.120.0,40.172.0,38.74.0"}
P.entries["quest:8598"] = {n="rANçOn !",s="Dans la terre fraîchement creusée de Tanaris, le livre de Narain Divinambolesque a disparu, et une demande de rançon a été laissée à sa place. Après avoir cherché le livre dans Draconic for Dummies, vous rapportez la lettre à Narain.",h="Dans la terre fraîchement creusée de Tanaris, le livre de Narain Divinambolesque a disparu, et une demande de...",kw={"draconic for dummies","terre fraîchement creusée","narain divinambolesque","rançon","lettre de rançon","tanaris"},sec={{t="Une note faite de morceaux",b="Composée de morceaux de caractères imprimés, la demande de rançon annonce à Narain Divinambolesque que ses auteurs détiennent son précieux livre. Ils le traitent de gnome et promettent qu'il le reverra seulement s'il suit leurs ordres à la lettre. Trois pages donnent des instructions détaillées, qui s'achèvent sur l'exigence d'apporter l'argent et de venir seul. Vous portez la lettre à Narain en Tanaris."},{t="La réponse de Narain",b="Narain Divinambolesque vous demande ce qui ne va pas, puis lit la lettre. Son visage devient rouge vif. Outré que quelqu'un ait pris son livre, il jure de montrer aux coupables ce qu'il en coûte de s'en prendre à un gnome psychique."}},faq={{q="Que réclame la demande de rançon ?",a="Les auteurs prétendent détenir le livre de Narain Divinambolesque et promettent qu'il le reverra seulement s'il suit leurs ordres. Trois pages d'instructions s'achèvent sur une demande d'argent et l'exigence qu'il vienne seul. La note ne révèle pas l'identité de ses auteurs.",al={"que dit la note","texte de la lettre de rançon","qui a pris le livre"}},{q="Où mène la suite de cette étape ?",a="Après avoir porté la lettre à Narain Divinambolesque en Tanaris, la suite de la chaîne est Decoy !",al={"que faire après la rançon","suite de la rançon","quête après la rançon"}},{q="Que s'est-il passé avant la découverte de la demande de rançon ?",a="Draconic for Dummies vient d'abord. Vous cherchez le livre enterré de Narain et trouvez la terre fraîchement creusée.",al={"quête précédente","prérequis de la rançon"}}},fp="6,199,21.346.0,15.198.1,34.234.0,31.91.0,41.103.0"}
P.entries["quest:8599"] = {n="Une chanson d'amour pour Narain",s="Meridith la Vierge de mer envoie une déclaration d’amour à Narain Divinambolesque, et vous lui apportez sa lettre à Tanaris. Elle a sauvé le gnome d’un engin volant écrasé et vous demande de retrouver son livre, Le drannais pour les nuls.",h="Meridith la Vierge de mer envoie une déclaration d’amour à Narain Divinambolesque, et vous lui apportez sa...",kw={"engin volant","lettre d’amour","meridith","vierge de mer","narain divinambolesque","tanaris","épave"},sec={{t="Un message pour le rivage",b="Meridith la Vierge de mer reçoit rarement des visiteurs. Le dernier était le gnome qu’elle a sauvé d’un engin volant écrasé. Ce souvenir lui fait perdre son regard au loin un instant. Puis elle vous demande si vous connaissez Narain Divinambolesque. Elle doit lui dire ce qu’elle ressent et elle est certaine que c’est de l’amour. Meridith vous supplie de lui porter son message et promet de vous en être éternellement redevable."},{t="La réponse de Narain",b="Narain Divinambolesque trouve que vous sentez le poisson. Lorsqu’il apprend ce que dit la lettre de Meridith, il s’agite. C’est un poisson, proteste-t-il, et lui est un gnome. Il affirme que leur amour ne pourrait jamais fonctionner."}},faq={{q="Qui est Meridith ?",a="Meridith est une vierge de mer qui reçoit rarement des visiteurs. Son dernier visiteur était Narain Divinambolesque, le gnome qu’elle a sauvé d’un engin volant écrasé.",al={"qui est meridith","meridith la vierge de mer","histoire des vierges de mer"}},{q="Comment Meridith connaît-elle Narain Divinambolesque ?",a="Meridith a sauvé Narain Divinambolesque de son engin volant écrasé. Elle croit être amoureuse de lui.",al={"comment meridith a rencontré narain","relation entre narain et meridith","accident d’aéronef de narain"}},{q="Qu’est-ce que la lettre d’amour ?",a="La lettre d’amour est le message de Meridith à Narain Divinambolesque, dans lequel elle lui révèle ses sentiments. Elle veut que vous la lui remettiez à Tanaris.",al={"lettre d’amour de meridith","lettre d’amour à narain","contenu du message"}},{q="Que s’est-il passé avant cette demande ?",a="Le drannais pour les nuls vient d’abord. Meridith vous demande de porter sa lettre pendant que vous cherchez le livre enterré de Narain.",al={"quête précédente","prérequis de une chanson d’amour pour narain"}}},fp="20,194,23.355.0,15.188.1,16.141.0,41.105.0,24.133.0,30.108.0"}
P.entries["quest:86"] = {n="Une tourte pour Billy",s="Une tourte pour Billy est une course prise entre deux feux dans la rivalité de longue date opposant les familles Champierreux et Maclure de la Forêt d’Elwynn. Le jeune Billy Maclure refuse de donner la moindre information sur le collier disparu de tante Bernice Champierreux sans recevoir une tourte de panse de porc en échange. Les aventuriers doivent chasser les sangliers des environs pour récolter la viande nécessaire afin que Bernice puisse préparer le pot-de-vin réclamé.",h="Une tourte pour Billy est une course prise entre deux feux dans la rivalité de longue date opposant les...",kw={"bernice stonefield","billy maclure","forêt d’elwynn","le collier perdu","les vignes des maclure","tourte de panse de porc","la ferme des champierreux","tender boar meat"},ang={["profession:Cooking"]="Tante Bernice souligne que, même si la viande de sanglier sauvage peut être coriace et fade, de bonnes épices et un mijotage lent en font une garniture de tourte salée exceptionnelle.",["race:Human"]="Cette querelle illustre les rivalités obstinées et insulaires qui prospèrent parmi les colons ruraux d'Elwynn, juste au sud des portes de Hurlevent."},sec={{t="Le pot-de-vin d'un garnement",b="Lorsqu'on l'interroge sur le vol du collier de famille de tante Bernice Champierreux, Billy Maclure ne manifeste aucun des remords qu'une aînée pourrait espérer. Au lieu de restituer le joyau ou d'avouer, le garçon saisit l'occasion de satisfaire son appétit. Il exige une tourte de panse de porc fraîchement sortie du four avant de prononcer le moindre mot sur l'identité de celui qui détient le collier, sachant pertinemment que tante Bernice est la meilleure cuisinière de la vallée."},{t="Cuisiner malgré la rancœur",b="Depuis des générations, les Maclure et les Champierreux s'échangent insultes, bagarres et accusations par-dessus les champs de citrouilles. Malgré son profond dégoût à l'idée de nourrir le vaurien qui a dérobé son bijou de famille, tante Bernice accepte d'allumer son four. En échange de Tender Boar Meat prélevée sur les bêtes sauvages qui errent dans les pâturages voisins, elle ravale sa fierté pour amadouer l'insolent jeune homme et récupérer son bien le plus précieux."}},faq={{q="Pourquoi Billy veut-il une tourte avant de parler ?",a="Billy Maclure est un jeune fermier opportuniste qui utilise ce qu'il sait du collier volé de tante Bernice comme moyen de pression. Sachant que Bernice prépare d'exceptionnelles tourtes de panse de porc, il refuse de révéler qui détient le bijou tant que son appétit n'a pas été comblé.",al={"pourquoi billy veut tourte","billy pot-de-vin tourte","billy tourte de panse de porc"}},{q="Pourquoi tante Bernice accepte-t-elle de cuisiner pour un voleur ?",a="Tante Bernice est furieuse de devoir récompenser le garçon même qu'elle soupçonne d'avoir dérobé son collier de famille, mais elle ne voit aucun autre moyen de le récupérer. Elle accepte à contrecœur de préparer la tourte dès qu'elle reçoit la viande de sanglier, faisant passer la restitution de son bien avant son amour-propre.",al={"pourquoi bernice cuisine","bernice stonefield raison tourte","stonefield cuisine pour maclure"}},{q="D'où provient la viande pour la tourte ?",a="La viande provient des sangliers sauvages qui fouissent dans les prairies et aux abords des fermes Champierreux et Maclure dans la Forêt d’Elwynn.",al={"où trouver de la viande","source tender boar meat"}},{q="Quelle est l'histoire entre les Champierreux et les Maclure ?",a="Les familles Champierreux et Maclure sont des fermiers voisins qui entretiennent depuis des années une rivalité mesquine et amère, se soupçonnant constamment de vol, de vandalisme et de querelles de mauvaise foi le long de leurs limites de propriété.",al={"conflit stonefield maclure","rivalité fermière","maclure contre stonefield"}},{q="Billy a-t-il vraiment volé le collier ?",a="Tante Bernice accuse directement Billy, et bien qu'il esquive tout aveu franc, il sait manifestement où le bijou de famille a fini et se sert de ce secret pour marchander de la nourriture.",al={"billy a-t-il vole collier","qui a pris collier","billy voleur collier"}},{q="Que se passe-t-il après que Bernice a reçu la viande ?",a="Une fois approvisionnée en Tender Boar Meat, tante Bernice prépare une tourte de panse de porc pour que vous la rapportiez à Billy afin qu'il révèle enfin qui possède son collier.",al={"etape apres tourte","suite une tourte pour billy"}}},fp="13,179,13.238.0,24.273.0,41.175.0,50.208.0,42.129.0,57.207.0,38.162.0,41.152.0"}
P.entries["quest:860"] = {n="Sergra Sombreronce",s="À la Croisée, Sergra Sombreronce attend les chasseurs taurens qui quittent Mulgore. Melor Sabot-de-pierre les envoie au nord, dans les Tarides, où les dangers s’intensifient et où les terres de la Horde s’étendent bien au-delà de leur foyer.",h="À la Croisée, Sergra Sombreronce attend les chasseurs taurens qui quittent Mulgore.",kw={"la croisée","voie du chasseur","melor sabot-de-pierre","mulgore","trotteur des plaines","sergra sombreronce","les tarides","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, vous abandonnez le simple pistage du gibier local et affrontez les prédateurs et les conditions difficiles des savanes centrales de Kalimdor.",["faction:Horde"]="À la Croisée, vous découvrez un centre logistique de la Horde où la résilience orque, la ruse des Sombrelance et la tradition tauren se rencontrent sous la conduite de vétérans comme Sergra.",["race:Tauren"]="Élevé en Mulgore, vous quittez votre terre ancestrale en répondant à l’appel de Sergra et en entrant au service de la Horde élargie."},sec={{t="Quitter les Sacred Hills",b="Une fois leurs premières épreuves achevées, Melor Sabot-de-pierre envoie les jeunes chasseurs taurens vers l’est, depuis Mulgore. Le village de Sabot-de-Sang et ses vallées leur sont familiers. Ils y ont appris la patience du pistage et sont prêts à découvrir la suite. À présent, il leur demande de rassembler leur équipement et de franchir le col montagneux vers les Tarides, loin de la sécurité de leur terre natale."},{t="La route de la Croisée",b="La route serpente dans des canyons de roche rouge, puis débouche sur la vaste savane des Tarides, brûlée par le soleil. Au croisement des routes commerciales du centre de Kalimdor se trouve la Croisée, une colonie fortifiée où vivent orcs, trolls et taurens.\n\nSergra Sombreronce attend sur le côté est de la colonie. Cette chamane orc expérimentée exige beaucoup des chasseurs qu’elle guide. Elle enseigne à ceux qui viennent traquer la faune féroce des Tarides et met leur ardeur à l’épreuve de la discipline qu’exige la nature sauvage."}},faq={{q="Qui donne cette quête et où la trouver ?",a="Melor Sabot-de-pierre confie cette tâche aux chasseurs taurens. Vous trouverez ce mentor des chasseurs à la Cime des chasseurs, aux Pitons-du-Tonnerre.",al={"qui donne la quête de sergra sombreronce","emplacement de melor sabot-de-pierre","où commencer"}},{q="Où se trouve Sergra Sombreronce ?",a="Sergra Sombreronce attend à la Croisée, au centre des Tarides, près du côté est, des tours de guet et des enclos.",al={"emplacement de sergra sombreronce","où est sergra","trouver sergra"}},{q="Comment rejoindre la Croisée depuis Mulgore ?",a="Depuis les Pitons-du-Tonnerre, voyagez vers le sud en passant par le village de Sabot-de-Sang, puis prenez la route de l’est à travers le col du canyon, jusqu’aux Tarides. Après la porte frontalière, suivez la route principale en terre vers l’est jusqu’à l’embranchement, puis prenez vers le nord jusqu’à la Croisée.",al={"itinéraire vers la croisée","de mulgore aux tarides","comment rejoindre la croisée depuis les pitons-du-tonnerre"}},{q="Quel est le but de cette quête ?",a="Ce voyage guide les chasseurs de Mulgore jusqu’à la Croisée, un centre important des Tarides où les attendent des tâches de chasse locales.",al={"pourquoi faire cette quête","but de sergra sombreronce","est-ce une quête d’introduction"}},{q="Les orcs et les trolls reçoivent-ils cette quête ?",a="Les orcs et les trolls reçoivent une tâche similaire, appelée Conscript of the Horde, en Durotar. Elle les envoie de Tranchecolline dans les Tarides, où ils peuvent aussi rencontrer Sergra et travailler pour elle.",al={"version orque","version troll","quête d’introduction de durotar"}},{q="Qu’enseigne Sergra Sombreronce aux chasseurs ?",a="Sergra met les chasseurs qui arrivent à l’épreuve de la faune des Tarides, en commençant par les trotteurs des plaines et les rôdeurs. Elle leur enseigne l’endurance, le respect de la terre et la résilience mentale, plutôt que la force brute.",al={"rôle de sergra","que fait sergra","chasse avec sergra"}}},fx={["94d282e7"]={q="Pourquoi Melor Sabot-de-pierre vous envoie-t-il vers Sergra Darkthorn ?",a="Melor Sabot-de-pierre reconnaît que vous avez dépassé les doux terrains de chasse de Mulgore. Pour suivre véritablement The Hunter's Path et tester votre esprit, vous devez vous mesurer aux bêtes féroces et opiniâtres des Tarides. Melor vous envoie auprès de Sergra Darkthorn à La Croisée car elle possède l'expertise chevronnée nécessaire pour guider votre entraînement à travers ces plaines arides et brûlées par le soleil.",al={"pourquoi envoyer vers sergra","mobile de melor sabot-de-pierre","pourquoi aller à la croisée"}},bb525daf={q="Pourquoi Melor vous choisit-il pour ce voyage ?",a="Ce voyage n'est pas une corvée ou une commission pour les gardes de Pitons-du-Tonnerre ; c'est un rite de passage essentiel pour un aspirant chasseur. Melor ne peut pas suivre ce chemin à votre place. Vous avez fait preuve du dévouement et de l'esprit nécessaires pour faire progresser votre entraînement, et ce n'est qu'en vous aventurant vous-même dans Les Tarides sauvages que vous pourrez aguerrir vos instincts et devenir un maître de la chasse.",al={"pourquoi moi melor","pourquoi melor m'envoie-t-il"}}},fp="16,206,24.348.0,26.479.0,46.113.0,34.113.0,44.227.0,34.122.0,34.182.0,41.183.0"}
P.entries["quest:8606"] = {n="Un leurre !",s="Lors de la remise au Berceau-de-l’Hiver, Narain Divinambolesque compte livrer la rançon à sa manière. Vous portez son déguisement à l’endroit indiqué par les ravisseurs du livre, en suivant la lettre de rançon.",h="Lors de la remise au Berceau-de-l’Hiver, Narain Divinambolesque compte livrer la rançon à sa manière.",kw={"ravisseurs du livre","leurre","narain divinambolesque","numéro deux","rançon","berceau-de-l’hiver"},sec={{t="Le plan de Narain",b="La demande de rançon indiquait que Narain devait effectuer la livraison lui-même. Il compte le faire à sa manière et vous choisit pour jouer son rôle. Sa trousse spéciale contient un turban, une robe et un sac rempli de pierres. Vous apportez le déguisement au lieu de remise indiqué par les ravisseurs du livre, au Berceau-de-l’Hiver. Quand ils viendront récupérer la marchandise, Narain veut les éliminer pour leur apprendre ce qu’il en coûte de lui chercher des ennuis."},{t="Le verdict de Narain",b="À votre retour, Narain admet que vous avez peut-être tous deux sous-estimé les ravisseurs du livre."}},faq={{q="Pourquoi Narain veut-il que vous portiez un déguisement ?",a="La demande de rançon indiquait que Narain devait effectuer la livraison lui-même. Il compte le faire à sa manière en vous envoyant à sa place, avec le turban et la robe de sa trousse spéciale.",al={"pourquoi porter le turban","pourquoi le déguisement","pourquoi se déguiser en narain"}},{q="Où a lieu la remise ?",a="La remise a lieu à l’endroit indiqué par les ravisseurs du livre, au Berceau-de-l’Hiver. C’est là qu’il faut déposer le sac de pierres.",al={"où déposer le sac","où apporter le sac","lieu de dépôt"}},{q="Que contient le sac de rançon ?",a="Narain remplit le sac de pierres au lieu d’y mettre de l’argent.",al={"que contient le sac","est-ce de l’or véritable","qu’a mis narain dans le sac"}},{q="Quelle quête a précédé celle-ci ?",a="Avant cela, la lettre de rançon réclamait de l’argent contre le livre volé de Narain, que vous lui avez rapporté.",al={"quête prérequise","quête précédente","ce qui a mené à cette quête"}}},fp="6,184,15.384.0,16.87.1,44.171.0,35.127.0,30.50.0,28.102.0"}
P.entries["quest:861"] = {n="Le chemin du chasseur",s="À Mulgore, les jeunes aventuriers suivent Le chemin du chasseur sous la guidance de Skorn Nuage-blanc. Vous chassez les rôdeurs des plaines et portez leurs griffes à Melor Sabot-de-pierre, sur la Cime des chasseurs à Pitons-du-Tonnerre, pour prouver votre talent et votre respect de la nature.",h="À Mulgore, les jeunes aventuriers suivent Le chemin du chasseur sous la guidance de Skorn Nuage-blanc.",kw={"rôdeur des plaines","griffes de rôdeur des plaines","cime des chasseurs","melor sabot-de-pierre","mulgore","skorn nuage-blanc","le chemin du chasseur","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez les leçons essentielles de la nature sauvage : traquer un prédateur qui chasse à l'affût avant qu'il ne frappe, et lire les signes subtils des prairies.",["faction:Horde"]="En tant qu'errant de la Horde, vous pouvez découvrir le respect taurène pour la nature et gagner leur confiance sur les hauteurs de Pitons-du-Tonnerre.",["race:Tauren"]="Pour un jeune tauren, apporter des griffes de rôdeur à la Cime des chasseurs marque un rite de passage. Des générations d'ancêtres ont chassé dans ces mêmes plaines."},sec={{t="Une tradition des plaines",b="Chez les taurens, la chasse est l'un des plus grands honneurs. Elle exige de la patience, le souci de l'équilibre de la Terre-Mère et du respect pour les bêtes des plaines. L'ancien Skorn Nuage-blanc a pisté à travers Kalimdor pendant des décennies avant de venir se reposer à Mulgore. Voyant de jeunes aventuriers impatients d'arpenter les terres, il leur propose une épreuve traditionnelle pour transformer leur ambition en discipline."},{t="Les rôdeurs des plaines",b="Les rôdeurs des plaines mettent à l'épreuve le talent de pisteur des candidats. Ces grands félins traversent rapidement et silencieusement les hautes herbes de Mulgore, puis tendent une embuscade à leurs proies. Rapportez quatre paires de griffes pour prouver que vous savez trouver un prédateur avant qu'il ne vous trouve. Puis retournez sa propre férocité contre lui."},{t="Rejoindre la Cime des chasseurs",b="Une fois les griffes réunies, vous gravissez les tours et les ponts de bois jusqu'à la Cime des chasseurs, à Pitons-du-Tonnerre. Melor Sabot-de-pierre y reçoit les trophées. Maître pisteur, Melor respecte l'antique sagesse de Skorn Nuage-blanc. Il accepte les griffes comme preuve que vous avez l'esprit nécessaire pour en apprendre davantage sur les traditions de chasse de Kalimdor."}},faq={{q="Qui propose la tâche consistant à suivre Le chemin du chasseur ?",a="Skorn Nuage-blanc, un ancien qui se repose à Mulgore, propose cette épreuve aux jeunes aventuriers impatients de maîtriser la nature sauvage.",al={"donneur de quête","qui donne la quête","skorn nuage-blanc"}},{q="Où dois-je apporter les griffes des rôdeurs des plaines ?",a="Apportez les griffes des rôdeurs des plaines à Melor Sabot-de-pierre, sur la Cime des chasseurs à Pitons-du-Tonnerre.",al={"où trouver melor sabot-de-pierre","lieu où rendre la quête","cime des chasseurs"}},{q="Pourquoi choisir les griffes des rôdeurs des plaines comme offrande ?",a="Les rôdeurs des plaines sont des chasseurs furtifs et dangereux des prairies de Mulgore. Les pister et les vaincre met à l'épreuve le regard perçant, la patience et la discipline nécessaires à la chasse avancée.",al={"pourquoi les rôdeurs des plaines","histoire des griffes de rôdeur","que sont les rôdeurs"}},{q="Cette quête est-elle réservée à la classe des chasseurs ?",a="Non. Skorn Nuage-blanc propose cette épreuve à tout jeune aventurier de la Horde impatient d'arpenter les terres et de découvrir les traditions des plaines.",al={"réservé aux chasseurs ?","les autres classes peuvent-elles faire cette quête","est-ce réservé aux chasseurs"}},{q="Où mène le voyage du chasseur après avoir parlé à Melor ?",a="Melor Sabot-de-pierre reconnaît vos talents grandissants et vous envoie vers les étendues plus rudes des Tarides. Là-bas, des pisteurs expérimentés comme Sergra Darkthorn peuvent vous guider.",al={"what comes next","quête suivante","où aller après melor"}},{q="Quelle place la chasse occupe-t-elle dans la culture taurène ?",a="Pour les taurens, la chasse est l'un des plus grands honneurs. Elle signifie vivre en harmonie avec la création de la Terre-Mère, ne prendre que le nécessaire et respecter le gibier qui fait vivre les tribus.",al={"histoire de la chasse chez les taurens","honneur de la chasse chez les taurens","pourquoi la chasse est-elle importante pour les taurens"}}},fx={["1c4e016d"]={q="Pourquoi Skorn Nuage-blanc veut-il que cela soit fait ?",a="Skorn Nuage-blanc est un ancien chasseur dont les jours d'errance sont derrière lui, mais son esprit brûle toujours intensément. Voyant votre agitation et votre désir d'explorer, il souhaite guider votre ambition vers les honorables traditions de la chasse. En testant vos capacités et en vous dirigeant vers Melor Sabot-de-pierre sur la Hunter's Rise, Skorn s'assure que l'héritage sacré de la chasse des Tauren est transmis à une nouvelle génération prometteuse.",al={"pourquoi skorn donne-t-il cette quête","mobile de skorn nuage-blanc","pourquoi m'envoyer vers melor"}},["837cf763"]={q="À quoi sert la Griffe de Rôdeur des basses plaines ?",a="Les griffes servent de preuve indéniable de votre talent de pistage, de votre ruse et de votre détermination martiale. Les rôdeurs des basses plaines sont des prédateurs féroces et insaisissables des plaines de Mulgore. Présenter quatre de leurs griffes à Melor Sabot-de-pierre démontre que vous possédez à la fois la patience pour chasser du gibier dangereux et la force pour le vaincre, prouvant aux maîtres de la Hunter's Rise que vous êtes digne de poursuivre votre entraînement.",al={"but des griffes de rôdeur des basses plaines","pourquoi collecter des griffes","tribut des griffes de rôdeur"}},d784e285={q="Que sont les rôdeurs des basses plaines et où les trouve-t-on ?",a="Les rôdeurs des basses plaines sont de grands félins prédateurs originaires des prairies ouvertes de Mulgore. Ils parcourent les plaines à la recherche de gibier, comptant sur leur discrétion, leur vitesse et leurs griffes acérées pour abattre leurs proies. En raison de leur ruse et de leur force naturelles, ils sont considérés comme une proie idéale pour vérifier si un aspirant chasseur maîtrise les compétences de base nécessaires pour traquer et abattre des bêtes sauvages.",al={"rôdeurs des basses plaines","rôdeurs de mulgore","que sont les rôdeurs"}},["3cad1e98"]={q="Pourquoi Skorn Nuage-blanc vous envoie-t-il au lieu de chasser les rôdeurs lui-même ?",a="Skorn a chassé à travers Mulgore pendant de nombreuses années, mais son corps a vieilli alors même que son esprit reste vif. Plus important encore, cette tâche n'est pas une simple corvée de collecte pour les provisions du camp ; c'est un rite de passage pour vous. Skorn reconnaît votre soif d'aventure juvénile et teste votre détermination directement afin que vous puissiez prouver que vous êtes digne de recevoir les conseils de Melor Sabot-de-pierre.",al={"pourquoi skorn ne chasse-t-il pas","pourquoi moi skorn nuage-blanc","pourquoi dois-je obtenir les griffes"}}},fp="16,232,25.357.0,30.265.0,20.305.0,45.116.0,43.87.0,53.181.0,50.121.0,61.158.1,54.193.0"}
P.entries["quest:862"] = {n="Brouet de rat",s="Boustiff' attend à l'est de la Croisée, affamé et rêvant d'un brouet de rat. Il envoie les voyageurs à Bael Modan, dans les Tarides du sud, chercher les rongeurs nécessaires à sa recette.",h="Boustiff' attend à l'est de la Croisée, affamé et rêvant d'un brouet de rat.",kw={"bael modan","tarides","cuisine","la croisée","brouet de rat","nains","boustiff'","rats"},ang={["faction:Horde"]="Prendre des rats fouisseurs à Bael Modan permet de se moquer des fouilles naines tout en rassemblant des provisions dans les Tarides du sud.",["profession:Cooking"]="Préparer un brouet de rat enseigne à se nourrir dans les régions sauvages : la vermine devient un repas copieux et nauséabond, cuit au feu de camp.",["race:Undead"]="Boustiff' aime laisser la viande pourrir pendant des semaines avant de la faire bouillir, un goût que peu de cuisiniers vivants partagent avec les Réprouvés."},sec={{t="Délices des Tarides",b="Les chasseurs traversent les Tarides arides en quête de zhevras, de trotteurs des plaines et de raptors. Boustiff', un orc qui campe à l'est de la Croisée, veut autre chose : des rats fouisseurs. Affamé toute la journée, il propose sa recette à tout voyageur prêt à attraper ces rongeurs fouisseurs."},{t="Les nuisibles nains",b="Au cœur des Tarides du sud, des prospecteurs nains creusent la terre rouge de Bael Modan. Leurs travaux ont dérangé des nids de rats fouisseurs. Les nains y voient une infestation ; Boustiff', un festin à portée de main près du site de fouilles."},{t="Une question de goût",b="Boustiff' affirme que les rats fouisseurs sont meilleurs après avoir pourri plusieurs semaines. Pour les voyageurs affamés qui veulent manger tout de suite, il accepte une viande plus fraîche. Sa recette montre à quel point la cuisine de route peut être accommodante aux confins de Kalimdor."}},faq={{q="Qui est Boustiff' ?",a="Boustiff' est un orc qui campe le long du sentier, à l'est de la Croisée dans les Tarides. Toujours affamé, il a des goûts particuliers et apprend aux voyageurs à cuisiner la vermine locale.",al={"boustiff'","qui est boustiff'","orc à l'est de la croisée"}},{q="D'où viennent les rats fouisseurs ?",a="Les rats fouisseurs infestent Bael Modan, un site de fouilles de l'Alliance dans l'extrême sud des Tarides, au sud de Camp Taurajo et au nord du Kraal de Tranchebauge. Les mines naines ont remué le sol et fait surgir des essaims de ces petites créatures.",al={"où trouver des rats fouisseurs","emplacement des rats fouisseurs","trouver des rats fouisseurs"}},{q="Pourquoi Boustiff' veut-il précisément des rats fouisseurs ?",a="Boustiff' dit que les rats fouisseurs sont le festin préféré de tous et que chasser la vermine est un rite de passage pour les voyageurs aguerris. Ils sont l'ingrédient principal de son brouet copieux et odorant.",al={"pourquoi des rats","pourquoi des rats fouisseurs","motivation de boustiff'"}},{q="Le brouet de rat est-il vraiment bon ?",a="Boustiff' trouve le brouet délicieux, même si ses goûts sont extrêmes. Il préfère une viande qui a pourri pendant quelques semaines, ce qui en fait un goût auquel il faut s'habituer, même selon les critères rudes de la Horde.",al={"le brouet est-il bon","manger des rats fouisseurs","goût de la recette de boustiff'"}},{q="Que font les nains à Bael Modan ?",a="Les nains de Bael Modan appartiennent à une expédition de Forgefer. Ils ont bâti un fort et un site de fouilles dans les Tarides du sud, où ils creusent et font exploser la terre en profondeur. Leur présence a exacerbé les tensions avec la Horde et dérangé la vermine locale.",al={"nains dans les tarides","pourquoi bael modan","alliance dans les tarides du sud"}},{q="Faut-il une formation culinaire particulière pour préparer le brouet ?",a="La méthode de Boustiff' demande des notions de cuisine au feu de camp et de préparation du gibier. Toute personne ayant quelques bases en cuisine peut apprendre à faire mijoter ces rongeurs pour obtenir un repas nourrissant.",al={"conditions pour cuisiner","faut-il une compétence en cuisine"}}},fx={["76cb3c44"]={q="À quoi servent les Rats fouisseurs ?",a="Les Rats fouisseurs sont l'ingrédient clé de la savoureuse mixture de Boustiff'. Alors que la plupart des gens détournent le nez devant la vermine, Boustiff' les considère comme un mets culinaire de choix et les laisse mijoter pour en faire un ragoût épais. Bien qu'il préfère en privé les laisser pourrir quelques semaines pour en extraire la saveur mûre et âcre, il cuisinera volontiers des prises fraîches sur place pour les voyageurs affamés à travers Les Tarides arides.",al={"utilisation du rat fouisseur","à quoi sert le rat fouisseur","pourquoi collecter des rats fouisseurs"}}},fp="12,150,18.249.0,18.202.0,18.208.0,12.159.0,28.209.0,41.172.0,37.168.0,36.239.0,55.160.0"}
P.entries["quest:863"] = {n="La fuite",s="À la Videfange, dans le nord des Tarides, Wizzlecrank se fraie un chemin hors d'un site de forage de KapitalRisk. Piégé dans un déchiqueteur prototype volé, le pilote gobelin a besoin de votre protection contre les mercenaires de la compagnie. Vous portez ensuite un message à son contact, Krachevalve, à Cabestan.",h="À la Videfange, dans le nord des Tarides, Wizzlecrank se fraie un chemin hors d'un site de forage de...",kw={"tarides","escorte","ignition","prototype","cabestan","déchiqueteur","la videfange","krachevalve","kapitalrisk","wizzlecrank"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez vous réjouir de voir les activités pétrolières polluantes de KapitalRisk perturbées à la Videfange, une verrue sur les Tarides.",["profession:Engineering"]="Le déchiqueteur prototype révèle les systèmes pneumatiques et les plans de cockpit de KapitalRisk. Les ingénieurs peuvent les étudier parmi les pièces récupérées.",["race:Gnome"]="En tant que gnome, vous reconnaîtrez peut-être la volonté de Wizzlecrank de piloter une machine instable au petit bonheur. Les bricoleurs gobelins, comme les gnomes, ont souvent tendance à bricoler d'abord et à poser des questions ensuite."},sec={{t="Une fuite maladroite",b="À la Videfange, Wizzlecrank peine à maîtriser le déchiqueteur volé. Il a démarré le prototype au cœur du site de forage de KapitalRisk, mais connaît mal ses leviers et ses commutateurs. La lourde machine cahote sur le sol boueux de la carrière. Sa conduite erratique et le grondement de ses articulations alertent les ouvriers et les gardes armés des environs. La fuite furtive se transforme en combat sur la rampe ouest de la fosse d'excavation."},{t="La poursuite de KapitalRisk",b="Les mercenaires de KapitalRisk tentent d'arrêter le prototype volé. Alors que la machine gravit la pente vers le terrain découvert, des escouades cherchent à l'intercepter et à la neutraliser. Le déchiqueteur riposte, mais ne peut résister à leur sabotage sans votre protection. Il franchit le rebord et s'éloigne en chancelant de la principale fosse de forage. Bientôt, la machine subit une panne critique."},{t="Récupération et récompense",b="Wizzlecrank s'échappe vivant de l'épave du déchiqueteur prototype. À l'abri du danger immédiat, la machine tombe en panne et s'effondre sur le sol de la savane. Wizzlecrank s'en extirpe et vous dit de faire rapport à Krachevalve, à Cabestan, tandis qu'il reste avec l'épave.\n\nImpatient d'étudier les plans de KapitalRisk avant que l'occasion ne lui échappe, Krachevalve envoie aussitôt une équipe de récupération gobeline rapporter au port les mécanismes encore intacts."}},faq={{q="Qui est Wizzlecrank et que fait-il dans un déchiqueteur ?",a="Wizzlecrank est un agent et mécanicien qui travaille avec Krachevalve à Cabestan. Il s'est introduit dans le site de forage du nord de KapitalRisk pour voler son dernier prototype expérimental de déchiqueteur, puis s'est retrouvé piégé en tentant de maîtriser les commandes inhabituelles du cockpit.",al={"qui est wizzlecrank","pourquoi un gobelin dans un déchiqueteur","wizzlecrank déchiqueteur"}},{q="Où se déroule cette fuite ?",a="La fuite commence au cœur de la Videfange, un site de forage industriel exploité par KapitalRisk dans le nord des Tarides, juste au nord du bassin de savane aride.",al={"où se trouve la quête la fuite","lieu de la fuite","escorte à la videfange"}},{q="Faut-il escorter le déchiqueteur jusqu'à Cabestan ?",a="Non. Vous escortez Wizzlecrank hors de la fosse de forage et jusqu'à la rampe ouest. Une fois le rebord de la carrière franchi, la machine tombe en panne et Wizzlecrank vous dit de vous rendre seul à Cabestan.",al={"jusqu'où dois-je marcher","itinéraire d'escorte","faut-il aller à cabestan"}},{q="Qui est Krachevalve ?",a="Krachevalve est un technicien gobelin installé près des quais de Cabestan. Il recueille des renseignements industriels sur sa rivale, KapitalRisk, et convoite ses plans mécaniques pour tirer profit de ses innovations technologiques.",al={"qui est krachevalve","pnj de remise de quête krachevalve","histoire de krachevalve"}},{q="Pourquoi le déchiqueteur s'effondre-t-il à la fin ?",a="Wizzlecrank connaît à peine les commandes, et l'embuscade pousse la machine expérimentale à ses limites. Elle subit de fortes contraintes mécaniques en franchissant le périmètre, puis lâche dès qu'elle quitte le site de forage.",al={"pourquoi le déchiqueteur tombe en panne","épave du déchiqueteur","panne du prototype"}},{q="Que se passe-t-il après l'accident du prototype ?",a="Wizzlecrank reste auprès de la machine abattue pendant que vous faites rapport à Krachevalve, à Cabestan. Krachevalve prépare aussitôt une équipe de récupération gobeline pour récupérer les précieux composants du prototype avant que KapitalRisk ne puisse les reprendre.",al={"équipe de récupération","que se passe-t-il ensuite","conclusion de la quête la fuite"}}},fx={["07b3d38e"]={q="Pourquoi Wizzlecrank doit-il s'échapper de La Videfange ?",a="Wizzlecrank a volé un déchiqueteur prototype expérimental juste sous le nez de la KapitalRisk. Piégé au cœur d'un territoire hostile sur le site de forage, il doit piloter cette machine de guerre lourde et inconnue à travers des cercles de Mercenaries en colère et de drudges pour survivre et livrer la technologie volée à son associé à Cabestan.",al={"pourquoi s'échapper de la videfange","mobile de wizzlecrank","pourquoi fuir la kapitalrisk"}},fce70664={q="Pourquoi Wizzlecrank compte-t-il sur vous pour l'escorter ?",a="Faire fonctionner le prototype volé accapare toute l'attention de Wizzlecrank ; il sait à peine quels leviers et boutons le font avancer, et encore moins combattre efficacement. Entouré par les forces hostiles de la KapitalRisk et incapable de se défendre tout en dirigeant l'engin encombrant hors du site de forage, il compte entièrement sur votre lame et vos sorts pour tenir les attaquants à distance.",al={"pourquoi wizzlecrank a-t-il besoin de moi","pourquoi wizzlecrank ne peut-il pas s'échapper seul","pourquoi un aventurier"}}},fp="10,269,16.406.0,23.354.0,18.429.1,51.252.0,34.158.0,58.198.1,20.215.0,43.226.1,41.234.1"}
P.entries["quest:8642"] = {n="L'Ancien Veine-argent",s="Pendant la fête lunaire, les voyageurs trouvent L'Ancien Veine-argent sur les collines au-dessus de Thelsamar, dans le Loch Modan. Ils lui rendent hommage et célèbrent les liens anciens entre les peuples ancestraux d’Azeroth. Il leur accorde une bénédiction ancestrale.",h="Pendant la fête lunaire, les voyageurs trouvent L'Ancien Veine-argent sur les collines au-dessus de...",kw={"ancêtre","pièce des ancêtres","ancien","loch modan","fête lunaire","silvervein","thelsamar"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance dans le Loch Modan, vous pouvez gravir la crête au-dessus de Thelsamar et honorer les morts de l’Antiquité entre deux chasses aux troggs.",["race:Dwarf"]="En tant que nain, vous pouvez honorer votre histoire ancienne commune avec Ancien Silvervein, près de Thelsamar."},sec={{t="Une veille au-dessus de Thelsamar",b="Au-dessus de Thelsamar, Ancien Silvervein veille tandis que les voyageurs lui rendent hommage. Il garde en mémoire les âges passés. Malgré les invasions de troggs et les conflits locaux qui troublent le Loch Modan, l’esprit ancien demeure paisible sur son promontoire."},{t="Honorer les races d’antan",b="Ancien Silvervein accueille les voyageurs qui honorent les races d’antan d’Azeroth. Son salut témoigne de sa reconnaissance ancestrale. À ceux qui lui rendent hommage, il offre un souvenir commémoratif."}},faq={{q="Qui est Ancien Silvervein ?",a="Ancien Silvervein est un esprit ancestral qui apparaît pendant la fête lunaire. Il passe la fête au sommet des hautes falaises près de Thelsamar, dans le Loch Modan.",al={"silvervein","qui est silvervein","ancien silvervein loch modan"}},{q="Où trouver Ancien Silvervein ?",a="Ancien Silvervein attend sur une colline herbeuse qui surplombe Thelsamar, dans le Loch Modan.",al={"emplacement de silvervein","où se trouve ancien silvervein","trouver silvervein"}},{q="Pourquoi chercher Ancien Silvervein ?",a="Pendant la fête lunaire, les voyageurs cherchent Ancien Silvervein pour honorer les ancêtres et les races anciennes. Il leur offre un souvenir festif et une bénédiction ancestrale.",al={"pourquoi rendre visite à silvervein","que fait silvervein","rôle de silvervein"}},{q="Que signifie « races d’antan » ?",a="Les races d’antan sont les peuples anciens d’Azeroth, qui ont vécu et façonné le monde bien avant que les conflits modernes n’occupent le devant de la scène. Leur héritage perdure.",al={"sens de races d’antan","pourquoi les races d’antan"}},{q="Ancien Silvervein accueille-t-il les voyageurs de la Horde ?",a="Oui. Ancien Silvervein accueille les voyageurs pacifiques de tous horizons qui viennent honorer les ancêtres pendant la fête lunaire.",al={"la horde peut-elle parler à silvervein","horde et silvervein"}},{q="Ancien Silvervein a-t-il un lien avec l’invasion des troggs ?",a="Non. Les incursions des troggs et les problèmes causés par les excavateurs troublent le Loch Modan, mais Ancien Silvervein reste à l’écart des conflits militaires locaux et se consacre à honorer les ancêtres.",al={"silvervein et les troggs","silvervein combat-il les troggs"}}},fp="20,217,22.210.0,24.167.0,24.146.0,34.70.0,52.151.0,39.151.0,48.122.0,64.161.0"}
P.entries["quest:8646"] = {n="L'Ancien Cri-du-marteau",s="Pendant le Lunar Festival, vous rencontrez L'Ancien Cri-du-marteau dans le Parc de Hurlevent et honorez les anciennes races avec un jeton cérémoniel.",h="Pendant le Lunar Festival, vous rencontrez L'Ancien Cri-du-marteau dans le Parc de Hurlevent et honorez les...",kw={"ancêtre","ancien cri-du-marteau","le parc","cri-du-marteau","lunar festival","races d'antan","hurlevent"},ang={["faction:Alliance"]="Lors de votre visite dans le Parc de Hurlevent, L'Ancien Cri-du-marteau évoque la vénération, la paix et le passé ancestral commun du monde.",["faction:Horde"]="Pour rejoindre L'Ancien Cri-du-marteau, vous entrez dans Hurlevent et vous dirigez vers le Parc, un voyage périlleux pour un pèlerin de la Horde.",["race:Human"]="Dans le Parc de Hurlevent, L'Ancien Cri-du-marteau vous rappelle que l'histoire d'Azeroth remonte à avant le royaume humain."},sec={{t="Honorer le sang ancien",b="Pendant le Lunar Festival, les esprits ancestraux parcourent Azeroth et offrent sagesse et bénédictions aux voyageurs qui leur rendent hommage. Dans le Parc de Hurlevent, L'Ancien Cri-du-marteau évoque les anciennes races qui foulaient ces terres avant l'essor des royaumes actuels."},{t="Jetons de vénération ancestrale",b="L'Ancien Cri-du-marteau vous demande seulement de reconnaître le passé. Il est soulagé et reconnaissant de voir que les anciennes races sont toujours honorées. En retour, il vous remet un jeton cérémoniel qui unit les vivants aux esprits qui les ont précédés."}},faq={{q="Qui est L'Ancien Cri-du-marteau ?",a="L'Ancien Cri-du-marteau est un esprit ancestral qui apparaît pendant le Lunar Festival. À Hurlevent, il honore les anciennes lignées d'Azeroth et offre bénédictions et jetons à ceux qui lui rendent hommage.",al={"cri-du-marteau","qui est cri-du-marteau","identité de l'ancien cri-du-marteau"}},{q="Où trouver L'Ancien Cri-du-marteau ?",a="Pendant le Lunar Festival, vous pouvez trouver L'Ancien Cri-du-marteau dans le quartier du Parc à Hurlevent.",al={"lieu où se trouve cri-du-marteau","où se trouve cri-du-marteau","cri-du-marteau elwynn"}},{q="Pourquoi L'Ancien Cri-du-marteau parle-t-il des « races d'antan » ?",a="L'Ancien Cri-du-marteau parle des races d'antan, car le Lunar Festival honore les peuples et traditions anciennes. Ils ont façonné Azeroth avant l'essor des établissements modernes.",al={"signification des races d'antan","que signifie cri-du-marteau"}},{q="Quel jeton offre L'Ancien Cri-du-marteau ?",a="L'Ancien Cri-du-marteau offre une Pièce des ancêtres, un jeton cérémoniel remis par les esprits du Lunar Festival aux voyageurs qui vont voir les anciens et leur rendent hommage.",al={"récompense de cri-du-marteau","jeton de cri-du-marteau","que donne-t-il"}},{q="Les aventuriers de la Horde peuvent-ils parler à L'Ancien Cri-du-marteau ?",a="Oui. Les voyageurs de la Horde peuvent parler à L'Ancien Cri-du-marteau, même si Hurlevent est la capitale de l'Alliance.",al={"la horde peut-elle parler à cri-du-marteau","cri-du-marteau et la horde"}},{q="Cette rencontre est-elle liée à une fête en cours ?",a="L'Ancien Cri-du-marteau apparaît pendant le Lunar Festival annuel et accorde des bénédictions avant de regagner le royaume des esprits.",al={"cri-du-marteau est-il toujours là","ancien du lunar festival"}}},fp="21,126,22.233.0,29.224.0,25.199.0,37.91.0,53.165.0,40.156.0,51.100.0,44.121.0"}
P.entries["quest:8648"] = {n="L'Ancien Sombre-noyau",s="Pendant la fête lunaire, les voyageurs trouvent l’Ancien Sombre-noyau à Fossoyeuse et honorent les anciens esprits d’Azeroth. En retour, ils reçoivent une Pièce des ancêtres.",h="Pendant la fête lunaire, les voyageurs trouvent l’Ancien Sombre-noyau à Fossoyeuse et honorent les anciens...",kw={"ancêtre","pièce des ancêtres","l'ancien sombre-noyau","ancien sombre-noyau","anciens","fête lunaire","fossoyeuse"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez participer aux rites de la fête lunaire dans une capitale alliée, sur les continents.",["race:Undead"]="Pour les Réprouvés qui arpentent les ruines de leur ancien royaume, l’Ancien Sombre-noyau évoque des temps plus anciens, avant le Fléau et la chute de Lordaeron."},sec={{t="Un esprit à Fossoyeuse",b="Pendant la fête lunaire, les esprits des anciens ancêtres elfes de la nuit et terrestres apparaissent sur tous les continents. Ils offrent sagesse et bénédictions à ceux qui les recherchent. L’Ancien Sombre-noyau réside dans les salles obscures de Fossoyeuse. Il observe le monde tel qu’il est aujourd’hui et se souvient de ceux qui en ont recherché les origines."},{t="Honorer les ancêtres",b="Rendre visite à l’Ancien Sombre-noyau, c’est honorer une ancienne coutume. C’est témoigner son respect aux vénérables défunts et aux gardiens intemporels d’Azeroth. En récompense de ce pèlerinage, l’esprit offre aux voyageurs une Pièce des ancêtres, gage de bienveillance et de mémoire durable."}},faq={{q="Pourquoi rendre visite à l’Ancien Sombre-noyau ?",a="Rendre visite à l’Ancien Sombre-noyau pendant la fête lunaire honore les peuples anciens d’Azeroth. Lui parler permet de recevoir une Pièce des ancêtres.",al={"objectif de l’ancien sombre-noyau","pourquoi rendre visite à sombre-noyau","but de la quête de sombre-noyau"}},{q="Où trouver l’Ancien Sombre-noyau ?",a="L’Ancien Sombre-noyau se trouve dans la salle du trône en ruine de Lordaeron, au-dessus de la capitale réprouvée de Fossoyeuse.",al={"emplacement de l’ancien sombre-noyau","où se trouve l’ancien sombre-noyau","emplacement de sombre-noyau à fossoyeuse"}},{q="Qu’est-ce que la fête lunaire ?",a="La fête lunaire est une célébration annuelle du souvenir et du renouveau à travers Azeroth. Elle célèbre la victoire contre la Légion ardente et honore les anciens qui ont guidé les races mortelles.",al={"histoire de la fête lunaire","pourquoi les anciens apparaissent","que sont les anciens"}},{q="Que représentent les anciens ?",a="Les anciens sont des esprits ancestraux souvent liés aux elfes de la nuit ou aux premières cultures terrestres. Pendant la fête lunaire, ils apparaissent pour bénir ceux qui se souviennent de leurs actes et perpétuent leurs enseignements.",al={"qui sont les anciens","histoire des anciens de la fête lunaire","esprits ancestraux"}},{q="Les aventuriers de l’Alliance peuvent-ils parler à l’Ancien Sombre-noyau ?",a="L’Ancien Sombre-noyau accueille tous les voyageurs qui parviennent jusqu’à lui. Les voyageurs de l’Alliance doivent braver la capitale réprouvée, lourdement défendue, pour lui parler.",al={"alliance et sombre-noyau","l’alliance peut-elle trouver sombre-noyau","ancien sombre-noyau et alliance"}},{q="Qu’est-ce qu’une Pièce des ancêtres ?",a="Une Pièce des ancêtres est un présent festif offert par les anciens pendant la fête lunaire. Elle honore le passé ancestral et peut être échangée contre des tenues festives et des souvenirs saisonniers.",al={"que sont les pièces des ancêtres","utilité de la pièce des ancêtres","pièce de la fête lunaire"}}},fp="18,158,25.298.0,22.242.0,47.127.0,34.102.0,27.180.0,29.195.0,49.138.0,27.166.0"}
P.entries["quest:8649"] = {n="L'Ancien Front-de-tempête",s="L'Ancien Stormbrow est l'un des esprits antiques honorés pendant la fête lunaire, se tenant près de l'eau non loin de Comté-de-l’Or. Les voyageurs qui viennent trouver cet ancien rendent hommage aux traditions ancestrales et aux anciennes races d'Azeroth. En échange de ce respect témoigné, l'ancien accorde une modeste marque de souvenir.",h="L'Ancien Stormbrow est l'un des esprits antiques honorés pendant la fête lunaire, se tenant près de l'eau non...",kw={"ancêtre","ancien stormbrow","forêt d’elwynn","forge","comté-de-l’or","fête lunaire","marque"},ang={["faction:Alliance"]="Reposant en plein cœur de la Forêt d’Elwynn, l'Ancien Stormbrow est l'un des esprits ancestraux les plus accessibles pour les jeunes aventuriers de l'Alliance traversant Comté-de-l’Or.",["race:Human"]="Pour les humains vivant en Elwynn, la présence de l'Ancien Stormbrow rappelle l'histoire ancienne au-delà des remparts et des guerres récentes de Hurlevent."},sec={{t="Un esprit à Comté-de-l’Or",b="L'Ancien Stormbrow se manifeste près du paisible étang niché juste derrière la forge de Comté-de-l’Or. Alors que le bourg grouille habituellement de gardes en armure, d'artisans et d'aventuriers épuisés en partance pour la forêt, l'arrivée de cet esprit vénéré apporte une parenthèse de calme. Se dressant sous la canopée sereine de la Forêt d’Elwynn, Stormbrow accueille tous ceux désireux d'honorer la longue histoire du royaume."},{t="Honorer les anciennes races",b="La fête lunaire marque une période où les esprits des grands ancêtres reviennent marcher parmi les vivants. L'Ancien Stormbrow félicite les voyageurs mortels qui prennent le temps de se souvenir de ceux qui les ont précédés. En échange de la reconnaissance de la sagesse et de l'héritage des peuples anciens, il accorde sa bénédiction ainsi qu'une pièce commémorative pour célébrer cette période."}},faq={{q="Où puis-je trouver l'Ancien Stormbrow ?",a="L'Ancien Stormbrow se tient juste à côté de l'étang situé directement derrière la forge de Comté-de-l’Or, dans la Forêt d’Elwynn.",al={"localisation de stormbrow","où se trouve l'ancien stormbrow","ancien de comté-de-l’or"}},{q="Qui est l'Ancien Stormbrow ?",a="L'Ancien Stormbrow est un Esprit ancestral qui apparaît pendant la fête lunaire, représentant les anciens vénérés des peuples ancestraux d'Azeroth.",al={"qui est stormbrow","histoire de stormbrow","identité de l'ancien stormbrow"}},{q="Quel est le but d'une visite à l'Ancien Stormbrow ?",a="Rendre visite à l'Ancien Stormbrow permet aux voyageurs de rendre hommage aux ancêtres antiques pendant la fête. En échange du respect de ces traditions, il offre ses salutations ainsi qu'un témoignage de gratitude.",al={"pourquoi rendre visite à stormbrow","quête de l'ancien stormbrow","rôle de l'ancien stormbrow"}},{q="Les joueurs de la Horde peuvent-ils parler à l'Ancien Stormbrow ?",a="Bien que les anciens de la fête lunaire honorent quiconque vient à eux en paix, Comté-de-l’Or est un territoire de l'Alliance lourdement gardé, ce qui rend toute visite par des voyageurs de la Horde extrêmement périlleuse.",al={"stormbrow horde","la horde peut-elle visiter stormbrow"}},{q="Quel témoignage l'Ancien offre-t-il ?",a="L'Ancien Stormbrow offre une Pièce des ancêtres, une marque traditionnelle de respect et de souvenir partagée par les anciens tout au long des festivités.",al={"récompense de stormbrow","quel insigne","pièce lunaire stormbrow"}},{q="Pourquoi Stormbrow mentionne-t-il les « anciennes races » ?",a="Stormbrow félicite les voyageurs de se souvenir que les civilisations actuelles foulent des terres façonnées par des peuples anciens et des coutumes immuables, bien avant l'avènement des royaumes modernes.",al={"signification anciennes races","pourquoi anciennes races","dialogue de stormbrow"}}},fp="19,182,21.239.0,24.262.0,33.104.0,23.150.0,48.150.0,43.152.0,32.135.0,45.191.0"}
P.entries["quest:865"] = {n="La corne, c'est le pied",s="À Cabestan, Mebok Mizzyrix cherche des cornes de raptor intactes pour un projet personnel. Il croit que les raptors des Tarides doivent leur ruse à leurs cornes et paie des voyageurs pour chasser des Sunscale Scytheclaws.",h="À Cabestan, Mebok Mizzyrix cherche des cornes de raptor intactes pour un projet personnel.",kw={"les tarides","corne de raptor intacte","mebok mizzyrix","la corne, c'est le pied","cabestan","smart drinks","cartel gentepression","sunscale scytheclaw"},ang={["class:Hunter"]="En tant que chasseur familier des meutes de raptors de Kalimdor, vous savez combien elles peuvent être rusées et mortelles. Croire que leur intelligence peut se mettre en bouteille relève du charlatanisme gobelin de Mebok.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous pouvez trouver un point d’appui neutre dans les Tarides dominées par la Horde, à Cabestan. Les petits travaux comme celui de Mebok permettent de gagner des pièces et la faveur du Cartel Gentepression."},sec={{t="L’esprit d’entreprise gobelin",b="Mebok Mizzyrix cherche fortune à Cabestan, où les gobelins tentent sans cesse de monter un nouveau projet. Il a vu les raptors des Tarides agir avec plus d’astuce et de coordination que les bêtes d’ailleurs. Mebok a donc décidé que leur intelligence devait se trouver dans leurs cornes. Il ne cherche pas à mener une enquête officielle. Il compte tirer profit de cette idée."},{t="Les Sunscale Scytheclaws",b="Mebok veut des cornes intactes de Sunscale Scytheclaws, parmi les prédateurs les plus redoutables des Tarides. Ils rôdent dans les étendues méridionales des Tarides et près des frontières septentrionales d’Orneval. Ces raptors chassent en meute et défendent farouchement leur territoire. Les abattre et prélever leurs cornes intactes exige de l’habileté au combat."},{t="Une recette pour s’enrichir",b="Mebok Mizzyrix prévoit de réduire les cornes intactes en fine poudre, puis de la faire infuser dans des boissons. Il les appelle « Smart Drinks » et espère que les clients achèteront de l’esprit en bouteille. Mebok est convaincu que ce projet le rendra riche du jour au lendemain."}},faq={{q="Pourquoi Mebok Mizzyrix veut-il des cornes de raptor ?",a="Mebok croit que la ruse des raptors des Tarides se trouve dans leurs cornes. Il prévoit de les réduire en poudre, d’en faire des « Smart Drinks » et de les vendre pour en tirer profit.",al={"pourquoi les cornes de raptor","objectif de mebok","que veut mebok"}},{q="Où trouve-t-on les Sunscale Scytheclaws ?",a="Les Sunscale Scytheclaws parcourent le sud des Tarides et les étendues septentrionales près de la frontière d’Orneval.",al={"où trouver les scytheclaws","emplacement des sunscale scytheclaws","emplacement des cornes de raptor"}},{q="Les cornes de raptor sont-elles vraiment magiques ou capables d’améliorer l’esprit ?",a="L’affirmation de Mebok selon laquelle les cornes de raptor renferment leur intelligence relève de la pseudo-science gobeline motivée par le profit. Les raptors des Tarides sont rusés, mais rien n’indique ici que leurs cornes soient magiques ou capables d’améliorer l’esprit.",al={"les smart drinks sont-elles efficaces","les raptors sont-ils intelligents","histoire de l’intelligence des raptors"}},{q="Qui est Mebok Mizzyrix ?",a="Mebok Mizzyrix est un marchand gobelin ambitieux de Cabestan, la ville portuaire. Il poursuit des projets et concoctions douteux pour faire fortune grâce aux voyageurs de passage.",al={"qui est mebok","histoire de mebok mizzyrix","mebok à cabestan"}},{q="Que se passe-t-il après avoir récupéré les cornes ?",a="Mebok prévoit de réduire les cornes intactes en poudre et d’en faire des boissons qu’il appelle « Smart Drinks ».",al={"quête suivante après la corne, c’est le pied","quête des smart drinks","suite de quêtes des cornes de raptor"}},{q="Les joueurs de l’Alliance peuvent-ils aider Mebok dans cette tâche ?",a="Oui. Cabestan est un port ouvert géré par le Cartel Gentepression. Mebok est un gobelin neutre qui fait affaire avec la Horde comme avec l’Alliance.",al={"cette quête est-elle réservée à la horde","cornes de raptor pour l’alliance","l’alliance peut-elle faire la quête des cornes de raptor"}}},fx={["3bee14c6"]={q="À quoi sert la Corne de raptor intacte ?",a="Mebok Mizzyrix a l'intention de broyer les cornes intactes pour en faire une fine poudre et de les mélanger à du vin. Convaincu que les raptors des Tarides stockent leur intellect rusé directement dans leurs cornes, il prévoit de mettre la concoction en bouteille et de la vendre comme un stimulant intellectuel appelé \"boisson intelligente\", dans le but de réaliser d'énormes profits sur le dos d'acheteurs crédules.",al={"utilisation de la corne de raptor intacte","pourquoi les cornes de raptor intactes","but de la corne de raptor"}},["5cf02a79"]={q="Que sont les Sunscale Scytheclaws et pourquoi les chasser ?",a="Les Sunscale Scytheclaws sont des raptors agressifs et rusés originaires des étendues arides des Tarides, parcourant à la fois les régions du sud et les plaines du nord près de la frontière de Orneval. Connus pour leur coordination exceptionnelle et leur férocité par rapport aux autres bêtes sauvages, leur remarquable acuité en fait la cible privilégiée de Mebok pour récolter la poudre de corne stimulante intellectuellement.",al={"sunscale scytheclaws","pourquoi les raptors sunscale","lore des sunscale scytheclaws"}},["57350450"]={q="Pourquoi Mebok Mizzyrix vous engage-t-il au lieu de chasser les raptors lui-même ?",a="Mebok est un entrepreneur gobelin ambitieux, pas un pisteur chevronné ou un chasseur de gros gibier. S'aventurer dans les plaines rudes des Tarides pour affronter des bêtes mortelles aux griffes acérées est bien trop risqué alors qu'il peut simplement payer un aventurier pour affronter la nature sauvage et rapporter des spécimens immaculés pendant qu'il garde les mains propres et concocte son produit en toute sécurité.",al={"pourquoi moi mebok","pourquoi mebok a-t-il besoin de moi","pourquoi engager un aventurier"}}},fp="12,192,23.321.0,24.322.0,19.230.1,42.158.0,39.100.0,52.187.0,22.166.0,40.104.1,47.146.0"}
P.entries["quest:8652"] = {n="L'Ancien Né-au-tombeau",s="Pendant la fête lunaire, l’Ancien Né-au-tombeau attend à l’extérieur de Brill, dans les Clairières de Tirisfal. Les voyageurs le trouvent parmi ses bosquets flétris pour honorer les anciens aïeux d’Azeroth et recevoir sa bénédiction ainsi qu’un gage de fête.",h="Pendant la fête lunaire, l’Ancien Né-au-tombeau attend à l’extérieur de Brill, dans les Clairières de...",kw={"brill","pièce des ancêtres","ancien né-au-tombeau","né-au-tombeau","fête lunaire","clairières de tirisfal"},ang={["class:Druid"]="En tant que druide, vous vénérez les anciens de la fête lunaire, liens avec le monde antique d’avant le Sundering, au-delà des frontières entre factions qui les entourent.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous devez traverser prudemment les Clairières de Tirisfal pour trouver l’Ancien Né-au-tombeau, car Brill est un refuge réprouvé lourdement fortifié.",["race:Undead"]="En tant que Réprouvés vivant à Brill, vous voyez l’arrivée des anciens esprits ancestraux comme un rappel de l’histoire profonde d’Azeroth, au-delà des tragédies récentes du Fléau."},sec={{t="Une veillée spectrale à Brill",b="Dans les Clairières de Tirisfal, les Réprouvés vivent au milieu de manoirs en ruine et de tombes. Pendant la fête lunaire, un esprit ancien apparaît juste à l’extérieur de Brill. L’Ancien Né-au-tombeau accueille les pèlerins qui s’arrêtent pour honorer les anciennes coutumes, même dans une terre dévastée par le Fléau et reconquise par les morts-vivants."},{t="Honorer les races anciennes",b="Pendant la fête lunaire, les esprits d’autrefois reviennent avec leur sagesse et leur gratitude. Lorsque vous approchez de l’Ancien Né-au-tombeau, il vous dit que cela le réconforte de voir les habitants de Tirisfal honorer encore leurs ancêtres malgré le déclin de ces terres. Il vous donne une Pièce des ancêtres lorsque vous le saluez."}},faq={{q="Où se trouve l’Ancien Né-au-tombeau ?",a="L’Ancien Né-au-tombeau attend près de la route, à l’extérieur de Brill, dans les Clairières de Tirisfal.",al={"emplacement de l’ancien né-au-tombeau","où trouver né-au-tombeau","coordonnées de né-au-tombeau"}},{q="Que se passe-t-il quand vous parlez à l’Ancien Né-au-tombeau ?",a="Lorsque vous saluez l’Ancien Né-au-tombeau, il vous félicite d’honorer les peuples anciens d’Azeroth et vous donne une Pièce des ancêtres pour la fête lunaire.",al={"récompense de né-au-tombeau","né-au-tombeau fête lunaire","que vous donne-t-il"}},{q="Pourquoi un ancien se tient-il dans les Clairières de Tirisfal ?",a="Pendant la fête lunaire, des esprits ancestraux apparaissent partout en Azeroth, des forêts kaldorei aux terres meurtries par la guerre et la peste. L’Ancien Né-au-tombeau veille sur le nord de Lordaeron, où la mort menace d’éclipser l’histoire de la région.",al={"pourquoi est-il à tirisfal","histoire de né-au-tombeau","qui est l’ancien né-au-tombeau"}},{q="Les membres de l’Alliance peuvent-ils rendre visite à l’Ancien Né-au-tombeau ?",a="L’Ancien Né-au-tombeau est un esprit neutre qui parle aussi bien aux membres de l’Alliance qu’à ceux de la Horde. Comme il attend juste à l’extérieur de la ville réprouvée de Brill, les aventuriers de l’Alliance doivent se méfier des gardes locaux.",al={"l’alliance peut-elle parler à né-au-tombeau","l’ancien né-au-tombeau alliance","né-au-tombeau hostile"}},{q="À quoi sert la Pièce des ancêtres ?",a="Pendant la fête lunaire, vous pouvez échanger contre des habits festifs, des recettes de feux d’artifice et d’autres gages de fête les Pièces des ancêtres recueillies auprès d’anciens comme Né-au-tombeau, au Reflet-de-Lune.",al={"utilité de la pièce des ancêtres","à quoi servent les pièces lunaires"}},{q="L’Ancien Né-au-tombeau fait-il partie des Réprouvés ?",a="Non. L’Ancien Né-au-tombeau est un esprit ancien honoré pendant la fête lunaire, et non l’un des Réprouvés. Sa forme fantomatique et son nom près de Brill appartiennent à la lignée des anciens d’Azeroth, et non aux Réprouvés de Sylvanas.",al={"né-au-tombeau est-il mort-vivant","l’ancien né-au-tombeau est-il réprouvé"}}},fp="19,216,24.295.0,24.274.0,33.71.0,47.144.0,52.231.0,43.192.0,38.177.0,39.205.0"}
P.entries["quest:8653"] = {n="L'Ancien Puits-doré",s="Pendant la fête lunaire, l’Ancien Puits-doré accueille les voyageurs à Kharanos et les invite à honorer les ancêtres. Votre visite perpétue leur mémoire dans les terres enneigées des nains.",h="Pendant la fête lunaire, l’Ancien Puits-doré accueille les voyageurs à Kharanos et les invite à honorer les...",kw={"ancêtre","pièce des ancêtres","dun morogh","ancien puits-doré","goldwell","forgefer","kharanos","fête lunaire","thunderbrew"},ang={["faction:Alliance"]="En territoire de l’Alliance, Goldwell est l’un des anciens les plus faciles à visiter pour les jeunes héros de l’Alliance, sur la route entre la Vallée des Frigères et Forgefer.",["faction:Horde"]="Pour rejoindre Goldwell, vous devez vous faufiler au cœur de Dun Morogh, au-delà des gardes nains et du froid mordant qui règne devant les hautes portes de Forgefer.",["race:Dwarf"]="Nain de retour de Forgefer, vous rencontrez un ancien d’ascendance antique devant la plus célèbre taverne de Kharanos, la Distillerie Tonnebière. Cette visite mêle révérence intemporelle et fierté locale."},sec={{t="Salutations montagnardes",b="À côté de la Distillerie Tonnebière, l’Ancien Puits-doré salue ceux qui suivent la route commerciale jusqu’aux portes de Forgefer. Voyageurs fatigués, aventuriers et habitants passent tous devant lui. Il se souvient des temps anciens, lorsque les premiers mortels marchaient sous les étoiles d’Azeroth."},{t="Honorer les ancêtres",b="Goldwell se réjouit que les mortels se souviennent encore des races anciennes et de leurs actes. Il vous remercie de vous être arrêté pour leur rendre hommage. Puis il vous remet une Pièce des ancêtres en signe de sa bénédiction."}},faq={{q="Où trouver l’Ancien Puits-doré ?",a="L’Ancien Puits-doré vous attend devant l’auberge de la Distillerie Tonnebière, à Kharanos. Le village se trouve le long de la route enneigée de Dun Morogh, juste au sud-ouest des portes de Forgefer.",al={"emplacement de l’ancien puits-doré","où se trouve l’ancien puits-doré","emplacement de goldwell"}},{q="Pourquoi rechercher l’Ancien Puits-doré ?",a="Pendant la fête lunaire, les voyageurs recherchent l’Ancien Puits-doré pour honorer les esprits ancestraux du monde. Leur respect montre que les races mortelles se souviennent encore des sacrifices et de la sagesse des temps anciens.",al={"pourquoi rendre visite à l’ancien puits-doré","que fait l’ancien puits-doré","quête de goldwell"}},{q="Quelle récompense l’Ancien Puits-doré offre-t-il ?",a="L’Ancien Puits-doré remet aux voyageurs une Pièce des ancêtres, un jeton béni par les anciens de la fête. Elle peut être présentée au Cercle cénarien, à Reflet-de-Lune, contre des articles de fête.",al={"récompense de l’ancien puits-doré","que reçoit-on de l’ancien puits-doré","pièce des ancêtres de goldwell"}},{q="Cette quête est-elle accessible aux voyageurs de la Horde ?",a="Oui. Goldwell et les autres anciens de la fête sont des esprits ancestraux neutres qui accueillent les aventuriers de toutes les factions. Les voyageurs de la Horde doivent éviter les montagnards nains qui patrouillent à Kharanos.",al={"la horde peut-elle parler à l’ancien puits-doré","ancien puits-doré et horde","l’ancien puits-doré est-il amical envers la horde"}},{q="Pourquoi l’Ancien Puits-doré réside-t-il à Dun Morogh ?",a="Les anciens de la fête lunaire apparaissent partout en Azeroth, là où les civilisations mortelles ont bâti des communautés durables. Goldwell a choisi Kharanos pour bénir ceux qui vivent près du cœur du royaume des nains.",al={"pourquoi goldwell est-il à kharanos","pourquoi dun morogh","goldwell en terre naine"}},{q="Peut-on terminer cette quête plus d’une fois ?",a="Non. À chaque fête, un aventurier peut honorer l’Ancien Puits-doré une fois et recevoir une seule bénédiction et une seule pièce.",al={"la quête de l’ancien puits-doré est-elle répétable","quête quotidienne de l’ancien puits-doré","réinitialisation de goldwell"}}},fp="18,181,19.257.0,22.184.0,32.154.0,50.187.0,40.168.0,43.186.0,45.195.0,43.109.0"}
P.entries["quest:86574"] = {n="Stonetalon Supply Run",s="Au Pic des Serres-Rocheuses, l’aubergiste Faralia attend des provisions après la mort d’un coursier et la disparition de la cargaison. Les wyvernes Pridewing ont peut-être emporté les ballots.",h="Au Pic des Serres-Rocheuses, l’aubergiste Faralia attend des provisions après la mort d’un coursier et la...",kw={"coursier","aubergiste faralia","cargaison disparue","wyvernes pridewing","provisions des serres-rocheuses","livraison de provisions aux serres-rocheuses"},sec={{t="Une cargaison perdue",b="Un coursier mort gît près d’un paquet éparpillé. Une note désigne l’aubergiste Faralia, au Pic des Serres-Rocheuses, comme destinataire. Vous devez récupérer les Stonetalon Supplies disparues auprès des Pridewing Wyverns. Faralia espère que la cargaison arrivera bientôt."},{t="Les remerciements de Faralia",b="Faralia apprend que le coursier n’a pas survécu. Elle dit qu’elle utilisera les provisions récupérées afin que la perte du coursier ne soit pas vaine."}},faq={{q="À qui étaient destinées les provisions ?",a="La note indique que l’aubergiste Faralia, au Pic des Serres-Rocheuses, en est la destinataire.",al={"qui reçoit les provisions","cargaison de faralia"}},{q="Qu’est-il arrivé au coursier ?",a="Le coursier a été tué, et son corps porte les marques de nombreuses attaques de wyvernes Pridewing.",al={"coursier mort","que s’est-il passé ici"}},{q="Qu’est-ce qui a disparu ?",a="Une cargaison de provisions destinée à l’aubergiste Faralia a disparu du paquet abandonné par le coursier.",al={"provisions disparues","contenu du paquet"}},{q="Où pourraient se trouver les provisions ?",a="Les Pridewing Wyverns ont peut-être emporté les ballots de provisions pour garnir leurs nids.",al={"provisions des wyvernes","où sont les ballots"}},{q="De quoi Faralia a-t-elle besoin ?",a="Faralia attend la cargaison de provisions qui lui était destinée au Pic des Serres-Rocheuses.",al={"besoins de l’aubergiste","livraison de provisions aux serres-rocheuses"}}},fp="21,168,15.251.0,16.139.1,25.74.0,29.88.0,18.96.0,28.83.0,23.92.0"}
P.entries["quest:86576"] = {n="Bloodfury Trinkets",s="Mor'rogal vous demande de lui apporter des pierres de soleil trouvées chez les harpies Bloodfury du Val calciné. Il dit qu'elles sont liées aux lumières du ciel.",h="Mor'rogal vous demande de lui apporter des pierres de soleil trouvées chez les harpies Bloodfury du Val...",kw={"harpies bloodfury","bloodfury trinkets","le val calciné","pierres de soleil scintillantes","lumières du ciel","mor'rogal","sanctuaires","pierres de soleil"},sec={{t="Pierres des harpies",b="Les harpies Bloodfury ramassent des objets brillants, notamment des pierres de soleil jaune doré. Mor'rogal se trouve sur les collines au-dessus de vous et a parlé de les utiliser. Il vous demande de lui apporter toutes les pierres de soleil scintillantes que vous trouverez."},{t="La lumière dans la pierre",b="Mor'rogal dit que les pierres de soleil reflètent la majesté du soleil. Elles peuvent orner les sanctuaires et les foyers de petites lueurs. La nuit, la lune leur prête sa beauté argentée. À ses yeux, elles rappellent un lien avec les lumières du ciel."}},faq={{q="Que ramassent les harpies Bloodfury ?",a="Les harpies Bloodfury ramassent des objets brillants, notamment des pierres de soleil jaune doré.",al={"objets brillants des harpies","bloodfury trinkets","que ramassent les harpies"}},{q="Qui veut les pierres de soleil ?",a="Mor'rogal, qui se trouve sur les collines au-dessus de vous, a parlé d'utiliser les pierres de soleil.",al={"qui a besoin de pierres de soleil","babiole de mor'rogal","qui donne les pierres de soleil"}},{q="À quoi Mor'rogal utilise-t-il les pierres de soleil ?",a="Mor'rogal dit que les pierres de soleil peuvent orner les sanctuaires et les foyers de petites lueurs.",al={"pourquoi mor'rogal veut des pierres","utilisation des pierres de soleil","à quoi servent les pierres"}},{q="Que représentent les pierres de soleil pour Mor'rogal ?",a="Les pierres de soleil rappellent à Mor'rogal un lien avec les lumières du ciel.",al={"signification des pierres de soleil","pierres des lumières du ciel","pourquoi les pierres sont spéciales"}}},fp="18,140,15.207.0,14.217.0,42.78.0,24.75.0,38.79.0,40.70.0"}
P.entries["quest:86585"] = {n="Banner of the Fallen",s="En territoire trogg, la quête de la Montagnarde Ylva pour retrouver ses camarades disparus s’est achevée sous l’étendard piétiné de Forgefer. Le relever fait revenir le trogg qui l’a abattue.",h="En territoire trogg, la quête de la Montagnarde Ylva pour retrouver ses camarades disparus s’est achevée sous...",kw={"banner of the fallen","capitaine rudagite","headsplitter","bannière de forgefer","étendard de forgefer","montagnarde ylva","troggs","ylva"},ang={["faction:Alliance"]="L’étendard de Forgefer représente l’allégeance des nains et leur défi en territoire trogg. Le récupérer rend hommage aux soldats tombés qui tiennent la ligne pour l’Alliance.",["race:Dwarf"]="La Montagnarde Ylva est morte en défendant l’honneur de Forgefer et en recherchant ses camarades disparus. Récupérer sa bannière piétinée et venger sa mort touche au cœur de la fierté et du devoir des nains."},sec={{t="L’étendard piétiné",b="L’étendard de Forgefer piétiné de la Montagnarde Ylva marque l’endroit où l’éclaireuse de l’Alliance a trouvé la mort. Elle s’était aventurée en territoire trogg pour retrouver des camarades disparus en patrouille, portant la bannière de la cité en signe de défi. Un puissant trogg l’a frappée avec assez de force pour briser ses défenses. L’étendard est resté dans la poussière."},{t="Venger Ylva",b="Headsplitter, la brute responsable de la mort d’Ylva, a reconnu l’étendard de Forgefer et la menace qu’il représentait. Relever la bannière tombée au sol défie ouvertement le trogg et le fait revenir pour défendre sa victime. Une fois Headsplitter tué, l’étendard abîmé peut être rendu au Capitaine Rudagite. Il s’arrange pour que l’arme d’Ylva soit transmise et que la bannière soit nettoyée et préservée en son honneur."}},faq={{q="Qui était la montagnarde tombée au combat ?",a="La Montagnarde Ylva était une naine indépendante d’esprit, partie en territoire trogg à la recherche de montagnards qui n’étaient pas revenus de patrouille. Elle portait un étendard de Forgefer et voulait montrer la détermination des nains face aux troggs, avant qu’ils ne l’abattent.",al={"qui était la montagnarde","lore sur ylva","qui est mort avec la bannière"}},{q="De quoi parle la quête Banner of the Fallen ?",a="Vous découvrez le corps de la Montagnarde Ylva et l’étendard de Forgefer piétiné qu’elle portait. Relever la bannière fait sortir son meurtrier, le trogg Headsplitter, afin que vous puissiez la venger et rendre l’étendard au Capitaine Rudagite.",al={"qu’est-ce que banner of the fallen","que se passe-t-il dans banner of the fallen","quête de la bannière de forgefer"}},{q="Qui a tué la Montagnarde Ylva ?",a="Un trogg connu sous le nom de Headsplitter a tué Ylva. Il a peut-être asséné le coup fatal à son crâne avec une lourde massue à pointes, lui faisant perdre son heaume. Relever l’étendard de Forgefer provoque le retour de la créature.",al={"qui a tué ylva","quel trogg a tué la montagnarde","trogg headsplitter"}},{q="Qui est le Capitaine Rudagite ?",a="Le Capitaine Rudagite est l’officier nain qui supervise les opérations des montagnards et reçoit l’étendard retrouvé d’Ylva. Il reconnaît son courage et son indépendance farouche, et promet de nettoyer et d’exposer l’étendard en son honneur.",al={"qui est rudagite","où rendre la bannière","bannière du capitaine rudagite"}},{q="Pourquoi la Montagnarde Ylva est-elle entrée seule en territoire trogg ?",a="Ylva est partie seule enquêter sur la disparition de montagnards qui n’étaient pas revenus d’une patrouille en territoire trogg. Farouchement indépendante, elle portait la bannière pour montrer que Forgefer ne se soumettrait jamais aux troggs.",al={"pourquoi ylva est-elle entrée en territoire trogg","pourquoi ylva était-elle seule","ylva et la patrouille disparue"}},{q="Comment attirer le trogg Headsplitter ?",a="Headsplitter se souvient de l’étendard de Forgefer après avoir abattu la Montagnarde Ylva. Planter et relever à nouveau la bannière piétinée provoque le retour du trogg, qui vient achever ce qu’il a commencé.",al={"comment invoquer headsplitter","faire sortir headsplitter","relever l’étendard"}}},fp="20,177,21.319.0,18.399.1,31.250.0,45.216.0,28.206.0,25.230.0,55.217.0,40.186.0"}
P.entries["quest:86611"] = {n="Stag Lord's Bauble",s="Au fond d’un lac souillé repose une statue érodée de cerf, ornée d’un médaillon serti d’une pierre d’un vert maladif. La vase a englouti son histoire, mais les elfes de la nuit de la Clairière de Griffebranche reconnaîtront peut-être cette sculpture antique.",h="Au fond d’un lac souillé repose une statue érodée de cerf, ornée d’un médaillon serti d’une pierre d’un vert...",kw={"bauble","cristal","énergie gangrenée","malorne","médaillon","stag lord","clairière de griffebranche"},ang={["class:Druid"]="Le Grand Cerf est sacré pour le Cercle cénarien. Découvrir ne serait-ce qu’un fragment du monument de Malorne souillé par la magie verte exige des réponses de la part des anciens de la clairière.",["race:NightElf"]="Malorne est vénéré sur vos terres ancestrales. Voir une relique du Stag Lord touchée par la corruption démoniaque appelle une action rapide pour empêcher la souillure de se propager."},sec={{t="Un monument englouti",b="Au fond d’un bassin de vase putride, un cerf de pierre gît, érodé par la fange. Nul ne sait comment la sculpture a atteint le fond du lac, mais un médaillon pend toujours à son cou. L’unique cristal serti dans la pierre luit d’un éclat malsain, vert. Apporter l’objet à la Clairière de Griffebranche pourrait révéler où se dressait autrefois le monument."},{t="Souillé par la Légion",b="Le médaillon ornait autrefois une statue au sanctuaire de Malorne. Durant la guerre, des démons précipitèrent le monument sur les pentes de la montagne. Au fil des ans, la pierre absorba la magie gangrenée jusqu’à ce qu’une puissance sombre s’y installe, obligeant les gardiens de la Clairière de Griffebranche à briser le cristal pour de bon."}},faq={{q="Où la statue du cerf a-t-elle été trouvée ?",a="Le monument érodé représentant un cerf repose sous une vase putride, au fond d’un lac.",al={"emplacement de la statue","statue de cerf dans le lac"}},{q="Qu’est-ce que le Stag Lord's Bauble ?",a="C’est un médaillon serti d’un unique cristal qui brille d’une lueur verte malsaine.",al={"définition de bauble","cristal de cerf"}},{q="Où faut-il apporter le médaillon ?",a="Les habitants de la Clairière de Griffebranche se souviennent peut-être de l’origine du monument englouti et de sa pierre souillée.",al={"qui connaît l’histoire","où apporter le bauble"}},{q="Qui est le Stag Lord ?",a="Le Stag Lord est Malorne, l’ancien cerf blanc vénéré dans les forêts du nord.",al={"identité du stag lord","nom du stag lord"}}},fp="18,220,17.329.0,21.288.1,32.74.0,31.94.0,36.101.0,21.89.0"}
P.entries["quest:86613"] = {n="Outils d’excavation",s="Magmar Fellhew vous demande de rapporter les outils abandonnés lorsque les troggs ont chassé les nains de leur chantier de fouilles. Ces outils pourront aider les fouilleurs à reprendre le travail une fois l’invasion maîtrisée.",h="Magmar Fellhew vous demande de rapporter les outils abandonnés lorsque les troggs ont chassé les nains de...",kw={"camp","chantier de fouilles","nains","fouilles","outils de fouille","magmar fellhew","troggs"},sec={{t="Les outils abandonnés",b="Magmar Fellhew a besoin des outils de fouille que les nains ont laissés derrière eux lorsque les troggs ont envahi leur camp. Vous pouvez les rapporter aux fouilleurs, dont les travaux sont interrompus par l’invasion."}},faq={{q="Pourquoi Magmar a-t-il besoin des outils de fouille ?",a="Les nains ont laissé la plupart de leurs outils derrière eux lorsque les troggs ont envahi leur camp. Ces outils aideront les fouilleurs à reprendre le travail une fois l’invasion maîtrisée.",al={"pourquoi les outils","outils de magmar","outils de fouille"}},{q="Qui est Magmar Fellhew ?",a="Magmar Fellhew est le fouilleur qui vous demande de rapporter les outils abandonnés.",al={"qui est magmar","magmar","homme aux outils"}},{q="Pourquoi les nains ont-ils laissé les outils ?",a="Les nains ont dû laisser la plupart de leurs outils derrière eux lorsque les troggs ont envahi leur camp.",al={"fuite des nains","pourquoi abandonnés","troggs outils"}},{q="Quel problème touche le chantier de fouilles ?",a="Les troggs ont envahi le camp, forçant les nains à abandonner la plupart de leurs outils et à interrompre leurs travaux jusqu’à ce que l’invasion soit maîtrisée.",al={"problème du chantier de fouilles","que s’est-il passé au camp","problème de fouilles"}}},fp="16,184,17.181.0,42.157.0,22.75.0,36.83.0,33.137.0"}
P.entries["quest:86614"] = {n="Silver of the Waves",s="Une pince à cheveux en argent égarée attend parmi des débris de pêche, tandis que sa propriétaire est accaparée par ses corvées quotidiennes. La retrouver lui apporte du soulagement et lui rend un souvenir qu’elle croyait perdu dans l’eau.",h="Une pince à cheveux en argent égarée attend parmi des débris de pêche, tandis que sa propriétaire est...",kw={"corvées","débris de pêche","pince à cheveux","k.d.","monogramme","souvenir en argent","silver of the waves"},sec={{t="Un souvenir parmi les débris",b="Parmi des débris de pêche abandonnés, vous trouvez une pince à cheveux en argent ouvragée, marquée des initiales K.D. Des hameçons rouillés et des bobines de fil métallique brisées gisent à proximité. L’humidité a terni la pince, mais son travail minutieux reste visible sous la corrosion."},{t="Faire briller le souvenir",b="La pince appartient à une habitante du coin, travailleuse et accaparée par ses corvées quotidiennes. Vous lui rendez ce souvenir qu’elle croyait perdu à jamais dans l’eau. Un peu de polissage suffira à lui rendre son éclat, et sa propriétaire reconnaissante se réjouit de le retrouver."}},faq={{q="Qu’est-ce que Silver of the Waves ?",a="Vous trouvez la pince à cheveux en argent ternie parmi des débris de pêche abandonnés, puis partez à la recherche de sa propriétaire. Elle porte les initiales K.D.",al={"silver of the waves","qu’est-ce que silver of the waves","quête de la pince à cheveux"}},{q="À qui appartient la pince à cheveux trouvée dans les débris ?",a="La pince à cheveux porte les initiales K.D. Sa propriétaire la reconnaît quand vous la lui rendez et se montre reconnaissante de retrouver un souvenir qu’elle croyait perdu à jamais.",al={"monogramme kd","à qui est la pince à cheveux","qui est kd"}},{q="Où la pince à cheveux a-t-elle été perdue ?",a="La pince à cheveux se trouve parmi des débris de pêche abandonnés, près de bobines de fil métallique brisées et d’hameçons rouillés. L’entrée ne précise pas où elle a été perdue.",al={"où la pince à cheveux a-t-elle été trouvée","emplacement de la pince à cheveux"}},{q="Dans quel état se trouve la pince à cheveux ?",a="La pince à cheveux ouvragée en argent est ternie par l’humidité et les intempéries, mais sa facture reste visible. Un peu de polissage lui rendra son éclat.",al={"état de la pince en argent","la pince à cheveux est-elle cassée"}},{q="Comment commence cette quête ?",a="Vous trouvez la pince à cheveux monogrammée parmi des déchets de pêche, des bobines de fil métallique brisées et des hameçons rouillés. Puis, vous partez à la recherche de sa propriétaire.",al={"qui donne la quête","comment commencer silver of the waves"}},{q="Pourquoi est-il important de rendre la pince à cheveux ?",a="Sa propriétaire croyait ce souvenir perdu à jamais dans l’eau. Le retrouver la soulage, et elle se réjouit de récupérer un bien précieux.",al={"récompense de la pince à cheveux","pourquoi rendre la pince à cheveux"}}},fp="19,171,25.231.0,19.232.0,28.126.0,39.141.0,29.141.0,35.147.0,26.128.0,43.160.0"}
P.entries["quest:86667"] = {n="Snowbound",s="À Loch Modan, Grenhild étudie les élémentaires locaux tandis que Norric Lochthane demande de la neige du Passage de la porte Sud. Sa requête cache un espoir plus profond : le chaman vieillissant veut revoir son ancienne élève.",h="À Loch Modan, Grenhild étudie les élémentaires locaux tandis que Norric Lochthane demande de la neige du...",kw={"grenhild","bocal de neige","loch modan","élémentaire mineur","norric lochthane","travaux chamaniques","snowbound","passage de la porte sud","le loch"},ang={["class:Shaman"]="Le recours de Norric Lochthane aux messagers élémentaires mineurs et aux réactifs gelés reflète les traditions chamaniques et les études élémentaires de Khaz Modan.",["race:Dwarf"]="L’échange entre Norric Lochthane et Grenhild donne un aperçu du mentorat nain et des études élémentaires autour des sommets et des rives de Loch Modan."},sec={{t="Une demande inhabituelle",b="Grenhild étudie les élémentaires locaux de Loch Modan lorsqu’un élémentaire mineur lui apporte un message de Norric Lochthane, son ancien mentor. Il a besoin de neige fraîche, non fondue, pour ses travaux chamaniques. Grenhild demande à un voyageur d’aller la chercher afin de poursuivre ses études. La neige vient du Passage de la porte Sud, où des courants d’air froid préservent les congères toute l’année. Il faut la sceller dans un bocal en céramique spécialement conçu pour la protéger de la chaleur de la vallée."},{t="Maître et élève",b="Norric Lochthane vit dans un cottage tranquille sur la côte nord-ouest du Loch, à l’écart des colonies. À l’arrivée du bocal, il se réjouit d’avoir le réactif froid nécessaire à ses recherches mystiques. Pourtant, il regrette que Grenhild ne soit pas venue en personne. Sa demande ne portait pas seulement sur un ingrédient magique : le chaman vieillissant espérait renouer avec son ancienne élève, qui suit désormais sa propre voie."}},faq={{q="Qui est Norric Lochthane ?",a="Norric Lochthane est un chaman expérimenté qui vit dans un cottage sur la côte nord-ouest du Loch, au Loch Modan. Il a autrefois enseigné à Grenhild et poursuit encore en privé ses travaux chamaniques. Il peut faire appel à des élémentaires mineurs pour porter des messages à travers les contrées sauvages.",al={"histoire de norric lochthane","qui est norric","norric à loch modan"}},{q="Qui est Grenhild ?",a="Grenhild est une chercheuse en élémentaires installée à Loch Modan. Elle a étudié la magie auprès de Norric Lochthane et respecte son art, mais consacre ses recherches de terrain aux élémentaires locaux et a peu de temps pour voyager.",al={"qui est grenhild","grenhild à loch modan","mentor de grenhild"}},{q="Pourquoi Norric a-t-il besoin d’un bocal de neige ?",a="Norric a besoin de neige pour ses travaux chamaniques et ses recherches mystiques. Il espérait aussi que Grenhild profiterait de cette demande pour lui rendre visite en personne.",al={"pourquoi norric veut de la neige","neige pour les travaux chamaniques","utilité du bocal de neige"}},{q="Où trouver la neige de cette quête ?",a="Ramassez de la neige près de l’entrée du tunnel au Passage de la porte Sud, dans les hauteurs entre Dun Morogh et Loch Modan. Le froid de l’altitude y maintient la neige toute l’année. Les voyageurs peuvent donc la conserver dans un bocal en céramique isolant.",al={"où trouver de la neige","emplacement de la neige au passage de la porte sud","comment obtenir le bocal de neige"}},{q="Pourquoi Grenhild ne pouvait-elle pas livrer la neige elle-même ?",a="Grenhild est occupée à observer et étudier les élémentaires locaux de Loch Modan. Ses recherches de terrain la retiennent à son poste et l’empêchent de faire le trajet jusqu’au Passage de la porte Sud, puis jusqu’à la demeure de Norric au bord du lac.",al={"pourquoi grenhild ne peut pas y aller","pourquoi grenhild a besoin d’aide","grenhild occupée"}},{q="Comment Norric a-t-il fait parvenir sa demande à Grenhild ?",a="Norric a invoqué un élémentaire mineur et l’a envoyé porter son message à Grenhild. Ce messager inhabituel témoigne de sa maîtrise des arts élémentaires et de la pratique chamanique.",al={"messager de norric","messager élémentaire","comment norric a contacté grenhild"}}},fp="9,202,18.448.0,17.379.0,24.260.0,16.202.0,35.152.0,42.224.0,47.181.0,44.157.0"}
P.entries["quest:867"] = {n="Les harpies pillardes",s="Dans le nord-ouest des Tarides, les harpies Aile-sorcière s'en prennent aux caravanes de ravitaillement. À la Croisée, Darsok Vivedague vous envoie traquer leurs pillardes et leurs plumavides ; leurs serres prouveront chaque élimination.",h="Dans le nord-ouest des Tarides, les harpies Aile-sorcière s'en prennent aux caravanes de ravitaillement.",kw={"tarides","la croisée","darsok","harpie","plumavide","vivedague","serres","aile-sorcière"},ang={["class:Rogue"]="En tant que voleur, vous comprenez l'intérêt de la méthode de Darsok Vivedague : repérer la cible, étudier ses rangs et éliminer son commandement étape par étape.",["faction:Horde"]="Sécuriser les routes de l'intérieur des Tarides facilite le ravitaillement des avant-postes récemment établis et les maintient unis sous les étendards d'Orgrimmar."},sec={{t="Menace venue du ciel",b="Les harpies Aile-sorcière rendent le nord-ouest des Tarides dangereux pour toutes les caravanes. Depuis les pitons rocheux, elles fondent sur les convois marchands et les chariots de ravitaillement. Elles tuent les bêtes de somme et s'emparent des marchandises destinées aux avant-postes orcs."},{t="Le plan de Darsok",b="Darsok Vivedague, un voleur orc, observe depuis des jours les habitudes et les rangs de la volée. Il pense qu'une attaque mal préparée contre leurs perchoirs montagneux les disperserait. Il compte donc briser les Aile-sorcière en remontant les rangs, en commençant par les pillardes avant de s'en prendre à leurs commandantes."}},faq={{q="Pourquoi la Horde s'en prend-elle aux harpies Aile-sorcière ?",a="Les harpies Aile-sorcière nichent dans les pitons du nord-ouest des Tarides et attaquent souvent les caravanes de ravitaillement de la Horde qui empruntent les routes principales.",al={"pourquoi tuer les harpies","problème des aile-sorcière","pourquoi attaquer les harpies"}},{q="Qui est Darsok Vivedague ?",a="Darsok Vivedague est un éclaireur et voleur orc en poste à la Croisée. Il surveille les menaces locales et a étudié la hiérarchie de la volée de harpies pour préparer une attaque méthodique.",al={"darsok","histoire de darsok vivedague","qui est darsok"}},{q="Pourquoi Darsok veut-il des serres d'Aile-sorcière ?",a="Darsok veut des serres arrachées comme preuve de chaque élimination. Il les collectionne comme trophées et pour vérifier que les rangs inférieurs de la volée diminuent.",al={"pourquoi les serres","utilité des serres de harpie"}},{q="Où se trouvent ces harpies ?",a="Les harpies nichent dans des falaises et des ravins envahis d'épines, à l'extrême nord-ouest des Tarides, au nord de la route des Serres-Rocheuses.",al={"où trouver les harpies","emplacement des aile-sorcière","emplacement des harpies pillardes"}},{q="Que se passe-t-il après avoir éliminé ces pillardes ?",a="Une fois les pillardes et les plumavides décimés, Darsok vous oriente vers les rangs supérieurs de la volée, notamment ses lieutenantes et sa matrone.",al={"quête suivante","après les harpies pillardes","what comes next"}},{q="Les harpies travaillent-elles pour quelqu'un d'autre ?",a="Les harpies Aile-sorcière sont des charognardes sauvages et territoriales qui obéissent à la matrone de leur perchoir, Serena Bloodfeather, et non à une faction extérieure.",al={"qui dirige les harpies","allégeance des harpies","chefs des aile-sorcière"}}},fx={["8e2506f2"]={q="Qui sont les harpies Witchwing ?",a="Les Witchwing sont une volée d'humanoïdes aviaires féroces nichant dans les crêtes et les canyons du nord-ouest des Tarides. Connues pour leur sauvagerie hurlante, elles descendent des falaises pour tendre des embuscades aux voyageurs et piller les caravanes de la Horde traversant les plaines arides. Darsok a identifié leurs pillards de base, y compris les Witchwing Roguefeathers, comme étant le fondement de la puissance de pillage de leur volée.",al={"cible des harpies witchwing","qui sont les harpies","witchwing roguefeathers"}}},fp="13,196,17.209.0,13.284.0,49.123.0,26.178.0,38.147.0,32.118.0,41.137.1,40.141.0"}
P.entries["quest:8670"] = {n="L'Ancienne Totem-Runique",s="À Tranchecolline, les voyageurs peuvent rendre hommage à L'Ancienne Totem-Runique pendant la fête lunaire. Cet Esprit ancestral attend sous un rayon de lumière céleste et offre des bénédictions et des jetons de la fête à ceux qui se souviennent du passé.",h="À Tranchecolline, les voyageurs peuvent rendre hommage à L'Ancienne Totem-Runique pendant la fête lunaire.",kw={"durotar","ancienne darkhorn","elder high mountain","ancienne totem-runique","fête lunaire","tranchecolline","totem-runique"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous devez franchir les lignes ennemies et pénétrer en Durotar pour rendre hommage à l'Ancienne Totem-runique, au risque de provoquer la colère des gardes orcs de Tranchecolline.",["faction:Horde"]="En tant que membre de la Horde, vous pouvez rendre hommage à l'Ancienne Totem-runique à Tranchecolline. C'est l'une des ancêtres les plus faciles et les plus sûres à visiter au début de vos voyages.",["race:Tauren"]="En tant que tauren, rencontrer un esprit de la famille Totem-runique au-delà de Mulgore vous rappelle le profond héritage spirituel de votre peuple à travers Kalimdor."},sec={{t="Un esprit à Tranchecolline",b="Pendant la fête lunaire, d'anciens esprits apparaissent partout en Azeroth pour communier avec les vivants. L'Ancienne Totem-runique attend juste après l'entrée sud de Tranchecolline. La lumière des étoiles tombe sur elle tandis qu'elle veille sur la colonie orque. Les voyageurs peuvent s'arrêter pour honorer la sagesse de leurs prédécesseurs."},{t="Des conseils à travers le continent",b="Rendez hommage à l'Ancienne Totem-runique et elle vous donnera un jeton de la fête porte-bonheur. Elle vous indique aussi où trouver d'autres esprits. Ses indications vous mènent auprès de l'Ancienne Darkhorn et d'Elder High Mountain, ailleurs sur le continent."}},faq={{q="Où se trouve l'Ancienne Totem-runique ?",a="L'Ancienne Totem-runique attend à Tranchecolline, en Durotar, juste à droite après l'entrée sud.",al={"emplacement de l'ancienne totem-runique","où se trouve l'ancienne totem-runique","trouver l'ancienne totem-runique"}},{q="Pourquoi un rayon de lumière l'éclaire-t-il ?",a="Un rayon de lumière céleste signale que l'Ancienne Totem-runique est une ancienne honorée, comme les Esprits ancestraux qui apparaissent pendant la fête lunaire.",al={"rayon de lumière sur l'ancienne","pourquoi totem-runique brille","rayon de lumière de l'ancienne"}},{q="Que recevez-vous en rendant hommage à l'Ancienne Totem-runique ?",a="Vous recevez un jeton de la fête en rendant hommage à l'Ancienne Totem-runique, qui vous indique aussi où trouver des esprits comme l'Ancienne Darkhorn et Elder High Mountain.",al={"récompense de totem-runique","que donne totem-runique","quête de l'ancienne totem-runique"}},{q="Les joueurs de l'Alliance peuvent-ils rendre visite à l'Ancienne Totem-runique ?",a="L'Ancienne Totem-runique accepte l'hommage de tous les mortels, quelle que soit leur allégeance, mais Tranchecolline est un avant-poste de la Horde bien gardé, périlleux à atteindre pour les voyageurs de l'Alliance.",al={"alliance et ancienne totem-runique","l'alliance peut-elle parler à totem-runique"}},{q="De quelles anciennes Totem-runique parle-t-elle ?",a="L'Ancienne Totem-runique vous indique où trouver l'Ancienne Darkhorn et Elder High Mountain.",al={"indications de totem-runique","qui totem-runique vous demande de trouver"}},{q="L'Ancienne Totem-runique est-elle une tauren vivante ou un fantôme ?",a="L'Ancienne Totem-runique est un Esprit ancestral qui apparaît pendant la fête lunaire pour bénir ceux dont l'esprit brûle de vie.",al={"totem-runique est-elle morte","totem-runique est-elle un fantôme"}}},fp="19,215,22.289.0,25.220.0,33.116.0,44.140.0,49.142.0,43.172.0,36.75.0,46.121.0"}
P.entries["quest:8673"] = {n="L'Ancien Sabot-de-Sang",s="Pendant la fête lunaire, les voyageurs honorent l’Ancien Sabot-de-Sang près du pont au nord de Sabot-de-Sang. L’esprit ancestral leur offre une pièce des ancêtres.",h="Pendant la fête lunaire, les voyageurs honorent l’Ancien Sabot-de-Sang près du pont au nord de Sabot-de-Sang.",kw={"ancêtre","sabot-de-sang","pièce des ancêtres","ancien sabot-de-sang","fête lunaire","mulgore"},ang={["class:Druid"]="En tant que druide, vous honorez les esprits de la fête lunaire et communiez avec les anciens. Cela renforce votre lien avec la terre et les étoiles.",["class:Shaman"]="En tant que chaman, vous communiez avec les ancêtres manifestés comme l’Ancien Sabot-de-sang, reliant les vivants aux esprits ancestraux.",["faction:Alliance"]="En tant que voyageur de l’Alliance, rejoindre l’Ancien Sabot-de-sang signifie traverser les plaines hostiles de la Horde jusqu’au cœur de Mulgore.",["race:Tauren"]="En tant que tauren, saluer l’Ancien Sabot-de-sang sur votre terre natale honore l’héritage de votre tribu et le rôle qu’elle a joué pour guider votre peuple vers un havre de paix en Mulgore."},sec={{t="La visite des ancêtres",b="Pendant la fête lunaire, les esprits des héros et des anciens d’autrefois reviennent en Azeroth. L’Ancien Sabot-de-sang apparaît près du pont au nord de Sabot-de-Sang. Les voyageurs honorent les sacrifices du passé en s’approchant de lui. Il leur adresse des paroles d’encouragement et leur offre une pièce des ancêtres."},{t="L’héritage des Sabot-de-Sang",b="Sur les terres ancestrales de Mulgore, l’Ancien Sabot-de-sang relie les tribus taurens vivantes au souvenir de leurs ancêtres. Honorer les morts est au cœur de la vie spirituelle tauren. Cela maintient l’harmonie entre la Terre-Mère, les ancêtres et ceux qui parcourent les plaines."}},faq={{q="Où trouver l’Ancien Sabot-de-sang ?",a="L’Ancien Sabot-de-sang apparaît près du pont, juste à l’extérieur de Sabot-de-Sang, en Mulgore, sous un rayon de lumière céleste.",al={"emplacement de l’ancien sabot-de-sang","où se trouve l’ancien sabot-de-sang","lieu de l’ancien sabot-de-sang"}},{q="Pourquoi chercher l’Ancien Sabot-de-sang ?",a="Pendant la fête lunaire, les voyageurs cherchent l’Ancien Sabot-de-sang pour honorer les ancêtres. En retour, l’esprit leur offre une pièce des ancêtres et des conseils sur les esprits voisins, comme Elder Proudhorn.",al={"pourquoi parler à l’ancien sabot-de-sang","rôle de l’ancien sabot-de-sang","que donne l’ancien sabot-de-sang"}},{q="Pourquoi un rayon de lumière l’éclaire-t-il ?",a="Le rayon de lumière désigne l’Ancien Sabot-de-sang comme un esprit ancestral manifesté pendant la fête lunaire. Il symbolise un lien sacré avec les cieux et les esprits du passé.",al={"pourquoi l’ancien sabot-de-sang brille","lumière sur l’ancien sabot-de-sang"}},{q="Les personnages de l’Alliance peuvent-ils rendre hommage à l’Ancien Sabot-de-sang ?",a="Les ancêtres de la fête lunaire honorent tous les mortels qui leur témoignent du respect, quelle que soit leur faction. Les voyageurs de l’Alliance doivent avancer avec prudence, car l’Ancien Sabot-de-sang se trouve près de la frontière du territoire de la Horde.",al={"l’alliance peut-elle faire cette quête","l’ancien sabot-de-sang est-il réservé à la horde"}},{q="Qui est Elder Proudhorn, dont parle cet ancien ?",a="Elder Proudhorn est un autre esprit ancestral honoré pendant la fête, à Pitons-du-Tonnerre. L’Ancien Sabot-de-sang peut guider les voyageurs jusqu’à lui.",al={"ancien wheathoof","qui est wheathoof"}},{q="Que représentent les pièces des ancêtres ?",a="Les pièces des ancêtres sont des marques de faveur offertes par les esprits honorés d’Azeroth. Elles montrent qu’un voyageur a honoré le passé, et les participants à la fête les échangent contre des tenues festives, des plans et des marchandises de célébration.",al={"que sont les pièces des ancêtres","jetons de la fête lunaire"}}},fp="19,159,26.277.0,20.250.0,33.117.0,51.191.0,49.170.0,54.191.0,48.134.0,40.209.0"}
P.entries["quest:86746"] = {n="The Legashi Threat",s="Ekkal vous demande de défendre les furbolgs Blackmaw contre les satyres Legashi, aux Ruines d’Eldarath. Les satyres ont corrompu des membres de la tribu et poussé les survivants à se réfugier dans des camps de fortune.",h="Ekkal vous demande de défendre les furbolgs Blackmaw contre les satyres Legashi, aux Ruines d’Eldarath.",kw={"blackmaw","ekkal","furbolg","legashi","ruines d'eldarath","satyre","timbermaw"},sec={{t="Une tribu menacée",b="Ekkal sollicite votre aide aux Ruines d’Eldarath, où les satyres Legashi ont envahi le repaire Blackmaw. Leur corruption s’est répandue parmi les furbolgs et a séparé la tribu de ses alliés Timbermaw. Les survivants se rassemblent maintenant dans des camps de fortune, tandis que la corruption gagne du terrain. Ekkal espère que chaque Legashi abattu épargnera la vie d’un furbolg."}},faq={{q="Qui demande de l’aide ?",a="Ekkal vous demande d’aider à défendre les furbolgs Blackmaw contre les satyres Legashi.",al={"qui est ekkal","aide d’ekkal","donneur de quête furbolg"}},{q="Que font les Legashi aux Blackmaw ?",a="Les Legashi ont envahi le repaire Blackmaw, corrompu de nombreux furbolgs et séparé la tribu de ses alliés Timbermaw.",al={"menace des legashi","que font les satyres","blackmaw attaqués"}},{q="Où se cachent les Legashi ?",a="Ekkal dit que les Legashi se cachent parmi les ruines, au nord-est du repaire Blackmaw.",al={"emplacement des legashi","où sont les satyres","ruines d’eldarath"}},{q="Quels Legashi Ekkal veut-il que vous vainquiez ?",a="Ekkal vous demande de vaincre Legashi Satyr, Legashi Rogues et Legashi Hellcallers.",al={"types de legashi","quels satyres tuer","ennemis legashi"}},{q="Pourquoi Ekkal demande-t-il de l’aide ?",a="Les Legashi menacent la tribu Blackmaw, déjà vulnérable, et Ekkal pense que chaque ennemi abattu pourrait sauver la vie d’un furbolg.",al={"pourquoi aider ekkal","furbolgs en détresse","pourquoi tuer les legashi"}}},fp="18,179,20.344.0,23.74.0,43.117.0,26.74.0,44.80.0,28.118.0"}
P.entries["quest:86747"] = {n="Legashi Horns",s="Un furbolg d’Ursolan vous demande de rapporter les cornes de satyres Legashi tués. Chaque lot témoigne de votre service auprès des Blackmaw.",h="Un furbolg d’Ursolan vous demande de rapporter les cornes de satyres Legashi tués.",kw={"blackmaw","furbolg","legashi","cornes des legashi","satyre","ursolan"},sec={{t="Parmi les Blackmaw",b="Les autres furbolgs des Blackmaw sont plus difficiles à convaincre, vos efforts contre les Legashi se poursuivent donc. Les satyres Legashi tués portent les cornes que vous devez rapporter. Chaque lot témoigne de votre service auprès de la tribu, et les furbolgs d’Ursolan entendront parler de vos exploits."}},faq={{q="Qui demande les cornes des Legashi ?",a="Un furbolg des Blackmaw vous demande de rapporter les cornes de satyres Legashi tués.",al={"qui demande les cornes","à qui sont les cornes"}},{q="Pourquoi veulent-ils ces cornes ?",a="Chaque lot témoigne de votre service auprès des Blackmaw et aide à convaincre les autres membres de la tribu.",al={"pourquoi les cornes","à quoi servent les cornes"}},{q="Qui sont les Legashi ?",a="Les Legashi sont des satyres, et les Blackmaw vous demandent de rapporter les cornes de ceux que vous tuez.",al={"satyres legashi","qui sont les legashi"}},{q="Que s’est-il passé avant ?",a="Vous avez déjà fait vos preuves auprès du furbolg qui parle au nom des Blackmaw, mais le reste de la tribu est plus difficile à convaincre.",al={"que s’est-il passé avant","confiance des blackmaw"}},{q="Où les furbolgs entendront-ils parler de mes exploits ?",a="Le furbolg qui parle au nom des Blackmaw affirme que vos exploits se répandront parmi les furbolgs d’Ursolan.",al={"où la nouvelle se répand","furbolgs d’ursolan"}}},fp="13,118,18.269.0,28.75.0,27.97.0,21.83.0,26.125.0,40.105.0"}
